(137112, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(137111, 'esMX', '|TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(137103, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_MOLTENBLOOD.BLP:20|t %s comienza a lanzar |cFFFF0000|Hspell:244057|h[Inflamación de corrupción]|h|r.', '|TInterface\\Icons\\SPELL_FIRE_MOLTENBLOOD.BLP:20|t %s comienza a lanzar |cFFFF0000|Hspell:244057|h[Inflamación de corrupción]|h|r.', 25549),
(137102, 'esMX', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t %s comienza a lanzar |cFFFF0000|Hspell:244056|h[Succión de corrupción]|h|r.', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t %s comienza a lanzar |cFFFF0000|Hspell:244056|h[Succión de corrupción]|h|r.', 25549),
(137081, 'esMX', 'Hemos adquirido muchos artículos y curiosidades en el transcurso de esta guerra.', '', 25549),
(137044, 'esMX', '¡Está completo una vez más!', '', 25549),
(137043, 'esMX', 'Ah, sí, todo marcha a la perfección.', '', 25549),
(137042, 'esMX', 'No he tenido que crear una cosa así en milenios. Ten un poco de paciencia.', '', 25549),
(136971, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 25549),
(136970, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(136933, 'esMX', '¡La Bendición del emperador aparece sobre la arena!', '', 25549),
(136932, 'esMX', '', '¡El Paraxis ha llegado! ¡Cúbranse bajo los escudos!', 25549),
(136930, 'esMX', '', '¡El Paraxis regresará pronto! ¡Ejército de la Luz, preparen sus escudos!', 25549),
(136926, 'esMX', '¡El equipo púrpura obtiene la Bendición del emperador!', '', 25549),
(136924, 'esMX', 'Quiero ir al Trono del Triunvirato (Calabozo).', 'Quiero ir al Trono del Triunvirato (Calabozo).', 25549),
(136898, 'esMX', '|cFFFF0000|Hspell:252508|h¡[El Paraxis]|h|r ha llegado! ¡Cúbrete!', '', 25549),
(136897, 'esMX', '¡|cFFFF0000|Hspell:252508|h[El Paraxis]|h|r llegará pronto!', '', 25549),
(136891, 'esMX', 'Iniciar el ataque sobre Antorus.', 'Iniciar el ataque sobre Antorus.', 25549),
(136890, 'esMX', '<El engranaje bélico zumba con energía, listo para participar de la batalla.>', '', 25549),
(136875, 'esMX', '', 'Lord Illidan se la ha llevado. Su plan está en marcha, $GDestripador:Destripadora;.', 25549),
(136873, 'esMX', 'Kor''vas, ¿en qué estado se encuentra la Piedra angular sargerita?', 'Kor''vas, ¿en qué estado se encuentra la Piedra angular sargerita?', 25549),
(136847, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|t ¡Esta área será el objetivo de |cFFF00000|Hspell:250249|h[Desintegración]|h|r!', '', 25549),
(136839, 'esMX', 'Argus jamás le pertenecerá a la Legión mientras estemos de pie.', '', 25549),
(136834, 'esMX', '', 'No debemos olvidar todos los sacrificios que se hicieron para potenciar el Crisol de luz abisal.', 25549),
(136833, 'esMX', '', 'El poder del Crisol de luz abisal está a tu disposición, $n.', 25549),
(136826, 'esMX', '', 'Debemos continuar luchando hasta que la Legión desaparezca.', 25549),
(136817, 'esMX', '¡Un Enfurecimiento vil posee al Arrastrapiés de pantano y logra liberarse de los corruptores!', '¡Un Enfurecimiento vil posee al Arrastrapiés de pantano y logra liberarse de los corruptores!', 25549),
(136794, 'esMX', 'Lo que pides es obvio.$b$bUn ataque directo sobre Antorus sería imprudente. Las fuerzas de la Legión nos superan ampliamente, y reemplazan a sus soldados a una velocidad sobrenatural. Algunos de estos brutos incluso son capaces de demorarme a mí... un poco.$b$bNecesitaremos otro plan para atravesar su fortaleza. Mientras tanto, tenemos un mar de demonios por asesinar.$b$bRegresa con tu Alto exarca para que elabore una estrategia. Tengo un enemigo que destruir.', '', 25549),
(136793, 'esMX', 'Acabaré con la Legión en este lugar maldito.', '', 25549),
(136792, 'esMX', 'Mis gujas están sedientas de sangre de demonio.', '', 25549),
(136791, 'esMX', 'Aquí concentran todas sus fuerzas. Realmente son una Legión.$b$bPerfecto.', '', 25549),
(136790, 'esMX', 'Por fin hemos llegado. Ha pasado tanto tiempo...', '', 25549),
(136787, 'esMX', '', 'La perspectiva es lúgubre.$b$bMontar un ataque directo desde esta ubicación nos costaría muchas vidas. De hecho, puede que esos cañones en la cima de la muralla tengan la potencia necesaria para derribar el Vindicaar.$b$bSugiero que uses esta posición para guiar ataques de guerrilla. Asesina a los miembros clave entre sus líderes y siembra el caos en sus filas.$b$bSé que no es lo que tú y Turalyon querían oír, pero un cazador paciente debe saber cuándo atacar.', 25549),
(136786, 'esMX', 'Turalyon quiere saber cuál es la situación aquí.', 'Turalyon quiere saber cuál es la situación aquí.', 25549),
(136785, 'esMX', '¿Qué información has logrado obtener, Alleria?', '¿Qué información has logrado obtener, Alleria?', 25549),
(136784, 'esMX', '', 'Realmente son infinitos. Debemos encontrar la forma de exterminarlos de una vez por todas.', 25549),
(136783, 'esMX', '', '$GBienvenido:Bienvenida; al corazón de Argus.', 25549),
(136782, 'esMX', '', 'Incluso desde aquí puedo oír su llamado. Su voracidad...', 25549),
(136781, 'esMX', '', 'Aquí hay muchas presas que cazar.', 25549),
(136749, 'esMX', '¡El equipo dorado obtiene la Bendición del emperador!', '', 25549),
(136748, 'esMX', '¡El equipo púrpura obtiene la Bendición del emperador!', '', 25549),
(136743, 'esMX', '', 'Ya es hora.', 25549),
(136737, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(136736, 'esMX', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(136735, 'esMX', '|TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(136734, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(136733, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(136716, 'esMX', 'Gracias, $gcampeón:campeona;... Estaba seguro de que era mi fin.', '', 25549),
(136715, 'esMX', '¡Por favor, salva a los demás!', '', 25549),
(136714, 'esMX', 'Pensé que no la contaba... ¡Muchas gracias!', '', 25549),
(136701, 'esMX', 'Hemos logrado nuestra misión. Regresemos al Vindicaar. Queda mucho trabajo por hacer.', '', 25549),
(136682, 'esMX', 'No estás... $Gpreparado:preparada;.', '', 25549),
(136661, 'esMX', '|TInterface\\Icons\\ABILITY_MAGE_DEEPFREEZE.BLP:20|t¡Busca un blandón! ¡Se acerca una |cFFFF0000|Hspell:251709|h[Congelación apresurada]|h|r!', '', 25549),
(136656, 'esMX', 'No está mal, pero es una verdadera lástima dejar los granos remojándose en el agua y decir que eso es una bebida. Tengo que llevar una muestra de este café al famoso clan Cebatruenos para que la prueben. Imagina una buena cerveza añejada con un poco de estos granos...', '', 25549),
(136612, 'esMX', 'PH Activate Choice UI', 'PH Activate Choice UI', 25549),
(136606, 'esMX', 'Ya he oído esta historia... <Omitir la gesta y comenzar tu viaje en la Costa Quebrada.>', 'Ya he oído esta historia... <Omitir la gesta y comenzar tu viaje en la Costa Quebrada.>', 25549),
(136598, 'esMX', '|TINTERFACE\\ICONS\\Inv_Elemental_Primal_Shadow.blp:20|t [Coloca la esencia de Sombra en el Crisol de luz abisal].', '|TINTERFACE\\ICONS\\Inv_Elemental_Primal_Shadow.blp:20|t [Coloca la esencia de Sombra en el Crisol de luz abisal].', 25549),
(136597, 'esMX', '|TINTERFACE\\ICONS\\Item_HolySpark.blp:20|t [Coloca la esencia de Luz en el Crisol de luz abisal].', '|TINTERFACE\\ICONS\\Item_HolySpark.blp:20|t [Coloca la esencia de Luz en el Crisol de luz abisal].', 25549),
(136596, 'esMX', 'Sombra.', 'Sombra.', 25549),
(136595, 'esMX', 'Luz.', 'Luz.', 25549),
(136594, 'esMX', 'La voz está sola... Es débil... ¡pero es tan hermosa!', '', 25549),
(136593, 'esMX', 'Lucha para superar el dolor... para dejarnos ver...', '', 25549),
(136586, 'esMX', '', 'Nuestro trabajo casi está terminado. ¡Pronto todo Argus caerá en la oscuridad!', 25549),
(136585, 'esMX', 'Haz lo que quieras con el ser de carne y su $Galiado:aliada;. Ellos no son importantes.', '', 25549),
(136584, 'esMX', 'No le daré al caminante intersticial la satisfacción de frustrar nuestros esfuerzos. Captúralo, cueste lo que cueste.', '', 25549),
(136583, 'esMX', '', 'Hay mucho material para cosechar aquí. ¡No desperdiciemos nada!', 25549),
(136582, 'esMX', 'Es una pena que no matara a la elfa y a su $Galiado:aliada; también.', '', 25549),
(136580, 'esMX', 'Tengo entendido que el virrey finalmente se encargó de ese sacerdote entrometido.', '', 25549),
(136544, 'esMX', 'Entiendo.', 'Entiendo.', 25549),
(136543, 'esMX', '', 'Mientras la naaru yacía agonizante, la esencia de L''ura me llamó. Un ser nacido en la Luz se había entregado a las Sombras.\n\nFue una sensación familiar.\n\nLa transformación que has visto está bajo mi control, y puedo usarla cuando sea necesario. Soy la misma persona de antes... pero también soy algo más.\n\nEl uso de este poder... perturba a algunos. Pero las sombras son una fuerza para utilizar, no para temer.\n\nComo con cualquier arma nueva, debes mantener el control siempre que la usas.', 25549),
(136542, 'esMX', '¿Qué te pasó en el Trono del Triunvirato?', '¿Qué te pasó en el Trono del Triunvirato?', 25549),
(136541, 'esMX', '', 'Nunca me vencerán.', 25549),
(136540, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFLAMERING.BLP:20|t ¡El Quiebraluz antaen está lanzando |cFFFF0000|Hspell:250880|h[Bombardeo descargavil]|h|r! ¡Permanece en el Cobijo de la Luz!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFLAMERING.BLP:20|t ¡El Quiebraluz antaen está lanzando |cFFFF0000|Hspell:250880|h[Bombardeo descargavil]|h|r! ¡Permanece en el Cobijo de la Luz!', 25549),
(136506, 'esMX', 'Corbyn no pudo encontrar nada brillante en %s.', 'Corbyn no pudo encontrar nada brillante en %s.', 25549),
(136505, 'esMX', '¡Corbyn le ha robado una moneda de cobre a %s!', '¡Corbyn le ha robado una moneda de cobre a %s!', 25549),
(136504, 'esMX', 'La mascota Corbyn de %s hurga en tus bolsas.', 'La mascota Corbyn de %s hurga en tus bolsas.', 25549),
(136503, 'esMX', 'La mascota Corbyn de %s da vueltas alrededor de tu cabeza.', 'La mascota Corbyn de %s da vueltas alrededor de tu cabeza.', 25549),
(136502, 'esMX', 'La mascota Corbyn de %s trata de picarte los ojos.', 'La mascota Corbyn de %s trata de picarte los ojos.', 25549),
(136501, 'esMX', 'La mascota Corbyn de %s grazna con fuerza en tus oídos.', 'La mascota Corbyn de %s grazna con fuerza en tus oídos.', 25549),
(136500, 'esMX', 'La mascota Corbyn de %s busca baratijas brillantes en tu cabello.', 'La mascota Corbyn de %s busca baratijas brillantes en tu cabello.', 25549),
(136499, 'esMX', 'La mascota Corbyn de %s te muerde las orejas en busca de baratijas brillantes.', 'La mascota Corbyn de %s te muerde las orejas en busca de baratijas brillantes.', 25549),
(136496, 'esMX', '¡$n prepara un festín de pescado!', '¡$n prepara un festín de pescado!', 25549),
(136433, 'esMX', '¡Gracias, $ghéroe:heroína;!', '¡Gracias, $ghéroe:heroína;!', 25549),
(136416, 'esMX', 'Elige el poder del Vindicaar que quieres usar en Argus. Solo puedes tener un poder activo a la vez.', '', 25549),
(136412, 'esMX', 'Necesito reparaciones, Durael.', 'Necesito reparaciones, Durael.', 25549),
(136392, 'esMX', 'Sí, bueno, me atrapaste. Pero es muy cómodo.$B$BAhora, si me disculpas, tengo mucho que leer.', '', 25549),
(136391, 'esMX', 'Pero estás sentado.', 'Pero estás sentado.', 25549),
(136390, 'esMX', '', 'Estoy bien, $n. Gracias por preguntar.$B$BAntes de que te aventures al campo de batalla, quiero que sepas que mis servicios siempre están disponibles si necesitas un lugar donde descansar.$B$BCuídate.', 25549),
(136389, 'esMX', 'Qué bueno verte, Ishanah. ¿Cómo estás?', 'Qué bueno verte, Ishanah. ¿Cómo estás?', 25549),
(136344, 'esMX', '¡Renace en la energía vil!', '', 25549),
(136343, 'esMX', '¿Crees que eres libre? Todos servimos a un maestro.', '', 25549),
(136342, 'esMX', 'De vil... a vil.', '', 25549),
(136339, 'esMX', 'Debo elegir uno de los innumerables medios a mi disposición para matarte.', '', 25549),
(136338, 'esMX', '¿Tienes tantas ganas de morir?', '', 25549),
(136337, 'esMX', 'Tú serás $Gel primero:la primera;.', '', 25549),
(136336, 'esMX', '', 'Puedo volverte inmortal. ¡Pero primero tienes que morir!', 25549),
(136335, 'esMX', '', 'Qué suerte. Mis mascotas estaban poniéndose hambrientas.', 25549),
(136334, 'esMX', '', '¡Oh, mira! Otra mascota ha venido a jugar.', 25549),
(136333, 'esMX', 'No te preocupes por mí, encontraré un camino... Tarde o temprano.', '', 25549),
(136305, 'esMX', 'Estoy usando zapatos.', 'Estoy usando zapatos.', 25549),
(136304, 'esMX', 'El piso frío bajo los pies me ayuda a mantener la concentración.', '', 25549),
(136303, 'esMX', 'Qué interesante... ¿Y por qué no estás usando zapatos?', 'Qué interesante... ¿Y por qué no estás usando zapatos?', 25549),
(136302, 'esMX', '¿Qué es eso detrás de ti?', '¿Qué es eso detrás de ti?', 25549),
(136301, 'esMX', '¿Qué hace ese portal aquí?', '¿Qué hace ese portal aquí?', 25549),
(136300, 'esMX', 'Este lugar está lleno de magia y misterio.', '', 25549),
(136294, 'esMX', 'Escena de cliente: El Vindicaar se vuelve dorado', 'Escena de cliente: El Vindicaar se vuelve dorado', 25549),
(136247, 'esMX', '', 'Saludos.', 25549),
(136246, 'esMX', '', 'Hola, $n. Todos a bordo han estado bastante activos. ¡Parece que tú también has estado $Gocupado:ocupada;! Si alguna vez necesitas dónde descansar, estoy a tu servicio.', 25549),
(136245, 'esMX', '¿Eso? Eso es solo un portal que invoqué para tener un salvoconducto para Dalaran.$B$B¡Nunca se sabe cuándo vas a necesitar refuerzos!', '', 25549),
(136244, 'esMX', '', 'A mi espalda se encuentra el Crisol de luz abisal. Es un antiguo vestigio de este mundo que supo ser una fuente de magias considerables.$B$BSi bien muchos creen que su posible poder es un don, para potenciarlo se necesitaría un gran sacrificio... Y un delicado equilibrio de Luz y Sombra.', 25549),
(136216, 'esMX', '', '', 25549),
(136209, 'esMX', 'La nave de la Legión te ha visto. Escapa para que no te ataquen.', '', 25549),
(136208, 'esMX', 'Los intrusos son más resistentes de lo que esperábamos, almirante.', '', 25549),
(136186, 'esMX', '', 'Acéptalo... esto no cambia... nada.', 25549),
(136185, 'esMX', '', 'El olvido... llama.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(136184, 'esMX', '', 'Regreso al Vacío.', 25549),
(136183, 'esMX', '', 'Voy con ustedes, amos oscuros.', 25549),
(136182, 'esMX', '', 'Se hará su voluntad.', 25549),
(136181, 'esMX', '', 'Sirvo al fin de todas las cosas.', 25549),
(136180, 'esMX', '', 'Por fin.', 25549),
(136175, 'esMX', 'Con la erupción de la máquina, algo se agita bajo la superficie.', '', 25549),
(136174, 'esMX', '', 'La llave está forjada de nuevo. Tómala y asegura la armería.', 25549),
(136173, 'esMX', '', 'Aquí vamos.', 25549),
(136172, 'esMX', 'Escena de cliente: Alleria se asoma al Vacío', 'Escena de cliente: Alleria se asoma al Vacío', 25549),
(136171, 'esMX', '', 'Xakaar, ¡¿qué significa esta demora?!', 25549),
(136158, 'esMX', '¡Nos atacan de nuevo! ¡Tráeme la llama!', '', 25549),
(136157, 'esMX', '¡Tráeme esferas de llama fusionada para fortalecerme para la batalla!', '', 25549),
(136155, 'esMX', 'No cejarán en sus esfuerzos por tratar de corromperme a mí y a mis hermanos. Pero quizás tu llegada pueda cambiar el destino.', '', 25549),
(136154, 'esMX', '¡Al fin, la corrupción termina!', '', 25549),
(136143, 'esMX', 'Por la Luz, no. ¡No después de haber llegado hasta aquí!', '', 25549),
(136142, 'esMX', 'A Pacing Quest Goes Here.', 'A Pacing Quest Goes Here.', 25549),
(136139, 'esMX', '', 'Nuestro hogar... ¿En qué se ha convertido?', 25549),
(136138, 'esMX', 'El Vindicaar está a tus órdenes.', '', 25549),
(136137, 'esMX', 'Llévame a la superficie.', 'Llévame a la superficie.', 25549),
(136136, 'esMX', 'La herida... ardiendo... ardiendo…', '', 25549),
(136135, 'esMX', 'Una espada... en la oscuridad... Arenas... empapadas de dolor.', '', 25549),
(136134, 'esMX', '¿Magni? ¿Estás bien? ¿Magni?', '', 25549),
(136133, 'esMX', 'Illidan es el carcelero del Titán oscuro. Su sacrificio ha puesto fin a la Legión. Al fin, la Cruzada Ardiente... ha terminado.', '', 25549),
(136132, 'esMX', 'Profeta... ¿qué pasó allí?', '', 25549),
(136131, 'esMX', 'Regresen a casa, hijos de Azeroth. Protejan al último titán.', '', 25549),
(136130, 'esMX', 'Hay que hacer un sacrificio.', '', 25549),
(136129, 'esMX', 'Nuestro mundo debe sobrevivir... ¡El precio no importa!', '', 25549),
(136128, 'esMX', '¿Se condenarían ustedes mismos para detenerlo?', '', 25549),
(136127, 'esMX', 'Usaremos el último remanente del poder de Argus para encerrarlo. El trono del Panteón será la prisión de Sargeras... y también la nuestra.', '', 25549),
(136126, 'esMX', 'No.', '', 25549),
(136125, 'esMX', 'Sargeras pronto acabará con todo lo que hemos defendido.', '', 25549),
(136124, 'esMX', 'Eso no importa. Perdimos. ¡Mira al cielo!', '', 25549),
(136123, 'esMX', 'Al fin el alma torturada de Argus descansa en paz.', '', 25549),
(136122, 'esMX', 'Héroes, yo puedo darles una señal a los titanes para comenzar. Pero cuando inicien su ritual... ¡no habrá vuelta atrás!', '', 25549),
(136121, 'esMX', 'Su última acción será usar lo que queda del poder de Argus para encerrar a Sargeras... de una vez por todas.', '', 25549),
(136120, 'esMX', ' Nuestras victorias no significan nada. Mientras Sargeras tenga el alma de Argus para alimentar su ejército infinito, Azeroth estará en grave peligro.', '', 25549),
(136119, 'esMX', 'Los titanes pueden cortar esa conexión... pero no aquí. Tienen que llevar el alma de Argus a su sede de poder... el trono del Panteón.', '', 25549),
(136118, 'esMX', '¡La cuna misma de la creación!', '', 25549),
(136117, 'esMX', '¡Lo lograron! ¡La esencia de Aggramar es libre! Ahora puede reunirse con sus hermanos.', '', 25549),
(136098, 'esMX', '', 'La Archimaga Y''mera te indica que la sigas.', 25549),
(136097, 'esMX', 'Haré todo lo posible para apaciguar los espíritus de los titanes. ¡Ustedes acaben con sus torturadoras!', '', 25549),
(136091, 'esMX', '¡Los tormentos del aquelarre sobre el Gran padre se han materializado!', '', 25549),
(136090, 'esMX', '¡El aquelarre los ataca con las tormentas de Golganneth!', '', 25549),
(136089, 'esMX', '¡Los demonios están usando las llamas del Creador contra ustedes!', '', 25549),
(136088, 'esMX', '¡Cuidado! ¡Los mortales no deben transitar la senda del Tejesueños!', '', 25549),
(136087, 'esMX', 'Los cielos del sur rebosan de energía caótica.', 'Los cielos del sur rebosan de energía caótica.', 25549),
(136084, 'esMX', 'Coloca una luzfena en el espacio.', 'Coloca una luzfena en el espacio.', 25549),
(136083, 'esMX', 'Coloca una jeseliana en el espacio.', 'Coloca una jeseliana en el espacio.', 25549),
(136082, 'esMX', 'Coloca una argulita en el espacio.', 'Coloca una argulita en el espacio.', 25549),
(136081, 'esMX', 'Coloca una malaquita rubicunda en el espacio.', 'Coloca una malaquita rubicunda en el espacio.', 25549),
(136080, 'esMX', 'Coloca una quemirina en el espacio.', 'Coloca una quemirina en el espacio.', 25549),
(136079, 'esMX', 'Coloca una labradorita en el espacio.', 'Coloca una labradorita en el espacio.', 25549),
(136078, 'esMX', 'Ves un lugar vacío donde podría entrar una luzfena.', '', 25549),
(136077, 'esMX', 'Ves un lugar vacío donde podría entrar una jeseliana.', '', 25549),
(136076, 'esMX', 'Ves un lugar vacío donde podría entrar una argulita.', '', 25549),
(136075, 'esMX', 'Ves un lugar vacío donde podría entrar una quemirina.', '', 25549),
(136074, 'esMX', 'Ves un lugar vacío donde podría entrar una malaquita rubicunda.', '', 25549),
(136073, 'esMX', 'Ves un lugar vacío donde podría entrar una labradorita.', '', 25549),
(136066, 'esMX', 'El cristal de Ata''mal pronto me mostró la horrible verdad que caería sobre nosotros si aceptábamos la oferta del titán.', '', 25549),
(136065, 'esMX', 'Tenía la esperanza de que los demás sentirían la oscuridad tras las palabras de Sargeras.', '', 25549),
(136064, 'esMX', 'Cuánto poder... Y nos dice la verdad.', '', 25549),
(136063, 'esMX', 'Es muy poco lo que pide, por lo que nos dará a cambio.', '', 25549),
(136062, 'esMX', 'Juntos, nos convertiremos en la Legión y derrotaremos el vacío hambriento que nos consumiría a todos.', '', 25549),
(136061, 'esMX', 'Júrame lealtad, concédeme los corazones de tu pueblo para mi causa.', '', 25549),
(136059, 'esMX', '¡Te perseguiré por las estrellas, traidor! ¡Aunque me tome mil años!', '', 25549),
(136058, 'esMX', '¡K''ure! ¡Ayúdanos!', '', 25549),
(136057, 'esMX', 'Por favor... mantén a salvo a mi familia.', '', 25549),
(136056, 'esMX', '¡Hatuun! ¡No tienes por qué hacer esto!', '', 25549),
(136055, 'esMX', 'No puede terminar así. Llévate a los otros y váyanse, Profeta. Les daremos tiempo.', '', 25549),
(136054, 'esMX', 'No...', '', 25549),
(136053, 'esMX', '¡Talgath se ha vuelto contra nosotros!', '', 25549),
(136052, 'esMX', '', 'El tiempo de ocultarse terminó. Ayúdenme... o todo terminará.', 25549),
(136051, 'esMX', '', 'Recuerdo mi huída... para negarle su premio.', 25549),
(136050, 'esMX', '', 'Recuerdo la unidad... hasta que la traición la destruyó.', 25549),
(136049, 'esMX', '', 'Recuerdo el despertar... cuando la vida fluía a nuestro alrededor.', 25549),
(136048, 'esMX', '¡Cuando complete mi nuevo Panteón, ningún poder del universo podrá enfrentarse a la Legión!', '', 25549),
(136047, 'esMX', 'La Protectora pronto se revelará. ¡No escapará de mí, amo!', '', 25549),
(136046, 'esMX', 'Hay una que nos sigue eludiendo. Necesitamos su esencia para asegurar la victoria de mi cruzada.', '', 25549),
(136045, 'esMX', 'Los nuestros aún se resisten a la verdad, amo. Pero pronto se quebrarán.', '', 25549),
(136044, 'esMX', 'La hora del renacimiento se acerca. ¿Están listas las almas?', '', 25549),
(136043, 'esMX', 'Conviértete en el instrumento de mi ira una vez más, Aggramar. Acaba con esta intromisión de la Luz.', '', 25549),
(136042, 'esMX', 'Los que no sirvan serán destruidos. Es el único camino.', '', 25549),
(136041, 'esMX', 'El círculo está por completarse. Los mortales no deben interrumpir el renacimiento.', '', 25549),
(136040, 'esMX', '¿Cuál es tu voluntad, amo?', '', 25549),
(136037, 'esMX', '¡Azeroth!', '', 25549),
(136036, 'esMX', 'Si caen en la oscuridad, Sargeras tendrá el poder que necesita para capturar al último titán.', '', 25549),
(136035, 'esMX', '¡Siento a esos demonios corrompiendo los espíritus de los titanes! ¡Obligándolos a usar su poder al servicio de la Legión!', '', 25549),
(136034, 'esMX', '', '¡Ignóralo, hermana! Concéntrate en tu deber. Estas almas están casi listas para unirse a Aggramar al servicio del amo.', 25549),
(136033, 'esMX', 'El objeto emite un suave brillo.', '', 25549),
(136032, 'esMX', '', '¡Estoy harta del parloteo de ese gusano! ¡Déjenme incinerar la carne de sus miserables huesos!', 25549),
(136031, 'esMX', '¡Aaaarggh! ¡Brujas! ¿A eso le llaman tormento? ¿He resistido cosas peores!', '', 25549),
(136030, 'esMX', 'Aquí estamos, el fin se cierne sobre nosotros. Avancen, amigos míos.', '', 25549),
(136029, 'esMX', 'Hay tanta agonía aquí... tantas voces. Es... ¡es casi abrumador! Pero siento que Eonar nos pide que avancemos.', '', 25549),
(136028, 'esMX', 'El corazón de Antorus yace ante nosotros. El poder que sustenta al ejército infinito de la Legión.', '', 25549),
(136027, 'esMX', 'Estamos tan cerca del final...', '', 25549),
(136026, 'esMX', 'Quédate aquí, Magni. Los demás seguiremos.', '', 25549),
(136025, 'esMX', 'Las almas del Panteón son libres, pero han sufrido mucho. Permítanme un momento con ellas. Déjenme ofrecerles un poco de consuelo.', '', 25549),
(136024, 'esMX', '¿Quién podría imaginarse semejante sacrificio?', '', 25549),
(136023, 'esMX', 'Puede que este sea el único lugar sagrado para la Legión. Los demonios preferirían arrancarse los ojos antes que contemplarlo.', '', 25549),
(136022, 'esMX', 'Ya me harté de tanto parloteo. ¡Mostrémosle a este lacayo de Sargeras que no tiene derechos sobre nuestro mundo!', '', 25549),
(136021, 'esMX', 'Pronto despertará mi hermano, Argus. Nuestro nuevo Panteón se unirá al amo para destruir su mundo decadente. Pero ustedes no vivirán para verlo.', '', 25549),
(136020, 'esMX', '|TInterface\\Icons\\Spell_Warlock_DemonicEmpowerment.blp:20|t¡Kin''garoth lanza |cFFFF0000|Hspell:249740|h[Sobrecarga]|h|r!', '', 25549),
(136019, 'esMX', 'Efecto de sonido para las tropas', 'Efecto de sonido para las tropas', 25549),
(136018, 'esMX', 'Efecto de sonido para las tropas', '', 25549),
(136017, 'esMX', 'Efecto de sonido para las tropas', '', 25549),
(136016, 'esMX', 'Veo que la Alianza también ha respondido el llamado.', '', 25549),
(136014, 'esMX', '¿T''uure? ¿Libre de las garras de la Legión al fin? Tu presencia es bienvenida, portantorcha.', '', 25549),
(136013, 'esMX', 'Les daremos uso de inmediato. Gracias por recuperarlos.', '', 25549),
(136012, 'esMX', 'Hay muchos restos de armamentos de nuestros ataques anteriores en el risco al este de la fortaleza. Si los recuperamos progresaremos en nuestra campaña.', '', 25549),
(136011, 'esMX', 'Están un poco desgastados, pero funcionan. Esto nos servirá.', '', 25549),
(136010, 'esMX', '||TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '||TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(136009, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(136008, 'esMX', '|TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(136007, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 25549),
(136006, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(136005, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(136004, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\spell_shadow_summonfelhunter:20|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 25549),
(136002, 'esMX', '¡La resistencia de la Legión caerá en cualquier momento! ¡No les den tregua! ¡No cedan!', '', 25549),
(136001, 'esMX', 'La piedra angular sigue fortaleciéndose. Qué interesante... Quizá podamos usarla para abrir fallas más poderosas.', '', 25549),
(136000, 'esMX', '¡Mostrémosles el precio de su arrogancia!', '', 25549),
(135999, 'esMX', 'Los demonios creen que nuestras fuerzas están concentradas en Argus. Los atacaremos desprevenidos.', '', 25549),
(135998, 'esMX', 'Usa la piedra angular para atravesar la falla. ¡Lleva la batalla a la Legión!', '', 25549),
(135997, 'esMX', 'Castigaremos su arrogancia y les daremos caza donde sea que osen mostrarse.', '', 25549),
(135996, 'esMX', 'A pesar de que marchamos sobre el corazón de Argus, la Legión sigue invadiendo otros mundos.', '', 25549),
(135995, 'esMX', 'Es como lo pensé... la piedra está agotada, pero intacta. Será útil.', '', 25549),
(135994, 'esMX', 'La cruzada fanática de la Legión se derrumba. Purgaremos su hedor de todos los mundos que han profanando.', '', 25549),
(135993, 'esMX', 'Hay un comandante de la Legión en un nuevo punto de invasión. ¡Ve y clama venganza!', '', 25549),
(135992, 'esMX', 'La arrogancia de la Legión ha quedado en claro. Persíguelos por todos los mundos que infesten. Muéstrales que no pueden escapar de nuestra furia.', '', 25549),
(135991, 'esMX', 'La Legión es imprudente e invade otros mundos además de Argus. Eso dispersa sus fuerzas. ¡Busca sus portales y mata a los demonios del otro lado!', '', 25549),
(135990, 'esMX', 'Mi mejor comandante, Lothraxion, fue enviado para defender Azeroth junto a la Mano de plata... Y para guiarte aquí.', '', 25549),
(135989, 'esMX', '¿Ponerles fin? ¡Bah! Sus números son infinitos. Es una tarea imposible. ¡Es un deseo de muerte!', '', 25549),
(135988, 'esMX', 'Solo queremos ser aliados. El Ejército de la Luz nos convocó a Argus para poner fin a la Legión. ¡Peleen a nuestro lado una vez más!', '', 25549),
(135987, 'esMX', 'No hay esperanza. Solo dolor. ¡Dolor!', '', 25549),
(135986, 'esMX', '¡Amo! ¡Reclamaré tu premio!', '', 25549),
(135985, 'esMX', '¡El amo exige su extinción!', '', 25549),
(135984, 'esMX', '¡Una liberación piadosa!', '', 25549),
(135983, 'esMX', '¡Conoce la oscuridad!', '', 25549),
(135982, 'esMX', 'Sin embargo, tu $Galiado:aliada; salvó a muchos de los nuestros de las garras de la Legión. Quizás hayas cambiado.', '', 25549),
(135981, 'esMX', 'Mi guardia... termina.', '', 25549),
(135980, 'esMX', 'Su presencia es una infestación. ¡Y toda infestación debe purgarse!', '', 25549),
(135979, 'esMX', '', 'El amo... será... su fin.', 25549),
(135978, 'esMX', '', 'Sí... ¡Acérquense, pequeños!', 25549),
(135977, 'esMX', '', 'No fueron... suficiente... para mí...', 25549),
(135976, 'esMX', '', '¿Nuevos juguetes? ¡Irresistible!', 25549),
(135975, 'esMX', 'La vista me falla...', '', 25549),
(135974, 'esMX', '¡Veo la debilidad de sus almas!', '', 25549),
(135973, 'esMX', '¡Aquí! Seguro que están cerca.', '', 25549),
(135972, 'esMX', 'Las llamas... los... consumirán...', '', 25549),
(135971, 'esMX', '¡Todos los mundos arderán en fuego vil!', '', 25549),
(135970, 'esMX', 'Im... Imposible...', '', 25549),
(135969, 'esMX', 'Vengan, pequeños. ¡Mueran a mis pies!', '', 25549),
(135968, 'esMX', 'La oscuridad... los... llevará...', '', 25549),
(135967, 'esMX', '¡Las sombras están hambrientas!', '', 25549),
(135966, 'esMX', 'Has derribado a los brutos y le has arrebatado otra victoria a la Legión. Su derrota está cerca.', '', 25549),
(135965, 'esMX', 'Unos eredar brutales han despertado de su estasis. ¡Derríbalos inmediatamente!', '', 25549),
(135964, 'esMX', 'La Legión está perdiendo la calma. ¡Apestan a desesperación!', '', 25549),
(135963, 'esMX', 'Ha caído un infernal, y ha matado a los amos que lo invocaron. ¡Destruye esta monstruosidad antes de que ponga en riesgo nuestro avance!', '', 25549),
(135962, 'esMX', '¿Un ataque exitoso y un engranaje bélico intacto para mí? ¡Esto sí es un milagro!', '', 25549),
(135961, 'esMX', 'Las fuerzas dentro de Antorus deben saber que no están a salvo. ¡Toma un engranaje bélico y golpea los objetivos descuidados tras sus filas!', '', 25549),
(135960, 'esMX', 'Los esclavos krokul huyeron a través del risco después de su liberación. No pudieron haber llegado lejos.', '', 25549),
(135959, 'esMX', 'Y así la Legión pierde otra arma.', '', 25549),
(135958, 'esMX', 'Unos eredar poderosos están capturados en estasis y están corrompiendo sus cuerpos en formas aún más brutales. ¡Mata a los demonios en su letargo!', '', 25549),
(135957, 'esMX', '¡Una explosión gloriosa! ¡El avance de la Luz no se detendrá!', '', 25549),
(135955, 'esMX', 'Los artificieros de la Legión son imprudentes. He encontrado una debilidad en su artillería. ¡Corta sus mechas y destruye sus cargamentos!', '', 25549),
(135954, 'esMX', '', 'Su amo ha fracasado, demonios. ¡Regresen al abismo!', 25549),
(135953, 'esMX', 'Cada nave destruida antes de despegar es un enemigo menos que dispara a los escudos del Vindicaar. ¡Excelente trabajo!', '', 25549),
(135952, 'esMX', 'Nuestros exploradores han encontrado un grupo de algunos de los pilotos más hábiles de la Legión. ¡Esta sería la oportunidad perfecta para eliminarlos!', '', 25549),
(135951, 'esMX', '', '¡La victoria se acerca, campeones! Encárguense de sus fuerzas restantes. Yo misma me encargaré de su navío.', 25549),
(135950, 'esMX', 'Incineraste las madrigueras de esas plagas de la Legión y despejaste el camino para nuestras tropas. ¡Buen trabajo!', '', 25549),
(135949, 'esMX', 'Hemos identificado un área crucial para que nuestras tropas lleguen al frente de batalla, pero está infestada con arañas demoníacas. ¡Quema esos nidos!', '', 25549),
(135948, 'esMX', 'Los soldados que salvaste recordarán los aullidos agónicos de esas bestias viles, incluso cuando marchen a las puertas de Antorus.', '', 25549),
(135947, 'esMX', 'Los canes de la Legión persiguen a nuestras tropas cuando quieren escapar. ¡Rescata la mayor cantidad de nuestras fuerzas que puedas!', '', 25549),
(135946, 'esMX', '', '¡Esbirros de la oscuridad! ¡Conocerán el poder de un titán!', 25549),
(135945, 'esMX', '', '¡Sientan la potencia de la vida! ¡Teman su poder!', 25549),
(135944, 'esMX', 'Has reavivado la llama en el corazón de nuestros soldados. ¡No hay duda de que ganaremos esta guerra!', '', 25549),
(135943, 'esMX', 'El valor de nuestras tropas nunca ha flaqueado, pero hasta un soldado experimentado sufre el cansancio. ¡Una demostración de fuerza en la vanguardia sería toda una inspiración!', '', 25549),
(135942, 'esMX', 'El camino está despejado. ¡Nuestra campaña para acabar con la Legión sigue en marcha!', '', 25549),
(135941, 'esMX', 'Bestias demoníacas y trampas mortales demoran nuestro avance. ¡Encárgate de estos impedimentos!', '', 25549),
(135940, 'esMX', 'Salvados de un destino aciago. Mis soldados te agradecen.', '', 25549),
(135939, 'esMX', '', '¡Largo, intrusos! ¡Regresen con su amo!', 25549),
(135938, 'esMX', 'Uno de nuestros grupos de exploración ha desaparecido. Tal vez la Legión los capturó...o peor. Encuentra a nuestros soldados... ¡antes de que sea tarde!', '', 25549),
(135937, 'esMX', 'Espero que mis hermanos y hermanas conozcan un poco de paz.', '', 25549),
(135936, 'esMX', 'Muchas almas de mi pueblo sufren tormentos a manos de la Legión. Libéralos para que puedan descansar.', '', 25549),
(135935, 'esMX', 'El tormento que toleraron estos soldados... Llegaste justo a tiempo.', '', 25549),
(135934, 'esMX', 'Los inquisidores emergen de la oscuridad y secuestran nuestras patrullas. Busca a los cautivos y sálvalos de su destino cruel.', '', 25549),
(135933, 'esMX', 'Y pensar que los soldados de la Legión beben esa porquería... ¡Son desagradables!', '', 25549),
(135932, 'esMX', 'Mis soldados hablan de brebajes demoníacos que derriten armaduras y desfiguran la carne. ¡Encuentra la fuente de esta alquimia insidiosa y destrúyela!', '', 25549),
(135931, 'esMX', 'La Cruzada Ardiente queda hecha trizas y los planes de la Legión se desmoronan.', '', 25549),
(135930, 'esMX', 'Los invocadores de la Legión están llamando a un infernal gigante para aterrorizar a nuestros aliados. ¡Acaba con su ritual!', '', 25549),
(135926, 'esMX', 'Debemos pelear juntos. ¡Por Azeroth!', '', 25549),
(135925, 'esMX', 'Algo anda mal en este lugar. Una presencia me llama desde las profundidades de la tierra.', '', 25549),
(135911, 'esMX', 'Esta no es un arma de asedio común...', '', 25549),
(135910, 'esMX', 'Algo anda mal.', '', 25549),
(135909, 'esMX', '¿No hay guardias tan cerca de su arma?', '', 25549),
(135908, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMEBOLT.BLP:20|t¡El Paraxis lanza una|cFFFF0000|Hspell:248326|h [Lluvia vil]|h|r sobre ti!', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMEBOLT.BLP:20|t¡El Paraxis lanza una|cFFFF0000|Hspell:248326|h [Lluvia vil]|h|r sobre ti!', 25549),
(135907, 'esMX', '|TInterface\\Icons\\SPELL_FEL_INCINERATE.BLP:20|t¡El Paraxis dispara orbes de energía vil para lograr tu|cFFFF0000|Hspell:248925|h [Aniquilación]|h|r!', '|TInterface\\Icons\\SPELL_FEL_INCINERATE.BLP:20|t¡El Paraxis dispara orbes de energía vil para lograr tu|cFFFF0000|Hspell:248925|h [Aniquilación]|h|r!', 25549),
(135906, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|t¡El Paraxis carga su |cFFFF0000|Hspell:248861|h[Lanza de la perdición]|h|r!', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|t¡El Paraxis carga su |cFFFF0000|Hspell:248861|h[Lanza de la perdición]|h|r!', 25549),
(135905, 'esMX', 'Destruyamos esta máquina vil mientras podamos.', '', 25549),
(135902, 'esMX', '¡Gracias a la Luz! Aún no es tarde.', '', 25549),
(135899, 'esMX', '¡No pueden detenerlo! ¡No pueden detenerme!', '', 25549),
(135897, 'esMX', '¡No quedará nada!', '', 25549),
(135896, 'esMX', 'Libre... libre...', '', 25549),
(135895, 'esMX', '¿Ha... terminado?', '', 25549),
(135894, 'esMX', 'No te acerques. Tú también perecerás.', '', 25549),
(135893, 'esMX', 'La tierra se retuerce en agonía. La vida alimenta la energía vil.', '', 25549),
(135892, 'esMX', 'Debemos resistir. Debemos pelear. Sobrevivir.', '', 25549),
(135891, 'esMX', 'Aquí no hay rastro de la Luz. Solo muerte.', '', 25549),
(135890, 'esMX', 'Los desobedientes son enviados al bosque. Nadie regresa.', '', 25549),
(135889, 'esMX', 'Yo puedo ayudarte, $c, con todas las reparaciones que tu equipo necesite.', '', 25549),
(135888, 'esMX', 'No nos encontrarán a todos. No en las sombras.', '', 25549),
(135887, 'esMX', 'No tiene caso combatirlos. ¡Regresan después de la muerte!', '', 25549),
(135886, 'esMX', 'Nuestras almas alimentan su magia. Ni siquiera la muerte da tregua.', '', 25549),
(135885, 'esMX', '', '...que guía a todos los que quieren usar este poder para sus propios fines.', 25549),
(135884, 'esMX', 'Tienes mi gratitud, $Gforastero:forastera;. Espero que volvamos a encontrarnos.', '', 25549),
(135883, 'esMX', '', 'Se ha convertido en un faro...', 25549),
(135882, 'esMX', '', 'La naaru rebosa de energía del Vacío.', 25549),
(135881, 'esMX', 'A... Ayúda... me...', '', 25549),
(135880, 'esMX', 'Los cuerpos de esos demonios rebosan de energía vil. La Legión no ha perdido tiempo durante su cruzada en este lugar. ', '', 25549),
(135879, 'esMX', 'No te enfrentes a los conquistadores sin ayuda. Puedo sentir su poder desde aquí.', '', 25549),
(135878, 'esMX', 'Estos son algunos de los mejores guerreros de los eredar. No los subestimes.', '', 25549),
(135877, 'esMX', 'El Vindicaar no puede disparar a los devastadores hasta deshabilitar la barrera. ¡Apresúrate!', '', 25549),
(135876, 'esMX', '$p, iremos juntos cuando te hayas preparado.', '', 25549),
(135873, 'esMX', 'Romuul, envía a nuestra vanguardia para asegurar una posición.', '', 25549),
(135872, 'esMX', '¡Búnker en posición, Profeta!', '', 25549),
(135871, 'esMX', '¡Debemos destruir el arma mientras se recarga! ¡Romuul, envía un búnker abajo!', '', 25549),
(135870, 'esMX', 'Avísame cuando tengas todo listo para partir.', '', 25549),
(135867, 'esMX', '', '¿Hay algo en lo que pueda ayudarte, $c?', 25549),
(135864, 'esMX', '¡Aggramar! ¡Ahora el titán caído sirve a Sargeras! Esto es malo... ¡MUY malo!', '', 25549),
(135863, 'esMX', 'Sí, Profeta. De inmediato.', '', 25549),
(135862, 'esMX', 'La Luz nos guiará a ellos. Romuul, comienza con los últimos preparativos y asegúrate de que nuestras fuerzas estén listas. Es hora.', '', 25549),
(135860, 'esMX', 'Golad niton acalah.', '', 25549),
(135859, 'esMX', 'Tu mundo arruinado... adornará... nuestros cielos...', '', 25549),
(135858, 'esMX', 'Mi servicio... termina...', '', 25549),
(135857, 'esMX', 'Amo... te he fallado.', '', 25549),
(135856, 'esMX', 'La Luz se desvanece.', '', 25549),
(135855, 'esMX', 'La muerte espera.', '', 25549),
(135854, 'esMX', 'Soy libre...', '', 25549),
(135853, 'esMX', 'Perdóname...', '', 25549),
(135852, 'esMX', '¡Acalah pek ecta!', '', 25549),
(135851, 'esMX', '¡Krypta!', '', 25549),
(135850, 'esMX', '¡Por la Legión!', '', 25549),
(135849, 'esMX', 'Tu fin se acerca.', '', 25549),
(135848, 'esMX', 'Arrodíllate o muere.', '', 25549),
(135847, 'esMX', 'Tu pueblo caerá.', '', 25549),
(135846, 'esMX', '¡Por el amo!', '', 25549),
(135845, 'esMX', 'Mis hermanos en el Ejército de la Luz esperan nuestra llegada. Solo unidos lograremos la victoria.', '', 25549),
(135844, 'esMX', '¡Pagarás con tu vida!', '', 25549),
(135841, 'esMX', 'Pero... ¿No podían regresar con nosotros de ninguna forma? ¿Con su pueblo? ¿Conmigo?', '', 25549),
(135840, 'esMX', 'El camino está abierto. Vamos, hijos de Argus, aliados, campeones. ¡El Vindicaar espera!', '', 25549),
(135839, 'esMX', 'Todo momento, todo recurso, se ha destinado al nacimiento de un nuevo navío. Nuestro instrumento de venganza.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(135838, 'esMX', 'El Exodar aún está deteriorado por los daños que sufrimos cuando nos estrellamos en este mundo.', '', 25549),
(135835, 'esMX', 'Concédeme tu fuerza, $p. Abriremos el camino juntos.', '', 25549),
(135834, 'esMX', '', 'Las fuerzas del Vacío siempre tratan de establecer bases en nuestro mundo. Es vital oponer resistencia para proteger el equilibrio.', 25549),
(135833, 'esMX', '', 'Han silenciado la presencia del Vacío en esta área. Bien hecho.', 25549),
(135831, 'esMX', '', 'Buena cacería, héroes.', 25549),
(135830, 'esMX', '', 'La bestia ha sido derrotada. Bien hecho, campeones.', 25549),
(135828, 'esMX', '', 'Buen trabajo, héroes.', 25549),
(135827, 'esMX', '', 'Los portales oscuros desgarran la realidad y la energía de las sombras fluye a nuestro reino. ¡Detengan esto, héroes!', 25549),
(135826, 'esMX', '', 'La energía del Vacío está saliéndose de control. Corten de raíz esta marea oscura antes de que nos arrase.', 25549),
(135825, 'esMX', '', 'Algo vil acecha en estas tierras, héroes. Salgan a cazarlo y destrúyanlo.', 25549),
(135824, 'esMX', 'Salvaremos nuestro mundo y detendremos a la Legión Ardiente... de una vez por todas.', '', 25549),
(135823, 'esMX', 'Compañeros draenei... campeones de Azeroth... ha llegado la hora de invadir Argus.', '', 25549),
(135822, 'esMX', '', 'Una entidad del Vacío ha aparecido en nuestro mundo. No podemos dejar que propague su corrupción.', 25549),
(135821, 'esMX', '', 'Siento una oleada de energía del Vacío en esta área. Busca la fuente y destrúyela.', 25549),
(135820, 'esMX', 'Imposible...', '', 25549),
(135819, 'esMX', 'Ya hemos ganado.', '', 25549),
(135818, 'esMX', 'Es demasiado tarde.', '', 25549),
(135817, 'esMX', 'La cruzada... debe...', '', 25549),
(135816, 'esMX', 'He... fallado.', '', 25549),
(135815, 'esMX', 'Antorus me llama.', '', 25549),
(135814, 'esMX', '¡Nunca podrán derrotarnos!', '', 25549),
(135813, 'esMX', '¡El apocalipsis es inevitable!', '', 25549),
(135812, 'esMX', '¡Contempla el poder de la Legión Ardiente!', '', 25549),
(135811, 'esMX', '¡Su mundo está condenado!', '', 25549),
(135810, 'esMX', '¡Nuestra cruzada es eterna!', '', 25549),
(135809, 'esMX', '¡Morirán aplastados a mis pies!', '', 25549),
(135808, 'esMX', 'Entonces finalmente mis padres pueden regresar a casa.', '', 25549),
(135807, 'esMX', 'Argus es nuestro hogar ancestral. No permitiremos que siga en manos de la Legión.', '', 25549),
(135806, 'esMX', '', 'Nunca vi a los draenei reunir una fuerza tan formidable.', 25549),
(135805, 'esMX', 'Vamos, te guiaré al Arca de las Luces. Los demás esperan nuestra llegada.', '', 25549),
(135804, 'esMX', 'Alabo tu heroísmo. Cada soldado que hay en el campo de batalla cuenta.', '', 25549),
(135803, 'esMX', 'Un grupo de los Templeluz está atrapado tras líneas enemigas. Debemos salvarlos.', '', 25549),
(135802, 'esMX', '¡Cuánto poder! Estos demonios deben saber que no nos derrotarán tan fácilmente.', '', 25549),
(135801, 'esMX', 'Se han abierto portales de la Legión cerca de la cumbre Nath''raxas para capturarla. Usa uno de nuestros engranajes bélicos para frustrar sus intentos.', '', 25549),
(135800, 'esMX', 'Acabaremos con la Legión, incluso si debemos destruir el propio Argus.', '', 25549),
(135799, 'esMX', 'Los hechiceros eredar convierten la sangre vil de este mundo en armas que usan contra nosotros. Hay que desmantelarlas.', '', 25549),
(135798, 'esMX', 'No se equivoquen, cada mundo está infestado con ejércitos interminables de demonios. Tenemos mucho por hacer.', '', 25549),
(135797, 'esMX', 'Que así sea. Los ejércitos de la Legión están dispersos por los mundos conquistados. Debemos asegurarnos de que no vengan a defender Argus hasta terminar nuestro trabajo.', '', 25549),
(135796, 'esMX', '', 'Qué bueno que apareciste. Hay tantos objetivos que ni yo llego a dispararles a todos.', 25549),
(135794, 'esMX', 'Expulsaremos a la Legión de todos los mundos que profanen. ¡Esto es solo el comienzo!', '', 25549),
(135793, 'esMX', '¡Las fuerzas de la Legión no están preparadas para tu llegada! ¡Extermínalas!', '', 25549),
(135792, 'esMX', '¡Ah, sí! ¡Funciona mejor de lo que pensé! Excelente.', '', 25549),
(135791, 'esMX', '¡Ahora, dispara! ¡Por Argus! ¡Por nuestro pueblo!', '', 25549),
(135790, 'esMX', 'Estamos listos. ¡Prepárate para disparar!', '', 25549),
(135789, 'esMX', 'Listo. ¡Rápido, dispara el cañón principal!', '', 25549),
(135788, 'esMX', 'Este es el corazón de la Legión, sus fortificaciones son la prueba. Un ataque ahora sería una locura. Necesitamos más preparación para conseguir una ventaja.', '', 25549),
(135787, 'esMX', '¡Debilita sus fuerzas! ¡Nosotros apuntaremos el arma del Vindicaar para dar el golpe de gracia!', '', 25549),
(135786, 'esMX', 'Si destruyes los generadores, deberíamos poder atacar sus defensas con el Vindicaar. ¡Ya casi lo logramos!', '', 25549),
(135785, 'esMX', '¡Con eso bastará! Estoy agregando las coordenadas a nuestra matriz de faros.', '', 25549),
(135784, 'esMX', 'Con el crisol en funcionamiento, ¡nuestras armas brillarán como las mismísimas estrellas! Ven, te mostraré.', '', 25549),
(135783, 'esMX', '¡Viajaremos hacia el corazón de Argus y le daremos el golpe de gracia a la Legión!', '', 25549),
(135782, 'esMX', 'No podemos permitir que esto nos detenga. La Sentencia de la Luz es la clave de nuestra victoria.', '', 25549),
(135781, 'esMX', '¡Sus largos años de servicio a la Luz no serán en vano!', '', 25549),
(135780, 'esMX', 'La Luz y la Sombra se complementan. Si controlamos el poder de un grandioso ser de las sombras, ¡el crisol estará terminado!', '', 25549),
(135779, 'esMX', 'Me pregunto si... No, no puede ser...', '', 25549),
(135778, 'esMX', 'La Luz arde con intensidad en el crisol, ¡pero aún no funciona!', '', 25549),
(135775, 'esMX', 'Su Luz no puede caer en la oscuridad. Debemos resguardar lo que podamos en el crisol.', '', 25549),
(135773, 'esMX', '¡Basta! No hay vuelta atrás. Nuestra misión continúa, con o sin la Madre de la Luz.', '', 25549),
(135767, 'esMX', 'Aunque su forma se ha destruido, su Luz no nos ha abandonado. No todavía.', '', 25549),
(135766, 'esMX', 'Tienes razón, Profeta. La misión sigue en pie.', '', 25549),
(135765, 'esMX', 'No te preocupes, aún hay mucha energía en la superficie devastada de Argus. ¡Solo debemos encontrarla!', '', 25549),
(135764, 'esMX', 'La Luz aún brilla dentro de mí. Aún brilla dentro de todos ustedes. ¡Venceremos!', '', 25549),
(135763, 'esMX', 'Ya casi está terminado, pero necesita una fuente de energía. Y necesitamos algo muy potente', '', 25549),
(135762, 'esMX', 'Debemos continuar con nuestra misión. Debemos destruir a la Legión.', '', 25549),
(135761, 'esMX', 'Aún tenemos un objetivo. Aún tenemos un mundo que salvar. ¡Debemos seguir adelante!', '', 25549),
(135760, 'esMX', 'La Luz no se extingue con la naaru suprema. ¡Brilla en cada uno de nosotros!', '', 25549),
(135757, 'esMX', '¡Cuando esté terminado, este crisol será capaz de concentrar las fuerzas fundamentales del cosmos en tu arma! Pero... no todavía.', '', 25549),
(135755, 'esMX', '¡La Luz te rodea! ¡Disfruta de su poder!', '', 25549),
(135754, 'esMX', '¡Por Azeroth!', '', 25549),
(135753, 'esMX', '¡Engranaje bélico en posición!', '', 25549),
(135752, 'esMX', '¡Que sientan tu furia!', '', 25549),
(135750, 'esMX', 'Tengo muchos experimentos en mente para estos fósiles. Conseguirlos no fue nada fácil. Gracias.', '', 25549),
(135749, 'esMX', '¡Fascinante! Los árboles antiguos de este lugar tienen restos de resina fosilizada con propiedades inusuales. Oye... ¿Te importaría buscar algunas muestras para mí, $gamigo mío:amiga mía;?', '', 25549),
(135745, 'esMX', 'Ten cuidado: se necesita mucho poder para desplegar un engranaje bélico. ¡No esperes a necesitar uno cuando se esté recargando!', '', 25549),
(135744, 'esMX', 'Cuando el transmisor esté unido a la Sentencia de la Luz, podremos usarlo para desplegar un engranaje bélico en tu posición. Creo que luego sabrás qué hacer.', '', 25549),
(135731, 'esMX', 'Es un punto de vista muy interesante, Lady Liadrin. Me has dado mucho para reflexionar.', '', 25549),
(135730, 'esMX', '', 'Así es. Te aseguro que nuestro camino no ha sido sencillo y hemos atravesado épocas oscuras. Pero juntos, nos enfrentamos a un mundo que muchas veces nos ha dado la espalda. Juntos, somos fuertes.', 25549),
(135729, 'esMX', '¿Y la Horda les sirvió para ese fin?', '', 25549),
(135728, 'esMX', '', 'Decidimos unirnos para luchar por nuestro lugar en Azeroth. Y comprendimos que necesitábamos aliados que nos acompañaran en la batalla.', 25549),
(135727, 'esMX', 'No hay peor corrupción que una sed insaciable de poder. ¿Cómo hicieron para dejar todo eso atrás?', '', 25549),
(135725, 'esMX', '', 'Y mi pueblo también. Uno de los líderes de los sin''dorei también realizó un pacto con la Legión y nos corrompió en el proceso.', 25549),
(135724, 'esMX', 'En toda mi vida, jamás había salido más allá de las fronteras de Suramar. Al ver este lugar comprendo el terrible destino que mi pueblo estuvo a punto de experimentar.', '', 25549),
(135723, 'esMX', '', 'Buena pelea. ¡Nuestras espadas destruirán esta marea de demonios!', 25549),
(135722, 'esMX', '', 'Incluso en este mundo lóbrego, ¡pelearemos por Azeroth!', 25549),
(135721, 'esMX', '', 'El enemigo está cerca. Prepárate. Peleamos por el futuro de nuestro mundo.', 25549),
(135720, 'esMX', '', 'Un demonio poderoso está cerca... muy cerca. ¡Derrótalo y que sirva de ejemplo!', 25549),
(135718, 'esMX', '', 'El tiempo se acaba. El enemigo se acerca. Acérquense y prepárense, hijos míos. La batalla final está cerca.', 25549),
(135717, 'esMX', '', 'Se los ruego, peleen a mi lado. Juntos podemos rechazar este embate y negarle la victoria a Sargeras.', 25549),
(135716, 'esMX', '', 'Durante eras incontables mi espíritu ha permanecido aquí, a salvo de las garras del Titán oscuro. Pero al fin me ha encontrado, y viene a reclamar mi poder.', 25549),
(135715, 'esMX', '', 'Bienvenidos a mi santuario, mortales.', 25549),
(135714, 'esMX', '', 'Los invasores están cargando sus armas. ¡Rápido! Usen estos portales para abordar sus navíos. ¡Detengan su ataque!', 25549),
(135713, 'esMX', 'Pronto estaremos en el patio para exterminarlos. ¡Por Azeroth!', '', 25549),
(135712, 'esMX', '', 'Veo que has elegido tu arma. Yo también.', 25549),
(135711, 'esMX', '', 'Una muerte apropiada para ese enemigo. Bien hecho.', 25549),
(135710, 'esMX', '', 'Cuánta habilidad. Aunque creo que mis flechas habrían acabado con ese demonio más rápido.', 25549),
(135709, 'esMX', '', 'Qué efectivo. Cada golpe que sufre la Legión es una bendición para nuestra causa.', 25549),
(135708, 'esMX', '', 'La Luz y la Sombra son medios para un fin. Para tu próximo enemigo, puedes elegir el arma que prefieras.', 25549),
(135707, 'esMX', '', 'Esta bestia de la oscuridad debe morir. No tengas piedad, pero apresúrate.', 25549),
(135706, 'esMX', 'Alto exarca, nuestro engranaje bélico está en funcionamiento. ¡Contemple!', '', 25549),
(135705, 'esMX', 'Gracias, $n. Espero que sus almas encuentren la paz.', '', 25549),
(135704, 'esMX', 'Nadie merece el destino que les espera a las almas reclamadas por la Legión.', '', 25549),
(135703, 'esMX', 'Si tomamos esta fortaleza ganaremos tiempo valioso para prepararnos para un ataque masivo sobre Antorus.', '', 25549),
(135702, 'esMX', 'Te veré en nuestra base de operaciones cerca de Nath''raxas. El Vindicaar debe estar listo para ayudarnos a capturar la fortaleza de inmediato.', '', 25549),
(135700, 'esMX', 'Primero la cuchilla de Maiev, ahora la tuya. Su castigo en Antorus será severo.', '', 25549),
(135698, 'esMX', 'Un señor del terror que antes me servía en el Templo Oscuro decidió unirse a la Legión. Lamentará haberme enfrentado.', '', 25549),
(135697, 'esMX', 'Su alma regresará a Antorus para renacer, pero sufrirá un castigo. Sargeras no tolera los fracasos.', '', 25549),
(135696, 'esMX', 'Una doncella de la fatalidad pretende formar un ejército de demonios bajo nuestras narices. No podemos permitirlo.', '', 25549),
(135695, 'esMX', 'La Legión no cede en su ataque. Debemos permanecer alerta.', '', 25549),
(135693, 'esMX', 'Un demonio se atreve a liderar un asalto contra el Vindicaar. Su muerte enviará un mensaje muy claro al enemigo.', '', 25549),
(135692, 'esMX', '', 'He cazado demonios a través del Vacío Abisal durante mil años. Creo que puedo dejarte este.', 25549),
(135691, 'esMX', '', 'Hemos ideado un plan para atacar a la Legión. Esta operación requiere de tus habilidades especiales.', 25549),
(135690, 'esMX', 'Los animales más jóvenes de la ciudad son especialmente susceptibles a la energía del Vacío. Usa este cristal para liberarlos de su control.', '', 25549),
(135689, 'esMX', 'Liberar a estas criaturas de las garras de las sombras fue un acto de piedad. Me entristece ver la ciudad así.', '', 25549),
(135688, 'esMX', '¡Eso debería ser todo! Solo activa la consola una última vez para completar la transferencia. ¡Yo me encargaré del resto!', '', 25549),
(135687, 'esMX', '', 'Bien hecho. ¡Los demonios quedarán furiosos!', 25549),
(135686, 'esMX', '', 'Con resultados como estos, confío en que lograremos la victoria.', 25549),
(135685, 'esMX', '', 'Hay más de una forma de golpear a la Legión. ¡Bien hecho!', 25549),
(135684, 'esMX', '', 'Para diezmar la ofensiva de la Legión, debemos destruir su infraestructura. ¡Pelea en nombre de Azeroth!', 25549),
(135682, 'esMX', '', 'Tenemos un objetivo que derribar en esta área. Elige el arma que creas más apropiada.', 25549),
(135681, 'esMX', '', 'A veces la sutileza es más efectiva que un ataque directo. Creo que es la estrategia adecuada para esta situación.', 25549),
(135678, 'esMX', 'La Legión no destruirá nuestros espíritus. Has recuperado estos recuerdos de nuestro pasado, y le has dado a mi pueblo esperanza para resistir. Te lo agradezco.', '', 25549),
(135677, 'esMX', 'Aunque nunca podremos prosperar aquí como antes, Argus es nuestro hogar. Has facilitado nuestra lucha, $Gforastero:forastera;, al menos por hoy.', '', 25549),
(135676, 'esMX', 'La Legión sigue llevándose a los de mi pueblo. Quieren romper nuestros vínculos de comunidad, enemistarnos entre hermanos. ¡Libéralos por favor!', '', 25549),
(135675, 'esMX', 'Mi pueblo tiene muy poco, pero aún así los demonios roban nuestras reliquias para separarnos de nuestro pasado. Ayúdanos a recuperar lo que nos pertenece, $Gforastero:forastera;.', '', 25549),
(135672, 'esMX', 'El ejército de la Luz resiste.', '', 25549),
(135671, 'esMX', 'El destino de nuestro mundo está en juego.', '', 25549),
(135669, 'esMX', 'NO ESTÁS PRE... <pausa> ¿Qué dices? ¿Que te estoy haciendo esperar demasiado? Bah. ¿Qué sabes tú de esperar?', '', 25549),
(135668, 'esMX', 'No permitiré que me toquen canallas como ustedes.', '', 25549),
(135667, 'esMX', 'No estás $Gpreparado:preparada;.', '', 25549),
(135666, 'esMX', 'Tu persistencia no me sorprende.', '', 25549),
(135665, 'esMX', 'IGC: Velen escapa de Argus', 'IGC: Velen escapa de Argus', 25549),
(135664, 'esMX', 'Mi cacería es eterna.', '', 25549),
(135663, 'esMX', 'La Legión conocerá su fin.', '', 25549),
(135662, 'esMX', 'Termina el trabajo.', '', 25549),
(135661, 'esMX', 'Llegaré al final de todo esto.', '', 25549),
(135660, 'esMX', 'Terminaré mi cacería.', '', 25549),
(135659, 'esMX', 'La furia de la Legión no se compara con la mía.', '', 25549),
(135658, 'esMX', 'No pierdas el tiempo.', '', 25549),
(135657, 'esMX', 'Una llegada oportuna.', '', 25549),
(135656, 'esMX', 'Al fin ha llegado la hora.', '', 25549),
(135655, 'esMX', 'La Legión no se detendrá ante nada para destruir nuestro mundo.', '', 25549),
(135654, 'esMX', 'Ningún sacrificio es demasiado grande.', '', 25549),
(135653, 'esMX', 'El mal se acerca.', '', 25549),
(135648, 'esMX', 'Entonces disfrutaré de la experiencia mientras pueda. Gracias por el consejo, Khadgar.', '', 25549),
(135647, 'esMX', 'No tienes de qué preocuparte. Estamos en presencia de los poderes primigenios que le dieron forma al mismísimo cosmos. Que sientas la fuerza de su influencia no es un símbolo de debilidad. Al contrario, demuestra que estás en sintonía con estos poderes.', '', 25549),
(135646, 'esMX', 'Todavía podemos penetrar en Antorus y desmantelar la máquina de resurrección de la Legión, pero necesitaremos a Xe''ra y al Ejército de la Luz con nosotros.', '', 25549),
(135645, 'esMX', 'Debo confesar que es un alivio saber que sientes lo mismo. Creí que era el único que experimentaba esas sensaciones.', '', 25549),
(135644, 'esMX', 'Lo sé, archimago. Puede ser... un tanto abrumador. Es difícil concentrarse.', '', 25549),
(135643, 'esMX', 'Jamás había visto un lugar como este, Khadgar. El poder que hay aquí...', '', 25549),
(135642, 'esMX', 'Una victoria valerosa. Ningún esbirro de la Legión debe jugar con fuerzas como esas.', '', 25549),
(135641, 'esMX', 'El poder es poder. Lo que importa es cómo lo usas. Con los propios recursos de la Legión en su contra, la batalla se vuelve a nuestro favor.', '', 25549),
(135640, 'esMX', 'Percibo una entidad que controla fuerzas poderosas con gran malevolencia. ¡Este demonio debe morir!', '', 25549),
(135639, 'esMX', 'Argus es un mundo repleto de poder. La Legión lo ha utilizado... ¡Y ahora es nuestro turno!', '', 25549),
(135637, 'esMX', 'El Vindicaar será el instrumento de nuestra venganza. Al igual que con cualquier arma, deberías conocerla bien antes de volver a arremeter en la batalla.', '', 25549),
(135636, 'esMX', 'Una victoria convincente. Has demostrado la inutilidad de la existencia de la Legión.', '', 25549),
(135635, 'esMX', 'Los gritos de fracaso del demonio resuenan por todo Argus. Nunca me cansaré de ese sonido.', '', 25549),
(135634, 'esMX', 'Acabaste rápido con las ambiciones de ese demonio. Pero sin dudas otros buscarán un camino similar hacia la infamia.', '', 25549),
(135633, 'esMX', 'Una victoria decisiva. No esperaba menos de ti.', '', 25549),
(135632, 'esMX', 'Ese ya no podrá alardear de nada, excepto la muerte rápida que sufrió.', '', 25549),
(135631, 'esMX', 'La moral de la Legión se derrumba... como su posición en Argus.', '', 25549),
(135630, 'esMX', 'No importa cuántas monstruosidades envíen contra nosotros, las eliminaremos.', '', 25549),
(135629, 'esMX', 'Cada objetivo que derribamos es otro fracaso en la cruzada del Titán oscuro.', '', 25549),
(135628, 'esMX', 'Ahora saben la verdad... Nunca cederemos. Su cruzada pronto caerá en el olvido.', '', 25549),
(135627, 'esMX', 'Estos enemigos no merecían piedad. Y no la han recibido.', '', 25549),
(135626, 'esMX', 'Sí... están aturdidos. Buena pelea.', '', 25549),
(135625, 'esMX', 'Nuestros enemigos sufrirán como nosotros.', '', 25549),
(135624, 'esMX', 'Guiaré a mi pueblo en la oscuridad.', '', 25549),
(135623, 'esMX', 'Una amenaza se acerca. Elimínala y demuéstrales a los demonios que no pueden contra nosotros.', '', 25549),
(135622, 'esMX', 'Nos ofrece un poder distinto a todo lo que conocemos.', '', 25549),
(135621, 'esMX', '¡El Triunvirato ha recibido a un visitante de otro mundo!', '', 25549),
(135620, 'esMX', 'La luz de nuestra civilización brilla intensamente... sobre lo que temíamos no era más que un vacío..', '', 25549),
(135619, 'esMX', 'Ahora les pido que unan sus voces en agradecimiento. ¡Alabado sea Sargeras!', '', 25549),
(135618, 'esMX', 'Con la ayuda de nuestro nuevo aliado, ¡la luz de los eredar brillará en todo el cosmos!', '', 25549),
(135617, 'esMX', 'Él nos ha mostrado el camino hacia un nuevo futuro.', '', 25549),
(135616, 'esMX', 'Ya no debemos lidiar con esta soledad.', '', 25549),
(135615, 'esMX', 'Durante mucho tiempo, los eredar hemos estado solos en el universo.', '', 25549),
(135614, 'esMX', 'Mi pueblo, los he llamado para compartir una revelación.', '', 25549),
(135613, 'esMX', 'Me alegra mucho ver que las viejas tradiciones se honran de esta forma. Gracias.', '', 25549),
(135612, 'esMX', 'Tantas tradiciones draenei se han perdido durante nuestro viaje... Los espíritus de Mac''Aree no han olvidado. Practican el combate ritual de Jed''hin hasta estos días. ¡Quizás reciban con brazos abiertos un nuevo desafío!', '', 25549),
(135611, 'esMX', 'Cuidado, una amenaza vil quiere demostrar su fuerza. Acaba con sus ambiciones.', '', 25549),
(135609, 'esMX', 'Este demonio quiere acabar con nuestra invasión para forjarse una reputación en la Legión. Demuéstrale su estupidez.', '', 25549),
(135608, 'esMX', 'No bajes la guardia. Una amenaza acecha, sedienta de sangre mortal.', '', 25549),
(135607, 'esMX', 'Otro campeón demoníaco ruge y gruñe. Silencia su cacofonía.', '', 25549),
(135606, 'esMX', 'Los demonios se reúnen alrededor de una amenaza brutal. Demuéstrales que su fe no será recompensada.', '', 25549),
(135605, 'esMX', 'Un demonio brutal acecha más adelante. Envíalo de regreso al infierno que lo creó.', '', 25549),
(135603, 'esMX', 'Otro campeón de la Legión está cerca. Acaba con su existencia.', '', 25549),
(135602, 'esMX', 'La Legión se cree resguardada en Argus. Intocable. ¡Pagarán su arrogancia con sufrimiento!', '', 25549),
(135601, 'esMX', 'Hay demonios por doquier. Ve. Pelea. No tengas piedad.', '', 25549),
(135600, 'esMX', 'La escoria demoníaca infecta esta tierra arrasada. No tomes prisioneros. ¡Mata a todo enemigo que encuentres!', '', 25549),
(135599, 'esMX', 'Todo demonio que deambula por este mundo es una perversión de lo que Argus supo ser. Has asestado un golpe en nombre de la Luz.', '', 25549),
(135598, 'esMX', 'La Luz no vencerá a menos que peleemos por ella. Hoy has cumplido con tu parte.', '', 25549),
(135597, 'esMX', 'La noticia de tu victoria se propagará por Argus. ¡Los que se aferran al recuerdo del Falsario están condenados a caer!', '', 25549),
(135596, 'esMX', 'Aunque la Legión es implacable, los demonios no pueden resistir a la Luz.', '', 25549),
(135595, 'esMX', 'Sargeras le arrebató demasiado a mi mundo. ¡Ahora es su turno de perder!', '', 25549),
(135594, 'esMX', 'Con cada enemigo como ese que derrotas, nuestra victoria definitiva se acerca cada vez más.', '', 25549),
(135593, 'esMX', 'En nombre de todas las nobles almas perdidas a manos de la Legión, te doy las gracias.', '', 25549),
(135592, 'esMX', 'Jamás lo dudes: al final, la Luz saldrá victoriosa.', '', 25549),
(135591, 'esMX', 'Puede que nos veamos superados en número, pero la Luz nos acompaña. ¡La victoria será nuestra!', '', 25549),
(135590, 'esMX', 'Nunca recuperaremos lo que hemos perdido, pero los haremos pagar por lo que le hicieron a Argus.', '', 25549),
(135589, 'esMX', 'La corrupción vil contamina el aire. ¡Acaba con esta aberración!', '', 25549),
(135588, 'esMX', 'Siento una presencia vil... Un mal que quiere extinguir la Luz. ¡Levántate en armas y acaba con este enemigo!', '', 25549),
(135587, 'esMX', 'Un discípulo de Kil''jaeden quiere vengar a su amo. ¡Prepárate para su ataque!', '', 25549),
(135585, 'esMX', 'Justo cuando la Luz logra consolidar una posición, otra nave del mal se dispone a atacarnos. Necesitamos tu fuerza una vez más.', '', 25549),
(135584, 'esMX', 'Un agente del Titán oscuro se prepara para atacar. ¡Ataca primero! ¡Ataca sin temor!', '', 25549),
(135583, 'esMX', 'Prepárate, adalid. La maldad ronda en las cercanías...', '', 25549),
(135582, 'esMX', 'Este villano profana el hogar que perdí hace tanto tiempo. ¡Acaba con esta atrocidad!', '', 25549),
(135581, 'esMX', 'Se acerca un campeón de la oscuridad insidioso. ¡Elimínalo!', '', 25549),
(135580, 'esMX', 'Debemos poner fin a la influencia de la Legión sobre esta tierra. ¡Es nuestro momento! ¡Peleen contra la oscuridad!', '', 25549),
(135575, 'esMX', 'La Legión ha profanado lo que supo ser un lugar sagrado para nuestro pueblo. ¡Expúlsalos!', '', 25549),
(135573, 'esMX', 'Toda victoria es satisfactoria, pero cuando cae un enemigo como este... Debo admitir que es mucho más placentero.', '', 25549),
(135572, 'esMX', 'El Ejército de la Luz se enorgullece de tenerte entre sus aliados.', '', 25549),
(135571, 'esMX', 'Impresionantes tácticas. Ahora entiendo por qué la Legión siente temor ante tu presencia.', '', 25549),
(135570, 'esMX', 'Es bueno saber que durante mi larga ausencia de Azeroth, nuestro mundo estuvo protegido por héroes como tú.', '', 25549),
(135569, 'esMX', 'Peleas como si hubieras combatido a la Legión durante mil años.', '', 25549),
(135568, 'esMX', 'Poco a poco nuestros esfuerzos merman el poderío de la Legión.', '', 25549),
(135567, 'esMX', 'Una victoria bien merecida. ¡La Legión caerá!', '', 25549),
(135566, 'esMX', 'Buena pelea. En nuestra larga batalla contra los demonios, debemos saborear cada victoria.', '', 25549),
(135564, 'esMX', 'Gracias a tu acción rápida y decisiva, los soldados del Ejército están a salvo. Tienes mi gratitud.', '', 25549),
(135563, 'esMX', 'Mi fe en ti se vio recompensada. Has ayudado a la Luz este día.', '', 25549),
(135562, 'esMX', 'Ese cargamento le pertenece al Ejército de la Luz, no a los esbirros de Sargeras. Bien hecho.', '', 25549),
(135561, 'esMX', 'Ahora la Legión Ardiente sabe la verdad... ¡los expulsaremos del corazón de Argus!', '', 25549),
(135560, 'esMX', 'Gracias a tu ayuda, hemos reunido nuestras fuerzas y la Legión está en retirada.', '', 25549),
(135559, 'esMX', 'Si nos atacan, responderemos con más fuerza. ¡A la victoria!', '', 25549),
(135558, 'esMX', 'La Legión cree que este bruto puede intimidarnos. ¡Demuéstrales lo contrario!', '', 25549),
(135557, 'esMX', 'Mis exploradores han avistado un objetivo principal. ¡A las armas!', '', 25549),
(135556, 'esMX', 'Un demonio acecha más adelante. ¡Elimínalo en nombre de Azeroth!', '', 25549),
(135554, 'esMX', 'Aquí en Argus sobran los enemigos. Tenemos otro cerca.', '', 25549),
(135553, 'esMX', 'Allí adelante... un gran mal se prepara para atacar. ¡Concéntrate!', '', 25549),
(135552, 'esMX', 'Los demonios se reúnen detrás de uno de sus campeones. ¡Derríbalo!', '', 25549),
(135551, 'esMX', 'Presiento una gran oscuridad cerca. ¡Mantente en guardia!', '', 25549),
(135550, 'esMX', 'Un objetivo vital aguarda más adelante. ¡Elimínalo en nombre de la Luz!', '', 25549),
(135549, 'esMX', 'Las fuerzas de la Legión han capturado a algunas de nuestras tropas. Los demonios los torturarán... o algo peor. ¡Debes guiar un grupo de rescate!', '', 25549),
(135548, 'esMX', 'El Ejército de la Luz te necesita. Sé que podemos confiar en ti para este trabajo.', '', 25549),
(135547, 'esMX', 'Los suministros del Xenedar han caído en manos de la Legión. ¡Recupera lo que nos pertenece!', '', 25549),
(135546, 'esMX', 'La Legión cree que esta posición es inexpugnable. ¡Vamos a mostrarles que están equivocados!', '', 25549),
(135545, 'esMX', 'Debemos repeler a los demonios antes de que arrasen con nosotros. ¡A las armas!', '', 25549),
(135544, 'esMX', 'Las fuerzas de la Legión se han apoderado de este lugar. ¡Expúlsalas en nombre de la Luz!', '', 25549),
(135543, 'esMX', 'Resistiremos.', '', 25549),
(135542, 'esMX', 'La Legión pagará.', '', 25549),
(135541, 'esMX', 'Adiós.', '', 25549),
(135540, 'esMX', 'Ten cuidado.', '', 25549),
(135538, 'esMX', 'No fallaremos.', '', 25549),
(135537, 'esMX', 'Te saludo.', '', 25549),
(135536, 'esMX', '¿Qué quieres?', '', 25549),
(135535, 'esMX', '¿Sí?', '', 25549),
(135534, 'esMX', 'Ha llegado nuestra hora.', '', 25549),
(135533, 'esMX', 'Nunca nos rendiremos.', '', 25549),
(135532, 'esMX', 'Camina por las sombras de la tierra.', '', 25549),
(135531, 'esMX', 'Cuídate de la ira de la Legión.', '', 25549),
(135530, 'esMX', 'Argus siempre será nuestro.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(135529, 'esMX', 'Los Caído oscuro no se rendirán.', '', 25549),
(135528, 'esMX', 'Luchamos y sobrevivimos.', '', 25549),
(135527, 'esMX', 'Te escucho. Habla.', '', 25549),
(135526, 'esMX', '¡Prepárate!', '', 25549),
(135525, 'esMX', '¡Ahí vienen!', '', 25549),
(135524, 'esMX', '', '¡Enemigos!', 25549),
(135523, 'esMX', '¡Sígueme!', '', 25549),
(135522, 'esMX', '¡Sígueme!', '', 25549),
(135521, 'esMX', '', '¡Sígueme!', 25549),
(135520, 'esMX', '¡Cuidado!', '', 25549),
(135519, 'esMX', '¡Por aquí!', '', 25549),
(135518, 'esMX', 'Por la Luz... ¡No!', '', 25549),
(135517, 'esMX', '¡Cuidado!', '', 25549),
(135516, 'esMX', '¡Por aquí!', '', 25549),
(135515, 'esMX', 'Por la Luz... ¡No!', '', 25549),
(135514, 'esMX', '', '¡No!', 25549),
(135513, 'esMX', '', '¡Por aquí!', 25549),
(135512, 'esMX', '', '¡Cuidado!', 25549),
(135510, 'esMX', 'Es más débil que una brisa, pero me parece tan familiar... Es como el llamado de Azeroth, pero... no es ella.', '', 25549),
(135509, 'esMX', 'Que la Luz nos ayude.', '', 25549),
(135508, 'esMX', 'Si el Blasón del conocimiento realmente está en el templo... nos enfrentaremos al mismísimo Vacío.', '', 25549),
(135507, 'esMX', 'Hay muchas cosas que Xe''ra no quería que supieras.', '', 25549),
(135506, 'esMX', 'Imposible. ¡Es una naaru! ¡Un ser de la Luz!', '', 25549),
(135505, 'esMX', 'El pacifista de siempre. ¡Enfréntame!', '', 25549),
(135504, 'esMX', 'Talgath. No tenemos por qué pelear. Te ofrezco una oportunidad: ríndete.', '', 25549),
(135503, 'esMX', 'La Legión quiere incorporar este mundo en su dominio. Destruyan sus ambiciones.', '', 25549),
(135502, 'esMX', 'Este mundo contiene un poder que la Legión no debe poseer. Impidan que lo reclamen.', '', 25549),
(135501, 'esMX', 'La Legión cree que controla este mundo. Demuéstrenles que se equivocan.', '', 25549),
(135500, 'esMX', 'El poder que yace dormido en este mundo podría fortalecer a la Legión. Reduzcan estos demonios a cenizas antes de que lo reclamen.', '', 25549),
(135499, 'esMX', 'Si la Legión controla el poder de este reino, serán imparables. Expúlsenlos de aquí.', '', 25549),
(135498, 'esMX', 'La Legión quiere reclamar el poder de este mundo ardiente. No deben lograrlo.', '', 25549),
(135497, 'esMX', 'Ya he visto estas tácticas antes. Esperemos que nuestro enemigo no sea quien yo creo.', '', 25549),
(135495, 'esMX', 'Llegamos.', '', 25549),
(135494, 'esMX', 'Telaamon debe estar cerca. Solo sigue el rastro de los cadáveres.', '', 25549),
(135493, 'esMX', 'Percibo a un aliado cerca.', '', 25549),
(135491, 'esMX', 'Allí está Baraat.', '', 25549),
(135490, 'esMX', 'Parece que no han encontrado a Velen... A pesar de que lo han intentado.', '', 25549),
(135489, 'esMX', 'Aún no han podido fortificar esta área.', '', 25549),
(135488, 'esMX', '¿Quién sigue?', '', 25549),
(135487, 'esMX', 'Un enemigo menos para combatir.', '', 25549),
(135485, 'esMX', 'La Luz prevalece.', '', 25549),
(135484, 'esMX', '¡Prueba mi espada, escoria demoníaca!', '', 25549),
(135483, 'esMX', 'No te interpondrás en mi camino.', '', 25549),
(135482, 'esMX', '¡Cae ante mí!', '', 25549),
(135481, 'esMX', '¡La Luz te doblegará!', '', 25549),
(135480, 'esMX', '¡Soy la espada de la Luz!', '', 25549),
(135479, 'esMX', '¡No puedes enfrentarte a la Luz!', '', 25549),
(135478, 'esMX', '¡Este será tu último día!', '', 25549),
(135477, 'esMX', '¡La Luz te rechaza, demonio!', '', 25549),
(135476, 'esMX', '', 'Rescata a mis hombres, Turalyon.', 25549),
(135475, 'esMX', 'Entonces no perdamos tiempo.', '', 25549),
(135474, 'esMX', '', 'Baraat disparó una bengala de señalización hace poco. Al menos está vivo. No he oído nada de los demás.', 25549),
(135473, 'esMX', 'Fareeya. ¿Cuál es la situación?', '', 25549),
(135470, 'esMX', 'Estas arenas han reclamado los huesos de muchos que vinieron en busca de poder. Asegúrense de que los demonios se agreguen a la colección.', '', 25549),
(135468, 'esMX', 'Estas arenas ocultan una fuente de poder ilimitado. Arrebátenselo a la Legión.', '', 25549),
(135467, 'esMX', 'Estas arenas ardientes ocultan fuentes de poder. Asegúrense de que la Legión no los controle.', '', 25549),
(135463, 'esMX', 'La Legión cree que estas islas están bajo su control. Muéstrenle a esta escoria que todo será nuestro.', '', 25549),
(135462, 'esMX', 'La Legión quiere quedarse con estas islas. Expúlsenlos.', '', 25549),
(135461, 'esMX', 'La Legión quiere controlar esta isla. Pongan fin a sus esfuerzos.', '', 25549),
(135460, 'esMX', 'Este mundo congelado ha reclamado los huesos de muchos que vinieron en busca de poder. Asegúrense de agregar a los demonios a la colección.', '', 25549),
(135459, 'esMX', 'Este mundo congelado contiene un poder peligroso. La Legión no debe controlarlo.', '', 25549),
(135458, 'esMX', 'Estos páramos helados ocultan un poder. Arrebátenselo a la Legión.', '', 25549),
(135454, 'esMX', 'La Legión quiere controlar este bosque. Aplástenlos.', '', 25549),
(135453, 'esMX', 'La Legión ha capturado estos bosques. Expúlsenlos.', '', 25549),
(135452, 'esMX', 'Estos demonios están arrasando con los recursos de este bosque. No podemos permitirlo.', '', 25549),
(135451, 'esMX', 'Estos tontos debieron huir cuando tenían la oportunidad. No dejen a nadie con vida.', '', 25549),
(135450, 'esMX', 'Esta es su oportunidad. ¡Terminen con la pelea!', '', 25549),
(135449, 'esMX', 'La Legión está furiosa por su asalto. ¡Extermínenlos!', '', 25549),
(135447, 'esMX', '¡Los han expulsado! ¡Ahora sigan con el ataque!', '', 25549),
(135438, 'esMX', 'Buena pelea, campeones. No importa dónde propaguen su corrupción, nosotros los detendremos.', '', 25549),
(135437, 'esMX', 'Han arrasado con sus filas. Estos demonios ya deben saber que no son el poder más grande del cosmos.', '', 25549),
(135436, 'esMX', 'Con cada victoria debilitamos la posición de la Legión en estos mundos.', '', 25549),
(135435, 'esMX', 'Bien hecho, campeones. Las noticias de esta victoria llegarán a la Gran oscuridad del más allá.', '', 25549),
(135434, 'esMX', 'Otra victoria, héroes. Pronto estos demonios no tendrán dónde esconderse.', '', 25549),
(135433, 'esMX', 'La Legión debe saber que siempre los derrotaremos, en cualquier reino.', '', 25549),
(135428, 'esMX', 'Quizás el pasado de este mundo nos ayude. Examinaré mi mente en busca de recuerdos.', '', 25549),
(135427, 'esMX', 'El alma de titán de Argus es la clave para derrotar a la Legión. Si nuestras defensas no resisten hasta que la destruyamos... Sargeras ganará.', '', 25549),
(135426, 'esMX', '', '¡Krona ki cristorr!', 25549),
(135425, 'esMX', '', 'Sirvo a la Luz.', 25549),
(135424, 'esMX', '', '¡Saludos, $gviajero:viajera;!', 25549),
(135423, 'esMX', '', 'En las noches más oscuras, nuestra esperanza resplandece.', 25549),
(135422, 'esMX', '¡Por favor, debes encontrar a nuestra capitana! Está al otro lado, en el oeste, defendiendo nuestras últimas baterías de artillería!', '¡Por favor, debes encontrar a nuestra capitana! Está al otro lado, en el oeste, defendiendo nuestras últimas baterías de artillería!', 25549),
(135421, 'esMX', '', 'Luchamos por una causa justa y un objetivo noble.', 25549),
(135420, 'esMX', '', 'Que la Luz te acompañe.', 25549),
(135419, 'esMX', '', 'Confía en la Luz.', 25549),
(135418, 'esMX', '', 'Acore palemos corta.', 25549),
(135417, 'esMX', '', 'Lucha con honor, $Gviajero:viajera;.', 25549),
(135416, 'esMX', '', 'Veremos caer a la Legión.', 25549),
(135415, 'esMX', '', 'Dioniss aca.', 25549),
(135414, 'esMX', 'Dioniss aca.', 'Dioniss aca.', 25549),
(135413, 'esMX', 'Veremos caer a la Legión.', 'Veremos caer a la Legión.', 25549),
(135412, 'esMX', 'Lucha con honor, $Gviajero:viajera;.', 'Lucha con honor, $Gviajero:viajera;.', 25549),
(135411, 'esMX', 'Acore palemos corta.', 'Acore palemos corta.', 25549),
(135410, 'esMX', 'Confía en la Luz.', 'Confía en la Luz.', 25549),
(135409, 'esMX', 'Que la Luz te acompañe.', 'Que la Luz te acompañe.', 25549),
(135408, 'esMX', 'Luchamos por una causa justa y un objetivo noble.', 'Luchamos por una causa justa y un objetivo noble.', 25549),
(135407, 'esMX', 'Pheta voros.', 'Pheta voros.', 25549),
(135406, 'esMX', 'Aun en la penumbra, la esperanza resplandece.', 'Aun en la penumbra, la esperanza resplandece.', 25549),
(135404, 'esMX', 'Regresaré al Vindicaar. Allí determinaré la ubicación del Blasón del conocimiento. Cuídate, $Gamigo mío:amiga mía;.', '', 25549),
(135403, 'esMX', '¡Saludos, $gviajero:viajera;!', '¡Saludos, $gviajero:viajera;!', 25549),
(135402, 'esMX', 'Sirvo a la Luz.', 'Sirvo a la Luz.', 25549),
(135401, 'esMX', '¡Krona ki cristorr!', '¡Krona ki cristorr!', 25549),
(135398, 'esMX', 'Ah, sí. Ha pasado mucho tiempo desde que humillé a un pupilo. Ven. Enfréntame.', '', 25549),
(135397, 'esMX', '', 'Creo que podrías hacerlo mejor.', 25549),
(135396, 'esMX', '', 'No olvides que tu desempeño es un reflejo de todos nosotros.', 25549),
(135395, 'esMX', 'No me impresionas.', '', 25549),
(135394, 'esMX', 'Tu arrogancia será tu fin.', '', 25549),
(135393, 'esMX', 'Sigue así y tal vez des una pelea digna.', '', 25549),
(135392, 'esMX', 'Hasta ahora tus esfuerzos han sido... insuficientes.', '', 25549),
(135391, 'esMX', 'Estos demonios quieren desangrar a una criatura que yace dormida bajo la superficie. Acaben con sus planes.', '', 25549),
(135390, 'esMX', 'La sed de sangre de la Legión es insaciable. Eliminen a esta escoria de este mundo.', '', 25549),
(135389, 'esMX', 'Tengo entendido que el poder proviene de lugares inusuales.', '', 25549),
(135329, 'esMX', '', 'El poder que controlan es inconmensurable. El Vindicaar no podrá resistir su embate.', 25549),
(135327, 'esMX', 'Bien hecho, héroes. Han expulsado a la Legión de este mundo.', '', 25549),
(135326, 'esMX', 'Entonces lo que Magni vio era verdad. Aggramar vive una vez más... al servicio de Sargeras.', '', 25549),
(135325, 'esMX', 'Han llamado la atención del comandante de la Legión. Derrótenlo, y los demás demonios huirán.', '', 25549),
(135324, 'esMX', 'El poder que hay aquí... ¡supera los límites que conocemos!', '', 25549),
(135323, 'esMX', 'Sin sus máquinas, la Legión no podrá drenar a esta criatura. Ahora ellos se desangrarán. ', '', 25549),
(135322, 'esMX', 'Jamás pensé que debería asesinar a un titán. Me apena, pero debemos hacer lo que sea necesario.', '', 25549),
(135321, 'esMX', '¡Deténganlas! ¡La magia de los titanes no debe caer en manos de la Legión!', '', 25549),
(135320, 'esMX', 'La Legión drena la sangre de una criatura colosal que duerme bajo la superficie. ¡Hay que detenerlos!', '', 25549),
(135319, 'esMX', 'El maestro de estas máquinas oculta su verdadera fuerza. No bajen la guardia.', '', 25549),
(135318, 'esMX', 'Armas, diseñadas para destruir fuerzas de un poder inimaginable. Es una pena que este poder no se haya usado con fines más productivos.', '', 25549),
(135317, 'esMX', 'La energía arcana se disipa y |4queda:quedan; $W13953 |4zona:zonas; más por desactivar.', 'La energía arcana se disipa y |4queda:quedan; $W13953 |4zona:zonas; más por desactivar.', 25549),
(135316, 'esMX', 'La energía vil se disipa y |4queda:quedan; $W13953 |4zona:zonas; más por desactivar.', 'La energía vil se disipa y |4queda:quedan; $W13953 |4zona:zonas; más por desactivar.', 25549),
(135315, 'esMX', 'La energía ígnea se disipa y |4queda:quedan; $W13953 |4zona:zonas; más por desactivar.', 'La energía ígnea se disipa y |4queda:quedan; $W13953 |4zona:zonas; más por desactivar.', 25549),
(135314, 'esMX', 'La energía corrompida se disipa y |4queda:quedan; $W13953 |4zona:zonas; más por desactivar.', 'La energía corrompida se disipa y |4queda:quedan; $W13953 |4zona:zonas; más por desactivar.', 25549),
(135313, 'esMX', 'Sé testigo del destino de los grandes creadores. Su único camino será el olvido.', '', 25549),
(135312, 'esMX', 'El poder de esta criatura... ¡es increíble! Tal vez podamos convertirla para que cumpla nuestras órdenes.', '', 25549),
(135311, 'esMX', 'Las hermanas tienen buena técnica, pero les falta el poder necesario para imponer su voluntad.', '', 25549),
(135310, 'esMX', 'Es una pena que se haya negado a rendirse ante sus superiores. Tenía tanto potencial.', '', 25549),
(135309, 'esMX', 'Estas armas han sido imbuidas con la esencia del caos. ¡Muy pronto las utilizaremos a nuestro favor!', '', 25549),
(135308, 'esMX', 'Observen las armas de la Legión. ¡Pronto, estarán a mi... digo... a nuestra disposición!', '', 25549),
(135307, 'esMX', 'Este ha sido una gran molestia para la Legión durante mucho tiempo. Nunca creí que seríamos aliados.', '', 25549),
(135306, 'esMX', 'Está interfiriendo con poderes que no comprende. Un paso en falso y la energía la consumirá.', '', 25549),
(135305, 'esMX', 'Esta criatura sí que es patética. Mira y aprende por qué tu voluntad siempre debe ser más fuerte que los poderes que controlas.', '', 25549),
(135304, 'esMX', 'Tiene la ambición, pero le falta talento.', '', 25549),
(135303, 'esMX', 'Subyuguen a esta cosa, sométanla a nuestra voluntad. Si no se rinde, destrúyanla.', '', 25549),
(135302, 'esMX', 'Esta ciudad supo ser la más grande de Argus. ¡Ahora mírala en ruinas! Las dinastías que antes eran poderosas ahora son simples peones de la Legión. Y muy pronto, también nos servirán.', '', 25549),
(135300, 'esMX', '¡Bien! Eso evitará que el enemigo envíe más refuerzos.', '', 25549),
(135299, 'esMX', 'Unos invocadores eredar están tratando de establecer nuevas estructuras en los Campos Destrozados. ¡Frustra sus planes y ayuda a nuestros soldados!', '', 25549),
(135298, 'esMX', '', 'Gracias. Estos cristales son valiosos ya que pueden adaptarse para fortalecer nuestras defensas.', 25549),
(135297, 'esMX', '', 'Nadie se acuerda de la logística y los suministros en medio de la batalla, pero son vitales para mantener nuestra posición. Recoge todo lo que puedas del campo de batalla para fortalecer nuestras defensas.', 25549),
(135296, 'esMX', '', 'Llegan demasiado tarde.', 25549),
(135295, 'esMX', '', 'Todo renacerá. ¡Todo será destruido!', 25549),
(135294, 'esMX', '', 'No interrumpirán el renacimiento. ¡Ellos volverán a la vida!', 25549),
(135293, 'esMX', '', 'Todos debemos aceptar el abismo inevitable.', 25549),
(135292, 'esMX', '', 'No pueden... entenderlo.', 25549),
(135291, 'esMX', '', 'Nuestra cruzada es el único camino hacia la redención. ¡Todo renacerá con las llamas del maestro!', 25549),
(135290, 'esMX', '¡Apunta el cañón hacia la nave de Kil''jaeden!', '', 25549),
(135289, 'esMX', '', '¿Acaso no lo ven? Sin la energía vil, ¡las sombras prevalecerán!', 25549),
(135288, 'esMX', 'Hogar, dulce hogar... Casi lo echo de menos.', '', 25549),
(135287, 'esMX', '', '¿Se atreven a poner un pie en estas pozas sagradas? ¡Sufran!', 25549),
(135285, 'esMX', '', 'La mayor parte de nuestro apoyo aéreo se perdió cuando el Xenedar se estrelló. Esos murciélagos habrían causado estragos en nuestras tropas terrestres.', 25549),
(135284, 'esMX', '', 'Los murciélagos invaden el campo de batalla de nuevo. ¡Ve a una de las baterías y derríbalos de los cielos!', 25549),
(135283, 'esMX', '', 'Excelente trabajo. Nuestros soldados están renovados, he cumplido con mi trabajo, ¡y los enemigos están debilitados! Todos salen ganando.', 25549),
(135282, 'esMX', '', 'Las tropas insisten en que me quede un tiempo a curar su heridas. Tendrás que encargarte de asesinar a mi enemigo.', 25549),
(135280, 'esMX', 'Todos los mundos caerán.', '', 25549),
(135279, 'esMX', 'Sargeras estará complacido.', '', 25549),
(135278, 'esMX', 'Vuelve al polvo.', '', 25549),
(135277, 'esMX', '¡Por Sargeras!', '', 25549),
(135276, 'esMX', '¡Caigan ante mi espada!', '', 25549),
(135275, 'esMX', 'Enemigo destruido.', '', 25549),
(135274, 'esMX', 'Amenaza eliminada.', '', 25549),
(135273, 'esMX', 'Exterminado.', '', 25549),
(135271, 'esMX', 'No quedan objetivos hostiles a la vista. Continuando patrulla.', '', 25549),
(135270, 'esMX', 'Guerreros enemigos neutralizados.', '', 25549),
(135269, 'esMX', 'Exterminación inminente...', '', 25549),
(135268, 'esMX', 'Núcleo de energía... defectuoso...', '', 25549),
(135267, 'esMX', 'Objetivos en la mira.', '', 25549),
(135266, 'esMX', 'Sistemas de supresión activados.', '', 25549),
(135262, 'esMX', 'El Paraxis se teletransporta.', 'El Paraxis se teletransporta.', 25549),
(135259, 'esMX', 'Mi muerte lo traerá a la vida...', 'Mi muerte lo traerá a la vida...', 25549),
(135258, 'esMX', 'No importa. Terminaré con esto.', 'No importa. Terminaré con esto.', 25549),
(135257, 'esMX', 'Ustedes se han aliado con los draenei traidores y su Luz, y sin embargo son tan débiles.', 'Ustedes se han aliado con los draenei traidores y su Luz, y sin embargo son tan débiles.', 25549),
(135256, 'esMX', 'Estoy ansioso por oír sus gritos de agonía resonando en estos salones.', 'No puedo esperar a oír sus gritos de agonía resonando en estos salones.', 25549),
(135255, 'esMX', 'Esta fortaleza es un mero eco de la grandeza de Antorus.', 'Esta fortaleza es un mero eco de la grandeza de Antorus.', 25549),
(135254, 'esMX', '¡El día nos pertenece! Te esperamos afuera, $p.', '', 25549),
(135253, 'esMX', 'La prueba de esta arma fue un éxito rotundo.', '', 25549),
(135252, 'esMX', '', 'Tal como pensaba. La corrupción del Vacío los ha seguido hasta aquí.', 25549),
(135251, 'esMX', '', 'Seguro que tuvo ayuda. Echa un vistazo. Llámame si encuentras algo interesante.', 25549),
(135250, 'esMX', 'Usaré sus huesos como piezas de repuesto.', '', 25549),
(135249, 'esMX', 'Soy un juguete... roto...', '', 25549),
(135248, 'esMX', 'Esto no estaba en las instrucciones...', '', 25549),
(135247, 'esMX', 'Hora de trabajar.', '', 25549),
(135246, 'esMX', 'Prepárense para ser desguazados.', '', 25549),
(135244, 'esMX', '', 'Quizá haya otro camino. Pero no me vendría mal un poco de ayuda.', 25549),
(135243, 'esMX', 'Es mucho peor de lo que temía. ¿Tenemos la fuerza para enfrentar a semejante enemigo?', '', 25549),
(135242, 'esMX', 'Su arrogancia será su fin.', 'Su arrogancia será su fin.', 25549),
(135241, 'esMX', '', 'Alto, Profeta. He explorado el área. Las sombras se han afianzado en Mac''Aree con más intensidad de la que imaginas.', 25549),
(135240, 'esMX', 'Vamos, debemos desafiar a la oscuridad.', '', 25549),
(135239, 'esMX', 'Al fin nuestro rol y el de la Legión se han invertido. ¡Que huyan ante nuestra invasión!', '', 25549),
(135238, 'esMX', 'Hasta la grieta más pequeña de una armadura permite que se deslice una cuchilla...', '', 25549),
(135237, 'esMX', 'Prosigue con la misión y yo distraeré sus fuerzas. Quizá me ayuden a prepararme para el verdadero desafío...', '', 25549),
(135236, 'esMX', '¿Cree que necesito ayuda? ¿Contra la Legión? Muy bien... Trata de seguirme el paso.', '', 25549),
(135235, 'esMX', 'El corazón palpitante de la Legión... Pronto lo haré pedazos.', '', 25549),
(135234, 'esMX', 'Los cambios en estos explosivos amplifican las energías viles. Los resultados deberían ser bastante... dramáticos.', '', 25549),
(135233, 'esMX', 'Por la Luz... ¿Qué le han hecho a mi mundo?', '', 25549),
(135232, 'esMX', 'La Legión ha invadido tu mundo. Ahora contempla el de ellos.', '', 25549),
(135231, 'esMX', 'Hemos llegado. Ahora atacaremos el corazón de la mismísima Legión.', '', 25549),
(135230, 'esMX', 'Debemos destruir esos cañones antes de atacar la ciudadela. Tu misión es vital, adalid.', '', 25549),
(135229, 'esMX', 'Nada de lo que hayas hecho tiene importancia, mortal. Somos infinitos. Somos la Legión.', 'Nada de lo que hayas hecho tiene importancia, mortal. Somos infinitos. Somos la Legión.', 25549),
(135228, 'esMX', 'Bríndales la ayuda que puedas. Alleria está al mando de las fuerzas allí y podrá dirigir tus esfuerzos.', '', 25549),
(135227, 'esMX', 'Lord Nath''raxas está en la cumbre más adelante. ¡Mátalo!', '', 25549),
(135223, 'esMX', 'La Legión ha reunido una fuerza considerable junto a esos cañones de asedio. Illidan ya debería estar allí, debilitando sus posiciones.', '', 25549),
(135222, 'esMX', 'A pesar de todo, debemos ser cautelosos. Debes encontrar un salvoconducto a la superficie para que sigamos con nuestro asalto.', '', 25549),
(135219, 'esMX', 'Estamos listos.', 'Estamos listos.', 25549),
(135218, 'esMX', '', '¿Todo listo para atacar?', 25549),
(135217, 'esMX', '¡Defiéndanse! ¡Esta incursión debe terminar aquí!', '¡Defiéndanse! ¡Esta incursión terminará aquí!', 25549),
(135216, 'esMX', 'El enemigo ha atravesado las puertas de la cumbre. ¡A las armas!', 'El enemigo ha atravesado las puertas de la cumbre. ¡A las armas!', 25549),
(135215, 'esMX', 'Sus gritos de angustia servirán como ejemplo para todos aquellos que se atrevan a asaltar a la Legión.', 'Sus gritos de angustia servirán como ejemplo para todos aquellos que se atrevan a asaltar a la Legión.', 25549),
(135214, 'esMX', '¡Se acercan naves de la Legión! ¡Cúbranse!', '¡Se acercan naves de la Legión! ¡Cúbranse!', 25549),
(135213, 'esMX', 'Prepárate para una gran resistencia. Nath''raxas no caerá sin pelear.', '', 25549),
(135212, 'esMX', 'Avanzaremos en la ciudadela por tierra mientras tú despejas el camino más adelante.', '', 25549),
(135211, 'esMX', 'Reunámonos en el patio central después de que haya caído. Buena suerte.', '', 25549),
(135210, 'esMX', 'Escuchen, ha llegado la hora de tomar la cumbre central. ¡Prepárense para la batalla!', '', 25549),
(135208, 'esMX', 'No nos precipitemos. Necesitamos poner a prueba los límites de tu nuevo poder. Ven.', '', 25549),
(135207, 'esMX', '', 'Parece que mi entrenamiento está completo.', 25549),
(135206, 'esMX', 'Me pediste que te enseñara a usar el Vacío como un arma. Ahora esa arma eres tú.', '', 25549),
(135205, 'esMX', '', 'Las voces son más fuertes. Más insistentes. Pero no me controlan.', 25549),
(135204, 'esMX', 'Has sobrevivido... ¡Qué interesante! ¿Cómo te sientes?', '', 25549),
(135203, 'esMX', 'Reclama su esencia, Alleria Brisaveloz. Incorpora su caos en tu ser.', '', 25549),
(135202, 'esMX', '', 'Aún derrotada, la naaru oscurecida rebosa de poder. Siento que las sombras me llaman.', 25549),
(135201, 'esMX', 'Estás a un paso de tu destino, Alleria. Deberás tomar decisiones... y aceptar las consecuencias.', '', 25549),
(135200, 'esMX', '', 'Siento el poder de la naaru caída. Me... llama.', 25549),
(135199, 'esMX', 'El Vacío es una fuerza de cambio... de transformación. Las sombras fluyen y mutan constantemente.', '', 25549),
(135198, 'esMX', '', '¿Cómo pudo un ser de la Luz convertirse en una criatura de las Sombras?', 25549),
(135197, 'esMX', 'Pero estas distracciones pueden esperar. Esta entidad debe morir.', '', 25549),
(135196, 'esMX', 'Es extraño que una naaru caiga en el Vacío de esta forma. En los pocos casos que conozco hubo mortales involucrados. Qué derivaciones tan fascinantes...', '', 25549),
(135195, 'esMX', '', 'Cuánto caos... Cuánta angustia. Nunca antes sentí algo así.', 25549),
(135194, 'esMX', '', 'Descubre sus motivos... Acaba con sus esfuerzos.', 25549),
(135193, 'esMX', '', 'Su llegada es de lo más oportuna, campeones. Los miembros de la Guardia de las Sombras están cerca y están corrompiendo a los nativos con energía del Vacío. Aunque desconozco su objetivo.', 25549),
(135192, 'esMX', '', 'Los exploradores están a salvo, gracias a tu ayuda.', 25549),
(135191, 'esMX', '', 'Envié exploradores para evaluar las fuerzas de la incursión de la Legión en Mac''Aree, pero no regresaron. Búscalos y ayúdalos, por favor... Si es que aún están vivos.', 25549),
(135186, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_CURSEOFTOUNGES.BLP:20|t¡El Paraxis comienza a |cFFFF0000|Hspell:249934|h[Purgar]|h|r a los enemigos a bordo!', '|TInterface\\Icons\\SPELL_SHADOW_CURSEOFTOUNGES.BLP:20|t¡El Paraxis comienza a |cFFFF0000|Hspell:249934|h[Purgar]|h|r a los enemigos a bordo!', 25549),
(135183, 'esMX', 'La energía arcana se concentra en torno a $n.', 'La energía arcana se concentra en torno a $n.', 25549),
(135182, 'esMX', 'La energía vil se concentra en torno a $n.', 'La energía vil se concentra en torno a $n.', 25549),
(135181, 'esMX', 'La energía ígnea se concentra en torno a $n.', 'La energía ígnea se concentra en torno a $n.', 25549),
(135180, 'esMX', 'La energía corrompida se concentra en torno a $n.', 'La energía corrompida se concentra en torno a $n.', 25549),
(135172, 'esMX', 'Yo abriré el camino después de que se encarguen de él.', '', 25549),
(135171, 'esMX', 'Si lo eliminamos, tendremos la oportunidad de entrar.', '', 25549),
(135170, 'esMX', 'Sí, esto servirá. Encontrarán al virrey cerca de la entrada del templo, tratando de entrar sin éxito.', '', 25549),
(135169, 'esMX', 'Gracias por eliminar los obstáculos que me separaban de este bastón, héroes.', '', 25549),
(135168, 'esMX', '', 'Avísenme cuando estén preparados, héroes, y comenzaremos el ataque.', 25549),
(135167, 'esMX', 'Si frustramos sus esfuerzos, todos nos beneficiaremos. Además, su comandante tiene un objeto especial que podría serme útil.', '', 25549),
(135166, 'esMX', '', 'La Guardia de las Sombras está fortaleciendo su posición cerca del templo.', 25549),
(135165, 'esMX', 'Es hora de devolverles el favor.', '', 25549),
(135164, 'esMX', '', 'Se volvería finito. ¡Quitarle la ventaja a la Legión nos daría la mejor oportunidad de salvar a Azeroth!', 25549),
(135163, 'esMX', 'Nuestras fuerzas están listas para atacar el Trono Ardiente, pero no podemos movernos hasta encontrar el espíritu de Eonar.', '', 25549),
(135162, 'esMX', 'Es hora de forjar nuestro propio camino, $gamigo mío:amiga mía;.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(135161, 'esMX', 'Este es el momento clave. Si activamos las defensas de la arena, la batalla habrá terminado.', '', 25549),
(135160, 'esMX', 'Este fragmento de alma me llama de nuevo, pero algo es diferente esta vez. No es Argus quien habla. Es... alguien más.', '', 25549),
(135159, 'esMX', 'Déjamelo a mí.', '', 25549),
(135158, 'esMX', 'Debemos encontrar su alma. Pero no sé cómo.', '', 25549),
(135157, 'esMX', '¡La Protectora! Por algún motivo, es la clave del plan de Sargeras.', '', 25549),
(135156, 'esMX', 'Qué bueno que hayas regresado. Algo ha... cambiado con la piedra.', '', 25549),
(135155, 'esMX', 'Debemos permitir que estos espíritus finalmente conozcan su libertad.', '', 25549),
(135154, 'esMX', 'Quizás la única forma de poner fin a su tormento sea terminar lo que empecé hace tanto tiempo.', '', 25549),
(135153, 'esMX', 'Tantos quedaron atrás... Permanecieron allí, obligados a revivir sus últimos momentos una y otra vez.', '', 25549),
(135152, 'esMX', 'Debiluchos. Les demostraré la gravedad de su error.', '', 25549),
(135151, 'esMX', 'Contempla la perfección. ¡Será la última dádiva que rechaces!', '', 25549),
(135150, 'esMX', '¿No quieres arrodillarte? ¡Entonces muere!', '', 25549),
(135149, 'esMX', '¡No mereces llamarte eredar!', '', 25549),
(135148, 'esMX', '¡Este es el poder que rechazaste!', '', 25549),
(135146, 'esMX', 'No soy el último. Los eredar... se alzarán...', '', 25549),
(135144, 'esMX', '|TInterface\\ICONS\\SPELL_SHADOW_PAINSPIKE:20|t¡Un Celador de la falla superior comienza a lanzar |cFFFF0000|Hspell:245164|h[Fragmento de desesperación]|h|r!', '', 25549),
(135143, 'esMX', 'Usando', 'Usando', 25549),
(135142, 'esMX', 'Mac''Aree... Esto es todo lo que queda.', '', 25549),
(135136, 'esMX', '', 'Su destino estaba en nuestra manos. ¡Pagarán por su insolencia, mortales!', 25549),
(135135, 'esMX', 'Un titán... ¡La Legión debe haber controlado el poder de su alma para regenerar sus ejércitos en el Vacío! Si lo destruimos, el ejército infinito...', '', 25549),
(135134, 'esMX', '', 'Suficiente. Que las sombras se apoderen de sus almas.', 25549),
(135133, 'esMX', '', 'La falta de fe será su perdición. La energía vil consumirá a los indignos.', 25549),
(135132, 'esMX', '', 'Tal vez el nathrezim ya se ha acostumbrado al tormento de las llamas, hermanas mías.', 25549),
(135131, 'esMX', '', '¡Los mortales flaquean!', 25549),
(135130, 'esMX', '', 'El prisionero se debilita. Está a punto de rendirse.', 25549),
(135129, 'esMX', '', '¡Patético! ¡Que ardan todos!', 25549),
(135128, 'esMX', '', 'No podemos permitir que este desgraciado saboree la victoria.', 25549),
(135127, 'esMX', '', '¡Observen cómo el toque helado de la desesperación acaba con su voluntad!', 25549),
(135126, 'esMX', '', '¡Observen! El pobre infeliz no puede con los mortales intrusos.', 25549),
(135125, 'esMX', '¡Arrrrraaaaagghhhh!', '', 25549),
(135124, 'esMX', '¡Los... mataré... a todos!', '', 25549),
(135123, 'esMX', '¡No pueden quebrarme!', '', 25549),
(135122, 'esMX', '¡Aaargg! ¡Brujas malditas!', '', 25549),
(135121, 'esMX', '¡Engendros de la agonía!', '', 25549),
(135120, 'esMX', '¡Contemplen la forma física del dolor!', '', 25549),
(135119, 'esMX', '¡Acepten el abrazo del dolor!', '', 25549),
(135118, 'esMX', '¡Compartan el sufrimiento!', '', 25549),
(135117, 'esMX', '¡Fuera!', '', 25549),
(135116, 'esMX', '¡Retrocede!', '', 25549),
(135115, 'esMX', '¡Ah, la agonía de las sombras!', '', 25549),
(135114, 'esMX', '¡El dolor acecha en la oscuridad!', '', 25549),
(135113, 'esMX', '¡Me pertenecen!', '', 25549),
(135112, 'esMX', '¡Presas fáciles!', '', 25549),
(135111, 'esMX', 'No importa. No logran ver la oscuridad que los rodea.', '', 25549),
(135110, 'esMX', 'Díganme... cuando se apoderó de su trono de pellejos y huesos, ¿se vieron obligados a jurar lealtad? No... Estoy seguro de que se entregaron voluntariamente... o al menos eso creyeron.', '', 25549),
(135109, 'esMX', 'Ah, finalmente ella me encontró. Envió a sus súbditos a terminar el trabajo.', '', 25549),
(135108, 'esMX', 'No importa. No son capaces de ver la oscuridad que se cierne sobre ustedes.', '', 25549),
(135107, 'esMX', 'Cuando la traición tiña de rojo sus tronos... Cuando sus sitios sagrados ardan y la máscara destruida cuelgue sobre su fogata... Solo entonces lo entenderán. Y será demasiado tarde.', '', 25549),
(135106, 'esMX', 'Así que su Alianza aún perdura. Bien, duró más de lo que esperaba, aunque ella ya ha plantado las semillas de su debacle. Es muy paciente.', '', 25549),
(135105, 'esMX', '¡Contemplen el poder de los nathrezim!', '', 25549),
(135104, 'esMX', '¡Es hora de acabar con todo esto!', '', 25549),
(135103, 'esMX', '¡Débiles! Se quiebran ante una pizca del dolor que he sufrido.', '', 25549),
(135102, 'esMX', '¡Debilucho patético!', '', 25549),
(135101, 'esMX', '¿Eso es todo lo que puedes soportar?', '', 25549),
(135100, 'esMX', 'Su tormento... apenas... ha comenzado.', '', 25549),
(135099, 'esMX', '¡Desenvainen sus armas! ¡Les mostraré un dolor inimaginable!', '', 25549),
(135098, 'esMX', '', '¡Hemos intentado durante mucho tiempo entrar a este reino! Y pensar que debemos agradecerle a $Gun mortal:una mortal; la posibilidad de establecer nuestra posición aquí. ¡Tu servicio será recordado!', 25549),
(135097, 'esMX', '', 'Esta criatura podría servir a nuestra causa. Tal vez aún podamos convertirla.', 25549),
(135096, 'esMX', '', 'Estas farsantes creen que los susurros enloquecedores son juegos de niños. ¡Novatas! Les demostraré cómo lo hacen las profesionales.', 25549),
(135095, 'esMX', '', 'Qué desilusión. Se alió con el lado equivocado y desperdició todo su potencial.', 25549),
(135094, 'esMX', '', 'Imagina esta maquinaria imbuida con nuestro poder. Sería muy interesante...', 25549),
(135093, 'esMX', '', 'Tanto esfuerzo y tantas amenazas, solo para demorar la victoria inevitable de sus superiores.', 25549),
(135092, 'esMX', '', '¡Esto sí que es una belleza! Al menos uno de estos mortales puede apreciar lo que ofrece.', 25549),
(135091, 'esMX', '', 'Yo disfruto de una saludable sed de poder, pero este se desespera como un principiante.', 25549),
(135090, 'esMX', '', 'Contempla cómo una mente débil se entrega a la oscuridad.', 25549),
(135089, 'esMX', '', 'Se jacta de desafiar a las sombras. La arrogancia será su fin.', 25549),
(135088, 'esMX', '', 'La oruga se ha convertido en mariposa. Ahora está fuera de nuestras manos.', 25549),
(135087, 'esMX', '', 'Parece prometedora. Los susurros la atraen a su destino.', 25549),
(135086, 'esMX', '', '¿Lo sientes en el aire? ¿El dulce néctar de la locura? Mmm... Lo inunda todo.', 25549),
(135085, 'esMX', '', 'Tanto potencial... malgastado en una cruzada que estaba condenada al fracaso.', 25549),
(135058, 'esMX', '¡Alto!', '', 25549),
(135027, 'esMX', 'Solo espero que no sea tarde.', '', 25549),
(135026, 'esMX', 'Así se hará. Haremos todo lo posible para que Eonar no caiga como los demás.', '', 25549),
(135023, 'esMX', '¡Sargeras está creando algo así como un Panteón oscuro! ¡Debemos encontrar el espíritu de Eonar antes que Aggramar!', '', 25549),
(135022, 'esMX', '<Coloca tu mano sobre la piedra.>', '<Coloca tu mano sobre la piedra.>', 25549),
(135021, 'esMX', 'La piedra resuena con energía.', '', 25549),
(135020, 'esMX', 'Apoya la mano en la piedra cuando estés $Glisto:lista;.', '', 25549),
(135019, 'esMX', 'Siento que el alma de Argus me llama de nuevo. Está frenético, desesperado... y triste, tan triste. ¡Me rompe el corazón!', '', 25549),
(135017, 'esMX', 'El enano de diamantes te espera en la cámara de descanso de la piedra. Está... perturbado.', '', 25549),
(135016, 'esMX', 'Que la Luz te guíe hasta Magni. Espero que tenga buenas noticias.', '', 25549),
(135015, 'esMX', '¡Han superado su vida útil!', '', 25549),
(135014, 'esMX', 'Parece que aún necesita algunos ajustes.', '', 25549),
(135013, 'esMX', '¡Tendrán el honor de ser los sujetos de prueba de mi más reciente invención!', '', 25549),
(135012, 'esMX', '¡Los convertiré en cenizas!', '', 25549),
(135011, 'esMX', '¡Mueran!', '', 25549),
(135010, 'esMX', '¡Contemplen el verdadero poder!', '', 25549),
(135008, 'esMX', '¡No hay escapatoria!', '', 25549),
(135007, 'esMX', 'Veamos qué tan rápido pueden correr.', '', 25549),
(135006, 'esMX', 'Permítanme mostrarles mi más reciente creación.', '', 25549),
(135005, 'esMX', '¡Envíen al siguiente sujeto de prueba!', '', 25549),
(135004, 'esMX', 'Será imposible reensamblarte.', '', 25549),
(134981, 'esMX', 'Muchos dieron sus vidas para proteger este territorio. ¡Honra su sacrificio y expulsa a estos demonios hacia el abismo!', 'Muchos dieron sus vidas para proteger este territorio. ¡Honra su sacrificio y expulsa a estos demonios hacia el abismo!', 25549),
(134928, 'esMX', 'Reunámonos en el Vindicaar para preparar el ataque final.', '', 25549),
(134926, 'esMX', 'Pero esta batalla aún no ha terminado. Un gran poder ruge atormentado en el núcleo de este mundo.', '', 25549),
(134920, 'esMX', 'El Trono Ardiente', 'El Trono Ardiente', 25549),
(134919, 'esMX', 'Riscos Tábidos', 'Riscos Tábidos', 25549),
(134918, 'esMX', '', '¡Yo controlo el poder del cosmos!', 25549),
(134917, 'esMX', '', 'Mi esencia... regresa... al Vacío.', 25549),
(134916, 'esMX', '', 'He recorrido todo el espacio interestelar. ¿De verdad creían que podían vencerme?', 25549),
(134915, 'esMX', '', 'Su vida fue insignificante.', 25549),
(134914, 'esMX', '', 'Su fe no bastará.', 25549),
(134913, 'esMX', 'Sumidero Vil', 'Sumidero Vil', 25549),
(134912, 'esMX', 'El Vindicaar aguarda tus órdenes, $n. ¿Dónde atacaremos ahora?', 'El Vindicaar aguarda tus órdenes, $n. ¿Dónde atacaremos ahora?', 25549),
(134903, 'esMX', '', '¿Quién osa profanar esta armería sagrada?', 25549),
(134902, 'esMX', '', '¡Muerte a los man''ari!', 25549),
(134901, 'esMX', '', '¡No! No puedo fallar...', 25549),
(134900, 'esMX', '', '¡Los man''ari nunca profanarán la armadura!', 25549),
(134892, 'esMX', 'He calculado tus probabilidades de supervivencia: ¡cero!', '', 25549),
(134889, 'esMX', '¡Mira por dónde caminas!', '', 25549),
(134888, 'esMX', 'Espero que disfrutes de mis inventos.', '', 25549),
(134887, 'esMX', 'Legión, ¡demuéstrenles a estos debiluchos por qué somos la fuerza dominante del cosmos!', '', 25549),
(134886, 'esMX', '¡Que no quede nadie con vida!', '', 25549),
(134885, 'esMX', '¡Demonios! ¡Ataquen!', '', 25549),
(134884, 'esMX', '', 'Cañones, ¡empiecen a disparar a mi señal!', 25549),
(134883, 'esMX', '¡Parece que esta situación amerita un enfoque más práctico!', '', 25549),
(134882, 'esMX', '', '¿Por qué dejar que mis naves los destrocen cuando puedo hacerlo yo misma?', 25549),
(134881, 'esMX', '¡No puedo resistir el llamado de la batalla!', '', 25549),
(134880, 'esMX', '¡Ya me cansé de este trabajo! Será más divertido ver cómo mis máquinas los hacen pedazos.', '', 25549),
(134879, 'esMX', '', '¡Todas las naves, converjan en mi posición!', 25549),
(134878, 'esMX', '¡Es hora de que mis peones acaben con ustedes!', '', 25549),
(134870, 'esMX', 'Detrás de estas puertas yace el corazón de la máquina de guerra de la Legión. Eliminemos esta amenaza y diezmemos el arsenal de los demonios.', '', 25549),
(134868, 'esMX', 'Hasta aquí llegaron, escorias mortales. Hay un precio por sus cabezas y pretendo cobrar la recompensa.', '', 25549),
(134840, 'esMX', 'Dieron sus vidas por esta guerra. Debemos honrar su sacrificio.', 'Dieron sus vidas por esta guerra. Debemos honrar su sacrificio.', 25549),
(134839, 'esMX', 'No queda nada por hacer, comandante. Ahora están en manos de la Luz.', 'No queda nada por hacer, comandante. Ahora están en manos de la Luz.', 25549),
(134821, 'esMX', '', 'Si Sargeras los subyuga como a Aggramar, ningún poder de este universo lo detendrá.', 25549),
(134798, 'esMX', 'Un orbe de energía arcana yace en el terreno cerca de $n.', 'Un orbe de energía arcana yace en el terreno cerca de $n.', 25549),
(134797, 'esMX', 'Un orbe de energía vil yace en el terreno cerca de $n.', 'Un orbe de energía vil yace en el terreno cerca de $n.', 25549),
(134796, 'esMX', 'Un orbe de energía ígnea yace en el terreno cerca de $n.', 'Un orbe de energía ígnea yace en el terreno cerca de $n.', 25549),
(134795, 'esMX', 'Un orbe de energía corrompida yace en el terreno cerca de $n.', 'Un orbe de energía corrompida yace en el terreno cerca de $n.', 25549),
(134791, 'esMX', 'Parece que mi empleador sobrestimó su capacidad. En fin, ¿quién soy para cuestionar la paga?', '', 25549),
(134788, 'esMX', 'Dinero fácil y rápido.', '', 25549),
(134787, 'esMX', '¡Casi no quedó nada para recolectar!', '', 25549),
(134785, 'esMX', '¡Ja! ¡Has caído ante el mejor!', '', 25549),
(134780, 'esMX', 'Sus huesos serán mi mejor recompensa.', '', 25549),
(134779, 'esMX', 'Creo que conservaré algunas partes como trofeo.', '', 25549),
(134744, 'esMX', 'Vaya, vaya. Los estaba esperando. Siempre necesito sujetos de prueba, ¡y ustedes serán un especimen perfecto!', '', 25549),
(134742, 'esMX', 'La Legión está agonizando. Es hora de estrangularlos. Regresen al Vindicaar y prepárense para asestar el golpe final.', '', 25549),
(134738, 'esMX', 'De acuerdo. Debemos acabar con esas máquinas de destrucción infernales. Adalides, utilicen este teletransportador para abordar el Vindicaar. ¡Vamos hacia nuestro siguiente objetivo!', '', 25549),
(134737, 'esMX', 'Atacar el corazón de la Legión es inútil si no destruimos sus máquinas de guerra. Si no nos encargamos, pronto acabarán con nosotros.', '', 25549),
(134736, 'esMX', '¡Sargeras quiere corromper a los otros titanes! Si no lo detenemos, el Panteón renacerá en la oscuridad. ¡No hay tiempo que perder!', '', 25549),
(134735, 'esMX', 'Bien hecho, campeones. Por primera vez en milenios, los habitantes del Trono ardiente han sufrido un golpe severo.', '', 25549),
(134734, 'esMX', '', 'No lucharás solo, Turalyon. Los demonios pagarán por sus actos... con su sangre.', 25549),
(134733, 'esMX', 'Las filas de la Legión se desmoronan pero aún nos superan en número. Mis fuerzas las mantendrán entretenidas aquí.', '', 25549),
(134732, 'esMX', '', 'Libérenlos, campeones, o su lucha habrá sido en vano.', 25549),
(134731, 'esMX', '', 'Los gritos atormentados del Panteón resuenan desde las profundidades de Argus.', 25549),
(134730, 'esMX', '¡Es Eonar, la Protectora! Este portal lleva a su santuario. Vayan. ¡Yo me quedaré y cuidaré sus espaldas!', '', 25549),
(134724, 'esMX', '', 'Escúchenme, campeones. La Legión se ha infiltrado en mi santuario, y pronto devastarán mis defensas. Bríndenme su apoyo, o Sargeras reclamará su premio.', 25549),
(134723, 'esMX', '¡Campeones! Oí una voz familiar que me llamaba, así que me abrí paso a golpes hasta este lugar maldito.', '', 25549),
(134721, 'esMX', 'Al fin el consejo de guerra ha pagado por su traición. Sin su liderazgo, la Legión caerá en el caos.', '', 25549),
(134720, 'esMX', 'Traicionaron todo lo que representaban cuando aceptaron ese pacto. La redención no es posible... solo queda el castigo.', '', 25549),
(134719, 'esMX', 'Reconozco los estandartes de los generales al mando de las fuerzas de la Legión. Antes de que Sargeras se apoderara de nuestro mundo, ellos reunieron a nuestros ejércitos y pacificaron Argus.', '', 25549),
(134718, 'esMX', 'Dos demonios menos. Pero muchos más requieren la atención de sus cuchillas.', '', 25549),
(134717, 'esMX', 'Sargeras nos dejó algunas de sus mascotas favoritas para que juguemos. Erradiquen a estas abominaciones del campo de batalla.', '', 25549),
(134716, 'esMX', 'Sin los portales, la Legión no puede llamar refuerzos. ¡Es el momento de atacar!', '', 25549),
(134714, 'esMX', 'Un cristal cercano crepita con energía arcana.', 'Un cristal cercano crepita con energía arcana.', 25549),
(134713, 'esMX', 'La energía vil recorre un cristal cercano.', 'La energía vil recorre un cristal cercano.', 25549),
(134712, 'esMX', 'Un cristal cercano arde con energía ígnea.', 'Un cristal cercano arde con energía ígnea.', 25549),
(134711, 'esMX', 'La energía corrompida infecta un cristal cercano.', 'La energía corrompida infecta un cristal cercano.', 25549),
(134709, 'esMX', '|TInterface\\Icons\\PRIEST_ICON_CHAKRA_BLUE.BLP:20|tEnergías arcanas crepitan a tu alrededor.', '|TInterface\\Icons\\PRIEST_ICON_CHAKRA_BLUE.BLP:20|tEnergías arcanas crepitan a tu alrededor.', 25549),
(134708, 'esMX', '|TInterface\\Icons\\PRIEST_ICON_CHAKRA_GREEN.BLP:20|tEnergía vil recorre tu cuerpo.', '|TInterface\\Icons\\PRIEST_ICON_CHAKRA_GREEN.BLP:20|tEnergía vil recorre tu cuerpo.', 25549),
(134707, 'esMX', '|TInterface\\Icons\\PRIEST_ICON_CHAKRA_RED.BLP:20|tEnergía ígnea corre por tus venas.', '|TInterface\\Icons\\PRIEST_ICON_CHAKRA_RED.BLP:20|tEnergía ígnea corre por tus venas.', 25549),
(134706, 'esMX', '|TInterface\\Icons\\PRIEST_ICON_CHAKRA.BLP:20|tUna energía corrompida te infecta.', '|TInterface\\Icons\\PRIEST_ICON_CHAKRA.BLP:20|tUna energía corrompida te infecta.', 25549),
(134705, 'esMX', 'Si la Legión está utilizando ese núcleo para traer refuerzos, debemos destruirlo antes de que sus filas nos superen.', '', 25549),
(134704, 'esMX', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_05.BLP:20|t¡El Paraxis carga sus armas para provocar la |cFFFF0000|Hspell:249121|h[Fatalidad devastadora]|h|r de Eonar!', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_05.BLP:20|t¡El Paraxis carga sus armas para provocar la |cFFFF0000|Hspell:249121|h[Fatalidad devastadora]|h|r de Eonar!', 25549),
(134703, 'esMX', 'Adalides, siento una perturbación cerca de ustedes. Es una sensación que no experimentaba desde la apertura del Portal Oscuro.', '', 25549),
(134702, 'esMX', '', 'Usen mis portales para llevar la batalla al enemigo. ¡Apúrense!', 25549),
(134701, 'esMX', 'Nuestras fuerzas se mueven hacia el alto mando de la Legión. Consíguenos todo el tiempo que puedas, Alleria.', '', 25549),
(134700, 'esMX', '', 'Turalyon, he comenzado mi asalto sobre el frente norte. Mantendré a sus fuerzas ocupadas para que puedas alcanzar a los objetivos prioritarios.', 25549),
(134694, 'esMX', 'Cuando las cumbres no sean un obstáculo, haremos nuestra jugada.', '', 25549),
(134692, 'esMX', '¡Adalides, derriben a esa monstruosidad!', '', 25549),
(134691, 'esMX', '¡Templeluz, retrocedan!', '', 25549),
(134690, 'esMX', '¡Estamos ganando terreno! ¡Sigan atacando!', '', 25549),
(134689, 'esMX', 'Te daré una pista: es una palabra de poder antigua. Si te la susurro al oído, enloquecerás. ¿Todavía te interesa?', '', 25549),
(134688, 'esMX', 'Si quieres ver cómo la realidad misma se destruye en mil pedazos, sigue preguntando por mi nombre.', '', 25549),
(134687, 'esMX', 'Si lo dijera en voz alta, se abrirían miles de portales del vacío para dar paso a ciertas entidades no muy agradables que buscan cobrarse algunas deudas del pasado.', '', 25549),
(134686, 'esMX', 'Sí, por supuesto que tengo un nombre "real". Pero no es de tu incumbencia.', '', 25549),
(134685, 'esMX', 'Cuidado. Controlo poderes que van más allá de tu comprensión.', '', 25549),
(134684, 'esMX', '', 'Hazlos sufrir.', 25549),
(134683, 'esMX', 'Adalides, nosotros nos encargaremos de mantener ocupadas a estas bestias aladas mientras ustedes abren camino.', '', 25549),
(134682, 'esMX', 'No te fallaremos, Profeta.', '', 25549),
(134681, 'esMX', 'El Vindicaar atraerá todos los ataques posibles, Turalyon, pero no podemos resistir mucho. ¡Debes destruir sus defensas!', '', 25549),
(134680, 'esMX', '¡Templeluz, aseguren esta posición!', '', 25549),
(134679, 'esMX', '¡Hemos atravesado el muro!', '', 25549),
(134677, 'esMX', 'Tengo tus coordenadas, adalid. Nos tomará algo de tiempo calibrar las matrices de teletransportación. ¡Asegúrate de que la Legión no le ponga las manos encima hasta entonces!', '', 25549),
(134662, 'esMX', 'Recuerda, número par de facetas, sin impurezas. ¡Debe ser así!', '', 25549),
(134660, 'esMX', 'Que la Legión caiga a tus pies.', '', 25549),
(134659, 'esMX', 'Resistiremos.', '', 25549),
(134658, 'esMX', 'El Vindicaar está a tus órdenes.', '', 25549),
(134657, 'esMX', 'Este es nuestro momento, $Ghéroe:heroína;.', '', 25549),
(134655, 'esMX', 'Vamos, habla conmigo.', '', 25549),
(134654, 'esMX', '', 'Haré que el vacío te consuma... si me lo pides de buena manera.', 25549),
(134653, 'esMX', 'Te ofrezco mi fuerza.', '', 25549),
(134645, 'esMX', '', 'Las relaciones entre hermanas son complicadas. Especialmente cuando una es no-muerta.', 25549),
(134644, 'esMX', '', 'Estuve desaparecida durante años, no toleraré que me trates de esta forma.', 25549),
(134643, 'esMX', '', 'Estuve desaparecida durante años, no toleraré que me trates de esta forma.', 25549),
(134642, 'esMX', 'Sus filas empiezan a debilitarse. ¡Debemos atacar ahora!.', '', 25549),
(134641, 'esMX', '¡Ahora seremos nosotros quienes los extingan!', '', 25549),
(134640, 'esMX', 'Los demonios llegaron a nuestro mundo con el único deseo de extinguir todo rastro de vida.', '', 25549),
(134636, 'esMX', 'Archimonde aprendió a hacer esto cuando era un acólito. ¿Cuán difícil puede ser?', '', 25549),
(134635, 'esMX', 'A este paso nunca me convertiré en archicónsul.', '', 25549),
(134634, 'esMX', 'Tal vez debí hacerles caso a mis padres y convertirme en joyero...', '', 25549),
(134628, 'esMX', '', 'Tal vez sería mejor que discutiéramos esto en privado.', 25549),
(134627, 'esMX', 'Krono-ka lith''tor agnos... ¿o era it lith''nos agtor? ¡Bah! ¡Nunca podré memorizar este hechizo!', '', 25549),
(134626, 'esMX', 'Debí haber empezado a estudiar antes.', '', 25549),
(134625, 'esMX', 'Tal vez si invierto la matriz central para expulsar... Alto, no. Así es como se producen las explosiones.', '', 25549),
(134623, 'esMX', '¿Acaso tenía que energizar la proyección antes de estabilizar la efusión? Oh...', '', 25549),
(134612, 'esMX', 'Estará listo, Alto exarca. Tiene mi palabra.', '', 25549),
(134611, 'esMX', 'No pondré en riesgo las vidas de nuestras fuerzas sin la protección del engranaje bélico.', '', 25549),
(134609, 'esMX', '', 'Si fallamos, perderán sus vidas. ¡Aseguren Mac''Aree!', 25549),
(134608, 'esMX', '', '¡Antorus exige su premio! ¡Mac''Aree será nuestro!', 25549),
(134607, 'esMX', '', '¡Podrán descansar cuando esta roca sea nuestra!', 25549),
(134606, 'esMX', '', '¡Dupliquen sus esfuerzos! Esta tierra lleva mucho tiempo sin dar frutos.', 25549),
(134605, 'esMX', '', 'Vuelvan al trabajo... ¡O conocerán el látigo!', 25549),
(134604, 'esMX', '', 'Los ojos de Antorus los vigilan. ¡Encuentren al Profeta o sufran las consecuencias!', 25549),
(134603, 'esMX', '', '¡La recompensa del fracaso será el tormento! ¡El Profeta no debe escapar!', 25549),
(134602, 'esMX', '', 'Busquen por todas partes. ¡Encuéntrenlo!', 25549),
(134601, 'esMX', '', '¡Recuerden mis palabras! ¡Velen no debe escapar!', 25549),
(134600, 'esMX', '', '¡Busquen al Profeta! ¡Maten a sus aliados!', 25549),
(134579, 'esMX', 'Tu cobardía te delata. Nunca nos detendremos...', '', 25549),
(134578, 'esMX', 'El Destructor te encontrará...', '', 25549),
(134577, 'esMX', 'Nunca nos detendremos...', 'Nunca nos detendremos...', 25549),
(134576, 'esMX', 'El Destructor te encontrará...', 'El Destructor te encontrará...', 25549),
(134575, 'esMX', 'Tu cobardía te delata. Nunca nos detendremos...', '', 25549),
(134574, 'esMX', 'El Destructor te encontrará...', '', 25549),
(134573, 'esMX', 'El Destructor te encontrará...', 'El Destructor te encontrará...', 25549),
(134572, 'esMX', '', 'Por supuesto que era tu turno. Nunca dudes de la memoria de una elfa... ni siquiera después de mil años.', 25549),
(134571, 'esMX', 'Nunca nos detendremos...', 'Nunca nos detendremos...', 25549),
(134570, 'esMX', 'Bueno, no estoy tan seguro...', '', 25549),
(134569, 'esMX', '¡Están usando la maestría en el tiempo de Aman''thul contra ustedes!  ', '', 25549),
(134568, 'esMX', 'Estoy de acuerdo. Ha pasado mucho tiempo pero, si no me equivoco, esta vez te tocaba a ti pagar los tragos, Khadgar.', '', 25549),
(134567, 'esMX', '¡No hay escapatoria!', '', 25549),
(134566, 'esMX', '¡Pagarás por tu cobardía!', '', 25549),
(134565, 'esMX', '¡No hay escapatoria!', '¡No hay escapatoria!', 25549),
(134564, 'esMX', '¡Pagarás por tu cobardía!', '¡Pagarás por tu cobardía!', 25549),
(134563, 'esMX', '¡No hay escapatoria!', '', 25549),
(134562, 'esMX', '¡Pagarás por tu cobardía!', '', 25549),
(134561, 'esMX', '¡Pagarás por tu cobardía!', '¡Pagarás por tu cobardía!', 25549),
(134560, 'esMX', 'Así es. Aunque no los veo tanto como me gustaría. ¡Cuando dejemos todo esto atrás, tal vez los Hijos de Lothar podríamos reunirnos para celebrar!', '', 25549),
(134559, 'esMX', '¡No hay escapatoria!', '¡No hay escapatoria!', 25549),
(134558, 'esMX', '', '¡Argus conocerá tu dolor!', 25549),
(134557, 'esMX', '', '¿Kurdran y Danath están a salvo también?', 25549),
(134556, 'esMX', '', '¡Más almas para la energía vil!', 25549),
(134555, 'esMX', 'También nos preocupamos por ti, Khadgar. Aunque creo que una parte de mí sabía que se necesita mucho más que la explosión de un planeta para vencerte.', '', 25549),
(134554, 'esMX', '', 'Te precipitas a tu muerte. Permíteme ayudarte.', 25549),
(134553, 'esMX', 'Es bueno volver a verlos, amigos. Después del exterminio de Draenor, no podía encontrarlos y no sabía qué pensar.', '', 25549),
(134552, 'esMX', '¡Déjanos en paz!', '', 25549),
(134551, 'esMX', '¡No eres $Gbienvenido:bienvenida; aquí!', '', 25549),
(134550, 'esMX', '¡Déjanos en paz!', '¡Déjanos en paz!', 25549),
(134549, 'esMX', '¡No eres $Gbienvenido:bienvenida; aquí!', '¡No eres $Gbienvenido:bienvenida; aquí!', 25549),
(134548, 'esMX', '¡Déjanos en paz!', '¡Déjanos en paz!', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(134547, 'esMX', '¡No eres $Gbienvenido:bienvenida; aquí!', '¡No eres $Gbienvenido:bienvenida; aquí!', 25549),
(134546, 'esMX', '', '¡No eres $Gbienvenido:bienvenida; aquí!', 25549),
(134545, 'esMX', '', '¡Déjanos en paz!', 25549),
(134544, 'esMX', 'Golganneth... ¡está perdido en una tormenta de agonía!', '', 25549),
(134543, 'esMX', '¡Están haciendo pedazos la mente de Norgannon!', '', 25549),
(134542, 'esMX', '', 'Esperé tanto tiempo...', 25549),
(134541, 'esMX', '', '¿Esto es... todo?', 25549),
(134540, 'esMX', 'Esperé tanto tiempo...', 'Esperé tanto tiempo...', 25549),
(134539, 'esMX', '¿Esto es... todo?', '¿Esto es... todo?', 25549),
(134538, 'esMX', 'Esperé tanto tiempo...', 'Esperé tanto tiempo...', 25549),
(134537, 'esMX', '¿Esto es... todo?', '¿Esto es... todo?', 25549),
(134536, 'esMX', '¿Esto es... todo?', '', 25549),
(134535, 'esMX', 'Esperé tanto tiempo...', '', 25549),
(134534, 'esMX', 'Estoy tan cansado.', 'Estoy tan cansada.', 25549),
(134533, 'esMX', 'Esta oscuridad... Creí que...', 'Esta oscuridad... Creí que...', 25549),
(134532, 'esMX', 'Velen... ¿por qué?', 'Velen... ¿por qué?', 25549),
(134531, 'esMX', 'No podíamos escapar.', 'No podíamos escapar.', 25549),
(134530, 'esMX', 'Debí haber... huido...', 'Debí haber... huido...', 25549),
(134529, 'esMX', '¿Cuándo terminará esto?', '¿Cuándo terminará esto?', 25549),
(134528, 'esMX', '¿Cuándo terminará esto?', '', 25549),
(134527, 'esMX', 'Debí haber... huido...', '', 25549),
(134526, 'esMX', 'No podíamos escapar.', '', 25549),
(134525, 'esMX', 'Velen... ¿por qué?', '', 25549),
(134524, 'esMX', 'Esta oscuridad... Creí que...', '', 25549),
(134523, 'esMX', 'Estoy tan cansado.', '', 25549),
(134522, 'esMX', '¡No me atormentarás!', '¡No me atormentarás!', 25549),
(134521, 'esMX', '¿Por qué no nos dejas descansar?', '¿Por qué no nos dejas descansar?', 25549),
(134520, 'esMX', '¡Este es nuestro hogar! ¡Lárgate!', '¡Este es nuestro hogar! ¡Lárgate!', 25549),
(134519, 'esMX', '¡No te burles de mi sufrimiento!', '¡No te burles de mi sufrimiento!', 25549),
(134518, 'esMX', '¡No deberías estar aquí!', '¡No deberías estar aquí!', 25549),
(134517, 'esMX', '¿Por qué has venido?', '¿Por qué has venido?', 25549),
(134516, 'esMX', '¿Por qué has venido?', '', 25549),
(134515, 'esMX', '¡No deberías estar aquí!', '', 25549),
(134514, 'esMX', '¡No te burles de mi sufrimiento!', '', 25549),
(134513, 'esMX', '¡Este es nuestro hogar! ¡Lárgate!', '', 25549),
(134512, 'esMX', '¿Por qué no nos dejas descansar?', '', 25549),
(134511, 'esMX', '¡No me atormentarás!', '', 25549),
(134510, 'esMX', '¡Esta será la última dádiva que rechaces!', '¡Esta será la última dádiva que rechaces!', 25549),
(134509, 'esMX', '¡Nadie detendrá a Sargeras!', '¡Nadie detendrá a Sargeras!', 25549),
(134508, 'esMX', '¡Acepta a Sargeras!', '¡Acepta a Sargeras!', 25549),
(134507, 'esMX', '¡Sí! ¡Huye! ¡Huye!', '¡Sí! ¡Huye! ¡Huye!', 25549),
(134506, 'esMX', '¡Huye al abismo, cobarde!', '¡Huye al abismo, cobarde!', 25549),
(134505, 'esMX', '¡Sufre por tu necedad!', '¡Sufre por tu necedad!', 25549),
(134504, 'esMX', '¡Nadie detendrá a Sargeras!', '', 25549),
(134503, 'esMX', '¡Esta será la última dádiva que rechaces!', '', 25549),
(134502, 'esMX', 'Están corrompiendo la voluntad de Khaz''goroth. ¡No puede controlar sus llamas!', '', 25549),
(134501, 'esMX', '¡Sufre por tu necedad!', '', 25549),
(134500, 'esMX', '¡Huye al abismo, cobarde!', '', 25549),
(134499, 'esMX', '¡Sí! ¡Huye! ¡Huye!', '', 25549),
(134498, 'esMX', '¡Acepta a Sargeras!', '', 25549),
(134497, 'esMX', 'Nunca... escaparás...', '', 25549),
(134496, 'esMX', 'No hay escapatoria.', '', 25549),
(134495, 'esMX', 'Argus... se alzará...', '', 25549),
(134494, 'esMX', '¿Por qué está... oscuro?', '', 25549),
(134493, 'esMX', 'Los eredar... reinan...', '', 25549),
(134491, 'esMX', 'Corre... mientras puedas.', '', 25549),
(134489, 'esMX', 'Nunca... escaparás...', 'Nunca... escaparás...', 25549),
(134488, 'esMX', 'No hay escapatoria.', 'No hay escapatoria.', 25549),
(134487, 'esMX', 'Argus... se alzará...', 'Argus... se alzará...', 25549),
(134486, 'esMX', '¿Por qué está... oscuro?', '¿Por qué está... oscuro?', 25549),
(134485, 'esMX', 'Los eredar... reinan...', 'Los eredar... reinan...', 25549),
(134484, 'esMX', 'Corre... mientras puedas.', 'Corre... mientras puedas.', 25549),
(134483, 'esMX', '', 'Esto no cambia nada.', 25549),
(134482, 'esMX', '', 'La llama de Argus me da nueva vida.', 25549),
(134481, 'esMX', '', 'Antorus, regreso...', 25549),
(134480, 'esMX', '', 'Soy una... de muchos...', 25549),
(134479, 'esMX', '', 'Renaceré de nuevo... Por siempre...', 25549),
(134478, 'esMX', '', 'Disfruta de mi caricia helada antes de caer congelado.', 25549),
(134477, 'esMX', '¡Lo lograste! ¡Vamos, entremos al Xenedar y rescatemos a Xe''ra!', '', 25549),
(134473, 'esMX', '', 'Se ven tan vulnerables, temblando de miedo en la oscuridad.', 25549),
(134472, 'esMX', '', '¡Antorus te envía saludos!', 25549),
(134470, 'esMX', '', '¡Asaré sus extremidades!', 25549),
(134469, 'esMX', '', '¿Crees que puedes derrotarnos? ¿Aquí? ¡Ja!', 25549),
(134468, 'esMX', '', 'Un error fatal.', 25549),
(134467, 'esMX', '', '¡Contempla el poder del Trono Ardiente!', 25549),
(134466, 'esMX', '', '¡Antorus escuchará tus gritos!', 25549),
(134462, 'esMX', '¡Los partiré en dos y cobraré el doble de recompensa!', '', 25549),
(134461, 'esMX', '¡No saldrán de aquí con vida!', '', 25549),
(134459, 'esMX', '¡Su precio ya supera el costo de esta batalla!', '', 25549),
(134458, 'esMX', 'La Sentencia de la Luz... Vaya, es magnífica. ¡La pondré en funcionamiento muy pronto!', '', 25549),
(134457, 'esMX', '¡Cuanto más peleen, mayor será mi recompensa!', '', 25549),
(134456, 'esMX', '¡Bombardeen esta área!', '', 25549),
(134455, 'esMX', '¡Fuego en mi posición!', '', 25549),
(134454, 'esMX', '', 'No te preocupes, Alto exarca. Enaara y Sorvos están posicionados en nuestro campamento principal. Los demás están dispersos, pero seguro que sobrevivieron.', 25549),
(134452, 'esMX', '¿Qué hay del resto de los capitanes? Ruego que estén a salvo también.', '', 25549),
(134446, 'esMX', '<Engranaje bélico templeluz>', '<Engranaje bélico templeluz>', 25549),
(134445, 'esMX', '<Campeón templeluz>', '<Campeón templeluz>', 25549),
(134444, 'esMX', '<Faro de teletransporte del Vindicaar>', '<Faro de teletransporte del Vindicaar>', 25549),
(134443, 'esMX', '<Embozo de ecos arcanos>', '<Embozo de ecos arcanos>', 25549),
(134441, 'esMX', 'Parece que tendré que llamar a la artillería pesada.', '', 25549),
(134440, 'esMX', 'No tienen a dónde huir.', '', 25549),
(134437, 'esMX', 'Bueno, ya sabes cuál es la única criatura que tropieza dos veces con la misma piedra...', '', 25549),
(134436, 'esMX', 'Mis hermanos están empecinados en precipitar el hundimiento de este lugar en la oscuridad. Frena sus actividades. O no. De todas formas, el Vacío siempre consigue lo que quiere.', '', 25549),
(134435, 'esMX', '', 'No desperdiciaré la oportunidad de aprender de mis antiguos compañeros. Gracias por tu ayuda.', 25549),
(134434, 'esMX', '', 'Hay muchas preguntas sin respuesta sobre los espíritus que deambulan por aquí. ¿Por qué se quedan? ¿Por qué rechazan nuestra presencia? Quizás si estudiamos su esencia obtengamos una respuesta.', 25549),
(134433, 'esMX', 'Te permitiré conservar tus credenciales. Por ahora.', '', 25549),
(134432, 'esMX', 'Ya es tarde para moralejas. Preséntate en el Salón de la Iluminación para un examen.', '', 25549),
(134431, 'esMX', '', '¡Fascinante! Sus escamas están cubiertas con partículas sensibles al maná. Sin dudas encontraré un uso para este conocimiento.', 25549),
(134430, 'esMX', '', 'Los pantharas se alimentan de los espíritus del Conservatorio. Tráeme muestras de sus escamas y crearé un agente para combatirlos.', 25549),
(134429, 'esMX', 'Hmm... Estaba seguro de que no completarías la prueba esta vez. De acuerdo con las reglas, debo reconocer tu éxito. Felicitaciones.', '', 25549),
(134428, 'esMX', 'He diseñado una modificación de una prueba anterior. Si estás a la altura del desafío, podrás demostrar tu astucia de nuevo.', '', 25549),
(134427, 'esMX', '', 'Una flecha menos en el carcaj. Quizá pueda encontrar un uso para estos cristales que sirva a nuestra causa.', 25549),
(134426, 'esMX', '', 'Este lugar rebosa de oscuridad, que se manifiesta en cristales de vacío puro. La Guardia de las Sombras ansía este recurso. Debemos reclamarlo antes que ellos.', 25549),
(134425, 'esMX', 'Una táctica inusual, sin dudas. Hay que impedir que la Legión use esos espíritus indefensos para sus planes.', '', 25549),
(134424, 'esMX', 'Es extraño... Los espíritus se han congregado para escuchar a Kil''jaeden, pero las apariencias engañan. Siento una presencia demoníaca. Encuéntrala en la multitud antes de que prepare una emboscada.', '', 25549),
(134423, 'esMX', 'Has ganado un tiempo valioso, pero debemos permanecer alerta. Mientras la Legión sepa que tenemos una base en Mac''Aree, no se rendirán.', '', 25549),
(134422, 'esMX', 'Las fuerzas de Antorus están usando los restos de los portales de Talgath para organizar otra invasión a Mac''Aree. Detén su avance antes de que nos arrasen.', '', 25549),
(134421, 'esMX', 'Me divierte ver cómo siguen subestimándolos, ser de carne. ¿No crees?', '', 25549),
(134420, 'esMX', 'Mis hermanos son tan laboriosos como astutos. Creo que la avanzada de la incursión necesita otro castigo. Ya sabes qué hacer.', '', 25549),
(134419, 'esMX', '', 'Espero que consigan paz después de tanto sufrimiento. Buen trabajo, aunque nuestra lucha contra la Guardia de las Sombras acaba de empezar.', 25549),
(134418, 'esMX', '', 'Las formidables criaturas locales son presas dignas de cualquier cazador, pero la Guardia de las Sombras quiere fortalecerlas aún más con el Vacío. Detén a los etéreos y devuelve estas bestias a la naturaleza.', 25549),
(134417, 'esMX', 'Eso debería mantenerlos ocupados. Al menos por ahora.', '', 25549),
(134416, 'esMX', 'La Legión quiere asegurar una posición en Mac''Aree. Desgasta sus fuerzas como puedas. Provoca un caos del que no puedan recuperarse.', '', 25549),
(134415, 'esMX', 'Los ensamblajes activados serán una distracción excelente. ¡Te lo agradezco!', '', 25549),
(134414, 'esMX', 'Las fuerzas de la Legión ocupan las fincas de Mac''Aree. Activa los vigilantes de los nobles para que ayuden en la batalla. Seguramente los eredar robaron sus cristales de poder.', '', 25549),
(134413, 'esMX', 'Esos ensamblajes no se han tomado muy bien el paso del tiempo, ¿verdad? Supongo que al final nada es inmune a la decadencia.', '', 25549),
(134412, 'esMX', 'Necesito un tipo de cristal muy específico para mantener las defensas del Vindicaar. Los ensamblajes que yacen aquí cuentan con esta tecnología. Quítales sus núcleos. Usa el método que creas más adecuado.', '', 25549),
(134411, 'esMX', 'Espero con ansias el día en que podamos dejar atrás este lugar devastado. Quizá entonces puedan encontrar la paz.', '', 25549),
(134410, 'esMX', 'Me temo que nuestra presencia permanente en Mac''Aree ha despertado más espíritus furiosos. Ayúdalos a encontrar la paz.', '', 25549),
(134409, 'esMX', 'Intenten conservar intactas las partes que permitan identificarlos.', '', 25549),
(134408, 'esMX', 'No necesito cadáveres enteros para cobrar la recompensa. Bastará con algunas extremidades sueltas.', '', 25549),
(134407, 'esMX', '¡Tienen que ser más rápidos, mortales!', '', 25549),
(134406, 'esMX', '¡Es hora de un baño de sangre!', '', 25549),
(134405, 'esMX', 'Síganme, si pueden.', '', 25549),
(134404, 'esMX', 'Los recogeré más tarde.', '', 25549),
(134403, 'esMX', '¡No se levanten!', '', 25549),
(134402, 'esMX', 'Dulces sueños.', '', 25549),
(134401, 'esMX', 'Ahora llevaremos la pelea al mismísimo Trono ardiente. Prepárense. ¡Antorus espera!', '', 25549),
(134400, 'esMX', '¡La Corona está completa una vez más!', '', 25549),
(134399, 'esMX', 'Te has enfrentado a peligros comparables con los que ha provocado la Legión. Por favor, el honor de colocar el Blasón te pertenece.', '', 25549),
(134396, 'esMX', 'No hay tiempo para celebrar nuestra victoria sobre Talgath. La canción oscura de L''ura resuena en mi mente.', '', 25549),
(134393, 'esMX', 'Entonces está oculta en el Trono del Triunvirato. Solo siento oscuridad en el interior.', '', 25549),
(134392, 'esMX', 'Al menos sabemos dónde está.', '', 25549),
(134391, 'esMX', 'El tiempo de esta reliquia ha pasado. Abandónala con la naaru en el templo. Que se pudran juntas.', '', 25549),
(134390, 'esMX', 'Es inútil. El Blasón no sirve por sí solo.', '', 25549),
(134389, 'esMX', 'De prisa, amigos míos. Algo oscuro y terrible se agita... Y no es Talgath.', '', 25549),
(134388, 'esMX', 'Estamos un paso más cerca de desbloquear el verdadero potencial del Vindicaar. Solo falta el Blasón del conocimiento. Así la Corona estará completa una vez más.', '', 25549),
(134387, 'esMX', 'Me pregunto qué quería lograr con estos desafíos. Quizás el Sigilo era la prueba en sí misma.', '', 25549),
(134386, 'esMX', 'Este menosprecio nos permitió recuperar el Sigilo. Si hubiera descubierto su valor antes que nosotros, je, seguro lo habría destruido.', '', 25549),
(134385, 'esMX', 'Archimonde menospreció las limitaciones del Sigilo. Sin el resto de la Corona, le brindó poco poder. Y el poder es todo lo que ansía.', '', 25549),
(134384, 'esMX', '"Ese no es tu camino", me dijeron. ¿Esto es lo que planeaban?', '', 25549),
(134383, 'esMX', 'A medida que Argus se hacía más y más pequeño con la distancia, yo solo les rogaba a los naaru poder regresar.', '', 25549),
(134382, 'esMX', 'Mi pueblo nunca sabrá cuánto sufrí por ellos... Mi profundo arrepentimiento.', '', 25549),
(134381, 'esMX', 'Tú... Insignificante...', '', 25549),
(134380, 'esMX', 'El resto ya lo sabes.', '', 25549),
(134379, 'esMX', 'Le conté mi plan de abandonar Argus. Le pedí que trajera a mi familia y me acompañara. En cambio, acudió a Kil''jaeden.', '', 25549),
(134378, 'esMX', '¿Acaso era esta... su visión?', '', 25549),
(134377, 'esMX', '¡No! Nuestro... destino...', '', 25549),
(134376, 'esMX', '¡Mi vida por Argus!', '', 25549),
(134375, 'esMX', '¡Imposible! ¡No aquí!', '', 25549),
(134374, 'esMX', 'No... No después de todo lo que hemos sacrificado...', '', 25549),
(134373, 'esMX', '¡Hasta aquí llegó tu patética resistencia!', '', 25549),
(134372, 'esMX', '¡Fuiste un insensato al venir aquí!', '', 25549),
(134371, 'esMX', '¡Yo poseo el verdadero poder de la energía vil!', '', 25549),
(134370, 'esMX', 'Argus será su tumba.', '', 25549),
(134369, 'esMX', 'Su mundo que flota en los cielos... ¡está condenado!', '', 25549),
(134368, 'esMX', '¡Tiembla ante el verdadero poder de la Legión!', '', 25549),
(134367, 'esMX', '', '¡No logras ver... la verdad!', 25549),
(134366, 'esMX', '', 'Veo que... eres $Gobstinado:obstinada;...', 25549),
(134365, 'esMX', '', '¡Nada detendrá al maestro!', 25549),
(134364, 'esMX', '', '¿Acaso no lo ves? Esta es la única manera. ¡Haré que lo entiendas!', 25549),
(134363, 'esMX', '', '¡La resistencia no será tolerada!', 25549),
(134362, 'esMX', '', 'Un dolor insignificante...', 25549),
(134361, 'esMX', '', 'No escaparás... de tu destino...', 25549),
(134360, 'esMX', '', '¡Mi vida por la Legión!', 25549),
(134359, 'esMX', '', 'He asesinado a una cantidad infinita de mortales. ¿Realmente crees que puedes derrotarme?', 25549),
(134358, 'esMX', 'Las reglas son las reglas.', '', 25549),
(134357, 'esMX', 'Eso tampoco fue placentero para mí.', '', 25549),
(134356, 'esMX', 'El protocolo indica que debo despedirte.', '', 25549),
(134355, 'esMX', 'Servir es mi obligación.', '', 25549),
(134354, 'esMX', 'Declara tus intenciones.', '', 25549),
(134353, 'esMX', 'Debo saludar. Hola.', '', 25549),
(134352, 'esMX', 'No prestes atención a los susurros.', '', 25549),
(134351, 'esMX', 'Shhh... ¿Oíste eso?', '', 25549),
(134350, 'esMX', '$GEl extraño:La extraña; habla extrañamente.', '', 25549),
(134349, 'esMX', '¿Me hablabas?', '', 25549),
(134348, 'esMX', '¡Ah! Oh. ¿Sí?', '', 25549),
(134347, 'esMX', 'Arkhaan te escucha.', '', 25549),
(134346, 'esMX', 'Qué bueno que has llegado, $n. Acabábamos de usar lo último de eso y creímos que tendríamos que esperar más tiempo para recibir más. ¡Gracias!', '', 25549),
(134345, 'esMX', '¿Cómo va todo, $n? ¿Hay algo con lo que pueda ayudarte?', '', 25549),
(134344, 'esMX', '', 'Ya era hora. Estos materiales comenzaban a escasear.$b$bDile a Vridiel que sus mensajeros deben trabajar más rápido.', 25549),
(134343, 'esMX', 'Tengo tu cargamento de laja vil.', 'Tengo tu cargamento de laja vil.', 25549),
(134342, 'esMX', '', 'Estoy ocupada, $r. ¿Qué quieres?', 25549),
(134338, 'esMX', 'No me hagas perder el tiempo.', '', 25549),
(134337, 'esMX', '', '¿Te atreves a pisar su mundo? ¡Morirás!', 25549),
(134336, 'esMX', 'La carne es frágil. El poder prevalece.', '', 25549),
(134335, 'esMX', 'Todo depende de cómo lo mires.', '', 25549),
(134333, 'esMX', 'Yo represento... una alternativa.', '', 25549),
(134332, 'esMX', 'Sigue tu camino.', '', 25549),
(134331, 'esMX', 'Fascinante. Simplemente fascinante.', '', 25549),
(134327, 'esMX', '', 'Es un buen día para cazar.', 25549),
(134326, 'esMX', '', 'Usa todas las armas a tu alcance.', 25549),
(134325, 'esMX', '', '¿Traes noticias?', 25549),
(134324, 'esMX', '', 'La Luz no te salvará. ¡No aquí!', 25549),
(134323, 'esMX', '', '¡Tu cadáver se convertirá en un trofeo para el maestro!', 25549),
(134322, 'esMX', '', 'Todos recorremos caminos diferentes. Elige el tuyo.', 25549),
(134321, 'esMX', '', 'Saludos.', 25549),
(134320, 'esMX', '', 'Las sombras pueden ser nuestras aliadas... Si logramos controlarlas.', 25549),
(134319, 'esMX', '', 'Adiós.', 25549),
(134318, 'esMX', '', 'Apunta con precisión.', 25549),
(134317, 'esMX', '', 'Hacemos lo que debemos por aquellos que amamos.', 25549),
(134316, 'esMX', '', 'Mantén la mirada fija en tu objetivo.', 25549),
(134315, 'esMX', 'Pero valió la pena. Por Azeroth, y por todos aquellos a quienes amamos.', '', 25549),
(134314, 'esMX', 'Luchando contra la Legión a cada paso... Saboreando cada victoria... y lamentando cada derrota.', '', 25549),
(134313, 'esMX', 'Pasé tanto tiempo lejos de mi hogar. Lejos de mi hijo.', '', 25549),
(134312, 'esMX', 'Luchamos por nuestro hogar... por nuestra familia.', '', 25549),
(134311, 'esMX', 'Que la Luz nos guíe.', '', 25549),
(134308, 'esMX', 'No llegamos hasta aquí para fallar ahora.', '', 25549),
(134307, 'esMX', 'Dioniss aca.', '', 25549),
(134306, 'esMX', 'Camina en la Luz.', '', 25549),
(134305, 'esMX', 'Resistiremos juntos.', '', 25549),
(134304, 'esMX', 'Mi fe es mi escudo.', '', 25549),
(134303, 'esMX', 'El Ejército de la Luz está preparado.', '', 25549),
(134302, 'esMX', 'La Luz te da la bienvenida, adalid.', '', 25549),
(134301, 'esMX', '¡Krona ki cristorr!', '', 25549),
(134287, 'esMX', 'Puede que los demás fragmentos sigan aquí, en Argus. Debemos ir a Mac''Aree, donde mis hermanos y yo solíamos gobernar.', '', 25549),
(134286, 'esMX', 'Yo aún poseo un tercio. Siempre lo llevo conmigo. Este es el Ojo de la profecía.', '', 25549),
(134285, 'esMX', 'Regresar a la entrada.', 'Regresar a la entrada.', 25549),
(134284, 'esMX', 'El faro vibra con energía.', '', 25549),
(134283, 'esMX', 'Hace mucho tiempo, mis hermanos y yo diseñamos una reliquia para brindar prosperidad a todos.', '', 25549),
(134282, 'esMX', 'La llamamos la Corona del Triunvirato.', '', 25549),
(134281, 'esMX', 'Pero hay una esperanza, un tesoro que podría darnos la ventaja que necesitamos.', '', 25549),
(134280, 'esMX', 'He pensado mucho en nuestra situación. En este momento, si desafiamos a Antorus seremos destruidos.', '', 25549),
(134262, 'esMX', 'Nunca... escaparás...', 'Nunca... escaparás...', 25549),
(134261, 'esMX', 'No hay escapatoria.', 'No hay escapatoria.', 25549),
(134260, 'esMX', 'Argus... se alzará...', 'Argus... se alzará...', 25549),
(134259, 'esMX', '¿Por qué está... oscuro?', '¿Por qué está... oscuro?', 25549),
(134258, 'esMX', 'Los eredar... reinan...', 'Los eredar... reinan...', 25549),
(134257, 'esMX', 'Corre... mientras puedas.', 'Corre... mientras puedas.', 25549),
(134256, 'esMX', '', '¿Cuándo terminará esto?', 25549),
(134255, 'esMX', '', 'Debí haber... huido...', 25549),
(134254, 'esMX', '', 'No podíamos escapar.', 25549),
(134253, 'esMX', '', 'Velen... ¿por qué?', 25549),
(134251, 'esMX', '', 'Esta oscuridad... Creí que...', 25549),
(134250, 'esMX', '', 'Estoy tan cansada.', 25549),
(134249, 'esMX', '¡Nadie detendrá a Sargeras!', '¡Nadie detendrá a Sargeras!', 25549),
(134248, 'esMX', '¡Esta será la última dádiva que rechaces!', '¡Esta será la última dádiva que rechaces!', 25549),
(134247, 'esMX', '¡Sufre por tu necedad!', '¡Sufre por tu necedad!', 25549),
(134246, 'esMX', '¡Huye al abismo, cobarde!', '¡Huye al abismo, cobarde!', 25549),
(134245, 'esMX', '¡Sí! ¡Huye! ¡Huye!', '¡Sí! ¡Huye! ¡Huye!', 25549),
(134244, 'esMX', '¡Acepta a Sargeras!', '¡Acepta a Sargeras!', 25549),
(134242, 'esMX', '', '¡No deberías estar aquí!', 25549),
(134241, 'esMX', '', '¡No te burles de mi sufrimiento!', 25549),
(134240, 'esMX', '', '¡Este es nuestro hogar! ¡Lárgate!', 25549),
(134239, 'esMX', '', '¿Por qué no nos dejas descansar?', 25549),
(134238, 'esMX', '', '¡No me atormentarás!', 25549),
(134222, 'esMX', 'Lo sé, amor mío. Siento lo mismo. Pero una vez que veamos a nuestro hijo, dejaremos que nuestros corazones hablen por nosotros.', '', 25549),
(134221, 'esMX', '', 'Durante mil años pensé en lo que le diría cuando lo viera. Sin embargo, ahora no encuentro las palabras.', 25549),
(134220, 'esMX', 'No hay suficientes jugadores.', '', 25549),
(134218, 'esMX', '¡Te enviaré a la oscuridad!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(134217, 'esMX', '¡Caerás en el Vacío!', '', 25549),
(134216, 'esMX', 'Qué fácil de vencer.', '', 25549),
(134215, 'esMX', 'Más alimento para mis bellezas.', '', 25549),
(134214, 'esMX', '¡Siempre estaré un paso adelante!', '', 25549),
(134213, 'esMX', '¡Un ataque rápido y letal!', '', 25549),
(134212, 'esMX', 'No había... previsto esto.', '', 25549),
(134210, 'esMX', 'Un simple... error táctico...', '', 25549),
(134207, 'esMX', 'Mis mascotas tienen hambre.', '', 25549),
(134206, 'esMX', '¡Nadie interrumpirá nuestros esfuerzos!', '', 25549),
(134205, 'esMX', '¡La oscuridad los llevará!', '', 25549),
(134204, 'esMX', 'La luz se desvanece.', '', 25549),
(134203, 'esMX', '¡Observen el abismo y desesperen!', '', 25549),
(134202, 'esMX', '¡Sus vidas acaban ahora!', '', 25549),
(134201, 'esMX', 'Mi muerte... no será un obstáculo. El Vacío... consumirá todo.', '', 25549),
(134200, 'esMX', '¡No! La oscuridad... debía ser mía...', '', 25549),
(134199, 'esMX', '¡Los guiaré hasta el crepúsculo!', '', 25549),
(134198, 'esMX', '¡El Vacío me llama!', '', 25549),
(134197, 'esMX', '¡Los exterminaré!', '', 25549),
(134196, 'esMX', '¡Oscuridad, dame fuerza!', '', 25549),
(134195, 'esMX', 'Ahora... todo es claro. El Vacío... era débil.', '', 25549),
(134194, 'esMX', 'Cuánta... fuerza.', '', 25549),
(134193, 'esMX', '¡Patético!', '', 25549),
(134192, 'esMX', '¡El Vacío consume a los débiles!', '', 25549),
(134191, 'esMX', 'Preparando', 'Preparando', 25549),
(134190, 'esMX', '', 'Mmm... Parece que uno de nuestros ganadores ha abandonado el edificio. Bueno, ¡se lo pierde!', 25549),
(134189, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMERING.BLP:20|t¡Kin''garoth ha potenciado |cFFFF0000|Hspell:246779|h[Bomba diabólica]|h|r!', '', 25549),
(134188, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_FLAMETOUNGE.BLP:20|t¡Kin''garoth ha potenciado |cFFFF0000|Hspell:248475|h[Golpe resonante]|h|r!', '', 25549),
(134187, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMEBREATH.BLP:20|t¡Kin''garoth ha potenciado |cFFFF0000|Hspell:246840|h[Arruinador]|h|r!', '', 25549),
(134185, 'esMX', 'Sale el sol.', '', 25549),
(134184, 'esMX', 'Choque de cuernos entre dos talbuks.', '', 25549),
(134183, 'esMX', 'Tu derrota es segura.', '', 25549),
(134182, 'esMX', 'Arrodíllate o muere.', '', 25549),
(134181, 'esMX', 'No eres un rival digno de mi espada.', '', 25549),
(134180, 'esMX', 'Cuando es imposible que te derroten, la victoria es inevitable.', '', 25549),
(134179, 'esMX', 'Dioniss aca.', '', 25549),
(134178, 'esMX', 'Recorre tu camino con confianza.', '', 25549),
(134177, 'esMX', 'Alimenta las llamas. Lucha contra la oscuridad.', '', 25549),
(134176, 'esMX', '', 'Saludos, $n. ¿Cómo sigue la batalla contra la Legión?', 25549),
(134175, 'esMX', 'Abraza la tranquilidad.', '', 25549),
(134174, 'esMX', '', 'Las bestias viles que acechan estas tierras desoladas tienen el pellejo más hediondo que jamás haya olido.$b$bEspero que algún día podamos largarnos de este lugar y encontrar un hogar con criaturas que huelan mejor.', 25549),
(134173, 'esMX', 'Soy uno con la Luz. La Luz me acompaña.', '', 25549),
(134172, 'esMX', 'La oscuridad que inunda el templo... La sombra que se cierne sobre todo Mac''Aree... es L''ura.', '', 25549),
(134171, 'esMX', 'Las últimas palabras de Talgath... Ni siquiera la Luz escapará. ¿Qué quiso decir?', '', 25549),
(134170, 'esMX', 'Vamos. No me atrevo a permanecer aquí.', '', 25549),
(134169, 'esMX', 'Hay un teletransportador en camino.', '', 25549),
(134168, 'esMX', 'He identificado una ruta de escape segura al noroeste de tu posición actual.', '', 25549),
(134167, 'esMX', 'No pierdas de vista las hierbas con incrustaciones viles. Aún puedes encontrar gloria astral en su interior.', '', 25549),
(134166, 'esMX', '', 'Oigo lo que se dice por ahí, que soy sanguinaria y me comporto de una forma indecorosa para una sacerdotisa.', 25549),
(134165, 'esMX', 'Siempre es agradable ver a $Gotro:otra; $c en las filas. Necesitamos toda la ayuda que podamos conseguir.', '', 25549),
(134160, 'esMX', '', 'Todos necesitamos sangre. Todos, menos los traidores. Y por eso se la quitamos.', 25549),
(134154, 'esMX', 'La caída del Xenedar fue una pérdida trágica. Sin embargo, esta es una nave fantástica. Tal vez aún tengamos una oportunidad contra la Legión.', '', 25549),
(134153, 'esMX', '', 'Quiero matar demonios todo el día. Y que Sargeras se enfurezca con mi voz.', 25549),
(134148, 'esMX', '', 'Cada demonio que asesines es un demonio menos que enfrentar.', 25549),
(134147, 'esMX', '', 'Ten cuidado, y asesina a cuantos demonios puedas.', 25549),
(134146, 'esMX', '', 'La Legión no se detendrá ante nada. Ten cuidado.', 25549),
(134145, 'esMX', '', 'Dioniss aca.', 25549),
(134144, 'esMX', '', 'Intenta encontrar algo útil.', 25549),
(134143, 'esMX', '', '¿Necesitas ayuda para exterminar a nuestros enemigos?', 25549),
(134142, 'esMX', '', '¿Estás $Gherido:herida;? ¡Bah! Aún estás de pie. Sigue luchando, ya habrá tiempo para hablar.', 25549),
(134141, 'esMX', '', '¡Descansarás cuando los hayamos asesinado a todos! ¡Sigue luchando!', 25549),
(134140, 'esMX', '', '¿Puedes caminar? Entonces puedes luchar.', 25549),
(134139, 'esMX', '', 'Pheta thones gamera.', 25549),
(134138, 'esMX', '', 'Traigan a los heridos. ¡Curaré sus heridas y purgaré esta escoria con una sola plegaria!', 25549),
(134137, 'esMX', '', '¡Almas miserables! Su derrota será rápida.', 25549),
(134136, 'esMX', '', '¡No existe redención para ustedes!', 25549),
(134135, 'esMX', '', 'Que la Luz te purifique.', 25549),
(134134, 'esMX', '', '¡No existe salvación para ustedes, traidores!', 25549),
(134133, 'esMX', '', '¡Arkonos vi acahachi!', 25549),
(134131, 'esMX', '', 'Te destruiremos, ¡cueste lo que cueste!', 25549),
(134130, 'esMX', '', 'No sé si asesinarte con un hechizo o con mi espada.', 25549),
(134129, 'esMX', '', '¡He sacrificado demasiado como para perder!', 25549),
(134128, 'esMX', '', 'Siente el filo de mi guja.', 25549),
(134127, 'esMX', '', '¡A mi lado, nobles guerreros!', 25549),
(134126, 'esMX', '', '¡La Luz quedará grabada en sus almas!', 25549),
(134124, 'esMX', '', '¡Otro asalto! ¡En guardia!', 25549),
(134121, 'esMX', '|TINTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:239153|h[Fragmentación espontánea]|h|r!', '|TINTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:239153|h[Fragmentación espontánea]|h|r!', 25549),
(134120, 'esMX', 'INTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t ¡|cFFFF0000|Hspell:240209|h[Fragmentación espontánea]|h|r te ha fijado como objetivo!', 'INTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t ¡|cFFFF0000|Hspell:240209|h[Fragmentación espontánea]|h|r te ha fijado como objetivo!', 25549),
(134119, 'esMX', '¡Ja! Llegas tarde. Nada escapará del templo. Ni siquiera la mismísima Luz.', '', 25549),
(134117, 'esMX', 'Este es tu fin. Si aún queda algo de bondad en ti, nos ayudarás a encontrar el Blasón del conocimiento.', '', 25549),
(134102, 'esMX', '|TInterface\\ICONS\\SPELL_FIRE_TWILIGHTNOVA:20|t¡El Virrey Nezhar comienza a lanzar |cFFFF0000|Hspell:248736|h[Crepúsculo eterno]|h|r!', '', 25549),
(134083, 'esMX', '¡Esto no debía pasar! ¡Yo debía vivir para siempre!', '', 25549),
(134082, 'esMX', 'Muchos han intentado matarme. ¡Todos están muertos, pero yo sigo aquí!', '', 25549),
(134081, 'esMX', '¿Crees que estás ganando? ¡Soy inmortal!', '', 25549),
(134080, 'esMX', '¡No moriré tan fácilmente! ¡El Corazón vil me protegerá!', '', 25549),
(134071, 'esMX', 'Ante ti yacen los restos de recuerdos pasados, ecos de lo que era nuestra gente antes de la llegada del Titán oscuro.$B$BCuando alguno de los nuestros logra escapar de las garras de la Legión, a veces regresa con un recuerdo de nuestro antiguo estilo de vida.$b$bEstas reliquias simbolizan todo lo que hemos perdido... y sirven para recordarnos por qué luchamos.', '', 25549),
(134058, 'esMX', 'Der''ek... manul...', '', 25549),
(134057, 'esMX', '¡AAAaaahhh!', '', 25549),
(134056, 'esMX', 'Ya veo. Buen viaje, Talgath.', '', 25549),
(134055, 'esMX', 'No. Esto termina ahora.', '', 25549),
(134054, 'esMX', 'Terminaremos esto en otr...', '', 25549),
(134053, 'esMX', 'Sheet-sah, te escondes tras tus aliados... como siempre.', '', 25549),
(134052, 'esMX', 'Parece que es un tema sensible...', '', 25549),
(134051, 'esMX', '¡Silencio! ¡No te atrevas a mencionarlos!', '', 25549),
(134050, 'esMX', 'Tenía la esperanza de que ellos fuesen un motivo para quedarte. Qué despiadado... marcharte sin tu compañera y tu hijo.', '', 25549),
(134047, 'esMX', '¡No he olvidado tu traición!', '', 25549),
(134046, 'esMX', 'No lo perdiste. Renunciaste a él... ¡a todo! A tu pueblo, tu planeta... ¡incluso tu familia!', '', 25549),
(134045, 'esMX', 'Yo también perdí a un hermano amado ese día.', '', 25549),
(134044, 'esMX', '¡Oh, Kil''jaeden sufrió mucho por ti! ¿Sabes cuánto lo hirió tu partida?', '', 25549),
(134041, 'esMX', 'Pheta thones gamera. Luz, guía nuestro camino.', '', 25549),
(134040, 'esMX', 'Estamos contigo, Velen.', '', 25549),
(134039, 'esMX', '¡Que termine la cacería! ¡Eres mío, Profeta!', '', 25549),
(134034, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(134033, 'esMX', 'Después de todo lo que he padecido por su culpa... Después de todo el sufrimiento de mi pueblo... Llegamos a este momento.$b$b<Velen aferra su bastón con fuerza.>$b$bCuando estés $Glisto:lista;, pondremos fin a esto juntos.', '', 25549),
(134032, 'esMX', 'Un cambio de actitud muy oportuno, no hay dudas.', '', 25549),
(134031, 'esMX', 'Qué diferencia, Velen, ahora te defiendes.', '', 25549),
(134030, 'esMX', 'Aquí está.', '', 25549),
(134029, 'esMX', 'IGC: Sargeras aparece frente al Triunvirato', 'IGC: Sargeras aparece frente al Triunvirato', 25549),
(134028, 'esMX', 'Muéstrame.', 'Muéstrame.', 25549),
(134027, 'esMX', 'Déjame mostrarte lo que he hecho. Tal vez así finalmente pueda estar en paz con mis acciones.', '', 25549),
(134026, 'esMX', '<La mirada de Velen está fija en la estatua frente a él.>', '', 25549),
(134025, 'esMX', 'El Gran Vindicador Sorvos asiente en tu dirección.', '', 25549),
(134024, 'esMX', 'El Maestro del acero Telaamon te saluda.', '', 25549),
(134020, 'esMX', 'Apártense. Yo mismo me encargaré de esto.', '', 25549),
(134019, 'esMX', '¡Sus lamentos se oirán en todo Antorus si los intrusos escapan!', '', 25549),
(134008, 'esMX', 'La Legión está acabada, por ahora. Nuestra guerra continúa en Argus.', '', 25549),
(134006, 'esMX', '¡Su comandante se acerca! Que se arrepienta por profanar este mundo.', '', 25549),
(134005, 'esMX', 'Los demonios se han rociado esporas en el cuerpo para ocultar sus ataques. ¡Muéstrales que no pueden huir de la muerte!', '', 25549),
(134004, 'esMX', 'Ni siquiera en el fango la Legión es capaz de ocultar su asqueroso olor. ¡Hazlos pedazos!', '', 25549),
(133978, 'esMX', '', '¡Rápido, héroes! ¡La naaru está aturdida, pero no durará mucho!', 25549),
(133977, 'esMX', '', '¡Ataquen ahora, campeones! ¡La naaru está débil!', 25549),
(133976, 'esMX', '', '¡Héroes, la naaru está debilitada!', 25549),
(133973, 'esMX', '¡Quédate con su sombra, Alleria! ¡Hazlo como te enseñé!', '', 25549),
(133972, 'esMX', '¡Drena la energía del portal! ¡La debilidad de la naaru será tu fuerza!', '', 25549),
(133967, 'esMX', '¡Sí! ¡Huyen a la terraza! Los tenemos justo donde queremos.', '', 25549),
(133957, 'esMX', '¿Por qué estamos en el Pozo de la Eternidad?', '¿Por qué estamos en el Pozo de la Eternidad?', 25549),
(133956, 'esMX', '¿Por qué estamos en Monte Hyjal?', '¿Por qué estamos en Monte Hyjal?', 25549),
(133955, 'esMX', '¿Por qué estamos en Andorhal?', '¿Por qué estamos en Andorhal?', 25549),
(133954, 'esMX', '¿Por qué estamos en Stratholme?', '¿Por qué estamos en Stratholme?', 25549),
(133949, 'esMX', '¡Llegas de tarde! Mi poder crece... ¡pronto caerás ante mí!', '', 25549),
(133948, 'esMX', 'El Corazón vil se alimenta de las energías de Argus. ¡Pronto seré imparable!', '', 25549),
(133940, 'esMX', '¡Me robaste mi poder! ¡Argus ya no me habla!', '', 25549),
(133937, 'esMX', '¡No escapé de Arcatraz para morir a tus manos!', '', 25549),
(133932, 'esMX', 'Ganaremos esta batalla.', '', 25549),
(133931, 'esMX', 'Tantas pérdidas... Necesitaremos sumar soldados a nuestras filas.', '', 25549),
(133930, 'esMX', 'La Luz nos acompaña.', '', 25549),
(133927, 'esMX', '', '¡El camino está abierto! ¡Rápido, héroes!', 25549),
(133922, 'esMX', 'Si cubres nuestra retirada, quizá sobrevivamos.', '', 25549),
(133921, 'esMX', 'Aunque estemos totalmente rodeados de enemigos, se siente bien luchar junto a mis soldados una vez más.', '', 25549),
(133920, 'esMX', 'El camino está despejado. La Madre de la Luz nos espera.$b$bTenemos que apurarnos. Ahora mismo no hay nada que le impida a la Legión llegar hasta ella.', '', 25549),
(133914, 'esMX', 'Muestra el camino, Profeta.', '', 25549),
(133910, 'esMX', 'Mi tormento... termina...', '', 25549),
(133909, 'esMX', 'Escoltaremos a Velen a salvo hasta el Blasón.', '', 25549),
(133908, 'esMX', 'Toda vida termina.', '', 25549),
(133907, 'esMX', '¡Es tu fin!', '', 25549),
(133906, 'esMX', '¡Muerte! ¡Muerte y dolor!', '', 25549),
(133905, 'esMX', 'Conque aquí está. Justo lo que me temía.', '', 25549),
(133903, 'esMX', '', 'Me entrego al olvido...', 25549),
(133902, 'esMX', '', 'No me apagaré jamás...', 25549),
(133901, 'esMX', 'Tu llegada es oportuna. Debemos encontrar el Blasón del conocimiento antes de que Talgath se lo lleve para siempre.', '', 25549),
(133900, 'esMX', 'Estoy bien.', '', 25549),
(133898, 'esMX', '', 'Entendido. Campeones, cuando la puerta esté abierta, despejen el camino hasta L''ura. Estaremos justo detrás de ustedes.', 25549),
(133897, 'esMX', '¿Estás herido?', '', 25549),
(133896, 'esMX', 'Sí, la naaru. Debemos entrar. Alleria, las habilidades que aprendiste pueden abrir el camino.', '', 25549),
(133895, 'esMX', '', 'Percibo una gran desesperación que emana del interior. L''ura...', 25549),
(133894, 'esMX', '', 'Tengo frío...', 25549),
(133892, 'esMX', '¿Velen?', '', 25549),
(133891, 'esMX', 'Perdóname, hijo mío.', '', 25549),
(133890, 'esMX', '', 'Tenías razon en temerle a la oscuridad.', 25549),
(133889, 'esMX', '', '¡Otro cuerpo para avivar las llamas!', 25549),
(133888, 'esMX', '', 'Tus extremidades serán un trofeo excelente.', 25549),
(133887, 'esMX', '¡Buen disparo! Ahora que esa nave maldita ha dejado de ser una preocupación, podemos concentrarnos en otros frentes.', '', 25549),
(133886, 'esMX', '¡La Legión está armando a un devastador para disparar contra el Xenedar! Necesitamos que lo sabotees.', '', 25549),
(133885, 'esMX', 'Es una pena que el recuerdo de la existencia de Kil''jaeden no se pueda eliminar con la misma facilidad con que has purificado este terreno.', '', 25549),
(133884, 'esMX', 'La nave de Kil''jaeden. Incluso después de su destrucción, su presencia nos inquieta. Elimina la peste del área que la rodea.', '', 25549),
(133882, 'esMX', '', 'No existe luz capaz de atravesar mis sombras.', 25549),
(133881, 'esMX', '', 'Carne crujiente.', 25549),
(133880, 'esMX', '', 'Sus cadáveres quedarán congelados en una agonía eterna.', 25549),
(133879, 'esMX', '', 'No pueden escapar de las sombras.', 25549),
(133878, 'esMX', '', 'Ansío ver crepitar su carne.', 25549),
(133877, 'esMX', '', 'Yo soy el escalofrío que sientes en la espalda.', 25549),
(133876, 'esMX', 'La muerte... nos llega... a todos.', '', 25549),
(133875, 'esMX', 'Al menos murieron aquí, donde ella no puede apoderarse de ustedes.', '', 25549),
(133874, 'esMX', '¡Te rompes tan fácilmente!', '', 25549),
(133873, 'esMX', 'Vengan. Intercambiemos un poco de dolor.', '', 25549),
(133871, 'esMX', 'Expandí mis horizontes, colega. Tengo todo tipo de cosas para ofrecer y muchas oportunidades.', '', 25549),
(133870, 'esMX', '¡Alto, $gpequeño:pequeña;! ¡No te muevas!', '', 25549),
(133869, 'esMX', '$GQuieto:Quieta;. La aldea oculta nuestra presencia. Aquí no sufriremos ningún daño.', '', 25549),
(133868, 'esMX', '¡Alto! Estos vientos que traicionan nuestros sentidos generan malestar en la naturaleza.', '', 25549),
(133867, 'esMX', 'Calma, $gpequeño:pequeña;. Aquí estamos a salvo.', '', 25549),
(133866, 'esMX', '$GTranquilo:Tranquila;. Es solo el viento.', '', 25549),
(133864, 'esMX', 'Me arrepiento... de haber aceptado... este trabajo...', '', 25549),
(133863, 'esMX', 'El Maestro del acero Telaamon asiente bruscamente.', '', 25549),
(133862, 'esMX', '<Telaamon baja su espada y te observa expectante.>', '', 25549),
(133861, 'esMX', 'Supongo que debería juntar las partes y cobrar mi recompensa.', '', 25549),
(133860, 'esMX', 'Blaaaac', '', 25549),
(133859, 'esMX', 'Paac', '', 25549),
(133858, 'esMX', 'Pa-caak', '', 25549),
(133857, 'esMX', 'Cuoooc', '', 25549),
(133856, 'esMX', 'Pa', '', 25549),
(133855, 'esMX', 'cloc-aaac', '', 25549),
(133854, 'esMX', 'Claaac', '', 25549),
(133853, 'esMX', 'Ca', '', 25549),
(133852, 'esMX', 'Cuu', '', 25549),
(133851, 'esMX', 'Du', '', 25549),
(133850, 'esMX', 'Craaac', '', 25549),
(133849, 'esMX', 'Cucraac', '', 25549),
(133848, 'esMX', 'a', '', 25549),
(133847, 'esMX', 'Chii-pacaa', '', 25549),
(133846, 'esMX', 'Extrayendo', 'Extrayendo', 25549),
(133845, 'esMX', 'Chiii', '', 25549),
(133844, 'esMX', 'Chaaaa', '', 25549),
(133843, 'esMX', 'Ca-craaac', '', 25549),
(133842, 'esMX', 'Aak', '', 25549),
(133841, 'esMX', 'Me pagan el doble si los hago sufrir.', '', 25549),
(133840, 'esMX', 'Colgaré sus cabezas en mi sala de trofeos.', '', 25549),
(133839, 'esMX', 'Ahora solo serviré... para piezas de repuesto.', '', 25549),
(133838, 'esMX', 'Su ensamblaje es de pésima calidad.', '', 25549),
(133837, 'esMX', 'Te haré pedazos y te usaré para mi próximo invento.', '', 25549),
(133836, 'esMX', '¿Pretenden vencer a mis máquinas con esas armas insignificantes?', '', 25549),
(133826, 'esMX', '', 'Es una conversación inevitable, pero de solo pensarlo me inunda el terror. ¿Cómo haré para explicarle a Alleria en qué se ha convertido nuestra hermana? La verdad le romperá el corazón.', 25549),
(133825, 'esMX', 'Sin duda mi madre preguntará por Sylvanas pronto. ¿Qué le dirás?', '', 25549),
(133824, 'esMX', 'Tu brazo cabe en el agujero, pero no logra llenar perfectamente el espacio.', '', 25549),
(133823, 'esMX', 'No sucede nada, más allá de que tu brazo luce pequeño en el agujero.', '', 25549),
(133822, 'esMX', '<Coloca el brazo en el agujero.>', '<Coloca el brazo en el agujero.>', 25549),
(133821, 'esMX', 'Una roca extraña yace en tu camino. Su característica principal es que tiene un agujero resplandeciente en el centro.\n\nEl hueco en la roca está justo a la altura del brazo.', '', 25549),
(133818, 'esMX', '<Coloca el brazo debajo del cubo.>', '<Coloca el brazo debajo del cubo.>', 25549),
(133817, 'esMX', '<El cubo se vuelve a configurar rápidamente.>\n\nColoca tu brazo debajo del cubo.', '', 25549),
(133816, 'esMX', '¡Estas criaturas los volverán más fuertes, debiluchos! ¡Vuelvan al trabajo o los mataré yo mismo!', '', 25549),
(133815, 'esMX', 'Mis creadores están en busca de un heredero interesante.', '', 25549),
(133814, 'esMX', 'El Gran Vindicador Sorvos gruñe afirmativamente.', '', 25549),
(133813, 'esMX', '¿Qué necesitas?', '¿Qué necesitas?', 25549),
(133812, 'esMX', 'Soy capaz de otorgar el primer símbolo.', '', 25549),
(133811, 'esMX', '¿Cuál es tu propósito?', '¿Cuál es tu propósito?', 25549),
(133810, 'esMX', 'Los atemporales me han impartido su conocimiento.', '', 25549),
(133809, 'esMX', '<El Vindicador respira agitado mientras el icor gotea de su maza y su escudo.>$b$b¿Qué era eso?', '', 25549),
(133808, 'esMX', '¿Qué conocimientos posees?', '¿Qué conocimientos posees?', 25549),
(133807, 'esMX', 'Baraat, el Tirolargo te saluda.', '', 25549),
(133800, 'esMX', '¡Cosecha más rápido! El maestro no tolerará a los holgazanes.', '¡Cosecha más rápido! El maestro no tolerará a los holgazanes.', 25549),
(133797, 'esMX', 'Soy el Cubo de la sabiduría.', '', 25549),
(133796, 'esMX', '', 'No es posible... Me han superado...', 25549),
(133795, 'esMX', '¡Inconcebible!', '', 25549),
(133792, 'esMX', '¡Mi nombre será recordado!', '', 25549),
(133791, 'esMX', '', 'Has dejado tus flancos expuestos.', 25549),
(133789, 'esMX', 'Patético.', '', 25549),
(133787, 'esMX', '¡Sin piedad!', '', 25549),
(133783, 'esMX', '<Transmitir las órdenes de Fareeya.>', '<Transmitir las órdenes de Fareeya.>', 25549),
(133782, 'esMX', 'Estaba explorando un terreno elevado en busca de un camino para Velen cuando la Legión nos atacó.$b$bCubrí su retirada, pero quedé separado de los demás.$b$b¿Tienes noticias?', '', 25549),
(133781, 'esMX', '¡El dragón te ha otorgado una bendición poderosa!', '¡El dragón te ha otorgado una bendición poderosa!', 25549),
(133780, 'esMX', '¡El dragón despejó el Santuario de Dragones rubí por ti!', '¡El dragón despejó el Santuario de Dragones rubí por ti!', 25549),
(133779, 'esMX', '¡El dragón despejó el Santuario de Dragones esmeralda por ti!', '¡El dragón despejó el Santuario de Dragones esmeralda por ti!', 25549),
(133778, 'esMX', '¡El dragón despejó el Santuario de Dragones obsidiana por ti!', '¡El dragón despejó el Santuario de Dragones obsidiana por ti!', 25549),
(133777, 'esMX', '¡El dragón despejó el Santuario de Dragones azur por ti!', '¡El dragón despejó el Santuario de Dragones azur por ti!', 25549),
(133776, 'esMX', 'No hay lugar para ustedes en mi campo de batalla.', '', 25549),
(133774, 'esMX', '¿De verdad esperaban otro resultado?', '', 25549),
(133773, 'esMX', '', '¿Este era su plan?', 25549),
(133772, 'esMX', '¡Su frente de batalla no resistirá mi embate!', '', 25549),
(133771, 'esMX', '', 'Esta es una batalla de la que no saldrán con vida.', 25549),
(133770, 'esMX', 'Parece que necesitas algunas lecciones sobre dolor. Permíteme enseñarte.', '', 25549),
(133767, 'esMX', '', 'Finalmente, uno de los maestros de la Legión ha caído. Sin embargo, esta guerra aún no ha terminado.\n\n¿Acaso era este el verdadero plan de Sargeras? ¿Su última jugada? O tal vez esto fue obra de alguien más. Alguien que ya traicionó a este mundo en el pasado.\n\n<Maiev entrecierra los ojos y mira fijamente al cielo.>\n\nEstaré atenta... y preparada.', 25549),
(133762, 'esMX', 'Mis exploradores encontraron los restos de Aggonar. Estamos en deuda contigo, Alto exarca. Y contigo también, $Gforastero:forastera;.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(133761, 'esMX', '', 'Paciencia, Arator. Puede que lleve tiempo, pero tu familia volverá a estar reunida. Lo sé.', 25549),
(133753, 'esMX', 'La Legión no descansará. Y nosotros tampoco.', '', 25549),
(133751, 'esMX', 'Otro lacayo de la Legión se atreve a desafiarnos. Acaba rápidamente con sus ambiciones impuras.', '', 25549),
(133750, 'esMX', 'Otro enemigo reducido a cenizas.', '', 25549),
(133749, 'esMX', 'Un maligno en llamas aterroriza a nuestros aliados en los fosos. Acaba con esta amenaza de inmediato.', '', 25549),
(133748, 'esMX', 'Uno por uno, les demostraremos que sus esfuerzos son inútiles.', '', 25549),
(133747, 'esMX', 'Otro demonio espera tu sentencia. Encuéntralo y ponle fin a su existencia.', '', 25549),
(133746, 'esMX', '', 'Dame un momento. Intentaré explicarlo lo mejor posible...', 25549),
(133744, 'esMX', '', 'Debo saberlo, Vereesa. ¿Qué fue lo que le sucedió a nuestra hermana?', 25549),
(133743, 'esMX', '', 'Eso no es todo. Yo... No sé bien cómo explicarlo. O si este es el momento y el lugar para...', 25549),
(133740, 'esMX', '', '¡Imposible! Me rehúso a creer que ahora lidera la Horda. No después de todo lo que le hicieron a nuestro pueblo durante la guerra.', 25549),
(133739, 'esMX', '', 'Carga a Thas''dorah con orgullo. Has probado ser digno de él.', 25549),
(133738, 'esMX', '', 'Quizás un día necesite el arma de mi familia otra vez. Pero por el momento, debo seguir un camino diferente.', 25549),
(133737, 'esMX', '', 'Está claro que tus habilidades y tu astucia están a la altura de Thas''dorah. Honras el arco y la memoria de aquellos que lo cargaron antes.', 25549),
(133736, 'esMX', '', 'Vereesa me contó que la acompañaste en su misión a Niskara y que arriesgaste tu vida para rescatarme. También me dijo que la salvaste de caer en la trampa del inquisidor.', 25549),
(133735, 'esMX', '', 'Quiero hablar contigo, $GMaestro:Maestra; de la Caza.', 25549),
(133734, 'esMX', '<Activador de la sentencia de la Luz>', '<Activador de la sentencia de la Luz>', 25549),
(133733, 'esMX', '<Corazón vil de Argus>', '<Corazón vil de Argus>', 25549),
(133677, 'esMX', 'Teletransportando', 'Teletransportando', 25549),
(133673, 'esMX', 'Excelente. Es hora de adueñarnos de nuestro destino.', '', 25549),
(133671, 'esMX', 'Nuestas fuerzas han asegurado una posición en la ciudadela, Alto exarca.', '', 25549),
(133655, 'esMX', 'No estás a la altura.', '', 25549),
(133654, 'esMX', 'Incompetente. Tu arrogancia fue tu perdición.', '', 25549),
(133653, 'esMX', '', 'Tal como pensé.', 25549),
(133652, 'esMX', 'Contemplando', 'Contemplando', 25549),
(133651, 'esMX', 'Ca-cu-caaa', '', 25549),
(133650, 'esMX', 'Ca-cuu chi-choo', '', 25549),
(133649, 'esMX', 'Cu-cú ca-craaa', '', 25549),
(133647, 'esMX', 'Pa-ca chi-cho-caaaa', '', 25549),
(133642, 'esMX', '¡A la batalla!', '', 25549),
(133641, 'esMX', '¡Pheta vi acahachi!', '', 25549),
(133640, 'esMX', '¡Krypta!', '', 25549),
(133639, 'esMX', '¡Acalah pek ecta!', '', 25549),
(133637, 'esMX', '¡Por los caídos!', '', 25549),
(133636, 'esMX', '¡Por nuestro pueblo!', '', 25549),
(133635, 'esMX', 'Atacaremos desde las sombras.', '', 25549),
(133634, 'esMX', 'Pagarás por tus acciones.', '', 25549),
(133631, 'esMX', 'Él... necesita que veamos algo...', '', 25549),
(133630, 'esMX', 'Pero con Argus es diferente. Está atormentado... quebrado. ¡Cuidado, o su dolor te abrumará!', '', 25549),
(133629, 'esMX', 'Cuando el espíritu de Azeroth me habla, es como una canción. Me transmite belleza, aunque su mensaje no sea precisamente claro.', '', 25549),
(133628, 'esMX', 'Los susurros de la piedra sosiegan el corazón de mi pueblo. Es curioso que tú también los oigas.', '', 25549),
(133627, 'esMX', 'Argus estará orgulloso de ustedes. Tomen su premio.', '', 25549),
(133626, 'esMX', '¡Cuando quieras!', '¡Cuando quieras!', 25549),
(133625, 'esMX', 'Estoy listo. ¡Intentémoslo otra vez!', 'Estoy lista. ¡Intentémoslo otra vez!', 25549),
(133624, 'esMX', '', '', 25549),
(133623, 'esMX', 'Lideraré a nuestras fuerzas para establecer una base fuera de la fortaleza de la Legión, mientras tú hablas con Magni.', '', 25549),
(133622, 'esMX', 'Estoy tan cansado.', 'Estoy tan cansada.', 25549),
(133621, 'esMX', 'Esta oscuridad... Creí que...   la Luz…', 'Esta oscuridad... Creí que...', 25549),
(133620, 'esMX', 'Velen... ¿por qué?', 'Velen... ¿por qué?', 25549),
(133619, 'esMX', 'No podíamos escapar.', 'No podíamos escapar.', 25549),
(133618, 'esMX', 'Debí haber... huido...', 'Debí haber... huido...', 25549),
(133617, 'esMX', '¿Cuándo terminará esto?', '¿Cuándo terminará esto?', 25549),
(133616, 'esMX', '¡No me atormentarás!', '¡No me atormentarás!', 25549),
(133615, 'esMX', '¿Por qué no nos dejas descansar?', '¿Por qué no nos dejas descansar?', 25549),
(133614, 'esMX', '¡Este es nuestro hogar! ¡Lárgate!', '¡Este es nuestro hogar! ¡Lárgate!', 25549),
(133613, 'esMX', '¡No te burles de mi sufrimiento!', '¡No te burles de mi sufrimiento!', 25549),
(133612, 'esMX', '¡No deberías estar aquí!', '¡No deberías estar aquí!', 25549),
(133611, 'esMX', '¿Por qué has venido?', '¿Por qué has venido?', 25549),
(133604, 'esMX', '', 'Redimiremos nuestro hogar.', 25549),
(133603, 'esMX', '', 'Nuestras espadas y hechizos están listos para servir a la Luz.', 25549),
(133602, 'esMX', '', 'Con la preparación adecuada, todo es un arma.', 25549),
(133601, 'esMX', '', '¡Dirígete a las baterías y empieza a disparar contra esos murciélagos! ¡Contamos contigo!', 25549),
(133600, 'esMX', '', '¡Tú! Tú no eres un demonio. ¡Ven y ayúdame a acabar con ellos!', 25549),
(133599, 'esMX', '', 'Archenon poros.', 25549),
(133598, 'esMX', '', 'Derrotaremos a la Legión.', 25549),
(133597, 'esMX', '', 'No bajes la guardia.', 25549),
(133596, 'esMX', '', 'Saludos.', 25549),
(133595, 'esMX', '', '¿Tienes algo que informar?', 25549),
(133594, 'esMX', '', 'Ganaremos esta guerra.', 25549),
(133593, 'esMX', '', 'La Luz prevalece.', 25549),
(133592, 'esMX', '', 'Estamos haciendo todo lo posible por defender el frente. ¡Encuentra a Y''mera y cambiemos el curso de la batalla!', 25549),
(133590, 'esMX', '¡Krona ki cristorr!', '', 25549),
(133589, 'esMX', 'Golad niton acalah.', '', 25549),
(133588, 'esMX', 'Acheon kor.', '', 25549),
(133587, 'esMX', 'Debemos resistir juntos.', '', 25549),
(133586, 'esMX', 'Ve en paz.', '', 25549),
(133585, 'esMX', 'Me has ayudado a asegurar el futuro de nuestro pueblo.', '', 25549),
(133584, 'esMX', 'Que la Luz nos guíe.', '', 25549),
(133583, 'esMX', 'Muchas gracias, $n.', '', 25549),
(133577, 'esMX', 'Permíteme presentarme. Soy el magnífico Al''Abas. Me encuentro temporalmente indispuesto en este recipiente decrépito. ¿Serías tan amable de escuchar mi relato?', '', 25549),
(133549, 'esMX', '', 'Tal vez no pueda ayudarte directamente, pero tengo información que podría interesarte.', 25549),
(133542, 'esMX', '', 'Qué generoso de tu parte.', 25549),
(133541, 'esMX', 'Tú, Y''mera, no serás parte de esto. Pero no te negaré la oportunidad de ver el fracaso de $n.', '', 25549),
(133535, 'esMX', '', '<Y''mera manipula el Sigilo con cautela.>$b$bMe siento muy expuesta con esta reliquia en la mano.', 25549),
(133533, 'esMX', '', 'Quoram y yo tenemos... una historia en común.$b$bSolo digamos que no abandoné el Conservatorio en los mejores términos.', 25549),
(133531, 'esMX', 'También debo permitir que los novatos participen.', '', 25549),
(133529, 'esMX', 'Tengo la obligación de informarte que el amo diseñó estos desafíos específicamente para este propósito.', '', 25549),
(133528, 'esMX', 'El Sigilo es el honor más grande del Conservatorio. Solo los elegidos de Archimonde pueden obtener este galardón.', '', 25549),
(133525, 'esMX', '', 'De todos los que podían convertirse en Ujier... $n, quizás tú debas encargarte de la charla.', 25549),
(133524, 'esMX', 'Los recursos del Conservatorio no están disponibles para alguien de tu... clase.', '', 25549),
(133523, 'esMX', 'Yo... debo regresar con mi pueblo de inmediato.', '', 25549),
(133522, 'esMX', '¡Nuestra lucha no termina aquí!', '', 25549),
(133521, 'esMX', '¡Debemos largarnos antes de que sea demasiado tarde!', '', 25549),
(133520, 'esMX', '¡Actúa rápido, antes de que los fosos te consuman!', '', 25549),
(133519, 'esMX', 'Muchas gracias. Encontraré mi camino.', '', 25549),
(133518, 'esMX', 'La oscuridad supera a la Luz.', '', 25549),
(133517, 'esMX', '¡Este lugar no es seguro!', '', 25549),
(133508, 'esMX', '', 'Necesitaré tu ayuda. ¿Por qué no lo sacudes un poco?', 25549),
(133486, 'esMX', '¡Ahora estás usando |TInterface\\ICONS\\Achievement_ChallengeMode_Auchindoun_Hourglass.blp:32|t [Robo de tiempo]!', '¡Ahora estás usando |TInterface\\ICONS\\Achievement_ChallengeMode_Auchindoun_Hourglass.blp:32|t [Robo de tiempo]!', 25549),
(133485, 'esMX', 'Esos corceles son vitales para nuestra batalla contra los demonios. Te agradezco que los hayas mantenido a salvo.', '', 25549),
(133484, 'esMX', 'Las vidas y las almas de mi pueblo están a salvo, gracias a ti.', '', 25549),
(133483, 'esMX', 'Ahora, los caídos pueden descansar.', '', 25549),
(133482, 'esMX', '', '|TInterface\\Icons\\INV_MISC_AMMO_ARROW_03:20|t¡%s marca a los enemigos con |cFFFF0000|Hspell:230139|h[Disparo de hidra]|h|r!', 25549),
(133454, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(133453, 'esMX', '|TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(133452, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(133451, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 25549),
(133442, 'esMX', 'Se acabó el tiempo.', 'Se acabó el tiempo.', 25549),
(133440, 'esMX', '', '¡Basta! ¡Hasta aquí llegó su intromisión, mortales!', 25549),
(133436, 'esMX', 'Sus habilidades no les bastarán para salvarse.', '', 25549),
(133435, 'esMX', 'Puede que hayan soportado las llamas, pero no sobrevivirán a mi furia.', '', 25549),
(133434, 'esMX', '¡El poder de Taeshalach los consumirá!', '', 25549),
(133433, 'esMX', '¡Contemplen el poder de Taeshalach!', '', 25549),
(133431, 'esMX', '¡El fuego les arrancará la carne de los huesos!', '', 25549),
(133427, 'esMX', '¡Las llamas los consumirán!', '', 25549),
(133426, 'esMX', 'No hay escapatoria.', '', 25549),
(133425, 'esMX', '¡Enfréntense a su muerte!', '', 25549),
(133424, 'esMX', '¡Mataré a quien se interponga!', '', 25549),
(133422, 'esMX', '¡Las llamas los sofocarán!', '', 25549),
(133420, 'esMX', '', 'Esperaba que funcionase. Las luces están encendidas pero no hay respuesta.', 25549),
(133419, 'esMX', '¡Ardan!', '', 25549),
(133418, 'esMX', '¡Nadie sobrevive al poder de Taeshalach!', '', 25549),
(133417, 'esMX', 'Tal vez... sea demasiado tarde para detenerlo...', '', 25549),
(133416, 'esMX', 'No tenían posibilidad de ganar. ¡Es imposible detener nuestra cruzada!', '', 25549),
(133414, 'esMX', 'Un enemigo insignificante.', '', 25549),
(133408, 'esMX', '¡Muere, mortal inservible!', '', 25549),
(133399, 'esMX', '|TINTERFACE\\ICONS\\INV_STONE_05.BLP:20|t ¡Tu Piedra de falla agotada se ha convertido en una |cFFFF0000|Hitem:151702|h[Piedra de falla cargada]|h|r!', '|TINTERFACE\\ICONS\\INV_STONE_05.BLP:20|t ¡Tu Piedra de falla agotada se ha convertido en una |cFFFF0000|Hitem:151702|h[Piedra de falla cargada]|h|r!', 25549),
(133398, 'esMX', 'Recoger una piedra de falla agotada.', 'Recoger una piedra de falla agotada.', 25549),
(133397, 'esMX', 'Obtendrás este objeto en una próxima serie de misiones. Por ahora, ¡puedes encontrarlo en el suelo!', '', 25549),
(133394, 'esMX', '¡Arderán!', '', 25549),
(133391, 'esMX', 'Ustedes son la corrupción. Borraremos todo recuerdo de su existencia para salvar el universo.', '', 25549),
(133390, 'esMX', 'Esas eran todas las fallas que había por el momento, aunque seguramente veamos más en el futuro.', '', 25549),
(133388, 'esMX', 'La crueldad de la Legión también recae sobre sus propios integrantes. Destruye a esta abominación y cierra la falla que conecta nuestros mundos.', '', 25549),
(133386, 'esMX', 'Mortales. Desperdicié milenios combatiendo para protegerlos de la corrupción. Hasta que al fin mis ojos vieron la verdad.', '', 25549),
(133385, 'esMX', 'Por el momento, ya no llegarán refuerzos desde ese mundo.', '', 25549),
(133384, 'esMX', 'La flota de la Legión se reúne. ¡Frustra sus preparativos y cierra la falla antes de que lleguen a Argus!', '', 25549),
(133383, 'esMX', 'Cada falla que cerramos representa un poco más de tiempo a nuestro favor. La Luz te acompaña, $Gcampeón:campeona;.', '', 25549),
(133382, 'esMX', 'Otro mundo profanado por la Legión. ¡Destruye sus fuerzas y cierra esta falla antes de que puedan unirse a la batalla en Argus!', '', 25549),
(133381, 'esMX', '', '¡Campeones! ¡Por aquí!', 25549),
(133378, 'esMX', '¡Ja! Un tributo digno de las enseñanzas de mi Conservatorio.', '', 25549),
(133377, 'esMX', 'La tenacidad no es nada contra mi voluntad. Los destruiré.', '', 25549),
(133376, 'esMX', 'Se creen muy astutos por haber llegado tan lejos. Pero yo sé cómo terminará todo.', '', 25549),
(133375, 'esMX', 'Tantos se han presentado ante mí, y tantos han fracasado.', '', 25549),
(133373, 'esMX', 'Debo admitir que estas pruebas ofrecen un entretenimiento interminable... para mí.', '', 25549),
(133367, 'esMX', '', 'Este ensamblaje debería contener información para ayudarnos a encontrar el Sigilo del despertar. Debemos despertarlo.', 25549),
(133366, 'esMX', '', 'Tengo toda mi fe puesta en ti, $n. Estaré cerca cuando termines.', 25549),
(133363, 'esMX', 'Quizás.', '', 25549),
(133362, 'esMX', '', 'No puedo poner una pezuña en el Pretorio. Pero ya lo sabías, ¿no?', 25549),
(133358, 'esMX', 'Lah''zaruun, mi leal sirviente. Quédate aquí y mata a estos tontos. Tengo mucho por hacer.', '', 25549),
(133352, 'esMX', 'Me temo que no puedo permitir eso, $n.', '', 25549),
(133347, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t La Señora Alluradel empieza a lanzar |cFFFF0404|Hspell:247551|h[Encantamiento cautivador]|h|r. ¡Mira hacia otro lado!', '|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t La Señora Alluradel empieza a lanzar |cFFFF0404|Hspell:247551|h[Encantamiento cautivador]|h|r. ¡Mira hacia otro lado!', 25549),
(133335, 'esMX', '', 'Perfecto. Seguiremos nuestro camino.', 25549),
(133334, 'esMX', '', 'Siento el poder en el aire. Sigue aquí, después de todo este tiempo.', 25549),
(133332, 'esMX', '¡Revisión de código exitosa!', '', 25549),
(133331, 'esMX', '¡Energía principal activada!', '', 25549),
(133330, 'esMX', '¡Robots de Bert derrotados!', '', 25549),
(133328, 'esMX', '¡Claramente falta un punto y coma en el código!', '', 25549),
(133327, 'esMX', '¡Robots de Bert vapulean vándalos!', '', 25549),
(133326, 'esMX', '¡Justicia ambiental!', '', 25549),
(133324, 'esMX', '¡Mis robots y yo limpiaremos Gnomeregan!\n\nClaro que aún no he terminado de ajustar los detalles tecnológicos. En este momento puedo hacer que los pequeñines absorban las emanaciones tóxicas, pero todo lo que producen es más emanaciones tóxicas.\n\nAdemás, todo se vuelve verde y borroso. En realidad no está mal, me ayuda a concentrarme en mi trabajo.\n\nEntonces, ¿qué puedo hacer hoy por ti, mi $Gbuen amigo:buena amiga; trogg?\n\n<Bert levanta la cabeza y mira levemente a tu izquierda.>', '', 25549),
(133323, 'esMX', 'Busco el Sigilo del despertar.', 'Busco el Sigilo del despertar.', 25549),
(133322, 'esMX', 'Explica tu presencia aquí o márchate de este lugar.', '', 25549),
(133320, 'esMX', '', 'Necesitamos...', 25549),
(133313, 'esMX', 'Empecemos.', '', 25549),
(133309, 'esMX', 'Exiliada Y''mera. ¿Por qué regresaste?', '', 25549),
(133308, 'esMX', '', 'Oh, no... Conozco esa voz.', 25549),
(133307, 'esMX', 'Estoy recuperado.', '', 25549),
(133299, 'esMX', '¡El enemigo quiere cerrar nuestra falla! ¡A las armas!', '¡El enemigo quiere cerrar nuestra falla! ¡A las armas!', 25549),
(133296, 'esMX', 'Perdí el antídoto. ¿Lo recogiste tú?', 'Perdí el antídoto. ¿Lo recogiste tú?', 25549),
(133293, 'esMX', '', '¡La Alianza organizará la gran carrera de Gnomeregan en Nueva Ciudad Manitas muy pronto!', 25549),
(133292, 'esMX', '', '¡La Alianza está celebrando la gran carrera de Gnomeregan en Nueva Ciudad Manitas!', 25549),
(133291, 'esMX', '', '¡La gran carrera de Gnomeregan está en curso en Nueva Ciudad Manitas en este preciso instante!', 25549),
(133290, 'esMX', '', '¡La gran carrera de Gnomeregan está en curso en Nueva Ciudad Manitas en este preciso instante! ¡¿Crees que puedes lograr una nueva marca personal?!', 25549),
(133289, 'esMX', '', '¡No te olvides de hidratarte bien y descansar para la gran carrera de Gnomeregan! ¡Comenzará en Nueva Ciudad Manitas muy pronto!', 25549),
(133288, 'esMX', '', '¿Has entrenado? ¡La gran carrera de Gnomeregan está por comenzar!', 25549),
(133287, 'esMX', 'ADVERTENCIA: Estás por consumir las cenizas de un hechicero malvado. No hay forma de saber lo que sucederá. ¿Estás ABSOLUTAMENTE $Gseguro:segura; de que quieres hacer esto?', '', 25549),
(133286, 'esMX', '<Consumir las cenizas.>', '<Consumir las cenizas.>', 25549),
(133285, 'esMX', 'Las runas de esta urna indican que contiene algunos restos de un poderoso ligaespíritus mogu. Muchas de las marcas parecen ser advertencias.', '', 25549),
(133280, 'esMX', 'Imbuyendo', 'Imbuyendo', 25549),
(133268, 'esMX', 'La Legión ha abierto portales para invadir el Arcatraz. Ciérralos... antes de que sus tropas te rodeen.', '', 25549),
(133257, 'esMX', 'Haremos todo lo posible.', '', 25549),
(133256, 'esMX', '', 'Hemos estado en peores situaciones. Defenderé esta posición.', 25549),
(133255, 'esMX', 'Lothraxion quedará a cargo si no regresamos. Mantente alerta, Fareeya.', '', 25549),
(133246, 'esMX', 'Mis llamas nunca se apagarán...', '', 25549),
(133245, 'esMX', '¡Sus cenizas se esparcirán por todo el cosmos!', '', 25549),
(133244, 'esMX', '', 'Ah... El sabor... de su carne derretida...', 25549),
(133243, 'esMX', '', 'Acérquense, héroes, ¡para que pueda observar cómo la carne se les desprende de los huesos!', 25549),
(133242, 'esMX', 'La Luz no los salvará...', '', 25549),
(133241, 'esMX', '¡Es tan fácil nublar sus mentes!', '', 25549),
(133238, 'esMX', '|TInterface\\Icons\\ABILITY_ROGUE_SHADOWSTEP:20|t¡Saprish se prepara para atacarte con |cFFFF0000|Hspell:247246|h[Flanqueo umbrío]|h|r!', '|TInterface\\Icons\\ABILITY_ROGUE_SHADOWSTEP:20|t¡Saprish se prepara para atacarte con su |cFFFF0000|Hspell:247246|h[Flanqueo umbrío]|h|r!', 25549),
(133237, 'esMX', '¡Eliminen a la cría de dragón! ¡Por la Horda!', '¡Eliminen a la cría de dragón! ¡Por la Horda!', 25549),
(133236, 'esMX', '¡Eliminen a la cría de dragón! ¡En nombre de la Alianza!', '¡Eliminen a la cría de dragón! ¡En nombre de la Alianza!', 25549),
(133235, 'esMX', '', 'Dragona inteligente. ¡Te he capturado una vez y volveré a hacerlo!', 25549),
(133234, 'esMX', '¡Abran los portales! ¡Destruyan a la dragona de bronce! ¡Que no escape!', '', 25549),
(133233, 'esMX', '¡Tus días de juguetear con el tiempo han llegado a su fin, mocosa!', '', 25549),
(133232, 'esMX', 'Los fríos dedos de la muerte se cierran alrededor de las escamas de tu cuello, dragona.', '', 25549),
(133231, 'esMX', 'Contempla tu perdición, mocosa. Tus cronoviajes han llegado a su fin.', '', 25549),
(133230, 'esMX', 'Qué extraño. ¿Qué haces TÚ aquí?', '', 25549),
(133229, 'esMX', '¡Ahí viene la dragona! ¡Asesínenla!', '', 25549),
(133228, 'esMX', '¡Ríndete, vermis!', '', 25549),
(133227, 'esMX', '', 'La muerte viene por ti, pequeña dragona...', 25549),
(133226, 'esMX', '¡Panzachancro comer tonta dragona!', '', 25549),
(133225, 'esMX', '', 'Impresionante. La Legión no esperará encontrarse con un ejército de esta magnitud.', 25549),
(133222, 'esMX', 'El Profeta Velen estará complacido de que respondas a su llamado. Los draenei hemos esperado mucho por este día.', '', 25549),
(133221, 'esMX', '', 'La Legión ha esparcido su corrupción en Azeroth durante demasiado tiempo. Llegó la hora de ponerle fin a todo esto.', 25549),
(133220, 'esMX', '', 'Juntos, nos encargaremos de que la Legión llegue a su fin.', 25549),
(133219, 'esMX', '<Recordar la derrota de Kil''Jaeden>', '<Recordar la derrota de Kil''Jaeden>', 25549),
(133218, 'esMX', '<Recuerda cuando Anduin recuperó a Shalamayne>', '<Recuerda cuando Anduin recuperó a Shalamayne>', 25549),
(133217, 'esMX', '<Recuerda la apertura de la Tumba de Sargeras>', '<Recuerda la apertura de la Tumba de Sargeras>', 25549),
(133216, 'esMX', '<Recuerda el ataque de Kil''Jaeden sobre Dalaran>', '<Recuerda el ataque de Kil''Jaeden sobre Dalaran>', 25549),
(133215, 'esMX', '¿AL''KSH SYR IIR AWAN? IILTH SYTHN AGEV.', '¿AL''KSH SYR IIR AWAN? IILTH SYTHN AGEV.', 25549),
(133210, 'esMX', '¡La falla colapsa, héroes! ¡Apúrense antes de que la entrada quede sellada para siempre!', '', 25549),
(133209, 'esMX', '¡Murciélagos viles comienzan a volar hacia la plataforma de Eonar!', '¡Murciélagos viles comienzan a volar hacia la plataforma de Eonar!', 25549),
(133208, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(133206, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(133205, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(133203, 'esMX', '|TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(133202, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t ¡Un Ascua de Taeshalach se sobrecarga y genera una |cFFFF0404|Hspell:244912|h[Erupción llameante]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t ¡Un Ascua de Taeshalach se sobrecarga y genera una |cFFFF0404|Hspell:244912|h[Erupción llameante]|h|r!', 25549),
(133196, 'esMX', '', 'Este lugar está maldito. Brindemos un poco de Luz a estas pobres almas.', 25549),
(133195, 'esMX', '<Aceptar el cristal.>', '<Aceptar el cristal.>', 25549),
(133194, 'esMX', '', '<Enaara te ofrece un cristal de oro forjado.>$b$bDeshazte de la oscuridad, $n. La Luz debe prevalecer.', 25549),
(133193, 'esMX', '', 'Tal vez no podamos devolverles la cordura, pero al menos podemos impedir que sucumban aún más.', 25549),
(133192, 'esMX', '', 'A pesar de nuestros esfuerzos, el vacío sigue filtrándose por las grietas. Busca al Ejército de la Luz y usa sus bendiciones para desterrar la oscuridad una vez más.', 25549),
(133191, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(133190, 'esMX', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 25549),
(133189, 'esMX', 'ADVERTENCIA: Estás por caer a una fisura oscura. Es posible que no puedas volver a la superficie. ¿Estás absolutamente $Gseguro:segura; de que quieres hacer esto?', '', 25549),
(133188, 'esMX', '<Saltar a la fisura.>', '<Saltar a la fisura.>', 25549),
(133187, 'esMX', '<Una fisura en el suelo, apenas lo suficientemente grande para pasar. Está muy oscuro como para ver algo, pero te das cuenta de que es muy profunda.>', '', 25549),
(133186, 'esMX', '', '¡La ira de la Legión los abrumará!', 25549),
(133185, 'esMX', '', '¡Nuestras fuerzas son infinitas!', 25549),
(133184, 'esMX', '', '¡En todo el universo, las fuerzas de la Legión responden a mis órdenes!', 25549),
(133183, 'esMX', '', '¡Es el fin de su resistencia!', 25549),
(133182, 'esMX', '', 'La Legión ha devastado miles de mundos. El suyo no será la excepción.', 25549),
(133181, 'esMX', '', 'Azeroth caerá igual que ustedes.', 25549),
(133180, 'esMX', '', '¿Eran estos los guerreros más fuertes de Azeroth?', 25549),
(133179, 'esMX', '', 'Te rompes tan fácilmente.', 25549),
(133178, 'esMX', '', 'Más huesos para mi colección.', 25549),
(133177, 'esMX', '', '¡Aprenderás a comportarte!', 25549),
(133176, 'esMX', '', 'Su mundo caerá...', 25549),
(133175, 'esMX', '', 'No... puede... ser...', 25549),
(133174, 'esMX', '', 'Los portales... deben... prevalecer...', 25549),
(133173, 'esMX', '', 'Nathreza... Otrora un mundo mágico y de vastos conocimientos, ahora es una zona corrompida de la que nadie logra escapar.', 25549),
(133172, 'esMX', '', '¡Contemplen Rancora y sus charcos purulentos, donde la muerte acecha a cada paso!', 25549),
(133171, 'esMX', '', 'Contemplen Xoroth, ¡un mundo de llamas infernales y huesos calcinados!', 25549),
(133170, 'esMX', '', '¡Desgarren su carne!', 25549),
(133169, 'esMX', '', '¡Nadie debe quedar con vida!', 25549),
(133168, 'esMX', '', '¡Que caigan todos!', 25549),
(133167, 'esMX', '', '¡Observen un poder capaz de destruir mundos enteros!', 25549),
(133166, 'esMX', '', 'Hemos conquistado todos los mundos a nuestro paso. El suyo es el próximo.', 25549),
(133165, 'esMX', '', 'Presencien el destino de aquellos que se nos oponen.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(133164, 'esMX', '', 'Hasta aquí llegó su guerra.', 25549),
(133163, 'esMX', '', 'He ralentizado el tiempo lo suficiente para prepararnos sin perder tiempo valioso.$b$b¡Avísame cuando estés $Glisto:lista; para partir!', 25549),
(133162, 'esMX', '', '¿Es esto todo lo que tienen para dar? Ja. Patético.', 25549),
(133160, 'esMX', '', '¡La Legión extermina a todos sus oponentes!', 25549),
(133146, 'esMX', '|TInterface\\ICONS\\ABILITY_WARLOCK_BACKDRAFTGREEN.BLP:20|t ¡Ubícate dentro de las áreas de impacto de |cFFF00000|Hspell:244761|h[Aniquilación]|h|r para evitar daños en toda la banda!', '', 25549),
(133145, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 25549),
(133135, 'esMX', 'Insertando larva mental', 'Insertando larva mental', 25549),
(133121, 'esMX', '', '¿Cromi necesita nuestra ayuda? La tendrá. Distraeremos a los cañones para que pueda escapar a salvo.', 25549),
(133119, 'esMX', 'Necesitamos que los druidas distraigan a los cañones que están en el exterior para que una dragona de bronce pueda escapar de Andorhal.', 'Necesitamos que los druidas distraigan a los cañones que están en el exterior para que una dragona de bronce pueda escapar de Andorhal.', 25549),
(133118, 'esMX', '', 'Aquí... ¡aquí dice que tienes órdenes directas del mismísimo Guardián Remulos! Muy bien, ¿cuáles son las órdenes, $n?', 25549),
(133117, 'esMX', '<Presenta los documentos del Círculo Cenarion.>', '<Presenta los documentos del Círculo Cenarion.>', 25549),
(133116, 'esMX', '', 'El Círculo Cenarion no se quedará de brazos cruzados mientras los soldados de la Horda y la Alianza se masacran. Si puedo ayudar a algunos soldados heridos, estaré complacido.', 25549),
(133110, 'esMX', 'Si tan solo pudiéramos observar su tormento cuando regrese a Antorus. Sargeras no se toma el fracaso a la ligera.', '', 25549),
(133109, 'esMX', 'Talestra, la doncella de la fatalidad man''ari, está intentando reunir un ejército de malignos. Encárgate de frustrar sus planes.', '', 25549),
(133107, 'esMX', 'La Legión no se detendrá hasta destruir nuestro mundo. Esta derrota debería servirles de lección.', '', 25549),
(133106, 'esMX', 'Un demonio se atreve a liderar un asalto contra el Vindicaar. Una muerte rápida dejará en evidencia la estupidez de su maestro.', '', 25549),
(133105, 'esMX', 'Estoy listo. ¡Vamos a salvarte la vida!\n|cFF0000FF(Iniciar la gesta).|r', 'Estoy lista. ¡Vamos a salvarte la vida!\n|cFF0000FF(Iniciar la gesta).|r', 25549),
(133098, 'esMX', 'Un transportador de tropas y un crucero de la Legión se materializan encima de la entrada superior del templo.', 'Un transportador de tropas y un crucero de la Legión se materializan encima de la entrada superior del templo.', 25549),
(133097, 'esMX', 'Un transportador de tropas y un crucero de la Legión se materializan encima de la entrada inferior.', 'Un transportador de tropas y un crucero de la Legión se materializan encima de la entrada inferior.', 25549),
(133096, 'esMX', 'Un transportador de tropas y un crucero de la Legión se materializan encima de la entrada principal.', 'Un transportador de tropas y un crucero de la Legión se materializan encima de la entrada principal.', 25549),
(133095, 'esMX', 'Revivir los últimos momentos de cordura de sus vidas atribuladas es una tarea aciaga. Pero es la mejor y única forma de honrarlos. Gracias por tu ayuda.', '', 25549),
(133094, 'esMX', 'Tenemos muchas incógnitas sobre el descenso de mis hermanos a la locura aquí en Mac''Aree. Tráeme todos los cristales de recuerdos que encuentres y continuaré con mi investigación.', '', 25549),
(133093, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 25549),
(133092, 'esMX', '|TInterface\\Icons\\INV_FelbatMount.blp:24|t', '|TInterface\\Icons\\INV_FelbatMount.blp:24|t', 25549),
(133091, 'esMX', '|TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 25549),
(133090, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 25549),
(133089, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 25549),
(133088, 'esMX', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t', 25549),
(133087, 'esMX', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t', 25549),
(133086, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t', 25549),
(133083, 'esMX', 'Un crucero de la Legión se materializa encima de la entrada superior del templo.', 'Un crucero de la Legión se materializa encima de la entrada superior del templo.', 25549),
(133082, 'esMX', 'Un crucero de la Legión se materializa encima de la entrada inferior.', 'Un crucero de la Legión se materializa encima de la entrada inferior.', 25549),
(133081, 'esMX', 'Un crucero de la Legión se materializa encima de la entrada principal.', 'Un crucero de la Legión se materializa encima de la entrada principal.', 25549),
(133080, 'esMX', 'Un transportador de tropas de la Legión se materializa encima de la entrada superior del templo.', 'Un transportador de tropas de la Legión se materializa encima de la entrada superior del templo.', 25549),
(133079, 'esMX', 'Un transportador de tropas de la Legión se materializa encima de la entrada inferior.', 'Un transportador de tropas de la Legión se materializa encima de la entrada inferior.', 25549),
(133078, 'esMX', 'Un transportador de tropas de la Legión se materializa encima de la entrada principal.', 'Un transportador de tropas de la Legión se materializa encima de la entrada principal.', 25549),
(133077, 'esMX', '|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t¡Si permaneces demasiado cerca de |cFFFF0000|Hspell:234621|h[Fauces devoradoras]|h|r hará que se lance |cFFFF0000|Hspell:232885|h[Devorar entero]|h|r!', '', 25549),
(133076, 'esMX', 'Veo que ya te has encargado de los santuarios de dragones. Por favor, acepta la bendición del vuelo bronce.', '', 25549),
(133075, 'esMX', 'No te preocupes por el ataque del Santuario de Dragones rubí. Yo me encargaré del exánime.', '', 25549),
(133074, 'esMX', 'No te preocupes por el ataque del Santuario de Dragones esmeralda. Yo me encargaré del sátiro.', '', 25549),
(133073, 'esMX', 'No te preocupes por el ataque del Santuario de Dragones obsidiana. Yo me encargaré del señor del terror.', '', 25549),
(133072, 'esMX', 'No te preocupes por el ataque del Santuario de Dragones azur. Yo me encargaré del coloso del vacío.', '', 25549),
(133068, 'esMX', '<Bajar la palanca.>', '<Bajar la palanca.>', 25549),
(133067, 'esMX', '<Levantar la palanca.>', '<Levantar la palanca.>', 25549),
(133063, 'esMX', 'La consola muestra el número 9.', '', 25549),
(133062, 'esMX', 'La consola muestra el número 8.', '', 25549),
(133061, 'esMX', 'La consola muestra el número 7.', '', 25549),
(133060, 'esMX', 'La consola muestra el número 6.', '', 25549),
(133059, 'esMX', 'La consola muestra el número 5.', '', 25549),
(133058, 'esMX', 'La consola muestra el número 4.', '', 25549),
(133057, 'esMX', 'La consola muestra el número 3.', '', 25549),
(133056, 'esMX', 'La consola muestra el número 2.', '', 25549),
(133052, 'esMX', 'Mientras la Legión usurpa los campos de caza de los pantharas, las bestias hambrientas se han vuelto más agresivas. Reduce sus números antes de que arrasen con nuestras manadas de talbuks.', '', 25549),
(133051, 'esMX', 'Estos demonios capturan a mi pueblo y lo someten a rituales atroces. Ya no nos perseguirán. ¡Ayúdanos a combatir la Legión!', '', 25549),
(133050, 'esMX', 'Están usando a nuestro pueblo como combustible para sus rituales viles. Destruye a estas creaciones monstruosas y ayúdanos a honrar los cuerpos de nuestros caídos.', '', 25549),
(133049, 'esMX', 'Cuéntame lo que sabes sobre la piedra.', 'Cuéntame lo que sabes sobre la piedra.', 25549),
(133034, 'esMX', 'El tiempo es vital. No podemos dejar que la Legión capture al Profeta.', '', 25549),
(133033, 'esMX', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t¡Una grieta del Vacío ha aparecido en los Cimientos del templo!', '', 25549),
(133032, 'esMX', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t¡Una grieta del Vacío ha aparecido en el Mirador en ruinas!', '', 25549),
(133031, 'esMX', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t¡Una grieta del Vacío ha aparecido en la Brecha del Vacío inferior!', '', 25549),
(133030, 'esMX', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t¡Una grieta del Vacío ha aparecido en la Brecha del Vacío superior!', '', 25549),
(133029, 'esMX', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t¡Una grieta del Vacío ha aparecido en la Puerta abisal inferior!', '', 25549),
(133028, 'esMX', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t¡Una grieta del Vacío ha aparecido en las Ruinas desmoronadas!', '', 25549),
(133027, 'esMX', 'Cromi ha muerto.', 'Cromi ha muerto.', 25549),
(133021, 'esMX', '', 'Tráemelo, rápido. Hemos establecido un perímetro seguro abajo.', 25549),
(133020, 'esMX', '', '¡Lo encontraste! Cuánto poder... Lo siento desde aquí.', 25549),
(133019, 'esMX', 'Ahora verán de cerca los frutos de nuestra labor. ¡Contemplen a Zuraal, el Ascendido! ¡El primero que ha aceptado el Vacío por completo!', '', 25549),
(133018, 'esMX', 'Ninguna interferencia impedirá nuestro avance. Todos servirán al Vacío o caerán en él.', '', 25549),
(133017, 'esMX', '¿Ya terminó el desafío?', '¿Ya terminó el desafío?', 25549),
(133016, 'esMX', 'Supongo que quieres que te envíe de regreso a la entrada del Conservatorio.', '', 25549),
(133015, 'esMX', 'Oh, lo lograste. Excelente.', '', 25549),
(133010, 'esMX', 'Desde luego. Así se hará, en el momento exacto que ordenó. La dragona de bronce no verá nada. Lo único que necesito es un intento desde el exterior del Santuario de Dragones obsidiana.', '', 25549),
(133000, 'esMX', 'Tu ayuda es más que bienvenida, Fareeya.', '', 25549),
(132998, 'esMX', 'Parece que esta molestia requiere un toque más personal. ¡Yo mismo me encargaré de ustedes!', '', 25549),
(132997, 'esMX', '¡Nos están acribillando! ¡Vayan y encárguense de esta incursión!', '', 25549),
(132996, 'esMX', '¡No nos expulsarán de aquí! ¡Invoquen más fuerzas del Vacío para lidiar con estos intrusos!', '', 25549),
(132995, 'esMX', '¡Idiotas! Los expulsaremos de aquí. ¡No pondrán en riesgo nuestra misión!', '', 25549),
(132973, 'esMX', 'Bien. Este desafío está terminado. Pero solo porque ya no tengo más espacio para ponerte a prueba.', '', 25549),
(132972, 'esMX', 'Por favor.', 'Por favor.', 25549),
(132971, 'esMX', 'Veo que eres muy veloz o, tal vez, muy persistente. Sin embargo, me pregunto si será suficiente para probar tu tenacidad.$b$b<Quoram emite un sonido similar a un zumbido.>', '', 25549),
(132970, 'esMX', 'Si quieres saberlo, antes fui el guardián de las llaves del Conservatorio, custodio de todas las cerraduras y puertas.$b$bPara detener el deterioro del tiempo, coloqué mi alma dentro de este ensamblaje. Y así he cuidado del Conservatorio durante toda la eternidad.$b$bSiempre tendré la carga de lidiar con personas como tú.', '', 25549),
(132962, 'esMX', 'Cuidado con las escaleras.', '', 25549),
(132960, 'esMX', 'Mantengan a los guardianes del Santuario rubí ocupados. Yo dirigiré el ataque de nuestro amo desde el interior mismo del árbol.', '', 25549),
(132959, 'esMX', 'Ahí estás...', '', 25549),
(132958, 'esMX', 'Te oigo...', '', 25549),
(132953, 'esMX', 'Trata de esquivar los rayos. Supongo que son muy dolorosos.', '', 25549),
(132951, 'esMX', 'Estoy confundido. ¿Qué dijiste antes?', 'Estoy confundida. ¿Qué dijiste antes?', 25549),
(132950, 'esMX', 'Está diseñado para matarte. Buena suerte.', '', 25549),
(132946, 'esMX', 'Lo siento, no escuché eso último. ¿Podrías repetirlo?', 'Lo siento, no escuché eso último. ¿Podrías repetirlo?', 25549),
(132936, 'esMX', 'Este desafío es muy simple. Entra y sigue hasta llegar al otro lado de la estructura.', '', 25549),
(132934, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(132929, 'esMX', '¿Estás $Glisto:lista; para comenzar el Desafío de tenacidad?', '', 25549),
(132925, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t ¡Un crucero de la Legión se prepara para liberar una |cFFFF0000|Hspell:244627|h[Descarga cerrada]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t ¡Un crucero de la Legión se prepara para liberar una |cFFFF0000|Hspell:244627|h[Descarga cerrada]|h|r!', 25549),
(132901, 'esMX', '|TInterface\\ICONS\\ABILITY_MAGE_FIRESTARTER.BLP:20|t ¡Eres el objetivo de |cFFF00000|Hspell:244410|h[Exterminación]|h|r!', '', 25549),
(132900, 'esMX', '', '¡Eliminen todas sus vías de refuerzos!', 25549),
(132899, 'esMX', '', '¡Síganme!', 25549),
(132898, 'esMX', '|TINTERFACE\\ICONS\\INV_ENCHANT_VOIDSPHERE.BLP:20|t ¡Acaba con las Imágenes del Vacío antes de que puedan lanzar |cFFFF0404|Hspell:246483|h[Desgarro del olvido]|h|r!', '|TINTERFACE\\ICONS\\INV_ENCHANT_VOIDSPHERE.BLP:20|t ¡Acaba con las Imágenes del Vacío antes de que puedan lanzar |cFFFF0404|Hspell:246483|h[Desgarro del olvido]|h|r!', 25549),
(132895, 'esMX', 'Gracias a ti, los cañones de la Legión han dejado de funcionar.', '', 25549),
(132894, 'esMX', 'ph', '', 25549),
(132892, 'esMX', 'La Legión ha acumulado grandes cantidades de municiones para usar contra nosotros. Reduce sus filas, marca las reservas como objetivos para el Vindicaar ¡y corre lo más rápido que puedas!', '', 25549),
(132875, 'esMX', 'Comencemos, Turalyon.', 'Comencemos, Turalyon.', 25549),
(132874, 'esMX', 'Con el Corazón de la Luz, podemos devolverle a Xe''ra su verdadera gloria.$b$bCuanto antes lo hagamos, antes nos volveremos más fuertes contra la Legión.', '', 25549),
(132873, 'esMX', '', 'Suficiente. Has demostrado tu valía.', 25549),
(132872, 'esMX', 'Pff... Ya hemos terminado.', '', 25549),
(132871, 'esMX', 'Supongo que eso califica como una victoria.', '', 25549),
(132870, 'esMX', 'Una tarea indigna, pero te complaceré.', '', 25549),
(132869, 'esMX', '', 'No me contendré. Empecemos.', 25549),
(132868, 'esMX', '¡Te enfrentas a Jarasum, Gran visir del Conservatorio!', '', 25549),
(132867, 'esMX', '', '<Velara te observa impasible.>\n\n¿Sí?', 25549),
(132866, 'esMX', 'Haz una reverencia antes de dirigirte al Alto heraldo.', '', 25549),
(132865, 'esMX', 'Te reto a un duelo.', 'Te reto a un duelo.', 25549),
(132864, 'esMX', 'Habla, $Gforastero:forastera;.', '', 25549),
(132863, 'esMX', '', 'El Alto heraldo Aargon. ¿Por dónde empiezo?\n\nAscendió a su posición solo después del destierro de su predecesor Thal''kiel. Pero esa historia es para otro momento, si no la conoces.\n\nNo hace falta decir que era... un oportunista.\n\nBajo su liderazgo investigamos profundamente los misterios de la vinculación de almas. Los ensamblajes que deambulan por estas calles son obra suya. Representan apenas una fracción de lo que los Heraldos pueden hacer.\n\nEn la Legión se convirtió en Aargoss. \n\nEn el Ejército de la Luz lo conocían como el Cortador de almas. Si había máquinas de alma cerca, Aargoss nunca estaba muy lejos.', 25549),
(132862, 'esMX', '', 'La Archicónsul Velara solo respondía al mismísimo Archimonde.\n\nEra una persona calma y concentrada, según recuerdo. En paralelo a la hermandad del Heraldo, lideró al Consulado en busca de los poderes de la creación.\n\nBajo su tutela mejoramos notablemente nuestra habilidad para invocar criaturas arcanas. Los familiares que permanecen aquí aún portan marcas de su pericia. También fue una de las principales responsables de desarrollar la tecnología de escudos que usamos hasta el día de hoy.\n\nAdoptó el nombre Velysra y el título de Archimaga cuando se unió a la Legión.\n\nSolo espero que nunca tengas que conocerla, $n.', 25549),
(132861, 'esMX', 'Cuéntame sobre los demás.', 'Cuéntame sobre los demás.', 25549),
(132860, 'esMX', '', 'Ah, el Gran visir.\n\nSirvió como segundo de la archicónsul y supervisó gran parte de las operaciones diarias en el Conservatorio.\n\nA la hora de ejercer disciplina, era su voz la que solía imponerse. No era de los más agradables, pero aún así lo respetaban.\n\nTengo entendido que se cambió el nombre a Jaraxxus cuando aceptó las magias viles de la Legión.\n\nMás allá de eso, no sé nada más sobre su devenir.', 25549),
(132859, 'esMX', 'Háblame de la Archicónsul Velara.', 'Háblame de la Archicónsul Velara.', 25549),
(132858, 'esMX', 'Háblame del Alto heraldo Aargon.', 'Háblame del Alto heraldo Aargon.', 25549),
(132857, 'esMX', 'Háblame del Gran visir Jarasum.', 'Háblame del Gran visir Jarasum.', 25549),
(132856, 'esMX', '', 'Sé contra quiénes pelearás.$b$bArchimonde les dio un título a cada uno como reconocimiento por sus notables conocimientos sobre ese arte.$b$bLamentablemente, todos ellos se unieron a la Legión. Es muy raro verlos en su antigua forma.', 25549),
(132855, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_ELEMENTALDEVASTATION:20|t¡Armagedón impactó contra la plataforma y provoca una |cFFFF0000|Hspell:240908|h[Explosión de armagedón]|h|r!', '|TInterface\\Icons\\SPELL_FIRE_ELEMENTALDEVASTATION:20|t¡Armagedón impactó contra la plataforma y provoca una |cFFFF0000|Hspell:|h[Explosión de armagedón]|h|r!', 25549),
(132854, 'esMX', '|TInterface\\Icons\\spell_shadow_painspike:20|t¡Estás afectado por |cFFFF0000|Hspell:233983|h[Angustia resonante]|h|r!', '|TInterface\\Icons\\spell_shadow_painspike:20|t¡Estás afectada por |cFFFF0000|Hspell:233983|h[Angustia resonante]|h|r!', 25549),
(132853, 'esMX', '|TINTERFACE\\ICONS\\ability_fixated_state_red.blp:20|t ¡Zuraal, el Ascendido se ha fijado en ti!', '', 25549),
(132852, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_PAINSPIKE:20|tA''nutsu comienza a lanzar |cFFFF0404|Hspell:245164|h[Fragmento de desesperación]|h|r', '', 25549),
(132851, 'esMX', 'El poder del sello del guardián se desvanece.', 'El poder del sello del guardián se desvanece.', 25549),
(132850, 'esMX', 'El volcán de Argus está entrando en erupción.', '', 25549),
(132829, 'esMX', '|TINTERFACE\\ICONS\\INV_KNIFE_1H_FIRELANDSRAID_D_01.BLP:20|t Aggramar comienza a utilizar una |cFFFF0404|Hspell:244688|h[Técnica de Taeshalach]|h|r!', '|TINTERFACE\\ICONS\\INV_KNIFE_1H_FIRELANDSRAID_D_01.BLP:20|t Aggramar comienza a utilizar una |cFFFF0404|Hspell:244688|h[Técnica de Taeshalach]|h|r!', 25549),
(132828, 'esMX', 'Usa esta llave para atravesar el ayuntamiento. Por aquí puedes regresar a las calles traseras de Stratholme.', '', 25549),
(132822, 'esMX', '|TINTERFACE\\ICONS\\WARLOCK_CURSE_SHADOW_AURA.BLP:20|t ¡Cuchilla del Vacío Zedaat empieza a lanzar |cFFFF0404|Hspell:246340|h[Erupción abisal]|h|r! ¡Corre!', '|TINTERFACE\\ICONS\\WARLOCK_CURSE_SHADOW_AURA.BLP:20|t ¡Cuchilla del Vacío Zedaat empieza a lanzar |cFFFF0404|Hspell:246340|h[Erupción abisal]|h|r! ¡Corre!', 25549),
(132818, 'esMX', '', 'Es el fin. Mi vida... le pertenece... a Sargeras...', 25549),
(132817, 'esMX', '', 'Mis últimas fuerzas... me abandonan. No podré... detenerlos...', 25549),
(132816, 'esMX', '', 'Mi resistencia se desvanece. Si Sargeras vence, toda vida caerá en la oscuridad.', 25549),
(132815, 'esMX', '', 'Derrótalos antes de que me alcancen, o todo estará perdido.', 25549),
(132814, 'esMX', '', '¡Campeones! ¡Las fuerzas de la Legión quieren capturar mi esencia para su amo infernal!', 25549),
(132813, 'esMX', '¡$n gana la partida!', '¡$n gana la partida!', 25549),
(132812, 'esMX', '', '¡¿Pero qué fue eso?!', 25549),
(132811, 'esMX', 'Será mejor empezar a distribuir el resto entre la población. La gente tiene que comer.', 'Será mejor empezar a distribuir el resto entre la población. La gente tiene que comer.', 25549),
(132810, 'esMX', '¡Cuánto grano! Los granjeros sí que se lucieron esta semana.', '¡Cuánto grano! Los granjeros sí que se lucieron esta semana.', 25549),
(132809, 'esMX', '¡$n está buscando un adversario!', '¡$n está buscando un adversario!', 25549),
(132808, 'esMX', 'Tranquilo, Pimienta. ¿Qué te sucede?', 'Tranquilo, Pimienta. ¿Qué te sucede?', 25549),
(132807, 'esMX', 'Un poco, tal vez. Pero a mí no me importa.', 'Un poco, tal vez. Pero a mí no me importa.', 25549),
(132806, 'esMX', '¿Hueles algo raro en este cargamento de granos?', '¿Hueles algo raro en este cargamento de granos?', 25549),
(132805, 'esMX', '', '¡Renaceré de las llamas de Argus! No dejaré... de luchar... jamás.', 25549),
(132804, 'esMX', '', '¿Crees que soy imbécil? ¡Demonios, a mí!', 25549),
(132803, 'esMX', '', 'Los ejércitos de mil mundos se alzarán en su contra. ¡Están condenados!', 25549),
(132802, 'esMX', '', '¡Defenderé Argus hasta mi último aliento!', 25549),
(132801, 'esMX', '¡Está... funcionando!', '', 25549),
(132800, 'esMX', 'Lo abrumaré con energía antes de que pueda disparar. Solo necesito un momento.', '', 25549),
(132799, 'esMX', 'No lograremos soportar otro embate de estas criaturas. Tenemos que terminar con esto ahora.', '', 25549),
(132798, 'esMX', 'Prepárense. ¡Ahí viene!', '', 25549),
(132793, 'esMX', 'Una vez que logremos impedir que dispare, los antaen seguramente nos atacarán.', '', 25549),
(132751, 'esMX', 'Excelente trabajo. El Vindicaar vuelve a estar a salvo.', '', 25549),
(132750, 'esMX', 'Los devastadores de la Legión están abrumando a nuestras fuerzas. ¡Desactiva sus barreras protectoras y les demostraremos el poder del Vindicaar!', '', 25549),
(132749, 'esMX', '¡Contemplen el poder del Vindicaar!', '', 25549),
(132748, 'esMX', '¡Que la Luz te purifique!', '', 25549),
(132747, 'esMX', 'El camino está despejado. ¡Fuego!', '', 25549),
(132746, 'esMX', '', 'En la otra esquina, un gólem con una personalidad magnética. Cuidado: ¡parece que a Klunk no le agradas!', 25549),
(132745, 'esMX', 'En la otra esquina, un gólem con una personalidad magnética. Cuidado: ¡parece que a Klunk no le agradas!', '', 25549),
(132744, 'esMX', '', '¡Alto ahí!', 25549),
(132743, 'esMX', '', '¡Alto!', 25549),
(132742, 'esMX', '', '¿Puedes sentirlo? Hay un tesoro por aquí.', 25549),
(132741, 'esMX', '', 'Presiento que hay un tesoro cerca.', 25549),
(132740, 'esMX', '', 'Falta un minuto. Veo que nos gusta el peligro, ¿eh?', 25549),
(132739, 'esMX', '', 'Faltan cinco minutos. ¿Crees que terminaremos a tiempo?', 25549),
(132738, 'esMX', '', '¡Mira la hora! Solo faltan diez minutos...', 25549),
(132732, 'esMX', 'Volver a La Brecha.', 'Volver a La Brecha.', 25549),
(132731, 'esMX', '¡Hay que detener a la Legión!', '', 25549),
(132730, 'esMX', 'Teletransportarme a la Cámara del Avatar.', 'Teletransportarme a la Cámara del Avatar.', 25549),
(132729, 'esMX', '', 'Con el poder del sello podemos viajar directamente a la Cámara del Avatar.', 25549),
(132728, 'esMX', '', 'Mmm... El Ujier está inactivo.', 25549),
(132726, 'esMX', '¡La dragona se acerca! ¡Acechadores viles, persíganla!', '', 25549),
(132723, 'esMX', '|TInterface\\Icons\\SPELL_DEATHKNIGHT_ARMYOFTHEDEAD.BLP:20|t¡El Caballero del metal invoca un |cFFFF0000|Hspell:245162|h[Ejército de muertos]|h|r para atacar a Devlynn Estigia!', '|TInterface\\Icons\\SPELL_DEATHKNIGHT_ARMYOFTHEDEAD.BLP:20|t¡El Caballero del metal invoca un |cFFFF0000|Hspell:245162|h[Ejército de muertos]|h|r para atacar a Devlynn Estigia!', 25549),
(132722, 'esMX', '|TInterface\\Icons\\WARRIOR_DISRUPTINGSHOUT.BLP:20|t¡Devlynn Estigia baja de un salto para lanzar sus |cFFFF0000|Hspell:245150|h[Gritos]|h|r sobre el Caballero del death metal!', '|TInterface\\Icons\\WARRIOR_DISRUPTINGSHOUT.BLP:20|t¡Devlynn Estigia baja de un salto para lanzar sus |cFFFF0000|Hspell:245150|h[Gritos]|h|r sobre el Caballero del death metal!', 25549),
(132721, 'esMX', '', 'El resto de ustedes, aseguren el área.', 25549),
(132720, 'esMX', '¡Falta un minuto para que Jabalí apestado suba al escenario! Acompáñennos en el Caldero de rock, en el lado este de la isla.', '', 25549),
(132719, 'esMX', '', 'Enaara, asegúrate de controlar a estos espíritus.', 25549),
(132718, 'esMX', '', 'De inmediato, capitana.', 25549),
(132717, 'esMX', '', 'Entendido. Tengo a la persona ideal para el trabajo: Y''mera.', 25549),
(132716, 'esMX', 'Buscamos el Sigilo del despertar. Quizás Archimonde lo dejó en el Conservatorio.', '', 25549),
(132715, 'esMX', '', 'Archenon poros, Profeta. El Ejército de la Luz está a tu lado.', 25549),
(132709, 'esMX', 'Entonces, así lo haremos. Resistiremos juntos.', '', 25549),
(132708, 'esMX', 'Yo soportaré los ataques todo el tiempo que pueda, ¡pero deben destruir esto antes de que sea demasiado tarde!', '', 25549),
(132705, 'esMX', 'No sé qué era esa cosa, pero no creo que fuera la única en el arsenal de Sargeras.', '', 25549),
(132704, 'esMX', '¡Cuidado!', '', 25549),
(132703, 'esMX', '', 'Perderán de todos modos. Las hermanas se encargarán...', 25549),
(132702, 'esMX', '', '¡No! ¡Este trofeo es mío! ¡Es un regalo para nuestro maestro!', 25549),
(132701, 'esMX', '', 'Ah, pero si apenas estaba comenzando. ¡Será un buen adorno en el Trono Ardiente!', 25549),
(132700, 'esMX', '', 'La cubierta superior del barco está en esta dirección. Xe''ra tendrá de qué hablar... con todos nosotros.', 25549),
(132699, 'esMX', '¡Xe''ra! No te preocupes, ya estás a salvo.', '', 25549),
(132698, 'esMX', 'Vamos. Ayúdame a guiarla hasta el Vindicaar para que podamos largarnos de aquí.', '', 25549),
(132697, 'esMX', 'Xe''ra sabrá que arriesgaste tu vida para salvarla. Recuperará la fe en ti... ¡Lo sé!', '', 25549),
(132695, 'esMX', 'Presiento que Xe''ra está en la cámara central. ¡Gracias a la Luz! Llegamos a tiempo.', '', 25549),
(132694, 'esMX', '', '¿Y luego, qué? Me encerró en una celda por utilizar el poder del Vacío. ¿Me encadenará por mi desobediencia? ¿O algo peor?', 25549),
(132689, 'esMX', '¡Estaba tan cerca! ¡Tú no podrás detenerme, gusano!', '', 25549),
(132687, 'esMX', '¡Sí, Capitán!', '¡Sí, Capitán!', 25549),
(132686, 'esMX', 'Prepárense para abordar el Vindicaar. Raalgar estará listo muy pronto.', 'Prepárense para abordar el Vindicaar. Raalgar estará listo muy pronto.', 25549),
(132685, 'esMX', 'Buen trabajo. Velen y yo te encontraremos en la Corona de Destrucción para detener a los antaen mientras podamos.', '', 25549),
(132666, 'esMX', 'El regreso del Alto inquisidor es un buen augurio. Argus pronto estará libre de esta alimaña.', 'El regreso del Alto inquisidor es un buen augurio. Argus pronto estará libre de esta alimaña.', 25549),
(132665, 'esMX', 'Buena pelea. Si la Legión alguna vez logra derribar el Vindicaar, Argus será nuestra tumba.', '', 25549),
(132664, 'esMX', 'Una marejada de demonios amenaza al Vindicaar nuevamente. Envía sus almas fétidas aullando de regreso a los salones de Antorus.', '', 25549),
(132660, 'esMX', '', '|TInterface\\Icons\\ABILITY_UPGRADEMOONGLAIVE.BLP:20|tLa cazadora Kasparian está lanzando |cFFFF0000|Hspell:236480|h[Tormenta de guja]|h|r!', 25549),
(132659, 'esMX', '', '|TInterface\\Icons\\ABILITY_DRUID_ECLIPSE.BLP:20|t¡La sacerdotisa Piraluna ha lanzado |cFFFF0000|Hspell:233263|h[Abrazo del eclipse]|h|r!', 25549),
(132658, 'esMX', '', '|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|t¡La capitana Yathae Lunaplena está apuntando con |cFFFF0000|Hspell:236304|h[Disparo incorpóreo]|h|r!', 25549),
(132652, 'esMX', 'Ah, $Gel héroe:la heroína; llega tarde. Nuestra maestra ya debe haber liberado al Alto inquisidor.', 'Ah, $Gel héroe:la heroína; llega tarde. Nuestra maestra ya debe haber liberado al Alto inquisidor.', 25549),
(132649, 'esMX', 'Acaben rápido con $Geste intruso:esta intrusa;. ¡Lah''zaruun necesita tiempo para llevar al Alto inquisidor a Argus!', 'Acaben rápido con este intruso. ¡Lah''zaruun necesita tiempo para llevar al Alto inquisidor a Argus!', 25549),
(132647, 'esMX', 'REUTILÍZAME', '', 25549),
(132644, 'esMX', 'Gracias, Romuul.', 'Gracias, Romuul.', 25549),
(132643, 'esMX', 'REUTILÍZAME', '', 25549),
(132642, 'esMX', '¿Puedes indicarme dónde buscar?', '¿Puedes indicarme dónde buscar?', 25549),
(132641, 'esMX', 'REUTILÍZAME', '', 25549),
(132640, 'esMX', 'REUTILÍZAME', '', 25549),
(132639, 'esMX', '¿Que sucederá si la Legión consigue la Piedra antes que nosotros?', '¿Que sucederá si la Legión consigue la Piedra antes que nosotros?', 25549),
(132638, 'esMX', 'Para ser un navío nuevo, la lista de reparaciones del Vindicaar es muy extensa. ¿En qué puedo ayudarte?', '', 25549),
(132637, 'esMX', '¿Qué ocurre, Romuul?', '¿Qué ocurre, Romuul?', 25549),
(132633, 'esMX', '', '¿Y luego, qué? Me encerró en una celda por blandir poderes del Vacío contra su voluntad. ¿Me capturará de nuevo? ¿O algo peor?', 25549),
(132632, 'esMX', '', 'Debes acudir en su ayuda, Turalyon. Me escabulliré tras el frente enemigo y los distraeré. Regresaremos pronto, Arator.', 25549),
(132631, 'esMX', '|TInterface\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t ¡%s está potenciando el |cFFF00000|Hspell:244152|h[Impulso apocalíptico]|h|r!', '', 25549),
(132630, 'esMX', '|TInterface\\ICONS\\ABILITY_HUNTER_SNIPERSHOT.BLP:20|t ¡Eres el objetivo de |cFFF00000|Hspell:244536|h[Bombardeo vil]|h|r!', '', 25549),
(132618, 'esMX', '¡Bebe y celebra durante el Tour de tabernas del Kirin Tor! ¡Busca a Anebria Vinosolar en el Salón Juego de Manos para unirte a los demás!', '', 25549),
(132612, 'esMX', '¡Espero que tengas sed, $p! ¡Visita a Anebria Vinosolar en el Salón Juego de Manos y acompaña al resto en el tour de tabernas del Kirin Tor!', '', 25549),
(132610, 'esMX', 'La fuente de la inmortalidad de Raalgar ya no existe. Al fin puedes matarlo y recuperar el Corazón vil de Argus.', '', 25549),
(132598, 'esMX', 'Podemos ayudarte.', 'Podemos ayudarte.', 25549),
(132597, 'esMX', 'Estamos tratando de averiguar quién está por atacar a Cromi y oímos que tienes problemas con las líneas ley. ¿Crees que estos hechos podrían estar relacionados?', 'Estamos tratando de averiguar quién está por atacar a Cromi y oímos que tienes problemas con las líneas ley. ¿Crees que estos hechos podrían estar relacionados?', 25549),
(132596, 'esMX', 'Podemos ayudarte.', 'Podemos ayudarte.', 25549),
(132595, 'esMX', 'Estamos tratando de averiguar quién está por atacar a Cromi. ¿Has visto algo extraño últimamente?', 'Estamos tratando de averiguar quién está por atacar a Cromi. ¿Has visto algo extraño últimamente?', 25549),
(132594, 'esMX', 'Te ayudaremos a defender el santuario de dragones.', 'Te ayudaremos a defender el santuario de dragones.', 25549),
(132593, 'esMX', 'Estamos tratando de averiguar quién está por atacar a Cromi y oímos que tienes algunos problemas con los no-muertos.', 'Estamos tratando de averiguar quién está por atacar a Cromi y oímos que tienes algunos problemas con los no-muertos.', 25549),
(132592, 'esMX', 'Entendido.', 'Entendido.', 25549),
(132591, 'esMX', 'Estamos tratando de averiguar quién está por atacar a Cromi y pensamos que tal vez sabías algo.', 'Estamos tratando de averiguar quién está por atacar a Cromi y pensamos que tal vez sabías algo.', 25549),
(132590, 'esMX', 'Para ser honesto, no estoy seguro. Es posible. Las líneas ley siempre han estado inquietas en esta parte del mundo, pero hoy se están comportando de manera muy extraña. Algo está interfiriendo con ellas.', '', 25549),
(132589, 'esMX', '¿Sí? ¿Qué viene a hacer el vuelo bronce aquí?', '', 25549),
(132588, 'esMX', '', 'Sí. Los soñadores no han logrado descansar. Ha sido... abrumador.', 25549),
(132587, 'esMX', '', '¿Sí? ¿Qué puedo hacer por ti?', 25549),
(132586, 'esMX', '', 'Así es. Normalmente nos cruzamos con dos o tres necrófagos por día, pero hoy nos atacó una cantidad que no habíamos visto en casi diez años.', 25549),
(132585, 'esMX', '', '¿En qué puedo ayudarte?', 25549),
(132584, 'esMX', '¿Yo? ¿Por qué siempre todos sospechan del dragón negro? Me siento humillado, Chronormu.$b$bNo, no sé nada del ataque. Simplemente fui a visitar Rasganorte por... diversión, digamos. Sin embargo, me sorprendí al encontrarme con esta infestación de esqueletos en nuestro amado santuario de dragones. Si estás buscando a alguien que sienta resentimiento por los dragones, te recomiendo empezar por estos no-muertos y quien sea que los esté controlando.', '', 25549),
(132583, 'esMX', 'Entiendo que el santuario estuvo abandonado durante algunos años pero... ¿Restos de esqueletos desgarbados? ¿De verdad? Mi padre jamás habría aprobado esto.', '', 25549),
(132582, 'esMX', '¡El Kirin Tor organizará un tour de tabernas pronto! ¡Ven al Salón Juego de Manos cuando empiece y deleita tu paladar con comidas y tragos!', '', 25549),
(132578, 'esMX', '', 'Creo que deberíamos empezar por hablar con alguno de los dragones bronce.', 25549),
(132577, 'esMX', 'Cuando quieras.', 'Cuando quieras.', 25549),
(132570, 'esMX', '', '¡Ven a divertirte a nuestras fiestas de baile en las casas de subasta de Ventormenta y Orgrimmar!', 25549),
(132569, 'esMX', '', '¡Todos a bailar! ¡Hemos ocupado las casas de subasta de Ventormenta y Orgrimmar para organizar una fiesta de baile!', 25549),
(132568, 'esMX', '', '¡Ocuparemos las casas de subasta de Ventormenta y Orgrimmar y organizaremos una fiesta de baile! ¡Espero que vayas y muestres tus mejores pasos!', 25549),
(132567, 'esMX', '', '¡Necesitas trabajar en tus movimientos, $p! ¡Organizaremos fiestas de baile en las casas de subasta de Ventormenta y Orgrimmar!', 25549),
(132561, 'esMX', '¿Qué fue lo que dijiste?', '¿Qué fue lo que dijiste?', 25549),
(132559, 'esMX', 'Los enemigos... están... en el sueño...', '', 25549),
(132558, 'esMX', 'Tienes que detener este tormento...', '', 25549),
(132557, 'esMX', 'Ayúdame...', '', 25549),
(132556, 'esMX', '¿Crees que eres de los que imponen tendencias? ¡Visita al Tejedor de distorsión Tuviss o a cualquier otro transfigurador para participar del Desafío de estilos!', '', 25549),
(132555, 'esMX', '¡Visita al Tejedor de distorsión Tuviss en Dalaran o a cualquier otro transfigurador para participar del Desafío de estilos!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(132554, 'esMX', 'Ey, $p. Necesitas mejorar tu estilo. ¡El Desafío de estilos comenzará pronto!', '', 25549),
(132553, 'esMX', '¡Prepara tus atuendos! ¡El Desafío de estilos comenzará pronto!', '', 25549),
(132552, 'esMX', 'Saludos.', '', 25549),
(132551, 'esMX', 'Estoy listo para ir al Arcatraz.', 'Estoy lista para ir al Arcatraz.', 25549),
(132546, 'esMX', 'Te defenderemos, Protectora.', 'Te defenderemos, Protectora.', 25549),
(132543, 'esMX', '', '<La esencia de Eonar flota frente a ti. Aunque su belleza y pureza son palpables, puedes sentir la pena y el temor que la embargan.>', 25549),
(132542, 'esMX', 'Solo avísame cuando estés $Glisto:lista; para comenzar. Seguramente pronto tendremos compañía.', '', 25549),
(132540, 'esMX', 'Tu atacante se oculta...  en la palma del dragón...', '', 25549),
(132539, 'esMX', 'Busca tu respuesta... en el agua...', '', 25549),
(132538, 'esMX', 'Debes detener... la gran pesadilla...', '', 25549),
(132535, 'esMX', 'Nos reuniremos contigo cerca del arma, $p.', '', 25549),
(132530, 'esMX', '', 'Aquí dice que su líder está en uno de esos discos flotantes sobre nosotros. ¡Acabemos con él!', 25549),
(132529, 'esMX', '¡Aardon''sha, kir kah''los!', '', 25549),
(132528, 'esMX', 'Concédeme tu fuerza, $p. ¡Terminaremos esto juntos!', '', 25549),
(132527, 'esMX', '', 'Todos están condenados.', 25549),
(132526, 'esMX', '', 'Todos se arrodillarán ante el Destructor.', 25549),
(132525, 'esMX', '', 'El caos reina.', 25549),
(132524, 'esMX', '', 'Entrégame tu alma.', 25549),
(132523, 'esMX', '', 'Azeroth será nuestro.', 25549),
(132522, 'esMX', '', '¡Nadie puede detener nuestra cruzada!', 25549),
(132521, 'esMX', '', 'Alimento para los viles.', 25549),
(132520, 'esMX', '', '¡Ardan en las llamas de Sargeras!', 25549),
(132519, 'esMX', 'Todos están condenados.', 'Todos están condenados.', 25549),
(132518, 'esMX', 'Todos se arrodillarán ante el Destructor.', 'Todos se arrodillarán ante el Destructor.', 25549),
(132517, 'esMX', 'Reina el caos.', 'El caos reina.', 25549),
(132516, 'esMX', 'Entrégame tu alma.', 'Muéstrame tu alma.', 25549),
(132515, 'esMX', 'Azeroth será nuestro.', 'Azeroth será nuestro.', 25549),
(132514, 'esMX', '¡Nadie puede detener nuestra cruzada!', '¡Nadie puede detener nuestra cruzada!', 25549),
(132513, 'esMX', 'Alimento para los viles.', 'Alimento para los viles.', 25549),
(132512, 'esMX', '¡Ardan en las llamas de Sargeras!', '¡Ardan en las llamas de Sargeras!', 25549),
(132511, 'esMX', '', '¡Conocerás el verdadero dolor!', 25549),
(132510, 'esMX', '', '¡Inclínate ante los ejércitos del maestro!', 25549),
(132509, 'esMX', '', '¿Cómo te atreves a pisar nuestro mundo?', 25549),
(132508, 'esMX', '', '¡Azeroth caerá!', 25549),
(132507, 'esMX', '', 'Me darán una recompensa por tu cabeza.', 25549),
(132506, 'esMX', '', 'Solo has visto una pizca de nuestro poder.', 25549),
(132505, 'esMX', '', 'Soy la furia de mil mundos conquistados.', 25549),
(132504, 'esMX', '', '¡Somos la Legión!', 25549),
(132503, 'esMX', '¡Conocerás el verdadero dolor!', '¡Conocerás el verdadero dolor!', 25549),
(132502, 'esMX', '¡Inclínate ante los ejércitos del maestro!', '¡Inclínate ante los ejércitos del maestro!', 25549),
(132501, 'esMX', '¿Cómo te atreves a pisar nuestro mundo?', '¿Cómo te atreves a pisar nuestro mundo?', 25549),
(132500, 'esMX', '¡Azeroth caerá!', '¡Azeroth caerá!', 25549),
(132499, 'esMX', 'Me darán una recompensa por tu cabeza.', 'Me darán una recompensa por tu cabeza.', 25549),
(132498, 'esMX', 'Solo has visto una pizca de nuestro poder.', 'Solo has visto una pizca de nuestro poder.', 25549),
(132497, 'esMX', 'Soy la furia de mil mundos conquistados.', 'Soy la furia de mil mundos conquistados.', 25549),
(132496, 'esMX', '¡Somos la Legión!', '¡Somos la Legión!', 25549),
(132489, 'esMX', 'Tu madre y tu padre aún viven, Arator. Estoy seguro. Pero por ahora, concéntrate en la pelea que se avecina.', '', 25549),
(132488, 'esMX', '', 'Creo que tendríamos que dar un aviso: ¡El tesoro va adentro, no afuera, tontos! ¿Verdad?', 25549),
(132487, 'esMX', '', '¡Es como si quisiéramos que los encuentren! Con todas esas decoraciones en oro y las gemas incrustadas...', 25549),
(132486, 'esMX', '', '¿Qué pasa con los cofres de tesoros últimamente? Se ven tan caros y brillantes...', 25549),
(132485, 'esMX', '', 'Al día siguiente, apareció una flota de más de 20 barcos. Esta vez el capitán gritó: "Tráiganme los pantalones marrones".', 25549),
(132484, 'esMX', '', 'En ese instante vociferó: "Tráiganme mi camisa roja". Explicó que, si lo herían, su tripulación no vería la sangre y seguirían luchando sin miedo.', 25549),
(132483, 'esMX', '', 'Un día, el Almirante de retaguardia Planchagracia se cruzó con un pequeño barco enemigo en el mar.', 25549),
(132482, 'esMX', '', '¡Seis piratas!', 25549),
(132481, 'esMX', '', '¿Qué tiene seis piernas, seis manos y seis ojos?', 25549),
(132480, 'esMX', '', 'Este es uno de esos acertijos…', 25549),
(132479, 'esMX', '', 'El capitán gritó: "¡Una flota!". Y el marinero respondió: "No, señor, ¡todas flotan!".', 25549),
(132478, 'esMX', '', 'Uno de la tripulación vio una gran cantidad de barcos que se acercaban y dio aviso: "¡Capitán, se acercan quince naves!".', 25549),
(132477, 'esMX', '', 'Hace un tiempo, el capitán Fausal estaba navegando en altamar.', 25549),
(132476, 'esMX', '', 'Y respondió: "El día que me pusieron el garfio me picaba el ojo".', 25549),
(132475, 'esMX', '', '"Un enemigo me cortó la mano de un sablazo", respondió. "¿Y el parche? ¿Qué te pasó en el ojo?", le dije.', 25549),
(132474, 'esMX', '', 'Uno de los marineros de la Tripulación aterradora llevaba un garfio y un parche. Le pregunté qué le había sucedido.', 25549),
(132473, 'esMX', '¡Aprende todo sobre los lechúcicos lunares en el Festival del lechúcico lunar en Claro de la Luna!', '', 25549),
(132472, 'esMX', '¡El Festival del lechúcico lunar comenzará pronto! ¡Visita Claro de la Luna cuando empiece para conocer más detalles!', '', 25549),
(132471, 'esMX', '¡Falta poco para el Festival del lechúcico lunar! Visita Claro de la Luna en cuanto empiece para averiguar de qué se trata.', '', 25549),
(132470, 'esMX', '¡Hola, $p! ¡Ven a aprender todo sobre los lechúcicos lunares en el Festival del lechúcico lunar en Claro de la Luna!', '', 25549),
(132469, 'esMX', '¡Mantengan la posición! ¡Debemos proteger el Vindicaar con nuestras vidas!', '', 25549),
(132468, 'esMX', 'Vamos, mostrémosle a Sargeras y a los de su clase el destino que se buscaron.', '', 25549),
(132467, 'esMX', '', 'El Capitán gritó: "Todos a babor". Y Babor murió aplastado.', 25549),
(132466, 'esMX', '', 'Después de varias copas, me contó que su padre se llamaba Jack Babor y que había muerto hace tiempo. "¿Cómo murió?", le pregunté.', 25549),
(132465, 'esMX', '', 'La semana pasada estaba tomando un trago con un artillero de la Tripulación aterradora...', 25549),
(132464, 'esMX', '', 'Ja, ahora que alguien me traiga un poco de grog.', 25549),
(132463, 'esMX', '', 'De acuerdo, prepárense para lo que viene, marineros. Este les despeinará las barbas...', 25549),
(132462, 'esMX', '', 'Gracias, $Gmarinero:marinera;. Lo valioso no siempre está dentro de un cofre.', 25549),
(132461, 'esMX', '', 'Corre la voz. Diles que la vieja Malas Noticias no es tan terrible después de todo.', 25549),
(132460, 'esMX', '', '¡Gracias! Dilo bien alto para que lo oigan los demás, ¿sí?', 25549),
(132459, 'esMX', '', '¿Lo dices en serio? ¡Te lo agradezco, $Gmarinero:marinera;!', 25549),
(132458, 'esMX', '', '¡Arrrr! ¡Celebremos con un trago!', 25549),
(132457, 'esMX', '', 'Me he entrenado en incontables océanos y saqueos. ¡Esto es humor de un auténtico pirata!', 25549),
(132456, 'esMX', '', 'Te partiré la cara... Ah, espera, ¿te gustaron? Gracias. Nunca le agradan a nadie.', 25549),
(132455, 'esMX', '', 'Te lo agradezco, $Gviejo marinero:vieja marinera;.', 25549),
(132454, 'esMX', '', '¡Ojalá te pongan la marca negra a ti y a todos tus amigos, cucarachas inservibles!', 25549),
(132452, 'esMX', '', 'Mejor ve a bailar con Jack Ketch. Déjale esto de las bromas a los más experimentados.', 25549),
(132451, 'esMX', '', '¡Ya cierra la boca y ve a caminar por la tabla, $Gmaldito lameplatos insensato:maldita lameplatos insensata;!', 25549),
(132449, 'esMX', '', '¡Cierra el pico o te atravesaré con mi sable, $Gpatético:patética; aspirante a pirata!', 25549),
(132448, 'esMX', '', '¡Te cortaré la lengua!', 25549),
(132447, 'esMX', '', '¡Te arrastraré por la quilla, inútil!', 25549),
(132446, 'esMX', '', '¡Ja! ¡Quisiera ver que lo hicieras mejor, sabandija!', 25549),
(132445, 'esMX', '', '¿Ah sí? Tu cara me da asco... ¡igual que la de tu madre!', 25549),
(132443, 'esMX', 'La Luz guía mi flecha. No existe lugar donde la oscuridad se pueda refugiar al exponerse a su gloria incandescente.', '', 25549),
(132442, 'esMX', '¡Tus chistes son pésimos!', '¡Tus chistes son pésimos!', 25549),
(132441, 'esMX', '¡Tus chistes son fantásticos!', '¡Tus chistes son fantásticos!', 25549),
(132440, 'esMX', 'Claro, cuéntame un chiste.', 'Claro, cuéntame un chiste.', 25549),
(132439, 'esMX', '', '¡Quítate los zapatos, toma una botella de grog y deja que te cuente un chiste!', 25549),
(132438, 'esMX', 'Nos tienen rodeados una vez más. Pobres tontos.', '', 25549),
(132437, 'esMX', 'Para mi presa, es inútil correr. Si no la mato yo, morirá de cansancio.', '', 25549),
(132436, 'esMX', 'Mientras haya demonios viles de pie, no habrá paz.$b$bMientras haya traidores impíos con vida, no habrá perdón.', '', 25549),
(132435, 'esMX', 'Un disparo, una muerte.', '', 25549),
(132434, 'esMX', 'Sistemas reactivados, redireccionando energía. Armas listas.', '', 25549),
(132433, 'esMX', 'Impulso apocalíptico activado.', '', 25549),
(132432, 'esMX', 'Nadie debe quedar con vida.', '', 25549),
(132431, 'esMX', 'Sistema de armas listo. Objetivo en la mira.', '', 25549),
(132430, 'esMX', 'Cañón preparado para aniquilación.', '', 25549),
(132429, 'esMX', 'Objetivos de exterminación en la mira.', '', 25549),
(132428, 'esMX', 'Error crítico del sistema...', '', 25549),
(132427, 'esMX', 'Objetivos eliminados.', '', 25549),
(132426, 'esMX', 'Guerreros enemigos detectados. Nivel de amenaza: insignificante.', '', 25549),
(132425, 'esMX', '', 'La codicia y el ansia de poder consumieron a nuestro pueblo. Tengo fe en la Luz, y poseo el poder necesario para demostrarles que se equivocaron.', 25549),
(132424, 'esMX', 'Enemigos detectados. Activando arsenal.', '', 25549),
(132423, 'esMX', '', 'Bormos tiene un dicho muy acertado para momentos como este: "Más valen cien Templeluz que mil tropas normales."', 25549),
(132422, 'esMX', '', 'Resistimos contra nuestros enemigos con sables y hechizos. No podemos confiar plenamente en ninguna de las dos opciones.', 25549),
(132421, 'esMX', '', 'Son pocos los que aún controlan la magia verdadera después de ver la tentación de nuestros hermanos. Aprovecharé todas las ventajas que pueda.', 25549),
(132420, 'esMX', 'Cuando tú digas, $p.', '', 25549),
(132419, 'esMX', 'Activando matriz de transporte.', '', 25549),
(132418, 'esMX', '', '¿Has venido a darnos un descanso de las oleadas interminables?', 25549),
(132417, 'esMX', '¡Faro en posición, Profeta!', '', 25549),
(132414, 'esMX', '¡Debemos destruir el arma mientras se recarga! ¡Romuul, envía un faro abajo!', '', 25549),
(132413, 'esMX', 'Su próximo ataque nos exterminará... A menos que ataquemos primero.', '', 25549),
(132412, 'esMX', '', 'Estos traidores jamás nos derrotarán, porque la Luz guía nuestro camino.', 25549),
(132411, 'esMX', '', '¿Estás $Gherido:herida;? No es nada. Estoy segura de que con un poco de comida estarás en forma para volver a luchar en un santiamén.', 25549),
(132410, 'esMX', '', '¿Alguien pidió una médica? ¡Qué pena, porque tenemos que luchar contra la Legión!', 25549),
(132409, 'esMX', '', 'Una traición como la de nuestro pueblo es una de las peores heridas que podría imaginar. Aún se encuentra abierta, incluso tantos años más tarde.$b$bEs necesario purificar estas heridas. Es necesario extirpar y destruir la corrupción para que la herida empiece a sanar.', 25549),
(132390, 'esMX', '', '<Insert neat RP moment where she absorbs the Heart of Nhal''atoth here.>', 25549),
(132389, 'esMX', 'Nuestras tropas se encargarán de proteger el Xenedar. Aunque hayamos recuperado su cargamento más preciado, no podemos permitir que el navío caiga en manos de la Legión.', '', 25549),
(132388, 'esMX', 'Fija el faro en mi ubicación. Regresemos a nuestro hogar.', '', 25549),
(132387, 'esMX', '¡Devuelve el talbuk al krokul en la entrada del bosque!', '¡Devuelve el talbuk al krokul en la entrada del bosque!', 25549),
(132386, 'esMX', 'Los que descubrieron la verdad trataron de escapar, pero terminaron atrapados en esta pesadilla. No sé cómo pudieron sobrevivir todo este tiempo.', '', 25549),
(132385, 'esMX', 'Muchos se unieron a la Legión por voluntad propia y se entregaron a las falsas promesas de poder y gloria de Sargeras.', '', 25549),
(132384, 'esMX', 'No todo mi pueblo abandonó Argus cuando Archimonde y Kil''jaeden sellaron su pacto con el Titán oscuro.', '', 25549),
(132383, 'esMX', 'Como quieras. Ven, $p. Siento su presencia no muy lejos de aquí.', '', 25549),
(132382, 'esMX', 'Confías demasiado en su lealtad. Arriesga tu vida si debes hacerlo. Prepararé nuestras fuerzas para el inevitable contraataque.', '', 25549),
(132381, 'esMX', 'Quiero ir a Karazhan (calabozo).', 'Quiero ir a Karazhan (calabozo).', 25549),
(132380, 'esMX', 'Podrían ser aliados valiosos en nuestra lucha.', '', 25549),
(132379, 'esMX', 'Estoy de acuerdo. Vi a esclavos de la Legión huir mientras aumentábamos el ataque.', '', 25549),
(132378, 'esMX', '¡Saludos! ¡Te doy la bienvenida al Evento Mítico Exclusivo!\n\nPuedo teletransportarte directamente a cualquier calabozo de Legion.\n\nAsegúrate de seleccionar la dificultad mítica antes de teletransportarte.', '', 25549),
(132375, 'esMX', 'Envíame al Templo Oscuro. (Banda de cronoviaje)', 'Envíame al Templo Oscuro.', 25549),
(132373, 'esMX', '', 'Saludos, $n. Posiblemente no me recuerdes, nos conocimos la semana que viene. ¿Te gustaría volver a visitar el Templo Oscuro?', 25549),
(132372, 'esMX', 'Adiós por ahora.', '', 25549),
(132371, 'esMX', 'Hubo muchos que no tuvieron esta suerte. Ahora están resistiendo en el lugar de la caída, peleando por sus vidas.', '', 25549),
(132370, 'esMX', 'El pueblo de Hatuun me salvó de la caída del Xenedar.', '', 25549),
(132369, 'esMX', '¡Ah, estás $Gvivo:viva;! Hay un faro en camino.', '', 25549),
(132368, 'esMX', '50,000 de oro', '50,000 de oro', 25549),
(132367, 'esMX', 'Están acercándose. Prepárate, $p.', '', 25549),
(132366, 'esMX', '¿Necesitas oro? Aquí tienes un equivalente a 50,000 monedas.', '¿Necesitas oro? Aquí tienes un equivalente a 50,000 monedas.', 25549),
(132363, 'esMX', '', 'Hace... frío.', 25549),
(132362, 'esMX', '', 'Entiendo. Gracias. A los dos.', 25549),
(132361, 'esMX', 'Llévalo, y estarás un paso más cerca de tu destino.', '', 25549),
(132360, 'esMX', 'El corazón de un semidiós. Esto no es un simple recuerdo, Alleria.', '', 25549),
(132359, 'esMX', 'No olvides reclamar nuestro premio, ser de carne. Yo me ocuparé de Alleria.', '', 25549),
(132358, 'esMX', '¡Pelea, maldita sea!', '', 25549),
(132357, 'esMX', '', 'Lárgate, maldita oscuridad.', 25549),
(132356, 'esMX', '', '¡No podrás! ¡Nunca te apoderarás de mí!', 25549),
(132355, 'esMX', '', 'No puedo... No... ¡Argh!', 25549),
(132354, 'esMX', 'El Vacío solo muestra la mitad de la verdad. Confía en tus instintos.', '', 25549),
(132353, 'esMX', '', '¡Arator! ¡¿Turalyon?!', 25549),
(132352, 'esMX', 'Concentra tus pensamientos. Recuerda tu entrenamiento.', '', 25549),
(132350, 'esMX', 'Vaya hallazgo... ¡Nosotros nos encargaremos de lo que sigue!', '', 25549),
(132349, 'esMX', '¡Rápido, rápido! ¡Que alguien le avise al intendente!', '', 25549),
(132348, 'esMX', '¡Oye, eso nos pertenece! ¡Nosotros lo vimos primero!', '', 25549),
(132305, 'esMX', '', 'Si atrapamos a este demonio, podré drenar su energía para mantenerlo a raya. Campeones, yo pondré las trampas; ustedes deben capturarlo.', 25549),
(132304, 'esMX', '¡Captura el poder de los portales, Alleria! ¡Puede ser tu arma!', '', 25549),
(132303, 'esMX', 'Resiste, $p. ¡La monstruosidad flaquea!', '', 25549),
(132302, 'esMX', 'Mi destino no es caer ante ti, monstruo. Tengo asuntos pendientes con tu amo.', '', 25549),
(132301, 'esMX', '¡Siente el odio de diez mil años!', '', 25549),
(132300, 'esMX', '¡La caída del Xenedar no será en vano!', '', 25549),
(132299, 'esMX', 'Haré mucho más que eso.', '', 25549),
(132298, 'esMX', 'Llama su atención, Illidan. ¡No llegamos tan lejos para caer ahora!', '', 25549),
(132295, 'esMX', '¡Está vivo!', '', 25549),
(132286, 'esMX', 'Por la Luz...', '', 25549),
(132285, 'esMX', 'Mi hechizo no surte efecto. Esta no es un arma de asedio común...', '', 25549),
(132284, 'esMX', 'Defenderemos esta posición. Solo ruego que haya sobrevivientes en el Ejército de la Luz.', '', 25549),
(132283, 'esMX', 'Pronto toda la Legión caerá sobre nosotros.', '', 25549),
(132278, 'esMX', 'Estoy contigo.', 'Estoy contigo.', 25549),
(132277, 'esMX', 'Si sobrecargamos esta arma, los demonios vendrán a nosotros.', '', 25549),
(132268, 'esMX', 'Salta al foso cuando tengas un |TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t |cFFFF0000|Hspell:240209|h[Alma inestable]|h|r!', 'Salta al foso cuando tengas un |TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t |cFFFF0000|Hspell:240209|h[Alma inestable]|h|r!', 25549),
(132259, 'esMX', 'Todo el poder de este lugar ahora le pertenece a la Legión.', 'Todo el poder de este lugar ahora le pertenece a la Legión.', 25549),
(132258, 'esMX', '¡ha comido demasiado!', '', 25549),
(132257, 'esMX', 'se siente satisfecho...', '', 25549),
(132256, 'esMX', 'no se siente muy bien...', '', 25549),
(132255, 'esMX', 'Es el Día de los Piratas y eso quiere decir una cosa: ¡es hora de celebrar!\n\nCuando te canses de esta patética congregación de la Tripulación aterradora, dirígete a la playa que está al sur... Ahí celebran los piratas DE VERDAD.\n\nMis compañeros, los poderosos Bucaneros velasangre, están ahí. Diles que vas de parte del viejo Mostachia y tal vez me dejen volver a entrar...', '', 25549),
(132253, 'esMX', '¿De dónde sacaste ese poni flotador?', '¿De dónde sacaste ese poni flotador?', 25549),
(132252, 'esMX', 'Ahh, uno pincha un pequeñito poni insignificante y lo expulsan de la fiesta para siempre... ¿Qué imporrrta? Al cabo que ni me gustan las... fiestas con ponis...\n\nLos ponis no son piratas de verdad... Ni siquiera pueden cargar una bala en el cañón... Ni siquiera tienen manos... Uooo...', '', 25549),
(132251, 'esMX', 'El estúpido Planchagracia me mandó a... una siesta de espionaje secreta... no apareció... ¡Yo también tengo cosas que hacer!', '', 25549),
(132250, 'esMX', 'Grog, grog... ¡Me encanta el grog!\nGrog, grog... ¡Otro trago!\nGrog, grog... ¡Consigue más!\nO te desollaré...\n\n¿Qué te parece esa improvisación?', '', 25549),
(132249, 'esMX', 'Si ESTA fiesta no te parece tan apestosa, deberías ir a MI fiesta...\n\n¿Te gustan los ponis?', '', 25549),
(132248, 'esMX', '...¡y no me interesa quién me oiga!\n\nToma eso DeMuza... DeMinza... ¡DeMensa!\n\nJa... Eso estuvo bien...', '', 25549),
(132247, 'esMX', 'Vengo a... divertirme... pero las fiestas de la Tripulación aterradora son más aburridas que... ¡UN GRUPO DE SHADOPAN!\n\n¡Ja!', '', 25549),
(132246, 'esMX', '', '¿Cómo pudiste hacer eso?', 25549),
(132245, 'esMX', '', '¡Casi lo logras!', 25549),
(132244, 'esMX', '', 'La costa está despejada. Inténtalo de nuevo.', 25549),
(132242, 'esMX', '¿Organizaste esta fiesta solo para mí, $pr? ... Te mereces un vaso...¡un vaso de grog!', '', 25549),
(132241, 'esMX', '¡Hoy es MI día! Soy pirata... Seee, ¡soy el MEJOR de los piratas!\n\n¡Tomen eso, Tripulación aterradora!', '', 25549),
(132239, 'esMX', '', 'Buscadores, protejan al Alto inquisidor en su partida. ¡Yo me encargaré de esta interrupción!', 25549),
(132238, 'esMX', '', '¡Así se hará, Alto inquisidor!', 25549),
(132234, 'esMX', '', 'Te tengo. Inténtalo de nuevo... Estamos a salvo por ahora.', 25549),
(132233, 'esMX', '¡Faltan 10 segundos!', '', 25549),
(132232, 'esMX', '¡Faltan 30 segundos!', '', 25549),
(132231, 'esMX', 'Al fin, regresaré a casa y me prepararé para atacar. Tú puedes quedarte aquí... ¡y morir!', '', 25549),
(132230, 'esMX', '', '¿Una distracción? ¿Qué estás ocultando?', 25549),
(132229, 'esMX', '', 'Tu carne te traiciona.', 25549),
(132228, 'esMX', '', 'Por su voluntad.', 25549),
(132227, 'esMX', '', '¿Creíste que escaparías?', 25549),
(132226, 'esMX', '', '¡Ja! Patético ser de carne.', 25549),
(132225, 'esMX', '', '¡Se hará su voluntad!', 25549),
(132224, 'esMX', '', '¡Muere, ser de carne!', 25549),
(132223, 'esMX', '', '¡No puedes esconderte en esta oscuridad!', 25549),
(132222, 'esMX', '', '¿Cómo osas entrar a nuestro reino?', 25549),
(132220, 'esMX', '', 'Qué arrogante de tu parte.', 25549),
(132219, 'esMX', '', 'Este es nuestro reino, ser de carne.', 25549),
(132218, 'esMX', '', 'Te veo.', 25549),
(132217, 'esMX', '', 'No puedes esconderte.', 25549),
(132216, 'esMX', '', 'No escaparás de mí.', 25549),
(132215, 'esMX', 'Vaya, vaya... ¿Qué es esto?', '', 25549),
(132214, 'esMX', 'Mmm... ja, ja, ja, ja.', '', 25549),
(132213, 'esMX', '¿Un intruso?', '', 25549),
(132212, 'esMX', '¡Muéstrate!', '', 25549),
(132211, 'esMX', '¿Qué fue eso?', '', 25549),
(132210, 'esMX', 'Los devastadores han sido destruidos. ¡Rápido, avancen!', '', 25549),
(132209, 'esMX', '¡Ya no corromperás este mundo!', '', 25549),
(132208, 'esMX', '¡Pagarán por sus crímenes, demonios asquerosos!', '', 25549),
(132207, 'esMX', '¡Sean purificados, demonios!', '', 25549),
(132206, 'esMX', '¡Soy libre!', '', 25549),
(132204, 'esMX', '', '¡Un esfuerzo inútil, insecto!', 25549),
(132202, 'esMX', '', '¡Esbirros! ¡Vengan a mí!', 25549),
(132182, 'esMX', 'Nos pertenece, hermana.', 'Nos pertenece, hermana.', 25549),
(132181, 'esMX', 'La magia del Vacío de Zereketh sigue aquí.', 'La magia del Vacío de Zereketh sigue aquí.', 25549),
(132176, 'esMX', 'No irás a ningún lado, "adalid". ¡El maestro tiene planes para ti!', '', 25549),
(132175, 'esMX', '', 'Sabes que me niego a morir con la Legión aún en pie, Alto exarca. Sígueme. Hemos establecido un perímetro.', 25549),
(132172, 'esMX', '', '¡Hoy no, monstruo! ¡La Luz prevalece!', 25549),
(132170, 'esMX', '', '¿Caminante intersticial?', 25549),
(132167, 'esMX', '', '¿Puedes sentirlo? Algo nos retiene...', 25549),
(132166, 'esMX', '', '¡Lo perdemos!', 25549),
(132165, 'esMX', '', '¡No puede oírnos! Debemos poner fin a su sufrimiento.', 25549),
(132164, 'esMX', '', '¡No! ¡Lo que has visto es una mentira!', 25549),
(132163, 'esMX', '', '¡Resiste a su llamado, Arkhaan!', 25549),
(132162, 'esMX', '¡Fareeya! ¡Estás viva!', '', 25549),
(132161, 'esMX', '¡No me demorarás, demonio!', '', 25549),
(132160, 'esMX', '', '¿Quién es?', 25549),
(132159, 'esMX', 'Me adelantaré y liberaré el camino. El puente que lleva hacia el Xenedar parece ser el más desprotegido. Que la Luz nos acompañe.', '', 25549),
(132158, 'esMX', '', 'Lamento que tuvieras que aprender así. Ahora descansa.', 25549),
(132157, 'esMX', '¿Por qué... no... escuchan?', '', 25549),
(132156, 'esMX', '¡Arkhaan te hará entender!', '', 25549),
(132155, 'esMX', '¡Debes saber la verdad!', '', 25549),
(132154, 'esMX', '¡Todo se destruirá! No existe nada... Solo el Vacío.', '', 25549),
(132153, 'esMX', '¡Gracias! ¡Gracias!', '', 25549),
(132127, 'esMX', 'Volveremos a hablar una vez que hayas llegado al Arcatraz.', '', 25549),
(132126, 'esMX', '|TInterface\\Icons\\INV_Axe_2H_UndeadGuitar_C_01.blp:20|t¡Los Acordes extasiantes caen del cielo, úsalos para |cFFFF0000|Hspell:245034|h[Extasiar]|h|r a tus enemigos!', '|TInterface\\Icons\\INV_Axe_2H_UndeadGuitar_C_01.blp:20|t¡Los Acordes extasiantes caen del cielo, úsalos para |cFFFF0000|Hspell:245034|h[Extasiar]|h|r a tus enemigos!', 25549),
(132125, 'esMX', '¡Es imposible! ¡Nadie puede derrotarme!', '', 25549),
(132124, 'esMX', 'Han fallado, Jabalí apestado. ¡Ahora sus fanáticos sirven en mis ejércitos de muertos!', '', 25549),
(132123, 'esMX', '¡Otra alma para mis ejércitos!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(132122, 'esMX', '¡Otra alma para mis canciones!', '', 25549),
(132121, 'esMX', 'De cada tumba, necrófagos emergerán. Aunque se defiendan, sus cuerpos no resistirán.', '', 25549),
(132120, 'esMX', '¡La oscuridad invade este mundo! ¡Con su azote las almas en pena forman un muro gemebundo!', '', 25549),
(132119, 'esMX', 'Aunque luchen y se defiendan, sus cuerpos se congelarán y se harán añicos.', '', 25549),
(132118, 'esMX', 'Demostraré de una vez por todas que solo un caballero de la tumba puede ser rey del heavy metal.', '', 25549),
(132116, 'esMX', 'Ajustemos nuestra estrategia.\n|cFF0000FF(Cambiar los talentos de Cromi).|r', 'Ajustemos nuestra estrategia.\n|cFF0000FF(Cambiar los talentos de Cromi).|r', 25549),
(132115, 'esMX', '<Ajustar los talentos de Cromi>', '<Ajustar los talentos de Cromi>', 25549),
(132110, 'esMX', '', '¡Hola de nuevo!', 25549),
(132109, 'esMX', 'Los espíritus de aquellos que se resisten a la Legión nos inspiran a todos.', '', 25549),
(132108, 'esMX', 'Aun siendo torturados por la Legión, mi pueblo se revela contra su cruzada maldita. Los demonios podrán quebrar sus cuerpos, pero jamás quebrarán su voluntad. Libera sus espíritus para que puedan alcanzar la paz.', '', 25549),
(132104, 'esMX', 'Shhh.', '', 25549),
(132103, 'esMX', '¡Ah!', '', 25549),
(132102, 'esMX', '¡Alto! ¡No escuches!', '', 25549),
(132101, 'esMX', 'Nnghh... ¡Quédate con nosotros!', '', 25549),
(132100, 'esMX', 'No, no... no.', '', 25549),
(132099, 'esMX', '¿Oíste eso?', '', 25549),
(132098, 'esMX', '', 'Espero que encuentres a este Raalgar antes que la Legión. Alguien del Vindicaar te ayudará.', 25549),
(132097, 'esMX', '', '¡Eso sonó mucho mejor en mi cabeza que dicho en voz alta!', 25549),
(132091, 'esMX', 'Ya veo. Gracias.', 'Ya veo. Gracias.', 25549),
(132090, 'esMX', 'No particularmente. Las líneas ley se han mostrado erráticas de nuevo, pero eso es normal en esta parte del mundo.', '', 25549),
(132089, 'esMX', 'De hecho, sí. La Jardinera del Santuario de Dragones esmeralda ha tenido problemas para mantener a los soñadores dormidos. Varios de los ancianos han despertado inesperadamente del Sueño, y aún no hemos podido descubrir el motivo.', '', 25549),
(132088, 'esMX', '', 'Los muertos se levantan una vez más.\n\nEl Santuario de Dragones rubí tiene una historia conflictiva con los no-muertos. Esa lucha se acabó tras la caída del Rey Exánime. Sin embargo, últimamente estos incidentes han ocurrido con más frecuencia.', 25549),
(132087, 'esMX', '¿Has visto algo extraño últimamente?', '¿Has visto algo extraño últimamente?', 25549),
(132086, 'esMX', 'Hay algo extraño en tu aura, $r. Tu presencia parece... de otro mundo. Como si no pertenecieras a este lugar.\n\n<Kalecgos observa a Cromi.>\n\nAh, ya veo. Viajas en el tiempo. Quizás... esa sea la explicación.\n\n<Kalecgos te observa con recelo.>', '', 25549),
(132085, 'esMX', 'Veo que vienes $Gacompañado:acompañada; por Chronormu. Si me permites preguntar... ¿vienes del futuro o del pasado?\n\nPensándolo bien, no hace falta que me respondas. Es mejor dejarle esos asuntos a los de bronce.', '', 25549),
(132084, 'esMX', '', '¿Yo... estoy en problemas?', 25549),
(132083, 'esMX', '', '¡$GBienvenido:Bienvenida; a Reposo del Dragón, $Gviajero:viajera; del tiempo! El consejo está a tu disposición si nos necesitas.', 25549),
(132082, 'esMX', '<Los ojos ya sin vida de la decodificadora observan el cielo. Un tomo delgado descansa debajo de su cadáver.>', '', 25549),
(132080, 'esMX', '<Toma el libro de códigos.>', '<Toma el libro de códigos.>', 25549),
(132078, 'esMX', '<Toma la misiva>', '<Toma la misiva>', 25549),
(132077, 'esMX', '<Logras divisar una parte de una misiva escondida en los brazales del mensajero.>', '', 25549),
(132075, 'esMX', 'Las estelas ardientes del terreno le recordarán a la Legión que es imposible silenciar nuestra resistencia. Gracias.', '', 25549),
(132074, 'esMX', 'Los man''ari torturan a los de mi clase con sus rituales de magia vil. Que sus palabras oscuras se purifiquen... ¡con fuego!', '', 25549),
(132073, 'esMX', '¡Vamos, tratemos de salvarte de nuevo!', '¡Vamos, tratemos de salvarte de nuevo!', 25549),
(132072, 'esMX', 'Estas aguas están malditas. No te rindas ante la sed.', '', 25549),
(132071, 'esMX', '', 'Seguro que podemos descifrar esto. Avísame cuando termines de prepararte.', 25549),
(132069, 'esMX', 'Mira. El camino está cerrado. ¿Cómo llegaremos a Isolon ahora?', '', 25549),
(132065, 'esMX', '', 'Intentémoslo de nuevo. Esta vez tendremos un POQUITO más de tiempo antes de mi asesinato. ¿Todo listo?', 25549),
(132064, 'esMX', '', '¿Todo listo? No hay tiempo como el presente... créeme.', 25549),
(132063, 'esMX', 'Estoy listo. ¡Vamos!', 'Estoy lista. ¡Vamos!', 25549),
(132062, 'esMX', '', '¡Hola de nuevo!', 25549),
(132052, 'esMX', 'Arkhaan lo sabe, sí.', '', 25549),
(132051, 'esMX', '', 'Arkhaan, ¿verdad? ¿Podrías decirnos qué le pasó a tu pueblo?', 25549),
(132036, 'esMX', '', 'El tiempo cura todas las heridas... excepto... las mortales…', 25549),
(132035, 'esMX', '', 'Lo siento...', 25549),
(132034, 'esMX', '', 'Esto no era lo que debía pasar... ', 25549),
(132033, 'esMX', '', 'Parece que es mi hora... de...', 25549),
(132032, 'esMX', '', 'Quizá la próxima...', 25549),
(132031, 'esMX', '', 'No… esto no debería pasar así… ', 25549),
(132030, 'esMX', '', '¡Sí, lo logré!', 25549),
(132029, 'esMX', '', '¡Ah, fantástico! ¡Todo salió bien!', 25549),
(132028, 'esMX', '', 'Lo siento, pero... así son las cosas.', 25549),
(132027, 'esMX', '', '¡Uhh! ¡Se te acabó el tiempo!', 25549),
(132026, 'esMX', '', 'Deberías saber que soy más poderosa de lo que parezco.', 25549),
(132025, 'esMX', '', '¡Aquí vamos!', 25549),
(132024, 'esMX', '', '¡El flujo temporal no se reparará solo!', 25549),
(132023, 'esMX', '', '¡Es hora de que yo misma me haga cargo de esto!', 25549),
(132022, 'esMX', '', 'Y ahora me tocaba atacar a ESTE...', 25549),
(132021, 'esMX', '', 'Umm... perdóname.', 25549),
(132018, 'esMX', 'Soy uno con la Luz. La Luz me acompaña.', '', 25549),
(132014, 'esMX', '', 'Quizá podamos usarlos para facilitar las cosas en Andorhal.', 25549),
(132013, 'esMX', '', 'Qué interesante... estos documentos dicen que el portador es alguien importante del Círculo Cenarion.', 25549),
(132012, 'esMX', '', 'No nos sirve de mucho aquí, pero quizás en el Pozo de la Eternidad...', 25549),
(132011, 'esMX', '', '¿La piedra lunar de Tyrande? ¿Cómo encontraste ESTO?', 25549),
(132008, 'esMX', '', 'Creo que podemos usar esto para irritar a los elementales de fuego del Monte Hyjal.', 25549),
(132007, 'esMX', '', 'Un faro de azufre... ¡Fascinante!', 25549),
(132006, 'esMX', '', 'Tenla a mano la próxima vez que visitemos Stratholme.', 25549),
(132005, 'esMX', '', '¿Eso es una llave para la puerta de Stratholme? ¡Ja! ¡Debe ser nuestro día de suerte!', 25549),
(131993, 'esMX', '', '¡Nos vemos la próxima vez, $n!', 25549),
(131992, 'esMX', '', '¡Pero ese es un problema para nuestros yo del futuro! Bueno, para el tú del futuro y el yo del pasado. Eh, no te preocupes. El tiempo es complicado.', 25549),
(131991, 'esMX', '', '¿Por qué todos están tan enfadados conmigo? Creo que deberíamos averiguarlo algún día.', 25549),
(131990, 'esMX', '', 'Muchísimas personas estaban decididas a matarme. Demonios, elementales, no-muertos, señores del vacío... ¡Incluso la Horda y la Alianza!', 25549),
(131989, 'esMX', '', 'Aunque todavía HAY algunas cosas que me molestan...', 25549),
(131988, 'esMX', '', '¡Qué bien!', 25549),
(131987, 'esMX', '', 'Parece que... todo volvió a la normalidad. Las líneas temporales son más claras. Ya no veo mi muerte.', 25549),
(131986, 'esMX', '', '¡Uf! Ya debería estar a salvo.', 25549),
(131985, 'esMX', '', '¡Allí está el portal! ¡Vamos!', 25549),
(131984, 'esMX', '', 'Debería haber un portal temporal activo al otro lado del Pozo. Conozco el camino. ¡Sígueme!', 25549),
(131983, 'esMX', '', 'Estas heridas viles sí que se ven mal. Tenemos que llevarme de regreso a Reposo del Dragón.', 25549),
(131982, 'esMX', '', '¡Oh, no! ¡Allí estoy!', 25549),
(131981, 'esMX', '', 'El Pozo de la Eternidad, justo antes de la Guerra de los Ancestros. Unos diez mil años antes de tu época, $n. Más o menos.', 25549),
(131980, 'esMX', '', 'Estaré bien, creo. ¡Gracias por la ayuda!', 25549),
(131979, 'esMX', '', '¿Te sientes mejor?', 25549),
(131978, 'esMX', '', 'No te preocupes. ¡Te protegeremos!', 25549),
(131977, 'esMX', '', 'Ay... ¡Estoy herida! Pero puedo sanarme... solo necesito un poco más de tiempo.', 25549),
(131976, 'esMX', '', '¡Allí estoy!', 25549),
(131975, 'esMX', '', 'Mmm, no recuerdo que hubiera tantos elementales de fuego por aquí...', 25549),
(131974, 'esMX', '', '¡Esto lo recuerdo! Debo estar un poco más adelante.', 25549),
(131973, 'esMX', '', 'Veamos... estamos en el Monte Hyjal, poco después del tiempo del Cataclismo.', 25549),
(131972, 'esMX', '', '¡No hay problema!', 25549),
(131971, 'esMX', '', '¡Muchas gracias por salvarme, yo!', 25549),
(131970, 'esMX', '', '¡Uuy! Esa criatura sí que es fea. Bueno, no hay forma de evadirla. Parece que tendremos que enfrentarla.', 25549),
(131969, 'esMX', '', '¡Supongo que iremos a Stratholme! Movámonos, ¡no tenemos mucho tiempo!', 25549),
(131968, 'esMX', 'No pude repelerlos. ¡Te han llevado a la ciudad!', '', 25549),
(131967, 'esMX', '¡Cromi! Gracias a las arenas que llegaste. ¡Te han llevado a la ciudad!', '', 25549),
(131966, 'esMX', '', 'Stratholme, durante la Tercera Guerra. Recuerdo este día: el príncipe Arthas no estaba precisamente en su mejor momento.', 25549),
(131965, 'esMX', '', 'Eso creo. ¡Nos vemos la próxima!', 25549),
(131964, 'esMX', '', 'El cañón está destruido. ¿Puedes salir?', 25549),
(131963, 'esMX', '', 'Puedo resistir aquí, pero no puedo volar con ese cañón apuntando al cielo.', 25549),
(131962, 'esMX', '', '¿La ALIANZA también me busca? ¿Qué está pasando?', 25549),
(131961, 'esMX', '¡Soldados de la Alianza! ¡Mantengan la posición! No puede esconderse para siempre.', '', 25549),
(131960, 'esMX', '', '¿Ves? Ese es el problema de ser una gnoma. A veces los soldados de la Horda tienen la necesidad de PATEARTE. ¡Uuoohh!', 25549),
(131959, 'esMX', '¡Ahí está! Ya tienen sus órdenes. ¡Asesinen al dragón!', '', 25549),
(131958, 'esMX', '', 'Andorhal, unos meses después del Cataclismo. Estamos en medio de una batalla entre la Horda y la Alianza.', 25549),
(131957, 'esMX', '', '¡Guau... este es viejo pero me gusta! Este portal lleva al Pozo de la Eternidad.', 25549),
(131956, 'esMX', '', 'Veo... un portal a Stratholme, de los días de la Tercera Guerra.', 25549),
(131955, 'esMX', '', '¡Ajá! ¡Un portal al Monte Hyjal! Me encanta posarme en el árbol de allí cuando hace calor.', 25549),
(131954, 'esMX', '', 'Qué interesante... un portal a Andorhal. ¡Es uno de mis lugares favoritos de todos los tiempos! Veamos si estoy en problemas.', 25549),
(131953, 'esMX', '', '¡Estos tipos sí que saben lo que hacen! No me sorprendería que tuvieran un dragón de bronce de su lado.', 25549),
(131952, 'esMX', '', 'Veo que no entiendes muy bien qué significa eso. Básicamente, van a atacarme en distintas coyunturas temporales al mismo tiempo.', 25549),
(131951, 'esMX', '', 'Tengo la leve sospecha de que el enemigo está planeando un ataque multisincronizado. ¿Por qué, si no, usarían cronofragmentos?', 25549),
(131950, 'esMX', '', 'Y mira esto... estaba llevando un cronofragmento. Tengo que llevarlo a Reposo del Dragón para descubrir a dónde lleva.', 25549),
(131949, 'esMX', '', 'Jamás creí que me convertiría en la enemiga de un SEÑOR DEL VACÍO. Increíble…', 25549),
(131948, 'esMX', '', 'Evitemos las líneas Ley y vayamos directo a ese señor del vacío. ¡El tiempo es valioso!', 25549),
(131947, 'esMX', '', 'Vayamos y busquemos pistas. Quizá las perturbaciones provengan de quien sea que quiera matarme.', 25549),
(131946, 'esMX', '', '¡Mira esto! Un cronofragmento. Deberíamos llevarlo de regreso a Reposo del Dragón.', 25549),
(131945, 'esMX', '', 'Qué extraño. No recuerdo que los sátiros fueran mis enemigos, ni ahora NI en el futuro.', 25549),
(131944, 'esMX', '', 'Recuerda, el sátiro está allí en esa garra ósea cerca del agua. ¡Acabemos con él!', 25549),
(131943, 'esMX', '', '¡Vamos!', 25549),
(131942, 'esMX', '', 'Los soñadores nos dieron tres pistas... Gran pesadilla, cerca del agua, palma del dragón... Solo debemos descubrir qué significan.', 25549),
(131941, 'esMX', '', 'Nosotros podemos ayudar, ¿verdad?', 25549),
(131940, 'esMX', '', '¡Podemos ayudar con eso!', 25549),
(131938, 'esMX', '', 'Mmm... un cronofragmento. Llevémoslo a Reposo del Dragón. Me pregunto a qué lugar y a qué tiempo lleva.', 25549),
(131937, 'esMX', '', 'Me pregunto qué querrá la Legión de mi humilde personita.', 25549),
(131936, 'esMX', '', 'Afortunadamente, ya sabemos del señor del terror que maneja los hilos desde la oscuridad. ¡Matémoslo antes de que me mate a mí!', 25549),
(131935, 'esMX', '', 'Y parece que reveló su ubicación. ¡Ja! ¡Vayamos a la entrada del Santuario de Dragones obsidiana y saquémoslo de allí!', 25549),
(131934, 'esMX', '', '¿Un señor del terror? Y una dragona de bronce... Un momento, ¿está hablando sobre mí?', 25549),
(131933, 'esMX', '', 'En eso tiene razón. Busquemos pistas en esa caverna tenebrosa.', 25549),
(131932, 'esMX', '', '¿Eh? ¿Qué es esto? ¿Una especie de cronofragmento? Tendré que llevarlo de regreso a Reposo del Dragón para investigar.', 25549),
(131930, 'esMX', '', '¡Así es como se debe lidiar con una amenaza a tiempo!', 25549),
(131929, 'esMX', '', 'Podemos ir directamente por ese exánime, $n. Si de verdad está orquestando este ataque, matarlo debería dispersar sus fuerzas.', 25549),
(131928, 'esMX', '', 'Está dentro del árbol, ¿verdad? Vayamos a buscarlo. ¡Llegó su hora!', 25549),
(131927, 'esMX', '', '¡Un exánime! ¡Grr! Ya me lo imaginaba... Aunque es extraño que no lo viera en ninguna línea temporal futura.', 25549),
(131926, 'esMX', '', 'Vamos, $n. Encarguémonos de los líderes no-muertos. Quizás ellos sepan algo sobre el próximo ataque.', 25549),
(131925, 'esMX', '', 'Parece que tenemos algunos Santuarios de Dragones que investigar. Vamos a, eh... ¡investigar Santuarios de Dragones!', 25549),
(131924, 'esMX', '', '¿Perturbaciones en las líneas Ley? Bah... típicos problemas de dragones azules.', 25549),
(131923, 'esMX', '', 'Gracias, Lord Itharius. Echaremos un vistazo y te avisaremos si descubrimos algo.', 25549),
(131922, 'esMX', '', 'Lo investigaremos. ¡Gracias!', 25549),
(131921, 'esMX', '', 'Estoy bastante segura de que se dirigía al Santuario de Dragones obsidiana.', 25549),
(131920, 'esMX', '', '¿Extraño? Déjame pensar... ¡Oh! Es cierto, vi a ese dragón negro hoy. ¿Cómo se llamaba? ¿Alamuerte? No, no, ese no... el otro. El del sombrero.', 25549),
(131919, 'esMX', '', '¿Ataques de no-muertos en el Santuario de Dragones rubí? Daremos un vistazo. Gracias, Ale.', 25549),
(131918, 'esMX', '', 'Investiguemos un poco y veamos si podemos descubrir de dónde vienen estas descargas sombrías.', 25549),
(131917, 'esMX', '', 'Quizá no sea suficiente para salvarme, pero es lo mejor que puedo hacer por ahora.', 25549),
(131916, 'esMX', '', 'En este momento faltan 15 minutos para mi muerte.', 25549),
(131915, 'esMX', '', '¡Ah, sip, ahí está!', 25549),
(131914, 'esMX', '', 'Intentémoslo una vez más...', 25549),
(131913, 'esMX', '', 'Ahora sí que empiezo a preocuparme, $n. Quien sea que haya orquestado este ataque hizo bien su trabajo. ¡Encontraron una forma de bloquear mis cronotransportaciones!', 25549),
(131912, 'esMX', '', '¡No importa! Cuatro horas era mucho tiempo de todos modos. Probemos con una.', 25549),
(131911, 'esMX', '', 'Mmm. Qué extraño. Algo me impide acceder a ese preciso momento.', 25549),
(131910, 'esMX', '', 'Bien, voy a cronotransportarnos a un punto cuatro horas antes de que suceda el ataque. Eso nos dará MUCHÍSIMO tiempo para arreglar este desastre.', 25549),
(131909, 'esMX', '', 'Alguien está tratando de matarte. De hecho, debería suceder en cualquier momento...', 25549),
(131908, 'esMX', '', '¿Y adónde vamos? ¿Por qué estamos abandonando Reposo del Dragón?', 25549),
(131907, 'esMX', '', '¡Oh! Bueno, está bien. Tu guía nunca me falló en el pasado. Ni en el futuro.', 25549),
(131906, 'esMX', '', '¡Sígueme! ¡No tenemos mucho tiempo!', 25549),
(131905, 'esMX', '', '¡Ah, hola! ¿Qué estoy haciendo aquí?', 25549),
(131904, 'esMX', '', '¡Ey! ¡Cromi!', 25549),
(131903, 'esMX', '', 'Esta vez conseguí algunos segundos más, pero tenemos que movernos rápido.', 25549),
(131902, 'esMX', '', 'Aquí vamos... ¡de nuevo!', 25549),
(131901, 'esMX', '', '¡Ah, hola! ¿Qué estás haciendo aquí?', 25549),
(131900, 'esMX', '', 'Ah, bien. Allí estoy. ¡Hola, yo!', 25549),
(131899, 'esMX', '', 'Bueno... veamos. Creo que es el momento indicado... un minuto más, un minuto menos. ¿Ya estoy muerta?', 25549),
(131898, 'esMX', '', 'Sujétate del casco... ¡viajaremos por el TIEMPO!', 25549),
(131891, 'esMX', '', 'Todo lo que hicimos fue para mantenerte a salvo. Tener que alejarnos de ti nos rompió el corazón.', 25549),
(131890, 'esMX', 'Arator... No hubo un día en el que tu madre y yo no...', '', 25549),
(131889, 'esMX', 'Pero... ¿No podían comunicarse de ninguna forma? ¿Con su pueblo? ¿Conmigo?', '', 25549),
(131877, 'esMX', '<Activar la secuencia de teletransporte.>', '<Activar la secuencia de teletransporte.>', 25549),
(131876, 'esMX', '<La Sentencia de la Luz se encuentra incrustada en los costados de los riscos. Está intacta, pero claramente no está en funcionamiento. $b$bDeberías poder activar el protocolo de seguridad para teletransportarla al Vindicaar.>', '', 25549),
(131873, 'esMX', 'Argus. El trono de la Legión Ardiente. Sus maquinarias infernales son un ejército infinito para Sargeras.\n\nEs hora de privar al Titán Oscuro de su premio.\n\nNuestro camino es claro. Debemos llevar la batalla a Argus y poner a la Legión de rodillas.', '', 25549),
(131872, 'esMX', 'La piedra angular sargerita desgarró la esencia misma de la realidad. Ahora el mundo de la Legión se yergue ante nosotros, con sus ejércitos listos para atacar.\n\nTuralyon está allí en algún lado. Alleria también... espero. Si podemos encontrar a mis viejos amigos, quizás el Ejército de la Luz pueda ayudarnos a poner fin a esta guerra.', '', 25549),
(131871, 'esMX', 'Siempre supe que vería Argus de nuevo. Nuestro regreso aparecía una y otra vez en mis visiones.\n\nPero nunca imaginé esto.\n\nNo hay dudas de que los destinos de mi mundo y el tuyo están entrelazados. ¿Habrá salvación para Argus, o habrá que sacrificarlo para detener a Sargeras? Mis visiones son nebulosas, inciertas.\n\nParece que debemos forjar nuestro propio destino. Que la Luz nos salve a todos, $n.', '', 25549),
(131866, 'esMX', 'Sí, Arkhaan llamó... Pero no esperaba...', '', 25549),
(131861, 'esMX', '¡Wooooooooooo!', '', 25549),
(131860, 'esMX', '¡Ooooooooooooooooh!', '', 25549),
(131859, 'esMX', '¡Aiiiiiiyaaaaahhhhhhh!', '', 25549),
(131858, 'esMX', '¡Yeeeeeeeeeee!', '', 25549),
(131857, 'esMX', '¡Aaaaaaaaaaaahhhhhhhh!', '', 25549),
(131856, 'esMX', '¡Aiiii!', '', 25549),
(131846, 'esMX', '', 'Te veré en las ruinas de abajo, $n. Empezaremos donde la oscuridad termina.', 25549),
(131837, 'esMX', '¡Despierta!', '', 25549),
(131835, 'esMX', '¡No estoy cansado!', '', 25549),
(131834, 'esMX', '¡No duermo!', '', 25549),
(131833, 'esMX', '¡No quiero dormir!', '', 25549),
(131823, 'esMX', '', 'Encontramos tus mensajes.', 25549),
(131822, 'esMX', '¡Una voz! Arkhaan nunca había oído algo así.', '', 25549),
(131821, 'esMX', '', 'Ven, acércate. No queremos lastimarte.', 25549),
(131820, 'esMX', '', 'Encontré un sobreviviente. Ven conmigo.', 25549),
(131817, 'esMX', 'No dejes que la larga noche oscura te doblegue. Acepta su dádiva.', '', 25549),
(131778, 'esMX', '|TInterface\\ICONS\\Spell_Deathknight_Necroticplague.blp:20|t ¡Estás $gafectado:afectada; por |cFFF00000|Hspell:244093|h[Abrazo necrótico]|h|r!', '', 25549),
(131773, 'esMX', '¡Esto es una locura!', '¡Esto es una locura!', 25549),
(131772, 'esMX', 'Nunca imaginé que así pasaría mi tiempo en Mac''Aree.', 'Nunca imaginé que pasaría mi tiempo en Mac''Aree de esta forma.', 25549),
(131770, 'esMX', '¡Maldito sea el Vacío por infestar a estas pobres criaturas!', '¡Maldito sea el Vacío por infestar a estas pobres criaturas!', 25549),
(131769, 'esMX', 'Creí que ese no se me escapaba.', 'Creí que ese no se me escapaba.', 25549),
(131768, 'esMX', '¡Solo queremos ayudarte, criatura!', '¡Solo queremos ayudarte, criatura!', 25549),
(131767, 'esMX', '¡No te muevas!', '¡No te muevas!', 25549),
(131762, 'esMX', 'Muéstrame.', 'Muéstrame.', 25549),
(131760, 'esMX', '', 'Debo mostrarte lo que he visto.', 25549),
(131759, 'esMX', '', 'La oscuridad nos acecha desde todos los ángulos. Actúa con prudencia.', 25549),
(131758, 'esMX', '', 'Mantén los ojos abiertos y no hagas ruido, $n.', 25549),
(131757, 'esMX', '', 'Las fuerzas que nos rodean escapan a nuestra comprensión. Mantente alerta.', 25549),
(131756, 'esMX', '', 'Hay una presencia familiar aquí. Oigo su llamado.', 25549),
(131753, 'esMX', 'Sin el Blasón del conocimiento, no podemos vencer.', '', 25549),
(131740, 'esMX', '', 'No hagamos esperar a nuestro hijo.', 25549),
(131673, 'esMX', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|tHas quedado $Gafectado:afectada; por |cFFFF0000|Hspell:236329|h[Quemadura estelar]|h|r. ¡Ocúltate detrás de los pilares infernales cuando te lancen Estrella destrozadora!', '', 25549),
(131669, 'esMX', '', 'La bestia se debilita. ¡Ataca!', 25549),
(131647, 'esMX', '|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t¡Lleva |cFFFF0000|Hspell:232913|h[Tinta contaminante]|h|r hasta Sarukel para acabar con sus |cFFFF0000|Hspell:234621|h[Fauces devoradoras]|h|r!', '', 25549),
(131601, 'esMX', 'La Horda ha perdido el control de las Minas.', '', 25549),
(131600, 'esMX', 'La Horda ha obtenido el control de las Minas.', '', 25549),
(131599, 'esMX', 'La Alianza ha perdido el control de las Minas.', '', 25549),
(131598, 'esMX', 'La Alianza ha obtenido el control de las Minas.', '', 25549),
(131597, 'esMX', 'La Horda ha perdido el control de la Cornisa.', '', 25549),
(131596, 'esMX', 'La Horda ha obtenido el control de la Cornisa.', '', 25549),
(131595, 'esMX', 'La Alianza ha perdido el control de la Cornisa.', '', 25549),
(131594, 'esMX', 'La Alianza ha obtenido el control de la Cornisa.', '', 25549),
(131593, 'esMX', 'La Horda ha perdido el control del Faro.', '', 25549),
(131592, 'esMX', 'La Horda ha obtenido el control del Faro.', '', 25549),
(131591, 'esMX', 'La Alianza ha perdido el control del Faro.', '', 25549),
(131590, 'esMX', 'La Alianza ha obtenido el control del Faro.', '', 25549),
(131589, 'esMX', 'La Horda ha perdido el control del Puente.', '', 25549),
(131588, 'esMX', 'La Horda ha obtenido el control del Puente.', '', 25549),
(131587, 'esMX', 'La Alianza ha perdido el control del Puente.', '', 25549),
(131586, 'esMX', 'La Alianza ha obtenido el control del Puente.', '', 25549),
(131585, 'esMX', 'La Horda ha perdido el control de la Estación de bombeo.', '', 25549),
(131584, 'esMX', 'La Horda ha obtenido el control de la Estación de bombeo.', '', 25549),
(131583, 'esMX', 'La Alianza ha perdido el control de la Estación de bombeo.', '', 25549),
(131582, 'esMX', 'La Alianza ha obtenido el control de la Estación de bombeo.', '', 25549),
(131581, 'esMX', 'La Horda ha perdido el control del Cruce.', '', 25549),
(131580, 'esMX', 'La Horda ha obtenido el control del Cruce.', '', 25549),
(131579, 'esMX', 'La Alianza ha perdido el control del Cruce.', '', 25549),
(131578, 'esMX', 'La Alianza ha obtenido el control del Cruce.', '', 25549),
(131577, 'esMX', 'La Horda ha perdido el control de la Costa.', '', 25549),
(131576, 'esMX', 'La Horda ha obtenido el control de la Costa.', '', 25549),
(131575, 'esMX', 'La Alianza ha perdido el control de la Costa.', '', 25549),
(131574, 'esMX', 'La Alianza ha obtenido el control de la Costa.', '', 25549),
(131573, 'esMX', 'La Horda ha perdido el control del Mirador.', '', 25549),
(131572, 'esMX', 'La Horda ha obtenido el control del Mirador.', '', 25549),
(131571, 'esMX', 'La Alianza ha perdido el control del Mirador.', '', 25549),
(131570, 'esMX', 'La Alianza ha obtenido el control del Mirador.', '', 25549),
(131569, 'esMX', '¡Mata al responsable de todo esto!', '', 25549),
(131568, 'esMX', 'Gracias por salvarme.', '', 25549),
(131567, 'esMX', 'Gracias.', '', 25549),
(131566, 'esMX', '¡Mata a Fuego de jade!', '', 25549),
(131565, 'esMX', '¡Clookle bajo tierra!', '', 25549),
(131564, 'esMX', '¡Salva a Clookle!', '', 25549),
(131563, 'esMX', '¡Busca a Clookle!', '', 25549),
(131561, 'esMX', '¡Ayuda a Clookle!', '', 25549),
(131559, 'esMX', '¡Fuego de jade tiene antídoto!', '', 25549),
(131557, 'esMX', '¡Eres $Gel:la; mejor!', '', 25549),
(131556, 'esMX', 'Eres increíble.', '', 25549),
(131555, 'esMX', '¡Hurra!', '', 25549),
(131554, 'esMX', '¡Iupi!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(131553, 'esMX', '¡Gracias!', '', 25549),
(131552, 'esMX', 'Te amo.', '', 25549),
(131551, 'esMX', '<La prole de lechúcico lunar parece estar muy feliz contigo.>', '', 25549),
(131550, 'esMX', 'Administra el antídoto.', 'Administra el antídoto.', 25549),
(131549, 'esMX', '...', '', 25549),
(131548, 'esMX', 'Ayúdame.', '', 25549),
(131547, 'esMX', 'Ayuda por favor.', '', 25549),
(131546, 'esMX', 'Ayuda...', '', 25549),
(131545, 'esMX', 'Agh...', '', 25549),
(131538, 'esMX', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s empieza a lanzar |cFFFF0000|Hspell:244509|h[Hermandad de las Sargerei]|h|r.', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s empieza a lanzar |cFFFF0000|Hspell:244509|h[Hermandad de las Sargerei]|h|r.', 25549),
