INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(130514, 'esMX', 'Efecto de sonido para las tropas', '', 25549),
(130513, 'esMX', 'Efecto de sonido para las tropas', 'Efecto de sonido para las tropas', 25549),
(130512, 'esMX', '¡Quiero participar en el Desafío de estilos!', '¡Quiero participar en el Desafío de estilos!', 25549),
(130511, 'esMX', 'Podremos obtener conocimiento de artefacto para ti en cuanto me traigas los recursos necesarios para producirlo.', 'Podremos obtener conocimiento de artefacto para ti en cuanto me traigas los recursos necesarios para producirlo.', 25549),
(130510, 'esMX', 'Quiero transfigurar mi equipo.', 'Quiero transfigurar mi equipo.', 25549),
(130509, 'esMX', 'Tengo todas las herramientas necesarias para ajustar la apariencia de tus armas y armadura.\n\n¿Empezamos?', '', 25549),
(130508, 'esMX', 'El archimago Khadgar tiene una pista sobre cómo seguir con nuestra investigación de conocimiento de artefacto. Búscalo en Punto de Liberación en la Costa Quebrada.', 'El archimago Khadgar tiene una pista sobre cómo seguir con nuestra investigación de conocimiento de artefacto. Búscalo en Punto de Liberación en la Costa Quebrada.', 25549),
(130507, 'esMX', 'Hemos alcanzado el conocimiento de artefacto máximo disponible para nosotros en este momento.', 'Hemos alcanzado el conocimiento de artefacto máximo disponible para nosotros en este momento.', 25549),
(130506, 'esMX', 'Las órdenes están compartiendo sus recursos, y ya no es necesario que investigues conocimiento de artefacto. Obtendremos más conocimiento cada semana.', 'Las órdenes están compartiendo sus recursos, y ya no es necesario que investigues conocimiento de artefacto. Obtendremos más conocimiento cada semana.', 25549),
(130505, 'esMX', '¿Por qué no puedo investigar conocimiento de artefacto?', '¿Por qué no puedo investigar conocimiento de artefacto?', 25549),
(130504, 'esMX', 'Sin importar lo que suceda, resistiremos juntos.', '', 25549),
(130503, 'esMX', '¡Más carne para devorar!', '', 25549),
(130502, 'esMX', '¡Tu carne alimentará estos pozos por toda la eternidad!', '', 25549),
(130501, 'esMX', '¡Nuestras cadenas ansían saborear tu carne!', '', 25549),
(130500, 'esMX', '¡Te arrodillarás o morirás!', '', 25549),
(130499, 'esMX', '¡Débil insensato! ¿Te atreves a entrar a nuestra guarida?', '', 25549),
(130498, 'esMX', '¡Tu carne tierna servirá para saciar mi hambre!', '', 25549),
(130497, 'esMX', 'Huesos frágiles. ¡Tan sabrosos y crujientes!', '', 25549),
(130496, 'esMX', 'Devoraré tu alma.', '', 25549),
(130483, 'esMX', '¡Mortal insolente! Ven... ¡Enfrenta tu muerte!', '', 25549),
(130482, 'esMX', 'Por aquí, $p. No dejes que te vean.', '', 25549),
(130481, 'esMX', 'Así es... el concurso de hoy no tiene temática. ¡Vístanse como quieran!', '', 25549),
(130480, 'esMX', '¡Togas blancas prístinas y armaduras brillantes a la orden del día!', '', 25549),
(130479, 'esMX', 'Como saben, la armadura épica SIEMPRE es púrpura. ¡Cúbranse con el último color del arcoíris!', '', 25549),
(130478, 'esMX', '¿Qué será hoy? ¿Granjero? ¿Cocinero? ¿Científico? ¿Pirata? Ooh... ¡Estoy ANSIOSO por v qué se les ocurre!', '', 25549),
(130477, 'esMX', '¿Representarán a Theramore? ¿El Kirin Tor? ¡Pónganse esos tabardos!', '', 25549),
(130476, 'esMX', '¡Es hora de divertirse y alocarse un poco con sus vestuarios!', '', 25549),
(130475, 'esMX', '¡Pulan esa armadura y prepárense para mostrar una buena pose!', '', 25549),
(130474, 'esMX', '¡Vístanse con pellejos de bestias, o envuélvanse en vides! Quiero ver su lado salvaje.', '', 25549),
(130473, 'esMX', '¡Por la Horda! ¡Por la Alianza! Veamos los colores de su equipo.', '', 25549),
(130472, 'esMX', '¡Veamos sus estilos más siniestros!', '', 25549),
(130471, 'esMX', 'Dicen que los opuestos se atraen. ¿Pero son realmente atractivos?', '', 25549),
(130470, 'esMX', '¡Diviértanse y vístanse con el conjunto más estridente que se les ocurra!', '', 25549),
(130469, 'esMX', '¡Quieto, corazón mío! ¡No teman mostrar un poco de piel!', '', 25549),
(130468, 'esMX', '¡Quítense el maquillaje y pónganse esa pintura de guerra!', '', 25549),
(130467, 'esMX', '¡Prepárense! ¡Veamos qué se usa en las costas heladas de Rasganorte!', '', 25549),
(130466, 'esMX', '', 'La temática de la competencia de hoy es... ¡estilo libre!', 25549),
(130465, 'esMX', '', 'La temática de la competencia de hoy es... ¡Campeones de la Luz!', 25549),
(130464, 'esMX', '', 'La temática de la competencia de hoy es... ¡púrpura épico!', 25549),
(130463, 'esMX', '', 'La temática de la competencia de hoy es... ¡héroes de todos los días!', 25549),
(130462, 'esMX', '', 'La temática de la competencia de hoy es... ¡hora de los tabardos!', 25549),
(130461, 'esMX', '', 'La temática de la competencia de hoy es... ¡hazme reír!', 25549),
(130460, 'esMX', '', 'La temática de la competencia de hoy es... ¡héroes de Azeroth!', 25549),
(130459, 'esMX', '', 'La temática de la competencia de hoy es... ¡estilo primigenio!', 25549),
(130458, 'esMX', '', 'La temática de la competencia de hoy es... ¡orgullo de la facción!', 25549),
(130457, 'esMX', '', 'La temática de la competencia de hoy es... ¡oscuro y letal!', 25549),
(130456, 'esMX', '', 'La temática de la competencia de hoy es... ¡fuego y hielo!', 25549),
(130455, 'esMX', '', 'La temática de la competencia de hoy es... ¡combinaciones caóticas!', 25549),
(130454, 'esMX', '', 'La temática de la competencia de hoy es... ¡divertido y provocador!', 25549),
(130453, 'esMX', '', 'La temática de la competencia de hoy es... ¡listo para la batalla!', 25549),
(130452, 'esMX', '', 'La temática de la competencia de hoy es... ¡indumentaria de invierno!', 25549),
(130450, 'esMX', 'Trato hecho. ¡Pero no vayas a olvidarlo!', '', 25549),
(130449, 'esMX', 'No te preocupes, hermanito. Si salimos de esta, cuando seas más grande te enseñaré a usar un cuchillo como me enseñó papá. ¿Qué dices?', '', 25549),
(130448, 'esMX', '¡Pero, mamá, dejas que Mycah pelee!', '', 25549),
(130447, 'esMX', '', 'Oro Junior, ¡quédate aquí! Tu padre quedaría devastado si algo te ocurriera.', 25549),
(130446, 'esMX', '¡Por favor, yo también quiero pelear!', '', 25549),
(130445, 'esMX', 'Si estoy muerta, ¿quién se encargará de mi familia?', 'Si estoy muerta, ¿quién se encargará de mi familia?', 25549),
(130444, 'esMX', 'No puedo estar muerta... que alguien me ayude...', 'No puedo estar muerta... que alguien me ayude...', 25549),
(130443, 'esMX', 'Por favor... ¡detén esta pesadilla!', 'Por favor... ¡detén esta pesadilla!', 25549),
(130442, 'esMX', '¿Dónde estoy? No recuerdo dónde estoy...', '¿Dónde estoy? No recuerdo dónde estoy...', 25549),
(130441, 'esMX', 'No quiero morir...', 'No quiero morir...', 25549),
(130440, 'esMX', '¿Qué me sucedió? ¿Dónde está mi cuerpo?', '¿Qué me sucedió? ¿Dónde está mi cuerpo?', 25549),
(130439, 'esMX', '', 'Eso es todo por hoy. ¡Nos vemos la próxima!', 25549),
(130438, 'esMX', '', 'Y a todos los demás, sigan esforzándose. Pronto se convertirán en campeones.', 25549),
(130437, 'esMX', '', 'Y por último, $Gnuestro gran campeón:nuestra gran campeona; de la noche. ¡Un aplauso para $n!', 25549),
(130436, 'esMX', '¡En segundo lugar tenemos a... $n! ¡Te veías $Gfabuloso:fabulosa; ahí!', '', 25549),
(130435, 'esMX', '', '¡Y el tercer puesto es para... $n! ¡Felicitaciones, $n!', 25549),
(130434, 'esMX', '¡Y a la derecha, $Gel:la; inimitable $n!', '', 25549),
(130433, 'esMX', 'Gracias por esta gentileza. Nunca te olvidaré...', 'Gracias por esta gentileza. Nunca te olvidaré...', 25549),
(130432, 'esMX', 'Fue un honor servir a Ventormenta... ¡servir a mi rey!', 'Fue un honor servir a Ventormenta... ¡servir a mi rey!', 25549),
(130431, 'esMX', '', 'A su izquierda, $Gel fabuloso:la fabulosa; $n!', 25549),
(130430, 'esMX', 'Puedo verla... veo la Luz... Gracias.', 'Puedo verla... veo la Luz... Gracias.', 25549),
(130429, 'esMX', 'Fue un honor servir a mi rey...', 'Fue un honor servir a mi rey...', 25549),
(130428, 'esMX', 'Al fin, la pesadilla termina...', 'Al fin, la pesadilla termina...', 25549),
(130427, 'esMX', 'Gracias. Nunca olvidaré esta gentileza...', 'Gracias. Nunca olvidaré esta gentileza...', 25549),
(130426, 'esMX', 'Por favor... nunca nos olvides. Nunca olvides nuestro sacrificio...', 'Por favor... nunca nos olvides. Nunca olvides nuestro sacrificio...', 25549),
(130425, 'esMX', '', 'La Legión Ardiente se acerca a Azeroth. ¡Todos debemos hacer nuestra parte!', 25549),
(130424, 'esMX', '|TInterface\\Icons\\ABILITY_WARLOCK_INFERNO.BLP:20|t¡%s te ha marcado con |cFFFF0000|Hspell:238430|h[Llama aterradora explosiva]|h|r!', '|TInterface\\Icons\\ABILITY_WARLOCK_INFERNO:20|t¡%s te ha marcado con |cFFFF0000|Hspell:238430|h[Llama aterradora explosiva]|h|r!', 25549),
(130423, 'esMX', '¡Estoy listo!', '¡Estoy lista!', 25549),
(130422, 'esMX', '', '$ct, los alquimistas felskorn de esta área son cada vez más agresivos. Hace poco se robaron un cargamento de nuestro brebaje. Y lo que es peor, parece que lo han modificado para mejorarse y ahora lo están rociando con sus propagadores!\n\nHay que detenerlos, pero no será fácil sin ayuda. Por fortuna, el Rey Mono nos ha prestado su garrocha. ¡Úsala para saltar por encima de sus cabezas y castigarlos desde las alturas!\n\n¿Nos ayudarás?', 25549),
(130421, 'esMX', 'La competencia comienza en dos minutos. ¡Buena suerte, $Ggalán:preciosa;!', '', 25549),
(130420, 'esMX', '', 'También tenemos sillas de peluquería, por si necesitas retocar tu peinado.', 25549),
(130419, 'esMX', '', 'Tómate los próximos minutos para preparar tu vestuario.', 25549),
(130418, 'esMX', 'Aah, me encanta un buen par de pantalones cortos.', '', 25549),
(130417, 'esMX', '', 'La temática de la competencia de hoy es... ¡estilos de verano!', 25549),
(130416, 'esMX', 'Espero que hayas traído tu guardarropas, ¡porque la competencia de hoy parece FEROZ!', '', 25549),
(130415, 'esMX', '', '¡Rápido, Alto inquisidor! ¡El enemigo se acerca!', 25549),
(130414, 'esMX', '', '¡$GBienvenido:Bienvenida; al Desafío de estilos: el mejor lugar para la moda en Azeroth!', 25549),
(130413, 'esMX', 'Juntos, acabaremos con esta bestia.', '', 25549),
(130412, 'esMX', '¡Maravíllate ante su gloria! ¡No puedes esconderte de lo inevitable!', '¡Maravíllate ante su gloria! ¡No puedes esconderte de lo inevitable!', 25549),
(130411, 'esMX', '¡Abre los ojos, $n! Solo te esperan mentiras en el interior. ¡La verdad está en los cielos!', '¡Abre los ojos, $n! Solo te esperan mentiras en el interior. ¡La verdad está en los cielos!', 25549),
(130410, 'esMX', '¡Este lugar solo ofrece promesas vacías! ¡Las riquezas no te salvarán!', '¡Este lugar solo ofrece promesas vacías! ¡Las riquezas no te salvarán!', 25549),
(130409, 'esMX', '¡Las posesiones son insignificantes! ¡Mira al cielo! ¡El final está por llegar!', '¡Las posesiones son insignificantes! ¡Mira al cielo! ¡El final está por llegar!', 25549),
(130408, 'esMX', '¡Los bienes materiales no podrán salvarte, $n!', '¡Los bienes materiales no podrán salvarte, $n!', 25549),
(130406, 'esMX', '¡Una gran verdad se revela!', '¡Una gran verdad se revela!', 25549),
(130405, 'esMX', '¡Mira al cielo! ¡Un gran destino se revela ante nosotros!', '¡Mira al cielo! ¡Un gran destino se revela ante nosotros!', 25549),
(130404, 'esMX', '¡Abre los brazos y recibe lo que el destino te depara!', '¡Abre los brazos y recibe lo que el destino te depara!', 25549),
(130403, 'esMX', '¡Al fin ha llegado el momento! ¡El viaje final está ante nosotros!', '¡Al fin ha llegado el momento! ¡El viaje final está ante nosotros!', 25549),
(130402, 'esMX', 'He soñado con este momento por tanto tiempo, pero jamás imaginé que sería tan... hermoso.', 'He soñado con este momento por tanto tiempo, pero jamás imaginé que sería tan... hermoso.', 25549),
(130401, 'esMX', '¿Has resucitado a alguna criatura interesante últimamente?', '¿Has resucitado a alguna criatura interesante últimamente?', 25549),
(130400, 'esMX', 'El Maestro del tesoro Iks''reeged te hace un gesto ofensivo.', '', 25549),
(130399, 'esMX', '|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t ¡El Avatar caído invoca |cFFFF0404|Hspell:242017|h[Vientos negros]|h|r!', '|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t ¡El Avatar caído invoca |cFFFF0404|Hspell:242017|h[Vientos negros]|h|r!', 25549),
(130398, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t¡%s está lanzando |cFFFF0000|Hspell:240910|h[Armagedón]|h|r!', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t¡%s está lanzando |cFFFF0000|Hspell:240910|h[Armagedón]|h|r!', 25549),
(130397, 'esMX', '|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t¡%s crea una |cFFFF0000|Hspell:235059|h[Singularidad de ruptura]|h|r!', '|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t¡%s crea una |cFFFF0000|Hspell:235059|h[Singularidad de ruptura]|h|r!', 25549),
(130396, 'esMX', '¿Has logrado algún hallazgo raro?', '¿Has logrado algún hallazgo raro?', 25549),
(130395, 'esMX', 'Nada por el momento.', 'Nada por el momento.', 25549),
(130394, 'esMX', '¿Tienes algún artilugio demoníaco raro en ese saco?', '¿Tienes algún artilugio demoníaco raro en ese saco?', 25549),
(130393, 'esMX', 'Debes buscar tu camino hacia la Luz, amiga mía. Ha llegado el momento de que descanses.', 'Debes buscar tu camino hacia la Luz, amiga mía. Ha llegado el momento de que descanses.', 25549),
(130392, 'esMX', 'No, ¡no puedo estar muerta! Tengo una familia... ¡No puedo abandonarlos! ¿Cómo sobrevivirán sin mí?', 'No, ¡no puedo estar muerta! Tengo una familia... ¡No puedo abandonarlos! ¿Cómo sobrevivirán sin mí?', 25549),
(130391, 'esMX', '¿Dónde estoy? Estaba peleando en la Costa Quebrada... ¿Pueden oírme? Por los dioses... ¿estoy... muerto?', '¿Dónde estoy? Estaba peleando en la Costa Quebrada... ¿Pueden oírme? Por los dioses... ¿estoy... muerta?', 25549),
(130390, 'esMX', 'No... no encuentro mi cuerpo. Estaba atrapada en la máquina de almas y ahora... ¿dónde está? ¡¿Qué me sucedió?!', 'No... no encuentro mi cuerpo. Estaba atrapada en la máquina de almas y ahora... ¿dónde está? ¡¿Qué me sucedió?!', 25549),
(130380, 'esMX', '¡Argh! ¡¿Qué hay en la caja?! ¡¿Qué tiene?!', '', 25549),
(130379, 'esMX', '¡Jaja! ¡Demasiado tarde, mortal!', '', 25549),
(130378, 'esMX', '¿Tú otra vez? ¡No te quedarás con mi tesoro!', '', 25549),
(130377, 'esMX', '¡Demasiado tarde! ¡Ya me llevé las cosas buenas!', '', 25549),
(130376, 'esMX', 'La Costa Quebrada.', 'La Costa Quebrada.', 25549),
(130375, 'esMX', '%s lucha contra el dolor que invade su cuerpo.', '%s lucha contra el dolor que invade su cuerpo.', 25549),
(130374, 'esMX', '%s se retuerce de dolor.', '%s se retuerce de dolor.', 25549),
(130373, 'esMX', 'Pheta vi hylas.', '', 25549),
(130371, 'esMX', '¡Krona ki cristorr!', '', 25549),
(130370, 'esMX', 'No podrán... quebrantar nuestra voluntad.', '', 25549),
(130369, 'esMX', 'Este dolor... es solo temporal.', '', 25549),
(130368, 'esMX', 'No... podrás... con nosotros.', '', 25549),
(130367, 'esMX', 'La Costa Quebrada es una tierra destrozada y desolada. Ahora entiendo que era necesario que lo viera por mí mismo.', '', 25549),
(130362, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t ¡El Avatar caído lanza |cFFFF0404|Hspell:234418|h[Lluvia del destructor]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t ¡El Avatar caído lanza |cFFFF0404|Hspell:234418|h[Lluvia del destructor]|h|r!', 25549),
(130360, 'esMX', 'LOS ASESINOS DE LA LEGIÓN HAN SIDO ELIMINADOS. ESTÁS A SALVO... POR AHORA.', 'LOS ASESINOS DE LA LEGIÓN HAN SIDO ELIMINADOS. ESTÁS A SALVO... POR AHORA.', 25549),
(130359, 'esMX', '', 'Discúlpame, Velen. Te lo explicaré cuando tengamos un momento.', 25549),
(130358, 'esMX', '¿Alleria?', '', 25549),
(130357, 'esMX', '', 'No estás a salvo aquí. Debemos movernos. Ahora.', 25549),
(130356, 'esMX', '', '¡Profeta!', 25549),
(130355, 'esMX', '|TInterface\\Icons\\spell_hunter_lonewolf:20|t ¡%s comienza a lanzar |cFFFF0404|Hspell:241772|h[Aullido sobrenatural]|h|r!', '', 25549),
(130354, 'esMX', '|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t¡%s te marca con |cFFFF0000|Hspell:236011|h[Gritos atormentados]|h|r!', '', 25549),
(130351, 'esMX', '¡Sí! ¡Otórgame Abrecaminos de las Islas Quebradas I y II y mi montura de clase final!', '¡Sí! ¡Otórgame Abrecaminos de las Islas Quebradas I y II y mi montura de clase final!', 25549),
(130350, 'esMX', '¡Ey, tú! ¿Nos ayudarías a probar la habilidad para volar en las Islas Quebradas?\n\n¡Para hacer más tentadora la oferta, te otorgaré también la misión para tu montura de clase!\n\n¿Qué dices?', '', 25549),
(130349, 'esMX', '¡Mi ENCANTA esta mochila helada! ¡Ja, ja!', '', 25549),
(130348, 'esMX', '¡Helado de ogro! ¡Ja!', '', 25549),
(130347, 'esMX', '¡Ja, ja! Estúpido ogro congelado.', '', 25549),
(130346, 'esMX', '¿Estás segura de tu decisión? Esta mención del artesano de armaduras solo te permite forjar un objeto legendario.', '¿Estás segura de tu decisión? Esta mención del artesano de armaduras solo te permite forjar un objeto legendario.', 25549),
(130345, 'esMX', 'Quiero crear un cinturón de placas.\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[Valor inalterable de Rethu]|h', 'Quiero crear un cinturón de placas.\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[Valor inalterable de Rethu]|h', 25549),
(130344, 'esMX', 'Quiero crear guantes de malla.\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[Percha de la vigilancia]|h', 'Quiero crear guantes de malla.\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[Percha de la vigilancia]|h', 25549),
(130343, 'esMX', 'Quiero crear botas de cuero.\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[Refugio eterno del centinela]|h', 'Quiero crear botas de cuero.\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[Refugio eterno del centinela]|h', 25549),
(130342, 'esMX', 'Quiero crear sobrehombros a medida.\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[Celumbra, la Dicotomía nocturna]|h', 'Quiero crear sobrehombros a medida.\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[Celumbra, la Dicotomía nocturna]|h', 25549),
(130341, 'esMX', 'Ahora, algo sumamente importante: debemos elegir el tipo de armadura que quieres fabricar. Elige con cuidado, tu mención solo te otorga una lección.', '', 25549),
(130338, 'esMX', 'El resto, regresen a la academia. Queda claro que necesitan varios cientos de años más de instrucción.', '', 25549),
(130337, 'esMX', '', 'Mmm... Me gustan $Glos escribas talentosos:las escribas talentosas;. Sigamos en contacto.', 25549),
(130336, 'esMX', '¡Te mereces una recompensa! Toma, espero que esto te sea útil.', '', 25549),
(130335, 'esMX', '¡Bendita sea Elune! ¡Gracias, $Ghéroe:heroína;!', '', 25549),
(130334, 'esMX', '¿El pequeño pajarito quiere monedas de oro brillantes?', '¿El pequeño pajarito quiere monedas de oro brillantes?', 25549),
(130333, 'esMX', '¿Tienes algo a la venta?', '¿Tienes algo a la venta?', 25549),
(130332, 'esMX', '', 'Oohh, ¿un escriba? Me encanta cuando alguien escribe sobre mis pequeños... actos de dominación. Puede que sepa un secreto. Uno muy oscuro. \n\n¿Nunca revelaste el secreto de alguien? Porque yo sí.', 25549),
(130331, 'esMX', '¡Libertad! ¡Por este insulto tu sufrimiento será legendario, elfo!', '', 25549),
(130319, 'esMX', '', '<Simplemente guiña mucho el ojo.>', 25549),
(130316, 'esMX', '', 'Uuuh... Tengo tanto frío. ¿Serías tan amable de prenderte fuego para mí?', 25549),
(130314, 'esMX', '', 'Ah, tu moral es deliciosa.', 25549),
(130312, 'esMX', '', 'Ah, eres adorable, pero lamentablemente ya me contrataron.', 25549),
(130311, 'esMX', '', '¿Mmmmm....? Mmmmm.', 25549),
(130292, 'esMX', 'Ah, sí. Sé dónde está. Antes de la caída de Karazhan, Khadgar y yo lo investigamos un poco en mi sagrario, donde aún permanece. Me temo que no tuvimos mucho tiempo para aprender sobre su naturaleza. $b$bNormalmente, viajar hasta el sagrario sería una tarea sencilla. Sin embargo, el camino hacia el portal está bloqueado por los demonios de este sótano.$b$bDerrótalos y encontrarás el portal al final del camino. El Tridisco aún debería estar ahí.', '', 25549),
(130281, 'esMX', 'Estoy aquí para preguntar por el Tridisco de fuego.', 'Estoy aquí para preguntar por el Tridisco de fuego.', 25549),
(130257, 'esMX', 'Por favor, acepta esto como recompensa.', 'Por favor, acepta esto como recompensa.', 25549),
(130256, 'esMX', 'B... Bendita seas... Sigo... con vida, gracias a ti.', 'B... Bendita seas... Sigo... con vida, gracias a ti.', 25549),
(130255, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:233983|h[Angustia resonante]|h|r!', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:233983|h[Angustia resonante]|h|r!', 25549),
(130254, 'esMX', 'Aguarda un instante, $n. Primero, terminemos con la armadura que estamos haciendo.', '', 25549),
(130253, 'esMX', '¡Fantástico! De acuerdo, empecemos. ¡Te enseñaré todo sobre la armadura legendaria que siempre has soñado  forjar!', '', 25549),
(130252, 'esMX', 'Te he traído esta mención del artesano de armaduras.', 'Te he traído esta mención del artesano de armaduras.', 25549),
(130250, 'esMX', 'Prueba', '', 25549),
(130249, 'esMX', 'Es hora, $p. Marca el rumbo hacia Argus.', '', 25549),
(130248, 'esMX', '$GBienvenido:Bienvenida; al Exodar, $p.', '', 25549),
(130247, 'esMX', 'En marcha.', '', 25549),
(130244, 'esMX', 'Te han descubierto y han enviado un asesino a matarte.', 'Te han descubierto y han enviado un asesino a matarte.', 25549),
(130243, 'esMX', '', '¡Muchísimas gracias! Toma este cofre del alijo. ¡Te lo has ganado!', 25549),
(130242, 'esMX', '', '¡Ayuda! ¡Quieren llevarse mis suministros!', 25549),
(130241, 'esMX', 'Xoroth no será... derrotado...', '', 25549),
(130240, 'esMX', 'Los corceles nefastos son míos, $Gbrujo:bruja;... ¡Míos!', '', 25549),
(130239, 'esMX', '¡Te aplastaré, insecto!', '', 25549),
(130238, 'esMX', '¡Pagarás por tus transgresiones, $Gbrujo:bruja;!', '', 25549),
(130237, 'esMX', '', 'No quedan dudas de que ya has estado luchando contra las monstruosidades que han invadido nuestro bosque. Sin embargo, si pudiéramos extraer la corrupción más... viscosa... que se encuentra en el agua, estoy seguro de que también lograríamos una gran victoria. Te sugiero que lo intentes con una caña de pescar.', 25549),
(130236, 'esMX', '', '<Se estira y toma los glóbulos mientras mira hacia otro lado con expresión de disgusto.>\n\nGracias. Disfrutaré de destruirlos.', 25549),
(130235, 'esMX', '', 'La corrupción ahoga nuestras aguas y destruye la naturaleza que alguna vez la habitó. ¡Debemos defendernos!', 25549),
(130234, 'esMX', '', '¡Ah! Primero y principal, los koi están empezando a sobrepoblar la zona. Tal vez si atraparas a algunos de los más pequeños, podría transferirlos a otros ríos. \n\nTen cuidado con Magicus, el guardián del acuario.', 25549),
(130233, 'esMX', '', '¡Espléndido! Ten, simplemente ponlas en mi globo de agua encantado y yo me encargaré del resto.\n\n<Sha''leth parece estar distraída mirando a los pececitos.>', 25549),
(130232, 'esMX', '', 'Antes de mi exilio, era el guardián del acuario en la ciudad. ¡La vida que existe en el tanque aún es mi responsabilidad y no pienso abandonarla!', 25549),
(130231, 'esMX', 'El cuervo observa unos guijarros brillantes cerca de sus patas y luego dirige su mirada al agua. Tienes el presentimiento de que podrías recuperarlos con una caña de pescar.', '', 25549),
(130230, 'esMX', 'Corbyn grazna con alegría.', '', 25549),
(130229, 'esMX', 'El cuervo te mira e inclina su cabeza hacia un lado.', '', 25549),
(130228, 'esMX', 'Estoy recolectando las incontables piezas del tótem destrozado. Es posible que encuentres algunas si usas una caña de pescar.', '', 25549),
(130227, 'esMX', '<Akule estudia los fragmentos cuidadosamente.>\n\nSí, no hay duda de que son parte del tótem original. Tienes mi agradecimiento, $c.', '', 25549),
(130226, 'esMX', 'Hace muchos años, un rayo impactó sobre un tótem de ritual que existía sobre estas aguas y lo hizo pedazos. Estoy intentando reconstruirlo para honrar a mis ancestros.', '', 25549),
(130225, 'esMX', '¡Atrapa algas con una caña de pescar! ¡Entrégale algas a Diablillus! ¡No hay ganancias!', '', 25549),
(130224, 'esMX', 'Diablillus está complacido con el trabajo de esbirro.', '', 25549),
(130223, 'esMX', 'Adiós.', '', 25549),
(130221, 'esMX', 'Diablillus está haciendo un barco. ¡Tú ayuda!', '', 25549),
(130220, 'esMX', '¡Gracias, $gcompañero:compañera;! Te daré un poco de mi poder como recompensa. Espero que te sea de ayuda contra nuestro enemigo.', '', 25549),
(130219, 'esMX', '', '¡Mis flechas no se equivocan!', 25549),
(130218, 'esMX', '', '¡No puedes eludir mi salva!', 25549),
(130217, 'esMX', 'Concentren sus ataques. Yo me encargaré de distraerlo.', '', 25549),
(130216, 'esMX', '¡Por Nar''thalas!', '¡Por Nar''thalas!', 25549),
(130215, 'esMX', '¡Firmes, Vigilantes nocturnos! ¡Nuestros enemigos se acercan!', '¡Firmes, Vigilantes nocturnos! ¡Nuestros enemigos se acercan!', 25549),
(130214, 'esMX', '¡Bandu Thoribas!', '¡Bandu Thoribas!', 25549),
(130213, 'esMX', '¡Los Centinoche jamás renunciaremos a nuestro deber!', '¡Los Centinoche jamás renunciaremos a nuestro deber!', 25549),
(130212, 'esMX', '¡A las armas, Vigilantes nocturnos! ¡La Legión se aproxima!', '¡A las armas, Vigilantes nocturnos! ¡La Legión se aproxima!', 25549),
(130211, 'esMX', '¡Aniquilar!', '', 25549),
(130210, 'esMX', '¡Oh, vaya! ¡Esto no estaba en el plan de la lección!', '', 25549),
(130209, 'esMX', '¿Me acompañarías en mis aventuras... para siempre?', '', 25549),
(130208, 'esMX', '¡Rápido! ¡No podemos esperar por toda la eternidad!', '', 25549),
(130207, 'esMX', 'Tú. Muéstrale al resto de la clase cómo funciona el encantamiento.', '', 25549),
(130206, 'esMX', 'Si escucharon con atención durante la última clase, deberían recordar el encantamiento que hace que explote y se convierta en una bola de fuego.', '', 25549),
(130205, 'esMX', 'No se preocupen, estudiantes, este demonio está perfectamente contenido en la matriz arcana.', '', 25549),
(130204, 'esMX', 'Eh... ¿cómo era la invocación? Ru shallora... eh... mmm... ¿abracadabra?', 'Eh... ¿cómo era la invocación? Ru shallora... eh... mmm... ¿abracadabra?', 25549),
(130203, 'esMX', 'Instructor, no creo que...', 'Instructor, no creo que...', 25549),
(130201, 'esMX', '<El portal vibra con energía. Gritos y otros ruidos perturbadores provienen del más allá.>\n\nRegresa cuando tengas más fragmentos del vacío.', '', 25549),
(130200, 'esMX', '', '¡Gracias, $n! Esto es justo lo que necesitaba.', 25549),
(130199, 'esMX', '¡Llévame al Desafío de estilos!', '¡Llévame al Desafío de estilos!', 25549),
(130198, 'esMX', '', 'Fantástico, ¿verdad? ¿Puedes sentir cómo su poder fluye a través de ti y perturba el mundo que nos rodea con cada latido? Puedo someter ese poder a mi voluntad si lo deseas....', 25549),
(130197, 'esMX', '', 'Algunos de los hechizos de protección se han fragmentado y han comenzado a disiparse. Me duele tener que sugerir esto, pero creo que podrías recuperar los fragmentos con una caña de pescar.', 25549),
(130196, 'esMX', '¿Cuál es tu deseo?', '', 25549),
(130195, 'esMX', '¿En qué puedo ayudar?', '¿En qué puedo ayudar?', 25549),
(130194, 'esMX', 'Campeona, te traigo un obsequio del Príncipe Farondis. Mis hechizos te permitirán volverte más fuerte, hábil y poderosa por un tiempo. Acércate y recibe tu favor.', 'Campeona, te traigo un obsequio del Príncipe Farondis. Mis hechizos te permitirán volverte más fuerte, hábil y poderosa por un tiempo. Acércate y recibe tu favor.', 25549),
(130193, 'esMX', '¡Campeona, te ofrezco el favor de Eyir! Acércate y recibe su bendición.', '¡Campeona, te ofrezco el favor de Eyir! Acércate y recibe su bendición.', 25549),
(130192, 'esMX', 'Lo siento, pero no puedo...', 'Lo siento, pero no puedo...', 25549),
(130191, 'esMX', '¡Sí!', '¡Sí!', 25549),
(130190, 'esMX', '¡He tenido los mismos sueños contigo!', '¡He tenido los mismos sueños contigo!', 25549),
(130189, 'esMX', 'Espero que la encuentres.', 'Espero que la encuentres.', 25549),
(130188, 'esMX', '...', '...', 25549),
(130187, 'esMX', '¡$n ha activado un Portal abisal inestable en Caída de Wrynn!', '¡$n ha activado un Portal abisal inestable en Caída de Wrynn!', 25549),
(130186, 'esMX', '¡$n ha activado un Portal abisal inestable en la Fractura Sombría!', '¡$n ha activado un Portal abisal inestable en la Fractura Sombría!', 25549),
(130185, 'esMX', '¡$n ha activado un Portal abisal inestable en el Bancal Sollozante!', '¡$n ha activado un Portal abisal inestable en el Bancal Sollozante!', 25549),
(130184, 'esMX', '¡$n ha activado un Portal abisal inestable en las Tierras Retorcidas!', '¡$n ha activado un Portal abisal inestable en las Tierras Retorcidas!', 25549),
(130183, 'esMX', '¡$n ha activado un Portal abisal inestable en la Gruta Espeluznante!', '¡$n ha activado un Portal abisal inestable en la Gruta Espeluznante!', 25549),
(130182, 'esMX', '¡$n ha activado un Portal abisal inestable en Confines de la playa!', '¡$n ha activado un Portal abisal inestable en Confines de la playa!', 25549),
(130181, 'esMX', '¡$n ha activado un Portal abisal inestable en la Ruina de Almas!', '¡$n ha activado un Portal abisal inestable en la Ruina de Almas!', 25549),
(130180, 'esMX', '¡$n ha activado un Portal abisal inestable en Tormento del Soldado!', '¡$n ha activado un Portal abisal inestable en Tormento del Soldado!', 25549),
(130179, 'esMX', '¡$n ha activado un Portal abisal inestable en los Riscos Aullantes!', '¡$n ha activado un Portal abisal inestable en los Riscos Aullantes!', 25549),
(130178, 'esMX', '¡$n ha activado un Portal abisal inestable en el Sendero de Sufrimiento!', '¡$n ha activado un Portal abisal inestable en el Sendero de Sufrimiento!', 25549),
(130177, 'esMX', '¡$n ha activado un Portal abisal inestable en el Ascenso Luz de luna!', '¡$n ha activado un Portal abisal inestable en el Ascenso Luz de luna!', 25549),
(130176, 'esMX', '¡$n ha activado un Portal abisal inestable en la Cala Dentada!', '¡$n ha activado un Portal abisal inestable en la Cala Dentada!', 25549),
(130175, 'esMX', '¡$n ha activado un Portal abisal inestable en la Senda Penadiablillo!', '¡$n ha activado un Portal abisal inestable en la Senda Penadiablillo!', 25549),
(130174, 'esMX', '¡$n ha activado un Portal abisal inestable en la Fortaleza de los Viles!', '¡$n ha activado un Portal abisal inestable en la Fortaleza de los Viles!', 25549),
(130173, 'esMX', '¡$n ha activado un Portal abisal inestable en la Franja Costahedionda!', '¡$n ha activado un Portal abisal inestable en la Franja Costahedionda!', 25549),
(130172, 'esMX', '¡$n ha activado un Portal abisal inestable en la Bóveda Jurapenas!', '¡$n ha activado un Portal abisal inestable en la Bóveda Jurapenas!', 25549),
(130171, 'esMX', '¡$n ha activado un Portal abisal inestable en la Playa Iravil!', '¡$n ha activado un Portal abisal inestable en la Playa Iravil!', 25549),
(130170, 'esMX', '¡$n ha activado un Portal abisal inestable en el Paso Fuego Vil!', '¡$n ha activado un Portal abisal inestable en el Paso Fuego Vil!', 25549),
(130169, 'esMX', '¡$n ha activado un Portal abisal inestable en la Caverna Polvovil!', '¡$n ha activado un Portal abisal inestable en la Caverna Polvovil!', 25549),
(130168, 'esMX', '¡$n ha activado un Portal abisal inestable en Hondonada Brechavil!', '¡$n ha activado un Portal abisal inestable en Hondonada Brechavil!', 25549),
(130167, 'esMX', '¡$n ha activado un Portal abisal inestable en Alto de Muertobosque!', '¡$n ha activado un Portal abisal inestable en Alto de Muertobosque!', 25549),
(130166, 'esMX', '¡$n ha activado un Portal abisal inestable en las Mazmorras Oscuras!', '¡$n ha activado un Portal abisal inestable en las Mazmorras Oscuras!', 25549),
(130165, 'esMX', '¡$n ha activado un Portal abisal inestable en las Ruinas Crecientes!', '¡$n ha activado un Portal abisal inestable en las Ruinas Crecientes!', 25549),
(130164, 'esMX', '¡$n ha activado un Portal abisal inestable en la Costa de Angustia!', '¡$n ha activado un Portal abisal inestable en la Costa de Angustia!', 25549),
(130163, 'esMX', '¡$n ha activado un Portal abisal inestable en el Camino de Cenizas!', '¡$n ha activado un Portal abisal inestable en el Camino de Cenizas!', 25549),
(130162, 'esMX', 'No tengo palabras... ¡Me has convertido en la persona más feliz del mundo! ¡A nuestra próxima aventura!', '', 25549),
(130161, 'esMX', 'Ent... entiendo.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(130160, 'esMX', '¿Eres...? ¡Eres TÚ! ¡Tengo tantas cosas para contarte! ¿Por dónde empiezo? \n\nDesde nuestra primera aventura, no podía pensar en otra cosa más que en cuándo sería la próxima. Mis amigos me decían que no eras real, que yo estaba loco y que tú no eras más que un sueño. ¡Sabía que estaban equivocados! ¡Estos sentimientos son mucho más que un sueño!\n\nCada aventura que hemos tenido, cada enemigo que hemos asesinado y cada conversación que hemos tenido me llevan a hacerte esta única pregunta...', '', 25549),
(130159, 'esMX', 'Seguiré esperando, ¡sé que vendrá!', '', 25549),
(130158, 'esMX', 'Antes de que lo preguntes, no conozco la apariencia de esta persona. En mi primer sueño era un elfo de la noche, en el segundo era un tauren, y en el tercero era un elfo de la noche de nuevo. En estos sueños nos embarcábamos en aventuras por todo Azeroth y Draenor combatiendo demonios, dragones, dioses antiguos, ¡e incluso múrlocs! \n\nJamás había sentido una conexión así. Parecía tan real. En mi último sueño, les pedí que se reunieran conmigo en este lugar.', '', 25549),
(130157, 'esMX', '¿¡Eres tú?! ¡¿Tú eres la persona con la que he estado soñando?!', '', 25549),
(130156, 'esMX', '<Shawn te mira expectante>', '', 25549),
(130155, 'esMX', 'Algo está muy mal aquí. Me temo que mi poder solo no será suficiente.', '', 25549),
(130154, 'esMX', 'Sí, Profeta.', 'Sí, Profeta.', 25549),
(130153, 'esMX', '¿Estás $Glisto:lista; para continuar, $Gamigo mío:amiga mía;?', '', 25549),
(130152, 'esMX', 'No... No puedo... ver...', '', 25549),
(130151, 'esMX', '<Velen trata de recuperar el aliento.>', '', 25549),
(130150, 'esMX', '¡Qué oscuridad más terrible!', '', 25549),
(130149, 'esMX', '<Velen grita.>', '', 25549),
(130148, 'esMX', '¡Cuánta... oscuridad!', '', 25549),
(130147, 'esMX', '<Quejido de dolor.>', '', 25549),
(130146, 'esMX', 'Acheon phetar, bríndame la claridad que busco. ¡Muéstrame dónde están!', '', 25549),
(130145, 'esMX', '<Respiración forzada.>', '', 25549),
(130144, 'esMX', 'No entiendo. ¿Por qué no puedo sentirlos?', '', 25549),
(130143, 'esMX', '<Plegarias parcialmente comprensibles.>', '', 25549),
(130142, 'esMX', 'Que la Luz guíe mi visión. Pheta vi acahachi.', '', 25549),
(130141, 'esMX', 'Hemos abandonado la protección de la barrera. Mantente alerta, $Gamigo mío;amiga mía:.', '', 25549),
(130139, 'esMX', 'Muchas edades atrás me paré en este mismo lugar y reuní a los draenei. Y en este sitio buscaré los otros fragmentos.', '', 25549),
(130138, 'esMX', 'Ahora que hemos recuperado la Corona podemos cambiar el destino del Xenedar.', '', 25549),
(130137, 'esMX', 'Mis hermanos abandonaron sus fragmentos cuando llegó Sargeras. Todavía están aquí, en Mac''Aree.', '', 25549),
(130136, 'esMX', 'La Corona era un conducto. Una fuerza unificadora. Cada uno de nosotros portaba solo una parte del todo.', '', 25549),
(130135, 'esMX', 'La verdad es que no fue fácil, pero logramos conseguirte una pieza de equipamiento de la mejor calidad para tus campeones.\n\nLamentablemente, nuestros suministros son muy limitados, así que debemos llevar un control de cuántos entregamos.', '', 25549),
(130134, 'esMX', '¡La Madre Tierra te acompaña, heroína! Párate en el círculo de tótems y recibe su bendición.', '¡La Madre Tierra te acompaña, heroína! Párate en el círculo de tótems y recibe su bendición.', 25549),
(130133, 'esMX', 'Cuando desees partir, $GSeñor:Señora; de la batalla, este portal te llevará de regreso a Bastión del cielo.', '', 25549),
(130129, 'esMX', 'EL ATRACADOR HA LLEGADO', 'EL ATRACADOR HA LLEGADO', 25549),
(130128, 'esMX', '¡Patada! ¡Golpe! ¡Arde!', '', 25549),
(130127, 'esMX', 'La verdad es que me gustaría ver tu espectáculo.', 'La verdad es que me gustaría ver tu espectáculo.', 25549),
(130126, 'esMX', '¿Podrías quedarte callada?', '¿Podrías quedarte callada?', 25549),
(130125, 'esMX', 'ADVERTENCIA: ENEMIGO DETECTADO', 'ADVERTENCIA: ENEMIGO DETECTADO', 25549),
(130124, 'esMX', '¿Tú otra vez?\n\nMira, yo no voy a tu casa a decirte qué debe hacer $Gun:una; $c, ¿así que por qué no te largas?', '', 25549),
(130123, 'esMX', 'Me gustaría echar un vistazo a tus mercancías.', 'Me gustaría echar un vistazo a tus mercancías.', 25549),
(130122, 'esMX', 'Solo trato con los mejores gladiadores.', 'Solo trato con los mejores gladiadores.', 25549),
(130118, 'esMX', '¡No... te... rindas!', '', 25549),
(130117, 'esMX', 'Así es. Y en gran parte se lo debo a nuestro amigo. Pero, Alleria... hay algo más que debo contarte.', '', 25549),
(130116, 'esMX', '¡Esbirros de las llamas! ¡Alímentense de su carne!', '', 25549),
(130115, 'esMX', 'Hola, ¿no sabes que no se interrumpe a un artista en medio del espectáculo?', '', 25549),
(130114, 'esMX', 'Diezmar a esos gusanos viles ayudará a restablecer el equilibrio en estas costas. Tienes mi agradecimiento, $Ghéroe:heroína;.', '', 25549),
(130113, 'esMX', '<El pelaje del perro está brillante, y se ve muy saludable. Es evidente que Breanni está cuidándolo muy bien.>\n\n<¿Pero cómo llegó aquí?>', '', 25549),
(130112, 'esMX', '<Muéstrale la piedra de las calles de Dalaran al perro.>', '<Muéstrale la piedra de las calles de Dalaran al perro.>', 25549),
(130111, 'esMX', '<El perro olfatea la piedra y te lame la mano serenamente.>', '', 25549),
(130110, 'esMX', '<El perro mueve la cola y se esfuerza por quedarse sentado y no saltar sobre ti. Está feliz de volver a verte después de tanto tiempo.>', '', 25549),
(130109, 'esMX', 'Contemplen el triunfo de los draenei: ¡el Exodar!', '', 25549),
(130108, 'esMX', 'Mis artificieros se han estado preparando para eso por un largo tiempo.', '', 25549),
(130107, 'esMX', '¿Cómo haremos para llegar a Argus enteros mientras la Legión nos azota de esta forma?', '', 25549),
(130106, 'esMX', 'L''ura...', '', 25549),
(130105, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(130104, 'esMX', 'Hemos esperado este día por mucho tiempo.', '', 25549),
(130103, 'esMX', 'Mi pueblo ha estado esperando este día.', '', 25549),
(130102, 'esMX', '', 'Pero ten cuidado, $n. Si el Sentinax llama demasiados refuerzos, puede que te encuentres en medio de una batalla imposible de ganar...', 25549),
(130101, 'esMX', '', 'Pero si estás buscando una pelea, o si estás buscando fragmentos del vacío, tal vez deberías usar estos faros.', 25549),
(130100, 'esMX', '', 'Estos faros solicitan refuerzos directamente al Sentinax. Eso podría ser peligroso.', 25549),
(130098, 'esMX', '¡Ja! ¡Excelente! Estamos en llamas. Uno tiene que buscar la forma de mantenerse animado. Muy bien, $Gcampeón:campeona;, como siempre.', '', 25549),
(130097, 'esMX', 'La Legión quiere extender su alcance ardiente. Te agradeceríamos si pudieras ayudarnos a extinguir esta amenaza, comandante.', '', 25549),
(130095, 'esMX', '¡Usa |TInterface\\Icons\\SPELL_SHADOW_ENSLAVEDEMON.BLP:20|t |cFFFF0000|Hspell:111771|h[Esclavizar demonio ]|h|r para subyugar al corcel iracundo!', '¡Usa |TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t |cFFFF0000|Hspell:111771|h[Portal demoníaco]|h|r para atravesar la barrera de Ariden!', 25549),
(130094, 'esMX', 'Ya hemos enviado a Minerva para explorar. Atraviesa el Portón de la muerte y reúnete con ella en la ciudadela.', '', 25549),
(130092, 'esMX', 'Entrégate a la Legión.', 'Entrégate a la Legión.', 25549),
(130091, 'esMX', '¡Mi alma por el poder vil!', '¡Mi alma por el poder vil!', 25549),
(130090, 'esMX', 'Mi deseo es servir a la Legión.', 'Mi deseo es servir a la Legión.', 25549),
(130089, 'esMX', '', 'Los naga prevalecerán...', 25549),
(130088, 'esMX', '', 'La Legión nos promete fuerza, ¡una fuerza más grande que la que Lady Azshara puede ofrecernos!', 25549),
(130087, 'esMX', '¡Córtenles la cabeza de sus cuerpos mortales!', '', 25549),
(130086, 'esMX', 'Las espinas son un mecanismo de defensa en las cosas verdes que crecen de la tierra: una flora frágil que de otro modo sería indefensa.$b$bNo maldigas a las espinas. Disfruta las flores que existen gracias a ellas.', '¡La Legión nunca nos derrotará!', 25549),
(130085, 'esMX', 'Las espinas son un mecanismo de defensa en las cosas verdes que crecen de la tierra: una flora frágil que de otro modo sería indefensa.$b$bNo maldigas a las espinas. Disfruta las flores que existen gracias a ellas.', 'Nos atacan por tierra y por aire. ¡Cuidado con la cabeza!', 25549),
(130084, 'esMX', 'Estoy listo para enfrentarme a Sigryn. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Sigryn. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130083, 'esMX', 'Estoy listo para enfrentarme a Kruul. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Kruul. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130082, 'esMX', 'Estoy listo para enfrentarme a Raest. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Raest. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130080, 'esMX', 'Estoy listo para enfrentarme a Xylem. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Xylem. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130078, 'esMX', 'Llévame hasta Agatha... |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Llévame hasta Agatha... |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130077, 'esMX', 'Llévame hasta Agatha... (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Llévame hasta Agatha... (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130076, 'esMX', '¡Las sombras vencerán!', '', 25549),
(130074, 'esMX', '¡Entréguense! ¡Déjense llevar!', '', 25549),
(130073, 'esMX', '¡Caigan en la oscuridad!', '', 25549),
(130072, 'esMX', 'Envíame hasta Cantosombrío. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Envíame hasta Cantosombrío. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130071, 'esMX', '¡Argus! Mi amado hogar... ¿qué te han hecho?', '', 25549),
(130070, 'esMX', 'Estoy listo para enfrentarme a Tugar Tótem de sangre. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Tugar Tótem de sangre. |cFFFF0000(100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(130069, 'esMX', 'Inicia el enfrentamiento con Gharsul, el despiadado.', 'Inicia el enfrentamiento con Gharsul, el despiadado.', 25549),
(130068, 'esMX', '¡Esta noche cenaremos carne mortal!', '', 25549),
(130067, 'esMX', '', 'Saludos, $c. Debo completar mi investigación.\n\n¿Podrías ayudarme?', 25549),
(130066, 'esMX', 'Los naga deben aprender que un pacto con la Legión solo trae dolor.', '', 25549),
(130065, 'esMX', 'La líder de estos naga ha hecho un pacto con la Legión: las vidas de su pueblo a cambio de poder. Y los tontos acatan en silencio e ignoran el precio que deben pagar. Muéstraselos.', '', 25549),
(130064, 'esMX', '¡Pronto sus almas conocerán el olvido!', '', 25549),
(130063, 'esMX', '¡La destrucción infinita obedece mis órdenes!', '', 25549),
(130062, 'esMX', '¡Sientan cómo el caos los consume!', '', 25549),
(130061, 'esMX', '¡Exterminen a los mortales y tráiganme sus cadáveres destruidos!', '', 25549),
(130060, 'esMX', '¡Yo los llevaré a esas naves, héroes! ¡Destrúyanlas antes de que el Falsario gane más fuerzas!', '', 25549),
(130059, 'esMX', '¡Ríndanse! ¡Aún pueden unirse a nosotros y servir al amo!', '', 25549),
(130058, 'esMX', '¡Su destino no será diferente del de los demás!', '', 25549),
(130057, 'esMX', '¡La Legión Ardiente ha venido por sus almas!', '', 25549),
(130056, 'esMX', 'Todos los mundos que se resistieron han caído.', '', 25549),
(130055, 'esMX', 'La resistencia de Velen del pasado marcó el camino de su caída.', '', 25549),
(130054, 'esMX', '¡Sus vidas son míseras e insignificantes! ¡Nosotros somos eternos!', '', 25549),
(130053, 'esMX', 'Estamos listos para partir, Profeta Velen.', '', 25549),
(130052, 'esMX', '¡Enfréntense a su destino!', '', 25549),
(130051, 'esMX', '¡Entréguense a sus miedos! ¡A sus deseos!', '', 25549),
(130050, 'esMX', 'Ten cuidado, $ct. Los demonios están al acecho.', 'Ten cuidado, $ct. Los demonios están al acecho.', 25549),
(130049, 'esMX', '¡Yo mismo acabaré contigo!', '', 25549),
(130048, 'esMX', '¿Quién compartirá su destino?', '', 25549),
(130047, 'esMX', '¡Consúmanlos a todos!', '', 25549),
(130046, 'esMX', '¡Ardan! ¡Sufran!', '', 25549),
(130045, 'esMX', '¡La muerte cae sobre ustedes!', '', 25549),
(130044, 'esMX', '¡La destrucción llama!', '', 25549),
(130043, 'esMX', '¡Encuéntrenme, campeones, y les concederé visión!', '', 25549),
(130042, 'esMX', '¡Pongan atención! ¡Contemplen una visión de lo que nos espera!', '', 25549),
(130041, 'esMX', '¡Tor ilisar''thera''nal!', '¡Tor ilisar''thera''nal!', 25549),
(130040, 'esMX', '¡Bandu thoribas!', '¡Bandu thoribas!', 25549),
(130039, 'esMX', '¡Con colmillos y garras, los detendré!', '¡Con colmillos y garras, los detendré!', 25549),
(130038, 'esMX', '¡Los demonios nunca pasarán por aquí! ¡Por las tierras salvajes!', '¡Los demonios nunca pasarán por aquí! ¡Por las tierras salvajes!', 25549),
(130037, 'esMX', '¡La Legión está en camino! ¡Debemos proteger nuestros hogares!', '¡La Legión está en camino! ¡Debemos proteger nuestros hogares!', 25549),
(130036, 'esMX', '¡Muéstrame un enemigo, y yo lo acabaré!', '', 25549),
(130035, 'esMX', '¡Tu cruzada ha terminado!', '', 25549),
(130034, 'esMX', 'Cierre del complejo confirmado. Enfrentando amenaza.', '', 25549),
(130033, 'esMX', '¡Esta será su última batalla!', '', 25549),
(130029, 'esMX', '', '¿Estás bien, Turalyon?', 25549),
(130028, 'esMX', '¡Elegidos de la Luz, saluden!', '', 25549),
(130027, 'esMX', '', 'Salvarte de los demonios se ha convertido en un hábito.', 25549),
(130026, 'esMX', '', '¡Izquierda!', 25549),
(130025, 'esMX', 'NOT USED', '', 25549),
(130024, 'esMX', 'Los campeones más fuertes de Azeroth esperan tu llegada en el Alto de Krasus cuando estés $Glisto:lista;.', '', 25549),
(130023, 'esMX', 'Vamos. Si debemos morir en el Vacío, ¡nos llevaremos al Falsario con nosotros!', '', 25549),
(130022, 'esMX', 'Es verdad. No hay otra opción. ¡Vamos, campeones! Tenemos muy poco tiempo para salvar a Velen y regresar antes de que el portal se cierre.', '', 25549),
(130021, 'esMX', 'Es hora de adueñarnos de nuestro destino. Debemos usar el portal y seguir al Falsario hasta el abismo. ¡No tenemos alternativa!', '', 25549),
(130020, 'esMX', 'No lograremos nada con sellar el portal, archimago. Puede que tarden años o milenios, pero la Legión regresará. Una y otra vez, hasta que ya no quede resistencia.', '', 25549),
(130019, 'esMX', '¡Velen! ¡Detente!', '', 25549),
(130018, 'esMX', '¡No! ¡Basta de huir! ¡Basta de esconderse! ¡Debo terminar con esto!', '', 25549),
(130017, 'esMX', '', '%s lanza sus flechas a una velocidad impresionante.', 25549),
(130016, 'esMX', '|TINTERFACE\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t ¡Tienes |cFFFF0000|Hspell:235271|h[Infusión]|h|r!', '|TINTERFACE\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t ¡La Doncella de vigilancia comienza a lanzar |cFFFF0000|Hspell:235271|h[Infusión]|h|r!', 25549),
(130015, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t ¡Tienes |cFFFF0000|Hspell:240209|h[Alma inestable]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t ¡Tienes |cFFFF0000|Hspell:235117|h[Alma inestable]|h|r!', 25549),
(130014, 'esMX', '¡Este será tu último día, demonio!', '', 25549),
(130013, 'esMX', 'Luz, ¡dame fuerzas!', '', 25549),
(130012, 'esMX', 'Quiero teletransportarme hasta Kil''jaeden.', 'Quiero teletransportarme hasta Kil''jaeden.', 25549),
(130011, 'esMX', 'Quiero teletransportarme hasta el Avatar caído.', 'Quiero teletransportarme hasta el Avatar caído.', 25549),
(130010, 'esMX', 'Quiero teletransportarme hasta la Doncella de vigilancia.', 'Quiero teletransportarme hasta la Doncella de vigilancia.', 25549),
(130009, 'esMX', 'Quiero teletransportarme hasta la Inquisición demoníaca.', 'Quiero teletransportarme hasta la Inquisición demoníaca.', 25549),
(130008, 'esMX', 'Quiero teletransportarme hasta el Anfitrión desolado.', 'Quiero teletransportarme hasta el Anfitrión desolado.', 25549),
(130007, 'esMX', 'Quiero teletransportarme hasta las Hermanas de la Luna.', 'Quiero teletransportarme hasta las Hermanas de la Luna.', 25549),
(130006, 'esMX', 'Quiero teletransportarme hasta la Maestra Sassz''ine.', 'Quiero teletransportarme hasta la Maestra Sassz''ine.', 25549),
(130005, 'esMX', 'Quiero teletransportarme hasta Harjatan.', 'Quiero teletransportarme hasta Harjatan, el golpeador.', 25549),
(130004, 'esMX', 'Oh, hola, aún no hemos terminado con los preparativos.\n\nSi buscas más muerte y metal que E.T.C., tienes que escuchar esto.\n\n¿Quieres ayudarnos a difundir el evento? ¡Es un concierto que no debes perderte por nada!', '', 25549),
(130002, 'esMX', 'Su pueblo... sus mundos... siempre caen.', '', 25549),
(130001, 'esMX', '¡Alleria! Justo a tiempo, como siempre.', '', 25549),
(130000, 'esMX', '', 'Elune ayuda a quienes desean defender la tierra contra la Legión Ardiente. Párate en la luz de la luna, $Ghéroe:heroína;, y recibe su bendición.', 25549),
(129999, 'esMX', 'NOT USED', '', 25549),
(129997, 'esMX', '¡No están a la altura de nuestro poder!', '', 25549),
(129996, 'esMX', 'Quiero ir a la Tumba de Sargeras (Banda).', 'Quiero ir a la Tumba de Sargeras (Banda).', 25549),
(129995, 'esMX', 'Quiero ir a la Catedral de la Noche eterna (Calabozo).', 'Quiero ir a la Catedral de la Noche eterna (Calabozo).', 25549),
(129994, 'esMX', '¡No se detengan! ¡Acabaremos con esta bestia ahora mismo!', '', 25549),
(129992, 'esMX', 'He luchado contra los de tu tipo por miles de años, demonio. Ruges, fanfarroneas, ¡y después mueres!', '', 25549),
(129991, 'esMX', '¡Tu carne es débil! ¡Tus huesos se quiebran!', '', 25549),
(129990, 'esMX', '¿Eso es TODO lo que tienes para dar? Patético...', '', 25549),
(129989, 'esMX', '¿Quieres saber cuál es la clave para derrotar a la Legión?\n\nLos edificios, $Gcompañero:compañera;.\n\nEdificios y más edificios. Increíble, ¿no?', '', 25549),
(129988, 'esMX', 'Estoy listo para luchar a tu lado.', 'Estoy lista para luchar a tu lado.', 25549),
(129987, 'esMX', 'No deberíamos permanecer aquí más de lo necesario.', '', 25549),
(129985, 'esMX', 'Prepara tu arma.', '', 25549),
(129984, 'esMX', '¡Sus almas ARDERÁN!', '', 25549),
(129982, 'esMX', '$GCampeón:Campeona;, la Expedición de Argus te convoca para que te unas al asalto contra el mundo natal de la Legión.', '', 25549),
(129977, 'esMX', 'La última vez que vi este lugar, solo pensaba en escapar. Talgath, mi consejero más confiable, me había traicionado.', '', 25549),
(129976, 'esMX', 'Quedó abandonada. Incluso ahora puedo sentir su presencia... pero su canción es amarga, distorsionada.', '', 25549),
(129975, 'esMX', 'Aún puedo oír la canción de guerra de los naaru. Una de ellos mantuvo el camino despejado para nosotros.', '', 25549),
(129974, 'esMX', 'Los espíritus... de todos los que murieron ese día.', '', 25549),
(129973, 'esMX', 'Espera... Algo se agita.', '', 25549),
(129972, 'esMX', 'Un faro de progreso... Eso atrajo la malevolencia del universo a nuestras puertas.', '', 25549),
(129971, 'esMX', 'Mac''Aree supo ser el pináculo de la civilización eredar.', '', 25549),
(129970, 'esMX', '<Velen mantiene la mirada hacia adelante. No parece haber notado tu llegada.>', '', 25549),
(129936, 'esMX', '|TINTERFACE\\ICONS\\ability_fixated_state_red.blp:20|t ¡Un Gladiador quijafilada se ha fijado en ti!', '', 25549),
(129935, 'esMX', '¡La maestra Sassz''ine ha llamado a un capataz escama oscura!', '', 25549),
(129934, 'esMX', 'Has salvado a nuestras fuerzas de un destino terrible. La Luz te da las gracias, $Ghéroe:heroína;.', '', 25549),
(129933, 'esMX', '$GCampeón:Campeona;, la Legión tiene prisioneras a nuestras tropas y las tortura casi hasta la muerte. Rescátalas... ¡antes de que la Luz se disipe!', '', 25549),
(129932, 'esMX', 'Quiero darte todas mis sardinillas doradas.', 'Quiero darte todas mis sardinillas doradas.', 25549),
(129931, 'esMX', 'Cuando finalmente comenzamos nuestro asalto final sobre Argus, sabíamos que existía la posibilidad de que no sobreviviéramos. Y cuando derribaron el Xenedar, parecía que ya no teníamos esperanza.', '', 25549),
(129930, 'esMX', 'Estábamos comprometidos con nuestra causa. O acabábamos con la cruzada de la Legión o ellos acababan con la nuestra...', '', 25549),
(129929, 'esMX', 'El Ejército de la Luz se enfrentó contra la Legión Ardiente durante miles de años. Batallas... Refriegas... Sabotajes...', '', 25549),
(129928, 'esMX', 'Hola, pajarito. ¿Quieres todas estas cosas que brillan?', 'Hola, pajarito. ¿Quieres todas estas cosas que brillan?', 25549),
(129927, 'esMX', 'Me parece que he encontrado un poco de esta sustancia asquerosa que buscabas.', 'Me parece que he encontrado un poco de esta sustancia asquerosa que buscabas.', 25549),
(129926, 'esMX', '¡Buen trabajo! Con la amenaza del kraken neutralizada, podemos concentrarnos en derrotar a la Legión Ardiente.', '', 25549),
(129925, 'esMX', 'He encontrado muchos de tus fragmentos de tótem. Tómalos por favor.', 'He encontrado muchos de tus fragmentos de tótem. Tómalos por favor.', 25549),
(129924, 'esMX', 'Bien. Toma todas mis algas profanadas.', 'Bien. Toma todas mis algas profanadas.', 25549),
(129923, 'esMX', '¡Acabaré contigo!', '¡Acabaré contigo!', 25549),
(129922, 'esMX', '¡No pueden detenernos!', '¡No pueden detenernos!', 25549),
(129921, 'esMX', '¡Morirás por mi espada!', '¡Morirás por mi espada!', 25549),
(129920, 'esMX', 'Tu hora se acerca.', 'Tu hora se acerca.', 25549),
(129919, 'esMX', '¡La energía vil te consumirá!', '¡La energía vil te consumirá!', 25549),
(129918, 'esMX', '¡Por la Legión!', '¡Por la Legión!', 25549),
(129917, 'esMX', '¡El |cFFFF0404|Hspell:232192|h[Rugido de orden]|h|r de Harjatan ha llamado la atención de múrlocs cercanos!', '', 25549),
(129916, 'esMX', 'Debo admitir que tengo una debilidad por los múrlocs. Pero por los viles... no tanto.', '', 25549),
(129915, 'esMX', '¿Múrlocs... viles? ¿Hay alguna raza que la Legión no corrompa? Encárgate de esto, ¿quieres?', '', 25549),
(129914, 'esMX', 'Nunca entendí cómo a alguien podrían parecerle encantadoras esas criaturas horribles. Concentrémonos en asuntos más urgentes.', '', 25549),
(129913, 'esMX', 'La Legión se ha rebajado a corromper a los múrlocs que habitan en esta costa. ¡Acaba con esta vileza!', '', 25549),
(129912, 'esMX', '¡Tus tesoros, dámelos!', '', 25549),
(129911, 'esMX', '¡Nuestro paso, tú sigue!', '', 25549),
(129910, 'esMX', '¡Este es paso de Dookya!', '', 25549),
(129909, 'esMX', '¡Peñasco mío, tú mueres!', '', 25549),
(129908, 'esMX', '¡Patético! Pierdo el tiempo aquí. Con el poder de la tumba, ¡los destruiré a todos!', '', 25549),
(129907, 'esMX', 'No solo eres tan inútil como todos los demás de este mundo, sino que además quieres enfrentarme. Muy bien.', '', 25549),
(129906, 'esMX', '¡%s activa un hechizo protector ancestral!', '¡%s activa un hechizo protector ancestral!', 25549),
(129905, 'esMX', '', 'Los peces de Suramar son mis amigos.', 25549),
(129904, 'esMX', '', 'Quiero purificar las aguas del lugar.', 25549),
(129903, 'esMX', 'El cuervo te mira intrigado.', '', 25549),
(129902, 'esMX', 'Los ríos me llaman.', '', 25549),
(129901, 'esMX', 'Diablillus no está seguro de por qué termino aquí.', '', 25549),
(129900, 'esMX', '', '¡Erradíquenlos!', 25549),
(129899, 'esMX', 'Qué interesante.', '', 25549),
(129898, 'esMX', 'Ahora entraré en comunión con el agua...', '', 25549),
(129897, 'esMX', 'Por favor, acompáñame a la costa.', '', 25549),
(129896, 'esMX', 'Vacío...', '', 25549),
(129895, 'esMX', '$ct, he enviado a un cuervo para que te lleve a la nave de mando.', '', 25549),
(129894, 'esMX', '¡A empalar!', '', 25549),
(129893, 'esMX', 'Gracias, Gran $Gmaestro:maestra; $p, por tu ayuda. Lamentablemente, Ban-Lu ya no está aquí. Lo vi dirigirse al sur, pero es todo lo que sé.', '', 25549),
(129892, 'esMX', '¡Reclamado!', '', 25549),
(129891, 'esMX', '¡Marcado!', '', 25549),
(129890, 'esMX', 'Estos pilones solo pueden transportar un puñado de tropas a la vez, pero por el momento bastarán.', '', 25549),
(129889, 'esMX', '¡Fuego!', '', 25549),
(129888, 'esMX', 'Debemos movernos rápido. Ahora que los demonios saben que estamos en la superficie, la Legión nos atacará con todo su poder.', '', 25549),
(129887, 'esMX', 'Debería advertirte que a veces el Ovoexplosión hace que los huevos de kraken eclosionen en lugar de explotar. Pero es un precio ínfimo por la conveniencia de la tecnología, ¿no crees?', '', 25549),
(129886, 'esMX', 'Aun así... no te negaré la oportunidad de caer ante una maravilla ancestral. ¡Que este avatar sea su fin!', '', 25549),
(129885, 'esMX', 'La cáscara que ven ante ustedes fue un contenedor para el poder de Sargeras. Pero este templo es nuestro premio. ¡Y lo usaremos para reducir su mundo a cenizas!', '', 25549),
(129884, 'esMX', '¿Nunca te cansas de tantas beaterías, Velen? Te haces llamar profeta, pero nunca tuviste la visión para vislumbrar el destino inevitable de nuestro mundo... de todos los mundos.', '', 25549),
(129875, 'esMX', '|CFFF00000ADVERTENCIA|R Esto invocará un enemigo peligroso que solo puede derrotarse con varios héroes. Perderás 100 fragmentos del vacío si destruyes este portal.', '|CFFF00000ADVERTENCIA|R Esto invocará un enemigo peligroso que solo puede derrotarse con varios héroes. Perderás 100 fragmentos del vacío si destruyes este portal.', 25549),
(129874, 'esMX', 'Estoy listo para eliminar a los sha.', 'Estoy lista para eliminar a los sha.', 25549),
(129873, 'esMX', '', 'Soy Magatha Tótem siniestro, de la tribu Tótem siniestro. Soy la bruja anciana, la matriarca de mi tribu.$b$bAunque Baine me haya exiliado de Cima del Trueno, soy la líder que los tauren necesitan. Ellos se quedan sentados en sus tiendas, esperando a que la Alianza o la Legión los extermine sin oponer resistencia. Mi pueblo y yo nos rehusamos a admitir ese destino. Hacemos todo para sobrevivir.$b$bLa Legión ha atacado. Los Tótem siniestro me necesitan. ¿Piensan ayudarme, o me estorbarán?', 25549),
(129872, 'esMX', 'He acabado con los sha.', 'He acabado con los sha.', 25549),
(129871, 'esMX', 'Sobrecargar con fragmentos del vacío [100]', 'Sobrecargar con fragmentos del vacío [100]', 25549),
(129870, 'esMX', '<El portal vibra con energía. Gritos y otros ruidos perturbadores provienen del más allá.>', '', 25549),
(129869, 'esMX', '¿Cómo va la eliminación de los sha restantes?', '', 25549),
(129868, 'esMX', 'Sí que eliminaste a muchos de los sha restantes, Gran $Gmaestro:maestra;. Te agradecemos por tu ayuda en este asunto.', '', 25549),
(129867, 'esMX', 'Saludos, Gran $Gmaestro:maestra; $n. Qué bueno que nos visites. Principalmente, estamos concentrando nuestros esfuerzos en despejar los últimos restos de los sha en el área.$b$bSi pudieras ayudarnos con esta tarea, quizá podamos corresponderte. ¿Qué dices?', '', 25549),
(129866, 'esMX', 'Soy la clarividente del Anillo de la Tierra. ¿Quién eres?', 'Soy la clarividente del Anillo de la Tierra. ¿Quién eres?', 25549),
(129865, 'esMX', '', '¿Tú estás a cargo de esto?', 25549),
(129864, 'esMX', 'He recuperado parte de la esencia que necesitas. Por favor, llévatela toda.', 'He recuperado parte de la esencia que necesitas. Por favor, llévatela toda.', 25549),
(129863, 'esMX', '', 'Soy Magatha de la tribu Tótem siniestro, ¡y tendrán que escucharme!', 25549),
(129862, 'esMX', 'Los demonios no pueden mantenernos encadenados por mucho tiempo.', 'Los demonios no pueden mantenernos encadenados por mucho tiempo.', 25549),
(129861, 'esMX', '¡Debo regresar al campamento!', '¡Debo regresar al campamento!', 25549),
(129860, 'esMX', '¡Gracias por salvarme!', '¡Gracias por salvarme!', 25549),
(129859, 'esMX', 'Escalar', 'Escalar', 25549),
(129858, 'esMX', 'Entonces eso es lo que haremos, Alto exarca.', '', 25549),
(129857, 'esMX', 'Pero miles de demonios se interponen entre nosotros y nuestros aliados. Debemos diezmar las filas de la Legión si queremos llegar al Xenedar con vida.', '', 25549),
(129856, 'esMX', 'Alleria sigue allí afuera, viejo amigo. Lo sé. Junto con otros sobrevivientes.', '', 25549),
(129855, 'esMX', 'La última vez que la vi estaba en el Xenedar. Aún estaba... bajo vigilancia.', '', 25549),
(129854, 'esMX', '¿Y Alleria? ¿Está...?', '', 25549),
(129853, 'esMX', '¡Turalyon! Me complace ver que sigues frustrando los esfuerzos que hace la Legión para matarte.', '', 25549),
(129852, 'esMX', 'This is a test broadcast for gender token testing, $gbrother:sister;! (Do not translate)', '', 25549),
(129851, 'esMX', 'Activando', 'Activando', 25549),
(129850, 'esMX', '', 'Como lo ordenes, sacerdotisa.', 25549),
(129849, 'esMX', '', '¡En marcha!', 25549),
(129848, 'esMX', 'Claro, voy a probarlo. ¿Qué podría salir mal?', 'Claro, voy a probarlo. ¿Qué podría salir mal?', 25549),
(129847, 'esMX', 'Saludos, $ct! \n\nYa debes saber que este lugar es más que un simple cementerio naval... ¡también es un criadero gigantesco de krakens! Digo, ¡mira toda esta incubación! Es espectacular... y tal vez un poco peligrosa.\n\nAprovechando que viniste aquí a destruir los huevos antes de que eclosionen, quizá disfrutes de mi más reciente y relativamente seguro invento:\n\nyo lo llamo... ¡el Ovoexplosión!\n\n¡Casi que funciona a la perfección la mayoría de las veces! ¿Qué dices?', '', 25549),
(129846, 'esMX', '', 'Gracias de nuevo. ¡No olvidaremos tu amabilidad!', 25549),
(129845, 'esMX', '', 'Mis hermanas y yo te debemos la vida. No tenemos mucho, pero puedes llevarte todo lo que te parezca útil de nuestros suministros.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129844, 'esMX', '', 'Que Elune te bendiga, valiente. Parece que el bosque ya no es un refugio contra las fuerzas de la Legión.', 25549),
(129843, 'esMX', 'La Legión pretende destruir nuestra voluntad profanando este templo otrora sagrado. ¡Sus hazañas demuestran que nuestro espíritu es inquebrantable!', '', 25549),
(129842, 'esMX', 'Kil''jaeden se deleita enviando a sus súbditos a profanar la catedral. Expulsa a esta criatura inmunda de nuestro mundo.', '', 25549),
(129841, 'esMX', 'Ese inquisidor se deleitaba enviando a sus víctimas a la muerte. Es más que adecuado que guiaras al demonio hacia su propio destino.', '', 25549),
(129840, 'esMX', 'Un inquisidor acecha en la catedral y convierte las almas de nuestros muertos en enemigos. Envía a esta escoria aullando de regreso al Vacío.', '', 25549),
(129839, 'esMX', 'Una muerte excelente. Esa criatura horrenda no volverá a invocar otro demonio.', '', 25549),
(129838, 'esMX', 'Percibo que un poder perverso se alza en la Legión. Destrúyelo y su posición en la catedral se debilitará.', '', 25549),
(129837, 'esMX', 'La bestia está acabada. ¡Bien! Pronto Kil''jaeden sufrirá el mismo destino.', '', 25549),
(129836, 'esMX', 'La Legión ha invocado una bestia voraz con hambre de carne mortal. ¡Destruye esta monstruosidad antes de que la liberen!', '', 25549),
(129835, 'esMX', 'Buen trabajo. El Falsario arderá de furia ahora que la catedral no está bajo su control.', '', 25549),
(129834, 'esMX', 'Kil''jaeden ha enviado a uno de sus generales a vigilar la Catedral de la Noche eterna. Ponle fin a su mandato.', '', 25549),
(129833, 'esMX', '', 'Estoy lista para viajar a Skold-Ashil.\n\n¿Podemos partir?', 25549),
(129832, 'esMX', '¡A los cielos, mis mascotas! ¡Yaaaaah!', '', 25549),
(129831, 'esMX', '¡Conocerás el dolor!', '¡Conocerás el dolor!', 25549),
(129830, 'esMX', 'El trabajo de la Legión será realidad.', 'El trabajo de la Legión será realidad.', 25549),
(129829, 'esMX', '¡¿Cómo te atreves?!', '¡¿Cómo te atreves?!', 25549),
(129828, 'esMX', '¡Tiembla ante mi poder!', '¡Tiembla ante mi poder!', 25549),
(129827, 'esMX', 'Tu muerte será rápida y despiadada.', 'Tu muerte será rápida y despiadada.', 25549),
(129826, 'esMX', '¡Tu mundo será purgado!', '¡Tu mundo será purgado!', 25549),
(129825, 'esMX', '¡La venganza será mía!', '¡La venganza será mía!', 25549),
(129824, 'esMX', 'Ah.... al fin.', 'Ah.... al fin.', 25549),
(129823, 'esMX', 'No... puede ser...', 'No... puede ser...', 25549),
(129822, 'esMX', '¡Que termine este tormento!', '¡Que termine este tormento!', 25549),
(129821, 'esMX', '¡Vete a la tumba!', '¡Vete a la tumba!', 25549),
(129820, 'esMX', 'Únete a nosotros en la eternidad...', 'Únete a nosotros en la eternidad...', 25549),
(129819, 'esMX', 'La muerte es solo el comienzo.', 'La muerte es solo el comienzo.', 25549),
(129818, 'esMX', '¡No hay donde huir!', '¡No hay donde huir!', 25549),
(129817, 'esMX', '¡Me perteneces!', '¡Me perteneces!', 25549),
(129816, 'esMX', '', 'Esos demonios se atrevían a subyugar los elementos. ¡Imbéciles! ¡Ahora han aprendido el precio de semejante insulto!', 25549),
(129815, 'esMX', '', 'Estos eredar están usando núcleos de poder en su patético intento por controlar los elementos. ¡Enséñales que estos poderes no son para jugar!', 25549),
(129814, 'esMX', '¡Los que me obedecen eligieron este destino!', '', 25549),
(129813, 'esMX', 'No... puede ser...', '', 25549),
(129812, 'esMX', 'Sucumbirás ante la Legión Ardiente. ¡Lo juro!', '', 25549),
(129811, 'esMX', '', '¡Mi muerte no romperá el pacto!', 25549),
(129810, 'esMX', '', '¡Estos espíritus le pertenecen a la Legión Ardiente!', 25549),
(129809, 'esMX', 'Vamos.', '', 25549),
(129808, 'esMX', 'Esto no cambia nada.', 'Esto no cambia nada.', 25549),
(129807, 'esMX', '¡Anduin!', '', 25549),
(129806, 'esMX', 'Mi destino ya estaba sellado hace mucho tiempo.', 'Mi destino ya estaba sellado hace mucho tiempo.', 25549),
(129805, 'esMX', '¡Allí!', '', 25549),
(129804, 'esMX', 'La muerte no trae paz.', 'La muerte no trae paz.', 25549),
(129803, 'esMX', '¡Mi sufrimiento no tiene fin!', '¡Mi sufrimiento no tiene fin!', 25549),
(129802, 'esMX', 'Ni la muerte puede liberarme...', 'Ni la muerte puede liberarme...', 25549),
(129801, 'esMX', '¡Esto no es mi decisión!', '¡Esto no es mi decisión!', 25549),
(129800, 'esMX', 'Mi voluntad no me pertenece.', 'Mi voluntad no me pertenece.', 25549),
(129799, 'esMX', 'No deberías estar aquí.', 'No deberías estar aquí.', 25549),
(129798, 'esMX', '¡Abandona este lugar, $c!', '¡Abandona este lugar, $c!', 25549),
(129797, 'esMX', '¿Estás $Gseguro:segura; de que quieres dejar de ganar experiencia cuando llegues al nivel 19?', '¿Estás $Gseguro:segura; de que quieres dejar de ganar experiencia cuando llegues al nivel 19?', 25549),
(129796, 'esMX', 'Deseo dejar de ganar experiencia cuando llegue a nivel 19.', 'Deseo dejar de ganar experiencia cuando llegue a nivel 19.', 25549),
(129795, 'esMX', 'Qué coincidencia. A ella tampoco le agradas.\n\nAhora ve a trabajar antes de que el eredar del otro lado descubra lo que he hecho y trate de sellar el portal.', '', 25549),
(129794, 'esMX', 'No me agrada este demonio.', 'No me agrada este demonio.', 25549),
(129793, 'esMX', '¿Tienes un "demonio prestado" para mí?', '¿Tienes un "demonio prestado" para mí?', 25549),
(129792, 'esMX', 'Vamos.', '', 25549),
(129791, 'esMX', 'Padre...', '', 25549),
(129790, 'esMX', '', 'Nuestros enemigos se acercan... ¡rápido!', 25549),
(129789, 'esMX', '', '¡Sigue avanzando! Este lugar no es seguro...', 25549),
(129788, 'esMX', '', '¡Debemos apurarnos, $Gforastero:forastera;!', 25549),
(129787, 'esMX', 'Yo no sabía...', '', 25549),
(129786, 'esMX', 'Esta tierra es lúgubre y está cargada de pesares.', '', 25549),
(129785, 'esMX', '$GHéroe:Heroína;, por aquí.', '', 25549),
(129784, 'esMX', '', '¡Ya basta de sermones! ¡Mátalos!', 25549),
(129783, 'esMX', '¡No mostraré piedad!', '¡No mostraré piedad!', 25549),
(129782, 'esMX', '', '¡La Madre Luna está complacida, Piraluna!', 25549),
(129781, 'esMX', '', '¡Que la diosa bendiga tus flechas!', 25549),
(129780, 'esMX', '', '¡Qué puntería tan impresionante, hermana!', 25549),
(129779, 'esMX', '', 'Deja de perder el tiempo. ¡Destrúyelos!', 25549),
(129778, 'esMX', '', '¡La guerrera nocturna guía tu mano, hermana!', 25549),
(129777, 'esMX', '', '¡El corte más afilado!', 25549),
(129776, 'esMX', '', '¡Estás en mi camino!', 25549),
(129775, 'esMX', '', '¡Justo en el blanco!', 25549),
(129774, 'esMX', '', '¡No eres digno!', 25549),
(129773, 'esMX', '', '¡Confiesa! ¡Arrepiéntete!', 25549),
(129772, 'esMX', '', '¡Madre Luna, revela sus pecados!', 25549),
(129771, 'esMX', '', '¡Paga el precio de tu herejía!', 25549),
(129770, 'esMX', '', '¡Contempla su gloria!', 25549),
(129769, 'esMX', '', '¡Diosa, quema a los herejes!', 25549),
(129768, 'esMX', '', '¡Hunde tus garras en su carne, mi mascota!', 25549),
(129767, 'esMX', '', '¡Nunca fallo!', 25549),
(129766, 'esMX', '', '¡Mi mira esta fija en ti!', 25549),
(129765, 'esMX', '', '¡Mi mira está fija en ti!', 25549),
(129764, 'esMX', '', '¡Reprensión desde los cielos!', 25549),
(129763, 'esMX', '', '¡La luz de Elune llega a su cénit!', 25549),
(129762, 'esMX', '', 'Yo tomaré tu lugar, hermana. ¡Mi guja quiere cantar!', 25549),
(129761, 'esMX', '', '¡Yo me encargaré de estos herejes, Yathae!', 25549),
(129760, 'esMX', '', '¡Basta de perder tiempo, Kasparian! ¡La victoria será mía!', 25549),
(129759, 'esMX', '', 'Elune... perdónanos...', 25549),
(129758, 'esMX', '', '¡No! Debería... haber... ganado...', 25549),
(129757, 'esMX', '', 'Le fallamos... a la diosa...', 25549),
(129756, 'esMX', '', 'La próxima vez, ¡yo seré la primera en salir!', 25549),
(129755, 'esMX', '', 'El templo está a salvo. ¡Buena pelea, hermanas!', 25549),
(129754, 'esMX', '', '¡La Madre Luna nos ha concedido la victoria!', 25549),
(129753, 'esMX', '', 'Ineficiente... pero efectivo.', 25549),
(129752, 'esMX', '', '¡Eres una digna sirvienta de la diosa!', 25549),
(129751, 'esMX', '', '¡Tu falta de fe te condenó!', 25549),
(129750, 'esMX', '', '¡Tu arco está bendecido, hermana!', 25549),
(129749, 'esMX', '', '¡Una muerte valiosa, hermana!', 25549),
(129748, 'esMX', '', '¡Mi presa cae!', 25549),
(129747, 'esMX', '', '¡La diosa está complacida, hermana!', 25549),
(129746, 'esMX', '', '¡Esa muerte te llevó tiempo, hermana!', 25549),
(129745, 'esMX', '', '¡Tu cacería ha terminado!', 25549),
(129744, 'esMX', '', 'Eres muy impetuosa, Kasparian.', 25549),
(129743, 'esMX', '', '¡Que la diosa guíe tu mano!', 25549),
(129742, 'esMX', '', '¡Yo derramaré la primera sangre!', 25549),
(129741, 'esMX', '', 'Mis flechas siempre están listas, Kasparian.', 25549),
(129740, 'esMX', '', '¡Hermanas! ¡En guardia!', 25549),
(129739, 'esMX', '', '¡Profanadores! ¡Debemos expulsarlos del templo sagrado de Elune!', 25549),
(129734, 'esMX', '¡Sí! ¡Dejen que vengan! ¡Sus cuerpos alimentarán las llamas de su mundo ardiente!', '', 25549),
(129733, 'esMX', 'Bien hecho. Los demonios no se recuperarán pronto de esa devastación.', '', 25549),
(129732, 'esMX', '¡Acaba con los demonios y arrasa con sus fortificaciones!', '', 25549),
(129731, 'esMX', 'La Costa Quebrada no es un lugar para ir solo. ¡Debemos encontrar a Anduin antes de que sea tarde!', '', 25549),
(129730, 'esMX', '¡Prepararé una nave de inmediato!', '', 25549),
(129729, 'esMX', 'Es hora de que yo siga su ejemplo. Llévame a donde murió mi padre. Debo verlo con mis propios ojos.', '', 25549),
(129728, 'esMX', 'Pasé mi vida protegido por la sangre de héroes como Tirion y Bolvar... héroes como mi padre.', '', 25549),
(129727, 'esMX', 'Los reyes de mi familia siempre han peleado junto a sus soldados por la libertad de Ventormenta.', '', 25549),
(129726, 'esMX', 'Mi bisabuelo, el rey Barathen, y mi abuelo, el rey Llane, también hicieron el máximo sacrificio.', '', 25549),
(129725, 'esMX', 'Mi padre no fue el primer rey de Ventormenta que murió combatiendo a la Legión Ardiente.', '', 25549),
(129724, 'esMX', 'Una y otra vez, he presenciado a la distancia cómo los héroes de Ventormenta peleaban y morían para defender la paz de Azeroth.', '', 25549),
(129723, 'esMX', 'Después de la muerte de mi madre, yo era el único recuerdo que le quedó de ella.', '', 25549),
(129722, 'esMX', 'Mi padre quiso protegerme de la guerra; insistía en que me quedara porque siempre debe haber un Wrynn reinando en Ventormenta. Pero vi la verdad en sus ojos... el miedo de perderme.', '', 25549),
(129721, 'esMX', 'Esta tierra es mucho peor de lo que imaginaba.', '', 25549),
(129720, 'esMX', 'Vamos, sigamos adelante.', '', 25549),
(129719, 'esMX', 'Esta tierra está herida y desolada, un lugar terrible para morir.', '', 25549),
(129718, 'esMX', 'Así que este es el sitio donde nuestras fuerzas llegaron a la Costa Quebrada.', '', 25549),
(129717, 'esMX', '', '¡Con esto debería bastar! A ver... ¿Katarata? ¿Katarsis? ¿Y esto cómo se dice?', 25549),
(129716, 'esMX', 'Solo voy a esconderme aquí atrás y esperaré a que todo termine.', '', 25549),
(129715, 'esMX', '¿Las encontraste? ¡Qué alivio! Estaba a punto de enloquecer tratando de encontrar otro regalo...', '', 25549),
(129714, 'esMX', '¡$GHéroe:Heroína;! Sufrí un pequeño inconveniente cuando venía volando aquí. Se me cayeron unas monedas especiales que iba a darle a... uh, no importa. Si las encuentras y me las devuelves, ¡te estaré muy agradecido!', '', 25549),
(129713, 'esMX', 'Necesito recuperarme... ¡Sigue sin mí!', 'Necesito recuperarme... ¡Sigue sin mí!', 25549),
(129712, 'esMX', 'Unggh...', 'Unggh...', 25549),
(129711, 'esMX', 'Heridas graves... Debo recuperarme...', 'Heridas graves... Debo recuperarme...', 25549),
(129710, 'esMX', '¡%s ha invocado a un teniente demoníaco!', '¡%s ha invocado a un teniente demoníaco!', 25549),
(129709, 'esMX', '¡%s ha potenciado los portales demoníacos!', '¡%s ha potenciado los portales demoníacos!', 25549),
(129708, 'esMX', '¡%s ha extendido la duración de los portales demoníacos!', '¡%s ha extendido la duración de los portales demoníacos!', 25549),
(129707, 'esMX', '¡%s ha invocado portales demoníacos!', '¡%s ha invocado portales demoníacos!', 25549),
(129706, 'esMX', '', 'La Legión resiste...', 25549),
(129705, 'esMX', '', '¡Mis crías se alimentarán con los cadáveres de sus aliados!', 25549),
(129704, 'esMX', '¡|TInterface\\Icons\\inv_egg_01:20|tUn grupo de huevos incubados está por hacer|cFFFF0404|Hspell:240319|h[Eclosión]|h|r!', '', 25549),
(129703, 'esMX', 'A... a... arañas....', 'A... a... arañas....', 25549),
(129702, 'esMX', 'Al fin... Ya puedo respirar de nuevo.', 'Al fin... Ya puedo respirar de nuevo.', 25549),
(129701, 'esMX', 'Siento que el veneno abandona mis venas. ¡Gracias!', 'Siento que el veneno abandona mis venas. ¡Gracias!', 25549),
(129699, 'esMX', '$GCampeón:Campeona;, la tierra misma se pudre bajo nuestros pies. La descomposición se presenta a cada paso. ¡Debemos erradicarla!', '', 25549),
(129698, 'esMX', '', 'Mi amado Corian... ¿Qué haría sin ti?', 25549),
(129697, 'esMX', '', '¡Muchas gracias! ¡Esos diablillos salieron de la nada! No tengo mucho, pero mereces una recompensa. Examina nuestros suministros y llévate todo lo que necesites.', 25549),
(129696, 'esMX', '', 'Y así regresan a la tierra.', 25549),
(129695, 'esMX', '', '¿Esos eredar insolentes aún creen que pueden someter la tierra de Azeroth a su voluntad? ¡Castígalos!', 25549),
(129694, 'esMX', '¿Seguimos?', '¿Seguimos?', 25549),
(129693, 'esMX', 'Han pasado eones desde la última vez que vi este lugar. Cuántos recuerdos...$b$b\n<Velen frunce el ceño, pensativo.>', '', 25549),
(129692, 'esMX', 'Debemos mantenernos todos unidos si queremos tener alguna posibilidad de derrotar a la Legión.', '', 25549),
(129691, 'esMX', 'No deseo pelear contigo, Hatuun. Pero no puedo permitir que tu resentimiento obstaculice nuestra guerra con la Legión.', '', 25549),
(129690, 'esMX', 'El fin...', 'El fin...', 25549),
(129689, 'esMX', '...en la oscuridad.', '...en la oscuridad.', 25549),
(129688, 'esMX', '<Temblando sin control.>', '<Temblando sin control.>', 25549),
(129687, 'esMX', '<Incomprensible.>', '<Incomprensible.>', 25549),
(129686, 'esMX', '<Balbucea sin sentido.>', '<Balbucea sin sentido.>', 25549),
(129685, 'esMX', 'Alto exarca Turalyon... Al fin nos conocemos.', '', 25549),
(129684, 'esMX', '¿Qué les diré a mis hijos?', '¿Qué les diré a mis hijos?', 25549),
(129683, 'esMX', '¡Bajen las armas! El Profeta y su $Galiado:aliada; no son nuestros enemigos.', '', 25549),
(129682, 'esMX', '¿Hay algo que podamos hacer?', '¿Hay algo que podamos hacer?', 25549),
(129681, 'esMX', '¡Basta!', '', 25549),
(129680, 'esMX', '¡Este no puede ser el final! ¡No puede ser!', '¡Este no puede ser el final! ¡No puede ser!', 25549),
(129679, 'esMX', 'Cambiamos, al igual que Argus. Resistimos. ¿Qué otra opción teníamos?', '', 25549),
(129678, 'esMX', 'Esa voz... ¿Hatuun? ¿Cómo sobreviviste a este infierno por tanto tiempo?', '', 25549),
(129677, 'esMX', '¡Ya no sé qué hacer!', '¡Ya no sé qué hacer!', 25549),
(129676, 'esMX', '¿Este es el fin? ¿De esto se trataba todo? Hay tantas cosas que quería hacer...', '¿Este es el fin? ¿De esto se trataba todo? Hay tantas cosas que quería hacer...', 25549),
(129675, 'esMX', '¡Los cielos son más oscuros que nunca! ¿Acaso no hay esperanza?', '¡Los cielos son más oscuros que nunca! ¿Acaso no hay esperanza?', 25549),
(129673, 'esMX', 'Le diste la espalda a tu pueblo, Profeta. A tu mundo. Semejante traición solo merece la muerte.', '', 25549),
(129672, 'esMX', 'Velen. Al fin has regresado al hogar que abandonaste.', '', 25549),
(129671, 'esMX', '¡Muéstrense!', '', 25549),
(129670, 'esMX', '¿Y si algo ataca la ciudad? ¿Qué se supone que haremos entonces?', '¿Y si algo ataca la ciudad? ¿Qué se supone que haremos entonces?', 25549),
(129669, 'esMX', '¿Qué significa? ¿Es el final?', '¿Qué significa? ¿Es el final?', 25549),
(129668, 'esMX', '¡Parece que debemos encargarnos de unos preparativos, $Gcampeón:campeona;! Será mejor que informes a Khadgar de nuestros descubrimientos. ¡Buena suerte!', '', 25549),
(129667, 'esMX', 'Este no es nuestro último día. Resistiremos juntos.', '', 25549),
(129666, 'esMX', 'Este lugar parece... familiar.', '', 25549),
(129665, 'esMX', 'Eso no fue un pedido. <Estrangularlo.>', 'Eso no fue un pedido. <Estrangularlo.>', 25549),
(129664, 'esMX', 'No te alejes demasiado. Nos están observando.', '', 25549),
(129663, 'esMX', '', 'No te preocupes, Clarividente... Nosotros cuidaremos de la Piedra de la muerte.', 25549),
(129659, 'esMX', 'La Legión la persigue... y los dioses antiguos también. Pero hay algo más... una oscuridad más grande...', '', 25549),
(129658, 'esMX', 'Hablar con el alma de un mundo no es como conversar con un mortal. Quizá por eso necesitaba que alguien fuera su portavoz.', '', 25549),
(129657, 'esMX', '¡Estás mejor sin ella!', '', 25549),
(129656, 'esMX', '¡No confíes en sus incoherencias! ¡Yo soy el único poder verdadero aquí!', '', 25549),
(129655, 'esMX', '', 'Vuelve más tarde. Quizá tenga otro trabajo para ti.', 25549),
(129654, 'esMX', 'Un mundo de belleza perfecta... ¡Qué ridículo! Este mundo no conoce más que dolor.', '', 25549),
(129653, 'esMX', '¡Bah! Soy tan poderosa como la Maretista, ¡o cualquiera de estas reliquias mohosas!', '', 25549),
(129652, 'esMX', '¡Ni siquiera su eco deja de parlotear! ¿Ahora ves con qué tengo que lidiar?', '', 25549),
(129651, 'esMX', '¿Me llamaste, Neptulon?', '¿Me llamaste, Neptulon?', 25549),
(129650, 'esMX', 'Ah... solo era un eco de su poder. No hay nada de qué preocuparse.', '', 25549),
(129649, 'esMX', 'Has contemplado la destrucción que puede causar la Piedra de la muerte en primera persona. Eres un guardián confiable de Azeroth, pero incluso en tus manos el poder provocó caos y pánico en tu pueblo. Imagina si estuviera en poder de alguien con planes malignos...$b$bNo podemos dejar que eso suceda.$b$bHemos debatido extensamente qué hacer con este artefacto mientras esperábamos que despertaras. Pensamos en darle un nuevo hogar en uno de los planos elementales, pero cada uno implica sus peligros.$b$bNo hay lugar más seguro que este, el corazón de Azeroth. Permanecerá bajo la protección del Anillo de la Tierra, y nadie volverá a usarlo. Colócalo sobre este pedestal, y nunca abandonará ese lugar.', '', 25549),
(129648, 'esMX', '¿Esta viva? ¡No! ¡No dejaré que me controle de nuevo!', '', 25549),
(129647, 'esMX', 'Saludos, Clarividente. ¿Ya te has recuperado?', '', 25549),
(129646, 'esMX', '¡Falsario! Hemos venido a ponerle fin a tu invasión de Azeroth. ¡La cruzada de tu maestro se acaba aquí!', '', 25549),
(129645, 'esMX', '¡Me alimentaré de sus cenizas!', '', 25549),
(129644, 'esMX', '¡La energía vil me alimenta!', '', 25549),
(129643, 'esMX', '¡El caos los consumirá!', '', 25549),
(129642, 'esMX', '¡Su realidad se desgarra!', '', 25549),
(129641, 'esMX', '¡No sé cómo sobrevivieron! Pero no importa. ¡Contemplen nuestras maravillas, mortales, y pierdan la esperanza! ¡Este mundo será su tumba!', '', 25549),
(129640, 'esMX', '¡Kil''jaeden obtendrá poder de esos contenedores!', '', 25549),
(129639, 'esMX', '¡Su impertinencia es inútil! ¡Un ejército infinito alimenta mi fuerza!', '', 25549),
(129638, 'esMX', 'No pueden resistirse a su propia naturaleza.', '', 25549),
(129637, 'esMX', 'Siento la corrupción en su interior.', '', 25549),
(129636, 'esMX', '¡Enfréntense a su propia oscuridad!', '', 25549),
(129635, 'esMX', '¿Cómo puede ser? ¿Ni siquiera la manifestación de sus dudas y temores los obliga a rendirse?', '', 25549),
(129634, 'esMX', 'No es difícil mostrar valor frente a mis esbirros. ¿Serán tan valientes contra las sombras del interior de su alma?', '', 25549),
(129633, 'esMX', '¡Ixallon! ¡Ven y destrúyelos!', '', 25549),
(129632, 'esMX', '¡Todos arderán!', '', 25549),
(129631, 'esMX', '¡Sientan toda mi furia!', '', 25549),
(129630, 'esMX', '¡Ardan! ¡Ardan y mueran!', '', 25549),
(129629, 'esMX', '¡Siguen resistiéndose! ¡Les mostraré el precio de su arrogancia!', '', 25549),
(129628, 'esMX', '¡Una lucha insignificante! ¡Azeroth caerá ante la Legión Ardiente!', '', 25549),
(129627, 'esMX', '¡Mortales insolentes! ¡Su destino quedó sellado en cuanto llegaron al Vacío!', '', 25549),
(129626, 'esMX', '¡Cae ante mis cuchillas!', '', 25549),
(129625, 'esMX', '¡Basura demoníaca!', '', 25549),
(129624, 'esMX', '¡$GHéroe:Heroína;! ¡Elige a tu objetivo con sabiduría!', '', 25549),
(129623, 'esMX', '¡Veamos tus habilidades de combate! ¡Elige un enemigo!', '', 25549),
(129622, 'esMX', '¡No pierdas la fe!', '', 25549),
(129621, 'esMX', '¡Todavía no es tu hora!', '', 25549),
(129620, 'esMX', '¡La Luz los revitalizará!', '', 25549),
(129619, 'esMX', '¡Caerás, $Ghéroe:heroína;!', '', 25549),
(129618, 'esMX', '¡Un destino inevitable!', '', 25549),
(129617, 'esMX', '¡Dirijan la mirada hacia ellos, jurapenas!', '', 25549),
(129616, 'esMX', '¡Brujos, incineren a estos debiluchos!', '', 25549),
(129615, 'esMX', '¡Vilnato! ¡Demuéstrenles las consecuencias de su resistencia!', '', 25549),
(129614, 'esMX', '¡Eredar! ¡Demuéstrenles a los perros de Velen lo inútil que es combatirnos!', '', 25549),
(129613, 'esMX', '¿Y ahora quién los salvará?', '', 25549),
(129612, 'esMX', '¡Caigan ante su amo!', '', 25549),
(129611, 'esMX', '¡Fue una estupidez seguirme hasta aquí!', '', 25549),
(129606, 'esMX', '¡No! No nos dividirás, Falsario. Pelearé a su lado, y ellos junto a mí. Unidos, ¡le pondremos fin a tu cruzada!', '', 25549),
(129605, 'esMX', 'Y ahora su furia impotente ha guiado a sus aliados a la perdición. ¡Contemplen cómo mi ejército infinito los masacra!', '', 25549),
(129604, 'esMX', '¡GRRAAAHHHHH!', '', 25549),
(129603, 'esMX', '¿Y la Luz salvó a tu hijo? ¿Viste un destello de fe en los ojos de Rakeesh cuando se cerraron por última vez? ¿O solo odio por el padre que lo abandonó?', '', 25549),
(129602, 'esMX', 'Perdiste la fe en la Luz. ¡Juntos, podríamos haber combatido a Sargeras y salvado a nuestro mundo!', '', 25549),
(129601, 'esMX', '¡Tú no tuviste visión! ¡Te negaste a ver la verdad de la victoria inevitable de la Legión!', '', 25549),
(129600, 'esMX', 'Perseguiste a tu propio pueblo, incluso a través de las estrellas. ¡Nunca más!', '', 25549),
(129599, 'esMX', 'Montemos, $GAlto señor:Alta señora;, y rescatemos a nuestros aliados perdidos.', 'Montemos, $GAlto señor:Alta señora;, y rescatemos a nuestros aliados perdidos.', 25549),
(129598, 'esMX', 'Lanzarme a la batalla junto a ti será glorioso, Alto señor.', 'Lanzarme a la batalla junto a ti será glorioso, Alta señora.', 25549),
(129597, 'esMX', 'Será un honor montar a tu lado, $GAlto señor:Alta señora;.', 'Será un honor montar a tu lado, $GAlto señor:Alta señora;.', 25549),
(129596, 'esMX', '¡Listo para montar a tu lado, $GAlto señor:Alta señora;!', '¡Lista para montar a tu lado, Alta señora!', 25549),
(129595, 'esMX', 'Pelearé a tu lado.', 'Pelearé a tu lado.', 25549),
(129594, 'esMX', 'Prepárate, adalid. Estamos rodeados.', '', 25549),
(129593, 'esMX', 'Estoy listo para buscar sobrevivientes.', 'Estoy lista para buscar sobrevivientes.', 25549),
(129592, 'esMX', 'Esto ya no es el Argus que recuerdo.', '', 25549),
(129591, 'esMX', 'Les pedimos que conserven la calma y la paciencia hasta que tengamos más información.', 'Les pedimos que conserven la calma y la paciencia hasta que tengamos más información.', 25549),
(129590, 'esMX', 'Estamos aquí para ustedes. No hay por qué entrar en pánico. Por favor, recuerden mantener una actitud respetuosa en todo momento.', 'Estamos aquí para ustedes. No hay por qué entrar en pánico. Por favor, recuerden mantener una actitud respetuosa en todo momento.', 25549),
(129589, 'esMX', 'Si notan alguna actividad sospechosa o comportamiento inusual, no duden en informarnos.', 'Si notan alguna actividad sospechosa o comportamiento inusual, no duden en informarnos.', 25549),
(129588, 'esMX', 'Debido al reciente influjo de visitantes, debemos recordar mantener una actitud tranquila y respetuosa.', 'Debido al reciente influjo de visitantes, debemos recordar mantener una actitud tranquila y respetuosa.', 25549),
(129587, 'esMX', 'Por favor, mantengan la calma y hagan una fila ordenada. Un banquero los ayudará en cuanto haya un lugar disponible.', 'Por favor, mantengan la calma y hagan una fila ordenada. Un banquero los ayudará en cuanto haya un lugar disponible.', 25549),
(129586, 'esMX', '', 'Espero que tener nuestras pertenencias en casa sea prueba del fin del mundo.', 25549),
(129585, 'esMX', '', '¿El fin del mundo? ¡Pfft! ¡Estoy tratando de sacar nuestras cosas, pero estos tipos son más lentos que un caracol!', 25549),
(129584, 'esMX', '', '¿Qué hay que hacer para que alguien te dé una mano por aquí? Esperábamos poder llevar nuestras cosas de regreso a casa antes de que... Bueno, ya sabes.', 25549),
(129583, 'esMX', '', '¡No te muevas! No queremos que nuestras pertenencias se derramen, ¿verdad?', 25549),
(129582, 'esMX', '', '¿Nunca habías visto a alguien proteger sus bienes? ¡Sigue tu camino!', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129581, 'esMX', '', '¿Qué te importa?', 25549),
(129580, 'esMX', '', 'Escucha, estamos seguros de que nuestros bienes están "a salvo" aquí, ¿pero por qué arriesgarse?', 25549),
(129579, 'esMX', 'Es muy posible que estemos yendo hacia una trampa.', '', 25549),
(129578, 'esMX', 'Mantente alerta, adalid. La Legión es experta en engaños.', '', 25549),
(129577, 'esMX', '¡El portal se cierra! Podemos sellar la puerta de la Legión y acabar con esta invasión.', '', 25549),
(129576, 'esMX', '¡Nunca! ¡Nuestra cruzada nunca se rendirá! Saboreen esta victoria superflua. Regresaremos una y otra vez, nunca nos detendremos. ¡Hasta exterminarlos!', '', 25549),
(129575, 'esMX', '', '¡Eso es! ¡Entrégate al poder!', 25549),
(129574, 'esMX', 'Ya... basta...', '', 25549),
(129573, 'esMX', '', '¡No pierdas la concentración! ¿Qué te sucede?', 25549),
(129572, 'esMX', '', '¡Cuánto poder... cuánto caos!', 25549),
(129571, 'esMX', 'Ese poder es demasiado para ti. ¡No puedes controlarlo!', '', 25549),
(129570, 'esMX', 'He cosechado las llamas de tu mundo. ¡Ahora obedece mis órdenes!', '', 25549),
(129569, 'esMX', 'La visión que Sargeras te mostró era una mentira, Kil''jaeden. ¡Ríndete! ¡Olvídalo de una vez!', '', 25549),
(129568, 'esMX', '¿No aprendiste nada de todas tus derrotas, Falsario?', '', 25549),
(129567, 'esMX', '¡Siguen peleando! ¡Siguen negando lo inevitable! ¡Su resistencia incesante es enloquecedora! ¿Por qué no se rinden?', '', 25549),
(129566, 'esMX', 'Llegó... el fin...', '', 25549),
(129565, 'esMX', 'La carne... fracasa.', '', 25549),
(129564, 'esMX', 'El maestro... vence.', '', 25549),
(129563, 'esMX', '...y en la oscuridad, la Luz prevalecerá.', '...y en la oscuridad, la Luz prevalecerá.', 25549),
(129562, 'esMX', 'Las reparaciones están casi terminadas.', 'Las reparaciones están casi terminadas.', 25549),
(129561, 'esMX', 'Nos alzaremos una vez más.', 'Nos alzaremos una vez más.', 25549),
(129560, 'esMX', 'Por más perturbadores que puedan parecer estos eventos, una visión de esperanza asoma en la oscuridad.', 'Por más perturbadores que puedan parecer estos eventos, una visión de esperanza asoma en la oscuridad.', 25549),
(129559, 'esMX', 'Los preparativos están casi terminados. Nos espera un gran viaje.', 'Los preparativos están casi terminados. Nos espera un gran viaje.', 25549),
(129558, 'esMX', 'Gracias a la bendición de la Luz, nuestro camino se renueva.', 'Gracias a la bendición de la Luz, nuestro camino se renueva.', 25549),
(129557, 'esMX', '¡Llegó tu fin!', '', 25549),
(129556, 'esMX', '', '¡Ese demonio no solo está devastando a tu pueblo, también a la tierra! Si alguna vez hubo motivos para usar la Piedra de la muerte, ¡este es el momento!', 25549),
(129555, 'esMX', '¡Muerto!', '', 25549),
(129554, 'esMX', '', '¡Purificaré la corrupción!', 25549),
(129553, 'esMX', 'Guardián...', '', 25549),
(129552, 'esMX', '¡Sieguen!', '', 25549),
(129551, 'esMX', '¡Maldecido!', '', 25549),
(129550, 'esMX', '¡Caos!', '', 25549),
(129549, 'esMX', '¡Arde!', '', 25549),
(129548, 'esMX', 'Mortales... ¡mueran!', '', 25549),
(129547, 'esMX', '¡Acabaré... con ustedes!', '', 25549),
(129546, 'esMX', 'Buena suerte, Clarividente $p. Tengo fe en que no me fallarás.', '', 25549),
(129545, 'esMX', '¡Basta de cadenas! ¡No te contengas! ¡Destroza su mundo y acaba con esto!', '', 25549),
(129544, 'esMX', '¡Los hilos de tu marioneta están cortados, Kil''jaeden!', '', 25549),
(129543, 'esMX', '¡Malditos mortales! Se arrastran a esta tumba como una plaga, se deshacen de mis lacayos y se creen oponentes dignos de la Legión. Héroes... campeones... ¡imbéciles!', '', 25549),
(129542, 'esMX', 'El camino está abierto. Todo lo que conoces, lo que amas, desaparecerá.', '', 25549),
(129541, 'esMX', 'Has condenado a tu mundo a ahogarse en las llamas del amo.', '', 25549),
(129540, 'esMX', 'No importa. Ya ha comenzado.', '', 25549),
(129539, 'esMX', '¡Idiota! La Legión que conoces es solo una sombra de nuestra verdadera gloria.', '', 25549),
(129538, 'esMX', 'Acaba... con esto...', '', 25549),
(129537, 'esMX', 'Nuestras líneas se debilitan a cada instante. ¡Extermina a su comandante antes de que nos arrasen!', '', 25549),
(129536, 'esMX', 'No tienen por qué disculparse. No hicieron nada malo. Solo tenemos que asegurarnos de que las calles son seguras para ustedes.', 'No tienen por qué disculparse. No hicieron nada malo. Solo tenemos que asegurarnos de que las calles son seguras para ustedes.', 25549),
(129535, 'esMX', 'Las calles no son un lugar para niños en estos tiempos. Alguien vendrá pronto a vigilarlos hasta que tengamos la certeza de que la ciudad es segura.', 'Las calles no son un lugar para niños en estos tiempos. Alguien vendrá pronto a vigilarlos hasta que tengamos la certeza de que la ciudad es segura.', 25549),
(129534, 'esMX', 'No es su culpa, niños, pero no deberían salir hasta que sepamos que es seguro.', 'No es su culpa, niños, pero no deberían salir hasta que sepamos que es seguro.', 25549),
(129533, 'esMX', '¿Dónde están sus padres? No deberían estar corriendo por la ciudad.', '¿Dónde están sus padres? No deberían estar corriendo por la ciudad.', 25549),
(129532, 'esMX', '¡Por favor! ¿Alguien ha visto a sus padres? No deberían estar corriendo por ahí ahora. No es seguro.', '¡Por favor! ¿Alguien ha visto a sus padres? No deberían estar corriendo por ahí ahora. No es seguro.', 25549),
(129531, 'esMX', 'Pronto el Consejo nos revelará más información. Estoy seguro.', '', 25549),
(129530, 'esMX', 'Deberíamos escuchar a nuestros líderes, no los rumores que inundan la ciudad. Pronto tendremos más información.', '', 25549),
(129529, 'esMX', '', 'Me pregunto cuándo se calmarán los ánimos en las calles. La ciudad no ha tenido un momento de silencio desde que todo esto comenzó.', 25549),
(129528, 'esMX', '', 'Más temprano iba caminando por la calle y se me cansaron los oídos de oír todas las especulaciones que rondan por ahí. Hay tanta incertidumbre por aquí últimamente.', 25549),
(129527, 'esMX', '', 'Deberíamos tratar de mantener una actitud positiva. La gente ya tiene suficientes preocupaciones. Debemos predicar con el ejemplo.', 25549),
(129526, 'esMX', '', 'Tengo absoluta fe en nuestros líderes. No deberíamos dejarnos influenciar por las tonterías que se dicen en la ciudad. Cada persona reacciona de manera diferente.', 25549),
(129525, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(129524, 'esMX', '¿Qué tal si robamos los secretos de los sastres natonocturnos?', '', 25549),
(129523, 'esMX', '¡Contempla los cielos! ¡Al fin la verdad se revela!', '¡Contempla los cielos! ¡Al fin la verdad se revela!', 25549),
(129522, 'esMX', '¡El fin se acerca!', '¡El fin se acerca!', 25549),
(129521, 'esMX', 'Cuéntame tu filosofía sobre el estilo.', 'Cuéntame tu filosofía sobre el estilo.', 25549),
(129520, 'esMX', 'Antes de contarte sobre la creación legendaria, primero debes abrazar la filosofía del estilo y el buen gusto. ¡Es una condición indispensable! ¿Estás $Glisto:lista; para comenzar?', '', 25549),
(129519, 'esMX', '', 'Aunque los capturen, mis Tótem siniestro siempre estarán listos para pelear. En cambio, tus Anillo de la Tierra... débiles.', 25549),
(129518, 'esMX', '', '¿Puedes oír el viento? Pide ayuda a gritos, que lo salven de la Legión.', 25549),
(129517, 'esMX', '', 'Contempla la majestuosidad de la tierra... tan fuerte, protectora, inmutable. Pero cuando tiembla, es capaz de causar una enorme destrucción.', 25549),
(129516, 'esMX', '', 'Los poderes del agua suelen ser revitalizantes. Es el más débil y pasivo de los elementos. ¿Para qué pensaba usarla la Legión?', 25549),
(129515, 'esMX', '', 'Los demonios tienen su fuego vil, y se creen capaces de controlar el de Azeroth también. ¡Están tan equivocados!', 25549),
(129514, 'esMX', '', '¿Para qué tener un artefacto tan grandioso si tienes miedo de usarlo? La Piedra de la muerte sería mucho más útil en mis manos.', 25549),
(129513, 'esMX', '', '¿Sabes? Si usaras la Piedra de la muerte, esto terminaría pronto.', 25549),
(129512, 'esMX', '', '¿Quieren que la tierra de Azeroth pelee contra sí misma? ¡Estúpidos eredar!', 25549),
(129511, 'esMX', '¡Sus cielos pertenecen a la Legión!', '¡Sus cielos pertenecen a la Legión!', 25549),
(129510, 'esMX', '¡Nuestras alas oscurecerán sus cielos!', '¡Nuestras alas oscurecerán sus cielos!', 25549),
(129509, 'esMX', 'Usaré sus cuerpos para alimentar mis cargas.', 'Usaré sus cuerpos para alimentar mis cargas.', 25549),
(129508, 'esMX', '', 'Si crees que voy a perder de vista la Piedra de la muerte, claramente no me conoces. Avancemos.', 25549),
(129507, 'esMX', '', 'Usaré sus cuerpos para alimentar mis cargas.', 25549),
(129506, 'esMX', '', '¡Sus cielos pertenecen a la Legión!', 25549),
(129505, 'esMX', '', '¡Nuestras alas oscurecerán sus cielos!', 25549),
(129504, 'esMX', '¡Sus cielos pertenecen a la Legión!', '', 25549),
(129503, 'esMX', 'Usaré sus cuerpos para alimentar mis cargas.', '', 25549),
(129502, 'esMX', '¡Nuestras alas oscurecerán sus cielos!', '', 25549),
(129501, 'esMX', '', '¡Los cielos no son el único lugar lleno de magia estos días! Relájate y echa un vistazo a algunas de nuestras nuevas incorporaciones.', 25549),
(129500, 'esMX', '', '¡Ey, $n! ¿Sabes si el Consejo ha revelado más información?', 25549),
(129499, 'esMX', 'Envíame al Trono de los Cuatro Vientos.', 'Envíame al Trono de los Cuatro Vientos.', 25549),
(129498, 'esMX', '', 'Estamos perdiendo la paciencia aquí. ¿Alguna noticia sobre lo que está pasando?', 25549),
(129497, 'esMX', '', '¿Alguna novedad, $n?', 25549),
(129496, 'esMX', '', '¿Qué se dice en las calles, $n?', 25549),
(129495, 'esMX', '', 'Trata de no hacer mucho ruido. Estas bestias han estado un poco nerviosas.', 25549),
(129494, 'esMX', '', '¡Calma, mis bestias grandiosas! Todo volverá a la normalidad pronto... espero.', 25549),
(129493, 'esMX', '', 'Ten cuidado. Las mascotas han estado comportándose de manera extraña. Quizá lo mejor sea mantenerse lejos de los corrales por un tiempo.', 25549),
(129492, 'esMX', '', 'Disculpa si las mascotas están un poco molestas. Hay algo que las tiene preocupadas.', 25549),
(129491, 'esMX', '%s comienza a molestarse.', '%s comienza a molestarse.', 25549),
(129490, 'esMX', '¡TU PRESENCIA AQUÍ NO ES BIENVENIDA! ¡REGRESA AL LUGAR DE DONDE VINISTE!', '', 25549),
(129489, 'esMX', '', '¡Mira por dónde vas, $n! Dime, ¿alguna novedad del Consejo?', 25549),
(129488, 'esMX', '', '¿Qué pasa ahí afuera? El ruido es cada vez más fuerte. Espero que tengamos novedades pronto.', 25549),
(129487, 'esMX', '', '¡$GBienvenido:Bienvenida;! Lucian y yo estábamos hablando de los últimos eventos. ¿Tienes alguna noticia para nosotros?', 25549),
(129486, 'esMX', '', '¿Cómo está todo por ahí, $n? Ha pasado mucha gente por aquí durante todo el día, pero parece que nadie sabe demasiado.', 25549),
(129485, 'esMX', '', '¿Tienes alguna noticia? Hace mucho que no tenemos novedades.', 25549),
(129484, 'esMX', '', 'Toda esta espera para saber qué está pasando me pone muy nerviosa.', 25549),
(129483, 'esMX', '', 'Espero que recibamos novedades pronto. Hace tiempo que no sabemos nada nuevo.', 25549),
(129482, 'esMX', '', 'A veces me pregunto si alguna vez tendremos una respuesta que explique lo que está sucediendo...', 25549),
(129481, 'esMX', '', 'Espero que estés bien, $n. Yo, por otro lado...', 25549),
(129480, 'esMX', '', '¡Uh, no! Derramé otro trago. Parece que no puedo mantener las manos quietas con todo lo que está pasando por aquí.', 25549),
(129479, 'esMX', '', '¡Ah, $n! Tal vez tú puedas ayudarnos con esto... Arille y yo estábamos discutiendo si el Consejo ya había terminado su evaluación. ¿Alguna noticia?', 25549),
(129478, 'esMX', '', 'Busca una silla y descansa un poco. Sabemos que las cosas pueden ser muy caóticas allí afuera, así que deja tus preocupaciones en la puerta.', 25549),
(129477, 'esMX', '', '¡Arille, por favor! No frente a los invitados. Todavía no sabemos qué es y no tiene sentido especular.', 25549),
(129476, 'esMX', '', 'Gracias, campeones. Rezo por que puedan purificar la oscuridad que acecha este templo.', 25549),
(129475, 'esMX', '', 'Traté de resistirme, pero fallé. Al menos ahora soy libre.', 25549),
(129474, 'esMX', '', 'Debí haber sido más fuerte. Dile a Tyrande... que lo siento.', 25549),
(129473, 'esMX', '', '¡El motor los consumirá a todos!', 25549),
(129472, 'esMX', '', 'Almas mortales... Tan débiles, ¡tan patéticas!', 25549),
(129471, 'esMX', '', 'Elune no tiene poder aquí. ¡Esta tumba le pertenece a la Legión!', 25549),
(129470, 'esMX', '', '¡Aliméntate, motor! ¡Aliméntate!', 25549),
(129469, 'esMX', '', '¡Reclamo sus almas para el amo!', 25549),
(129468, 'esMX', '', '¡Tu espíritu me pertenece!', 25549),
(129467, 'esMX', '', '¡No se resistan a la voluntad del amo!', 25549),
(129466, 'esMX', '', '¡Este templo será su tumba!', 25549),
(129465, 'esMX', '', '¡Servirán, tal como yo!', 25549),
(129464, 'esMX', '¡Contemplen nuestra victoria!', '', 25549),
(129463, 'esMX', '¡Su lucha no tiene sentido!', '', 25549),
(129462, 'esMX', '¡La esperanza morirá con ustedes!', '', 25549),
(129461, 'esMX', 'Nuestro trabajo... debe continuar...', '', 25549),
(129460, 'esMX', 'El motor... falla...', '', 25549),
(129459, 'esMX', 'Qué... penosa... cosecha...', '', 25549),
(129458, 'esMX', '¡El motor necesita más!', '', 25549),
(129457, 'esMX', '¡Cuántas almas para servirnos!', '', 25549),
(129456, 'esMX', '¡Una cosecha excelente!', '', 25549),
(129455, 'esMX', '¡Más combustible!', '', 25549),
(129454, 'esMX', '¡Otra alma que se une a nosotros!', '', 25549),
(129453, 'esMX', '¡Uno más para la cosecha!', '', 25549),
(129452, 'esMX', '¡Sus almas no son más que alimento!', '', 25549),
(129451, 'esMX', '¡No son más que combustible para el motor!', '', 25549),
(129450, 'esMX', '¡Cosecharemos sus almas!', '', 25549),
(129449, 'esMX', '¡Nos alimentaremos con su sufrimiento!', '', 25549),
(129448, 'esMX', '¡Serán parte de nosotros!', '', 25549),
(129447, 'esMX', '¡Nuestra furia no tiene límites!', '', 25549),
(129446, 'esMX', 'Confío en que podrás encargarte de tu parte. Esperemos que los demás puedan pasar.', '', 25549),
(129445, 'esMX', 'Vacío... desolación...', '', 25549),
(129444, 'esMX', '¡Sus almas conocerán la desesperación!', '', 25549),
(129443, 'esMX', '¡La oscuridad se los llevará!', '', 25549),
(129442, 'esMX', '', '¿Sientes las garras de la perdición?', 25549),
(129441, 'esMX', '', '¡Ahhh, los vínculos irrompibles!', 25549),
(129440, 'esMX', '', 'Vida y muerte... ¡entrelazadas!', 25549),
(129439, 'esMX', '', '¡Compartirán su tormento!', 25549),
(129438, 'esMX', '', '¡Báñense en su agonía!', 25549),
(129437, 'esMX', '', '¡Oigan el clamor de los desolados!', 25549),
(129436, 'esMX', 'Trato de mantenerme positivo, pero la verdad es que no sé que esperar.', 'Trato de mantenerme positiva, pero la verdad es que no sé que esperar.', 25549),
(129435, 'esMX', '¿Has oído alguna noticia hoy?', '¿Has oído alguna noticia hoy?', 25549),
(129434, 'esMX', 'Sigo regresando con la esperanza de que haya novedades, pero la respuesta siempre es la misma.', 'Sigo regresando con la esperanza de que haya novedades, pero la respuesta siempre es la misma.', 25549),
(129433, 'esMX', '¿Qué significa? Nunca antes había visto algo así.', '¿Qué significa? Nunca antes había visto algo así.', 25549),
(129432, 'esMX', 'No he oído nada que no supiera, $n. ¿Y tú?', 'No he oído nada que no supiera, $n. ¿Y tú?', 25549),
(129431, 'esMX', 'Espero que haya algunas respuestas.', 'Espero que haya algunas respuestas.', 25549),
(129430, 'esMX', 'Necesito saber qué está pasando.', 'Necesito saber qué está pasando.', 25549),
(129429, 'esMX', 'Necesito respuestas. ¿Has oído alguna novedad?', 'Necesito respuestas. ¿Has oído alguna novedad?', 25549),
(129428, 'esMX', 'La fase final de esta gesta aún no está completa. Destruirán la nave de la Legión y será genial. ¡Envía tus comentarios!', 'La fase final de esta gesta aún no está completa. Destruirán la nave de la Legión y será genial. ¡Envía tus comentarios!', 25549),
(129427, 'esMX', 'Hemos llegado lejos juntos, $n.', '', 25549),
(129426, 'esMX', 'Estoy listo para iniciar el asalto.', 'Estoy lista para iniciar el asalto.', 25549),
(129425, 'esMX', '', 'Aquí estás a salvo, $n. Ainderu no ha dejado de vigilar la puerta desde que todo esto comenzó, pero a mí no me preocupa.', 25549),
(129424, 'esMX', '', 'Nuestra puerta siempre está abierta, $n. Espero que la atmósfera de aquí sea más tranquila que la de afuera.', 25549),
(129423, 'esMX', '', 'Qué bueno volver a verte, $n. ¿Viniste a conversar? ¿Necesitas suministros? O quizás solo un descanso de... Bueno, lo que sea que está pasando por allí.', 25549),
(129422, 'esMX', '', '¡$GBienvenido:Bienvenida; a la tienda! ¿El Consejo ya ha divulgado sus descubrimientos, $n?', 25549),
(129421, 'esMX', '', '¡$n, qué bueno verte! ¿Tienes alguna noticia sobre lo que está pasando?', 25549),
(129420, 'esMX', '¿Es normal ver estrellas?', '¿Es normal ver estrellas?', 25549),
(129419, 'esMX', 'Solo quiero volver a sentirme como antes.', 'Solo quiero volver a sentirme como antes.', 25549),
(129418, 'esMX', 'Esto es demasiado para mí. No sé si puedo resistirlo.', 'Esto es demasiado para mí. No sé si puedo resistirlo.', 25549),
(129417, 'esMX', 'Dicen que todo está en tu cabeza, pero esto... esto es diferente. ¡Lo juro!', 'Dicen que todo está en tu cabeza, pero esto... esto es diferente. ¡Lo juro!', 25549),
(129416, 'esMX', 'Esto tiene que terminar. No puedo soportar esto mucho más.', 'Esto tiene que terminar. No puedo soportar esto mucho más.', 25549),
(129415, 'esMX', 'Por favor. Tienes que ayudarnos.', 'Por favor. Tienes que ayudarnos.', 25549),
(129414, 'esMX', 'Siento que se acerca de nuevo...', 'Siento que se acerca de nuevo...', 25549),
(129413, 'esMX', 'No... no me siento bien.', 'No... no me siento bien.', 25549),
(129412, 'esMX', '', 'Hola, $n. ¿Sabías que el Estanque Real supo albergar a los peces más grandes y hermosos de todo Azsuna? La realeza se detenía a contemplar las aguas y admirar sus gráciles movimientos para olvidar sus pesadas cargas.\n\nAhora... ¡algo anda mal!', 25549),
(129411, 'esMX', '', 'Nunca antes había visto algo así, $n. Nosotros nos encargaremos. Envíanos a todos los que tengan síntomas similares.', 25549),
(129410, 'esMX', '', 'Espero que la situación se tranquilice. La gente llega presa del pánico.', 25549),
(129409, 'esMX', '', 'Pronto tendremos que enviar a la gente afuera en busca de ayuda. No creo que tengamos los recursos para mantener un mínimo orden.', 25549),
(129408, 'esMX', '', '¿Tienes alguna noticia, $n? ¡Los síntomas siguen apareciendo, pero aún no hay ninguna explicación!', 25549),
(129407, 'esMX', '', 'Ya casi no tenemos espacio para nuestros invitados. No sé cuánto tiempo más podremos seguir así.', 25549),
(129406, 'esMX', '', 'No sé cuánto tiempo más podremos seguir así, $n. Empezamos a quedarnos sin suministros.', 25549),
(129405, 'esMX', '', 'Hemos traído más ayuda y los atenderemos pronto. Tengan paciencia, por favor.', 25549),
(129404, 'esMX', '', 'Si hay demasiada gente aquí, salgan. Tenemos más estaciones preparadas y un asistente listo para ayudarlos.', 25549),
(129403, 'esMX', '', '¡$n! ¡No dejan de venir! Nunca había visto algo así.', 25549),
(129402, 'esMX', '', 'Conserven la calma. Los atenderemos a todos pero les pedimos que sean pacientes.', 25549),
(129401, 'esMX', '¡No lograrán más que enfurecer a los elementos!', '¡No lograrán más que enfurecer a los elementos!', 25549),
(129400, 'esMX', '¡Sin sus núcleos de poder no tienen control!', '¡Sin sus núcleos de poder no tienen control!', 25549),
(129399, 'esMX', 'Subyugar a los elementos de Azeroth a su voluntad... ¡La Legión ha ido demasiado lejos!', 'Subyugar a los elementos de Azeroth a su voluntad... ¡La Legión ha ido demasiado lejos!', 25549),
(129398, 'esMX', '', 'Si los ciudadanos siguen presentando estos síntomas, tendremos que empezar a entrenar más ayudantes.', 25549),
(129397, 'esMX', '', '¿Estás aquí para ayudar, $n? Aún no he podido diagnosticarlo. Sus síntomas están por todas partes.', 25549),
(129396, 'esMX', 'Necesitas ayuda para llegar a la entrada de El Exodar. Había olvidado que muchos de los recién llegados no están muy familiarizados con estos salones sagrados. Hay una rampa en el anillo superior del Trono de los Naaru que te llevará hasta la superficie.', 'Necesitas ayuda para llegar a la entrada de El Exodar. Había olvidado que muchos de los recién llegados no están muy familiarizados con estos salones sagrados. Hay una rampa en el anillo superior del Trono de los Naaru que te llevará hasta la superficie.', 25549),
(129395, 'esMX', 'Al exterior, a la Isla Bruma Azur', 'Al exterior, a la Isla Bruma Azur', 25549),
(129394, 'esMX', '¡La Legión ha corrompido el sagrario!', '¡La Legión ha corrompido el sagrario!', 25549),
(129393, 'esMX', '"El poder que controlamos es la carga de nuestros enemigos".', '"El poder que controlamos es la carga de nuestros enemigos".', 25549),
(129392, 'esMX', '"El viento es raudo y tenaz".', '"El viento es raudo y tenaz".', 25549),
(129391, 'esMX', '"En todo hay verdad".', '"En todo hay verdad".', 25549),
(129390, 'esMX', '"La fortaleza puede encontrarse en las tierras de abajo".', '"La fortaleza puede encontrarse en las tierras de abajo".', 25549),
(129389, 'esMX', 'Otros continentes', 'Otros continentes', 25549),
(129388, 'esMX', 'Ventormenta o Forjaz de los Reinos del Este', 'Ventormenta o Forjaz de los Reinos del Este', 25549),
(129387, 'esMX', 'Península del Fuego Infernal de Terrallende', 'Península del Fuego Infernal de Terrallende', 25549),
(129386, 'esMX', 'Darnassus', 'Darnassus', 25549),
(129385, 'esMX', 'Si deseas aventurarte a nuestra tierra natal de Terrallende, puedes usar el portal del Arca de las Luces para llegar a la Península del Fuego Infernal.', 'Si deseas aventurarte a nuestra tierra natal de Terrallende, puedes usar el portal del Arca de las Luces para llegar a la Península del Fuego Infernal.', 25549),
(129384, 'esMX', 'Hay un portal a la capital de los elfos de la noche, Darnassus, ubicado en el Arca de las Luces.', 'Hay un portal a la capital de los elfos de la noche, Darnassus, ubicado en el Arca de las Luces.', 25549),
(129383, 'esMX', 'Para llegar a Ventormenta deberás viajar por mar. Primero ve a la superficie y a la Isla Bruma Azur. Luego debes seguir el camino al Atracadero de Valaar. El Valaar te llevará hasta la Aldea Rut''theran. Hay un barco que zarpa hacia Ventormenta y los demás Reinos del Este. Si necesitas ayuda para llegar a la superficie, también puedo darte indicaciones hasta la entrada.', 'Para llegar a Ventormenta deberás viajar por mar. Primero ve a la superficie y a la Isla Bruma Azur. Luego debes seguir el camino al Atracadero de Valaar. El Valaar te llevará hasta la Aldea Rut''theran. Hay un barco que zarpa hacia Ventormenta y los demás Reinos del Este. Si necesitas ayuda para llegar a la superficie, también puedo darte indicaciones hasta la entrada.', 25549),
(129382, 'esMX', 'El Consejo nos pide que mantengamos la calma hasta que hayan terminado de evaluar la situación.', 'El Consejo nos pide que mantengamos la calma hasta que hayan terminado de evaluar la situación.', 25549),
(129381, 'esMX', 'Si ves algún comportamiento inusual, mágico o de cualquier otro tipo, avisa de inmediato.', 'Si ves algún comportamiento inusual, mágico o de cualquier otro tipo, avisa de inmediato.', 25549),
(129380, 'esMX', 'Debemos conservar la calma hasta que el Consejo concluya su investigación.', 'Debemos conservar la calma hasta que el Consejo concluya su investigación.', 25549),
(129379, 'esMX', 'No dejaremos de trabajar lado a lado con el Consejo hasta que la situación se solucione.', 'No dejaremos de trabajar lado a lado con el Consejo hasta que la situación se solucione.', 25549),
(129378, 'esMX', 'Somos nuevos en este mundo, pero ya hemos establecido conexiones con las ciudades principales de la Alianza.\n\n¿A dónde quieres viajar?', 'Somos nuevos en este mundo, pero ya hemos establecido conexiones con las ciudades principales de la Alianza.\n\n¿A dónde quieres viajar?', 25549),
(129377, 'esMX', 'El Consejo está al tanto de la situación y les pide que mantengan la calma hasta que completen su evaluación.', 'El Consejo está al tanto de la situación y les pide que mantengan la calma hasta que completen su evaluación.', 25549),
(129376, 'esMX', 'Es necesario mantener la calma. Pronto habrá respuestas.', 'Es necesario mantener la calma. Pronto habrá respuestas.', 25549),
(129375, 'esMX', '¡Necesitamos respuestas! No sabemos qué esperar.', '¡Necesitamos respuestas! No sabemos qué esperar.', 25549),
(129374, 'esMX', '¿Qué están haciendo con el comportamiento de las personas? Están asustando a los niños.', '¿Qué están haciendo con el comportamiento de las personas? Están asustando a los niños.', 25549),
(129373, 'esMX', '¿Deberíamos preocuparnos?', '¿Deberíamos preocuparnos?', 25549),
(129372, 'esMX', '¿Qué significa?', '¿Qué significa?', 25549),
(129371, 'esMX', 'Durante mucho tiempo hemos buscado separarnos de los demás y por eso no tenemos muchas conexiones con otras tierras. Como parte de nuestro pacto con la Horda, contamos con formas de viajar a otras ciudades y frentes.\n\n¿A dónde deseas ir?', 'Durante mucho tiempo hemos buscado separarnos de los demás y por eso no tenemos muchas conexiones con otras tierras. Como parte de nuestro pacto con la Horda, contamos con formas de viajar a otras ciudades y frentes.\n\n¿A dónde deseas ir?', 25549),
(129370, 'esMX', '¿Tienes alguna novedad?', '¿Tienes alguna novedad?', 25549),
(129369, 'esMX', 'Solo queremos respuestas.', 'Solo queremos respuestas.', 25549),
(129368, 'esMX', '¿Y si sucede algo?', '¿Y qué pasa si sucede algo?', 25549),
(129367, 'esMX', '¿Qué está pasando? ¿Qué nos ocultan?', '¿Qué está pasando? ¿Qué nos ocultan?', 25549),
(129366, 'esMX', 'Entrañas u Orgrimmar', 'Entrañas u Orgrimmar', 25549),
(129365, 'esMX', 'Península del Fuego Infernal de Terrallende', 'Península del Fuego Infernal de Terrallende', 25549),
(129364, 'esMX', 'Para llegar a Entrañas y a Orgrimmar o Kalimdor, tienes que usar el teletransportador ubicado en la Aguja Furia del Sol.', 'Para llegar a Entrañas y a Orgrimmar o Kalimdor, tienes que usar el teletransportador ubicado en la Aguja Furia del Sol.', 25549),
(129363, 'esMX', 'Hay un portal que lleva a la Península del Fuego Infernal de Terrallende. Se encuentra en la Aguja Furia del Sol.', 'Hay un portal que lleva a la Península del Fuego Infernal de Terrallende. Se encuentra en la Aguja Furia del Sol.', 25549),
(129362, 'esMX', 'Otros continentes', 'Otros continentes', 25549),
(129361, 'esMX', '¡Bien hecho, Gran $Gmaestro:maestra;! Hemos mantenido a raya al enemigo... por ahora.', '', 25549),
(129360, 'esMX', '¡Gran $Gmaestro:maestra;! Nos han informado que los Felskorn están preparando otro ataque. ¡Debes frustrar sus planes antes de que puedan actuar!', '', 25549),
(129359, 'esMX', '¡Bendiciones para ti! Los monjes estamos en deuda contigo.', '', 25549),
(129358, 'esMX', '¡$Héroe:Heroína;! Nos han informado que los Felskorn están preparando otro ataque. ¡Debes frustrar sus planes antes de que puedan actuar!', '', 25549),
(129357, 'esMX', 'Tu vigor me ha impresionado, Clarividente, y confío en que tu fe en Thunderaan no es un error. Puede contar con mi lealtad.', '', 25549),
(129356, 'esMX', 'Hoy los vientos han soplado a tu favor, Clarividente. Reconsideraré mi lealtad a Thunderaan.', '', 25549),
(129355, 'esMX', 'Parece que debemos prepararnos.', '', 25549),
(129354, 'esMX', '', 'Khadgar querrá saber de esto.', 25549),
(129353, 'esMX', '', 'Pero los pilares solos no pueden ganar la guerra. Solo un ejército unido basado en la fuerza y el coraje puede conquistar a la Legión. Cuando tú y tus aliados estén listos para la batalla final, mi eco regresará a ayudarlos. El destino de Azeroth está en sus manos.', 25549),
(129352, 'esMX', '¡|TInterface\\ICONS\\Spell_Arcane_PortalDarnassus.blp20|t %s comienza a lanzar |cFFFF0404|Hspell:234676|h[Reflejo retorcido]|h|r!', '¡|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s comienza a lanzar |cFFFF0404|Hspell:234423|h[Drenar vida]|h|r!', 25549),
(129351, 'esMX', '', 'Pero aún hay esperanza. Si anclan los Pilares de la creación a los salones de abajo, restablecerán mis defensas y harán retroceder a los invasores. Luego deben aventurarse a las profundidades de la tumba y usar el Ojo de Aman''Thul para erradicar a los Tormenta vil y cortar el vínculo entre la Legión y Azeroth.', 25549),
(129350, 'esMX', '', 'Soy Aegwynn, guardiana de Tirisfal. Dejé este eco de mi poder como defensa en caso de que las guardas que dispuse para proteger la tumba fallaran. En efecto, percibo que el maestro de la Legión Ardiente planea reclamar su premio.', 25549),
(129349, 'esMX', '', 'En eras pasadas, este escudo defendió la joven alma del mundo de la locura y la corrupción. Hoy, servirá a los defensores de Azeroth.', 25549),
(129348, 'esMX', '', '¿Será posible? ¡La Guardiana!', 25549),
(129347, 'esMX', '¿Qué es esto?', '', 25549),
(129346, 'esMX', '¡|TINTERFACE\\ICONS\\SPELL_SHADOW_CURSEOFMANNOROTH.BLP:20|t %s comienza a lanzar |cFFFF0404|Hspell:236572|h[Aniquilación]|h|r!', '¡|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s comienza a lanzar |cFFFF0404|Hspell:234423|h[Drenar vida]|h|r!', 25549),
(129345, 'esMX', '', 'Un arma tan poco elegante no sustituye a una guja afilada, pero supongo que fue efectiva.', 25549),
(129344, 'esMX', '', 'Nuestros aliados dicen haber preparado su nave con un armamento devastador. ¡Pongamos a prueba sus armas!', 25549),
(129343, 'esMX', 'Al fin solos.', '', 25549),
(129342, 'esMX', 'Yo controlaré los cielos. ¡Encárgate de la Égida!', '', 25549),
(129341, 'esMX', '', 'Ah, el frío abrazo de la muerte. ¡Es tan liberador!', 25549),
(129340, 'esMX', '', 'Perdona si mi guja termina en tu corazón, Illidan. Con tantos demonios, es difícil distinguirte entre toda esta escoria.', 25549),
(129339, 'esMX', '', 'Nuestros caballeros de la muerte han desatado un ejército de dracos no-muertos para bombardear esta área. ¿Quieres unirte a la diversión?', 25549),
(129338, 'esMX', 'Que vengan. Maiev y yo los contendremos en las escaleras.', '', 25549),
(129337, 'esMX', 'Hemos perdido. La Legión rompió nuestras líneas y nos expulsó de la tumba. Son todo lo que se interpone entre ellos y la Égida. ¡Están en camino!', '', 25549),
(129336, 'esMX', '', 'El Consejo me pidió que estudiara estas marcas de incineración. Parecen ser muy recientes.', 25549),
(129335, 'esMX', '', 'No te acerques demasiado, $n. Esta área sufrió un ataque reciente. No es segura.', 25549),
(129334, 'esMX', '', '¡Excelente!', 25549),
(129333, 'esMX', 'La corrupción vil se propaga por la playa. El Cónclave necesita tu ayuda.', '', 25549),
(129332, 'esMX', '', 'Daumyr te espera, $GSeñor:Señora; de la muerte. ¿Quieres unirte a la furia de los cielos?', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129331, 'esMX', '', 'Estas marcas parecen frescas. Te sugiero que mantengas distancia hasta que sepamos de qué se trata, $n. No quiero que salgas $Glastimado:lastimada;.', 25549),
(129330, 'esMX', 'La parte de "historiador" de mi título requiere de cierta aura implícita de autoridad erudita. $b$bDicho eso, estas ropas monótonas son de microfibra, con control de humedad, perdurables, laminadas, entrelazadas, con hebras, antisépticas, antiarrugas, con control de reducción y hechas a medida. $b$bAhí tienes. $b$bY presta atención a mi piel. El régimen de humectación es vigoroso.', '', 25549),
(129329, 'esMX', '', 'Eso debería poner un alto en sus planes, al menos por un tiempo. ¡Gracias por la ayuda!', 25549),
(129328, 'esMX', '', 'La Legión planea ataques contra nuestros Ancestros desde este campamento. ¡Ayúdanos a frustrar sus planes!', 25549),
(129327, 'esMX', 'Eso demorará la propagación vil en este oscuro lugar.', '', 25549),
(129326, 'esMX', '', 'Nuestras fuerzas se enfrentan a la Legión en la base. Debemos colocar la Égida en la torre antes de que nuestras pérdidas sean innumerables.', 25549),
(129325, 'esMX', 'La corrupción vil se propaga por la playa. Toma mi don y purifica esta tierra.', '', 25549),
(129324, 'esMX', '', 'Demonios estúpidos. ¿Alguna vez aprenderán? ¡No pueden derrotarnos!', 25549),
(129323, 'esMX', '', '¡Hay otro plan demoníaco para atacar a los Ancestros! ¡Demuéstrales a estas inmundicias por qué no pueden meterse con la naturaleza!', 25549),
(129322, 'esMX', 'Dadas tus opiniones sobre la moda y el buen gusto, ¿cómo explicas la monotonía de tus ropas?', 'Dadas tus opiniones sobre la moda y el buen gusto, ¿cómo explicas la monotonía de tus ropas?', 25549),
(129321, 'esMX', 'Nada aquieta el parloteo de los demonios como encontrar a uno de sus campeones frío y muerto. ¡Bien hecho!', '', 25549),
(129320, 'esMX', 'Erdu''val, uno de los guerreros más brutales de la Legión, se ufana de sus victorias. ¡Acaba con la vida retorcida de este charlatán!', '', 25549),
(129319, 'esMX', 'Bien hecho. Le mostraremos a la Legión que no pueden esconderse de la aniquilación.', '', 25549),
(129318, 'esMX', 'El demonio Dresanoth acecha entre los naga. ¡Destruye a todos los enemigos que se metan en tu camino y expulsa a esta escoria de nuestro mundo!', '', 25549),
(129317, 'esMX', 'La Legión alimentó a ese monstruo con carne mortal. ¡Una muerte excelente!', '', 25549),
(129316, 'esMX', 'Ese hedor aberrante en el aire significa que el acechador siniestro está cerca. Debemos acabar con esta feroz mascota de la Legión si queremos reclamar este templo.', '', 25549),
(129315, 'esMX', 'Ese gigante codicioso consiguió su merecido. ¡Bien hecho!', '', 25549),
(129314, 'esMX', 'Una ejecución gloriosa, $GSeñor:Señora; de la batalla, como siempre. No esperaba menos de ti.', '', 25549),
(129313, 'esMX', 'El poder de la tumba no solo ha llamado la atención de la Legión. Puñoalga, un codicioso y poderoso gigante de mar, ha emergido para quedarse con las reliquias del templo. ¡Hay que detenerlo!', '', 25549),
(129312, 'esMX', '¡$GSeñor:Señora; de la batalla! Los naga y sus lacayos skrog han vuelto a sus viejos hábitos. ¡Enséñales un poco de respeto!', '', 25549),
(129311, 'esMX', 'Las leyendas siempre destacan la ferocidad tenaz de Fauceabismo. ¡Me alegra que tengamos a nuestros propios héroes legendarios para detener esta amenaza!', '', 25549),
(129310, 'esMX', 'La presencia de la Legión ha despertado a una hidra ancestral conocida como Fauceabismo. Destruye a esta criatura antes de que descargue su ira sobre nuestro mundo.', '', 25549),
(129309, 'esMX', 'Bien hecho, héroes. La pérdida del Señor de la guerra Darjah ha debilitado el poderío de los naga en la tumba.', '', 25549),
(129308, 'esMX', 'La magia de los Vilnato requiere de cierta... sutileza. Qué pena que abusaran de ella. Tuvieron el destino que se merecían.', '', 25549),
(129307, 'esMX', '¡|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s comienza a lanzar |cFFFF0404|Hspell:234423|h[Drenar vida]|h|r!', '¡|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s comienza a lanzar |cFFFF0404|Hspell:234423|h[Drenar vida]|h|r!', 25549),
(129306, 'esMX', 'La presencia de la Maretista ha atraído a los fanáticos seguidores de la reina Azshara, incluso al esquivo Señor de la guerra Darjah. Una oportunidad excelente para eliminar esta amenaza.', '', 25549),
(129305, 'esMX', '', '¡Excelente pelea! Eso le enseñará a Ryul a no salir de su tumba.', 25549),
(129304, 'esMX', '', 'Ryul fue un guerrero formidable mientras vivió. Hoy, muerto, es una abominación que intenta destruirnos. Devuélvelo a su tumba.', 25549),
(129303, 'esMX', '', 'Ha recuperado la paz que se ganó hace mucho tiempo. Tienes mi agradecimiento.', 25549),
(129302, 'esMX', 'Esperemos que valga la pena.', 'Esperemos que valga la pena.', 25549),
(129301, 'esMX', '', 'Era una amiga de confianza que perdió la vida defendiendo este templo. Han profanado su descanso y hoy deambula por estos pasillos como un alma en pena. ¡Libérala de este tormento!', 25549),
(129300, 'esMX', 'Parece que no aprecias el regalo que te entrego. El regalo de una filosofía guía es uno que la mayoría nunca recibe, $n. $b$b<suspira> Mira, te juzgarán a través del tiempo por lo que vistas, y con mi investigación y enseñanzas, podrás crear objetos legendarios que te distinguirán de los demás. Empecemos.', '', 25549),
(129299, 'esMX', '', '¡Me dejaste perpleja! ¿O quizá debería decir "aturdida"?', 25549),
(129298, 'esMX', '', 'A nuestros pícaros les vendría bien una mano con la misión de la caverna. ¡Estas bombas aturdidoras les darán la ventaja que necesitan!', 25549),
(129297, 'esMX', 'Tienes razón, Illidan. Kil''jaeden y la Legión nos han derrotado en el pasado. Pero si peleamos juntos, podremos salvar Azeroth. ¡Lo sé!', '', 25549),
(129296, 'esMX', 'La impaciencia de la juventud. $b$bUn artesano solo es tan bueno como sus materiales, y —admitámoslo— la basura que has usado hasta ahora es una de las razones principales por las que te pareces más a los contadores de Ventormenta que a una leyenda en potencia. $b$bPiénsalo bien: cuando pinten cuadros de ti, el estilo y el peso de tus vestiduras o armadura quedarán plasmados en la historia. ¿No es eso lo que siempre quisiste?', '', 25549),
(129295, 'esMX', 'Kil''jaeden persiguió a mi pueblo por las estrellas, pero ya no huiremos. Pagará por sus atrocidades contra nuestro mundo... y contra mi hijo.', '', 25549),
(129294, 'esMX', 'Ojalá hubiera elegido otra profesión.', 'Ojalá hubiera elegido otra profesión.', 25549),
(129293, 'esMX', '', '¡Esa explosión fue mejor que la última! Creo que a Tethys le gustaría.', 25549),
(129292, 'esMX', '', 'Nuestros espías han avistado demonios en esta cueva, Hoja de las sombras. Hemos colocado los suministros adecuados. ¡Ya sabes qué hacer!', 25549),
(129291, 'esMX', '$GArchimago:Archimaga;, los Vilnato del Bancal Sollozante cuentan con sables de maná esclavizados. Si los liberamos, ¡esas mágicas criaturas podrían sernos de gran ayuda!', '', 25549),
(129290, 'esMX', 'Valientes palabras, Khadgar, pero la victoria necesita más que valor ahora. Los ejércitos de su Alianza y su Horda tenían valor... hasta que se enfrentaron a una masacre en la Costa Quebrada. El Falsario usará sus miedos y sus dudas en su contra.', '', 25549),
(129289, 'esMX', 'Pondremos fin a los planes de Kil''jaeden, Aegwynn. Esta vez no fallaremos.', '', 25549),
(129288, 'esMX', '', 'Los elfos construyeron este templo sobre un sitio de poder ancestral, una bóveda que creí que protegería la carcasa de mi enemigo caído. Pero con la ayuda de su discípulo, el Titán oscuro amenaza con regresar a este mundo más poderoso que nunca.', 25549),
(129287, 'esMX', '¿Te falta mucho?', '¿Te falta mucho?', 25549),
(129286, 'esMX', '', '¡Muy útil! ¿Disfrutaste de tu breve demostración de lo que sienten los cazadores de demonios cuando planean por el aire, $Ghéroe:heroína;?', 25549),
(129285, 'esMX', '¡Eso no importa! ¡Piensa en el potencial desperdiciado de lo que has hecho hasta ahora! $b$bNo es completamente tu culpa, aunque es claro que te has concentrado en la utilidad y la funcionalidad en lugar del estilo. Con el sistema SBEG, podrás revertir estas fallas y quizás, finalmente, tener la oportunidad de convertirte en una verdadera leyenda. $b$bEl camino es duro y está repleto de peligros.', '', 25549),
(129284, 'esMX', '', 'Los Pilares de la creación están en posición. Regresen a la catedral y yo revelaré el secreto ancestral que guarda este templo.', 25549),
(129283, 'esMX', '', '¡$GCampeón:Campeona;! Nuestro navío necesita núcleos de poder cargados de energía de géiseres viles. Estas alas raídas pueden ser útiles si te encuentras en el aire. ¡No dudes en desplegarlas!', 25549),
(129282, 'esMX', 'No sé de qué hablaba, pero no sonaba nada bien. ¡Y ni siquiera es el primero en hacer eso esta semana!', '', 25549),
(129281, 'esMX', 'Has pensado mucho en mis manos.', 'Has pensado mucho en mis manos.', 25549),
(129280, 'esMX', 'Tus manos... delicadas pero poderosas, endurecidas por la batalla pero hábiles... Son las únicas manos en las que deberías confiar para crear prendas o armaduras dignas de un héroe. $b$bMuchas de las leyendas de antaño que has leído en tu niñez no se preocupaban por los hechizos y las espadas, pero sus vestimentas... ¡oh, sus vestimentas! Por eso todavía hablamos de ellas. $b$b¡Muy pocos saben esto y ahora tú eres $Guno:una; de ellos!', '', 25549),
(129279, 'esMX', 'Ey, ey. ¡Ven, pasa! Descansa un poco, luego vuelve a salir y asegúrate de que sigamos aquí mañana.', '', 25549),
(129278, 'esMX', '¡Ey, tú! Ah, no importa. Creímos que eras uno de... ya sabes... ellos.', '', 25549),
(129277, 'esMX', '', 'Estas lágrimas de belleza perfecta representan el sueño de lo que nuestro mundo pudo haber sido. Hoy purifican sus corazones para la batalla que se avecina.', 25549),
(129276, 'esMX', '', 'Desde esta piedra fluían ríos y mares, la mismísima esencia vital de Azeroth. Hoy lava la oscuridad que rasga nuestro mundo.', 25549),
(129275, 'esMX', '', 'Mi eco los ha guiado hasta donde podía, campeones. En vida, lidié con demasiadas cargas sola y pagué terriblemente por mi orgullo. Solo si se mantienen unidos podrán sobreponerse a la oscuridad que los espera. Buena suerte.', 25549),
(129274, 'esMX', 'Ajá.', 'Ajá.', 25549),
(129273, 'esMX', 'Mi sistema Barbamartillo de estilo y buen gusto patentado es una filosofía natural de clase. Investigación extensa, ajustes detallados y pruebas exhaustivas realizadas por un servidor. La filosofía SBEG será un elemento tácito de tu educación. $b$bHabrá muchos peligros, $n, pero las recompensas son mucho más grandes de lo que puedes comprender hoy.', '', 25549),
(129272, 'esMX', '', 'Este martillo ha forjado maravillas ancestrales y ha dado forma a la tierra misma. Hoy destruye las ataduras del destino que pretende exterminarnos.', 25549),
(129271, 'esMX', '¿Cómo está la gente allí afuera?', '', 25549),
(129270, 'esMX', '¿Alguna noticia sobre lo que está pasando allí afuera?', '', 25549),
(129269, 'esMX', '¿Qué noticias traen los cielos, $n?', '', 25549),
(129268, 'esMX', 'Pocos entendieron que usara a los naga para obtener el Ojo de Sargeras, pero fue una táctica necesaria para preservar el futuro de Azeroth. ¡Que nada les impida hacer lo que sea necesario!', '', 25549),
(129267, 'esMX', 'Mantengan la guardia. Dudo que los espíritus atrapados aquí sean amistosos... o piadosos.', '', 25549),
(129266, 'esMX', 'Ha pasado una era desde que recorrí estos salones. Hice lo que era necesario, pero pagué un precio muy alto.', '', 25549),
(129265, 'esMX', 'Descansa y recupera las fuerzas. Las necesitaremos en las pruebas que nos esperan.', '', 25549),
(129264, 'esMX', 'Héroes, los caminos están abiertos. Usen los Pilares de la creación para eludir las protecciones de Aegwynn antes de que la Legión reclame el avatar.', '', 25549),
(129263, 'esMX', 'Entonces no tenemos tiempo que perder.', '', 25549),
(129262, 'esMX', 'Saludos, $n. Las noticias de tus hazañas en las Islas Quebradas han llegado a nuestro hogar de Ventormenta. Tu presencia es un honor para la Alianza.', '', 25549),
(129261, 'esMX', '', 'Presiento que uno de los amos de la Legión trata de reanimar el Avatar de Sargeras. Si Kil''jaeden logra imbuir esa carcasa con el poder del Titán oscuro, dudo que haya fuerza en este mundo capaz de detenerlo.', 25549),
(129260, 'esMX', '', 'Hay tantas personas que van y vienen, entran y salen de las tiendas, el banco... ¿Qué está pasando exactamente? Empiezo a ponerme nerviosa.', 25549),
(129259, 'esMX', '', '¿Alguien quiere un dulce? Nada hace olvidar las penas y la melancolía como darse un gusto fresco y sabroso.', 25549),
(129258, 'esMX', '', '¡$n, por aquí! Si te enteras de alguna novedad, cuéntame de inmediato. Necesito tiempo para empacar mis cosas.', 25549),
(129257, 'esMX', 'Cuéntame.', 'Cuéntame.', 25549),
(129256, 'esMX', '', 'Ahora mis guardas protectores les cortan el camino. Cada sello solo puede abrirse con uno de los Pilares de la creación. Pero cuidado: los demonios serán implacables y les impedirán el avance.', 25549),
(129255, 'esMX', '', 'He sellado cada nivel de este templo para que ningún invasor pudiera descender a sus profundidades. Jamás creí que la Legión encontraría otra forma de infiltrarse en su corazón.', 25549),
(129254, 'esMX', '', 'La preparación es fundamental, $n. Mis bienes pueden ser tuyos... por un precio.', 25549),
(129253, 'esMX', 'Tengo noticias para ti, $n: todo lo que has aprendido sobre tu profesión hasta el día de hoy fue un juego de niños. ¡No había ningún desafío, ni expresión, ni estilo, ni gracia! $b$bNo soy solo un historiador de la moda, joven $r, también soy un filósofo y, no me molesta admitirlo, algo así como un ícono del estilo por estos lares.', '', 25549),
(129252, 'esMX', '', '¿Estás $Gpreparado:preparada;, $n? Algunos de tus aliados no están manejando bien la situación.', 25549),
(129251, 'esMX', 'El eco de la Guardiana Aegwynn se presenta, igual que en la catedral.', '', 25549),
(129250, 'esMX', 'La Legión ha traído una clase de demonio nueva. Veamos si sangra como todos los demás.', '', 25549),
(129249, 'esMX', '¡No dejen a ninguno en pie! Si fallamos aquí, Azeroth arderá.', '', 25549),
(129248, 'esMX', '¡Rápido, ayuden a nuestras filas! ¡Debemos avanzar!', '', 25549),
(129247, 'esMX', '', 'Los cielos se oscurecen, $n. Espero que estés $Glisto:lista;.', 25549),
(129246, 'esMX', 'Sé que estos tiempos pueden ser estresantes, ¡pero no temas y deja que tu mente deambule por un lugar de misterio y emoción!', '', 25549),
(129245, 'esMX', '¡$GBienvenido:Bienvenida;, $n! Solo tenemos una regla: ¡tener una actitud positiva! No dejes que toda la conmoción del exterior te distraiga.', '', 25549),
(129244, 'esMX', 'No hay nada mejor para distraer una mente preocupada que unos juguetes. ¡Adelante, echa un vistazo en la tienda!', '', 25549),
(129243, 'esMX', '', '¡Adelante, $n! Deja tus preocupaciones en la puerta. Los guardias nos han asegurado que todo está bien.', 25549),
(129242, 'esMX', 'Saludos, $n.', '', 25549),
(129241, 'esMX', '', '¿Eh? ¿Por qué algo andaría mal? Vamos, muévete.', 25549),
(129240, 'esMX', '', 'Agregaré esto a nuestras reservas. ¡Gracias de nuevo, $GDestripador:Destripadora;!', 25549),
(129239, 'esMX', '', 'Las reservas del Martillo vil se están agotando, $GDestripador:Destripadora;. La energía vil que rodea a la tumba puede reabastecer nuestros núcleos de poder y tú deberías poder montar esos géisers hasta allí.', 25549),
(129238, 'esMX', 'Orgrimmar o los Reinos del Este', 'Orgrimmar o los Reinos del Este', 25549),
(129237, 'esMX', 'Península del Fuego Infernal de Terrallende', 'Península del Fuego Infernal de Terrallende', 25549),
(129236, 'esMX', 'Aquí en Mulgore no tenemos muchas opciones para viajar, pero te ayudaré en todo lo que pueda. \n\n¿A dónde quieres ir?', 'Aquí en Mulgore no tenemos muchas opciones para viajar, pero te ayudaré en todo lo que pueda. \n\n¿A dónde quieres ir?', 25549),
(129235, 'esMX', 'Otros continentes', 'Otros continentes', 25549),
(129234, 'esMX', 'Hay un portal en la cueva bajo el Alto de los Espíritus que te llevará al páramo desolado de la Península del Fuego Infernal de Terrallende.', 'Hay un portal en la cueva bajo el Alto de los Espíritus que te llevará al páramo desolado de la Península del Fuego Infernal de Terrallende.', 25549),
(129233, 'esMX', 'Darnassus cuenta con un portal a la Península del Fuego Infernal en el Templo de la Luna. Sigue mis indicaciones para llegar a Darnassus. Una vez allí, pregúntale a otra centinela si necesitas indicaciones para el Templo.', 'Darnassus cuenta con un portal a la Península del Fuego Infernal en el Templo de la Luna. Sigue mis indicaciones para llegar a Darnassus. Una vez allí, pregúntale a otra centinela si necesitas indicaciones para el Templo.', 25549),
(129232, 'esMX', 'El Disruptor abisal está listo para la construcción. Ven a donar tus suministros.', 'El Disruptor abisal está listo para la construcción. Ven a donar tus suministros.', 25549),
(129231, 'esMX', '¡Han atacado el Disruptor abisal! ¡Ya no podemos beneficiarnos con su gloria!', '¡Han atacado el Disruptor abisal! ¡Ya no podemos beneficiarnos con su gloria!', 25549),
(129230, 'esMX', '¡El Disruptor abisal está construido! Ya puedes acceder a las cosas.', '¡El Disruptor abisal está construido! Ya puedes acceder a las cosas.', 25549),
(129229, 'esMX', 'El Centro de mando está listo para construir. Ven a donar tus suministros.', 'El Centro de mando está listo para construir. Ven a donar tus suministros.', 25549),
(129228, 'esMX', '¡Han atacado el Centro de mando! ¡Ya no podemos beneficiarnos con su gloria!', '¡Han atacado el Centro de mando! ¡Ya no podemos beneficiarnos con su gloria!', 25549),
(129227, 'esMX', '¡El Centro de mando está construido! Ya puedes acceder a las cosas.', '¡El Centro de mando está construido! Ya puedes acceder a las cosas.', 25549),
(129226, 'esMX', 'Península del Fuego Infernal de Terrallende', 'Península del Fuego Infernal de Terrallende', 25549),
(129225, 'esMX', 'Ciudad de Ventormenta de los Reinos del Este', 'Ciudad de Ventormenta de los Reinos del Este', 25549),
(129224, 'esMX', 'Otros continentes', 'Otros continentes', 25549),
(129223, 'esMX', 'Si quieres llegar a las tierras estériles de la Península del Fuego Infernal de Terrallende, usa el portal ubicado en el Templo de la Luna.', 'Si quieres llegar a las tierras estériles de la Península del Fuego Infernal de Terrallende, usa el portal ubicado en el Templo de la Luna.', 25549),
(129222, 'esMX', 'El Exodar, la nave y el hogar de los draenei. Encontrarás un portal hacia El Exodar en el Templo de la Luna.', 'El Exodar, la nave y el hogar de los draenei. Encontrarás un portal hacia El Exodar en el Templo de la Luna.', 25549),
(129221, 'esMX', 'El barco hacia El Exodar parte del muelle occidental', 'El barco hacia El Exodar parte del muelle occidental', 25549),
(129220, 'esMX', 'El Exodar', 'El Exodar', 25549),
(129219, 'esMX', 'El barco a Ventormenta zarpa del muelle sur por allí.', 'El barco a Ventormenta zarpa del muelle sur por allí.', 25549),
(129218, 'esMX', 'Para llegar a Ventormenta primero debes atravesar el portal a la Aldea Rut''theran ubicado en el centro de la ciudad. Cuando estés en la base de Teldrassil, dirígete al muelle sur para subirte al barco.', 'Para llegar a Ventormenta primero debes atravesar el portal a la Aldea Rut''theran ubicado en el centro de la ciudad. Cuando estés en la base de Teldrassil, dirígete al muelle sur para subirte al barco.', 25549),
(129217, 'esMX', 'Vivimos en una isla. Por lo tanto, dependemos del mar y de nuestra habilidad mágica para subsistir.\n\n¿A dónde deseas viajar?', 'Vivimos en una isla. Por lo tanto, dependemos del mar y de nuestra habilidad mágica para subsistir.\n\n¿A dónde deseas viajar?', 25549),
(129216, 'esMX', '', '¡Ya he colocado las cadenas, $Ghéroe:heroína;! ¡Atrae a un demonio hasta la trampa para eliminarlo!', 25549),
(129215, 'esMX', '', '¡Y ahora afila tus cuchillas para las próximas batallas! ¡Los Illidari prevalecerán!', 25549),
(129214, 'esMX', '', '¡Con $Gel Destripador:la Destripadora; a la cabeza, la Legión CAERÁ! ¡Tomémonos este momento para celebrar nuestra victoria!', 25549),
(129213, 'esMX', 'Parece que Genn y Velen están hablando de mí, pero no logro entender lo que dicen...', '', 25549),
(129212, 'esMX', 'Debemos bajar la voz y actuar con normalidad, o alguien podría oírnos...', '', 25549),
(129211, 'esMX', 'Ventormenta y otras capitales de la Alianza', 'Ventormenta y otras capitales de la Alianza', 25549),
(129210, 'esMX', 'Fiordo Aquilonal de Rasganorte', 'Fiordo Aquilonal de Rasganorte', 25549),
(129209, 'esMX', 'Península del Fuego Infernal de Terrallende', 'Península del Fuego Infernal de Terrallende', 25549),
(129208, 'esMX', 'Forjaz no es la ciudad portuaria de Ventormenta, pero ofrecemos muchas rutas a otros continentes.\n\n¿A dónde te gustaría ir?', 'Forjaz no es la ciudad portuaria de Ventormenta, pero ofrecemos muchas rutas a otros continentes.\n\n¿A dónde te gustaría ir?', 25549),
(129207, 'esMX', 'Estoy listo para pelear.', 'Estoy lista para pelear.', 25549),
(129206, 'esMX', '¿Viniste con Magatha? Sabía que ella nos liberaría.', '¿Viniste con Magatha? Sabía que ella nos liberaría.', 25549),
(129205, 'esMX', 'Tienes mi agradecimiento, y mi maza.', 'Tienes mi agradecimiento, y mi maza.', 25549),
(129204, 'esMX', 'Hora de la venganza.', 'Hora de la venganza.', 25549),
(129203, 'esMX', '', 'Sssupongo que debería asegurarme de que el Martillo Vil reciba las reparaciones adecuadas. Nos vemos allí, $GDessstripador:Dessstripadora;.', 25549),
(129202, 'esMX', 'Oh, el Fiordo Aquilonal de Rasganorte. Te espera un buen viaje. Busca a Gryth Thurden, el maestro de grifos, para conseguir un vuelo al Puerto de Menethil. El Picanorte parte desde allí con destino a Valgarde.', 'Oh, el Fiordo Aquilonal de Rasganorte. Te espera un buen viaje. Busca a Gryth Thurden, el maestro de grifos, para conseguir un vuelo al Puerto de Menethil. El Picanorte parte desde allí con destino a Valgarde.', 25549),
(129201, 'esMX', '¡La caída de su mundo ha comenzado!', '', 25549),
(129200, 'esMX', '¡No puedes escapar! ¡Nuestro alcance es infinito!', '', 25549),
(129199, 'esMX', '¡Sientan dolor en sus corazones a medida que las garras de Sargeras aprisionan su mundo!', '', 25549),
(129198, 'esMX', 'Carne débil y huesos quebradizos... ¡No son rivales para la Legión!', '', 25549),
(129197, 'esMX', 'Conque la Península del Fuego Infernal. Ese páramo abrasado de Terrallende. Bueno, nuestros magos han creado un portal para llevarte allí en la Sala de los Misterios, ubicada en la Sala Mística.', 'Conque la Península del Fuego Infernal. Ese páramo abrasado de Terrallende. Bueno, nuestros magos han creado un portal para llevarte allí en la Sala de los Misterios, ubicada en la Sala Mística.', 25549),
(129196, 'esMX', 'Mortales, su mundo se derrumba alrededor de ustedes. ¡No pueden detenernos!', '', 25549),
(129195, 'esMX', 'Mortales frágiles. ¡Arrodíllense ante el poder de la Legión Ardiente!', '', 25549),
(129194, 'esMX', 'Otros continentes', 'Otros continentes', 25549),
(129193, 'esMX', 'Te odio...', '', 25549),
(129192, 'esMX', '', 'Ah, ¿esa cosa brillante? La perdí.', 25549),
(129191, 'esMX', '¡¿De veras?! ¡Pásame ese Fragmento de vinculación y el hechizo se romperá!', '', 25549),
(129190, 'esMX', '', '¡Por supuesto! ¿Cómo lo hago?', 25549),
(129189, 'esMX', '¿Alguna vez me dejarás ir?', '', 25549),
(129188, 'esMX', 'Claro. La próxima semana.', '', 25549),
(129187, 'esMX', '', 'Entonces... ¿La próxima semana?', 25549),
(129186, 'esMX', 'Me dieron esta vida miserable hace eones, cuando me crearon dentro de los reinos más profundos del vacío.', '', 25549),
(129185, 'esMX', '', 'Ey, Iksy. ¿Cuándo es tu cumpleaños? ¡Tenemos que festejar!', 25549),
(129184, 'esMX', '¿Estar suspendido eternamente en una prisión construida por un goblin insoportable? Es de lo mejor...', '', 25549),
(129183, 'esMX', '', 'Parece que la diversión no se detiene.', 25549),
(129182, 'esMX', '', 'Tomaré eso como un sí.', 25549),
(129181, 'esMX', 'Si te acercas a mí, te arrancaré la mano.', '', 25549),
(129180, 'esMX', '', '¿Los demonios tienen cosquillas?', 25549),
(129179, 'esMX', 'Ciudad de Lunargenta de los Reinos del Este', 'Ciudad de Lunargenta de los Reinos del Este', 25549),
(129178, 'esMX', 'Orgrimmar de Kalimdor', 'Orgrimmar de Kalimdor', 25549),
(129177, 'esMX', 'Fiordo Aquilonal de Rasganorte', 'Fiordo Aquilonal de Rasganorte', 25549),
(129176, 'esMX', 'Península del Fuego Infernal de Terrallende', 'Península del Fuego Infernal de Terrallende', 25549),
(129175, 'esMX', 'Vega de Tuercespina de los Reinos del Este', 'Vega de Tuercespina de los Reinos del Este', 25549),
(129174, 'esMX', 'Hombres mágicos abren portal a Península del Fuego Infernal de Terrallende. Encontrarlo en su Barrio de los Magos.', 'Hombres mágicos abren portal a Península del Fuego Infernal de Terrallende. Encontrarlo en su Barrio de los Magos.', 25549),
(129173, 'esMX', 'Elfos brillantes colocan orbe teletransportador en ruinas sobre Entrañas. Tócala para ir a su hogar de Ciudad de Lunargenta.', 'Elfos brillantes colocan orbe teletransportador en ruinas sobre Entrañas. Tócala para ir a su hogar de Ciudad de Lunargenta.', 25549),
(129172, 'esMX', 'Meefi te lleva a fría Rasganorte. Su globo parte de torre izquierda al norte de Ruinas de Lordaeron. Ve a Fortaleza de la Venganza de Fiordo Aquilonal para pelear vrykul.', 'Meefi te lleva a fría Rasganorte. Su globo parte de torre izquierda al norte de Ruinas de Lordaeron. Ve a Fortaleza de la Venganza de Fiordo Aquilonal para pelear vrykul.', 25549),
(129171, 'esMX', 'No.', '', 25549),
(129170, 'esMX', '', 'No sabes para qué sirven, ¿verdad?', 25549),
(129169, 'esMX', 'Es un secreto protegido por guardianes de secretos ancestrales por razones secretas.', '', 25549),
(129168, 'esMX', '', '¿Por qué te gustan tanto los fragmentos del vacío?', 25549),
(129167, 'esMX', '', '¿Cómo están las cosas afuera, $n? Con tantos clientes, ha sido un desafío cumplir con todos los pedidos. Espero que todo esté bien.', 25549),
(129166, 'esMX', '', 'A nuestros visitantes les agradan nuestros bienes. Confío en que si llega el momento, no dudarán en... Ah, $Gbienvenido:bienvenida; a la tienda, $n.', 25549),
(129165, 'esMX', '', 'Cíñete a lo que conoces, Icks. No tiene sentido especular. Y ahora mantente atento, tenemos una visita.', 25549),
(129164, 'esMX', 'La guerra ha consumido toda mi energía y atención. No he tenido un momento para el luto.', '', 25549),
(129163, 'esMX', 'No he regresado a Descanso del león desde que trasladaron el monumento conmemorativo de mi padre desde el castillo hasta aquí.', '', 25549),
(129162, 'esMX', 'He pescado tanto aquí que ya no queda nada, pero con la guerra y todo lo demás, es demasiado peligroso abandonar la ciudad.', '', 25549),
(129161, 'esMX', 'Orgrimmar es el corazón de la Horda y ofrece muchas formas de viajar a los límites de Azeroth y más allá. \n\n¿A dónde te gustaría viajar?', 'Orgrimmar es el corazón de la Horda y ofrece muchas formas de viajar a los límites de Azeroth y más allá. \n\n¿A dónde te gustaría viajar?', 25549),
(129160, 'esMX', 'Las Tierras Devastadas y el portal a Draenor', 'Las Tierras Devastadas y el portal a Draenor', 25549),
(129159, 'esMX', 'Península del Fuego Infernal de Terrallende', 'Península del Fuego Infernal de Terrallende', 25549),
(129158, 'esMX', 'Áreas creadas por el Cataclismo', 'Áreas creadas por el Cataclismo', 25549),
(129157, 'esMX', 'Dalaran por encima de las Islas Quebradas', 'Dalaran por encima de las Islas Quebradas', 25549),
(129156, 'esMX', 'Poblado Almíbar de Pandaria', 'Poblado Almíbar de Pandaria', 25549),
(129155, 'esMX', 'Vega de Tuercespina de los Reinos del Este', 'Vega de Tuercespina de los Reinos del Este', 25549),
(129154, 'esMX', 'Cima del Trueno de Mulgore', 'Cima del Trueno de Mulgore', 25549),
(129153, 'esMX', 'Tundra Boreal de Rasganorte', 'Tundra Boreal de Rasganorte', 25549),
(129152, 'esMX', 'Entrañas o Ciudad de Lunargenta de los Reinos del Este', 'Entrañas o Ciudad de Lunargenta de los Reinos del Este', 25549),
(129151, 'esMX', 'Nuestros aliados de Pandaria nos han permitido crear un portal al Poblado Almíbar en el Bosque de Jade. Se encuentra en el medio del Valle del Honor.', 'Nuestros aliados de Pandaria nos han permitido crear un portal al Poblado Almíbar en el Bosque de Jade. Se encuentra en el medio del Valle del Honor.', 25549),
(129150, 'esMX', 'El Kirin Tor ha establecido un portal en el Circo de las Sombras para ayudar a los jugadores a llegar a Dalaran sobre las Islas Quebradas.', 'El Kirin Tor ha establecido un portal en el Circo de las Sombras para ayudar a los jugadores a llegar a Dalaran sobre las Islas Quebradas.', 25549),
(129149, 'esMX', '%s desenfunda su arma.', '', 25549),
(129148, 'esMX', '¡Alto! ¡Ahh! ¿Cuántas veces pasará esto? Primero los guardias pasan a ver que esté todo bien, ahora tú... Bueno, no hay mucho para elegir, pero echa un vistazo.', '', 25549),
(129147, 'esMX', '¡Las manos donde pueda verlas! ¡Gah! Eres tú otra vez. Tuve que echar a tantos maleantes últimamente que ya no sé qué pensar.', '', 25549),
(129146, 'esMX', 'Nuestros magos han abierto un portal dentro del Circo de las Sombras para ayudar a los jugadores a llegar a las Tierras Devastadas y a Draenor.', 'Nuestros magos han abierto un portal dentro del Circo de las Sombras para ayudar a los jugadores a llegar a las Tierras Devastadas y a Draenor.', 25549),
(129145, 'esMX', '¡No te muevas! Ah, ¿eres tú, $n? ¡Esos malditos ladrones han estado entrando y saliendo todo el día! Echa un vistazo, pero no te demores.', '', 25549),
(129144, 'esMX', 'Hay un portal que lleva a la Península del Fuego Infernal de Terrallende. Se encuentra en el Circo de las Sombras, debajo de Orgrimmar.', 'Hay un portal que lleva a la Península del Fuego Infernal de Terrallende. Se encuentra en el Circo de las Sombras, debajo de Orgrimmar.', 25549),
(129143, 'esMX', '', '¡Espera! ¡Espera! ¿Alguna novedad, $n? Estamos empezando a ponernos ansiosos por recibir noticias.', 25549),
(129142, 'esMX', '', 'Lamento molestarte, $n, ¿pero tienes alguna novedad? Los guardias pasan a menudo pero no nos dan mucha información.', 25549),
(129141, 'esMX', '', '¡Por aquí, $n! ¿Tienes alguna noticia? No sé mucho, pero algunas personas se están comportando de manera muy extraña por aquí.', 25549),
(129140, 'esMX', 'Pero aun cuando recorro este camino familiar, nunca me había sentido más perdido.', '', 25549),
(129139, 'esMX', 'Ventormenta siempre ha sido mi hogar. Conozco sus tiendas y sus calles como la palma de mi mano.', '', 25549),
(129138, 'esMX', 'Si vas a la Tundra Boreal de Rasganorte debes tomar el zepelín Viento poderoso. Busca a Greeb Lanzacohetes en la torre del zepelín oeste para cuando parta hacia Bastión Grito de Guerra.', 'Si vas a la Tundra Boreal de Rasganorte debes tomar el zepelín Viento poderoso. Busca a Greeb Lanzacohetes en la torre del zepelín oeste para cuando parta hacia Bastión Grito de Guerra.', 25549),
(129137, 'esMX', 'Los ánimos de las personas se oscurecen como el firmamento. Sin embargo, la esperanza todavía puede devolvernos la luz.', '', 25549),
(129136, 'esMX', 'Busca a Snurk Oroveloz en la torre del zepelín oeste en la cima de la meseta central de Ogrimmar. Es la maestra de zepelines de la Vega de Tuercespina y te dará más información sobre el horario de partida del zepelín hacia nuestra avanzada de Grom''gol en el sur de los Reinos del Este.', 'Busca a Snurk Oroveloz en la torre del zepelín oeste en la cima de la meseta central de Ogrimmar. Es la maestra de zepelines de la Vega de Tuercespina y te dará más información sobre el horario de partida del zepelín hacia nuestra avanzada de Grom''gol en el sur de los Reinos del Este.', 25549),
(129135, 'esMX', 'Para llegar a Entrañas o la Ciudad de Lunargenta, deberías buscar a Frezza en la torre del zepelín este en la meseta de central de Orgrimmar. Él te dará más información sobre el horario de partida del zepelín hacia Rémol en los Claros de Tirisfal, justo al norte de Entrañas. Hay un teletransportador en la entrada de Entrañas que puede llevarte a la Ciudad de Lunargenta.', 'Para llegar a Entrañas o la Ciudad de Lunargenta, deberías buscar a Frezza en la torre del zepelín este en la meseta de central de Orgrimmar. Él te dará más información sobre el horario de partida del zepelín hacia Rémol en los Claros de Tirisfal, justo al norte de Entrañas. Hay un teletransportador en la entrada de Entrañas que puede llevarte a la Ciudad de Lunargenta.', 25549),
(129134, 'esMX', 'El zepelín a Cima del Trueno en el centro de Kalimdor parte de la torre del zepelín occidental sobre la meseta central de Orgrimmar. La maestra de zepelines Zelli Tobera Ígnea podrá darte más información.', 'El zepelín a Cima del Trueno en el centro de Kalimdor parte de la torre del zepelín occidental sobre la meseta central de Orgrimmar. La maestra de zepelines Zelli Tobera Ígnea podrá darte más información.', 25549),
(129133, 'esMX', 'El aire nos habla de muchas maneras, $n. ¿Qué te dicen estos tiempos a ti?', '', 25549),
(129132, 'esMX', 'No dejes que el comportamiento de los demás te afecte. Debemos mantener la compostura cuando nos enfrentamos a lo desconocido.', '', 25549),
(129131, 'esMX', 'No dejes que el comportamiento de los demás influencie tu opinión. Debemos mantener la compostura cuando nos enfrentamos a lo desconocido.', '', 25549),
(129130, 'esMX', 'No lo olvides... Quien busque conclusiones rápidas quizás llegue primero, pero no siempre a un destino de su agrado.', '', 25549),
(129125, 'esMX', '', '¡|TInterface\\Icons\\inv_misc_horn_03:20|t%s |cFFFF0000|Hspell:237937|h[Potencia]|h|r a todo su consejo!', 25549),
(129124, 'esMX', '', '¡|TInterface\\Icons\\inv_misc_horn_03:20|t%s se |cFFFF0000|Hspell:237937|h[Potencia]|h|r a sí misma y a uno de sus aliados!', 25549),
(129123, 'esMX', '', '¡|TInterface\\Icons\\inv_misc_horn_03:20|t%s |cFFFF0000|Hspell:237937|h[Potencia]|h|r a $n!', 25549),
(129122, 'esMX', '¡Sobrevivientes! Defenderemos esta posición. Tú encárgate de encontrarlos antes que la Legión.', '', 25549),
(129121, 'esMX', 'No podremos resistir otro ataque de una de esas criaturas. Debemos fortalecer nuestras filas.', '', 25549),
(129120, 'esMX', 'Cada demonio que matemos aquí morirá por última vez. No cedas.', '', 25549),
(129118, 'esMX', 'Las alimañas ya están inquietas.', '', 25549),
(129117, 'esMX', 'No podremos defender esta posición por mucho tiempo.', '', 25549),
(129115, 'esMX', 'Hasta ahora este brujo ha sido bastante útil para descifrar las magias de nuestros enemigos.\n\nTambién estuvo a punto de hacer que nos maten a los dos en varias ocasiones, pero ese era un riesgo que ya conocía cuando acepté aliarme con semejante villano.\n\nA pesar de sus muchas fallas, también me ha salvado la vida varias veces. Para bien o para mal, llegaremos al final de esto, juntos.', '', 25549),
(129114, 'esMX', 'Mira, estos portales no van a sabotearse solos. Necesito tiempo para hacer esto bien o podrías aparecer en una olla de fundición de la Legión o los intestinos de un señor del foso. \n\n¿Quieres teletransportarte a los intestinos de un señor del foso? Oh, claro, al principio parece un ataque astuto e inesperado. Pero luego te digieren en jugos viles y te preguntas qué pasó con tu gran plan.\n\nDéjame trabajar.', '', 25549),
(129113, 'esMX', 'Héroes de Azeroth, las órdenes de sus clases se han vuelto muy poderosas a lo largo de nuestra campaña en las Islas Quebradas. Su fuerza, su coraje, ahora son necesarios. Ha llegado la hora de unir nuestras fuerzas y de liberar a Azeroth de la Legión Ardiente.', '', 25549),
(129112, 'esMX', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t¡Una de las runas |cFFFF0000|Hspell:237908|h[Detona]|h|r!', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t¡Una de las runas |cFFFF0000|Hspell:237908|h[Detona]|h|r!', 25549),
(129111, 'esMX', 'Áreas creadas por el Cataclismo', 'Áreas creadas por el Cataclismo', 25549),
(129110, 'esMX', 'Tundra Boreal de Rasganorte', 'Tundra Boreal de Rasganorte', 25549),
(129109, 'esMX', 'Teldrassil o El Exodar de Kalimdor', 'Teldrassil o El Exodar de Kalimdor', 25549),
(129108, 'esMX', 'Las Tierras Devastadas y el portal a Draenor', 'Las Tierras Devastadas y el portal a Draenor', 25549),
(129107, 'esMX', 'Península del Fuego Infernal de Terrallende', 'Península del Fuego Infernal de Terrallende', 25549),
(129106, 'esMX', 'Dalaran de las Islas Quebradas', 'Dalaran de las Islas Quebradas', 25549),
(129105, 'esMX', 'Aldea Zarpa''don de Pandaria', 'Aldea Zarpa''don de Pandaria', 25549),
(129104, 'esMX', 'Forjaz', 'Forjaz', 25549),
(129103, 'esMX', 'La Legión será su fin...', '', 25549),
(129102, 'esMX', '¡Estos suministros le pertenecen a la Legión!', '', 25549),
(129100, 'esMX', 'Tus acciones llevan al máximo los límites de nuestra alianza, Caballero de la muerte.', '', 25549),
(129099, 'esMX', 'Nunca encontrarás lo que buscas, Libramorte. Ya has prolongado demasiado tu visita a este templo, ¡fuera!', '', 25549),
(129098, 'esMX', 'No sé de qué estás hablando. Y ahora, si me disculpas, tengo asuntos de que ocuparme. Puedes hacerle cualquier otra pregunta a nuestro representante.', '', 25549),
(129097, 'esMX', 'Dime todo lo que sepas sobre un poderoso dragón que murió en un glaciar al norte de Corona de Hielo.', 'Dime todo lo que sepas sobre un poderoso dragón que murió en un glaciar al norte de Corona de Hielo.', 25549),
(129096, 'esMX', 'La peste de la no-muerte te sigue hasta este templo de vida. No te quedes por mucho tiempo.', '', 25549),
(129095, 'esMX', 'Ventormenta es el centro de la Alianza y ofrece muchas formas de viajar a los límites de Azeroth y más allá. \n\n¿A dónde te gustaría ir?', 'Ventormenta es el centro de la Alianza y ofrece muchas formas de viajar a los límites de Azeroth y más allá. \n\n¿A dónde te gustaría ir?', 25549),
(129094, 'esMX', 'El Tranvía Subterráneo es la ruta más rápida a Forjaz. Lo encontrarás en el Distrito de los Enanos.', 'El Tranvía Subterráneo es la ruta más rápida a Forjaz. Lo encontrarás en el Distrito de los Enanos.', 25549),
(129092, 'esMX', 'Nuestros nuevos aliados en Pandaria nos han permitido crear un portal a la Aldea Zarpa''don en el Bosque de Jade. Se encuentra en el límite occidental del lago junto al Castillo de Ventormenta.', 'Nuestros nuevos aliados en Pandaria nos han permitido crear un portal a la Aldea Zarpa''don en el Bosque de Jade. Se encuentra en el límite occidental del lago junto al Castillo de Ventormenta.', 25549),
(129091, 'esMX', 'Tienes suerte de que Dalaran esté ubicada sobre las Islas Quebradas, y de que el Kirin Tor haya establecido un portal justo dentro del Castillo de Ventormenta.', 'Tienes suerte de que Dalaran esté ubicada sobre las Islas Quebradas, y de que el Kirin Tor haya establecido un portal justo dentro del Castillo de Ventormenta.', 25549),
(129090, 'esMX', 'Di lo que quieras sobre Arthas, pero el antiguo Rey Exánime tenía una fría eficiencia para lidiar con la Legión.', '', 25549),
(129089, 'esMX', 'Hay un portal que lleva a la Península del Fuego Infernal de Terrallende. Se encuentra en el Sagrario del Mago, ubicado en la cima de la Torre de los magos.', 'Hay un portal que lleva a la Península del Fuego Infernal de Terrallende. Se encuentra en el Sagrario del Mago, ubicado en la cima de la Torre de los magos.', 25549),
(129088, 'esMX', 'Los magos han abierto un portal dentro de la Torre de los magos para ayudar a los jugadores a llegar a las Tierras Devastadas y a Draenor. Junto a él, verás a la maga Chispabrillante.', 'Los magos han abierto un portal dentro de la Torre de los magos para ayudar a los jugadores a llegar a las Tierras Devastadas y a Draenor. Junto a él, verás a la maga Chispabrillante.', 25549),
(129087, 'esMX', 'Se siente tan bien estar lejos de Acherus haciendo algo útil... volver a la vieja investigación de campo con cadáveres frescos y pilas de huesos.', '', 25549),
(129086, 'esMX', 'Si esto es una representación del tipo de nigromancia que practica la Legión Ardiente, nuestra situación es mejor de lo que creía.', '', 25549),
(129085, 'esMX', 'Si vas al Exodar o a Teldrassil en Kalimdor, busca a Nayura. Es la maestra de embarcadero del Valentía, que partirá del muelle al sur de Puerto de Ventormenta.', 'Si vas al Exodar o a Teldrassil en Kalimdor, busca a Nayura. Es la maestra de embarcadero del Valentía, que partirá del muelle al sur de Puerto de Ventormenta.', 25549),
(129084, 'esMX', 'Si vas a Rasganorte, debes buscar a Leesha Curtidoby, la maestra de embarcadero del Kraken. Parte hacia la Fortaleza Denuedo de la Tundra Boreal desde el muelle norte del puerto de Ventormenta.', 'Si vas a Rasganorte, debes buscar a Leesha Curtidoby, la maestra de embarcadero del Kraken. Parte hacia la Fortaleza Denuedo de la Tundra Boreal desde el muelle norte del puerto de Ventormenta.', 25549),
(129083, 'esMX', '', 'Discúlpame si parezco un poco nerviosa. $GBienvenido:Bienvenida; a la tienda.', 25549),
(129082, 'esMX', '¿Qué tipo de ayuda?', '¿Qué tipo de ayuda?', 25549),
(129081, 'esMX', 'Estoy seguro de que el Consejo está bien preparado, Kerta. Muéstrate atenta. Tenemos otro cliente.', '', 25549),
(129080, 'esMX', '¡Adelante! Kerta y yo estábamos hablando sobre los últimos acontecimientos. Me gustaría conocer tu opinión.', '', 25549),
(129079, 'esMX', '$GBienvenido:Bienvenida;. Me temo que nuestros suministros son un poco escasos. Hemos estado preparando pedidos sin descanso desde... Bueno, ya sabes.', '', 25549),
(129078, 'esMX', 'No, Kerta. No creo que tengamos nada de qué preocuparnos. Ahora, concéntrate. No hagamos esperar a $Gnuestro invitado:nuestra invitada;.', '', 25549),
(129077, 'esMX', '¡$GBienvenido, viajero:Bienvenida, viajera;! ¿Cómo anda todo ahí afuera?', '', 25549),
(129076, 'esMX', 'La Legión Ardiente sigue tratando de recrear la obra maestra que era la Plaga. \n\nRecurren a los nathrezim, que crean marionetas a partir de huesos. \n\nRecurren a estos Caminaespíritus caídos, que no hacen más que entrometerse con estas magias.\n\nEstoy aquí en nombre de la Espada de Ébano, para observar y juzgar. Y para ayudarte, $Ghéroe:heroína;, si me necesitas.', '', 25549),
(129075, 'esMX', 'Si no levantas la mirada todo está bien. ¡Sigue tu camino!', '', 25549),
(129074, 'esMX', 'Ocúpate de tus asuntos, $Gamigo:amiga;.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129073, 'esMX', '¡El fin está cerca, $n! Al menos es lo que dicen. No veo razón para no participar.', '', 25549),
(129072, 'esMX', 'No sé qué piensas tú, pero yo me niego a conocer a mi creador vestido con un atuendo de mago común.', '', 25549),
(129071, 'esMX', 'No seré una herramienta de la Legión.', '', 25549),
(129070, 'esMX', 'El precio no es un obstáculo si hay que salir con estilo. Estoy totalmente en bancarrota... pero pronto no importará.', '', 25549),
(129069, 'esMX', 'Soy... soy libre. Gracias.', '', 25549),
(129068, 'esMX', '¿Y qué trae a $Gun:una; $c como tú por aquí, $n? ¿Buscas un atuendo elegante para el fin del mundo tal como lo conocemos?', '', 25549),
(129067, 'esMX', 'Solo tú puedes acabar con este tormento, hermano. ¡Pelea!', '', 25549),
(129066, 'esMX', 'Ah, $n. Justo $Gel:la; $c que estaba buscando. ¿Te gusta mi atuendo nuevo? Bah, ¿a quién engaño? Pronto no importará.', '', 25549),
(129065, 'esMX', '¡Purga esta corrupción, $gamigo mío:amiga mía;!', '', 25549),
(129064, 'esMX', '¡Regresa al descanso que te ganaste hace tanto tiempo, hermano!', '', 25549),
(129063, 'esMX', 'Te sugiero que te deshagas de esos harapos y te pongas algo más elegante. El fin del universo no es excusa para no verse bien.', '', 25549),
(129062, 'esMX', '¡Hay algo raro con mis conejos! Pobrecitos... ¡Tenemos que hacer algo!', '', 25549),
(129061, 'esMX', '¡Debemos encargarnos de ese demonio, $n! Luego nos ocuparemos de Erdris.', '', 25549),
(129060, 'esMX', 'No temas. Puedo resucitar más.', '', 25549),
(129059, 'esMX', '¡Los demonios atacan a mis tropas antes de que puedan recuperarse!', '', 25549),
(129058, 'esMX', '', '¿Pero qué demonios pasó con mis gallinas?', 25549),
(129057, 'esMX', '...y hablando de eso, obviamente no podemos olvidarnos del Cúmulo de cinco: los Trozos de hielo pequeños norte, sur, este y oeste que técnicamente no están designados como glaciares. Es una historia muy graciosa...', '', 25549),
(129056, 'esMX', '', 'Ese golpe en la cabeza sí que fue feo. Aun así, $Gnuestro Destripador:nuestra Destripadora; es muy fuerte. ¡Mira!', 25549),
(129055, 'esMX', '', '$GEl Destripador:La Destripadora; sigue inconsciente. Temo por lo que pasará si...', 25549),
(129054, 'esMX', 'Alrededor del Gran glaciar norte estaban, en orden de formación, el Glaciar noreste mediano, el Pequeño glaciar sur, el Pequeño glaciar sudoeste, el Pequeño glaciar sud-sudoeste, el Pequeño glaciar sud-sudeste, el Pequeño glaciar sur, el Primer y el Segundo glaciar pequeño norte que siempre cambian de posición...', '', 25549),
(129053, 'esMX', '¡Agh! ¡Está bien! Antes había unos... glaciares... enormes... al norte de Corona de Hielo... se alejaron hace años... No sé nada más, ¡lo juro! Habla con... ¡Tariol!', '', 25549),
(129052, 'esMX', '<Los ojos de Trizormu se entrecierran.>\n\n¿Y para qué querría un Libramorte como tú esa información?', '', 25549),
(129051, 'esMX', '¡Ah, hola! Gracias por visitarme de nuevo.\n\n¿O es la primera vez?\n\n¿Qué día es?', '', 25549),
(129050, 'esMX', 'No, no que yo recuerde. Lo siento mucho, todavía estoy dolido por el fallecimiento de nuestra amada Ysera; casi que no puedo pensar en otra cosa. ¿Le preguntaste al vuelo bronce? Tienen una memoria formidable.', '', 25549),
(129049, 'esMX', '', '¡Contempla nuestro poder vil!', 25549),
(129048, 'esMX', 'Dime todo lo que sepas sobre un glaciar emplazado al norte donde murió un poderoso dragón.', 'Dime todo lo que sepas sobre un glaciar emplazado al norte donde murió un poderoso dragón.', 25549),
(129047, 'esMX', '', 'Aquí vamos. ¡Prepárate!', 25549),
(129046, 'esMX', '<Lethecus tiene la mirada perdida.>\n\nOh, ¿sí? No te había visto.\n\n<Lethecus bosteza.>', '', 25549),
(129045, 'esMX', '', '¡Solo será un momento!', 25549),
(129044, 'esMX', '', '¿Eso crees? ¿Cómo hará exactamente para detener a un ejército infinito de demonios e impedir que maten a todos?', 25549),
(129043, 'esMX', 'A veces el miedo juega con la mente. Deberías descansar un poco, Jenny.', '', 25549),
(129042, 'esMX', 'Encontraremos la forma de comprender el sentido de todo esto, y cuando llegue el momento de actuar, no tengo dudas de que nuestros aliados estarán bien preparados.', 'Encontraremos la forma de comprender el sentido de todo esto, y cuando llegue el momento de actuar, no tengo dudas de que nuestros aliados estarán bien preparados.', 25549),
(129041, 'esMX', 'No importa lo que haga, no puedo evitar levantar la mirada.', 'No importa lo que haga, no puedo evitar levantar la mirada.', 25549),
(129040, 'esMX', '¿Has visto la tienda de primeros auxilios? La fila es tan larga que llega hasta afuera.', '¿Has visto la tienda de primeros auxilios? La fila es tan larga que llega hasta afuera.', 25549),
(129039, 'esMX', 'No puedes decir que no lo presientes. Mira a nuestro alrededor. Este mundo empieza a dudar de sí mismo.', 'No puedes decir que no lo presientes. Mira a nuestro alrededor. Este mundo empieza a dudar de sí mismo.', 25549),
(129038, 'esMX', '¿Cuánto falta para que nuestro mundo se derrumbe?', '¿Cuánto falta para que nuestro mundo se derrumbe?', 25549),
(129037, 'esMX', 'Destruyen unas pocas naves y lo llaman victoria. Será la última, se los aseguro. Saboreen este momento, ¡porque nuestro próximo encuentro será su fin!', '', 25549),
(129036, 'esMX', '¿Otro mortal insolente desea enfrentarme? ¡Que así sea!', '', 25549),
(129035, 'esMX', '¡Silencio!', '', 25549),
(129034, 'esMX', 'Sí, acércate. ¡Me vendría bien un poco de entretenimiento!', '', 25549),
(129033, 'esMX', 'El cielo se acerca día tras día. ¿Alguna vez terminará?', 'El cielo se acerca día tras día. ¿Alguna vez terminará?', 25549),
(129032, 'esMX', 'Illidan, lleva la Égida de Aggramar a la catedral. Descenderé a la tumba con Khadgar y perseguiré al demonio. ¡El reino de destrucción de Kil''jaeden está por terminar!', '', 25549),
(129031, 'esMX', '¡Mephistroth!', '', 25549),
(129030, 'esMX', 'Quizás. Pero no hoy, ¡demonio!', '', 25549),
(129029, 'esMX', '¡Basta de discusiones! ¡Concéntrense!', '', 25549),
(129028, 'esMX', 'Igual que nosotros.', '', 25549),
(129027, 'esMX', 'Yo... no puedo evitarlo. He tratado de mantenerme ocupado, pero mi mente siempre vuelve a este sentimiento... Este... Ya no sé cómo llamarlo.', 'Yo... no puedo evitarlo. He tratado de mantenerme ocupada, pero mi mente siempre vuelve a este sentimiento... Este... Ya no sé cómo llamarlo.', 25549),
(129026, 'esMX', '¡Estás condenado al fracaso!', '', 25549),
(129025, 'esMX', '¿Crees que unos pocos mortales con armas llamativas pueden detenernos?', '', 25549),
(129024, 'esMX', 'Toma, esto te ayudará. Plántalas alrededor de la nave. Yo las activaré desde aquí cuando todo esté listo.', '', 25549),
(129023, 'esMX', '', 'Tienes demasiada confianza en Illidan, profeta. Me encargaré de que cumpla con lo que le corresponde.', 25549),
(129022, 'esMX', '', 'Illidan, has sido muy amable en venir. Celadoras, encárguense del verdadero trabajo mientras los cazadores de demonios de Illidan revolotean por ahí con sus murciélagos.', 25549),
(129021, 'esMX', '', '¡¿Más portales?! ¿Dónde demonios están los refuerzos?', 25549),
(129020, 'esMX', '', 'Las Celadoras están contigo, $ct.', 25549),
(129019, 'esMX', 'Puede que hayamos ganado hoy, pero aún nos espera una gran amenaza. El amo de la Legión todavía no ha hecho su jugada.', '', 25549),
(129018, 'esMX', '¡Los brujos arrebataron tu mundo, nathrezim! Yo no sería tan arrogante en tu lugar.', '', 25549),
(129016, 'esMX', 'Bien. Tenemos nuestras órdenes. Buena suerte.', '', 25549),
(129015, 'esMX', '¿Pero cómo llegó hasta ahí? No pudo aparecer de la nada.', '¿Pero cómo llegó hasta ahí? No pudo aparecer de la nada.', 25549),
(129014, 'esMX', 'Ah, allí estás, $ct. Creí que había activado las bombas demasiado pronto.', '', 25549),
(129013, 'esMX', 'Prepárate, $ct. ¡Te sacaré de allí y detonaré las bombas!', '', 25549),
(129012, 'esMX', 'Queda su nave de mando más fuerte. ¡Debemos destruirla antes de que caigan las defensas de Dalaran! El Consejo de la Cosecha Oscura ha preparado un portal para nosotros. Puedes hacer los honores, $n.', '', 25549),
(129011, 'esMX', '$n, las fuerzas del Comandante aterrador Arganoth están hacia el noreste. Debemos cerrar los portales antes de que arrasen con nuestros aliados.', '', 25549),
(129010, 'esMX', 'Parece que estabas condenado a fallar, Kalgorath.', '', 25549),
(129009, 'esMX', '¡Arqueros! ¡Acribíllenlos!', '', 25549),
(129008, 'esMX', '¿Los viste? Esos que andan paseando, conversando consigo mismos.', '¿Los viste? Esos que andan paseando, conversando consigo mismos.', 25549),
(129007, 'esMX', '¡Ah! Una nave menos.', '', 25549),
(129006, 'esMX', 'Dirígete a la colina del oeste con el resto de las fuerzas. Un eredar y sus súbditos vigilan la zona. Ya sabes qué hacer.', '', 25549),
(129005, 'esMX', '¡Bien! Creyeron que podrían con nosotros, ¡pero nunca han visto a las fuerzas de Azeroth trabajar tan unidas!', '', 25549),
(129004, 'esMX', 'Debemos tomar la playa antes de capturar las ruinas del oeste.', '', 25549),
(129003, 'esMX', '¡Hoy no ganará La Legión! Les mostraremos lo que significa estar unidos. ¡Por Azeroth!', '', 25549),
(129002, 'esMX', 'Debemos capturar las ruinas al oeste de la isla. Desde allí podemos concentrar todas nuestras fuerzas en la nave principal que está sobre la máquina de almas.', '', 25549),
(129001, 'esMX', '¡Necesito que encabeces a nuestras fuerzas mientras yo me encargo de estas naves!', '', 25549),
(129000, 'esMX', '$n, nuestro ataque a la playa sur se ha encontrado con una resistencia muy fuerte.', '', 25549),
(128999, 'esMX', '¡Rápido, $ct, te necesitamos al frente de la batalla!', '', 25549),
(128998, 'esMX', 'No. No creerás que... ¡Es imposible!', 'No. No creerás que... ¡Es imposible!', 25549),
(128997, 'esMX', 'Dividiremos nuestras fuerzas para atacarlos por distintos frentes a la vez.', '', 25549),
(128996, 'esMX', 'Me pregunto qué significa.', 'Me pregunto qué significa.', 25549),
(128995, 'esMX', '$GBienvenido:Bienvenida;, $ct. ¿Qué tal si empezamos con el ataque?', '', 25549),
(128994, 'esMX', 'Preferiría no responder más preguntas sobre lo que está pasando. Últimamente no confío demasiado en mis respuestas.', 'Preferiría no responder más preguntas sobre lo que está pasando. Últimamente no confío demasiado en mis respuestas.', 25549),
(128993, 'esMX', '¿Dónde estoy? ¿Quién eres?', '¿Dónde estoy? ¿Quién eres?', 25549),
(128992, 'esMX', '¿Qué... qué me sucedió?', '¿Qué... qué me sucedió?', 25549),
(128991, 'esMX', 'El agua... ¡no dejes que los demás beban el agua!', 'El agua... ¡no dejes que los demás beban el agua!', 25549),
(128990, 'esMX', 'Quería detenerme pero no podía... era como una marioneta.', 'Quería detenerme pero no podía... era como una marioneta.', 25549),
(128989, 'esMX', 'Se metieron en mi cabeza... ¡en mi mente!', 'Se metieron en mi cabeza... ¡en mi mente!', 25549),
(128988, 'esMX', 'No... no podía controlarme...', 'No... no podía controlarme...', 25549),
(128987, 'esMX', 'Muchas personas se comportan de forma extraña últimamente... Espero que no sea una enfermedad.', '', 25549),
(128986, 'esMX', 'No te ves muy bien. ¿Otro día difícil en los campos?', '', 25549),
(128985, 'esMX', 'No tienes buen color. ¿Te sientes bien?', '', 25549),
(128984, 'esMX', 'Estoy seguro de que el Consejo revelará más información cuando la tenga. Mientras tanto, recuerda que en tiempos como estos suele revelarse la verdadera naturaleza de las personas.', 'Estoy seguro de que el Consejo revelará más información cuando la tenga. Mientras tanto, recuerda que en tiempos como estos suele revelarse la verdadera naturaleza de las personas.', 25549),
(128983, 'esMX', 'Si perdemos la fe en el Consejo, las hebras de nuestra unión se desintegrarán. Debemos estar juntos, y no caer presos del temor por eventos que aún no han sucedido.', 'Si perdemos la fe en el Consejo, las hebras de nuestra unión se desintegrarán. Debemos estar juntos, y no caer presos del temor por eventos que aún no han sucedido.', 25549),
(128982, 'esMX', '', 'Apresúrate, Gran $Gmaestro:maestra;. ¡La supervivencia de la orden depende de ti!', 25549),
(128981, 'esMX', 'Has peleado bien, Clarividente $p. Veo que Thunderaan elige a sus campeones con sabiduría. Me someteré a su poder.', '', 25549),
(128980, 'esMX', '¿Y si este es el final?', '¿Y si este es el final?', 25549),
(128979, 'esMX', '¡NO! Tienes que escucharme. ¡Te digo que tenemos que salir de aquí!', '¡NO! Tienes que escucharme. ¡Te digo que tenemos que salir de aquí!', 25549),
(128978, 'esMX', 'Ah... Gran $Gmaestro:maestra;. Almai y Clara están esperándote en el poblado. Debo... descansar... un poco.', '', 25549),
(128977, 'esMX', 'Quién sabe. Lo primero que vi cuando levanté la vista fue esa monstruosidad que se erguía en la distancia.', 'Quién sabe. Lo primero que vi cuando levanté la vista fue esa monstruosidad que se erguía en la distancia.', 25549),
(128976, 'esMX', '...sí, pero algunos no saben qué esperar. Es muy importante predicar con el ejemplo, en especial en tiempos como estos.', '...sí, pero algunos no saben qué esperar. Es muy importante predicar con el ejemplo, en especial en tiempos como estos.', 25549),
(128975, 'esMX', 'Ya te lo dije, no sé de qué hablaban. Pero se veían... preocupados.', 'Ya te lo dije, no sé de qué hablaban. Pero se veían... preocupados.', 25549),
(128974, 'esMX', 'Estos Guardagrajos acaban de resucitar, y es posible que su corrupción no sea absoluta. ¡Quizás aún puedan salvarse!', '', 25549),
(128973, 'esMX', 'No sé muy bien qué estaba haciendo, pero su comportamiento era un poco... Bah. No me prestes atención. ¡Todo está bien!', 'No sé muy bien qué estaba haciendo, pero su comportamiento era un poco... Bah. No me prestes atención. ¡Todo está bien!', 25549),
(128972, 'esMX', 'No debes dejar que los rumores de los ociosos te afecten. En tiempos como estos debemos ser fuertes.', 'No debes dejar que los rumores de los ociosos te afecten. En tiempos como estos debemos ser fuertes.', 25549),
(128971, 'esMX', 'No permitas que el temor a un futuro incierto te abrume. Aún no sabemos qué nos espera.', 'No permitas que el temor a un futuro incierto te abrume. Aún no sabemos qué nos espera.', 25549),
(128970, 'esMX', 'Tienes razón. No sabemos qué nos espera. Pero si la oscuridad aparece, la enfrentaremos juntos.', 'Tienes razón. No sabemos qué nos espera. Pero si la oscuridad aparece, la enfrentaremos juntos.', 25549),
(128969, 'esMX', 'La luz de Dalaran brilla más resplandeciente que nunca, pero si la oscuridad se reúne, nuestros aliados estarán listos. Estoy seguro.', 'La luz de Dalaran brilla más resplandeciente que nunca, pero si la oscuridad se reúne, nuestros aliados estarán listos. Estoy seguro.', 25549),
(128968, 'esMX', 'Siento la energía profana que emana de ti. Revive al dragón y hazlo tu propiedad.', '', 25549),
(128967, 'esMX', 'Has robado la energía vital de los dragones. Ahora, úsala para satisfacer tus deseos. Corrómpela con tu oscuridad.', '', 25549),
(128966, 'esMX', 'Siento muchos no-muertos ferales cerca. Han estado alimentándose de su energía vital. Arrebátasela. Mátalos a todos.', '', 25549),
(128965, 'esMX', 'Estás acercándote. Siento la chispa de la vida delante de ti. Traerás la ruina a este lugar perdido.', '', 25549),
(128964, 'esMX', 'Claro que, si no logras sobrevivir, debes saber que yo me quedaré con Acherus. Arthas buscaba vengarse de la ciudadela, pero yo... yo tengo otros planes.', '', 25549),
(128963, 'esMX', 'Aquí es... puedo sentirlo. Tus suministros deben estar congelados. Siento no-muertos ferales enterrados en el hielo. Parece que ha llegado la hora de poner a prueba tu voluntad.', '', 25549),
(128961, 'esMX', 'Y aférrate a las riendas.', '', 25549),
(128960, 'esMX', 'Sigue hacia el norte, $GSeñor:Señora; de la muerte, hacia la ventisca.', '', 25549),
(128958, 'esMX', 'Vuela hacia el norte. Encuentra ese glaciar... y tu destino.', '', 25549),
(128957, 'esMX', 'Estás vacío por dentro, igual que yo.', '', 25549),
(128956, 'esMX', 'En algún lugar de este sagrario debe rondar un registro de su historia. Perdónale la vida a quien quieras, o mátalos a todos... tú decides.', '', 25549),
(128955, 'esMX', 'Ya ha alertado a sus aliados. Estarán esperándote.', '', 25549),
(128954, 'esMX', 'Los rojos saben algo. Esconden sus secretos en el Sagrario Rubí debajo de Reposo del Dragón.', '', 25549),
(128953, 'esMX', 'Encuentra a un miembro de los vuelo bronce, los guardianes de la historia. No tengas piedad.', '', 25549),
(128952, 'esMX', 'Mas todo lo que queda es el mar, y no percibo rastro de los no-muertos.', '', 25549),
(128951, 'esMX', 'Los huesos de un dragón de lo más antiguo y de un poder inimaginable.', '', 25549),
(128950, 'esMX', 'Mira más allá... ¿lo ves?', '', 25549),
(128949, 'esMX', 'Aquí fue donde vi a los no-muertos atravesar una placa de hielo cual manada, en busca de un premio que Arthas codiciaba.', '', 25549),
(128946, 'esMX', 'Ahora ve hacia el norte, lejos de Corona de Hielo, y te mostraré lo que he visto.', '', 25549),
(128945, 'esMX', 'Pero cuando extiendo las manos más allá de los fríos zarcillos de hielo interminable, no siento nada.', '', 25549),
(128944, 'esMX', 'He tenido una visión... miles de no-muertos marchando hacia los límites de Rasganorte en busca de un poder enorme.', '', 25549),
(128943, 'esMX', 'El Yelmo de Dominación me muestra muchas cosas, $GSeñor:Señora; de la muerte.', '', 25549),
(128942, 'esMX', '¿Erdris? ¿Tú también estás corrompido? Me apena ver que tu descanso eterno se haya visto interrumpido.', '', 25549),
(128941, 'esMX', '¡Muerte a todos los enemigos de la Legión!', '¡Muerte a todos los enemigos de la Legión!', 25549),
(128940, 'esMX', '¡Por la Legión!', '¡Por la Legión!', 25549),
(128939, 'esMX', '¿No lo ves? ¡La Legión ya ganó!', '¿No lo ves? ¡La Legión ya ganó!', 25549),
(128938, 'esMX', 'No tiene sentido... ¡estamos condenados! ¡Todos condenados!', 'No tiene sentido... ¡estamos condenados! ¡Todos condenados!', 25549),
(128937, 'esMX', '¡No puedes escapar de la Legión!', '¡No puedes escapar de la Legión!', 25549),
(128936, 'esMX', '¡Por mis amos! ¡Por la Legión!', '¡Por mis amos! ¡Por la Legión!', 25549),
(128935, 'esMX', 'Tan... cansado...', '', 25549),
(128932, 'esMX', '¡Por el Señor de la batalla!', '', 25549),
(128931, 'esMX', 'Bastión del Cielo.', 'Bastión del Cielo.', 25549),
(128930, 'esMX', 'Te acompañaré al Descanso del león.', 'Te acompañaré al Descanso del león.', 25549),
(128929, 'esMX', 'La hora de rezar ha terminado. Debo conocer los corazones y las mentes de mi pueblo.', '', 25549),
(128928, 'esMX', 'No tuviste suerte, ¿eh? El rey Cringris no estará feliz, pero no tengo dudas de que hiciste todo lo posible.', '', 25549),
(128927, 'esMX', 'Debo averiguarlo. ¡Sígueme hasta el castillo!', '', 25549),
(128926, 'esMX', '¡Ahora sí lo lograste! ¡ES HORA DE PELEAR!', '', 25549),
(128925, 'esMX', '¡Estás metiéndote con la voz del planeta! ¡DEL PLANETA!', '', 25549),
(128924, 'esMX', '¡Se me sube el magma a la cabeza!', '', 25549),
(128923, 'esMX', '¿Puedes dejar ya esas estupideces?', '', 25549),
(128922, 'esMX', '¡De vuelta al trabajo!', '', 25549),
(128921, 'esMX', '¡Por Azeroth!', '', 25549),
(128920, 'esMX', '¡Pelea por nuestro mundo!', '', 25549),
(128919, 'esMX', 'Estas piedras tienen historias que contar.', '', 25549),
(128918, 'esMX', '¡Un gusto!', '', 25549),
(128917, 'esMX', '¡Hablo por Azeroth!', '', 25549),
(128916, 'esMX', '¡Esbirro! Traga esto.', '', 25549),
(128915, 'esMX', '¡Ah! Mi hechizo de invocación de $Gcampeón: campeona; funcionó. ¡Esbirro! Debemos luchar contra otro de mis antiguos maestros más adelante. ¡Andando!', '', 25549),
(128914, 'esMX', '¡Fascinante! A pesar de la frecuencia con que invocamos elementales y demonios, jamás se me ocurrió que la puerta pudiera abrirse hacia ambos lados.', '', 25549),
(128913, 'esMX', '$GCampeón:Campeona;, hay una fuente de energía cerca de nuestro campamento que parece estar específicamente conectada contigo. ¿Podrías investigar de qué se trata?', '', 25549),
(128912, 'esMX', '', '¡Ey! ¡Mira todo este tesoro!', 25549),
(128911, 'esMX', '', '¡Ups! ¡Así que para eso sirve esa cosa! Ah, bueno...', 25549),
(128910, 'esMX', '¡Aaahhh! ¡¿Qué has hecho?! ¡Me has condenado a quedarme en este reino para siempre! ¡No podría imaginar un destino peor!', '', 25549),
(128909, 'esMX', '¡NO! ¡¿Cómo te atreves?! ¡No me arrodillaré ante esta criatura insignificante!', '', 25549),
(128908, 'esMX', '', 'El fragmento ancestral de vinculación comienza a irradiar un poder imponente.', 25549),
(128907, 'esMX', '¡Soy Iks''reeged, maestro del tesoro! Un segundo... ¿qué tienes ahí?', '', 25549),
(128906, 'esMX', '', 'Ah, hola. ¿Quién eres?', 25549),
(128905, 'esMX', '', '¡Ey, idiota! creo que este fragmento que me diste está roto. ¡Hasta traté de golpearlo con una roca y todo!', 25549),
(128904, 'esMX', 'No importa, ¡en un instante desapareceré con todos mis tesoros!', '', 25549),
(128903, 'esMX', '¡Maldito intruso! ¡¿Cómo encontraste mi guarida?!', '', 25549),
(128902, 'esMX', '¡Domatrax abre más portales viles!', '¡Domatrax abre más portales viles!', 25549),
(128901, 'esMX', '¡Ven, $Gpequeño campeón:pequeña campeona;! ¡Ahoguemos a nuestros enemigos bajo la ola de la justicia!', '', 25549),
(128900, 'esMX', 'Mis aguas están verdes de corrupción. Es hora usar un buen filtro.', '', 25549),
(128899, 'esMX', '¡Ahógate en la ola de la justicia!', '', 25549),
(128898, 'esMX', '¡No puedes enfrentarte a la marea!', '', 25549),
(128897, 'esMX', '¡Desaparece, maldito!', '', 25549),
(128896, 'esMX', '¡Te ahogaré!', '', 25549),
(128895, 'esMX', '¡Tus llamas se extinguen!', '', 25549),
(128894, 'esMX', '¡Que el Agua te purifique!', '', 25549),
(128893, 'esMX', '¡Ahógate en tu fracaso!', '', 25549),
(128892, 'esMX', 'Gracias, $Gcampeón:campeona;. ¡La situación se estaba poniendo un poco acalorada!', '', 25549),
(128891, 'esMX', 'Neptulon envió a uno de sus campeones más poderosos para que ayude en nuestra causa, y preguntó específicamente por ti. ¡Estoy ansioso por ver el gran escándalo que desatarán!', '', 25549),
(128890, 'esMX', '¡No! La Legión... destruirá... tu mundo...', '', 25549),
(128889, 'esMX', '¡Masacraré a todos tus preciados ancestros!', '', 25549),
(128888, 'esMX', '¡Una matanza verdaderamente gloriosa! ¡Sí que les demostraste a esas pestes acuosas quién manda!', '', 25549),
(128887, 'esMX', '¡$GHéroe:Heroína! Los naga y sus lacayos skrog han acosado a mis guerreros por demasiado tiempo. ¡Haz que paguen por sus crímenes!', '', 25549),
(128886, 'esMX', '$GArchimago:Archimaga;, ¡hay que liberar a los sables de maná vínculo vil del Bancal sollozante! Los abjuradores que los tienen son muy poderosos. Robar un hechizo a tiempo podría ser muy útil.', '', 25549),
(128885, 'esMX', 'Libraste una batalla admirable más temprano, apagaste las llamas del mal y ahogaste la voluntad de los demonios.$b$bLo hiciste bastante bien para estar tan dolorosamente seco.', '', 25549),
(128884, 'esMX', '', 'Te veré de regreso en la Arboleda de los Sueños, Archidruida. ¡Gracias por traerme!', 25549),
(128883, 'esMX', '¿Estoy... con vida? ¡Gracias, mi querido amigo! ¡Te lo agradezco!', '¿Estoy... con vida? ¡Gracias, mi querida amiga! ¡Te lo agradezco!', 25549),
(128882, 'esMX', '¡Tienes mi agradecimiento!', '¡Tienes mi agradecimiento!', 25549),
(128881, 'esMX', '¡No volveré a salir de Nar''thalas!', '¡No volveré a salir de Nar''thalas!', 25549),
(128880, 'esMX', '¡Gracias, héroe! ¡Creí que no saldría vivo de esta!', '¡Gracias, heroína! ¡Creí que no saldría vivo de esta!', 25549),
(128879, 'esMX', 'Me siento tan débil... Las telarañas estaban absorbiendo mi propia esencia.', 'Me siento tan débil... Las telarañas estaban absorbiendo mi propia esencia.', 25549),
(128878, 'esMX', '¡Gracias, forastero!', '¡Gracias, forastera!', 25549),
(128877, 'esMX', '', 'No... entienden...', 25549),
(128876, 'esMX', 'Regresaré a la Arboleda de los Sueños. ¡Gracias!', 'Regresaré a la Arboleda de los Sueños. ¡Gracias!', 25549),
(128875, 'esMX', 'Debemos detener al comandante. ¡Creo en ti!', 'Debemos detener al comandante. ¡Creo en ti!', 25549),
(128874, 'esMX', 'Gracias, Archidruida. Temí lo peor.', 'Gracias, Archidruida. Temí lo peor.', 25549),
(128872, 'esMX', 'No permitiré que suceda.', 'No permitiré que suceda.', 25549),
(128871, 'esMX', '¡Mortal! El gran Neptulon me ha enviado aquí para destruir a estos ineptos viles que osan invadir nuestro mundo.$b$bAcompáñame a la batalla y juntos lograremos apagar las llamas del mal.', '', 25549),
(128867, 'esMX', '', '¡Ese comandante probará el sabor amargo de mi acero!', 25549),
(128866, 'esMX', '¡Pronto el corazón de su mundo dejará de latir!', '', 25549),
(128862, 'esMX', 'Tu coraje se perderá.', '', 25549),
(128860, 'esMX', 'El dolor físico es fugaz. El verdadero tormento es eterno.', '', 25549),
(128859, 'esMX', '', '¡Hora de comer!', 25549),
(128858, 'esMX', '', '¡Vengan, hijas mías! ¡Aliméntense!', 25549),
(128857, 'esMX', '¡Mira el verdadero rostro de la muerte y sabrás que tu fin se acerca!', '', 25549),
(128854, 'esMX', '', 'Le saqué toda la información que necesitaba a este demonio antes de que llegaras. ¡Ya sé dónde está el comandante!', 25549),
(128845, 'esMX', 'Acompáñame a la plataforma de invocación. El ritual ya está preparado.', '', 25549),
(128843, 'esMX', '¡La Égida de Aggramar se ha agotado!', '', 25549),
(128842, 'esMX', 'Contengan a la bestia, yo me encargaré de invocarlos...', '', 25549),
(128841, 'esMX', '¡Mantén los cielos liberados! ¡De lo contrario, el conducto no caerá jamás!', '¡Mantén los cielos liberados! ¡De lo contrario, el conducto no caerá jamás!', 25549),
(128840, 'esMX', '¡Si el vínculo permanece intacto por mucho tiempo más, Azsuna estará perdida!', '¡Si el vínculo permanece intacto por mucho tiempo más, Azsuna estará perdida!', 25549),
(128839, 'esMX', 'Debemos controlar los cielos un poco más. No podemos fallar ahora.', 'Debemos controlar los cielos un poco más. No podemos fallar ahora.', 25549),
(128838, 'esMX', 'La energía que emana esta cosa es impresionante.', 'La energía que emana esta cosa es impresionante.', 25549),
(128837, 'esMX', '¡No te detengas hasta que hayas logrado interrumpir la conexión!', '¡No te detengas hasta que hayas logrado interrumpir la conexión!', 25549),
(128836, 'esMX', 'Concentra tus ataques. ¡Debemos interrumpir la conexión!', 'Concentra tus ataques. ¡Debemos interrumpir la conexión!', 25549),
(128835, 'esMX', '', '¡Ya oíste a Goldrinn! Tenemos que encontrar al responsable de estos ataques, ¡ahora! ¡No hay tiempo que perder!', 25549),
(128834, 'esMX', 'Debo encontrar un lugar seguro para recuperarme. ¡Tú debes averiguar quién está detrás de todo esto y acabar con su vida!', '', 25549),
(128833, 'esMX', 'Debí haber... ido a la escuela... un tiempo más...', '', 25549),
(128832, 'esMX', 'No... lo pensé... bien...', '', 25549),
(128831, 'esMX', '¡Para qué necesito leer cuando puedo pelear!', '', 25549),
(128830, 'esMX', '¡JA! ¿Quién es el listo ahora, eh?', '', 25549),
(128829, 'esMX', '¿Ya aprendiste la lección?', '', 25549),
(128828, 'esMX', '¡Estás muerto, baboso!', '', 25549),
(128827, 'esMX', '¡Leer es para tontos!', '', 25549),
(128826, 'esMX', '¡Vengan aquí!', '', 25549),
(128825, 'esMX', '¡Vengan a pelear!', '', 25549),
(128824, 'esMX', '¡Quédense quietos, cobardes!', '', 25549),
(128823, 'esMX', '¡LOS APLASTARÉ!', '', 25549),
(128822, 'esMX', 'Debo ir a la Costa Quebrada y ver el sacrificio que él hizo con mis propios ojos.', '', 25549),
(128821, 'esMX', '¡Los atropellaré, tontos!', '', 25549),
(128820, 'esMX', '¡Tontos insignificantes! ¿Se creen capaces de burlar a la Legión? ¡A ver si piensan un poco!', '', 25549),
(128819, 'esMX', 'Te lo agradezco. Ya sé lo que debo hacer para lidiar con el peso de la corona de mi padre.', '', 25549),
(128818, 'esMX', 'Mi final... estaba escrito... en mis anillos...', '', 25549),
(128817, 'esMX', 'Ahora yo... alimentaré... la tierra...', '', 25549),
(128816, 'esMX', 'Los mortales no saben apreciar la verdadera belleza.', '', 25549),
(128815, 'esMX', 'No mostraron el debido respeto por la naturaleza.', '', 25549),
(128814, 'esMX', '¡Comida para los gusanos!', '', 25549),
(128813, 'esMX', '¡Más abono para la plantas!', '', 25549),
(128812, 'esMX', '¡Perturbas la perfección de la naturaleza!', '', 25549),
(128811, 'esMX', '¡Este suelo ancestral no te pertenece!', '', 25549),
(128810, 'esMX', '¡Mis vides te atraparán!', '', 25549),
(128809, 'esMX', 'Un rey debe conocer el peso de las órdenes que imparte, debe saber cuál es su precio. Si una brújula puede romper su espíritu, ¿cómo reaccionará cuando la guerra llegue a nuestras puertas?', '', 25549),
(128808, 'esMX', '¡Exprimiré la vida de tu cuerpo!', '', 25549),
(128807, 'esMX', 'Necesitamos más que eso, y él también. Anduin no estuvo en la Costa Quebrada. No ha visto el sacrificio que hicieron sus soldados... el sacrificio que siguen haciendo.', '', 25549),
(128806, 'esMX', '¡Este será tu último aliento!', '', 25549),
(128805, 'esMX', '¡Tu garganta se cierra!', '', 25549),
(128804, 'esMX', 'Sí, mis preciosos. La energía vil ha revelado nuestra verdadera belleza.', '', 25549),
(128803, 'esMX', 'La Luz es fuerte en Anduin. Se volverá digno de su corona. Debemos tener fe.', '', 25549),
(128802, 'esMX', 'Las visiones no ganan guerras, profeta. El muchacho tiene un buen corazón, pero no ha demostrado su valía.', '', 25549),
(128801, 'esMX', 'El joven rey será un gran líder. Lo he previsto.', '', 25549),
(128800, 'esMX', 'Ya he oído la voz del pueblo, ¿pero qué piensan los consejeros de mi padre? Creo que no confían en mí tanto como en él.', '', 25549),
(128799, 'esMX', 'Mi pueblo tiene agrado por mí, me respetan... pero no creen en mí. No como creían en él.', '', 25549),
(128798, 'esMX', '¡Pobre alma! Y pensar que a mí me consideran cruel...', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128797, 'esMX', 'Desde que me devolviste la brújula de mi padre, le he rezado a la Luz para que me guíe y para que me asegure que su espíritu está en paz. La Luz no responde.', '', 25549),
(128796, 'esMX', '¡Pagarás por ese insulto!', '', 25549),
(128795, 'esMX', 'Todo mi trabajo... ¡arruinado!', '', 25549),
(128794, 'esMX', '¡Miren con cuánto empeño nos obedece esta alma!', '', 25549),
(128793, 'esMX', '¡Vean esto, mortales! ¡Las almas obedientes sirven a la Legión!', '', 25549),
(128792, 'esMX', 'Aún... hay más dolor… por venir.', '', 25549),
(128791, 'esMX', 'Esta derrota... me atormentará...', '', 25549),
(128790, 'esMX', '¡Fueron sus cuerpos los que se rindieron! ¡El triunfo me pertenece!', '', 25549),
(128789, 'esMX', 'Las mentes mortales se rompen tan fácilmente. Qué insatisfactorio.', '', 25549),
(128788, 'esMX', '¡Esa mente ya no resistió más!', '', 25549),
(128787, 'esMX', '¡Demasiado delicado para sobrevivir!', '', 25549),
(128786, 'esMX', '¡Qué voluntad tan débil!', '', 25549),
(128785, 'esMX', '¡Me perteneces!', '', 25549),
(128784, 'esMX', 'No puedo culparlo por su decisión. Mi padre sacrificó todo para salvar a su pueblo. Fue un gran rey.', '', 25549),
(128783, 'esMX', 'Sí, mi papá también dice eso. De acuerdo, soy el rey Varian. ¡Cuidado, demonios!', '', 25549),
(128782, 'esMX', '', 'No seas Anduin, ¡sé Varian! Él era mucho más fuerte.', 25549),
(128781, 'esMX', '¡Rueguen por la libertad, mortales!', '', 25549),
(128780, 'esMX', '¡Sus mentes no resistirán!', '', 25549),
(128779, 'esMX', '¡Soy el rey Anduin! ¡Mataré a todos los demonios que vea!', '', 25549),
(128778, 'esMX', '¡La resistencia solo lleva al dolor!', '', 25549),
(128777, 'esMX', '¡Su valentía arderá en llamas!', '', 25549),
(128776, 'esMX', '¿Por qué soportas este dolor? ¡Arrodíllate ante la Legión!', '', 25549),
(128775, 'esMX', '¡Ofrezco un respiro de la oscuridad! ¡Somete tu voluntad a mí!', '', 25549),
(128774, 'esMX', 'Nuestro sufrimiento... será... glorioso...', '', 25549),
(128773, 'esMX', 'El dolor... de fallarle... al amo...', '', 25549),
(128772, 'esMX', '¡Sus almas portarán el tormento de la derrota por toda la eternidad!', '', 25549),
(128771, 'esMX', 'La muerte fue una escapatoria demasiado fácil para ellos.', '', 25549),
(128770, 'esMX', '¿Demasiado para ti?', '', 25549),
(128769, 'esMX', '¡Frágil mortal!', '', 25549),
(128768, 'esMX', '¡Otro cuerpo destrozado!', '', 25549),
(128767, 'esMX', 'Hacen bien en tener miedo. Si no podemos detener a la Legión en la Costa Quebrada, los demonios atacarán nuestro hogar y a nuestras familias.', '', 25549),
(128766, 'esMX', 'Esto dolerá... ¡Lo juro!', '', 25549),
(128765, 'esMX', '¿Cuánto más podrán resistir?', '', 25549),
(128764, 'esMX', '¡Tu sufrimiento será legendario!', '', 25549),
(128763, 'esMX', '', 'Qué extraño, creí oír... No. Mi imaginación debe estar jugándome una mala pasada.', 25549),
(128762, 'esMX', '¡Aliméntenme con sus gritos!', '', 25549),
(128761, 'esMX', '¡Los cortaré en dos!', '', 25549),
(128760, 'esMX', 'Al menos estamos a salvo aquí en Ventormenta. El rey Wrynn protegerá la ciudad.', '', 25549),
(128759, 'esMX', '¡La agonía los atraviesa!', '', 25549),
(128758, 'esMX', '¡Dolor! ¡Dolor inimaginable!', '', 25549),
(128757, 'esMX', '', 'La semana pasada trajeron el cuerpo de mi primo de la Costa Quebrada. Supongo que vendrán muchos más.', 25549),
(128756, 'esMX', 'Antes de lo que esperaba, pero no importa. ¡Comencemos nuestro trabajo!', '', 25549),
(128755, 'esMX', '¡Bah! Fue el sufrimiento que yo le causé... ¡Alto! ¡Vienen los mortales! ¡Ese idiota de Goroth ha fallado de nuevo!', '', 25549),
(128754, 'esMX', '¿Dolor físico? ¡Bah! La angustia mental es la verdadera arma. ¿No fue esa la clave para convertir a Rakeesh?', '', 25549),
(128753, 'esMX', '¡Admite que tengo razón! Si rompes el cuerpo, el espíritu lo seguirá.', '', 25549),
(128752, 'esMX', '¡La Legión no se saldrá con la suya!', '¡La Legión no se saldrá con la suya!', 25549),
(128751, 'esMX', 'Deberías eliminar a estos diablillos rápido. No son las criaturas más fuertes, ¡pero pueden arrasar contigo si te descuidas!', '', 25549),
(128750, 'esMX', 'Despierta, Goldrinn.', 'Despierta, Goldrinn.', 25549),
(128749, 'esMX', '<Goldrinn duerme pacíficamente ahora que las energías viles han desaparecido.>', '', 25549),
(128748, 'esMX', 'Creo que conozco el hechizo indicado. Sígueme.', '', 25549),
(128747, 'esMX', 'Tendré que disfrazarme para recorrer la ciudad sin llamar la atención.', '', 25549),
(128746, 'esMX', 'El rey Cringris dijo que vendrías. Por favor, pasa.', '', 25549),
(128745, 'esMX', '', '¡Quieren... quieren corromper a Goldrinn! ¡Rápido, Archidruida!', 25549),
(128744, 'esMX', '', 'Por un tiempo, ningún demonio atravesará este portal.', 25549),
(128743, 'esMX', '', '¡Eso les enseñará!', 25549),
(128742, 'esMX', '', '¿Te imaginas a los demonios atravesando el portal solo para terminar enredados en las vides? ¡Un clásico!', 25549),
(128741, 'esMX', '', 'Los portales deben estar aquí, en algún lado... ¡Mantén los ojos abiertos!', 25549),
(128740, 'esMX', 'Entiendo la necesidad de hacer duelo, pero el lugar del rey es su trono. Debemos concentrarnos en la Costa Quebrada. ¡Convence a Anduin de que termine con su vigilia!', '', 25549),
(128739, 'esMX', 'Anduin se niega a comer y dormir. Ignora todos los ruegos de que regrese al palacio. Parece que nada de lo que le digo lo reconforta.', '', 25549),
(128738, 'esMX', '$GNuestro invitado:Nuestra invitada; ha llegado. Quizás ahora haya esperanzas de llegar al rey.', '', 25549),
(128737, 'esMX', 'Gracias por traer la brújula de mi padre de regreso. Es una forma de recordar cuánto lo extraño.', '', 25549),
(128736, 'esMX', 'Desde que esta guerra con la Legión comenzó, apenas he tenido tiempo para pensar... o para lamentarme. Quizá sea la hora de un cambio.', '', 25549),
(128735, 'esMX', 'Pedí que hicieran esta brújula para el cumpleaños de mi padre. Se la di unos meses antes de que mi barco se estrellara en Pandaria. Ya ha pasado una eternidad...', '', 25549),
(128734, 'esMX', '', '¡Vamos, avancemos! ¡Tenemos que salvar a Goldrinn!', 25549),
(128732, 'esMX', '', '¡Ayúdame! ¡Rápido!', 25549),
(128730, 'esMX', 'Oh, así que vienes por más, ¿eh? Bueno, espero que al menos dejes buenas propinas.', '', 25549),
(128729, 'esMX', '¿No te gusta el espectáculo? ¡Entonces puedes besarme el chispeante posterior encantado!', '', 25549),
(128728, 'esMX', 'Tu camino solo te lleva a la ruina. ¡Deja tus armas y arrodíllate ante tus amos!', '', 25549),
(128727, 'esMX', 'Llevará tiempo, pero gracias a tus obras, algún día la tierra se recuperará. ¡Buen trabajo!', '', 25549),
(128726, 'esMX', '¡Jaja! ¡Hasta nunca, archiperdedores!', '', 25549),
(128725, 'esMX', 'Presiento otra infestación de demonios cerca. ¡Cuento contigo para erradicarlos!', '', 25549),
(128724, 'esMX', 'Nos vemos, presdigiti-, em, prestititi... Ay, como se diga. ¡Olvídalo!', '', 25549),
(128723, 'esMX', '¡Bien! Buscaré mis cosas y nos alejaremos de estos tipos.', '', 25549),
(128722, 'esMX', 'Sujétate bien. Te sacaré de ahí.', '', 25549),
(128721, 'esMX', 'Uf, ¡estuvo cerca! Los conejos no son nada baratos, ¿sabes?', '', 25549),
(128720, 'esMX', '¡¿Cómo llegó un lobo hasta aquí?! No te quedes mirando, ¡a ver si matas a esa cosa!', '', 25549),
(128719, 'esMX', 'Muy bien, solo mete un poco las narices y trata de averiguar qué pasa con los conejos.', '', 25549),
(128718, 'esMX', '¡¿Qué?! ¿Cómo puede...?', '', 25549),
(128717, 'esMX', 'Toma, ahora inténtalo tú.', '', 25549),
(128716, 'esMX', 'Solo lo llenas de conejitos yyy, ¡bam!', '', 25549),
(128715, 'esMX', 'Bien, lo primero que tienes que hacer es conseguir un sombrero con un portal a una dimensión minúscula dentro.', '', 25549),
(128714, 'esMX', 'Regresa al Salón del guardián, y te daré alguna compensación por la molestia.', '', 25549),
(128713, 'esMX', 'Ya fueron suficientes pruebas. ¡Creo que es hora de empezar a pensar en producir!', '', 25549),
(128712, 'esMX', 'No te preocupes por nuestros sujetos de prueba. Seguramente ya están acostumbrados.', '', 25549),
(128711, 'esMX', '¡Ahora sí me gusta! ¡Mira cómo va!', '', 25549),
(128710, 'esMX', '¡Colega! ¡Tengo una propuesta para ti!', '', 25549),
(128709, 'esMX', 'Tuvimos muchos problemas para encontrar voluntarios con el coraje suficiente para entrar a este nido del mal. Si necesitas un par de zapatos nuevos después de pasar por esas telarañas, ¡tengo un contacto en Dalaran que puede ofrecerte un descuento!\n', '', 25549),
(128708, 'esMX', '¡Bien hecho! Mientras la sombra de la Legión cubra nuestro mundo, debemos mantenernos atentos.', '', 25549),
(128707, 'esMX', 'Siento una fuerza maligna en Bradensbrook. ¡Busca cualquier presencia de la Legión y destrúyela!', '', 25549),
(128706, 'esMX', 'Te voy a poner en una situación pegajosa, $Gcampeón:campeona;. Necesitamos la seda de las colonias de la Gruta Espeluznante para un encantamiento más bien complejo. ¿Podrías darnos una mano?', '', 25549),
(128705, 'esMX', 'Me he enfrentado a nagas malignos, espíritus furiosos y demonios insidiosos. Pero las arañas... ¡son insoportables!', '', 25549),
(128704, 'esMX', '', '¡No hay tiempo que perder, Archidruida! Estoy lista para apuñalar demonios.', 25549),
(128703, 'esMX', '', 'Oh... Aviana...', 25549),
(128702, 'esMX', 'Debes destruir todas las nidadas de huevos que encuentres. ¡Esta infestación no puede propagarse!', '', 25549),
(128701, 'esMX', '¡Arañas! De todos los demonios infernales que la Legión podía enviar a mi reino, ¿tenían que ser arañas?', '', 25549),
(128700, 'esMX', '', '¡Aviana!', 25549),
(128699, 'esMX', '', '¡Los que lastimen a mis hijos la pagarán!', 25549),
(128698, 'esMX', 'Vamos.', 'Vamos.', 25549),
(128697, 'esMX', '¡Voy por ustedes!', '', 25549),
(128690, 'esMX', '', 'Sujeto: Azeroth. Arritmia menor detectada, pero los signos vitales están dentro de los parámetros aceptables. Informes del incidente actualizados.', 25549),
(128689, 'esMX', '', 'Señales amenazantes neutralizadas. Defensas del complejo al 74.39 por ciento. Reparaciones en curso.', 25549),
(128688, 'esMX', 'Ninguna amenaza local detectada. Iniciando agradecimiento por ayuda.', '', 25549),
(128687, 'esMX', 'Amenaza neutralizada. Desplegando matriz de reparación.', '', 25549),
(128686, 'esMX', '', '¡Oh! Me encontré con él en Tel''anor, atrapado por una arpía y sin nada de ropa. ¡Ja!\n\nLa arpía estaba tan ocupada discutiendo con un alma en pena sobre quién tenía derecho a jugar primero con él, que nunca notaron mi presencia.\n\nSe veía muy incómodo, así que intervine. ¡Y el resto es historia!', 25549),
(128685, 'esMX', 'Sar...ger...as...', '', 25549),
(128684, 'esMX', '', 'Aviana, tus aves traen noticias de todo Azeroth. ¡Por favor, ayúdanos a encontrar el objetivo de los demonios! ¡Debemos vengar a nuestros caídos!', 25549),
(128683, 'esMX', '¿Cómo podemos ayudar?', '¿Cómo podemos ayudar?', 25549),
(128682, 'esMX', 'Cielos en llamas. Una espada... en la oscuridad... la herida... ardiendo...', '', 25549),
(128681, 'esMX', '', 'Y pensar que mis hermanos y hermanas murieron por una "distracción"... ¡No lo toleraré!', 25549),
(128680, 'esMX', '¿Cómo conociste a Aethas?', '¿Cómo conociste a Aethas?', 25549),
(128679, 'esMX', 'Arenas... empapadas de dolor. Ríos... ríos de sangre.', '', 25549),
(128678, 'esMX', '', 'Siempre creí que la magia era maravillosa en todas sus formas. Ahora que el escudo ha caído, ¡no puedo esperar a dominarlas todas!', 25549),
(128677, 'esMX', 'Sus sentimientos son un caos. Debo concentrarme, dejar que sus pensamientos fluyan en... ¡UNNGG!', '', 25549),
(128676, 'esMX', '', '¡Aviana! Tus hijos te necesitan. ¡La Legión está masacrando a los druidas de la Garfa!', 25549),
(128675, 'esMX', '¡El Titán oscuro está en camino! ¡Debemos detenerlo! Argus... el mundo de la Legión. Dice que nuestro destino está allí.', '', 25549),
(128674, 'esMX', '', 'Si mis ancestros supieran que estaba trabajando junto a $Gun forastero:una forastera;, me desterrarían... O algo peor.', 25549),
(128673, 'esMX', 'Háblame, amiga. Dime qué te tiene tan inquieta…', '', 25549),
(128672, 'esMX', '', 'Los shal''dorei han estado aislados por muchísimas generaciones. Es difícil abrir nuestras mentes a nuevas formas de pensar.', 25549),
(128671, 'esMX', 'Estos fantasmas deben ser sus sueños... sus pesadillas. Si la ayudamos a superar estos errores, Azeroth podrá transmitirnos su mensaje.', '', 25549),
(128670, 'esMX', '', 'No sé si esto funcionará, pero vale la pena intentarlo... ¡Atrás!', 25549),
(128669, 'esMX', '¡Algo activó las defensas! ¡Cuidado, tienes compañía!', '', 25549),
(128668, 'esMX', 'Últimamente parecía... afligida. Difícil de leer. Espero que puedas ayudarme a conectar con ella.', '', 25549),
(128667, 'esMX', 'Los titanes construyeron estos salones para velar por el alma del mundo. Desde esta cámara puedo oírla, claro como un diamante.', '', 25549),
(128666, 'esMX', 'Aquí tienes. Esta plataforma te llevará bajo tierra, a un lugar que ningún mortal ha pisado en milenios... ¡la Sala de Comunión! Bajemos, tengo mucho que enseñarte.', '', 25549),
(128665, 'esMX', 'Ah, te estás acercando. Ven al Mirador de los Creadores, en las alturas de las montañas del este. Te mostraré cómo entrar.', '', 25549),
(128664, 'esMX', '¡$GCampeón:Campeona;! Azeroth necesita nuestra ayuda.', '', 25549),
(128663, 'esMX', 'Estás CIEGO. TE FORZARÉ A ABRIR LOS OJOS.', '', 25549),
(128662, 'esMX', '¡Lo lograste! Las pesadillas están contenidas. Sigue avanzando, estoy en la cámara siguiente.', '', 25549),
(128661, 'esMX', 'Percibo sus miedos... sus dudas. ¡Tenemos que ayudarla! Parece que algunas defensas están desactivadas. Si las reactivas, ¡quizá puedas salvarla!', '', 25549),
(128660, 'esMX', 'Modo de autorreparación reanudado. Evaluación de asistencia externa: gracias.', '', 25549),
(128659, 'esMX', 'Secuencia de reactivación terminada. Iniciando protocolos de vigilancia.', '', 25549),
(128658, 'esMX', 'Anomalía detectada. Iniciando protocolo de defensa gama-zeta-fi-ómicron.', '', 25549),
(128657, 'esMX', '¡Ya basta! ¡Yo mismo acabaré con esto!', '', 25549),
(128656, 'esMX', 'Qué pena que Brann no vino contigo. ¡Nada le gusta más a mi hermano que abrir puertas de titanes!', '', 25549),
(128655, 'esMX', 'Búscame en la Cuenca de Sholazar de Rasganorte. Juntos, ¡llegaremos al fondo de todo esto!', '', 25549),
(128654, 'esMX', 'Está tratando de enviarme un mensaje... una advertencia, creo yo. Pero algo no está bien.', '', 25549),
(128653, 'esMX', 'Qué gusto verte, $n. Ahora que las pesadillas han desaparecido, podremos saber qué quiere decirnos. Esperamos tu orden para comenzar.', '', 25549),
(128652, 'esMX', '', 'Te veré más adelante.', 25549),
(128651, 'esMX', 'A decir verdad, la descubrí por accidente. Eh, bueno, ella me descubrió a mí.\n\nMe vi involucrado en una... situación... con una arpía y un alma en pena, y... Eh, no importa.\n\nComo sea, Ryanna me liberó con una impresionante demostración de magia. Y luego pidió unirse al Tirisgarde.\n\n¿Cómo iba a rechazarla?', '', 25549),
(128650, 'esMX', 'Cuéntame más sobre la Arcanista Ryanna.', 'Cuéntame más sobre la Arcanista Ryanna.', 25549),
(128649, 'esMX', '', '¡Un trabajo brillante! Parece que el contagio está controlado.', 25549),
(128648, 'esMX', '', 'Un contagio terrible ha consumido Alto de Muertobosque. Las arpías que infestan la isla son portadoras. ¡Su corrupción no debe propagarse!', 25549),
(128647, 'esMX', '', 'El contagio vil se ha esparcido hasta Alto de Muertobosque una vez más, $GSumo sacerdote:Suma sacerdotisa;. Debemos contener esta enfermedad antes de que infecte el continente.', 25549),
(128646, 'esMX', '¡Qué batalla! En cualquier momento esta nave explotará en pedazos. ¡No importa! ¡Una de nuestras águilas te llevará a salvo!', '', 25549),
(128645, 'esMX', 'Eso estuvo cerca. Gracias por la ayuda.', '', 25549),
(128644, 'esMX', '', 'Rápido, héroes. ¡Lasan necesita su ayuda!', 25549),
(128643, 'esMX', 'Je. ¿Esto es todo lo que el planeta tiene para ofrecer? Cuánta debilidad. Necesito un desafío de verdad.', '', 25549),
(128642, 'esMX', '', 'Los tramperos vilnato están usando su magia perversa sobre la vida silvestre de aquí. Toma este bálsamo de raíz de maná y úsalo en todos los animales heridos que encuentres. Rápido, ¡antes de que la corrupción se arraigue!', 25549),
(128641, 'esMX', '¡Arrgh!', '', 25549),
(128640, 'esMX', 'Tú encárgate de sabotear la nave de la Legión y de rescatar a nuestros aliados. ¡El comandante demoníaco es mío!', '', 25549),
(128639, 'esMX', 'Estas águilas de guerra nos llevarán a nuestro destino. ¿Todo listo? ¡Entonces, a volar!', '', 25549),
(128638, 'esMX', '', 'Una vez a bordo, rescaten a todos los cautivos que puedan. Cuando mi pueblo esté a salvo, coloquen los explosivos y salgan... ¡rápido!', 25549),
(128637, 'esMX', '', '¡Debemos seguir avanzando!', 25549),
(128636, 'esMX', '', '¡Cuidado!', 25549),
(128635, 'esMX', '', 'Entendido. Héroes, vayamos al punto de encuentro.', 25549),
(128634, 'esMX', 'Estamos listos para atacar la nave de la Legión. Mayla, campeones, reunámonos fuera de Tótem del Trueno. ¡Es hora de que paguen!', '', 25549),
(128633, 'esMX', '', 'Buen trabajo, héroes. Aunque solo se sellaron dos de los túneles, todo sirve.', 25549),
(128632, 'esMX', '', 'Héroes... encárguense de este... demonio...', 25549),
(128631, 'esMX', '', '¡Aagh!', 25549),
(128630, 'esMX', '', 'Uno de los geomantes de Navarrogg está sellando los túneles para cortar los refuerzos de la Legión. ¡Defiéndanlo, cueste lo que cueste!', 25549),
(128629, 'esMX', '¡Has traicionado a nuestro pueblo! ¡Te aliaste con estos adoradores de demonios!', '', 25549),
(128628, 'esMX', '', 'Campeones, la Legión quiere infiltrarse en Tótem del Trueno desde abajo. ¡Ayuden a repelerlos!', 25549),
(128627, 'esMX', '', 'Mis elegidos te ofrecen el don de la vida. ¡Reclama su premio y sigue peleando!', 25549),
(128626, 'esMX', '', 'Eres $Gun verdadero protector:una verdadera protectora; de la naturaleza. Tienes mi agradecimiento.', 25549),
(128625, 'esMX', '¡Están atacando Tótem del Trueno! Salvemos a nuestros camaradas antes de derribar esa nave demoníaca del cielo.', '', 25549),
(128624, 'esMX', '', '¡Aun con su líder muerto, estos tramperos vilnato no se detienen! Toma este bálsamo de raíz de maná y úsalo en todos los animales heridos que encuentres. ¡Salva a tantos como puedas!', 25549),
(128623, 'esMX', '', 'El Paso Fuego Vil está repleto de ocultistas leales a la Legión Ardiente. ¡No podemos permitir que controlen una posición!', 25549),
(128622, 'esMX', '', '¡Vaya demostración de poder! ¡Seguramente esos ocultistas están arrepentidos de aliarse con nuestro enemigo!', 25549),
(128621, 'esMX', '', 'Aunque Kanrethad regresó con nosotros, estos ocultistas siguen siendo leales a la Legión. No podemos permitirles que recuperen el control del Paso Fuego Vil. ¡Diezma sus filas y absorbe sus fuentes de poder!', 25549),
(128620, 'esMX', 'La poderosa Legión ha atacado, y apenas podemos resistir su asedio.', '', 25549),
(128619, 'esMX', 'Continúa.', 'Continúa.', 25549),
(128618, 'esMX', 'El saboteador era de la Horda, uno de mis propios atracasoles, de hecho.\n\nAlgunos del Consejo siempre se opusieron fervientemente a autorizarnos a regresar al Kirin Tor. Como te imaginarás, esto les dará todas las municiones que necesitan para convencerlos de que nos expulsen una vez más.\n\nY si eso sucede, nuestra tregua quedará hecha pedazos y Azeroth caerá en las garras de la Legión.', '', 25549),
(128617, 'esMX', 'Tienes órdenes de presentarte en el campo de batalla de inmediato. ¡Destruye a los demonios que están diezmando nuestras filas!', '', 25549),
(128616, 'esMX', '¿Cómo pudo la Legión acceder a las armas de Dalaran?', '¿Cómo pudo la Legión acceder a las armas de Dalaran?', 25549),
(128615, 'esMX', 'Parece que nuestros aliados se las arreglaron para repeler el ataque... mantente alerta.', '', 25549),
(128614, 'esMX', 'Descubrimos el cadáver del saboteador cerca del arsenal. Le habían drenado el alma... Uf, qué forma terrible de morir.\n\nMe temo que la situación es peor de lo que esperaba.', '', 25549),
(128613, 'esMX', '', 'Si esto era solo una distracción, ¿dónde es el ataque principal? Preguntémosle a Aviana. ¡Ella debe saber!', 25549),
(128612, 'esMX', 'Yo me dejé llevar por las sombras... No hagas lo mismo.', '', 25549),
(128611, 'esMX', 'Nunca serás un mago de verdad con ese atuendo.', '', 25549),
(128610, 'esMX', '¿Aprendices..? ¿Aprendiccise..? ¿Aprendicci...? Sí, ese suena bien...', '', 25549),
(128609, 'esMX', 'Un segundo... ¿me dejé la Prueba de fuego encendida? Estoy bastante seguro de que la apagué...', '', 25549),
(128608, 'esMX', 'No dejes de estudiar.', '', 25549),
(128607, 'esMX', 'Un momento, ¿y tú quién eras?', '', 25549),
(128606, 'esMX', 'Ve y haz... ¡algo!', '', 25549),
(128605, 'esMX', '¡Trata de no morir ahora!', '', 25549),
(128604, 'esMX', '¿Estoy aquí... o soy una ilusión?', '', 25549),
(128603, 'esMX', '¿Te gustan las... pruebas?', '', 25549),
(128602, 'esMX', 'Nunca está de más tener otro aprendiz.', '', 25549),
(128601, 'esMX', 'Saludos.', '', 25549),
(128600, 'esMX', 'Solo soy uno de los muchos que han tomado una lanza por Azeroth.', '', 25549),
(128599, 'esMX', 'Durante nuestro tiempo juntos, mi hermano y yo hemos sido testigos de muchas guerras y pruebas.', '', 25549),
(128598, 'esMX', 'Ten cuidado con los dragones. ¡No confíes en ellos!', '', 25549),
(128597, 'esMX', '¡Azotaré a nuestros enemigos!', '', 25549),
(128596, 'esMX', 'Mi escudo es tuyo.', '', 25549),
(128595, 'esMX', 'Protegeré el reino.', '', 25549),
(128594, 'esMX', 'Que la Luz te dé fuerzas.', '', 25549),
(128593, 'esMX', '¿En qué puedo ayudar?', '', 25549),
(128592, 'esMX', 'Que la Luz te bendiga, $Gviajero:viajera;.', '', 25549),
(128591, 'esMX', 'Saludos, $gaventurero:aventurera;.', '', 25549),
(128590, 'esMX', 'Hola.', '', 25549),
(128589, 'esMX', '', 'Una lanza de fuego vil podría serme muy útil en este momento...', 25549),
(128588, 'esMX', '', '¿Sabes? Creo que me vería bien de verde...', 25549),
(128587, 'esMX', '', '¡Ni siquiera la Legión ha sido tan irritante!', 25549),
(128586, 'esMX', '', 'Mi linaje no se caracteriza por su temperamento pacífico.', 25549),
(128585, 'esMX', '', 'Tal vez mi padre tenía razón sobre ti.', 25549),
(128584, 'esMX', '', 'Detente. Ahora.', 25549),
(128583, 'esMX', '', 'Ya no me perseguirán.', 25549),
(128582, 'esMX', '', 'Pelea con honor, $Gforastero:forastera;', 25549),
(128581, 'esMX', '', 'Que los dioses te acompañen.', 25549),
(128580, 'esMX', '', 'Nunca flaquearé.', 25549),
(128579, 'esMX', '', 'Mi voluntad es implacable.', 25549),
(128578, 'esMX', '', 'Mi escudo está listo.', 25549),
(128577, 'esMX', '', '¿Cuál es tu propósito?', 25549),
(128576, 'esMX', '', 'Saludos, $Gforastero:forastera;.', 25549),
(128575, 'esMX', '', 'Druidas imbéciles... ¡nuestra distracción ha funcionado!', 25549),
(128574, 'esMX', '¿Por qué nunca puedo quedarme con el corcel nefasto?', '', 25549),
(128573, 'esMX', '¿No deberías estar reuniendo materiales o algo?', '', 25549),
(128572, 'esMX', '¿Me has traído más sangre?', '', 25549),
(128571, 'esMX', 'Que las pezuñas viles te den velocidad.', '', 25549),
(128570, 'esMX', 'Los demonios nos obedecerán.', '', 25549),
(128569, 'esMX', 'Xoroth llama.', '', 25549),
(128568, 'esMX', 'Los corceles nefastos serán nuestros.', '', 25549),
(128567, 'esMX', '¿Qué invocaremos hoy?', '', 25549),
(128566, 'esMX', '¿Requieres mis servicios?', '', 25549),
(128565, 'esMX', '¿Qué necesitas conjurar?', '', 25549),
(128564, 'esMX', '¿Sí?', '', 25549),
(128563, 'esMX', '', '¡Vete a las profundidades oscuras del infierno!', 25549),
(128562, 'esMX', '', '¡Vamos, Archidruida! ¡Mi pueblo necesita nuestra ayuda!', 25549),
(128561, 'esMX', 'Bien hecho. Veámonos cerca de la torre de Lady Remor''za y yo invocaré un portal.', '', 25549),
(128560, 'esMX', 'Recuerda, ¡no te acerques a la Piedra de alma natonocturno mientras absorbe energía!', '', 25549),
(128559, 'esMX', '', 'Este mago te teletransportará hasta nosotros. La tarea que nos espera no será fácil. ¡Prepárate!', 25549),
(128558, 'esMX', '', 'Cuando llegues, reabriremos el portal al dominio del demonio y acabaremos con él... ¡de una vez por todas!', 25549),
(128557, 'esMX', '', 'El Profeta ha preparado sus encantamientos, y yo he meditado lo suficiente. Kruul debe morir.', 25549),
(128556, 'esMX', 'He informado mi ubicación a tus magos. Una vez que llegues, entraremos en la caverna de Tugar y neutralizaremos su amenaza.', '', 25549),
(128555, 'esMX', 'Debemos acabar con él y su repugnante mascota antes de que ataquen Tótem del Trueno. Esto no será fácil.', '', 25549),
(128554, 'esMX', 'Tugar Tótem de sangre ha reaparecido en Altamontaña. Y está acompañado por un gusano gigante saturado de energía vil.', '', 25549),
(128553, 'esMX', 'Vamos, $n. Es hora de acabar con Erdris... de una vez por todas.', '', 25549),
(128552, 'esMX', 'Un par de los guerreros más feroces de Bradensbrook han insistido en unirse a nuestra campaña. Pero aun con su ayuda, la batalla que nos espera será un desafío.', '', 25549),
(128551, 'esMX', 'Ya es hora. He encontrado a Erdris Espina en la cima del Fuerte Torre Oscura, ¡y planea levantar un ejército no-muerto!', '', 25549),
(128550, 'esMX', '', 'Nos reuniremos en el Salón del guardián, $GArchimago:Archimago; $n.', 25549),
(128549, 'esMX', 'Dime, ¿tienes ganas de sentir el extremo afilado de mi espada?', '', 25549),
(128548, 'esMX', 'Soy Maximillian de Villanorte, virtuoso rescatista de damiselas. ¡Cómo te atreves!', '', 25549),
(128547, 'esMX', '¿Acaso sabes con quién estás hablando?', '', 25549),
(128546, 'esMX', 'Hasta luego.', '', 25549),
(128545, 'esMX', '¡Vete! ¡Tengo dragones que matar!', '', 25549),
(128544, 'esMX', 'Muy bien.', '', 25549),
(128543, 'esMX', '¿Cómo puedo servirte?', '', 25549),
(128542, 'esMX', '¿Sí?', '', 25549),
(128541, 'esMX', '¿Qué tal?', '', 25549),
(128540, 'esMX', '¡Cabalguemos!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128539, 'esMX', '¡Juntos, asesinaremos a muchas bestias!', '', 25549),
(128538, 'esMX', '¿Qué tal?', '', 25549),
(128537, 'esMX', '¡Ey, hola de nuevo, $Gescudero:escudera;!', '', 25549),
(128536, 'esMX', '¡Con mi fuerza le pongo fin a tu vida!', '', 25549),
(128535, 'esMX', '¡Por Doloria!', '', 25549),
(128534, 'esMX', '¡Qué dragón más extraño! ¡No importa!', '', 25549),
(128533, 'esMX', '¡Excaliberto! ¡Ataca!', '', 25549),
(128532, 'esMX', '¡Te acabaré con mi grandiosa espada!', '', 25549),
(128531, 'esMX', 'Bueno, eso fue fácil.', '', 25549),
(128530, 'esMX', '¡Otro enemigo cae ante mis ataques fulminantes!', '', 25549),
(128529, 'esMX', '¿Te enteraste de mi victoria, $Gescudero:escudera;?', '', 25549),
(128528, 'esMX', 'Necesito... un descanso.', '', 25549),
(128527, 'esMX', '¡Ayúdame!', '', 25549),
(128526, 'esMX', 'Encárgate de este, $Gescudero:escudera;.', '', 25549),
(128525, 'esMX', 'No te preocupes por mí, $GGran maestro:Gran maestra;. Me acordé de traer mis pociones de respiración acuática.', '', 25549),
(128524, 'esMX', 'Ah, un chapuzón refrescante... Me recuerda a aquella vez que me nadé todo el camino hasta Kezan. ¡El Gran maestro Rochu no estaba muy feliz cuando vio lo arrugadas que tenía las patas!', '', 25549),
(128523, 'esMX', '¿Alguna vez te conté la historia del hozen y la tarta de crema? Mmm... Tal vez sea mejor guardarla para otra ocasión.', '', 25549),
(128522, 'esMX', 'El maestro cervecero sabio reconoce la importancia de tomar una bebida... y la importancia de detenerse antes de que la bebida tome esa decisión por él.', '', 25549),
(128521, 'esMX', 'No te preocupes por el fracaso, $GGran maestro:Gran maestra;. Concéntrate, en cambio, en levantarte cada vez que caes.', '', 25549),
(128520, 'esMX', 'El mejor momento para plantar un árbol es hace cincuenta años. El segundo mejor momento es ahora.', '', 25549),
(128519, 'esMX', 'El monje sabio elige su propio estilo, en lugar de dejar que la opinión popular se imponga sobre él.', '', 25549),
(128518, 'esMX', 'Las cometas no vuelan si el viento no sopla, $GGran maestro:Gran maestra;.', '', 25549),
(128517, 'esMX', 'Hablar de cambios sin intenciones de actuar es igual a cavar un agujero para atrapar un dragón nimbo.', '', 25549),
(128516, 'esMX', '¡Recuerda terminar de cruzar el río antes de decirle al crocolisco que tiene mal aliento!', '', 25549),
(128515, 'esMX', '¿Falta mucho, $GGran maestro:Gran maestra;?', '', 25549),
(128514, 'esMX', 'La pereza no suele preceder al éxito, $GGran maestro:Gran maestra;.', '', 25549),
(128513, 'esMX', 'Escucha todas las voces, $GGran maestro:Gran maestra;. Si solo te rodeas de los que concuerdan contigo, tus pensamientos nunca madurarán.', '', 25549),
(128512, 'esMX', 'El yak perezoso nunca se baña.', '', 25549),
(128511, 'esMX', '¡Hasta pronto!', '', 25549),
(128510, 'esMX', '¡Buena suerte, $GGran maestro:Gran maestra;!', '', 25549),
(128509, 'esMX', 'Quizás deberías ser más $Gdiscreto:discreta; con los panecillos de maná, $GGran maestro:Gran maestra;...', '', 25549),
(128508, 'esMX', 'Qué bueno verte de nuevo, $GGran maestro:Gran maestra;.', '', 25549),
(128507, 'esMX', '¿A dónde iremos hoy, $GGran maestro:Gran maestra;?', '', 25549),
(128506, 'esMX', '', 'Estoy lista para llevarte a los Salones del valor. Ven a hablar conmigo cuando hayas reunido a tus aliados y estés $Glisto:lista;.', 25549),
(128505, 'esMX', '¡Tenemos que rendirnos! ¡La fuerza de la Legión nos destruirá!', '', 25549),
(128504, 'esMX', '¡No nos detendrán!', '', 25549),
(128503, 'esMX', 'Regresemos a la Isla Errante... ¡juntos!', '', 25549),
(128502, 'esMX', '¡Tus habilidades son verdaderamente impresionantes! Sería un honor servirte, tal como serví a los anteriores grandes líderes de nuestra orden.', '', 25549),
(128501, 'esMX', 'Claramente eres la personificación de la sabiduría, la integridad y la tenacidad de un Gran maestro. Falta una sola prueba... ¡Demuéstrame que puedes luchar como un Gran maestro!', '', 25549),
(128500, 'esMX', 'Has demostrado paciencia con el Maestro Bu, honor con los grúmel, deber con el Shadopan, y fe con los jinyu.', '', 25549),
(128499, 'esMX', 'Pero en el medio de mi meditación, vi que apareció algo nuevo e interesante... tú.', '', 25549),
(128498, 'esMX', 'Entristecido por la muerte del gran maestro Cenit, vagué por Pandaria para reflexionar.', '', 25549),
(128497, 'esMX', '¿Nada? ¿Revisaste bien? Quizá debas prestar más atención, Gran $Gmaestro:maestra;...', '', 25549),
(128496, 'esMX', '¡$GGran maestro:Gran maestra;! ¿Has encontrado a Ban-Lu?', '', 25549),
(128495, 'esMX', 'Tengo una idea, $GGran maestro:Gran maestra;...', '', 25549),
(128494, 'esMX', 'Parece que hemos llegado a un camino sin salida. Meditaré un momento sobre este enigma.', '', 25549),
(128493, 'esMX', '¿Proseguimos con la búsqueda de Ban-Lu, $GGran maestro:Gran maestra;?', '', 25549),
(128492, 'esMX', '¿A dónde fuiste? Espera allí. Gracias por tener paciencia con este anciano.', '', 25549),
(128491, 'esMX', '¿Podrías desacelerar el paso un momento? Te pido disculpas por mi lentitud.', '', 25549),
(128490, 'esMX', '¡Espérame, por favor! Estos viejos huesos ya no responden como antes.', '', 25549),
(128489, 'esMX', '¡Fiu! Un viaje emocionante, pero agotador. Permíteme descansar un momento. Tal vez puedas preguntarles a estos grúmel si han visto a Ban-Lu.', '', 25549),
(128488, 'esMX', '¡Un rastro de zarpas! Mmm, ¿a dónde llevarán?', '', 25549),
(128487, 'esMX', '¿Qué encontraste? Déjame ver...', '', 25549),
(128486, 'esMX', 'Busca cualquier señal que pueda guiarnos hasta Ban-Lu.', '', 25549),
(128485, 'esMX', '¡$GGran maestro:Gran maestra;! Por aquí.', '', 25549),
(128484, 'esMX', 'Tal vez si regresamos allí, encontraremos pistas sobre su paradero.', '', 25549),
(128483, 'esMX', 'Pero nadie ha visto a Ban-Lu desde el ataque de la Legión al Pico de la Serenidad. Parece que la pérdida de vidas... lo afectó profundamente.', '', 25549),
(128482, 'esMX', 'Durante siglos, Ban-Lu sirvió como la montura personal de cada gran maestro. ¡Era un deber que cumplía con honor!', '', 25549),
(128481, 'esMX', 'Xuen, el Tigre blanco, uno de los Augustos Celestiales, tenía un hijo llamado Ban-Lu.', '', 25549),
(128480, 'esMX', '¡$GGran maestro:Gran maestra;! ¿Tienes un momento para escuchar el relato de un anciano?', '', 25549),
(128479, 'esMX', '', 'Después de esa noche, estaba sola. La última descendiente de mi linaje.', 25549),
(128478, 'esMX', '', 'Me reconforta saber que los dioses los juzgarán cuando llegue su hora.', 25549),
(128477, 'esMX', '', 'Pero no tiene caso. Siempre logran escaparse de mí. Debo concentrarme en la tarea que me toca.', 25549),
(128476, 'esMX', '', '¡Otra emboscada! ¡Prepara tu acero!', 25549),
(128475, 'esMX', '', '¡Basura cobarde! Los cazaría a todos y a sus amos también, si supiera quién los envió.', 25549),
(128474, 'esMX', '', 'Nunca olvidaré la noche en que vinieron. Mi madre cayó ante mis ojos, y ya se habían encargado de mi hermano antes de que yo pudiera escapar.', 25549),
(128473, 'esMX', '', 'Parece que escapar de mi pasado era un anhelo demasiado grande.', 25549),
(128472, 'esMX', '', 'Te lo advierto: es posible que sigan al acecho.', 25549),
(128471, 'esMX', '', 'Pasé mis últimos momentos aquí escapando de las garras de asesinos enviados a acabar con mi familia.', 25549),
(128470, 'esMX', '', '¡Hay movimiento en los árboles! ¡Cuidado!', 25549),
(128469, 'esMX', '', 'Nos reuniremos en Valdisdall en Stormheim. Deberíamos poder llegar a Skold-Ashil desde allí.', 25549),
(128468, 'esMX', '¡Ha sido un honor pelear a tu lado, $GSeñor:Señora; de la batalla $n! Me presentaré en el Bastión del Cielo. ¡Te veré ahí!', '', 25549),
(128467, 'esMX', '<Disfrutar de la noche y despertar en Recinto del Disparo Certero.>', '<Disfrutar de la noche y despertar en Recinto del Disparo Certero.>', 25549),
(128466, 'esMX', '¡Vaya cacería! Este es el verdadero espíritu de la naturaleza. ¡Disfrutemos de esta noche y dejemos nuestras preocupaciones para mañana!', '', 25549),
(128465, 'esMX', '%s grazna con fuerza cuando te acercas.', '', 25549),
(128464, 'esMX', 'Conserva la calma, Aviash. $n está de nuestro lado.', '', 25549),
(128463, 'esMX', '', 'El destino de los Marvilis está en tus manos. ¡Que los dioses te acompañen, $Gforastero:forastera;!', 25549),
(128462, 'esMX', '', 'Tu Kirin Tor ha encontrado la manera de llevarte hacia los salones de Odyn. ¡Apresúrate! ¡Tenemos que hacer que Sigryn entre en razón antes de que sea demasiado tarde!', 25549),
(128461, 'esMX', '', '¡$GForastero:Forastera;! Sigryn ha atormentado los Salones del valor y está decidida a enfrentarse a Odyn. ¡La ira cegó su razón y se dirige directo a su muerte!', 25549),
(128460, 'esMX', '', 'Bueno, también debe tener orígenes natonocturno para lograr un matrimonio tan armonioso. Oh, y debe estar recién forjado, sin uso previo. Cualquier otra cosa terminará en desastre. \n\nSi los rumores son ciertos, quizás Aethas pueda ayudarte. ¡Dicen que tiene una hermosa natonocturno como aprendiz! Es todo un escándalo.\n\nDeberías pedirle que te la presente.', 25549),
(128459, 'esMX', '¿Dónde podría encontrar algo así?', '¿Dónde podría encontrar algo así?', 25549),
(128458, 'esMX', '', '¡Él se alzará! reinará...', 25549),
(128457, 'esMX', '', '¡Mi vigilia termina! No permitas... que el oscuro... despierte...', 25549),
(128456, 'esMX', '', '¡La esperanza de tu mundo muere contigo!', 25549),
(128455, 'esMX', '', 'Mi vigilia continúa. Pero... ¿a quién sirvo?', 25549),
(128454, 'esMX', '', '¡La carne es débil!', 25549),
(128453, 'esMX', '', 'Un final necesario.', 25549),
(128452, 'esMX', '', '¡No interrumpirás los planes del amo!', 25549),
(128451, 'esMX', '', '¡Lo que yace abajo no es para ojos mortales!', 25549),
(128450, 'esMX', '', 'El objeto inamovible se encontró con la fuerza irresistible, y descubrí... un nuevo llamado.', 25549),
(128449, 'esMX', '', 'Durante milenios mi vigilia fue constante... inquebrantable. Y luego esta voz me llamó.', 25549),
(128448, 'esMX', '', 'No fui la primera en colocar defensas en este templo. Pero temo que el vigía anciano encargado de proteger este lugar... haya sufrido daños. Ten cuidado. Te protegeré cuanto pueda.', 25549),
(128447, 'esMX', '', '¡Acaben conmigo, mortales! ¡Y arrebátenle su premio al Falsario!', 25549),
(128446, 'esMX', '', 'Este cuerpo... mi mente... no resistieron. ¡Les he fallado a los creadores!', 25549),
(128444, 'esMX', 'Estoy listo para asistir al festín', 'Estoy lista para asistir al festín', 25549),
(128443, 'esMX', '', 'Odyn y sus mejores cazadores te esperan en los Campos de la Cacería Eterna.', 25549),
(128442, 'esMX', '$GBienvenido:Bienvenida; a Cornisa Alavil, $GDestripador:Destripadora; $p. La Madre Matrona está esperándote en el área de entrenamiento, al oeste.', '', 25549),
(128441, 'esMX', '', '(UNUSED)Tu visión demoníaca será útil para seguir su rastro de sangre.(UNUSED)', 25549),
(128440, 'esMX', '¡Bien hecho! ¡Nuestro mundo nunca caerá mientras haya campeones como tú para defenderlo!', '', 25549),
(128439, 'esMX', 'Saludos, adalid. ¿Estás aquí para responder al llamado de Odyn?', '', 25549),
(128438, 'esMX', '¡La furia de la tormenta arde en mi interior! ¿Terminaste con tus preparativos?', '', 25549),
(128437, 'esMX', '¡Contempla la velocidad de mi hacha!', '', 25549),
(128436, 'esMX', '', '¡El poder de la sangre de mi padre fluye a través de mí!', 25549),
(128435, 'esMX', 'Avísame cuando hayas terminado de perpararte y emprenderemos el vuelo.', '', 25549),
(128434, 'esMX', 'Una peste demoníaca corrompe esta tierra, $Gcampeón:campeona;. ¡Debemos erradicarla!', '', 25549),
(128433, 'esMX', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t¡%s canaliza |cFFFF0000|Hspell:237945|h[Sangre del padre]|h|r!', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t¡%s canaliza |cFFFF0000|Hspell:237945|h[Sangre del padre]|h|r!', 25549),
(128432, 'esMX', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|tVarias |cFFFF0000|Hspell:237908|h[Runas]|h|r aparecen en el terreno cercano.', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|tVarias |cFFFF0000|Hspell:237908|h[Runas]|h|r aparecen en el terreno cercano.', 25549),
(128431, 'esMX', '|TInterface\\Icons\\ABILITY_WHIRLWIND.BLP:20|t¡%s crea una |cFFFF0000|Hspell:237866|h[Filotormenta]|h|r!', '|TInterface\\Icons\\ABILITY_WHIRLWIND.BLP:20|t¡%s crea una |cFFFF0000|Hspell:237866|h[Filotormenta]|h|r!', 25549),
(128430, 'esMX', '|TInterface\\Icons\\ABILITY_WARRIOR_RAMPAGE.BLP:20|t¡%s obtiene |cFFFF0000|Hspell:237947|h[Ira rabiosa]|h|r!', '|TInterface\\Icons\\ABILITY_WARRIOR_RAMPAGE.BLP:20|t¡%s obtiene |cFFFF0000|Hspell:237947|h[Ira rabiosa]|h|r!', 25549),
(128429, 'esMX', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s comienza a lanzar |cFFFF0000|Hspell:237952|h[Conocimiento ancestral]|h|r!', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s comienza a lanzar |cFFFF0000|Hspell:237952|h[Conocimiento ancestral]|h|r!', 25549),
(128428, 'esMX', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_SVALASORROWGRAVE.BLP:20|t¡Varias Val''kyr oscuras forman filas para |cFFFF0000|Hspell:237761|h[cargar]|h|r por el campo de batalla!', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_SVALASORROWGRAVE.BLP:20|t¡Varias Val''kyr oscuras forman filas para |cFFFF0000|Hspell:237761|h[cargar]|h|r por el campo de batalla!', 25549),
(128427, 'esMX', '¡Los drekirjar nunca se rinden!', '', 25549),
(128426, 'esMX', '¡Tengo el poder de mis ancestros!', '', 25549),
(128425, 'esMX', '', '¡Tantos tesoros! ¡Y todos para mí!', 25549),
(128424, 'esMX', '', '¡Yo lidero a las legiones, mortal!', 25549),
(128423, 'esMX', 'Estoy listo para empezar.', 'Estoy lista para empezar.', 25549),
(128422, 'esMX', 'Puede que la Legión trate de debilitarnos, de desgastar a nuestros aliados como valles inundados después de una tormenta; pero nunca nos rendiremos. Nuestra sangre nos impulsa a luchar hasta que el sol brille sobre nosotros una vez más.', '', 25549),
(128421, 'esMX', 'Debes estudiar estas runas con detenimiento, $c. ¡No quiero imaginar lo que podría pasar si fallamos!', '', 25549),
(128418, 'esMX', '', 'Te veré allí. ¡Debemos apurarnos, o será demasiado tarde!', 25549),
(128417, 'esMX', '', '¡Archidruida! ¡Necesito tu ayuda!', 25549),
(128416, 'esMX', '', 'Los amigos del Kirin Tor pueden abrir un portal temporal a su ubicación. Debes poner fin a la locura de Xylem... pero por favor, ¡trata de perdonarle la vida!', 25549),
(128415, 'esMX', '', 'Desde ese lugar, Xylem podría usar el Iris de enfoque para provocar un caos en las líneas Ley de Azeroth.', 25549),
(128414, 'esMX', '', 'He estado trabajando junto a los demás aprendices de Xylem para determinar su ubicación. ¡Creo que lo encontramos en el El Ojo de la Eternidad, $ct!', 25549),
(128413, 'esMX', 'Ahora está más tranquila, pero sigue preocupada. Debería poder comunicarme con ella.$b$b¿Estás $Glisto:lista;, $n?', '', 25549),
(128412, 'esMX', '', '¡Druidas! ¡Hemos salido victoriosos! El Ídolo de Aviana está a salvo una vez más. Archidruida, haz los honores y regresa al ídolo donde pertenece.', 25549),
(128411, 'esMX', '', 'Lo hicimos. Llevemos a este ídolo de regreso a la Arboleda de los Sueños.', 25549),
(128410, 'esMX', '¡Ya me cansé de este juego!', '', 25549),
(128409, 'esMX', '', '¡Aviana, te lo ruego! ¡Ayúdanos!', 25549),
(128408, 'esMX', '', '¡Por aquí!', 25549),
(128407, 'esMX', '', '¡Malditos blasfemos!', 25549),
(128406, 'esMX', '¡Llegas demasiado tarde, druida! ¡Usaremos su poder para volar y derribaremos Dalaran!', '', 25549),
(128405, 'esMX', '', '¡Te equivocas! ¡Hoy es el día de tu muerte, demonio!', 25549),
(128404, 'esMX', '¡Legión! Con este ídolo, la ciudad flotante de los mortales cobardes ya no los protegerá.', '', 25549),
(128403, 'esMX', '', '¡Veamos qué sucede... con discreción!', 25549),
(128402, 'esMX', '', 'Nos veremos en Azsuna, Archidruida.', 25549),
(128401, 'esMX', '', 'Qué demonios... ¡No puedo transformarme en mi forma de vuelo! Con la desaparición del ídolo, hemos perdido nuestras alas. ¡Teletranspórtense y reagrupémonos en la Arboleda de los Sueños!', 25549),
(128400, 'esMX', '', 'El santuario está perdido. ¡Druidas, alcen vuelo! ¡Nos retiramos!', 25549),
(128399, 'esMX', '', '¡Noooo!', 25549),
(128398, 'esMX', '', 'Maldito... ¡No! ¡El ídolo!', 25549),
(128397, 'esMX', '¡Muere ante el poder de la Legión!', '', 25549),
(128396, 'esMX', '', '¡Muere, escoria demoníaca!', 25549),
(128395, 'esMX', '', '¿Oíste eso? ¡Vienen gritos del santuario! ¡Tenemos que regresar!', 25549),
(128394, 'esMX', '', '¡Al demonio con el frente de batalla! Iré por la retaguardia y asesinaré a sus hechiceros y a su artillería. ¡El que quiera unirse, bienvenido!', 25549),
(128393, 'esMX', '', '¡Archidruida! ¡Están atacando el Santuario de Aviana otra vez, pero ahora es una invasión de gran escala! ¡Los ancestros necesitan ayuda!', 25549),
(128392, 'esMX', 'Escuchemos lo que tiene para decir, Magni.', 'Escuchemos lo que tiene para decir, Magni.', 25549),
(128391, 'esMX', 'Sus pesadillas... sus miedos más grandes... ¡tenemos que ayudar!', '', 25549),
(128390, 'esMX', 'No te preocupes. Te protegeremos. ¡No tenemos opción!', '', 25549),
(128389, 'esMX', 'Si el Destructor está vivo, ella está en grave peligro. Con razón está tan preocupada...', '', 25549),
(128388, 'esMX', 'Estoy listo, Madre Matrona.', 'Estoy lista, Madre Matrona.', 25549),
(128387, 'esMX', 'Descansa en paz, Maestra cervecera', '', 25549),
(128386, 'esMX', '', 'Es hora de que abandone este reino, amigos míos. Almai, creo que tu vida ya no es la de una simple cervecera.', 25549),
(128385, 'esMX', '¡$GGran maestro:Gran maestra;, tú eres esa luz! ¡Jamás dudes en combatir a la Legión Ardiente!', '', 25549),
(128384, 'esMX', 'Tuve una visión. Un tsunami de demonios caía sobre nosotros... y extinguía todas las luces... excepto una.', '', 25549),
(128383, 'esMX', 'Todo mi ser, incluso mi alma... quemados...', '', 25549),
(128382, 'esMX', 'Ponshu Cuerpo férreo tose débilmente.', '', 25549),
(128381, 'esMX', 'Necesito un pasaje a Cornisa Alavil.', 'Necesito un pasaje a Cornisa Alavil.', 25549),
(128380, 'esMX', '¡Salve $Gel Señor de la batalla:la Señora de la batalla;! ¡Lok-tar!', '', 25549),
(128379, 'esMX', 'Fue un honor pelear a tu lado, $GSeñor de la batalla:Señora de la batalla; $n. Me presentaré en el Bastión del Cielo.', '', 25549),
(128378, 'esMX', '', '¡Está viejo, pero es muy fuerte! Sobrevivirá... ¿verdad?', 25549),
(128377, 'esMX', '', '¡El eco de mi poder puede salvarte!', 25549),
(128376, 'esMX', '', '¡La sima está protegida contra su magia!', 25549),
(128375, 'esMX', '', '¡Mi guardia continúa! ¡Yo puedo protegerte!', 25549),
(128374, 'esMX', 'Buena suerte con Agatha, $c. La necesitarás...', '', 25549),
(128373, 'esMX', 'Parece que Fhambar encontró a tu maga perdida. Ahora me lo llevaré de regreso.', '', 25549),
(128372, 'esMX', '|TINTERFACE\\ICONS\\Ability_BossFelLord_FelSpike.blp:20|t ¡Domatrax comienza a lanzar |cFFFF0404|Hspell:234107|h[Energía caótica]|h|r! ¡Cúbrete!', '|TINTERFACE\\ICONS\\Ability_BossFelLord_FelSpike.blp:20|t ¡Domatrax comienza a lanzar |cFFFF0404|Hspell:234107|h[Energía caótica]|h|r!', 25549),
(128371, 'esMX', 'Fhambar no encuentra nada útil...', '', 25549),
(128370, 'esMX', 'Fhambar presiente algo...', '', 25549),
(128369, 'esMX', 'No... me siento muy bien...', '', 25549),
(128368, 'esMX', 'Bien... Una vez que hayan pasado, la estúpida "Ofensiva de Legión caída" no tendrá ninguna oportunidad. Encontrarán la muerte que buscan.', '', 25549),
(128367, 'esMX', 'Les avisaré a los invocadores de inmediato. Ellos solo abrirán los portales a mi orden.', '', 25549),
(128366, 'esMX', 'La víspera de nuestro ataque está cerca. ¿Has reunido a las fuerzas?', '', 25549),
(128365, 'esMX', '¡Mantente alerta, $Gcampeón:campeona;! Debemos vigilar al enemigo, así como ellos nos vigilan a nosotros.', '', 25549),
(128364, 'esMX', '¡Celebremos, entonces! ¡Por la Noche de la naturaleza! ¡Por las grandiosas bestias! ¡Por $Gel Maestro de caza:la Maestra de caza;!', '', 25549),
(128363, 'esMX', '¡Ja, ja! Creo que le agradas, $Gcazador:cazadora;. Ahora la bestia y tú comparten un vínculo, en este reino y en el mortal. ¡Ahora, regresemos al festín, y dejemos nuestras preocupaciones para mañana!', '', 25549),
(128362, 'esMX', '¿Aceptarás la compañía del Lobohalcón?', '', 25549),
(128361, 'esMX', '¿Entiendes lo que la historia quiere enseñarnos? Con nuestros compañeros, somos mucho más fuertes que solos.', '', 25549),
(128360, 'esMX', 'Regresa a la fogata, gran $Gcazador:cazadora; ¡y pasemos la noche celebrando!', '', 25549),
(128359, 'esMX', 'Ahora con su espíritu ligado al tuyo, los hijos de Haukenulfnir responderán a tus invocaciones en el mundo mortal.', '', 25549),
(128358, 'esMX', 'Te considera un acompañante digno. ¡El espíritu de Haukenulfnir está con $Gel cazador:la cazadora;!', '', 25549),
(128357, 'esMX', 'Ella percibe tu destreza depredadora y tu afinidad con las bestias. Si te le acercas, te pondrá a prueba, $Gcazador:cazadora;.', '', 25549),
(128356, 'esMX', '¡Es Haukenulfnir, el que acechaba la naturaleza cuando el mundo apenas nacía!', '', 25549),
(128355, 'esMX', '¿Qué es esto? Un espíritu rarísimo y de lo más extraordinario ha aparecido, uno que no ha visitado estos campos durante eras.', '', 25549),
(128354, 'esMX', '¡Contémplalos! Fereki, madre del cubil, gran depredadora de la tierra, y el poderoso Vetholnir, señor de los cielos.', '', 25549),
(128353, 'esMX', '¡Los espíritus te tienen en alta estima, $GMaestro de caza:Maestra de caza;! ¡Han emergido los depredadores más renombrados de todas nuestras leyendas! ¡Esta es, sin lugar a dudas, la Noche de la naturaleza más grandiosa que he vivido!', '', 25549),
(128352, 'esMX', 'Ranulf del Abismo aullante triunfó en vida contra Habrok. ¡El espíritu de Ranulf acompaña $Gal cazador:a la cazadora;!', '', 25549),
(128351, 'esMX', 'Habrok, el gran búho, se posa sobre ti. Alguna vez todas las bestias sintieron temor por sus garras, y se escondían de su aguda visión durante la noche.', '', 25549),
(128350, 'esMX', 'Tor de Asedio brutal mató a Ketlingr ¡El espíritu de Tor acompaña $Gal cazador:a la cazadora;!', '', 25549),
(128349, 'esMX', 'Ketlingr, el gran felino, bebe ante ti. Un depredador ágil, feroz. ¡Muchos han aprendido a temer a sus colmillos y a sus garras!', '', 25549),
(128348, 'esMX', 'Bjorn de Tormenta negra trajo aquí a Garos. ¡El espíritu de Bjorn acompaña $Gal cazador:a la cazadora;!', '', 25549),
(128347, 'esMX', 'Sigues el rastro de Garos, la gran gusano. Muchos son sus hijos y profundos son sus túneles.', '', 25549),
(128346, 'esMX', 'El primero en ir tras Hyrtir fue Haldor del Acantilado rocoso. ¡El espíritu de Haldor acompaña $Gal cazador:a la cazadora; esta noche!', '', 25549),
(128345, 'esMX', '¡Emerge Hyrtir, el gran venado! La más veloz de las bestias, con cuernos afilados como lanzas. ¡Que la suerte sea contigo, $Gcazador:cazadora;!', '', 25549),
(128344, 'esMX', 'Encontrar a estas ingeniosas bestias en la oscuridad no será fácil, pero todo buen cazador es un maestro del rastreo.', '', 25549),
(128343, 'esMX', 'Cuando estés $Gsatisfecho, cazador:satisfecha, cazadora;, abandona la mesa y adéntrate en la naturaleza. ¡Tu presa espera!', '', 25549),
(128342, 'esMX', '¡Que comience el festín!', '', 25549),
(128341, 'esMX', '¡Alcen sus vasos por $Gel Maestro de caza, nuestro cazador:la Maestra de la caza, nuestra cazadora; de bestias!', '', 25549),
(128340, 'esMX', 'Para cazar a los nobles espíritus y regresarlos a su honrado reposo.', '', 25549),
(128339, 'esMX', 'Uno de nosotros ha sido elegido para adentrarse en la oscuridad.', '', 25549),
(128338, 'esMX', 'Esta noche, los espíritus de las grandes bestias legendarias se alzan en estos mismos campos.', '', 25549),
(128337, 'esMX', 'La Noche de la naturaleza ha llegado una vez más, amigos.', '', 25549),
(128336, 'esMX', 'La Legión envía sus ojos omnipresentes para espiar nuestros esfuerzos de guerra. ¡Es intolerable! Encárgate de que no puedan usar nada de lo que aprendieron en nuestra contra.', '', 25549),
(128335, 'esMX', 'Nada escapa de la Legión.', '', 25549),
(128334, 'esMX', '¿Has oído eso? ¡Vino de allí!', '', 25549),
(128333, 'esMX', '¿Un intruso? ¡Muéstrate!', '', 25549),
(128332, 'esMX', '¡La Bomba vil de %s detona!', '¡La Bomba vil de %s detona!', 25549),
(128331, 'esMX', '', 'Sentía que la vida se escapaba de mi cuerpo... Tienes mi eterna gratitud, Gran maestra.', 25549),
(128330, 'esMX', '', '¡Puaj! ¡Jamás creí que estaría feliz de probar algo tan asqueroso!', 25549),
(128329, 'esMX', '', 'Fui tan débil... ¡Gracias por ayudarme!', 25549),
(128328, 'esMX', '', '¡Bendita seas, Gran maestra!', 25549),
(128327, 'esMX', 'Sentía que la vida se escapaba de mi cuerpo... Tienes mi eterna gratitud, $GGran maestra:Gran maestra;.', '', 25549),
(128326, 'esMX', '¡Puaj! ¡Jamás creí que estaría feliz de probar algo tan asqueroso!', '', 25549),
(128325, 'esMX', 'Fui tan débil... ¡Gracias por ayudarme!', '', 25549),
(128324, 'esMX', '¡Bendito seas, Gran maestro!', '', 25549),
(128323, 'esMX', '', 'Eso fue... exquisito...', 25549),
(128322, 'esMX', '', 'Agatha... estará... complacida...', 25549),
(128321, 'esMX', '', 'Espero que $Geste:esta; sea más $Gdivertido:divertida; que el último.', 25549),
(128320, 'esMX', '', '¡Juguemos, $c!', 25549),
(128319, 'esMX', '', 'No te preocupes, Uhrlia, parece que $Geste:esta; está en forma. No se rendirá tan fácilmente.', 25549),
(128318, 'esMX', '', '¡Listo! Terminé.', 25549),
(128317, 'esMX', '', 'Retrocede mientras agregamos las hierbas al brebaje...', 25549),
(128316, 'esMX', 'Tú perseverancia y la de tus aliados es una inspiración para nuestras fuerzas. ¡Es la prueba de que juntos podemos salvar Azeroth!', '', 25549),
(128315, 'esMX', '', 'Vaya, parece que Agatha encontró un juguete nuevo.', 25549),
(128314, 'esMX', 'La Legión no es rival para el poder de la Luz. ¡No cuando alguien como tú la defiende!', '', 25549),
(128313, 'esMX', 'Has salvado muchas vidas hoy. Por este noble acto, tienes mi agradecimiento.', '', 25549),
(128312, 'esMX', 'Has traído la Luz a este lugar oscuro. Gracias.', '', 25549),
(128311, 'esMX', '¡$GCampeón:Campeona;! ¡La Luz te necesita!', '', 25549),
(128310, 'esMX', '¡Que la Luz nos proteja! Nuestros aliados nos necesitan. Por favor, adalid, ¡ayúdalos!', '', 25549),
(128309, 'esMX', 'Reúne a tus aliados, $Ghéroe:heroína;. ¡La amenaza que estás por enfrentar pondrá tus habilidades a prueba!', '', 25549),
(128308, 'esMX', 'Tú y tus amigos son una fuerza de combate impresionante. ¡Nuestra unidad logrará la caída de la Legión!', '', 25549),
(128307, 'esMX', 'Una vez más, te debo las gracias. ¡Creo que esto ya se te empieza a hacer un hábito!', '', 25549),
(128306, 'esMX', '¡Bien hecho! La forma en que eliminaste a los enemigos me recuerda a mis días de juventud. Mi tan lejana juventud.', '', 25549),
(128305, 'esMX', 'Tu trabajo nos ha salvado la vida, $Gcampeón:campeona;. ¡Debes estar $gorgulloso:orgullosa;!', '', 25549),
(128304, 'esMX', '¡Buen trabajo! Hemos repelido a la Legión... al menos por ahora.', '', 25549),
(128303, 'esMX', 'Reúne a tus aliados, $Gcampeón:campeona;. ¡Una gran amenaza se aproxima y necesitamos héroes!', '', 25549),
(128302, 'esMX', '¡Por aquí! ¡Ven rápido!', '', 25549),
(128301, 'esMX', '¡Por aquí, $Gcampeón:campeona;!', '', 25549),
(128300, 'esMX', 'Nuestros exploradores informan la presencia de un enemigo letal cerca. ¡Llegó la hora de atacar!', '', 25549),
(128299, 'esMX', 'Algunos aliados cercanos están en problemas, $Gcampeón:campeona;. ¡Por favor, debes ayudarlos!', '', 25549),
(128298, 'esMX', '¡$GHéroe:Heroína;! Nuestros enemigos se han infiltrado en esta área. ¡Contamos contigo para que los elimines!', '', 25549),
(128297, 'esMX', '%s escupe.', '%s escupe.', 25549),
(128296, 'esMX', '¡No puedes enfrentarte a mí!', '', 25549),
(128295, 'esMX', '¡Pongamos a prueba su determinación!', '', 25549),
(128294, 'esMX', '¡Los aplastaré!', '', 25549),
(128293, 'esMX', '¿Te atreves a desafiarme?', '', 25549),
(128292, 'esMX', '¡El dolor cae sobre ti!', '', 25549),
(128291, 'esMX', '¡Quédense en donde están!', '', 25549),
(128290, 'esMX', '¡No se muevan!', '', 25549),
(128289, 'esMX', '¡No se muevan!', '', 25549),
(128288, 'esMX', '¡Los haré pedazos!', '', 25549),
(128287, 'esMX', '¡Los haré polvo!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128286, 'esMX', '¡Los aplastaré!', '', 25549),
(128285, 'esMX', '¡Ardan! ¡Ardan en las llamas de mi tormento!', '', 25549),
(128284, 'esMX', 'Aún... hay más... agonía por venir...', '', 25549),
(128283, 'esMX', 'El amo estará satisfecho.', '', 25549),
(128282, 'esMX', 'Me he ganado la gloria... y se las arrebaté a estos mortales.', '', 25549),
(128281, 'esMX', '¡Otro enemigo que cae!', '', 25549),
(128280, 'esMX', '¡Mortal patético!', '', 25549),
(128279, 'esMX', '¡Muy fácil de romper!', '', 25549),
(128278, 'esMX', '¡Vengan, enfréntense a su perdición!', '', 25549),
(128277, 'esMX', '¡Me deleitaré con su sufrimiento!', '', 25549),
(128276, 'esMX', '¡Conocerán el dolor!', '', 25549),
(128275, 'esMX', '¡Intrusos! ¡Si los mato me ganaré el favor del amo!', '', 25549),
(128274, 'esMX', '', 'La energía de este lugar es maléfica. ¡Vamos!', 25549),
(128273, 'esMX', '', 'Parece que has perdido algo. ¿Puedo ayudarte?', 25549),
(128272, 'esMX', '¿Hay algo que necesites hacer explotar? ¡El viejo Icks tiene el personal indicado para ti!', '', 25549),
(128271, 'esMX', 'Tú y tus camaradas pelearon bien. Esa determinación será crucial en las próximas batallas.', '', 25549),
(128270, 'esMX', 'La caída de semejante enemigo inspirará a nuestras fuerzas... e infundirá temor en los corazones de los demonios.', '', 25549),
(128269, 'esMX', 'El poder de las armas no es la única forma de asestarle un golpe a la Legión. ¡Bien hecho!', '', 25549),
(128268, 'esMX', 'Una batalla bien peleada. ¡La Legión ha aprendido a temerte!', '', 25549),
(128267, 'esMX', 'Te necesitamos a ti y a tus aliados, $Gcampeón:campeona;. ¡Reúne a tus fuerzas!', '', 25549),
(128266, 'esMX', 'Un poderoso enemigo está cerca. ¡Acábalo con toda la malicia que se merece!', '', 25549),
(128265, 'esMX', '¡Eras mi amigo! ¿Cómo pudiste hacerme esto a mí? ¿Y a mi FAMILIA?', '¡Eras mi amiga! ¿Cómo pudiste hacerme esto a mí? ¿Y a mi FAMILIA?', 25549),
(128264, 'esMX', 'Parece que no pude escapar al veneno de ese demonio...', 'Parece que no pude escapar al veneno de ese demonio...', 25549),
(128263, 'esMX', 'Ojalá pudiera dormir todo el día.', 'Ojalá pudiera dormir todo el día.', 25549),
(128262, 'esMX', '<bostezo> ¿Ya es hora de regresar al trabajo?', '<bostezo> ¿Ya es hora de regresar al trabajo?', 25549),
(128261, 'esMX', 'Nuestros aliados necesitan tu ayuda, $Gcampeón:campeona;. ¡Debes actuar de inmediato!', '', 25549),
(128260, 'esMX', '¡¿Dónde podrá estar?!', '¡¿Dónde podrá estar?!', 25549),
(128259, 'esMX', 'Sé que se me cayó por aquí en algún lado...', 'Sé que se me cayó por aquí en algún lado...', 25549),
(128258, 'esMX', 'Tal vez debamos ver si quedó algo de utilidad.', 'Tal vez debamos ver si quedó algo de utilidad.', 25549),
(128257, 'esMX', '¡$GCampeón:Campeona;! ¡Necesitamos tus habilidades! ¡Prepárense para la batalla!', '', 25549),
(128256, 'esMX', '$GBienvenido:Bienvenida; al Templete de los Escribas, $c. ¿Puedo sugerirte algún pergamino?', '', 25549),
(128255, 'esMX', 'El ataque de la Legión fue implacable en esta área. Parece que no hay sobrevivientes.', 'El ataque de la Legión fue implacable en esta área. Parece que no hay sobrevivientes.', 25549),
(128254, 'esMX', '¡Otro más! Aliarse con estos "demonios" fue un error.', '¡Otro más! Aliarse con estos "demonios" fue un error.', 25549),
(128253, 'esMX', '<suspiro> Otro centinela muerto.', '<suspiro> Otro centinela muerto.', 25549),
(128252, 'esMX', '<suspiro> Lo perdimos demasiado pronto.', '<suspiro> Lo perdimos demasiado pronto.', 25549),
(128251, 'esMX', 'Que Elune guíe tu alma, hijo mío.', 'Que Elune guíe tu alma, hijo mío.', 25549),
(128250, 'esMX', 'Nunca encontrarán esto enterrado aquí...', 'Nunca encontrarán esto enterrado aquí...', 25549),
(128249, 'esMX', 'Una vez allí, te entregaré un obsequio en muestra de mi agradecimiento. Espero que te sea útil.', '', 25549),
(128248, 'esMX', 'Clarividente $p, te regresaré al corazón de Azeroth. Ve con mi agradecimiento.', '', 25549),
(128247, 'esMX', 'Divididos, somos hojas en el viento. Pero unidos, somos un ciclón implacable. Que este consejo jamás vuelva a disolverse.', '', 25549),
(128246, 'esMX', 'Yo soy el Señor del viento ahora, y todos braman bajo mi dominio. Pero no dejemos este consejo con un aire viciado y turbulento.', '', 25549),
(128245, 'esMX', 'Veo que $Gel:la; Clarividente ha inclinado su lealtad hacia mí. Bien. Permítanme disipar todas las dudas que les atormentan la mente.', '', 25549),
(128244, 'esMX', 'Cuando conozcan tus intenciones, buscarán eliminarte de este plano. Te concederé una bendición que lo impedirá, al menos por un tiempo.', '', 25549),
(128243, 'esMX', 'Tu parloteo no me impresiona, demonio. ¡Siente la ira del ejército de un verdadero comandante!', '', 25549),
(128242, 'esMX', '¡Ja, ja, ja, ja, ja!', '', 25549),
(128241, 'esMX', 'Creen inocentemente que Sarsarun es el heredero legítimo al trono. Tontos. Necesito que los convenzas de lo contrario.', '', 25549),
(128240, 'esMX', 'Los vientos llevan mi voluntad a los lejanos rincones de este plano, pero ni siquiera yo puedo estar en todos lados al mismo tiempo. Aquí, en Muro celeste, algunos de mis súbditos aún no han comprendido la totalidad de mi ascenso.', '', 25549),
(128239, 'esMX', '¡Al ataque!', '', 25549),
(128237, 'esMX', 'Agradezco tu ayuda, Clarividente $p. Estoy seguro de que resolverás este problema pronto.', '', 25549),
(128236, 'esMX', 'No deberías perder el tiempo que te concedieron para completar tu tarea, Clarividente $p.', '', 25549),
(128235, 'esMX', '', 'Todavía tengo trabajo que hacer aquí, pero me reuniré contigo en el Martillo vil, $GDestripador:Destripadora; $p.', 25549),
(128234, 'esMX', '', 'Permítenos dejar a la criatura presentable para que te sea conferida en el Martillo Vil. Habla con Yrdris y él te llevará de regreso a la nave.', 25549),
(128233, 'esMX', '', 'Veo que has domado a la bestia, $GDestripador:Destripadora; $p. ¡Mereces mis felicitaciones!', 25549),
(128232, 'esMX', 'Erdris... ¡tu magia es débil! ¡No... nos... vencerás!', '', 25549),
(128231, 'esMX', '|TInterface\\Icons\\INV_SPEAR_08.BLP:20|t¡%s apunta a |cFFFF0000$n|r con una |cFFFF0000|Hspell:235933|h[Lanza de angustia]|h|r!', '', 25549),
(128230, 'esMX', '', 'Esto... no parece estar bien. ¿Dónde estoy?', 25549),
(128229, 'esMX', '¿Qué es esta sensación? Una fuerza oscura... se adentra en mi mente...', '', 25549),
(128228, 'esMX', '|TInterface\\Icons\\Ability_Rogue_BloodyEye:20|tLa |cFFFF0000|Hspell:237726|h[Mirada desdeñosa]|h|r de Aporreador se posa sobre |cFFFF0000$n|r!', '|TInterface\\Icons\\Ability_Rogue_BloodyEye:20|tLa |cFFFF0000|Hspell:237726|h[Mirada desdeñosa]|h|r de Aporreador se posa sobre |cFFFF0000$n|r!', 25549),
(128227, 'esMX', 'Seguramente enviará a sus esbirros para detenernos. Necesitaré todas mis fuerzas para mantener el portal. Tú debes encargarte de mantenerlos alejados.', '', 25549),
(128225, 'esMX', 'Activaré el portal. Cuando esté abierto, necesitaré que coloques la piedra de invocación para atraer a Arax''ath y el corcel iracundo.', '', 25549),
(128224, 'esMX', '', 'Debería ser fácil de rastrear con tu visión demoníaca. Pero si huyó hacia el criadero, creo que vas a tener algunos problemas para traerlo de regreso. Los murciélagos pueden ser criaturas muy... enérgicas.', 25549),
(128223, 'esMX', '', 'Lo siento, $GDestripador:Destripadora;, parece que escapó. Ah, ¿viste esto? Un rastro de sangre. ¡Qué conveniente!', 25549),
(128222, 'esMX', '', '¡Rápido, atrapa a la criatura!', 25549),
(128221, 'esMX', '', 'Domar una bestia tan imponente requiere una gran demostración de dominio. Claro que esa es mi especialidad... pero en este caso, sugiero que solo lo aporrees hasta someterlo.', 25549),
(128220, 'esMX', '', 'Hace algunos días, este murciélago vil atacó nuestro campamento. Es un lujo muy inusual capturar un espécimen maduro, así que insistí en que lo contuvieran en lugar de matarlo.', 25549),
(128219, 'esMX', '', '¡Illidari! ¡Traigan a la bestia!', 25549),
(128218, 'esMX', '', '$GBienvenido, Destripador:Bienvenida, Destripadora; $p, a los criaderos de murciélagos viles. Hemos capturado un precioso espécimen para que conozcas hoy.$b$bAvísame cuando estés $Glisto:lista; para verlo.', 25549),
(128217, 'esMX', '|TInterface\\ICONS\\Ability_FelArakkoa_FelDetonation_Green:20|t ¡Cuidado! Evita la |cFFFF0404|Hspell:238005|h[Nova de fuerza cataclísmica]|h|r! para quedarte a bordo de la nave!', '', 25549),
(128216, 'esMX', '', '¡Nunca me sentí tan viva!', 25549),
(128215, 'esMX', '', 'Daumyr se encargó de ellos rápidamente. ¿Oíste sus gritos? ¡Es música para mis oídos!', 25549),
(128214, 'esMX', '', 'Los jinetes lograron contener a los demonios.', 25549),
(128213, 'esMX', '', '¡Una tanda menos! ¡Envíenlos a la tumba!', 25549),
(128212, 'esMX', '', '¿Ves a los jinetes? Es increíble que puedan resistir contra semejante multitud.', 25549),
(128211, 'esMX', '', 'La Legión temblará bajo la sombra de Daumyr. ¡Pedirán piedad a gritos ante nuestra lluvia de muerte y destrucción!', 25549),
(128210, 'esMX', '', 'Todos esos demonios... ¡bah! No hay posibilidad de que nos derroten; no si controlamos el poder de Daumyr y su linaje.', 25549),
(128209, 'esMX', '', '¿Todo listo para develar nuestra arma secreta?', 25549),
(128208, 'esMX', '¡No pueden detenerme, demonios! ¡ARRIBA, SOLDADOS!', '', 25549),
(128207, 'esMX', 'Me canso de esperar.', '', 25549),
(128206, 'esMX', '¡Los Ritualistas xorothianos están conjurando Cataclismo!', '', 25549),
(128205, 'esMX', '', 'Me aseguraré de que ningún otro esbirro de Kruul cruce el portal. Que sufras bien.', 25549),
(128204, 'esMX', '', 'Debería poder reactivar su portal. Este lugar está repleto de almas que podríamos usar.', 25549),
(128203, 'esMX', '', '|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|t¡%s te marca con |cFFFF0000|Hspell:236304|h[Disparo incorpóreo]|h|r!', 25549),
(128202, 'esMX', '', 'Iré contigo, $GGran maestro:Gran maestra;. ¡No tenemos tiempo que perder!', 25549),
(128201, 'esMX', 'Qué improvisación tan formidable. Si tan solo más de nuestras fuerzas pudieran encargarse de estas misiones. Ahora sal de ahí antes de que los refuerzos te encuentren.', '', 25549),
(128200, 'esMX', 'Marius y su brujo mascota lograron revertir uno de los portales demoníacos. Atraviésalo y desata el caos del otro lado.', '', 25549),
(128199, 'esMX', '¡No... no fue tu culpa, Almai! Pero... debemos apurarnos... para encontrar una cura. Algunos ya han muerto...', '', 25549),
(128198, 'esMX', '', 'El señor del terror me atacó, envenenó mi cerveza de celebración, y se robó mi forma...', 25549),
(128194, 'esMX', '', '¡Debemos regresar al Templo de los Cinco Albores! ¡Avísame cuando estés $Glisto:lista;!', 25549),
(128193, 'esMX', 'Dudar frente al peligro no es un defecto ni una debilidad, sino una oportunidad para responder al llamado de la batalla.', 'Dudar frente al peligro no es un defecto ni una debilidad, sino una oportunidad para responder al llamado de la batalla.', 25549),
(128192, 'esMX', '', 'Puedo preparar una buena cerveza con los ojos cerrados. Pero tejer niebla, eso sí que es un desafío. Algún día espero ser buena en eso.', 25549),
(128191, 'esMX', '', 'La vida en el Valle de los Cuatro Vientos suele ser pacífica, y para la mayoría eso es bueno. Pero para mí, también es aburrido. Prefiero alguna emoción de vez en cuando.', 25549),
(128190, 'esMX', '', 'Mi familia ha hecho cerveza por generaciones, ¡así que tengo un don natural para eso! Aun así, siempre he querido probar mis habilidades en algo diferente.', 25549),
(128189, 'esMX', 'El viento solo dura hasta que llega la calma. Debemos recordar nuestro entrenamiento.', 'El viento solo dura hasta que llega la calma. Debemos recordar nuestro entrenamiento.', 25549),
(128188, 'esMX', '¡Debemos mantener la compostura! Demuéstrales a nuestros aliados quiénes somos realmente, ¡no lo que esos demonios creen que somos!', '¡Debemos mantener la compostura! Demuéstrales a nuestros aliados quiénes somos realmente, ¡no lo que esos demonios creen que somos!', 25549),
(128187, 'esMX', 'Alza la cabeza, joven guerrero. Nuestro viaje acaba de comenzar.', 'Alza la cabeza, joven guerrera. Nuestro viaje acaba de comenzar.', 25549),
(128186, 'esMX', 'Debemos mantenernos fuertes.', 'Debemos mantenernos fuertes.', 25549),
(128185, 'esMX', 'Sé que es doloroso, pero con el paso de los años recordaremos este día y todo por lo que peleamos, todo lo que entregamos. Eso es lo que nos define.', 'Sé que es doloroso, pero con el paso de los años recordaremos este día y todo por lo que peleamos, todo lo que entregamos. Eso es lo que nos define.', 25549),
(128184, 'esMX', 'Muchos guerreros han buscado refugio durante una tormenta, pero este no es el momento de resguardarse. Debemos levantar nuestras armas y atacar el corazón de la naturaleza misma.', 'Muchos guerreros han buscado refugio durante una tormenta, pero este no es el momento de resguardarse. Debemos levantar nuestras armas y atacar el corazón de la naturaleza misma.', 25549),
(128183, 'esMX', 'Son fuertes, con sangre más caliente que el sol de verano. Te aseguro que se recuperarán a tiempo, pero debemos cumplir con nuestra parte y regresar. ¡Nuestro pueblo nos necesita!', 'Son fuertes, con sangre más caliente que el sol de verano. Te aseguro que se recuperarán a tiempo, pero debemos cumplir con nuestra parte y regresar. ¡Nuestro pueblo nos necesita!', 25549),
(128182, 'esMX', '', 'Tengo el deber de... asegurar... ¡el fin de tu existencia!', 25549),
(128181, 'esMX', '', 'Los simples mortales jamás podrán entender mi cometido. Un deber sagrado de servir... ¡de servir al amo!', 25549),
(128180, 'esMX', 'Andando.', 'Andando.', 25549),
(128179, 'esMX', '¡La hora ha llegado! ¡Su destino está cerca!', '', 25549),
(128178, 'esMX', '¡Arriba! ¡Sí! ¡Levántense!', '', 25549),
(128177, 'esMX', '¡El poder fluye dentro de ti! ¡Destruye a estos demonios!', '', 25549),
(128176, 'esMX', '¡Su comandante los llama!', '', 25549),
(128175, 'esMX', '¡Arriba, mis soldados!', '', 25549),
(128174, 'esMX', '¡Si este es el mejor cazador que tu mundo puede ofrecer, realmente está perdido!', '', 25549),
(128173, 'esMX', '¿Vuelves por más? ¡Mis sabuesos te harán trizas!', '', 25549),
(128172, 'esMX', '¡No le temo a ninguna bestia! ¡La Legión es infinita!', '', 25549),
(128171, 'esMX', 'Me gustaría salir de las Minas de la Muerte.', 'Me gustaría salir de las Minas de la Muerte.', 25549),
(128170, 'esMX', '', '¡Maestra cervecera! ¡NO!', 25549),
(128169, 'esMX', '', '¿Qué... qué pasó? ¿Qué quiso decir? $GGran maestro:Gran maestra;, tenemos que regresar al templo, ¡y rápido! ¡Avísame cuando estés $Glisto:lista;!', 25549),
(128168, 'esMX', 'Mi trabajo está completo, monjes enclenques... ¡Su orden está perdida!', '', 25549),
(128166, 'esMX', '', 'Fue bueno mientras duró.', 25549),
(128165, 'esMX', '', 'Almai, tu ingenuidad es tan refrescante. Es una pena que tengas que morir.', 25549),
(128164, 'esMX', '', '¿Maestra cervecera? ¿De qué hablas? ¡Estuvimos buscándote por todas partes!', 25549),
(128163, 'esMX', '', '$GGran maestro:Gran maestra;, has llegado más lejos de lo que esperaba. Parece que tendré que encargarme de ti yo misma.', 25549),
(128162, 'esMX', '', '¡El Brebaje de tormenta es fascinante! ¡No me sorprende que la Legión le tenga temor!', 25549),
(128161, 'esMX', '', 'Yo no elegí mi destino... ¡y tú tampoco podrás!', 25549),
(128160, 'esMX', '', '¡Conoce el tormento de un alma dividida!', 25549),
(128159, 'esMX', '¡Vengan, campeones de este mundo, y los exterminaré de inmediato!', '', 25549),
(128158, 'esMX', '¡$GTejedor vil:Tejedora vil;! ¡Encárgate de estos intrusos!', '', 25549),
(128157, 'esMX', 'Con su comandante derrotado y los escudos anulados, los dracos azules pueden atacar la nave con todas sus fuerzas. Enviarán un transporte a buscarte antes de comenzar.', '', 25549),
(128156, 'esMX', '¡$n! ¡Conmigo, rápido! ¡Esto termina ahora!', '', 25549),
(128155, 'esMX', 'Los dracos nos llevarán hasta la nave de la Legión para que nos encarguemos del comandante del área. Después vendrán por ti, antes de iniciar el ataque principal a la nave.', '', 25549),
(128154, 'esMX', 'Los dracos azures del área han jurado ayudarnos para combatir a la Legión, pero necesitarán tu ayuda. Bríndales la ayuda que puedas.', '', 25549),
(128153, 'esMX', 'Hora de ir a la Costa Quebrada, Daumyr.', 'Hora de ir a la Costa Quebrada, Daumyr.', 25549),
(128152, 'esMX', '', '<Daumyr asiente con la cabeza, con la mirada vacía.>', 25549),
(128151, 'esMX', '', '¡Tu preciado mundo arderá!', 25549),
(128150, 'esMX', '¡Por el honor de Altamontaña! ¡Estoy listo! [Hacer cola para la gesta]', '¡Por el honor de Altamontaña! ¡Estoy lista! [Hacer cola para la gesta]', 25549),
(128149, 'esMX', 'Sugiero que seamos rápidos. Los cielos están llenándose de estas bestias inmundas.\n\nTenemos la oportunidad de atacar el corazón de la Legión. Debemos llevar la pelea al frente de batalla.', '', 25549),
(128148, 'esMX', 'Buen trabajo, $Ghéroe:heroína;. ¡Las historias de tus hazañas se cantarán en los Salones del Valor!', '', 25549),
(128147, 'esMX', 'Vuela rápido, $ct. Nos veremos allí.', '', 25549),
(128146, 'esMX', '¡Destruye sus cañones y derriba sus barreras! ¡Que nuestros valientes valarjar los enfrenten con el verdadero espíritu de la batalla!', '', 25549),
(128145, 'esMX', 'Estos demonios cobardes se esconden tras sus defensas. ¡Toma mi martillo bendito y acábalos!', '', 25549),
(128144, 'esMX', '¿Creyeron que podían escapar si se escondían en su cervecería miserable? ¡La Legión Ardiente lo ve todo!', '', 25549),
(128143, 'esMX', 'Sus esfuerzos llegan demasiado tarde, criaturas patéticas...', '', 25549),
(128142, 'esMX', '', '¿Cómo es que la Legión conoce nuestro Brebaje de tormenta? Siempre lo mantuvimos en secreto...', 25549),
(128141, 'esMX', 'No soy un amante de los múrlocs, pero ni siquiera ellos merecen conocer su fin a manos de la Legión. Gracias, $ghéroe:heroína;.', '', 25549),
(128140, 'esMX', '¡Cuánta depravación! Los demonios drenan las almas de los inocentes para alimentar su magia vil. ¡Ponle fin a esta cosecha, $Ghéroe:heroína;!', '', 25549),
(128139, 'esMX', '¡Buena pelea! Cada victoria es vital en esta guerra.', '', 25549),
(128138, 'esMX', '¡Nuestras costas arden con fuego vil! Ataca rápido, antes de que la amenaza avance por el continente.', '', 25549),
(128137, 'esMX', 'Disfruta el caos...', '', 25549),
(128136, 'esMX', '¡Pero qué deliciosa ironía! Los demonios son tan rápidos para enfrentarse entre ellos...', '', 25549),
(128135, 'esMX', '', '¡Pestes insolentes! ¡Sus esfuerzos no son NADA!', 25549),
(128134, 'esMX', '¡El péndulo se mueve en nuestro favor! Dirígete a los riscos y encárgate de ese demonio. Nos reuniremos luego de que asegures los cielos.', '', 25549),
(128133, 'esMX', 'Yo... eh... nosotros... estamos...', '', 25549),
(128132, 'esMX', '¡No convertirás a mis aliados en tus esclavos descerebrados!', '', 25549),
(128131, 'esMX', 'Levantaré a estos Thorignir como mis soldados, y Daumyr será la siguiente.', 'Levantaré a estos Thorignir como mis soldados, y Daumyr será la siguiente.', 25549),
(128130, 'esMX', '$GBienvenido:Bienvenida; a mi cima, $ct.$b$bSoy el último vigía anciano que queda de los drekirjar. Este es mi hogar, donde cuido de los cuerpos sagrados de nuestros aliados que dieron la vida por nuestra alianza. Puede que Skovald haya destruido nuestra alianza con los Thorignir, pero algunos de nosotros no obedecemos sus órdenes.$b$bHasta el día de hoy, los Thorignir mueren en nuestro enfrentamiento. Es todo lo que puedo hacer para servirles hasta que sus cuerpos regresen a la nieve. Con Daumyr como mi compañera, protegemos nuestro deber con nuestras vidas.', '', 25549),
(128129, 'esMX', '', 'Yo recuperaré la llama. ¡Esperaba tanto este momento!', 25549),
(128128, 'esMX', '¡Uf! ¡Yo me largo!', '¡Uf! ¡Yo me largo!', 25549),
(128127, 'esMX', 'Por la oscuridad del vacío, ¿qué...?', 'Por la oscuridad del vacío, ¿qué...?', 25549),
(128126, 'esMX', '¡Eso duele!', '¡Eso duele!', 25549),
(128125, 'esMX', '¡Qué grosería!', '¡Qué grosería!', 25549),
(128124, 'esMX', '¡Auch! ¿Por qué me haces eso?', '¡Auch! ¿Por qué me haces eso?', 25549),
(128123, 'esMX', 'Solo descansaré un momento...', 'Solo descansaré un momento...', 25549),
(128122, 'esMX', '¡Ahora veo con claridad!', '¡Ahora veo con claridad!', 25549),
(128121, 'esMX', '¿Dónde... estoy?', '¿Dónde... estoy?', 25549),
(128120, 'esMX', '¡La oscuridad se ha ido! Gracias.', '¡La oscuridad se ha ido! Gracias.', 25549),
(128119, 'esMX', '|TInterface\\ICONS\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t ¡El Avatar caído te marca con |cFFFF0404|Hspell:236604|h[Hojas de las sombras]|h|r!', '|TInterface\\ICONS\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t ¡El Avatar caído te marca con |cFFFF0404|Hspell:236604|h[Hojas de las sombras]|h|r!', 25549),
(128118, 'esMX', 'Estoy listo para enfrentarme a Sigryn. (Gratis)', 'Estoy lista para enfrentarme a Sigryn. (Gratis)', 25549),
(128117, 'esMX', 'Estoy listo para enfrentarme a Kruul. (Gratis)', 'Estoy lista para enfrentarme a Kruul. (Gratis)', 25549),
(128116, 'esMX', 'Estoy listo para enfrentarme a Raest. (Gratis)', 'Estoy lista para enfrentarme a Raest. (Gratis)', 25549),
(128115, 'esMX', 'Estoy listo para encargarme de Xylem. (Gratis)', 'Estoy lista para encargarme de Xylem. (Gratis)', 25549),
(128114, 'esMX', '', 'Fue un honor conocerte, $GGran maestro:Gran maestra;. ¡Espero que volvamos a vernos pronto!', 25549),
(128113, 'esMX', 'Llévame con Agatha... (Gratis)', 'Llévame con Agatha... (Gratis)', 25549),
(128112, 'esMX', 'Hablaré...', 'Hablaré...', 25549),
(128111, 'esMX', 'Solo déjame...', 'Solo déjame...', 25549),
(128110, 'esMX', '¡Eh, tú, ayúdame!', '¡Eh, tú, ayúdame!', 25549),
(128109, 'esMX', '¡Aagh!', '¡Aagh!', 25549),
(128108, 'esMX', '¡Haz que se detenga!', '¡Haz que se detenga!', 25549),
(128107, 'esMX', '¡Mis huesos!', '¡Mis huesos!', 25549),
(128106, 'esMX', '¡Alto!', '¡Alto!', 25549),
(128105, 'esMX', 'No puedo...', 'No puedo...', 25549),
(128104, 'esMX', '¡AHHHHHH!', '¡AHHHHHH!', 25549),
(128103, 'esMX', '¡Siento que la carne se desprende de mis huesos!', '¡Siento que la carne se desprende de mis huesos!', 25549),
(128102, 'esMX', 'Todo es verde, ¡no puedo ver!', 'Todo es verde, ¡no puedo ver!', 25549),
(128101, 'esMX', '¡Aghhhhh! ¡Quema, quema!', '¡Aghhhhh! ¡Quema, quema!', 25549),
(128100, 'esMX', 'Envíame con Cantosombrío. (Gratis)', 'Envíame con Cantosombrío. (Gratis)', 25549),
(128099, 'esMX', 'Estoy listo para enfrentarme a Tugar Tótem de sangre. (Gratis)', 'Estoy lista para enfrentarme a Tugar Tótem de sangre. (Gratis)', 25549),
(128098, 'esMX', '¡Gurg glurgggll!', '', 25549),
(128097, 'esMX', '¡Gurg murglgl!', '', 25549),
(128096, 'esMX', '¡Murglag!', '', 25549),
(128095, 'esMX', '¡¿Grulgrug grull murg gruumblg?!', '', 25549),
(128094, 'esMX', '¡Gurg gar gur gal!', '', 25549),
(128093, 'esMX', '¡Murgg gur gr gr grulgl!', '', 25549),
(128092, 'esMX', '¡¿Gurrg mrggll?!', '', 25549),
(128090, 'esMX', 'Estoy listo para enfrentarme a Sigryn. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Sigryn. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(128089, 'esMX', '', '¡Discúlpame, $n! Algunos de esos desastres que habías postergado requieren tu atención. Ven a hablar conmigo, por favor.', 25549),
(128088, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t ¡Tienes |cFFFF0000|Hspell:235117|h[Alma inestable]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t ¡Tienes |cFFFF0000|Hspell:235117|h[Alma inestable]|h|r!', 25549),
(128087, 'esMX', '¿A dónde vas?', '', 25549),
(128086, 'esMX', '¡Nuh-uh!', '', 25549),
(128085, 'esMX', '¡Nop!', '', 25549),
(128084, 'esMX', '¡No avanzarás más!', '', 25549),
(128083, 'esMX', '¡No te llevarás mi barco! ¡Aves a los cañones! ¡Monos a las velas!', '', 25549),
(128082, 'esMX', 'La felicidad de la ignorancia es un regalo que les he dado, uno que no apreciarán hasta que sea demasiado tarde. Pero ya no hay vuelta atrás. Lo hecho, hecho está. Espero haber tomado la decisión correcta.', '', 25549),
(128081, 'esMX', 'El peso de mi decisión es una carga que me agobia el corazón, pero cada día, cuando veo sus sonrisas despreocupadas, la carga se hace un poco más liviana.', '', 25549),
(128080, 'esMX', 'Tal vez nuca me perdonen por lo que he hecho, pero al menos estarán a salvo. Por ahora, mi familia estará a salvo.', '', 25549),
(128079, 'esMX', '¡Ah, los cielos de mi hogar! Creí que nunca volvería a ver este mundo.', '', 25549),
(128078, 'esMX', 'El Falsario despreció mis talentos en vida. ¡Veamos cuál de los dos sobrevive a la batalla que se avecina!', '', 25549),
(128077, 'esMX', '¡Cuidado! El poder aún vibra dentro de este gólem ancestral. Sería mejor destruirlo antes de que la Legión le otorgue más poder.', '', 25549),
(128076, 'esMX', '¡Aj! ¡Este lugar apesta a titanes!', '', 25549),
(128075, 'esMX', 'Qué uso más peculiar de la energía de alma. Habrían logrado tantas cosas si hubieran sido más aplicados.', '', 25549),
(128074, 'esMX', '¡Detesto a los espíritus! Siempre parloteando sobre sus vidas pasadas. ¡Consume sus almas y acaba con ellos!', '', 25549),
(128073, 'esMX', 'Los naga son una raza corrompida. Poseen habilidades arcanas, pero carecen de la sutileza propia de mi pueblo.', '', 25549),
(128072, 'esMX', '', 'Así es, tío. Supongo que por lo menos esto es un comienzo....', 25549),
(128071, 'esMX', 'Sé que debo responder por muchos crímenes.', '', 25549),
(128070, 'esMX', '', '¡DEMONIOS! ¡TODOS USTEDES!', 25549),
(128069, 'esMX', 'Ese idiota creyó que yo no era más que un artilugio para recolectar poder. ¡Ahora ha pagado por su falta de visión!', '', 25549),
(128068, 'esMX', '', '¿Qué... sucede? Siento que... me hierve la sangre... Yo, yo…', 25549),
(128067, 'esMX', '%s parpadea, perplejo. Sus ojos brillan con energía vil.', '', 25549),
(128066, 'esMX', '¿Adoradores... de demonios?', '', 25549),
(128065, 'esMX', '¡Ah, mi viejo amo! ¡La hora de la venganza está cerca!', '', 25549),
(128064, 'esMX', 'Este es poderoso, pero estúpido. Sería un esbirro inútil.', '', 25549),
(128063, 'esMX', 'Conozco encantamientos ancestrales que podrían revelar la sangre vital de tu mundo. Este sería un lugar ideal para utilizarlos.', '', 25549),
(128062, 'esMX', '¿Lo sientes? La sangre vital de tu mundo fluye justo por debajo de la superficie de este lugar.', '', 25549),
(128061, 'esMX', 'Y aquí estamos, el lugar donde los tontos fueron exterminados. Recuerda, el coraje no reemplaza al poder.', '', 25549),
(128060, 'esMX', 'Tus habilidades han mejorado notablemente desde nuestro primer encuentro. Con un par de miles de años, quizás alcances el nivel de mis mejores aprendices.', '', 25549),
(128059, 'esMX', 'Este lugar es tan parecido a Argus... retorcido, devastado, destruido. ¡Me recuerda tanto a mi hogar!', '', 25549),
(128058, 'esMX', 'La última vez que viniste estuviste a punto de morir. Ahora tienes la fortuna de contar con mi compañía.', '', 25549),
(128057, 'esMX', '¿Hueles el olor a carne chamuscada en el viento? ¡Ah, el aroma de mi hogar!', '', 25549),
(128056, 'esMX', 'Solo una fracción del poder de la Legión habita este sitio. Aún quedan muchos horrores por enfrentar.', '', 25549),
(128055, 'esMX', 'La Legión ha conquistado esta costa. ¡Pero pronto nosotros conquistaremos a la Legión!', '', 25549),
(128054, 'esMX', '', 'Usa mi portón de la muerte o abre uno propio. De cualquier forma, nos veremos en Acherus.', 25549),
(128053, 'esMX', '', 'Todavía veo un poco borroso, pero puedo pelear.', 25549),
(128052, 'esMX', 'Alana be''lendor', '', 25549),
(128051, 'esMX', '¡Muere por reina hermosa!', '', 25549),
(128050, 'esMX', 'Estoy listo para enfrentarme a Kruul. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Kruul. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(128049, 'esMX', 'Harjatan... no pelea... tan bien...', '', 25549),
(128048, 'esMX', 'Harjatan... falló... a hermosa reina...', '', 25549),
(128047, 'esMX', '¡Hora de aplastar!', '', 25549),
(128046, 'esMX', '¡Ash''thero sanguine!', '', 25549),
(128045, 'esMX', '¡Vengan, amiguitos! ¡Aplasten!', '', 25549),
(128044, 'esMX', '¡Bal, lamer zhita!', '', 25549),
(128043, 'esMX', '', '¡Más muerte! ¡Más matanza!', 25549),
(128042, 'esMX', '', '¡Tú! ¡Tráeme la Maretista!', 25549),
(128041, 'esMX', '', '¡Ayuden a nuestro torpe campeón!', 25549),
(128040, 'esMX', '', '¡Esbirros! ¡A la batalla!', 25549),
(128039, 'esMX', '', '¡Bestia inútil! Nunca voy a entender por qué la reina lo apreciaba.', 25549),
(128038, 'esMX', '', '¡Silencio, idiota descerebrado! ¡Mátalos!', 25549),
(128037, 'esMX', '', '¡Harjatan! ¡Pulverízales los huesos!', 25549),
(128036, 'esMX', '', '¡Ya basta de fracasos! ¡Ahora se enfrentarán al verdadero poder de los naga!', 25549),
(128035, 'esMX', '', '¡Incompetentes! ¿Acaso debo ensuciarme las manos con esta basura?', 25549),
(128034, 'esMX', '', '¡Débiles! ¿Se atreven a decepcionar a nuestra reina?', 25549),
(128033, 'esMX', '', '¡Asesinen a los intrusos! ¡Recuperen lo que nos pertenece!', 25549),
(128032, 'esMX', '', 'Estos idiotas nos traen la Maretista. ¡Tal como lo predijo nuestra bendita reina!', 25549),
(128031, 'esMX', 'Estoy listo para enfrentarme a Raest. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Raest. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(128030, 'esMX', 'Estoy listo para enfrentarme a Xylem. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Xylem. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128028, 'esMX', 'Bien hecho. Con los demonios asesinados y los suministros recuperados, estamos un paso más cerca de asegurar la Costa Quebrada.', '', 25549),
(128027, 'esMX', 'Mortal insignificante. ¡No ganas nada! Arrodíllate... ¡o ARDERÁS!', '', 25549),
(128026, 'esMX', '', '¡Mis mascotas los devorarán enteros!', 25549),
(128025, 'esMX', '', '¡Las profundidades los devorarán!', 25549),
(128024, 'esMX', '', '¡Sus almas pertenecen a las profundidades!', 25549),
(128023, 'esMX', '', '¡Sufran el frío de las profundidades!', 25549),
(128022, 'esMX', '', '¡La muerte llega para llevárselos!', 25549),
(128021, 'esMX', '', '¡El poder del mar se alza!', 25549),
(128020, 'esMX', '', '¡Disfruten de este festín de carne!', 25549),
(128019, 'esMX', '', '¡Consúmanlos!', 25549),
(128018, 'esMX', '', 'Esta muerte... no es digna de mí...', 25549),
(128017, 'esMX', '', 'Ah. Qué... indignidad...', 25549),
(128016, 'esMX', '', 'El reinado de Azshara es absoluto... ¡Siempre lo será!', 25549),
(128015, 'esMX', '', 'Diez mil años, y los mortales siguen siendo igual de patéticos...', 25549),
(128014, 'esMX', '', '¡Carnada para los peces!', 25549),
(128013, 'esMX', '', '¡Hora de alimentar a los peces!', 25549),
(128012, 'esMX', '', '¡Enfréntate a tu fin, escoria mortal!', 25549),
(128011, 'esMX', '', '¡Reclamo sus vidas en nombre de Azshara!', 25549),
(128010, 'esMX', 'Elimina las fuerzas demoníacas de la playa y recupera los suministros que puedas para la invasión.', '', 25549),
(128009, 'esMX', 'Las ruinas de nuestro anterior asalto en estas orillas contienen suministros vitales para nuestros esfuerzos contra la Legión Ardiente.', '', 25549),
(128008, 'esMX', 'Lo lamento, Delas. Sé que pedirte perdón sería demasiado, pero debo pedirte ayuda.', '', 25549),
(128007, 'esMX', '', '¿Esto... esto es obra tuya? ¡¿Cómo pudiste?!', 25549),
(128006, 'esMX', 'Los espíritus están ligados a la Legión, forzados a cumplir con la voluntad de los demonios.', '', 25549),
(128005, 'esMX', 'Pero al final, el pacto que hice maldijo a nuestros ancestros con un destino peor que la muerte.', '', 25549),
(128004, 'esMX', '¡Tienes que entender! Solo quería proteger a nuestra familia...', '', 25549),
(128003, 'esMX', '', '¿Nerus? ¿Qué haces aquí, tío?', 25549),
(128002, 'esMX', '¡Libre al fin!', '', 25549),
(128001, 'esMX', '¡Al fin! La venganza... ¡la venganza es mía!', '', 25549),
(128000, 'esMX', '¡Tu espíritu resistente soporta la horrenda magia vil!', '¡Tu espíritu resistente soporta la horrenda magia vil!', 25549),
(127999, 'esMX', 'La Fauce de los Malditos busca escaparse de tu poder a medida que te acercas al Falsario.', 'La Fauce de los Malditos busca escaparse de tu poder a medida que te acercas al Falsario.', 25549),
(127998, 'esMX', '', 'Gracias, $Ghéroe:heroína;. Hoy les has hecho un gran favor a las tribus de Altamontaña.', 25549),
(127997, 'esMX', '', 'Aquí los Viltótem recibieron su instrucción demoníaca. ¡Purifica la caverna de su mal y envía a sus amos de regreso al Vacío Abisal!', 25549),
(127996, 'esMX', '', 'Me equivoqué. Parece que la presuntuosa "diosa" sigue teniendo poder aquí. En fin...', 25549),
(127995, 'esMX', '', '¡Celadoras, aseguren la catedral! Resistiremos aquí mientras nuestros aliados avanzan hacia la tumba de abajo.', 25549),
(127994, 'esMX', '', 'Perdona si mi guja termina en tu corazón, Illidan. Con tantos demonios, es difícil distinguirte entre toda esta escoria.', 25549),
(127993, 'esMX', '', '¡No me perdonaría que murieras a manos de otro, traidor!', 25549),
(127992, 'esMX', '¿Sigues con vida, Maiev?', '', 25549),
(127991, 'esMX', 'Yo me ocuparé de este flanco. ¿Podrás sobrevivir sin mí, celadora?', '', 25549),
(127990, 'esMX', 'Este mundo... será... de la Legión...', '', 25549),
(127989, 'esMX', '¡Su carne arderá!', '', 25549),
(127988, 'esMX', '¡Todo el poder de la Legión caerá sobre ustedes!', '', 25549),
(127987, 'esMX', '¡Su escudo ha caído! ¡No dejen sobrevivientes!', '', 25549),
(127986, 'esMX', '¡Infernales! ¡Arrasen con sus filas!', '', 25549),
(127985, 'esMX', '¡Demonios! ¡Destruyan ese escudo!', '', 25549),
(127984, 'esMX', '¡Legión! ¡Incinérenlos hasta los huesos!', '', 25549),
(127983, 'esMX', '¡Mi hacha quiere carne!', '', 25549),
(127982, 'esMX', '', 'Un vestigio de poder permanece en este templo destruido. ¡Debe ser nuestro! Vamos, entremos al círculo y tomémoslo.', 25549),
(127981, 'esMX', '', 'La figura enigmática extrae un vial con una sustancia viscosa del caldero.', 25549),
(127980, 'esMX', 'Este... es fuerte. No importa, estas almas le servirán bien al amo.', '', 25549),
(127979, 'esMX', '', '¡Salto poderoso!', 25549),
(127978, 'esMX', '', 'No tengo tiempo para esas supuestas frases ingeniosas. Así que solo me retiraré con estilo.', 25549),
(127977, 'esMX', '', 'Ruega que no volvamos a encontrarnos.', 25549),
(127976, 'esMX', '', 'No importa, ya conseguí lo que quería.', 25549),
(127975, 'esMX', '', '¡YO!', 25549),
(127974, 'esMX', '', 'Además, si te atreves a lastimar un solo cabello de la cabeza de mi dulce tauren, tendrás un VERDADERO problema...', 25549),
(127973, 'esMX', '', 'Como si alguien tan débil pudiera detenernos...', 25549),
(127972, 'esMX', '', '¿Quieres arruinar nuestro plan otra vez? ¡Ja!', 25549),
(127971, 'esMX', '', '¡Ey, tú! ¡Tú eres $Gel:la; que mencionó el tauren!', 25549),
(127970, 'esMX', 'Kil''jaeden envía su gratitud por habernos entregado la Égida en nuestras manos.', '', 25549),
(127969, 'esMX', '', 'Debes enfrentarte al Falsario en su propio terreno, donde es vulnerable. Ven, ¡saboreemos un bocado de su alma!', 25549),
(127968, 'esMX', '', 'Permíteme guiar tu mano en la batalla contra este simple sirviente. Aunque solo conserva una fracción del poder del titán caído, no sobrevivirás a su furia sin mis habilidades.', 25549),
(127967, 'esMX', '', 'Invasores que corrompen a otros invasores caóticamente... típico. Es mucho más útil guiarlos por el camino correcto, ¿no crees?', 25549),
(127966, 'esMX', '', 'Los elfos arrogantes de antaño tenían sus espíritus en muy alta estima. ¡Que indignidad tan deliciosa!', 25549),
(127965, 'esMX', '', 'Me encanta ver el sagrario de un gran enemigo profanado por el espíritu de sus propios adoradores.', 25549),
(127964, 'esMX', '', 'A veces parece que los naga ruegan por migajas de la mesa de la Legión. Pero la reina a la que sirven quiere más que eso.', 25549),
(127963, 'esMX', '', 'Desde que nacen, los señores del foso son gigantescos y estúpidos. De algún modo la Legión se las arregla para magnificar los dos atributos.', 25549),
(127962, 'esMX', '', 'Esta sí que ha sido una plaga para tu mundo durante mucho tiempo. No todos sus planes tuvieron éxito, pero los que prosperaron causaron una ruina indescriptible.', 25549),
(127961, 'esMX', '', 'Un bruto de la Legión destruyendo sabiduría invaluable... Imagínate.', 25549),
(127960, 'esMX', '', 'Siento que el pulso de tu mundo se acelera. Pronto todo quedará empapado de su sangre vital.', 25549),
(127959, 'esMX', '', 'Tus aliados me consideran una mala influencia. Sin embargo, lo único que he hecho ha sido impulsarlos por el camino que eligen.', 25549),
(127958, 'esMX', '', 'La Luz condenaría a tu clase a la obediencia y el estancamiento. Yo ofrezco los dones de la fuerza y la libertad. Espero que siempre recuerdes mi amabilidad.', 25549),
(127957, 'esMX', '', 'Fuiste una buena elección. Ningún otro portador se ha abierto paso matando por todo el continente como tú. Admiro tu persistencia.', 25549),
(127956, 'esMX', '', 'Esta tierra ha soportado muchas catástrofes. Los dos Cataclismos, la Purga... no tienes la menor idea.', 25549),
(127955, 'esMX', '', 'Pasó mucho tiempo hasta que pude regresar a la superficie después del Gran Cataclismo. Los naga son tan celosos de sus artefactos.', 25549),
(127954, 'esMX', '', 'Este conflicto no es más que una sombra de una guerra ancestral anterior a la interferencia de los titanes. Ejércitos innumerables se enfrentaron en una batalla incesante. Pero seguramente su pequeña guerra es impresionante... a su manera.', 25549),
(127953, 'esMX', '', 'Esta mísera escaramuza no es más que una distracción. La verdadera batalla llegará cuando el círculo esté completo.', 25549),
(127952, 'esMX', 'La victoria... final... será nuestra...', '', 25549),
(127951, 'esMX', '', 'Fue aquí, en las edades pasadas, que el Dios de las Profundidades perdió una gran batalla contra el Dios de Siete Cabezas. Pero como suele ocurrir, hasta la derrota benefició a N''Zoth.', 25549),
(127950, 'esMX', '', 'Ese edificio vil que se yergue sobre esta tierra no es nada comparado con la grandeza que habitó el lugar hace mucho tiempo.', 25549),
(127949, 'esMX', '', 'Este siempre fue un lugar de poder. Aegwynn fue guiada aquí, y los elfos antes que ella, y antes los trols. Y antes que ellos...', 25549),
(127948, 'esMX', '¡Entréguenme el escudo y les concederé una muerte rápida!', '', 25549),
(127947, 'esMX', '¡Qué amable de tu parte traerme la Égida!', '', 25549),
(127946, 'esMX', '¡Estoy harto de estos juegos! Veamos cómo se las arreglan sin su baratija.', '', 25549),
(127945, 'esMX', '¡Es tan divertido verlos sufrir!', '', 25549),
(127944, 'esMX', '¡No pueden resistir el poder de la Legión!', '', 25549),
(127943, 'esMX', '¡Cuidado con las sombras!', '', 25549),
(127942, 'esMX', '¿Huir? ¡Idiota! ¡Los traje hasta su muerte!', '', 25549),
(127941, 'esMX', '', 'Creo que estas tierras no han visto una masacre semejante desde la Batalla de K''tanth. Ha pasado tanto tiempo...', 25549),
(127940, 'esMX', '', '¿No es este el sitio que los mortales consideran su peor humillación? Espero que esta vez tengan más suerte...', 25549),
(127939, 'esMX', '', 'Hay tanta muerte aquí... ¡tanto poder!', 25549),
(127938, 'esMX', '¡Ya no tienes a dónde huir, demonio!', '', 25549),
(127937, 'esMX', 'Mantén tu postura solemne si lo deseas, Maiev, pero por el momento haz lo que mejor sabes hacer y sígueme.', '', 25549),
(127936, 'esMX', '', '¿Realmente creías que podías escapar de mí, Illidan? Si vuelves a huir, te encadenaré como la bestia que eres.', 25549),
(127935, 'esMX', 'Yo encontraré al Señor del terror. Ustedes encárguense de la escoria.', '', 25549),
(127934, 'esMX', 'Los demonios bloquean el camino, pero no resistirán nuestra furia.', '', 25549),
(127933, 'esMX', '', 'Yo seguiré buscando a Illidan. Ustedes encárguense de esas abominaciones.', 25549),
(127932, 'esMX', '', '¡Illidan nos dejó un desastre! No te alejes... nos abriremos paso entre estos demonios.', 25549),
(127931, 'esMX', '', '¡Illidan! ¡Maldigo a ese impetuoso cazador de demonios!', 25549),
(127930, 'esMX', 'Ah, al fin han llegado nuestros invitados de honor. ¡Estoy ansioso por arrancarte esos cuernos del cráneo, Traidor!', '', 25549),
(127929, 'esMX', '¡No hay ningún escondite donde no pueda encontrarte, demonio!', '', 25549),
(127928, 'esMX', '¿Funcionó?', '', 25549),
(127923, 'esMX', '¡Excelente trabajo, $GArchimago:Archimaga;! Sabía que triunfarías. ¡Por $Gel Archimago:la Archimaga! ¡Por el Tirisgarde!', '', 25549),
(127922, 'esMX', 'El negocio va bien.$b$bMuy bien.$b$b<Nargle mete unas pocas monedas en su bolsillo.>$b$bEl señor Tragonublo estará complacido. ¡Sigue así!', '', 25549),
(127921, 'esMX', 'La Piedra de alma está lista. ¡Usa la matriz arcana para activar las defensas de la ciudad!', '', 25549),
(127920, 'esMX', '', 'Ah, no importa. Espera a que Mograine nos vea volando. ¡Se quedará helado!', 25549),
(127919, 'esMX', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_LORDMARROWGAR:20|t¡El %s tiembla y escupe el Anfitrión desolado! ¡Se sobrecargan los conductos de almas!', '', 25549),
(127918, 'esMX', 'Muy bien.', 'Muy bien.', 25549),
(127917, 'esMX', '¿Y cuál es la causa de esta estampida, eh?', '¿Y cuál es la causa de esta estampida, eh?', 25549),
(127916, 'esMX', '¿Cuál es el plan?', '¿Cuál es el plan?', 25549),
(127915, 'esMX', '¿Acaso me viste cara de brujo? No me imagino por qué. Tal vez sea una estampida de temporada o algo así, en la que los corceles nefastos corren para migrar, o aparearse, o están huyendo...$b$b¡O quizás solo están corriendo por aquí para impedir que entreguemos la cerveza!', '', 25549),
(127914, 'esMX', '¡Es simple! Solo debes subirte a ese barril. $b$b¡Con tu velocidad seguro podrás esquivar la estampida y entregar la cerveza! Es como siempre decía mi maestro: "Si puedes esquivar un caballo sobre un barril, puedes esquivar un golpe".$b$bDigamos que mi entrenamiento fue... exótico. Mira, solo súbete a ese barril, sigue rodando hasta que llegues a la patrulla, ¡y ten cuidado con los caballos en el camino!', '', 25549),
(127913, 'esMX', '¡Oh, vaya que me alegra verte! ¡Nuestros hermanos y hermanas están peleando en la rampa, pero ya no tienen más cerveza!$b$bEstas bestias confundidas están pasando en estampida, así que no podemos llevar los barriles a menos que alguien...$b$bEso me da una idea...', '', 25549),
(127912, 'esMX', '', '|TInterface\\Icons\\Spell_Deathknight_Defile:20|t¡Sin almas en el Reino espiritual, %s desata su furia con |cFFFF0000|Hspell:236507|h[Óbito]|h|r!', 25549),
(127911, 'esMX', '|TInterface\\Icons\\Spell_Deathknight_Defile:20|t¡Sin almas para corromper en el Reino corpóreo, el %s desata su furia con |cFFFF0000|Hspell:236507|h[Óbito]|h|r!', '', 25549),
(127910, 'esMX', '', '¡Juntos, destrozaremos los huesos de innumerables demonios!', 25549),
(127909, 'esMX', '', '|TInterface\\Icons\\SPELL_SHADOW_SHADESOFDARKNESS:20|t¡%s comienza a liberar una oleada de |cFFFF0000|Hspell:236075|h[Almas gemebundas]|h|r!', 25549),
(127908, 'esMX', '', '|TInterface\\Icons\\ABILITY_WARLOCK_SOULLINK:20|t¡%s encadena la esencia viviente con |cFFFF0000|Hspell:236449|h[Nexo de almas]|h|r!', 25549),
(127907, 'esMX', '|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t¡El %s comienza a emitir una serie de |cFFFF0000|Hspell:236011|h[Gritos atormentados]|h|r!', '', 25549),
(127906, 'esMX', '', '|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t¡%s invoca al poderoso Sarukel para que abra sus |cFFFF0000|Hspell:234621|h[Fauces devoradoras]|h|r!', 25549),
(127905, 'esMX', '', '|TInterface\\Icons\\Ability_Butcher_Whirl.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:232722|h[Tornado cortante]|h|r!', 25549),
(127904, 'esMX', '¡Valarjar de Bastión del cielo! ¡Que las celebraciones para $Gnuestro campeón:nuestra campeona; resuenen en todos los muros!', '', 25549),
(127903, 'esMX', 'Con eso ganamos un breve receso. Ahora mis illidari podrán defender el frente.', '', 25549),
(127902, 'esMX', 'Necesitamos a todos en el frente de batalla. ¡Se aproxima otra oleada de demonios!', '', 25549),
(127901, 'esMX', '', 'La Legión subestima la persistencia y determinación de la naturaleza... ¡y las tuyas, según veo!', 25549),
(127900, 'esMX', '', '¡Hasta la vida salvaje de Altamontaña se alza contra los demonios! Destruye a los infernales y encuentra la fuente de su incursión.', 25549),
(127899, 'esMX', '¡A Tótem del Trueno! Mis jinetes controlarán los cielos; tú encargate de las tropas terrestres.', '', 25549),
(127898, 'esMX', '', '¡Excelente pelea! Nuestras fuerzas están avanz...', 25549),
(127897, 'esMX', '', '¡La Legión Ardiente marcha hacia Altamontaña! Nuestros aliados se enfrentan a demonios por todo el terreno. Para cambiar el curso de la batalla, $Gcampeón:campeona;, ¡debes atacar el grueso de sus fuerzas!', 25549),
(127891, 'esMX', 'La Torre de los magos está destruida, pero pronto estará en pie nuevamente.', 'La Torre de los magos está destruida, pero pronto estará en pie nuevamente.', 25549),
(127890, 'esMX', '¡Están atacando la Torre de los magos!', '¡Están atacando la Torre de los magos!', 25549),
(127889, 'esMX', 'La Torre de los magos está en construcción.', 'La Torre de los magos está en construcción.', 25549),
(127869, 'esMX', '¡Perseguiré a los trols hasta su cueva y encontraré la cerveza Martillo de tormenta!', '', 25549),
(127868, 'esMX', '¡Soren, viejo amigo, busca al jabalí que se llevó nuestra cerveza rubia de Theramore!', '', 25549),
(127867, 'esMX', '¡Jona, Joren, vayan a buscar el Gnomenbrau! ¡Un grupo de troggs se lo llevó!', '', 25549),
(127866, 'esMX', '¡Se llevaron los barriles!', '', 25549),
(127865, 'esMX', 'No puedo llevarte más lejos. Esperemos que tus compañeros tengan la fuerza suficiente para ayudarte a completar el camino.', '', 25549),
(127864, 'esMX', '¿Qué... qué me sucedió?', '', 25549),
(127863, 'esMX', 'No... No me siento bien.', '', 25549),
(127862, 'esMX', 'Esa cosa... se metió en mi cabeza. ¡No podía detenerme!', '', 25549),
(127861, 'esMX', '¿Dónde... dónde estoy?', '', 25549),
(127860, 'esMX', 'Mi cabeza... ¿qué pasó?', '', 25549),
(127859, 'esMX', '¿Qué... qué pasó? ¡Esto no es la cabaña!', '', 25549),
(127858, 'esMX', '¡Ey, atrapa eso!', '', 25549),
(127857, 'esMX', '¡Nos atacan!', '', 25549),
(127856, 'esMX', '¡Piensa rápido!', '', 25549),
(127855, 'esMX', '¡Ahí va eso!', '', 25549),
(127854, 'esMX', '¡Esquiva esto!', '', 25549),
(127853, 'esMX', 'Hay mucho movimiento en las Minas de la Muerte. \n\nSupongo que el lugar está infestado con todo tipo de criaturas. ¿Vamos a investigar?', '', 25549),
(127852, 'esMX', 'Llévame a las Minas de la Muerte.', 'Llévame a las Minas de la Muerte.', 25549),
(127836, 'esMX', 'Quiero donar suministros bélicos a la Torre de los Magos.', 'Quiero donar suministros bélicos a la Torre de los Magos.', 25549),
(127835, 'esMX', '¿En qué puedo ayudarte?', '¿En qué puedo ayudarte?', 25549),
(127834, 'esMX', '¡Eres tan $Gpequeño:pequeña;! Es como jugar con un conejo.', '', 25549),
(127833, 'esMX', 'Tu estilo de pelea no me impresiona ni me interesa. Pronto caerás ante mi fuerza.', '', 25549),
(127832, 'esMX', 'Me parece muy divertido que sigas peleando, aunque estés $Gdestinado:destinada; a perder.', '', 25549),
(127831, 'esMX', 'Teletranspórtame a la siguiente taberna.', 'Teletranspórtame a la siguiente taberna.', 25549),
(127830, 'esMX', '¡Hoy es un día de júbilo! ¡Hemos encontrado las joyas!', '', 25549),
(127829, 'esMX', '¡Terminen sus bebidas! ¡Nos vamos en menos de un minuto!', '¡Terminen sus bebidas! ¡Nos vamos en menos de un minuto!', 25549),
(127828, 'esMX', 'Ya he completado mi entrenamiento.', 'Ya he completado mi entrenamiento.', 25549),
(127827, 'esMX', 'Nuestros jinetes se encargarán ahora. Sigue peleando, $Gcampeón:campeóna;.', '', 25549),
(127826, 'esMX', 'Nuestros jinetes luchan contra la Legión en el cielo. Ayuda a los caídos. ¡Debemos mantener esta ubicación!', '', 25549),
(127825, 'esMX', '', 'Tu victoria trae esperanza a los corazones de mi pueblo. ¡La Legión Ardiente jamás controlará nuestras tierras!', 25549),
(127824, 'esMX', '', 'Puedes confiar en mí para hacer lo que sea necesario.', 25549),
(127823, 'esMX', '', '¡Mi voluntad es inquebrantable!', 25549),
(127822, 'esMX', '', 'Esta derrota no me detendrá.', 25549),
(127821, 'esMX', '', 'Sigue sin mí. Te alcanzaré luego.', 25549),
(127820, 'esMX', '', 'Los débiles siempre perecerán.', 25549),
(127819, 'esMX', '', 'No había otro final posible.', 25549),
(127818, 'esMX', '', 'Este es el destino que mereces.', 25549),
(127817, 'esMX', '', '¡Lo disfrutaré tanto!', 25549),
(127816, 'esMX', '', '¡Morirás! ¡Y seré yo quien te mate!', 25549),
(127815, 'esMX', '', '¡Corre si te atreves, pero no llegarás lejos!', 25549),
(127814, 'esMX', '', 'Protegeremos estas tierras, juntos.', 25549),
(127813, 'esMX', '', 'Estoy aquí para ocupar mi lugar a tu lado.', 25549),
(127812, 'esMX', '', 'Debes mantenerte alerta, $GMaestro de caza:Maestra de caza;. No sabemos qué peligros acechan en las cercanías.', 25549),
(127811, 'esMX', '', 'Si no te detienes ahora, me encargaré de que D''Bynn lo haga.', 25549),
(127810, 'esMX', '', '¡Estás cruzando una línea de la que no hay retorno!', 25549),
(127809, 'esMX', '', 'Seguro que sabes otros trucos, ¿no?', 25549),
(127808, 'esMX', '', 'Veo que eres persistente, ¿eh?', 25549),
(127807, 'esMX', '', 'Me caes mejor cuando no hablas.', 25549),
(127806, 'esMX', '', 'Tienes toda mi atención.', 25549),
(127805, 'esMX', '', 'Mantente a salvo.', 25549),
(127804, 'esMX', '', 'Permanezcan alerta.', 25549),
(127803, 'esMX', '', 'Adiós.', 25549),
(127802, 'esMX', '', '¿Qué necesitas?', 25549),
(127801, 'esMX', '', '¿Puedo ayudarte?', 25549),
(127800, 'esMX', '', '¿Sí?', 25549),
(127799, 'esMX', 'Haré lo que sea necesario en nombre de la Cosecha Oscura.', '', 25549),
(127798, 'esMX', '¡Conocerás mi poder!', '', 25549),
(127797, 'esMX', 'No te detengas por mí.', '', 25549),
(127796, 'esMX', 'Me siento impotente...', '', 25549),
(127795, 'esMX', 'Necesito un momento para recuperar fuerzas.', '', 25549),
(127794, 'esMX', 'Creo que fue demasiado fácil.', '', 25549),
(127793, 'esMX', '¡Nuestro poder crece!', '', 25549),
(127792, 'esMX', 'Nuestro poder no tiene comparación.', '', 25549),
(127791, 'esMX', '¡Este será tu fin!', '', 25549),
(127790, 'esMX', '¡No estás a la altura de nuestro poder!', '', 25549),
(127789, 'esMX', '¡Siente el poder de la Cosecha Oscura!', '', 25549),
(127788, 'esMX', '¡Nuestros enemigos caerán!', '', 25549),
(127787, 'esMX', 'Hay tanto poder por descubrir en este mundo.', '', 25549),
(127786, 'esMX', 'Es un honor pelear junto a un poder tan grandioso.', '', 25549),
(127785, 'esMX', 'Jubeka tendría que haberte desterrado.', '', 25549),
(127784, 'esMX', '¿Estás seguro de que quieres despertar al demonio?', '', 25549),
(127783, 'esMX', '¡Te recomiendo que no juegues conmigo!', '', 25549),
(127782, 'esMX', '¡Seguramente el líder de la Cosecha Oscura no puede darse el lujo de perder el tiempo así!', '', 25549),
(127781, 'esMX', '¿Qué te sucede?', '', 25549),
(127780, 'esMX', 'Hasta la próxima.', '', 25549),
(127779, 'esMX', 'Adiós.', '', 25549),
(127778, 'esMX', 'Buen viaje.', '', 25549),
(127777, 'esMX', '¿Sí?', '', 25549),
(127776, 'esMX', '¿Como puedo ayudarte?', '', 25549),
(127775, 'esMX', 'Hola.', '', 25549),
(127774, 'esMX', '', 'Y yo que creía que el molesto era Roland.', 25549),
(127773, 'esMX', '', 'Esto no acabará bien para ti.', 25549),
(127772, 'esMX', '', '¡Desaparece de mi vista!', 25549),
(127771, 'esMX', '', '¡Fuera!', 25549),
(127770, 'esMX', '', '¿Te crees muy inteligente?', 25549),
(127769, 'esMX', '', 'Estás poniendo a prueba mi paciencia.', 25549),
(127768, 'esMX', '', 'Adiós.', 25549),
(127767, 'esMX', '', 'Que las sombras te amparen.', 25549),
(127766, 'esMX', '', 'Cuídate.', 25549),
(127765, 'esMX', '', '¿Cómo puedo ayudarte?', 25549),
(127764, 'esMX', '', '¿Qué necesitas?', 25549),
(127763, 'esMX', '', '¿Sí?', 25549),
(127762, 'esMX', '', 'Esto debería ser interesante...', 25549),
(127761, 'esMX', '', 'Esta derrota es solo temporal.', 25549),
(127760, 'esMX', '', 'Esto no me lo esperaba.', 25549),
(127759, 'esMX', '', 'Solo necesitaré un momento.', 25549),
(127758, 'esMX', '', 'Tu lucha ha terminado.', 25549),
(127757, 'esMX', '', 'Tú te lo buscaste.', 25549),
(127756, 'esMX', '', 'El vacío espera.', 25549),
(127755, 'esMX', '', '¡Te purgaré de este mundo!', 25549),
(127754, 'esMX', '', '¡Sentirás mi ira!', 25549),
(127753, 'esMX', '', 'Tu hora se acerca.', 25549),
(127752, 'esMX', '', '¡Nuestros enemigos se ahogarán en las sombras!', 25549),
(127751, 'esMX', '', 'Estoy aquí para ayudar.', 25549),
(127750, 'esMX', '', 'No tienes que hacer esto sin ayuda.', 25549),
(127749, 'esMX', '', '¿Qué sorpresas nos esperan?', 25549),
(127748, 'esMX', 'Esto se tiene que terminar.', '', 25549),
(127747, 'esMX', 'Esto no me divierte.', '', 25549),
(127746, 'esMX', '¿De verdad me merezco esto?', '', 25549),
(127745, 'esMX', '¿No tienes mejores cosas que hacer?', '', 25549),
(127744, 'esMX', '¿Así es como debo pagar por mis errores?', '', 25549),
(127743, 'esMX', 'Ande''thoras-ethil.', '', 25549),
(127742, 'esMX', 'Elune-adore.', '', 25549),
(127741, 'esMX', 'Buen viaje.', '', 25549),
(127740, 'esMX', 'Qué bueno verte.', '', 25549),
(127739, 'esMX', 'Qué gusto saludarte.', '', 25549),
(127738, 'esMX', 'Ishnu-alah.', '', 25549),
(127737, 'esMX', '', '¡Si no me concedes el honor, entonces te destruiré! ¡$GCampeón:Campeona;, ayúdame a acabar con este miserable!', 25549),
(127736, 'esMX', '', '¿Así que no me enfrentarás en un combate singular? ¡Los huesos sagrados de nuestros ancestros se resquebrajarían ante semejante deshonra!', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127735, 'esMX', 'Niña tonta. ¡Estos huesos me obedecen a mí, no a tu honor idealizado!', '', 25549),
(127734, 'esMX', 'Haré lo que me pidan.', '', 25549),
(127733, 'esMX', '¡Lucho por $Gel Alto señor:la Alta señora;!', '', 25549),
(127732, 'esMX', 'Debes seguir sin mí.', '', 25549),
(127731, 'esMX', 'Necesito descansar un momento.', '', 25549),
(127730, 'esMX', 'Mi espíritu se debilita...', '', 25549),
(127729, 'esMX', 'Nuestra voluntad es fuerte.', '', 25549),
(127728, 'esMX', 'Nos impondremos.', '', 25549),
(127727, 'esMX', 'La sentencia será rápida y certera.', '', 25549),
(127726, 'esMX', '¡Bandu thoribas!', '', 25549),
(127725, 'esMX', '¡No mostraré piedad!', '', 25549),
(127724, 'esMX', '¡No escaparás del juicio!', '', 25549),
(127723, 'esMX', 'Demostraré que soy digno.', '', 25549),
(127722, 'esMX', 'Es un honor caminar a tu lado, $GAlto señor:Alta señora;.', '', 25549),
(127721, 'esMX', 'Debo pagar por mis errores.', '', 25549),
(127720, 'esMX', '', 'En efecto, sí.\n\nUna escudera errante pasó hace poco tiempo y acampó fuera del poblado. Se quedó solo el tiempo suficiente para comprar suministros y evitó todo tipo de contacto visual durante su estadía.\n\nIba a visitarla para averiguar qué hacía aquí, pero puedes ir en mi lugar. Encontrarás su campamento en la playa del este.', 25549),
(127719, 'esMX', '¿No has visto pasar por aquí a una vrykul que llamara tu atención?', '¿No has visto pasar por aquí a una vrykul que llamara tu atención?', 25549),
(127718, 'esMX', '', 'Te estoy vigilando, $Gforastero:forastera;.', 25549),
(127717, 'esMX', '', 'Estoy familiarizada con la profecía valkyra de los Faldrottin, pero no he leído el texto. Permíteme ver los pergaminos que encontraste.\n\n<Bryna lee el texto de los pergaminos.>\n\n¡Si estos pergaminos están en lo correcto, significa que tenemos a la heredera de Skovald entre nosotros! No importa lo que crean las valkyra; nos harás un gran favor si te la llevas de aquí.\n\nBusca a Yngvild en la torre del poblado. Ella se mantiene alerta a las personas que van y vienen en Jandvik, y lo habría notado si alguien importante hubiera pasado últimamente.', 25549),
(127716, 'esMX', 'Slodi dijo que tú podrías ayudarme a encontrar al vrykul que figura en estos pergaminos.', 'Slodi dijo que tú podrías ayudarme a encontrar al vrykul que figura en estos pergaminos.', 25549),
(127715, 'esMX', '', 'Oí el cuerno de Slodi. Supongo que tú eres $Gel forastero:la forastera; que estaba anunciando.', 25549),
(127714, 'esMX', '¡Pobres cachorros! Al menos los salvaste de convertirse en esclavos de la Legión. Gracias, $Gcampeón:campeona;.', '', 25549),
(127713, 'esMX', 'No sé por qué te interesas en la profecía vrykul, pero los pergaminos que tienes parecen genuinos. Les avisaré a los vrykul de Jandvik para que te dejen pasar y puedas buscar quien buscas. \n\nLa sacerdotisa Bryna es la más instruida de la aldea. Quizás debas buscarla.', '', 25549),
(127712, 'esMX', 'No sé mucho sobre profecías, pero hemos visto caras nuevas en Jandvik desde la caída de Skovald.\n\nDeberías hablar con la sacerdotisda Bryna. Su morada está en el centro del poblado. Tal vez sepa algo sobre esa profecía.', '', 25549),
(127711, 'esMX', 'Estoy buscando al vrykul mencionado en estos pergaminos.', 'Estoy buscando al vrykul mencionado en estos pergaminos.', 25549),
(127710, 'esMX', 'Anda con cuidado, $c. A los vrykul de Jandvik no les agradan los forasteros.', '', 25549),
(127709, 'esMX', 'Saludos, $c. \n\nConozco el edicto de Toryl: mi cuchilla no te hará ningún daño.', '', 25549),
(127708, 'esMX', 'La Legión está corrompiendo a los lobos de las Colinas Aulladoras para atacar Cuerno del Cielo. ¡Hay que detener estos rituales viles!', '', 25549),
(127707, 'esMX', '¿Te atreves a interrumpirme?', '', 25549),
(127706, 'esMX', 'Hay algo... extraño... en ti.', '', 25549),
(127705, 'esMX', 'Ni se te ocurra robar nada. Estamos vigilando. Siempre vigilamos.', '', 25549),
(127704, 'esMX', 'Saludos, $ct $n. ¡Mi furia contra la Legión Ardiente es infinita!', '', 25549),
(127703, 'esMX', '¿Estás tratando de escaparte con algo?', '', 25549),
(127702, 'esMX', 'Vuelve al trabajo o te enviaré a limpiar las jaulas del foso.', '', 25549),
(127701, 'esMX', '¿Te atreves a dirigirme la palabra?', '', 25549),
(127700, 'esMX', 'Si no sabes cuál es tu lugar, yo te lo recordaré.', '', 25549),
(127699, 'esMX', 'Vuelve al trabajo.', '', 25549),
(127698, 'esMX', 'Ah, $n. Sabía que lo lograrías. Estaré listo para enfrentarme a la Legión de inmediato.', '', 25549),
(127697, 'esMX', 'Ya van dos veces que casi me matan los demonios. No habrá una tercera oportunidad.', '', 25549),
(127696, 'esMX', '', 'No te arrepentirás de esta decisión, Hoja de las sombras. ¡Eliminaré a todo demonio o conspirador de la Legión que se cruce en mi camino!', 25549),
(127695, 'esMX', '¡Ahora conocerás tu fin!', '¡Ahora conocerás tu fin!', 25549),
(127694, 'esMX', 'Tus esfuerzos son en vano.', 'Tus esfuerzos son en vano.', 25549),
(127693, 'esMX', '¿Te atreves a interrumpir a un sirviente de la Legión?', '¿Te atreves a interrumpir a un sirviente de la Legión?', 25549),
(127692, 'esMX', 'Tu hora se acerca.', 'Tu hora se acerca.', 25549),
(127691, 'esMX', 'Tus tesoros son pequeños y opacos. Deberías dármelos para que yo pueda "deshacerme de ellos".', '', 25549),
(127690, 'esMX', '¿Quién te envió? ¿Fue Haraposo? Dile que fue Dienteflojo el que se llevó su tesoro. ¡No fui yo!', '', 25549),
(127689, 'esMX', '', 'No te desharás de los Tótem siniestro tan fácilmente, criatura. Nos ganaremos nuestro lugar.', 25549),
(127688, 'esMX', 'A Soplalón y a Flivelina los enviaron al laberinto y no se supo nada más de ellos. Así que muévete o harás que los auditores nos envíen a los dos al laberinto.', '', 25549),
(127687, 'esMX', '¿Qué le pasa a tu rostro?', '', 25549),
(127686, 'esMX', 'Shh. Los auditores podrían oírte.', '', 25549),
(127685, 'esMX', '¡Deja mis tesoros en paz!', '', 25549),
(127684, 'esMX', 'Qué nariz tan bonita para morder.', '', 25549),
(127683, 'esMX', '¿Crees que eso es una mochila grande? ¡Ja! He visto enanos y niños pequeños cargar más peso que tú.', '', 25549),
(127682, 'esMX', '', 'Empiezo a aburrirme. Dinos lo que queremos saber o enfréntate a tu perdición.', 25549),
(127681, 'esMX', '', '¡Habla!', 25549),
(127680, 'esMX', '', 'Estoy cansada de estos juegos. Habla, o muere.', 25549),
(127679, 'esMX', '', '¿Qué están planeando, demonio?', 25549),
(127678, 'esMX', '', 'No puedes negarte conmigo. Habla.', 25549),
(127677, 'esMX', '', 'Me DARÁS lo que quiero, demonio.', 25549),
(127676, 'esMX', '', '¡Nunca tendrás oportunidad contra la Legión!', 25549),
(127675, 'esMX', '', '¡No eres rival para mí y mis sabuesos!', 25549),
(127674, 'esMX', 'Porque sé más sobre viajes demoníacos que tú. Ponte a estudiar.', '', 25549),
(127673, 'esMX', '¿Cómo llegaste al portal antes que yo?', '¿Cómo llegaste al portal antes que yo?', 25549),
(127672, 'esMX', '¿Transformarme?', '¿Transformarme?', 25549),
(127671, 'esMX', 'Así que este es el lugar donde estos ladrones infernales guardan sus baratijas.$b$bBueno, ya que estamos aquí podríamos recuperar algunos de los objetos. Te preparé una lista de compras/robo con lo que debes conseguir.\n\nEste sería el momento en el que un mago experto en ilusionismo te toca con su varita para que te veas como uno de ellos. ¡Pf! Ilusiones. ¿Dónde quedó el compromiso? \n\nYo te voy a TRANSFORMAR en una de esas cosas. ¿Tienes dotes para la actuación?', '', 25549),
(127670, 'esMX', 'Excelente trabajo. Debemos reunir al consejo. Necesitamos sus fuerzas combinadas para atrapar a una bestia de semejante poder. Es la única manera.', '', 25549),
(127669, 'esMX', '¡Rápido, esclaviza al corcel iracundo antes de que escape!', '', 25549),
(127668, 'esMX', 'Imposible...', '', 25549),
(127667, 'esMX', '¡El corcel iracundo nunca será tuyo, mortal!', '', 25549),
(127666, 'esMX', '¡Yo mismo acabaré contigo!', '', 25549),
(127665, 'esMX', 'Puede que mis esbirros insignificantes hayan caído, pero la victoria no será tuya.', '', 25549),
(127664, 'esMX', '¡¿Están locos?! ¡Nos destruirán a todos!', '', 25549),
(127663, 'esMX', 'Los acólitos están formando un círculo ritual. ¡Hagas lo que hagas, no dejes sobrevivientes suficientes para completarlo!', '', 25549),
(127662, 'esMX', '¡Arax''ath protege a sus acólitos con un escudo vil! ¡Tendrás que disiparlo para eliminarlos!', '', 25549),
(127661, 'esMX', '¡Acólitos! ¡Que llueva fuego sobre este insecto!', '', 25549),
(127660, 'esMX', '¡Cuidado, $gbrujo:bruja;! La mordida de estos manáfagos es venenosa para los mortales. ¡Aunque claro que no deberían ser ningún problema para tus demonios!', '', 25549),
(127659, 'esMX', '¡Mis sabuesos te arrancarán la carne de los huesos!', '', 25549),
(127658, 'esMX', '¡¿Qué?! ¿Te atreves a invocar a mi corcel?', '', 25549),
(127657, 'esMX', '¡El camino está abierto, $Gbrujo:bruja;! ¡Activa la piedra de invocación!', '', 25549),
(127656, 'esMX', '¿Qué es esto? ¡¿Un mortal quiere espiar mi reino?!', '', 25549),
(127655, 'esMX', 'Ah, qué bueno volver a verte, $n.', '', 25549),
(127654, 'esMX', '¡Vae Xoroth!', '', 25549),
(127653, 'esMX', '¡Rak-ath varus mir''enon!', '', 25549),
(127652, 'esMX', 'Ahora, ¡lancémonos al Vacío Abisal y tomemos lo que nos pertenece!', '', 25549),
(127651, 'esMX', '', 'Hel''nurath te cazará, $c...', 25549),
(127650, 'esMX', '', '¡Te usaré como alimento para los corceles nefastos!', 25549),
(127649, 'esMX', 'Un momento... ¿¡qué estoy haciendo!? ¡Zuriwa me cortará la cabeza! ¡Aléjate de mí!', 'Un momento... ¿¡qué estoy haciendo!? ¡Zuriwa me cortará la cabeza! ¡Aléjate de mí!', 25549),
(127648, 'esMX', 'Busca a Zuriwa... Ella nos observa... desde su torre.', 'Busca a Zuriwa... Ella nos observa... desde su torre.', 25549),
(127647, 'esMX', '¿Quieres a... nuestro líder? Claro... por ti, lo que sea...', '¿Quieres a... nuestro líder? Claro... por ti, lo que sea...', 25549),
(127646, 'esMX', '...¿qué estoy diciendo? ¡Muere, $Gbrujo:bruja;!', '...¿qué estoy diciendo? ¡Muere, $Gbrujo:bruja;!', 25549),
(127645, 'esMX', 'No... no... ¡no traicionaré a la Legión!', 'No... no... ¡no traicionaré a la Legión!', 25549),
(127644, 'esMX', '...¡suficiente! ¡Acabaré contigo, demonio!', '...¡suficiente! ¡Acabaré contigo, demonio!', 25549),
(127643, 'esMX', '¿Líder, dices? Puedes darme órdenes cuando quieras...', '¿Líder, dices? Puedes darme órdenes cuando quieras...', 25549),
(127642, 'esMX', '¿Qué? ¿No tengo el liderazgo suficiente para ti?', '¿Qué? ¿No tengo el liderazgo suficiente para ti?', 25549),
(127641, 'esMX', '¿Nuestro líder? No lo sé...', '¿Nuestro líder? No lo sé...', 25549),
(127640, 'esMX', 'Bueno... si lo dices así...', 'Bueno... si lo dices así...', 25549),
(127639, 'esMX', 'Oh... qué hemosas... pezuñas tienes...', 'Oh... qué hemosas... pezuñas tienes...', 25549),
(127638, 'esMX', 'Ahhh... qué bien... Espera, ¿qué dijiste que querías?', 'Ahhh... qué bien... Espera, ¿qué dijiste que querías?', 25549),
(127637, 'esMX', 'Con los materiales que has conseguido, estamos encaminados para apoderarnos del corcel iracundo.\n\nMientras nosotros construimos el portal, tú deberías concentrar tus esfuerzos en buscar una carnada que atraiga a Arax''ath y su corcel iracundo.', '', 25549),
(127636, 'esMX', 'Para atraer a Arax''ath, tendremos que crear un portal capaz de mantener un enlace con Xoroth. Será mucho más difícil que nuestros portales comunes, y necesitará muchos más recursos.', '', 25549),
(127635, 'esMX', 'Bien, tenemos preparativos por delante.', '', 25549),
(127634, 'esMX', 'Excelente. Sabía que no me decepcionarías.', '', 25549),
(127633, 'esMX', '¡El corcel iracundo será mío!', '¡El corcel iracundo será mío!', 25549),
(127632, 'esMX', 'Si bien el lenguavermis no sabía demasiado sobre el corcel, es obvio que Hel''nurath solo ha podido crear uno hasta el momento. Se lo ha regalado a su mejor general, el caballero vil Arax''ath. La parte difícil es que Arax''ath no suele abandonar Xoroth, sino que prefiere guiar a sus ejércitos desde la distancia.\n\nSin embargo, creo que podríamos sacarlo de su escondite. Y para eso necesito tu ayuda.\n\n¿Estás $Glisto:lista; para el desafío?', '', 25549),
(127631, 'esMX', 'Continúa...', 'Continúa...', 25549),
(127630, 'esMX', 'Iré directo al grano:\n\nDesde mi "desplazamiento" de las Las Estepas Ardientes a manos de los orcos Roca Negra, he continuado con mi investigación sobre los corceles nefastos de Xoroth en secreto. Durante uno de mis rituales, logré capturar a un extraño demonio del otro lado, uno de los que llamamos "lenguavermis".\n\nTras varias semanas de interrogatorio, el demonio reveló que Lord Hel''nurath ha estado trabajando para crear un corcel más poderoso para los caballeros viles de Xoroth.\n\nLos llama corceles iracundos.', '', 25549),
(127629, 'esMX', '¿Por qué me hiciste venir aquí?', '¿Por qué me hiciste venir aquí?', 25549),
(127628, 'esMX', 'Es un placer conocerte, $GSeñor abisal:Señora abisal;.', '', 25549),
(127627, 'esMX', 'Encontrémonos en la Falla Cicatriz Aterradora y te lo explicaré.', '', 25549),
(127626, 'esMX', 'Ha pasado mucho tiempo desde la primera vez que perforamos el velo que cubría el plano de Xoroth, pero una nueva oportunidad exige que regresemos al reino de los corceles nefastos.', '', 25549),
(127625, 'esMX', 'Saludos, $Gbrujo:bruja;. Me presento ante tu consejo con un descubrimiento que creo que te resultará interesante.', '', 25549),
(127623, 'esMX', 'Saborea el momento en que el miedo en los ojos de un demonio desplaza a la ira. ¡Los aplastaremos!', '', 25549),
(127622, 'esMX', 'Una sola muerte no es castigo suficiente para ese demonio. Ahora sufrirá la furia de su amo vil.', '', 25549),
(127621, 'esMX', 'La Legión no puede huir ni esconderse. ¡Los cazaremos!', '', 25549),
(127620, 'esMX', 'Una victoria impresionante. Tu determinación nunca flaqueó.', '', 25549),
(127619, 'esMX', '¡Nada se compara con la satisfacción de deshacerte de otro esclavo de la Legión!', '', 25549),
(127618, 'esMX', 'Este juego terminará pronto. La Legión Ardiente caerá.', '', 25549),
(127617, 'esMX', 'Cada golpe que le asestamos a la Legión los acerca más a su final.', '', 25549),
(127616, 'esMX', 'El crecimiento de tu poder es verdaderamente impresionante. La Legión conoce tu nombre... y le teme.', '', 25549),
(127615, 'esMX', 'Otro de los esbirros de la Legión se acerca. ¡Erradícalo!', '', 25549),
(127614, 'esMX', 'Ah, sí, el inconfundible hedor de la escoria de la Legión. ¡Busca la fuente y destrúyela!', '', 25549),
(127613, 'esMX', 'Presiento un objetivo cerca. ¡Ataca con celeridad!', '', 25549),
(127612, 'esMX', 'El enemigo maligno está cerca. ¡Cumple con tu deber!', '', 25549),
(127611, 'esMX', 'Se acerca un objetivo. ¡Envía a esta escoria de regreso al Vacío!', '', 25549),
(127610, 'esMX', 'Este agente de la Legión ha subestimado tu poder. Demuéstrale la gravedad de su error.', '', 25549),
(127609, 'esMX', 'La Legión ha enviado a otro de sus peones. Encárgate de esta amenaza de inmediato.', '', 25549),
(127608, 'esMX', 'Este lugar está plagado de escoria demoníaca. ¡Un objetivo principal se acerca!', '', 25549),
(127607, 'esMX', '', 'Otra amenaza erradicada. ¡Excelente!', 25549),
(127606, 'esMX', '', 'Victoria a victoria, avanzamos contra esta marea invasiva. ¡Buen trabajo!', 25549),
(127605, 'esMX', '', '¡Muy bien! Tus habilidades son más letales que cualquier arma de la Legión.', 25549),
(127604, 'esMX', '', '¡Impresionante! Ese infeliz no tenía oportunidad.', 25549),
(127603, 'esMX', '', 'El demonio recibió más piedad de la que merecía. ¡Al próximo objetivo!', 25549),
(127602, 'esMX', '', '¡Mensaje entregado!', 25549),
(127601, 'esMX', '', 'Un final apropiado para un invasor vil.', 25549),
(127600, 'esMX', '', 'Un golpe certero, $Gcampeón:campeona;. Mantente alerta.', 25549),
(127599, 'esMX', '', 'Hay una gran amenaza cerca. ¡Búscala y destrúyela!', 25549),
(127598, 'esMX', '', 'Los demonios se multiplican como ratas. ¡Acaba con este antes de que invoque más seres de su despreciable clase a nuestro mundo!', 25549),
(127597, 'esMX', '', 'Un poco más adelante... hay un nuevo objetivo. ¡Devuélvelo gritando al Vacío Abisal!', 25549),
(127596, 'esMX', '', 'Nuestros exploradores nos informan de una gran amenaza en esta área. ¡Elimínala!', 25549),
(127595, 'esMX', '', 'Tenemos mucho trabajo. Dale una muerte rápida a este demonio.', 25549),
(127594, 'esMX', '', 'Es hora de enviar un mensaje a la Legión. ¡Devuelve a este en pedazos!', 25549),
(127593, 'esMX', '', 'Una amenaza acecha. Elimina el objetivo.', 25549),
(127592, 'esMX', '', 'Hay una amenaza de la que debes ocuparte. No te demores.', 25549),
(127591, 'esMX', '¿Buscan al comandante? ¡Tendrán que pasar por mí primero, débiles!', '', 25549),
(127590, 'esMX', 'Cuantas menos bestias corrompidas por energía vil, mejor.', '', 25549),
(127589, 'esMX', 'Señores del foso. ¡Bah! No son más que arrogancia encarnada. Las esencias de esos demonios caídos podrían ser útiles en las batallas venideras.', '', 25549),
(127588, 'esMX', '$GDestripador:Destripadora;, te necesitan en el frente de batalla. ¡Arráncales la esencia a los demonios que emergen de la Tumba y usa esas almas potenciadas para partir en dos al señor del foso!', '', 25549),
(127587, 'esMX', 'Estas gigantescas máquinas de guerra de la Legión no son apropiadas para este terreno. ¡Deberían pensarlo mejor antes de enviar otra!', '', 25549),
(127586, 'esMX', '', '¡No nos detendrán!', 25549),
(127585, 'esMX', '', 'Juntos protegeremos nuestro hogar de la Legión Ardiente.', 25549),
(127584, 'esMX', 'Cuidado, amigos, ¡parece que a Klunk no le agradan!', '', 25549),
(127583, 'esMX', '', 'Cuidado, amigos, ¡parece que a Klunk no le agradan!', 25549),
(127582, 'esMX', '', 'D''Bynn y yo estaremos en el recinto, por si nos necesitas.', 25549),
(127572, 'esMX', 'No podrás detener nuestro trabajo. ¡Este territorio le pertenece a la Legión!', '', 25549),
(127571, 'esMX', 'Esta tierra nunca sanará...', '', 25549),
(127570, 'esMX', 'Los paladines son tan predecibles. Ven, veamos cuál es el verdadero poder de tu espada...', '', 25549),
(127567, 'esMX', '¿El bálsamo funcionó? Digo... sí, claro que funcionó. Buen trabajo, $Gcampeón:campeona;.', '', 25549),
(127566, 'esMX', 'Enviamos tropas para que exploraran esta área, ¡solo para que caigan ante la mirada de los basiliscos! Usa este bálsamo mágico para liberar a nuestros exploradores petrificados.', '', 25549),
(127565, 'esMX', '¡Nunca más volveré a acercarme a un basilisco!', '¡Nunca más volveré a acercarme a un basilisco!', 25549),
(127564, 'esMX', 'Gracias, $ct. ¡Regresaré al campamento!', 'Gracias, $ct. ¡Regresaré al campamento!', 25549),
(127563, 'esMX', '¿Cuánto tiempo estuve ahí atorada?', '¿Cuánto tiempo estuve ahí atorada?', 25549),
(127562, 'esMX', '', '¡Es mejor que no juegues con mi paciencia! ¡La tormenta responde a mi llamado!', 25549),
(127561, 'esMX', '', '¿Tienes la cabeza tan vacía como tu copa?', 25549),
(127560, 'esMX', '', 'Ya fue suficiente, gracias.', 25549),
(127559, 'esMX', '', '¡Espero que pruebes muchos brebajes, $Gamigo mío:amiga mía;!', 25549),
(127558, 'esMX', '', '¡Nunca sabes con qué maravillas te encontrarás!', 25549),
(127557, 'esMX', '', 'No hay nada mejor que compartir un brebaje con amigos.', 25549),
(127556, 'esMX', '', 'Uno siempre debe hacerse tiempo para inventar nuevos brebajes.', 25549),
(127555, 'esMX', '¿Por qué la babosa se mueve tan rápido?', '', 25549),
(127554, 'esMX', '', 'Un buen brebaje necesita una buena dosis de amor.', 25549),
(127553, 'esMX', '¡Regresa! ¡Necesito tus componentes principales!', '', 25549),
(127552, 'esMX', '¡Babosa mugrienta! ¡No te muevas!', '', 25549),
(127551, 'esMX', '', '¿Ya has bebido algo hoy?', 25549),
(127550, 'esMX', 'Aprendí una técnica nueva. Se llama "Patada al avispero". ¿Quieres que haga una demostración contigo?', '', 25549),
(127549, 'esMX', 'No puedo controlar mis pensamientos si sigues molestando.', '', 25549),
(127548, 'esMX', 'Por favor, déjame en paz. Estoy meditando.', '', 25549),
(127547, 'esMX', 'No descansaremos hasta derrotar a la Legión.', '', 25549),
(127546, 'esMX', 'El mal no podrá corrompernos si nuestros corazones son puros.', '', 25549),
(127545, 'esMX', 'Servimos a todo Azeroth.', '', 25549),
(127544, 'esMX', 'Somos una fuerza de equilibrio en un océano caótico.', '', 25549),
(127543, 'esMX', 'Eres una señal de luz en la oscuridad.', '', 25549),
(127542, 'esMX', 'No pierdas la fuerza en estos tiempos difíciles.', '', 25549),
(127541, 'esMX', '|TInterface\\Icons\\ability_fixated_state_red:20|t¡Karam comienza a perseguirte por última vez!', '|TInterface\\Icons\\ability_fixated_state_red:20|t¡Karam comienza a perseguirte por última vez!', 25549),
(127540, 'esMX', '', 'Lord Illidan, tu llegada es muy bienvenida... Celadoras, encarguémonos del trabajo de verdad mientras los cazadores de demonios juegan con sus murciélagos.', 25549),
(127539, 'esMX', '¡Acaben con el Comandante aterrador Arganoth! Nosotros nos encargaremos del resto.', '', 25549),
(127538, 'esMX', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_GENERALVEZAX_01.BLP:20|t¡Una Runa de invocación conjura una |cFFFF0000|Hspell:236461|h[Cosa de pesadillas]|h|r para perseguirte!', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_GENERALVEZAX_01.BLP:20|t¡Una Runa de invocación conjura una |cFFFF0000|Hspell:236461|h[Cosa de pesadillas]|h|r para perseguirte!', 25549),
(127537, 'esMX', '|TInterface\\Icons\\SPELL_MAGE_RUNEOFPOWER.BLP:20|t¡Raest proyecta una |cFFFF0000|Hspell:236460|h[Runa de invocación]|h|r en las cercanías!', '|TInterface\\Icons\\SPELL_MAGE_RUNEOFPOWER.BLP:20|t¡Raest proyecta una |cFFFF0000|Hspell:236460|h[Runa de invocación]|h|r en las cercanías!', 25549),
(127536, 'esMX', '|TInterface\\Icons\\ability_fixated_state_red:20|t¡Karam comienza a perseguirte de nuevo!', '|TInterface\\Icons\\ability_fixated_state_red:20|t¡Karam comienza a perseguirte de nuevo!', 25549),
(127535, 'esMX', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_05.BLP:20|t¡Una mano demoníaca del más allá comienza a lanzar |cFFFF0000|Hspell:235578|h[Mano del más allá]|h|r!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_05.BLP:20|t¡Una mano demoníaca del más allá comienza a lanzar |cFFFF0000|Hspell:235578|h[Mano del más allá]|h|r!', 25549),
(127534, 'esMX', '|TInterface\\Icons\\INV_MISC_SHADOWEGG.BLP:20|t¡Raest usa |cFFFF0000|Hspell:235446|h[Ruptura dimensional]|h|r para abrir Fisuras al Vacío!', '|TInterface\\Icons\\INV_MISC_SHADOWEGG.BLP:20|t¡Raest usa |cFFFF0000|Hspell:235446|h[Ruptura dimensional]|h|r para abrir Fisuras al Vacío!', 25549),
(127533, 'esMX', '|TInterface\\Icons\\ability_fixated_state_red:20|t¡Karam comienza a perseguirte!', '|TInterface\\Icons\\ability_fixated_state_red:20|t¡Karam comienza a perseguirte!', 25549),
(127532, 'esMX', '¡No eres digno del sol!', '', 25549),
(127531, 'esMX', '¿Tienes alguna investigación de artefactos preparada?', '¿Tienes alguna investigación de artefactos preparada?', 25549),
(127530, 'esMX', '¡Voy a divertirme muchísimo! ¡Jajaja!', '', 25549),
(127529, 'esMX', '¿Y ahora a dónde?', '', 25549),
(127528, 'esMX', '¡Tanto para quemar! Je, je, je.', '', 25549),
(127527, 'esMX', '¡Al fin libre!', '', 25549),
(127526, 'esMX', 'Estoy por perder el control... ¡y creo que me gusta!', '', 25549),
(127525, 'esMX', 'Mi ira aumenta...', '', 25549),
(127524, 'esMX', '¿Qué quieres?', '', 25549),
(127523, 'esMX', 'Mis garras están afiladas y listas para la acción.', '', 25549),
(127522, 'esMX', 'Por la Alianza.', '', 25549),
(127521, 'esMX', 'Mantente fuerte.', '', 25549),
(127520, 'esMX', '¿Necesitas algo?', '', 25549),
(127519, 'esMX', 'Hola.', '', 25549),
(127518, 'esMX', '¿Hay algún problema?', '', 25549),
(127517, 'esMX', 'Por supuesto que tendré éxito, $GSeñor de la batalla:Señora de la batalla;.', '', 25549),
(127516, 'esMX', '¡Caerás ante la furia de mis garras!', '', 25549),
(127515, 'esMX', 'Mi ira se apacigua... por ahora...', '', 25549),
(127514, 'esMX', '$GSeñor de la batalla:Señora de la batalla;, te he... fallado...', '', 25549),
(127513, 'esMX', 'Mis garras... ya no tienen filo...', '', 25549),
(127512, 'esMX', '¡Tu muerte alimenta mi ira!', '', 25549),
(127511, 'esMX', '¡Tu sangre gotea por mis garras!', '', 25549),
(127510, 'esMX', '¡Por la Alianza!', '', 25549),
(127509, 'esMX', '¡Afilaré mis garras con tu pellejo!', '', 25549),
(127508, 'esMX', '¡Te haré pedazos!', '', 25549),
(127507, 'esMX', '¡Graaaaaaagh!', '', 25549),
(127506, 'esMX', '¡Siente mi furia!', '', 25549),
(127505, 'esMX', '¡Te destruiré!', '', 25549),
(127504, 'esMX', '¡Juntos destruiremos a nuestros enemigos!', '', 25549),
(127503, 'esMX', '¡Defenderemos Azeroth hasta la muerte!', '', 25549),
(127502, 'esMX', 'Mis saludos, $GSeñor de la batalla:Señora de la batalla;. ¡Estoy listo para pelear!', '', 25549),
(127500, 'esMX', '¡No provoques mi ira!', '', 25549),
(127499, 'esMX', 'Mi hacha está sedienta.', '', 25549),
(127498, 'esMX', '¿Qué?', '', 25549),
(127497, 'esMX', 'Adiós.', '', 25549),
(127496, 'esMX', 'Mantén tus armas afiladas.', '', 25549),
(127495, 'esMX', 'No pierdas las fuerzas.', '', 25549),
(127494, 'esMX', 'Saludos, camarada.', '', 25549),
(127493, 'esMX', '¿Sí?', '', 25549),
(127492, 'esMX', 'Throm-ka!', '', 25549),
(127491, 'esMX', 'Zug-zug. No te fallaré, $GSeñor de la batalla:Señora de la batalla; $n.', '', 25549),
(127490, 'esMX', '¡Tiembla ante mi furia!', '', 25549),
(127489, 'esMX', 'Mi hacha se alzará nuevamente...', '', 25549),
(127488, 'esMX', 'Estoy débil...', '', 25549),
(127487, 'esMX', 'Mi furia está... satisfecha...', '', 25549),
(127486, 'esMX', '', '¿Estás seguro de que necesitas mi ayuda?', 25549),
(127485, 'esMX', 'Demasiado fácil.', '', 25549),
(127484, 'esMX', '¡Mi furia no tiene límite!', '', 25549),
(127483, 'esMX', '¡El placer de la victoria!', '', 25549),
(127482, 'esMX', '¡Aaaaaaagh!', '', 25549),
(127481, 'esMX', 'Lok-tar ogar!', '', 25549),
(127480, 'esMX', '¡Por la Horda!', '', 25549),
(127479, 'esMX', '¡Mi hacha tiene sed de sangre!', '', 25549),
(127478, 'esMX', 'Debemos destruir este mal.', '', 25549),
(127477, 'esMX', '¡Nuestra furia salvará Azeroth!', '', 25549),
(127476, 'esMX', 'Saludos, $GSeñor de la batalla:Señora de la batalla;. Pelearé a tu lado.', '', 25549),
(127475, 'esMX', '¡Tal anu''men no Tirisgarde!', '', 25549),
(127474, 'esMX', '¡Basta de payasadas!', '', 25549),
(127473, 'esMX', '¿Mi sufrimiento te resulta divertido?', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127472, 'esMX', '¿Qué quieres?', '', 25549),
(127471, 'esMX', 'Haré lo mejor que pueda, $GArchimago:Archimaga;.', '', 25549),
(127470, 'esMX', '¡Anar''alah belore, arderás!', '', 25549),
(127469, 'esMX', 'Mi mejor esfuerzo...no fue suficiente...', '', 25549),
(127468, 'esMX', 'Necesito... un descanso.', '', 25549),
(127467, 'esMX', 'Debo recuperar... fuerzas...', '', 25549),
(127466, 'esMX', '¡Márchate al reino sin sol!', '', 25549),
(127465, 'esMX', 'Diel ma''ahn orindel''o.', '', 25549),
(127464, 'esMX', 'Has fallado.', '', 25549),
(127463, 'esMX', 'Insignificante.', '', 25549),
(127462, 'esMX', '¡Arde!', '', 25549),
(127461, 'esMX', '¡Diel fin''al!', '', 25549),
(127460, 'esMX', '¡Tu grupo decidió expulsar a Schnottz del globo!', '', 25549),
(127459, 'esMX', '¡Hora de prender fuego!', '', 25549),
(127458, 'esMX', '¡Otro objetivo para destruir!', '', 25549),
(127457, 'esMX', '¡Incineraremos a esta oscuridad!', '', 25549),
(127456, 'esMX', '¡Juntos salvaremos Azeroth!', '', 25549),
(127455, 'esMX', '¡Ayudaremos a los Tirisgarde!', '', 25549),
(127454, 'esMX', 'Bal''a dash, $GArchimago:Archimaga;. ¡Pelearemos juntos!', '', 25549),
(127453, 'esMX', 'El globo se irá una vez que tengamos tres pasajeros listos para partir.', 'El globo se irá una vez que tengamos tres jinetes listas para partir.', 25549),
(127452, 'esMX', '', 'Tal vez... no estoy hecha para esto... después de todo...', 25549),
(127451, 'esMX', '', '¡Ya basta, no estoy bromeando! ¡Te haré probar mi patada giratoria!', 25549),
(127450, 'esMX', '', 'Bueno, bueno... ¡ya basta!', 25549),
(127449, 'esMX', '', '¡Jajaja! ¡Basta! ¡Me haces cosquillas!', 25549),
(127448, 'esMX', '', '¿Puedo ir contigo?', 25549),
(127447, 'esMX', '', '¡Buena suerte!', 25549),
(127446, 'esMX', '', '¡Deberíamos salir a beber un trago alguna vez!', 25549),
(127445, 'esMX', '', '¡Estoy lista para lo que sea!', 25549),
(127444, 'esMX', '', '¿Qué tal, $Ghéroe;heroína;?', 25549),
(127443, 'esMX', '', '¿Te gustaría probar mi brebaje especial?', 25549),
(127442, 'esMX', '', '¡Guau! ¡Haré mi mejor esfuerzo, $GGran maestro:Gran maestra;!', 25549),
(127441, 'esMX', '', '¡Muere o aléjate de mi camino! ¡Uoo... uo... uo... uoo!', 25549),
(127440, 'esMX', '', 'Lamento decepcionarte, $GGran maestro:Gran maestra;.', 25549),
(127439, 'esMX', '', 'Voy a necesitar una medida doble después de esto...', 25549),
(127438, 'esMX', '', '¡Auch! Tal vez debí haberme quedado en la cervecería...', 25549),
(127437, 'esMX', '', '¿De verdad eso fue lo mejor que tenías?', 25549),
(127436, 'esMX', '', 'Ey, ¡creo que empiezo a ser buena en esto!', 25549),
(127435, 'esMX', '', '¡No puedo creer que haya desperdiciado mi chi en alguien como tú!', 25549),
(127434, 'esMX', '', '¡Toma eso!', 25549),
(127433, 'esMX', '', '¡Excelente! ¡Me vendría bien un poco de práctica de combate!', 25549),
(127432, 'esMX', '', '¡Te dejaré fuera de combate!', 25549),
(127431, 'esMX', '', '¡Apuesto a que nunca viste una patada giratoria como la mía!', 25549),
(127430, 'esMX', '', '¡Jamás podrás atravesar mis nieblas!', 25549),
(127429, 'esMX', '', '¡Apuesto que no sabes apreciar una buena cerveza!', 25549),
(127428, 'esMX', '', '¡Juro que no te fallaré, $GGran maestro:Gran maestra;!', 25549),
(127427, 'esMX', '', '¡Yo te cubro, $GGran maestro:Gran maestra;!', 25549),
(127426, 'esMX', '', '¡Arremanguémonos y empecemos a trabajar!', 25549),
(127425, 'esMX', '', 'Supongo que me encargaré de esto... por ti.', 25549),
(127424, 'esMX', '', '¡Te enviaré a una tumba submarina!', 25549),
(127423, 'esMX', '', 'No acepto... este resultado...', 25549),
(127422, 'esMX', '', 'Tendrás que hacer esto... sin mí...', 25549),
(127421, 'esMX', '', 'Esto no es... posible...', 25549),
(127419, 'esMX', '', 'Los Cicatriz Espiral siempre obtenemos lo que queremos.', 25549),
(127417, 'esMX', '', '¡Comida para los peces!', 25549),
(127416, 'esMX', '', 'Tendrías que haber aprendido a nadar.', 25549),
(127415, 'esMX', '', 'Me aburres.', 25549),
(127414, 'esMX', '', '¡Tiembla ante los Cicatriz Espiral!', 25549),
(127413, 'esMX', '', '¿Podemos hacer algo más interesante esta vez?', 25549),
(127412, 'esMX', '', '$GDestripador:Destripadora;. Supongo que tengo algo de tiempo para ayudarte.', 25549),
(127411, 'esMX', '', '¿Seguro necesitas mi ayuda?', 25549),
(127410, 'esMX', '', '¡Húndete o empieza a nadar!', 25549),
(127409, 'esMX', '', '¡Te ahogarás!', 25549),
(127408, 'esMX', '', 'Esto será rápido.', 25549),
(127407, 'esMX', '', '¡Lord Illidan estará complacido con tu muerte!', 25549),
(127406, 'esMX', '', 'No eres digno de mí.', 25549),
(127405, 'esMX', '¡Estoy harto de tus intromisiones! ¡Ven a buscarme si te atreves!', '', 25549),
(127404, 'esMX', '¡La Legión lo conquistará todo! Sus patéticos salones quedarán hechos polvo.', '', 25549),
(127403, 'esMX', '', '...Si es que tuviera pulso, claro.', 25549),
(127402, 'esMX', '', 'Y si no, estaré más que feliz de destrozarlos a hachazos. Sea como sea, no me temblará el pulso.', 25549),
(127401, 'esMX', '', 'Cuando los demonios vean nuestro linaje, ¡morirán de pánico!', 25549),
(127400, 'esMX', '', 'No me malinterpretes... los Cuatro Jinetes son impresionantes. Pero dragones no-muertos gigantes...', 25549),
(127399, 'esMX', '', 'Ahora que Daumyr y su linaje nos pertenecen, el curso de la batalla cambiará.', 25549),
(127398, 'esMX', '', 'Hola, $n. ¿Sabías que hoy se organiza un tour de tabernas patrocinado por el Kirin Tor? De hecho, te puedo teletransportar a la taberna donde todos están pasando el rato.', 25549),
(127397, 'esMX', '¡Una victoria intachable, campeones! Las canciones sobre su gloria resonarán en los Salones del valor durante las eras venideras.', '', 25549),
(127396, 'esMX', 'Acabaron con su comandante. ¡Buen trabajo! Los dracos de Vethir los llevarán a un lugar seguro. ¡Yo mismo le asestaré el golpe de gracia a su despreciable nave!', '', 25549),
(127395, 'esMX', '¡Debemos erradicar a la Legión de los cielos! Los dracos los llevarán hasta la fortaleza voladora de los demonios. Desde allí, podrán sabotear su nave infernal.', '', 25549),
(127394, 'esMX', 'Héroes, regresen a mí. El linaje de Vethir se ha unido a nuestra batalla contra los invasores. ¡Alcen vuelo y quédense con la victoria!', '', 25549),
(127393, 'esMX', 'Han capturado al linaje de Vethir... ¡otra vez! Libérenlos para que puedan ayudarnos a repeler este ataque.', '', 25549),
(127392, 'esMX', '', 'Y ahora esperamos. ¡Esta pelea será gloriosa!', 25549),
(127391, 'esMX', '', 'Me encantan tus anteojos. Son tan vintage.', 25549),
(127390, 'esMX', '¡Hoy la Legión caerá! ¡Por Azeroth!', '', 25549),
(127389, 'esMX', 'Debemos capturar las ruinas en el oeste de la isla. ¡Desde allí, podremos reunir a nuestras fuerzas y marchar hacia la máquina de almas!', '', 25549),
(127388, 'esMX', '¡Necesito que guíes a mis fuerzas y a las órdenes en la batalla mientras yo me encargo de los demás frentes!', '', 25549),
(127387, 'esMX', '$n, nuestro ataque a la playa sur se ha encontrado con una resistencia muy fuerte.', '', 25549),
(127386, 'esMX', 'La puerta del gran salón de baile de la Escalera Quebrada se abre.', 'La puerta del gran salón de baile de la Escalera Quebrada se abre.', 25549),
(127385, 'esMX', 'Ya casi lo tenías. La próxima vez será.', 'Ya casi lo tenías. La próxima vez será.', 25549),
(127384, 'esMX', 'Emm... ¿gracias por intentarlo?', 'Emm... ¿gracias por intentarlo?', 25549),
(127383, 'esMX', '¡Perdiste! ¡No te llevas nada!', '¡Perdiste! ¡No te llevas nada!', 25549),
(127382, 'esMX', 'Qué lástima, qué lástima.', 'Qué lástima, qué lástima.', 25549),
(127381, 'esMX', '¿Soy yo o aquí huele a victoria?', '¿Soy yo o aquí huele a victoria?', 25549),
(127380, 'esMX', 'Umm, de seguro más de uno de ustedes no estaba prestando atención.', 'Umm, de seguro más de uno de ustedes no estaba prestando atención.', 25549),
(127379, 'esMX', 'La lucha terminó... ¡y nuestros héroes son los campeones! Bolsas de oro grandes y rebosantes para todos los involucrados.', 'La lucha terminó... ¡y nuestros héroes son los campeones! Bolsas de oro grandes y rebosantes para todos los involucrados.', 25549),
(127378, 'esMX', 'No puedo creerlo... ¡ganaron! ¡Es un milagro! Bromeaba, esto pasa todo el tiempo.', 'No puedo creerlo... ¡ganaron! ¡Es un milagro! Bromeaba, esto pasa todo el tiempo.', 25549),
(127377, 'esMX', '', 'Está grande y lista para pelear. Claro que ahora parece una linda gatita, pero esperen a que la arrinconen. Eviten a nuestra próxima luchadora, ¡Mazhareen!', 25549),
(127376, 'esMX', '', '¡Si no puedes ganarle, únete a él! Prepárense para que sus mentes, bebidas y rostros congelados se derritan frente al único e inigualable ¡Gzzaj Rompementes!', 25549),
(127375, 'esMX', '', 'No hace falta que derroten a estas criaturas, solo deben sobrevivir. Oh, y nos quedaremos con todo vuestro equipo y experiencia también. ¡Que disfruten de su aventura en Tuercespina!', 25549),
(127374, 'esMX', '', '¡H-I-P-O-P-Ó-T-A-M-O se traduce como muerte! Intenten que no los aplaste nuestro próximo luchador: ¡Senya!', 25549),
(127373, 'esMX', '', 'Estos tres pandaren tienen un desafío para ti... lleva una de tus vagonetas de cerveza hacia el centro del ring antes de que ellos consigan hacer lo propio. ¡El equipo ganador puede beberlo todo!', 25549),
(127372, 'esMX', '', 'Nuestro combate de hoy consta de un conjunto de pingüinos picadores de los precipicios polares de Rasganorte. ¡Cuidado con la estampida resbaladiza!', 25549),
(127371, 'esMX', '', 'Nuestro combate de hoy es un mamífero musculoso adicto a la venganza. No quiere ayudarte... quiere matarte. Es el alce hostil, ¡el Guardián de las penas!', 25549),
(127370, 'esMX', 'Está grande y lista para pelear. Claro que ahora parece una linda gatita, pero esperen a que la arrinconen. Eviten a nuestra próxima luchadora, ¡Mazhareen!', '', 25549),
(127369, 'esMX', '¡Si no puedes ganarle, únete a él! Prepárense para que sus mentes, bebidas y rostros congelados se derritan frente al único e inigualable ¡Gzzaj Rompementes!', '', 25549),
(127368, 'esMX', 'No hace falta que derroten a estas criaturas, solo deben sobrevivir. Oh, y nos quedaremos con todo vuestro equipo y experiencia también. ¡Que disfruten de su aventura en Tuercespina!', '', 25549),
(127367, 'esMX', '¡H-I-P-O-P-Ó-T-A-M-O se traduce como muerte! Intenten que no los aplaste nuestro próximo luchador: ¡Senya!', '', 25549),
(127366, 'esMX', 'Estos tres pandaren tienen un desafío para ti... lleva una de tus vagonetas de cerveza hacia el centro del ring antes de que ellos consigan hacer lo propio. ¡El equipo ganador puede beberlo todo!', '', 25549),
(127365, 'esMX', 'Nuestro combate de hoy consta de un conjunto de pingüinos picadores de los precipicios polares de Rasganorte. ¡Cuidado con la estampida resbaladiza!', '', 25549),
(127364, 'esMX', 'Nuestro combate de hoy es un mamífero musculoso adicto a la venganza. No quiere ayudarte... quiere matarte. Es el alce hostil, ¡el Guardián de las penas!', '', 25549),
(127363, 'esMX', '', '¡Arderás con un poder que no puedes controlar!', 25549),
(127362, 'esMX', '', '¡Tu clase será erradicada de este mundo!', 25549),
(127361, 'esMX', '¡|TInterface\\Icons\\INV_Misc_Food_Legion_gooOil_multi.blp:20|tLos pozos de alquitrán empiezan a hacer |cFFFF0000|Hspell:236333|h[Erupción]|h|r !', '', 25549),
(127360, 'esMX', 'Comienza a salir alquitrán desde el suelo alrededor de %s...', '', 25549),
(127359, 'esMX', '¡El núcleo destruido de un atracador vil está creando una hueste de aberraciones! ¡Recupera los fragmentos del núcleo antes de que la Legión recicle su creación!', '', 25549),
(127358, 'esMX', '¡Bien hecho! Puede que la Legión deje algunas marcas de su presencia, pero desaparecerán con el tiempo.', '', 25549),
(127357, 'esMX', '¡La Legión corrompe todo lo que toca! ¡Destruye a sus corruptores viles antes de que infesten todo Stormheim!', '', 25549),
(127356, 'esMX', 'Estoy listo para comenzar la prueba, Odyn.', 'Estoy lista para comenzar la prueba, Odyn.', 25549),
(127355, 'esMX', 'Teletranspórtame al tour de tabernas.', 'Teletranspórtame al tour de tabernas.', 25549),
(127354, 'esMX', 'Estoy listo para regresar a Bastión del Cielo.', 'Estoy lista para regresar a Bastión del Cielo.', 25549),
(127353, 'esMX', '¿Qué has traído?', '¿Qué has traído?', 25549),
(127352, 'esMX', 'Es un honor estar aquí para ti, $GSeñor de la batalla:Señora de la batalla;. Espero que salgas $Gvictorioso:victoriosa; en tus pruebas.', '', 25549),
(127351, 'esMX', '', 'Te doy la bienvenida al tour de tabernas del Kirin Tor, $n. Sírvete toda la bebida y comida que quieras. Saldremos hacia la siguiente taberna en algunos minutos.', 25549),
(127350, 'esMX', 'Puedo llevarte de regreso a Bastión del Cielo cuando estés $Glisto:lista; para partir, $GSeñor de la batalla:Señora de la batalla;.', '', 25549),
(127349, 'esMX', 'Puedo llevarte de regreso a Bastión del Cielo cuando estés $Glisto:lista; para partir, $GSeñor de la batalla:Señora de la batalla;.', '', 25549),
(127348, 'esMX', 'Ah, eso alegró a mi espíritu. ¡Gracias por hacer compañía a un viejo cazador!', '', 25549),
(127347, 'esMX', 'Je, está bien que yo lo diga porque soy un enano. ¡Y un cazador!', '', 25549),
(127346, 'esMX', '¡Porque no se puede beber del barril de un arco!', '', 25549),
(127345, 'esMX', '¿Por qué los cazadores enanos usan armas de fuego?', '', 25549),
(127344, 'esMX', '¿Alguien se sabe algún buen chiste? Bien, yo empiezo...', '', 25549),
(127343, 'esMX', 'Ahora me dio melancolía.', '', 25549),
(127342, 'esMX', '¿Puedo pasear en tu globo?', '¿Puedo pasear en tu globo?', 25549),
(127341, 'esMX', 'Estoy listo. Invoca un portal.', 'Estoy lista. Invoca un portal.', 25549),
(127340, 'esMX', 'El poder es tuyo, $n. Acaba con esto.', '', 25549),
(127339, 'esMX', '¡Se ha interrumpido la conexión! Tenemos que actuar rápido, $n. Encontrémonos en Farondale. La última batalla está cerca.', '', 25549),
(127338, 'esMX', '¡Ineptos! ¡Observen el cielo más allá y sean testigos del fin de su mundo!', '', 25549),
(127337, 'esMX', '', 'No... no puedo creer que perdí. Tal vez no sea digna de ascender...', 25549),
(127336, 'esMX', '', 'Cuando te derrote, estaré un paso más cerca de ascender.', 25549),
(127335, 'esMX', '¿Será la proeza guerrera $Gdel Señor de la batalla:de la Señora de la batalla; $p suficiente para superar a este rival, la favorita a los ojos de Eyir?', '', 25549),
(127334, 'esMX', 'Eyir ha enviado a su mejor pupila como última retadora $Gdel Señor de la batalla:de la Señora de la batalla; $p. ¡Les presento a la aspirante Thyri!', '', 25549),
(127333, 'esMX', '¡Celebremos la victoria de nuestro campeón! ¡Que viva $Gel Señor:la Señora; de la batalla!', '', 25549),
(127332, 'esMX', '¡$GEl Señor:La Señora; de la batalla ha superado a todos los contendientes! ¡La prueba ha terminado!', '', 25549),
(127331, 'esMX', '$GSeñor de la batalla:Señora de la batalla; $p, cuando estés $Glisto:lista; para enfrentar tu último desafío, párate sobre la runa.', '', 25549),
(127330, 'esMX', '¡Una batalla para el recuerdo! El dominio de Asrea ha sido tan abrumador que muchos espectadores la consideraban invencible. ¡Parece que su orgullo ha causado su caída!', '', 25549),
(127329, 'esMX', '¡La prodigiosa defensa de Pezuñacero ha caído ante la habilidad de $p! ¿Pero será suficiente para derrotar al próximo contendiente?', '', 25549),
(127328, 'esMX', '¡Una primera ronda fantástica! Parece que Damrul subestimó la fuerza $Gdel Señor:de la Señora; de la batalla $p.', '', 25549),
(127327, 'esMX', '¡El tiempo se detiene y la Torre de los magos cruje!', '¡El tiempo se detiene y la Torre de los magos cruje!', 25549),
(127325, 'esMX', 'La Legión ha comenzado a corromper bestias. Una de ellas se ha asentado en una cueva entre los múrlocs. ¡Hay que eliminarla!', '', 25549),
(127324, 'esMX', 'Es mejor que nuestras fuerzas revivan y peleen a nuestro lado a que sirvan como combustible para los viles.', '', 25549),
(127323, 'esMX', 'Debemos encontrar a Erdris. Exploraré el fuerte y te avisaré cuando sea el momento de atacar. Nos veremos pronto, $n.', '', 25549),
(127322, 'esMX', '¡Unos demonios viles están usando a nuestros aliados heridos como carnada! Necesitamos que todos los soldados regresen al frente. Ve a la batalla y dirígelos... pero ten cuidado de las sombras.', '', 25549),
(127321, 'esMX', 'Saborea esta victoria mientras puedas. He estudiado tus tácticas... y conozco tus debilidades. ¡Ahora alzaré mi propio ejército en el Fuerte Torre oscura!', '', 25549),
(127320, 'esMX', 'Impresionante. Hasta las magias más poderosas pueden anularse con las herramientas adecuadas.', '', 25549),
(127319, 'esMX', '$GMaestro de caza:Maestra de caza;, ve por tus bengalas. Hay bestias de las sombras controlando un territorio vital de la Legión. Revela a estas criaturas para que nuestros arqueros provoquen una lluvia de destrucción sobre ellos.', '', 25549),
(127318, 'esMX', 'Sí... levántense... ¡combatan a la "Legión"!', '', 25549),
(127317, 'esMX', '¡Tropas, a mí! ¡Necesito su fuerza!', '', 25549),
(127316, 'esMX', '¡Convoca a tus tropas, $G"mi señor":"mi señora";! Yo los levantaré y los haré más fuertes.', '', 25549),
(127315, 'esMX', 'La muerte se aproxima.', '', 25549),
(127314, 'esMX', 'Me rindo, $GSeñor de la batalla;Señora de la batalla;. Has demostrado sin lugar a dudas que eres $Gun guerrero:una guerrera; superior.', '', 25549),
(127313, 'esMX', 'Por fortuna, Erdris reveló de quién debemos encargarnos. Deberían estar cerca de la granja. ¡Vamos!', '', 25549),
(127312, 'esMX', '¡Espera! Basta, ya... ya no puedo seguir. Claramente eres el brul más fuerte.', '', 25549),
(127311, 'esMX', '¡Disa, Nethos, Tael''thos! ¡Formen filas! ¡Quiero esa infestación erradicada!', '', 25549),
(127310, 'esMX', 'Estoy listo para iniciar el asalto final. [Hacer cola para la gesta]', 'Estoy lista para iniciar el asalto final. [Hacer cola para la gesta]', 25549),
(127309, 'esMX', '¡La Legión Ardiente caerá!', '', 25549),
(127308, 'esMX', 'He... fracasado.', '', 25549),
(127307, 'esMX', 'Permíteme abrir un portal. ', '', 25549),
(127306, 'esMX', '¡Juntos aplastaremos a la Legión Ardiente, $GArchimago:Archimaga; $n!', '', 25549),
(127303, 'esMX', 'Gracias, campeona. ¡Por favor, libera a los otros también!', 'Gracias, campeona. ¡Por favor, libera a los otros también!', 25549),
(127302, 'esMX', 'Gracias, campeona. ¡Por favor, libera a los otros también!', 'Gracias, campeona. ¡Por favor, libera a los otros también!', 25549),
(127300, 'esMX', '', 'Ha pasado un tiempo desde la última vez que mi cuchilla probó sangre. Me pregunto si la tuya será de su agrado...', 25549),
(127299, 'esMX', 'Su espada ha derribado a muchos guerreros en esta arena. ¿Podrá $Gel Señor:la Señora; de la batalla encontrar la forma de vencer?', '', 25549),
(127298, 'esMX', 'La próxima retadora $Gdel Señor de la batalla:de la Señora de la batalla; $p es Asrea Filoluna de los orgullosos Natonocturnos de Suramar.', '', 25549),
(127297, 'esMX', '', '¡NO ME RENDIRÉ ANTE ALGUIEN COMO TÚ, $GCAMPESINO:CAMPESINA;!', 25549),
(127296, 'esMX', '', 'Eres $Gun tonto:una tonta;, $r. Pero si solo la muerte te dará una lección, que así sea.', 25549),
(127295, 'esMX', '', 'He participado de esta prueba miles de veces. Y siempre le demostré a Odyn que sus guerreros no son dignos de estar en la misma arena que yo.', 25549),
(127290, 'esMX', '¡Estás metiéndote con poderes que no comprendes, mortal! ¡Tu orgullo será tu fin!', '', 25549),
(127285, 'esMX', '¡|TInterface\\Icons\\SPELL_SHADOW_SOULLEECH_1.BLP:20|t%scomienza a |cFFFF0000|Hspell:236133|h[Florecer]|h|r !', '', 25549),
(127284, 'esMX', 'Amigo...', '', 25549),
(127283, 'esMX', '¡Inclínense ante el poder de la Legión Ardiente! ¡Sus esfuerzos son insignificantes, mortales!', '', 25549),
(127282, 'esMX', 'La presencia demoníaca retrocede, pero no podemos confiarnos. Te esperaré fuera del Templo. Ahora es nuestro turno de avanzar.', '', 25549),
(127281, 'esMX', 'La intimidación es un arma de la Legión. La inteligencia no.', '', 25549),
(127280, 'esMX', 'La Legión está tratando de reparar un atracador vil mediante un ritual inestable. Ve a frustrar sus intentos y usa sus propias energías contra ellos.', '', 25549),
(127279, 'esMX', 'Las energías viles que había dentro de esos cristales se disiparon después de su destrucción. Considera la amenaza neutralizada.', '', 25549),
(127278, 'esMX', 'La Legión les ha concedido gemas con poderes maléficos a los Vilnato. Arrebátales esas baratijas y destrúyelas. La vida de esos elfos ya están perdidas.', '', 25549),
(127277, 'esMX', '', '¡Esta ronda la paga $n! ¡Bebidas gratis por los próximos dos minutos!', 25549),
(127276, 'esMX', '¡El salón Bum de Bizmo ha abierto sus puertas a todos los luchadores, cortesía de $n!', '', 25549),
(127275, 'esMX', '', '$n entregó oro suficiente como para infringir las normas de la arena. ¡Habla con algún gorila si quieres pelear contra un luchador aleatorio!', 25549),
(127274, 'esMX', 'Esto es lo que pasa: puede que no te hayas GANADO el derecho a entrar al salón Bum, pero alguien que me cae mejor que tú me pagó para que te dejara entrar.\n\nEstá bien, entra y no causes problemas.', '', 25549),
(127273, 'esMX', '¿Tu rango es 8, verdad?\n\nNo está mal, pasa.', '', 25549),
(127272, 'esMX', 'Cuando Bizmo y su equipo erigieron esta taberna en un costado del Tranvía Subterráneo, asumieron un gran riesgo: gastaron mucho oro en la construcción de este lugar.\n\nAsí que creó el salón VIP. El salón Bum, como lo llama. Mejores vistas de las peleas, todas las bebidas de mejor calidad que puedas comprar y la satisfacción de saber que puedes acceder a un club exclusivo para miembros. Verás, solo se puede acceder si eres de rango 8 o superior.\n\n¿Quieres entrar al salón Bum? Pues sigue ganando tus combates.', '', 25549),
(127271, 'esMX', '<Muestra el formulario de alquiler del salón VIP.>', '<Muestra el formulario de alquiler del salón VIP.>', 25549),
(127270, 'esMX', '¡La Legión Ardiente marcha hacia Azsuna! ¡Debemos diezmar sus filas para dar en el corazón de la amenaza!', '', 25549),
(127269, 'esMX', 'Ha sido un honor que Odyn me reciba en este lugar. Le demostraré que no ha cometido un error al confiar en mi fuerza.', '', 25549),
(127268, 'esMX', 'No te avergüences cuando pierdas. Mi defensa es impenetrable.', '', 25549),
(127267, 'esMX', 'Será un placer aplastarte.', '', 25549),
(127266, 'esMX', '¡Te reto a un combate!', '¡Te reto a un combate!', 25549),
(127265, 'esMX', '¿Vienes a hacer ejercicio conmigo, brul?', '', 25549),
(127264, 'esMX', 'Mi escudo ha rechazado ejércitos de guerreros. No creo que $Gun:una; $r pueda atravesarlo.', '', 25549),
(127263, 'esMX', '¡Veamos si las habilidades de $p pueden con el infame escudo de Pezuñacero!', '', 25549),
(127262, 'esMX', 'El próximo retador del $GSeñor de la batalla:Señora de la batalla; $p es Omanawkwa Pezuñacero de la tribu de Altamontaña.', '', 25549),
(127261, 'esMX', 'No habríamos podido resistir mucho más tiempo. ¡Muchas gracias!', 'No habríamos podido resistir mucho más tiempo. Muchas gracias, $c.', 25549),
(127260, 'esMX', 'Este brebaje es particularmente espumoso. Es justo el refresco que necesito.', 'Este brebaje es particularmente espumoso. Es justo el refresco que necesito.', 25549),
(127259, 'esMX', '¡Ahhh! ¡Un brebaje frío y refrescante!', '¡Ahhh! ¡Un brebaje frío y refrescante!', 25549),
(127258, 'esMX', 'Los demonios pagarán mil veces por sus crímenes. ¡No dejen de atacar!', '', 25549),
(127257, 'esMX', '¡Un ataque fulminante contra la Legión!', '', 25549),
(127256, 'esMX', 'Cada victoria afirma nuestro avance y fortalece a nuestros ejércitos. Gracias, $Gcampeón:campeona;.', '', 25549),
(127255, 'esMX', 'Nuestra patrulla divisó a un enemigo poderoso en esta área. Si lo derrotamos, lograríamos reducir notablemente la presencia de la Legión aquí.', '', 25549),
(127254, 'esMX', 'Las tropas de la Legión se están reuniendo con un adversario poderoso. ¡Debemos impedir que reúnan más fuerzas!', '', 25549),
(127253, 'esMX', 'La presencia de la Legión es fuerte aquí. Prepárate, $Gcampeón:campeona;. ¡La Luz debe prevalecer!', '', 25549),
(127252, 'esMX', 'Aplastaremos a la Legión donde sea que aparezca, hasta que desaparezca para siempre.', '', 25549),
(127251, 'esMX', 'Por cada uno que eliminemos, otro regresará. Mantente alerta.', '', 25549),
(127250, 'esMX', '¡No estaban preparados!', '', 25549),
(127249, 'esMX', 'Esta peste se atreve a volver a pisar Azeroth. Trátalos del mismo modo que ellos han tratado a otros mundos. Erradícalos.', '', 25549),
(127248, 'esMX', 'Otro insecto de la Legión se ha escabullido fuera de su roca. ¡Demuéstrale el poderío de nuestros ejércitos!', '', 25549),
(127247, 'esMX', 'Presiento a un enemigo poderoso cerca. ¡Ataca con toda tu furia para desterrarlo de este mundo!', '', 25549),
(127246, 'esMX', 'Ciertamente hay una gran carnicería en el ring hoy. Más que lo normal, diría yo. Creo que me golpeó con un diente.', '', 25549),
(127245, 'esMX', 'No tengo intenciones de reincorporarme al consejo, pero es muy agradable estar entre sus miembros.', '', 25549),
(127244, 'esMX', '$n quiere saber: ¿te sientes con suerte? Habla con lord Winifred Browne y prueba tu... potencial para conseguir oro.', '', 25549),
(127243, 'esMX', 'Otra victoria para los ejércitos de Legión caída. ¡No podemos desperdiciar esta ventaja!', '', 25549),
(127242, 'esMX', 'Gracias, $Gcampeón:campeona;. Nos has conseguido un descanso de sus ataques interminables.', '', 25549),
(127241, 'esMX', '¡Un golpe digno de $Gun verdadero archimago:una verdadera archimaga;! Aunque no suena muy mágico...', '', 25549),
(127240, 'esMX', 'La presencia de este enemigo es una gran amenaza para nuestros ejércitos. ¡Derrótalo y así ganaremos tiempo para prepararnos!', '', 25549),
(127239, 'esMX', '¡Voy a revolearte como a un muñeco de trapo, $r!', '', 25549),
(127238, 'esMX', 'Hay un poderoso agente de la Legión cerca. No podemos ignorar esta amenaza. ¡Tienes que destruirlo!', '', 25549),
(127236, 'esMX', 'Los informes indican que hay un demonio particularmente poderoso en esta ubicación. ¡Tenemos que eliminarlo rápido!', '', 25549),
(127235, 'esMX', '', '¿Está vivo?', 25549),
(127234, 'esMX', 'Nuestros primeros contendientes son $Gel poderoso Señor:la poderosa Señora; de la batalla $p y el infame drogbar, Damrul el Forzuto!', '', 25549),
(127233, 'esMX', '', '¿Así que prefieres que me porte como un monstruo?', 25549),
(127232, 'esMX', '', '¡Déjame en paz!', 25549),
(127231, 'esMX', '', '¡Fuera de aquí!', 25549),
(127230, 'esMX', '', 'Hay mucho por hacer.', 25549),
(127229, 'esMX', '', 'No pierdas el tiempo.', 25549),
(127228, 'esMX', '¡Bienvenidos, guerreros, a la Prueba de ira!', '', 25549),
(127227, 'esMX', '', 'No bajes la guardia.', 25549),
(127226, 'esMX', '', 'Vivo mi vida en las sombras.', 25549),
(127225, 'esMX', '', 'Mis cuchillas siempre están afiladas.', 25549),
(127224, 'esMX', '', '¿Qué es lo que quieres?', 25549),
(127223, 'esMX', '', '¡Lo lograste, $GSeñor abisal:Señora abisal;! Kanrethad ha regresado con nosotros.', 25549),
(127222, 'esMX', '', '¿Quieres que cave una tumba para ti?', 25549),
(127221, 'esMX', '', 'A algunos la muerte les sienta bien.', 25549),
(127220, 'esMX', '', '¡Deja de molestarme!', 25549),
(127219, 'esMX', '', 'La no-muerte es eterna.', 25549),
(127218, 'esMX', '', '¿Eso es todo?', 25549),
(127217, 'esMX', '', 'Que sufras bien.', 25549),
(127216, 'esMX', '', 'Mi hacha está hambrienta.', 25549),
(127215, 'esMX', '', 'La no-muerte te da la bienvenida.', 25549),
(127214, 'esMX', '', '¿Sí?', 25549),
(127213, 'esMX', '', '¡He derrotado a campeones y jefes! ¡Tú no eres más que un insecto insignificante!', 25549),
(127212, 'esMX', '', '¡Buen trabajo! Nuestras tropas podrán continuar luchando hasta que termine la estampida.', 25549),
(127211, 'esMX', '', '¡Una de nuestras patrullas ha quedado atrapada detrás de esta estampida! Debemos llevarles brebaje de tormenta para que recuperen fuerzas. ¿Pero cómo...?', 25549),
(127210, 'esMX', '', '¡Tengo más poder en un solo dedo que tú en todo el cuerpo!', 25549),
(127209, 'esMX', '', 'No me molestes.', 25549),
(127208, 'esMX', '', 'Los Tótem siniestro volverán a alzarse.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127207, 'esMX', '', 'Mantén a tus amigos cerca...', 25549),
(127206, 'esMX', '', 'Ya vete de aquí.', 25549),
(127205, 'esMX', '', '¿Qué necesitas de la vieja Magatha?', 25549),
(127204, 'esMX', '', '¿Qué necesitas?', 25549),
(127203, 'esMX', '', 'No tengo tiempo para tonterías.', 25549),
(127202, 'esMX', '', '¡No dejes que absorban su poder!', 25549),
(127201, 'esMX', '', '¡No interrumpirás este ritual!', 25549),
(127200, 'esMX', '', '¡El poder de Kanrethad le pertenece a la Legión Ardiente!', 25549),
(127199, 'esMX', 'Mis heridas son profundas, pero me he recuperado de situaciones peores. ¡Pronto la Legión sufrirá mi venganza!', '', 25549),
(127198, 'esMX', '', '¿Quieres un cuchillo en la garganta? Es mi especialidad.', 25549),
(127197, 'esMX', '', '¿Es tan difícil?', 25549),
(127196, 'esMX', '', '¡Ya termina de una vez!', 25549),
(127195, 'esMX', '', '¡No quites la vista de los cielos!', 25549),
(127194, 'esMX', '', 'Que los vientos te amparen.', 25549),
(127193, 'esMX', '', '¡Hasta luego!', 25549),
(127192, 'esMX', '', 'Tú me rascas la espalda, yo te doy mis garras.', 25549),
(127191, 'esMX', '', '¿Cómo estás?', 25549),
(127190, 'esMX', '', '¿Hay algún peligro? ¡Yo me encargo!', 25549),
(127189, 'esMX', '¡Estoy preparado! Envíame a las Puertas del Valor. [Hacer cola para la gesta]', '¡Estoy preparada! Envíame a las Puertas del Valor. [Hacer cola para la gesta]', 25549),
(127188, 'esMX', '', '¿Estás $Glisto:lista; para responder al llamado de la gloria, $c?', 25549),
(127187, 'esMX', 'No podemos seguir avanzando hasta que lleguen los refuerzos. ¡Retrocedan, todos!', '', 25549),
(127186, 'esMX', '', 'Ya oyeron a la señorita, ¡todos afuera!', 25549),
(127185, 'esMX', '', 'Sin esperanzas, %s se desploma.', 25549),
(127184, 'esMX', '', 'A %s se le empañan los ojos mientras su escopeta cae al suelo.', 25549),
(127183, 'esMX', '', 'Nadie debería sobrevivir a sus nietos...', 25549),
(127182, 'esMX', '', '¡Jarod! Se... se ha ido. ¡Tenemos que retirarnos hasta que lleguen los refuerzos!', 25549),
(127181, 'esMX', '', 'Creo... que solo... descansaré un momento...', 25549),
(127180, 'esMX', '', 'No... puedo seguir...', 25549),
(127179, 'esMX', '¡Señor de la batalla $p! ¡Por aquí!', '', 25549),
(127178, 'esMX', 'Espero que estés $Gpreparado, Señor de la batalla:preparada, Señora de la batalla;. He traído algunos suministros por si acaso los necesitas.', '', 25549),
(127177, 'esMX', 'Cuando estés $Glisto:lista; para pelear, desafía a Damrul el Forzuto. Después, párate sobre la runa y comenzará la pelea.', '', 25549),
(127176, 'esMX', 'Cuando estés $Glisto:lista; para pelear, desafía a Damrul el Forzuto. Después, párate sobre la runa y comenzará la pelea.', '', 25549),
(127175, 'esMX', 'Espero que te hayas preparado, $GSeñor de la batalla:Señora de la batalla;. He traído algunos suministros por si acaso los necesitas.', '', 25549),
(127174, 'esMX', '¡Señor de la batalla $p! ¡Por aquí!', '', 25549),
(127173, 'esMX', 'Gracias, $Gguerrero:guerrera;.', '', 25549),
(127172, 'esMX', 'Ahora entiendo lo que quiso decir el chamán. He aprendido una lección de humildad, y ahora soy más fuerte gracias a eso.', '', 25549),
(127171, 'esMX', 'Espero nuestro enfrentamiento con ansias, $Gguerrero:guerrera;. Si es que sobrevives hasta entonces.', '', 25549),
(127170, 'esMX', '¡Pareces ser de voluntad fuerte, pero mi voluntad y mi mente son superiores!', '', 25549),
(127169, 'esMX', 'Cuando hablé con el chamán de mi tribu, predijo que yo ganaría este día. Quizá te convenga retirarte con honor, $Gcompañero guerrero:compañera guerrera;.', '', 25549),
(127168, 'esMX', 'Me equivoqué al juzgar tu fuerza, brul. Siempre creí que el tamaño era importante, pero puede que estuviera errado.', '', 25549),
(127167, 'esMX', 'Es normal que desees que me vaya. La mayoría de mis adversarios pierden en cuanto me ven.', '', 25549),
(127166, 'esMX', 'Te permitiría entrenar conmigo, pero estas pesas son tan grandes como tú. Regresa cuando tengas músculos más grandes.', '', 25549),
(127165, 'esMX', 'Tu fuerza debe ser igual que tu tamaño. Insignificante.', '', 25549),
(127164, 'esMX', '', 'Me pregunto si alguien recordará tu nombre después de tu fracaso...', 25549),
(127163, 'esMX', '', 'Tu clase no debería estar aquí. Esta tierra es NUESTRA, ¡y solo nosotros somos dignos de entrar en este torneo!', 25549),
(127162, 'esMX', '', 'Será un placer ver su vergüenza cuando caigas.', 25549),
(127161, 'esMX', '', 'Odyn fue un tonto al elegirte como su $Gcampeón:campeona;.', 25549),
(127160, 'esMX', '', 'No podemos permitir que la Legión Ardiente triunfe.', 25549),
(127159, 'esMX', '¡No nos detendrán!', '', 25549),
(127158, 'esMX', 'No interferirás con nuestros planes. ¡La Legión Ardiente controlará el poder de Kanrethad! ¡Cae ante nuestra fuerza!', '', 25549),
(127157, 'esMX', '¡La luz prevalece!', '', 25549),
(127156, 'esMX', '¡La Hermandad lidera el ataque!', '', 25549),
(127155, 'esMX', '¡Contempla la Luz!', '', 25549),
(127154, 'esMX', 'Aajj, no mates a tantos sin mí.', '', 25549),
(127153, 'esMX', 'Debo retirarme.', '', 25549),
(127152, 'esMX', 'Regresaré...', '', 25549),
(127151, 'esMX', 'Es un honor.', '', 25549),
(127150, 'esMX', 'Viajemos juntos.', '', 25549),
(127149, 'esMX', 'Estoy a tu lado.', '', 25549),
(127148, 'esMX', '¡Cae ante la Luz!', '', 25549),
(127147, 'esMX', '¡Por la Hermandad!', '', 25549),
(127146, 'esMX', '¡Témele a mi espada!', '', 25549),
(127145, 'esMX', 'Purifiquemos la oscuridad de estas tierras.', '', 25549),
(127144, 'esMX', '¡La Hermandad resiste unida!', '', 25549),
(127143, 'esMX', 'Peleamos juntos.', '', 25549),
(127142, 'esMX', 'Invasores de Escudo de Tormenta asesinados: $1i', '', 25549),
(127141, 'esMX', 'Invasores de El Exodar asesinados: $1i', '', 25549),
(127140, 'esMX', 'Invasores de Darnassus asesinados: $1i', '', 25549),
(127139, 'esMX', 'Invasores de Forjaz asesinados: $1i', '', 25549),
(127138, 'esMX', 'Invasores de Ventormenta asesinados: $1i', '', 25549),
(127137, 'esMX', 'Invasores de Lanza de Guerra asesinados: $1i', '', 25549),
(127136, 'esMX', 'Invasores de Lunargenta asesinados: $1i', '', 25549),
(127135, 'esMX', 'Invasores de Entrañas asesinados: $1i', '', 25549),
(127134, 'esMX', 'Invasores de la Cima del Trueno asesinados: $1i', '', 25549),
(127133, 'esMX', 'Defensor mítico de Escudo de Tormenta', '', 25549),
(127132, 'esMX', 'Defensor heroico de Escudo de Tormenta', '', 25549),
(127131, 'esMX', 'Defensor de Escudo de Tormenta', '', 25549),
(127130, 'esMX', 'Defensor mítico de El Exodar', '', 25549),
(127129, 'esMX', 'Defensor heroico de El Exodar', '', 25549),
(127128, 'esMX', 'Defensor de El Exodar', '', 25549),
(127127, 'esMX', 'Defensor mítico de Darnassus', '', 25549),
(127126, 'esMX', 'Defensor heroico de Darnassus', '', 25549),
(127125, 'esMX', 'Defensor de Darnassus', '', 25549),
(127124, 'esMX', 'Defensor mítico de Forjaz', '', 25549),
(127123, 'esMX', 'Defensor heroico de Forjaz', '', 25549),
(127122, 'esMX', 'Defensor de Forjaz', '', 25549),
(127121, 'esMX', 'Defensor mítico de Ventormenta', '', 25549),
(127120, 'esMX', 'Defensor heroico de Ventormenta', '', 25549),
(127119, 'esMX', 'Defensor de Ventormenta', '', 25549),
(127118, 'esMX', 'Defensor mítico de Lanza de Guerra', '', 25549),
(127117, 'esMX', 'Defensor heroico de Lanza de Guerra', '', 25549),
(127116, 'esMX', 'Defensor de Lanza de Guerra', '', 25549),
(127115, 'esMX', 'Defensor mítico de Lunargenta', '', 25549),
(127114, 'esMX', 'Defensor heroico de Lunargenta', '', 25549),
(127113, 'esMX', 'Defensor de Lunargenta', '', 25549),
(127112, 'esMX', 'Defensor mítico de Entrañas', '', 25549),
(127111, 'esMX', 'Defensor heroico de Entrañas', '', 25549),
(127110, 'esMX', 'Defensor de Entrañas', '', 25549),
(127109, 'esMX', 'Defensor mítico de la Cima del Trueno', '', 25549),
(127108, 'esMX', 'Defensor heroico de la Cima del Trueno', '', 25549),
(127107, 'esMX', 'Defensor de la Cima del Trueno', '', 25549),
(127106, 'esMX', 'Defensor mítico de Orgrimmar', '', 25549),
(127105, 'esMX', 'Defensor heroico de Orgrimmar', '', 25549),
(127104, 'esMX', '¡El contagio te consumirá!', '', 25549),
(127103, 'esMX', '¡Nadie puede detener a la Legión Ardiente!', '', 25549),
(127102, 'esMX', '¡No saldrán de aquí con vida!', '', 25549),
(127101, 'esMX', 'Defensor de Orgrimmar', '', 25549),
(127100, 'esMX', 'Invasores de Orgrimmar asesinados: $1i', '', 25549),
(127099, 'esMX', 'Puede que Raest haya escapado, pero lo encontraremos. Y cuando llegue ese día, espero volver a contar con tu ayuda.', '', 25549),
(127097, 'esMX', '', 'Fue una decisión muy sabia. Lograremos muchas cosas juntos.', 25549),
(127096, 'esMX', 'No podemos resignarnos; no importa lo que hagan los demonios.', 'No podemos resignarnos; no importa lo que hagan los demonios.', 25549),
(127095, 'esMX', 'No... no pude controlarme...', 'No... no pude controlarme...', 25549),
(127094, 'esMX', 'Mi cabeza... ¡al... aléjate de esa cosa!', 'Mi cabeza... ¡al... aléjate de esa cosa!', 25549),
(127093, 'esMX', '¿Qué... qué pasó?', '¿Qué... qué pasó?', 25549),
(127092, 'esMX', '', 'Ánimo, Roland. Parece que ha llegado la ayuda.', 25549),
(127091, 'esMX', '¡|TInterface\\Icons\\ABILITY_HUNTER_PET_RAPTOR.BLP:20|t%s |cFFFF0000|Hspell:235886|h[llama]|h|r a su manada!', '', 25549),
(127090, 'esMX', '', 'Mmm, delicioso... ¡como un cuchillo en la oscuridad! Encontrarás tu último objetivo en Ventormenta. ¡Será el desafío más grande que hayas tenido!', 25549),
(127089, 'esMX', '', 'Ahí está, contra la pared. Dicen que es un cobarde que se escuda detrás de su armadura. ¡Demuéstrale lo equivocado que está!', 25549),
(127088, 'esMX', '', 'Ese alarido de muerte... ¡es música para mis oídos! Hemos localizado el siguiente objetivo en Forjaz, oculto en las sombras del consejo enano.', 25549),
(127087, 'esMX', '', 'Tu objetivo está en una fiesta en un jardín cerca del Bancal del Guerrero. ¡Ten cuidado! Sus aliados son hechiceros tan poderosos como ella. Y no te olvides de los guardianes.', 25549),
(127086, 'esMX', '', 'Ah, una puñalada limpia... ¡Encantador! Tu siguiente objetivo te espera en Darnassus. Te recomiendo que entres por la aldea debajo de Teldrassil.', 25549),
(127085, 'esMX', '', 'Tu primer objetivo se hace pasar por un simple sacerdote y se pasea por la ciudad a la vista de todos. ¡Ten cuidado de su gólem de cristal! Sepáralos si puedes... y hazlo con discreción.', 25549),
(127084, 'esMX', '', 'Recuerda... aunque estás tratando de ayudarlos, la Alianza creerá que estás atacando a uno de los suyos.', 25549),
(127083, 'esMX', '', 'No podemos arriesgarnos a que cometas un asesinato en una ciudad aliada, pero nadie se escandalizará si eliminas un objetivo en el Exodar. Tú encárgate de ese objetivo, nosotros nos ocuparemos de Lunargenta.', 25549),
(127082, 'esMX', '', '¡Pobres y miserables objetivos! Ningún escondite los amparará de las sombras. Ven, visita a tus colegas. Lord Ravenholdt tiene un regalo para ti.', 25549),
(127081, 'esMX', '', '¡Allí! En el lugar más transitado que puedas imaginar: la casa de subastas. ¡No hagas ruido, ataca con firmeza y desaparece de inmediato!', 25549),
(127080, 'esMX', '', 'Mmm, delicioso... ¡como un cuchillo en la oscuridad! Encontrarás tu último objetivo en Orgrimmar. ¡Será el desafío más grande que hayas tenido!', 25549),
(127079, 'esMX', '', 'Ahí está, junto a la hoguera. Dicen que es un cobarde que se escuda detrás de su armadura. ¡Demuéstrale lo equivocado que está!', 25549),
(127078, 'esMX', '', 'Ese alarido de muerte... ¡es música para mis oídos! Hemos localizado el siguiente objetivo en la Cima del Trueno, oculto a la sombra del líder tauren.', 25549),
(127077, 'esMX', '', 'Tu objetivo está tomando el té con invitados en la terraza sobre el Barrio de los Pícaros. ¡Ten cuidado! Sus aliados son hechiceros tan poderosos como ella. Tendrás que encontrar la forma de llegar hasta allí.', 25549),
(127076, 'esMX', '', 'Ay, una puñalada limpia... ¡Encantador! Tu próximo objetivo te espera en Entrañas. Te recomiendo que entres por las cloacas del oeste.', 25549),
(127075, 'esMX', '', 'Tu primer objetivo se ha establecido como un aristócrata acaudalado que se pasea por la ciudad ante la vista de todos. ¡Ten cuidado de su gólem arcano! Sepáralos si puedes... y hazlo con discreción.', 25549),
(127074, 'esMX', '', 'Recuerda... aunque estás tratando de ayudarlos, la Horda creerá que estás atacando a uno de los suyos.', 25549),
(127073, 'esMX', '', 'No podemos arriesgarnos a que cometas un asesinato en una ciudad aliada, pero nadie se escandalizará si eliminas un objetivo en Lunargenta. Tú encárgate de ese objetivo, y yo iré al Exodar.', 25549),
(127072, 'esMX', '', 'Nuestros agentes creen haber identificado homúnculos en Lunargenta y en el Exodar.', 25549),
(127071, 'esMX', '', 'Los demonios sabían que los illidari los encontrarían si trataban de infiltrarse otra vez en nuestras ciudades, así que enviaron a estos... homúnculos.', 25549),
(127070, 'esMX', '', 'Parece que los señores del terror han descubierto cómo crear agentes no-muertos tan "vivos" que hasta a mí me cuesta distinguirlos.', 25549),
(127069, 'esMX', '', 'Los pensamientos que expresaba eran muy coherentes, y su piel... tan bien conservada. Pero algunas señales lo delataron.', 25549),
(127068, 'esMX', '', 'No debería hacer eso, y SIN DUDA no tendría que tener ese color.', 25549),
(127067, 'esMX', '', 'Pero mira lo que pasa si corto justo aquí...', 25549),
(127066, 'esMX', '', 'Me considero una adepta cazadora de no-muertos. Y ni siquiera yo lo noté al principio.', 25549),
(127065, 'esMX', '', '¡Hoja de las sombras! ¡Por aquí!', 25549),
(127064, 'esMX', '¡|TInterface\\Icons\\SPELL_NATURE_UNRELENTINGSTORM.BLP:20|t%s comienza a lanzar |cFFFF0000|Hspell:235766|h[Nova de relámpagos]|h|r !', '', 25549),
(127063, 'esMX', '', 'Ven, Roland. Abandonemos este lugar despreciable antes de que vuelvas a enfermarte.', 25549),
(127062, 'esMX', 'La oscuridad de este mundo ya es suficiente; no necesita más sombras. Tienes mi agradecimiento, $Gcampeón:campeona;.', '', 25549),
(127061, 'esMX', 'Los conjuradores eredar están reuniendo fuerzas oscuras del Vacío. ¡Detenlos!', '', 25549),
(127060, 'esMX', '', '¿Este lugar no te recuerda a tu hogar?', 25549),
(127059, 'esMX', '', '¿Estás seguro de que no tienes otro sitio a donde ir, Roland?', 25549),
(127058, 'esMX', '', '¿Por qué siempre estás tan cerca, Roland?', 25549),
(127057, 'esMX', '', '¡Mi escudo los protege, héroes!', 25549),
(127056, 'esMX', 'Abriremos un portal hasta su posición, pero no podré mantenerlo por mucho tiempo. ¡Debemos detener a Raest!', '', 25549),
(127055, 'esMX', 'Karam insistió en que lo enviáramos antes que a ti, pero temo que no podrá enfrentar este desafío solo.', '', 25549),
(127054, 'esMX', 'No tenemos mucha información sobre lo que sucede, pero parece que encontró una manera de usar la energía del Vacío Abisal para potenciar su magia nigromántica.', '', 25549),
(127053, 'esMX', '¡$GCampeón:Campeona;! Nuestros magos han localizado la ubicación de Raest Lanzarcana en el Vacío Abisal!', '', 25549),
(127052, 'esMX', '¡Derriba esa monstruosidad! ¡No hay que dejar pasar nada!', '¡Derriba esa monstruosidad! ¡No hay que dejar pasar nada!', 25549),
(127051, 'esMX', 'Mi navío y yo debemos irnos a otra parte. ¡Disfruta de este... regalo de despedida!', '', 25549),
(127050, 'esMX', 'Será mejor que regrese al combate.', 'Será mejor que regrese al combate.', 25549),
(127049, 'esMX', 'Te debo la vida, sacerdotisa.', 'Te debo la vida, sacerdotisa.', 25549),
(127048, 'esMX', 'No olvidaré tu compasión.', 'No olvidaré tu compasión.', 25549),
(127047, 'esMX', 'Estoy en deuda contigo.', 'Estoy en deuda contigo.', 25549),
(127046, 'esMX', 'Por fin la niebla se levanta...', 'Por fin la niebla se levanta...', 25549),
(127045, 'esMX', 'Has aliviado mi dolor. Gracias, $n.', 'Has aliviado mi dolor. Gracias, $n.', 25549),
(127044, 'esMX', 'Tienes mi agradecimiento.', 'Tienes mi agradecimiento.', 25549),
(127039, 'esMX', 'La Égida de Aggramar debe estar en posición. ¡Comenzaremos cuando lo ordenen, héroes!', '', 25549),
(127038, 'esMX', '¡Prepara tus cuchillas! ¡Ya vienen los demonios!', '¡Prepara tus cuchillas! ¡Ya vienen los demonios!', 25549),
(127037, 'esMX', 'Artilleros, ¡abran fuego sobre estas escorias mortales! ¡Aniquílenlos con fuego infernal!', '', 25549),
(127032, 'esMX', 'Estamos listos.', 'Estamos listas.', 25549),
(127031, 'esMX', '¡Prepárense! La Legión no descansará hasta capturar el escudo.', '¡Prepárense! La Legión no descansará hasta capturar el escudo.', 25549),
(127030, 'esMX', 'La Cruz escarchada es un artículo de inmenso poder. Sería imprudente intentar poseer más de una. Cuando hayas utilizado a la Vermis de escarcha, podremos invocar otra.', '', 25549),
(127029, 'esMX', '¿Por qué no podemos comenzar otro ritual?', '¿Por qué no podemos comenzar otro ritual?', 25549),
(127028, 'esMX', 'Parece que lograste reducir el crecimiento de su población. ¡Bien hecho! No queremos que monstruosidades como estas se diseminen más allá de estas costas.', '', 25549),
(127027, 'esMX', '', 'Simplemente no estamos preparados para contar con múltiples núcleos de la falla a la vez. Aún tienes uno en tu poder. Cuando lo hayas utilizado, comenzaremos a cargar otro.', 25549),
(127026, 'esMX', 'Las harpías son repugnantes, pero... ¿harpías leales a la Legión? ¡Eso sí que es intolerable! $GCampeón:Campeona;, encárgate de mantener esta amenaza bajo control.', '', 25549),
(127025, 'esMX', '¿Por qué no podemos alimentar el núcleo de la falla?', '¿Por qué no podemos alimentar el núcleo de la falla?', 25549),
(127024, 'esMX', '¡Llegas demasiado tarde, mortal! ¡Mi centro de mando acaba de llegar!', '', 25549),
(127023, 'esMX', '', 'El poder de Dalaran solo puede canalizarse una vez. Parece que aún posees un cristal de enfoque en tu poder. Cuando lo hayas utilizado, mi voluntad de mago formará otro para ti.', 25549),
(127022, 'esMX', '¿Por qué no podemos enfocar otro cristal?', '¿Por qué no podemos enfocar otro cristal?', 25549),
(127021, 'esMX', '', 'Los infernales son seres retorcidos y extremadamente poderosos. Debemos tener cuidado con ellos. Aún tienes una filacteria en tu poder; sería imprudente tener más.', 25549),
(127020, 'esMX', '¿Por qué no podemos invocar a otro infernal?', '¿Por qué no podemos invocar a otro infernal que utilizar?', 25549),
(127019, 'esMX', '', 'Lo siento, pero no puedo invocar otro asalto hasta que hayas desplegado a todas las tropas que tienes reunidas actualmente.', 25549),
(127018, 'esMX', '¿Por qué no puedo convocar a las Val''kyr?', '¿Por qué no puedo convocar a las Val''kyr?', 25549),
(127017, 'esMX', 'Viajera, el peligro nos espera más adelante. El mal se ha apoderado del área.', 'Viajera, el peligro nos espera más adelante. El mal se ha apoderado del área.', 25549),
(127016, 'esMX', '', 'Mmm, eso fue desafortunado. Seguramente alguien con tus habilidades es capaz de revivirlo, ¿verdad?', 25549),
(127015, 'esMX', 'Me disculpo, solo tenemos suficientes tropas para preparar una única vanguardia de despliegue a la vez. Cuando hayas dado tus órdenes, podremos solicitar otra.', '', 25549),
(127014, 'esMX', '¿Por qué no puedo llamar a otra vanguardia?', '¿Por qué no puedo llamar a otra vanguardia?', 25549),
(127013, 'esMX', '', '¡Basta de parloteo! ¡Tenemos una nave que salvar!', 25549),
(127012, 'esMX', '', 'No es momento de insinuaciones despreciables, mi querida S''theno. Lo primero que hicieron fue sacarnos las armas. ¡Si nos ayudas a matar a esas criaturas horrendas, podremos encargarnos de las reparaciones!', 25549),
(127011, 'esMX', '', 'Nunca debieron llegar tan cerca, Malevolencia. ¿Por qué el Martillo vil no les disssparó?', 25549),
(127010, 'esMX', '', '¡Reproducir escena fantástica del Martillo Vil destruyendo a una de las naves de la Legión mientras el resto salta al vacío!', 25549),
(127009, 'esMX', '', 'Tienes razón, S''theno. Si no nos arriesgamos, moriremos de todos modos. ¡$GDestripador:Destripadora; $n, tenemos que llegar a la consola principal arriba!', 25549),
(127006, 'esMX', '', 'Gracias, $GAlto señor:Alta señora;. Has traído paz a mis ancestros.', 25549),
(127005, 'esMX', '', '$GAlto señor:Alta señora;, el arma que blandes es necesaria para liberar a estos espíritus viles. Destruye sus colgantes y libera a mis ancestros de esta maldición ancestral.', 25549),
(127004, 'esMX', '', 'Bien hecho, $Gcampeón:campeona;. Espero que sus espíritus finalmente encuentren la paz.', 25549),
(127003, 'esMX', '', 'Los espíritus de estas ruinas están ligados a la Legión Ardiente por un pacto ancestral. Ponlos a descansar para que conozcan la paz.', 25549),
(127002, 'esMX', 'Si llegas a necesitar otro de estos, ven y dímelo. Yo me encargo.', '', 25549),
(127001, 'esMX', '¡Magnífico! Disfruta de tu creación antes de que la magia desaparezca.', '', 25549),
(127000, 'esMX', 'Deberías ir a que te revisen.', 'Deberías ir a que te revisen.', 25549),
(126999, 'esMX', 'Se dice que los restos de los que fueron enterrados en estas ruinas tienen propiedades mágicas. ¡Veamos si los rumores son ciertos! Recupera los huesos antiguos y colócalos en el altar en ruinas.', '', 25549),
(126998, 'esMX', '¡Al demonio con esto, haré mi propia orden de magos... con Hearthstone ... y súcubos! Y ahora que lo pienso, ¡olviden la orden de magos!', '', 25549),
(126997, 'esMX', '¿No te molesta si me quedo con parte del botín?', '', 25549),
(126996, 'esMX', 'Te voy a cobrar más por esto...', '', 25549),
(126995, 'esMX', '¡Ay! ¡Deja de golpearme! ¡Golpea al héroe!', '', 25549),
(126994, 'esMX', 'Puedo hacerlo mejor.', 'Puedo hacerlo mejor.', 25549),
(126993, 'esMX', 'Nos vamos a separar para siempre.', 'Nos vamos a separar para siempre.', 25549),
(126992, 'esMX', 'No eres tú, soy yo.', 'No eres tú, soy yo.', 25549),
(126991, 'esMX', '¡Creí que eras tú!', '¡Creí que eras tú!', 25549),
(126990, 'esMX', 'Fue solo una vez.', 'Fue solo una vez.', 25549),
(126989, 'esMX', 'Vas a tener que pagar por mis reparaciones.', '', 25549),
(126988, 'esMX', 'Fue solo una vez.', 'Fue solo una vez.', 25549),
(126987, 'esMX', '¡Eso te pasa por no dejar propina!', '', 25549),
(126986, 'esMX', 'Debería empezar a cobrar por cadáver.', '', 25549),
(126985, 'esMX', 'Deberíamos ver a otras personas.', 'Deberíamos ver a otras personas.', 25549),
(126984, 'esMX', 'Sí, sé que soy el mejor.', '', 25549),
(126983, 'esMX', 'No eres tú, soy yo.', 'No eres tú, soy yo.', 25549),
(126982, 'esMX', 'Espero que me paguen por el riesgo.', '', 25549),
(126981, 'esMX', 'Aun así podemos ser amigos.', 'Aun así podemos ser amigos.', 25549),
(126980, 'esMX', '¡Tengo un truco para mostrarte!', '', 25549),
(126979, 'esMX', '¡Prepárate para una muerte suavecita y esponjosa!', '', 25549),
(126978, 'esMX', '', '¡Malditos sean! ¡Vamos!', 25549),
(126977, 'esMX', '¿Te ayudo?', '', 25549),
(126976, 'esMX', 'Elige una carta. ¡Cualquiera!', '', 25549),
(126975, 'esMX', '¡Bienvenido, bienvenido! Sírvete un par de bebidas y algo de comer.', '¡Bienvenida, bienvenida! Sírvete un par de bebidas y algo de comer.', 25549),
(126974, 'esMX', '¡Última llamada! ¡Voy a abrir un portal a la siguiente taberna!', '¡Última llamada! ¡Voy a abrir un portal a la siguiente taberna!', 25549),
(126973, 'esMX', '¡Venga, vámonos! ¡A la siguiente taberna!', '¡Venga, vámonos! ¡A la siguiente taberna!', 25549),
(126972, 'esMX', 'Creo que ya hemos buscado suficientes reliquias por hoy. Vamos a darles tiempo a los espíritus para que se tranquilicen. ¡Disfruta del botín!', '', 25549),
(126971, 'esMX', '¡Tengo un as bajo la manga!', '', 25549),
(126970, 'esMX', 'Las viejas ruinas como estas están repletas de rarezas que todo coleccionista querría tener. Recupera todas las reliquias que puedas, ¡pero cuidado con los espíritus que acechan por ahí!', '', 25549),
(126969, 'esMX', '¡El Gran Akazamzarak está listo para la acción!', '', 25549),
(126968, 'esMX', '¡Si quieres ver mis hechizos, muéstrame tu moneda!', '', 25549),
(126967, 'esMX', 'Muy bien, vamos a enseñarles algunos trucos a estos tipos.', '', 25549),
(126966, 'esMX', 'Hello, $c, do you wish to research more about your artifact? \n\nI would like to assist you, but it appears you might still be carrying Artifact Research Notes. Reading them will further your knowledge.', 'Hola, $c, ¿quieres investigar más sobre tu artefacto? \n\nMe gustaría ayudarte, pero parece que tienes notas de investigación del artefacto que, al leerlas, te ayudarán a ahondar más en tu conocimiento.', 25549),
(126965, 'esMX', 'Puedes descansar por ahora, héroe. Te lo has ganado.', '', 25549),
(126964, 'esMX', '¡$GCampeón:Campeona;! No permitas el avance de las fuerzas de la Legión. ¡Únete a nuestros aliados en el frente de batalla y protege nuestras tierras!', '', 25549),
(126962, 'esMX', '¡La Legión nos engañó! ¡El  único objetivo de sus ataques era distraernos mientras establecían una base en la isla de Reposo del Escudo!', '', 25549),
(126961, 'esMX', '¡La Legión Ardiente se atreve a asaltar Stormheim! ¡Extirpa su asquerosa presencia de esta tierra, $Gcampeón:campeona;, y álzate con la gloria!', '', 25549),
(126958, 'esMX', 'Muy bien, pero ¿puedes hacerlo otra vez?', 'Muy bien, pero ¿puedes hacerlo otra vez?', 25549),
(126957, 'esMX', 'Estás mejorando.', 'Estás mejorando.', 25549),
(126956, 'esMX', 'Excelente estrategia.', 'Excelente estrategia.', 25549),
(126955, 'esMX', '¡No te rindas!', '¡No te rindas!', 25549),
(126954, 'esMX', 'Esfuérzate más.', 'Esfuérzate más.', 25549),
(126953, 'esMX', '¡Otra vez!', '¡Otra vez!', 25549),
(126952, 'esMX', 'Parece que estás listo.', 'Parece que estás lista.', 25549),
(126951, 'esMX', 'Patético.', 'Patético.', 25549),
(126950, 'esMX', 'Empecemos.', 'Empecemos.', 25549),
(126949, 'esMX', 'Gracias a tu ayuda, ahora podemos desarrollar una cura confiable para este veneno.', '', 25549),
(126948, 'esMX', '¡Una aranasi se llevó a nuestras tropas para alimentar a su linaje vil! Mata a estos arácnidos y recoge sus sacos de veneno para desarrollar una cura contra sus toxinas.', '', 25549),
(126947, 'esMX', 'Nuestras tropas están llegando al campamento a salvo y, lo más importante, sin rastros de veneno. ¡Buen trabajo!', '', 25549),
(126946, 'esMX', 'Una aranasi se ha apoderado de nuestras fuerzas para alimentar a su linaje. ¡Gran $Gmaestro:maestra;, debemos confiar en tu habilidad para acabar con ese demonio y depurar a los cautivos para salvarlos del veneno!', '', 25549),
(126945, 'esMX', '¡Me largo de aquí!', '¡Me largo de aquí!', 25549),
(126944, 'esMX', '¡Me sentía más débil con cada segundo que pasaba! Gracias.', '¡Me sentía más débil con cada segundo que pasaba! Gracias.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126943, 'esMX', 'Gracias, Gran maestro.', 'Gracias, Gran maestra.', 25549),
(126942, 'esMX', '¡Tus acciones han despertado a los espíritus!', '¡Tus acciones han despertado a los espíritus!', 25549),
(126941, 'esMX', 'Como mucho, hemos logrado retrasar a nuestro enemigo. Debemos estar preparados, esto aún no termina.', '', 25549),
(126940, 'esMX', '¡Desciendan sobre nuestros enemigos y destruyan la base que tienen en este mundo! ¡No dejen nada a lo que puedan aferrarse y no les tengan piedad!', '', 25549),
(126939, 'esMX', '¡Suficiente!', '', 25549),
(126938, 'esMX', '¡La Legión se está retirando! ¡Salten del navío! ¡Los hipogrifos los atraparán!', '', 25549),
(126937, 'esMX', '¿Otra vez? Tardé siglos en quitarme la armadura y ahora me la tengo que volver a poner. Mmm.', '¿Otra vez? Tardé siglos en quitarme la armadura y ahora me la tengo que volver a poner. Mmm.', 25549),
(126936, 'esMX', 'Aquí están los materiales que solicitaste, Alard.', 'Aquí están los materiales que solicitaste, Alard.', 25549),
(126935, 'esMX', 'La paciencia es una virtud, pero no podemos darnos el lujo de seguir esperando. Prepárate.', '', 25549),
(126934, 'esMX', '', '¿De verdad crees que tus compañeros están listos para unirse a nuestro asalto?', 25549),
(126933, 'esMX', '', 'Entrenas o te mueres. Aquí no hay segundas oportunidades.', 25549),
(126932, 'esMX', 'Estoy seguro de que Grisillo estará complacido de ver lo que logramos. Envíale mis saludos.', '', 25549),
(126931, 'esMX', '¡Listo! Un excelente trabajo, si me permites decirlo. Ya puedes llevártela.', '', 25549),
(126930, 'esMX', '¡Y por último, aunque no menos importante, la joya!', '', 25549),
(126929, 'esMX', 'Ahora solo debería colocar la piedra ley aquí... yyyyy aquí....', '', 25549),
(126928, 'esMX', 'Primero, debo fundir todo este mineral...', '', 25549),
(126927, 'esMX', '¡Muy bien, mejoremos esta gualdrapa!', '', 25549),
(126926, 'esMX', 'Estoy... estoy vivo, pero no estoy en condiciones de pelear. ¡Date prisa, debes detenerlo!', '', 25549),
(126925, 'esMX', 'Buen trabajo. ¡Poner el poder de esos truhanes grandes en su contra fue una idea... aplastante!', '', 25549),
(126924, 'esMX', 'Los naga suponen una amenaza constante para nuestro objetivo. Hemos subyugado a uno de sus brutos y lo usaremos contra ellos. ¡Móntalo hacia la batalla contra los naga!', '', 25549),
(126923, 'esMX', 'Envíame hasta Cantosombrío. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Envíame hasta Cantosombrío. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(126922, 'esMX', 'Estoy listo para regresar, Grisillo.', 'Estoy lista para regresar, Grisillo.', 25549),
(126921, 'esMX', '$GAlto señor:Alta señora;, avísame cuando estés $glisto:lista; para regresar al Salón de la orden y me encargaré de que regresemos a salvo.', '', 25549),
(126920, 'esMX', 'Cuando quieras partir, ven a hablar conmigo y me encargaré de que regresemos a salvo.', '', 25549),
(126919, 'esMX', 'Reunámonos en el Santuario de la Luz. Allí podrás ensillar a la bestia sin problemas.', '', 25549),
(126918, 'esMX', '¡Hemos capturado a la bestia, $GAlto señor:Alta señora;! ¡La Luz nos ha bendecido el día de hoy!', '', 25549),
(126916, 'esMX', '¡El caballo! ¡Rápido, hay que contenerlo!', '', 25549),
(126915, 'esMX', '¡Yo, Raemien, propagaré una vez más la peste sobre esta tierra y haré que todos se arrodillen ante mí!', '', 25549),
(126914, 'esMX', '¡Tú y tus patéticos compañeros se convertirán en soldados de mi ejército de no-muertos!', '', 25549),
(126913, 'esMX', '¡¿BUSCABAS ALGO?! ¡JA, JA, JA!', '', 25549),
(126912, 'esMX', '¡Alguien se lo llevó! Esto no está nada bien...', '', 25549),
(126911, 'esMX', '¡¿Dónde está su cuerpo?! ¡Debería estar aquí!', '', 25549),
(126910, 'esMX', 'Ellos controlarán la retaguardia mientras nosotros acabamos con Osahendido.', '', 25549),
(126909, 'esMX', '¡A MONTAR, PALADINES! ¡CABALGUEMOS!', '', 25549),
(126908, 'esMX', 'Hecho. La gualdrapa está lista. Vamos a la cripta de Osahendido para enfrentar a su espectro.', '', 25549),
(126907, 'esMX', 'Aplicaré el agua a la gualdrapa. Tú y tu arma deberán encargarse del resto, $GAlto señor:Alta señora;.', '', 25549),
(126906, 'esMX', 'Has hecho un trabajo excelente al recuperar el agua, $GAlto señor:Alta señora;. Y te agradezco profundamente por haber salvado a mis paladines.', '', 25549),
(126905, 'esMX', '¡¿Se acabó?! ¿Esto es real? Alta señora, eres tú... creo... creo que puedo regresar sin ayuda. Gracias.', '¡¿Se acabó?! ¿Esto es real? Alta señora, eres tú... creo... creo que puedo regresar sin ayuda. Gracias.', 25549),
(126904, 'esMX', 'Sentí como si me estuvieran arrancando el alma del cuerpo lentamente. El nigromante... Debo ver a Grisillo.', 'Sentí como si me estuvieran arrancando el alma del cuerpo lentamente. El nigromante... Debo ver a Grisillo.', 25549),
(126903, 'esMX', 'Nos rodearon. Yo... intenté luchar, pero... Gracias por salvarme, $GAlto señor:Alta señora;.', 'Nos rodearon. Yo... intenté luchar, pero... Gracias por salvarme, $GAlto señor:Alta señora;.', 25549),
(126902, 'esMX', '¡Aliméntate con sus entrañas, Putriboca!', '', 25549),
(126901, 'esMX', '¡Aspira los vapores de Pestulon y únete a mi ejército!', '', 25549),
(126900, 'esMX', '¡Osseine te concederá una muerte rápida!', '', 25549),
(126898, 'esMX', 'Ya es tarde para salvar a tus aliados, paladín. Sus almas fortalecerán mi ejército...', '', 25549),
(126897, 'esMX', '¡Esta ciudad les pertenece a los muertos! ¡Y pronto tú serás parte de ella!', '', 25549),
(126896, 'esMX', '¡Tu misión es inútil, paladín! Esta ciudad esparcirá la muerte una vez más...', '', 25549),
(126895, 'esMX', 'Tal vez alguien con tus habilidades sería un mejor candidato para recuperar el agua. Llévate algunos de mis paladines, por favor. Quién sabe qué habrá acechando en este lugar.', '', 25549),
(126894, 'esMX', 'Envié a tres de mis mejores hombres a buscarla, pero aún no han regresado. Temo que les haya pasado algo.', '', 25549),
(126893, 'esMX', 'Bienvenido, Alto señor $p. He estado realizando los preparativos para el ritual de purificación de la gualdrapa. Pero hasta ahora no hemos podido conseguir el agua bendita.', '', 25549),
(126892, 'esMX', 'Encarguémonos del Comandante Can''tomas. (Se necesita la Piedra angular rebosante)', 'Encarguémonos del Comandante Can''tomas. (Se necesita la Piedra angular rebosante)', 25549),
(126891, 'esMX', 'Encarguémonos del Comandante Erdris. (Se debe usar la piedra angular gratuita de Jarod).', 'Encarguémonos del Comandante Erdris. (Se debe usar la piedra angular gratuita de Jarod).', 25549),
(126890, 'esMX', 'Nos espera una tarea peligrosa y siniestra, $n. Estos dos exigieron venir con nosotros para asegurarse de que "lo haremos bien". No debería ser así.', '', 25549),
(126889, 'esMX', '', '¡Pagarás... por esto! Tú... pagarás...', 25549),
(126888, 'esMX', '', '¡No... mis preciosuras!', 25549),
(126887, 'esMX', 'Has protegido a nuestras fuerzas de un ataque aéreo bastante desagradable. Mmm, puede que los illidari sepan aprovechar a estos pequeños que has ahuyentado...', '', 25549),
(126886, 'esMX', '', 'Pero antes, mereces un castigo por haberme quitado a mi hermosa mascota.', 25549),
(126885, 'esMX', '', 'En este momento, mis sayaad están tentando a tus débiles magos. ¡Tus aliados se entregarán a la Legión por propia voluntad!', 25549),
(126884, 'esMX', '', '¡Llegas demasiado tarde! ¡El poder de Levia me pertenece! ¡Con sus conocimientos, mis esbirros se infiltrarán en Kirin Tor y lo destruirán desde adentro!', 25549),
(126883, 'esMX', '¡Murciélagos viles! ¡Malditos demonios alados! No solo atormentan nuestras fuerzas sino que se reproducen como conejos. ¡Necesitamos reducir sus filas!', '', 25549),
(126882, 'esMX', '', '¡Debemos detener a la madre de los diablillos! Buena suerte, $Gcampeón:campeona;.', 25549),
(126881, 'esMX', '', 'Su ubicación está bastante protegida, pero nuestros magos del Kirin Tor deberían poder abrir un portal hasta allí por un período breve.', 25549),
(126880, 'esMX', '', 'A esta altura, posiblemente ya haya aprovechado la mayor parte del poder que le robó a Levia. Si es así, no hay forma de saber hasta dónde llegan sus capacidades.', 25549),
(126879, 'esMX', '', '$GCampeón:Campeona;, me alegra poder hablar contigo. Seguramente Victoria ya te ha informado: hemos encontrado a Agatha, la madre de los diablillos.', 25549),
(126878, 'esMX', '', '¡Rápido! La Legión nos invadirá pronto.', 25549),
(126877, 'esMX', '', 'Ven a visitar Bradensbrook de vez en cuando. Todavía quedan muchas aves para disparar.', 25549),
(126876, 'esMX', '', '¡Ha sido un placer trabajar contigo! Gracias por salvar a nuestro poblado.', 25549),
(126875, 'esMX', 'Gracias, $n. Hemos impedido que la Legión dividiera nuestras fuerzas. Al Kirin Tor le complacerá la noticia de nuestra victoria. Me dieron algo para que regresaras con ellos.', '', 25549),
(126874, 'esMX', 'Espero que hayas encontrado la paz, comandante.', '', 25549),
(126873, 'esMX', 'Hemos perdido... el fuerte...', '', 25549),
(126872, 'esMX', 'Los espíritus tienen una enorme resistencia, pero ser consumido por las energías viles a lo largo del tiempo es un tormento que va más allá de la comprensión de la mente de los mortales.', '', 25549),
(126871, 'esMX', 'La caída del navío de la Legión liberó lo que quedaba de las almas que se habían usado para su creación. Estas almas agonizan, perdidas en un dolor incesante. Por favor, ¡libéralas de este tormento!', '', 25549),
(126870, 'esMX', '¡Levántense, soldados! ¡Acepten mi regalo y acaben con la Legión!', '', 25549),
(126869, 'esMX', '¡No puedo permitirte que sigas amenazando la vida de todos, Erdris!', '', 25549),
(126868, 'esMX', 'Terminemos con esto.', '', 25549),
(126867, 'esMX', 'Ten cuidado, $Gcampeón:campeona;. Algo está emergiendo del portal... ¡algo poderoso!', '', 25549),
(126866, 'esMX', '¡Contempla el poder de la energía vil!', '', 25549),
(126864, 'esMX', 'Esperen un momento y recuperen fuerzas. Luego avanzaremos.', '', 25549),
(126863, 'esMX', 'Prepárense. La Legión ha hechizado a Erdris y cree que todos somos sus enemigos.', '', 25549),
(126862, 'esMX', '¡Lo lograste! ¡Alabada sea Elune! No creo que tengamos mucho tiempo.', '', 25549),
(126861, 'esMX', 'Gracias a tus esfuerzos, los prisioneros han recuperado su libertad y sus vidas. Buen trabajo.', '', 25549),
(126860, 'esMX', 'Tienen prisioneros en esta área. ¡Haz todo lo posible para liberarlos, $Gcampeón:campeona;!', '', 25549),
(126859, 'esMX', 'Dieron sus vidas y ahora se merecen un descanso. Has hecho un trabajo noble.', '', 25549),
(126858, 'esMX', 'Los tauren Viltótem están profanando los cuerpos de los caídos. Nadie merece un final así. Ponlos a dormir, $Gcampeón:campeona;.', '', 25549),
(126857, 'esMX', '¡Estúpidos mortales! ¿De verdad creyeron que sería tan fácil derrotar a la Legión Ardiente?', '', 25549),
(126856, 'esMX', '¡Lexera no tolera a los que interfieren con sus asuntos!', '', 25549),
(126855, 'esMX', '<Indícale a tu renacuajo que te siga.>', '<Indícale a tu renacuajo que te siga.>', 25549),
(126854, 'esMX', '¿Syrenne está forzando a los forasteros a cumplir su voluntad? ¡Qué patético!', '', 25549),
(126853, 'esMX', '¡No nos detendrán!', '', 25549),
(126852, 'esMX', '', 'Saluda a Modera de mi parte, $c. Y... gracias.', 25549),
(126851, 'esMX', '', 'De... detrás de ti...', 25549),
(126850, 'esMX', '¡Una vez más, debo arreglar tu desorden, hermano!', '', 25549),
(126849, 'esMX', '¡Inútil! Hazte a un lado. Yo me encargaré de lo que no eres capaz de hacer.', '', 25549),
(126848, 'esMX', '¿Gll grm grmurrmr?', '', 25549),
(126847, 'esMX', '¡Rápido, $ct, te necesitamos en el frente de batalla!', '', 25549),
(126846, 'esMX', '¡Una pícara se ha infiltrado en nuestra ciudad!', '¡Una pícara se ha infiltrado en nuestra ciudad!', 25549),
(126845, 'esMX', '¡La muerte viene por mí!', '¡La muerte viene por mí!', 25549),
(126844, 'esMX', '¡Ayuda! ¡Ayuda!', '¡Ayuda! ¡Ayuda!', 25549),
(126843, 'esMX', '¡Los espías de la Legión están aquí!', '¡Los espías de la Legión están aquí!', 25549),
(126842, 'esMX', '¡No me derribarás, villano!', '¡No me derribarás, villana!', 25549),
(126841, 'esMX', '¡Los asesinos están aquí!', '¡Los asesinos están aquí!', 25549),
(126840, 'esMX', '¡Ciudadanos, ayúdenme!', '¡Ciudadanos, ayúdenme!', 25549),
(126839, 'esMX', '¡Ayuda! ¡Me están atacando!', '¡Ayuda! ¡Me están atacando!', 25549),
(126838, 'esMX', '¡Ah! ¡Son especímenes excelentes, $GSeñor:Señora; de la muerte! Ten, puede que esto te sea útil.', '', 25549),
(126837, 'esMX', '', 'Lo siento, $GAlto señor:Alta señora;. Necesito... algo de tiempo a solas con mis pensamientos.', 25549),
(126836, 'esMX', 'Un uso interesante de la nigromancia. La magia oscura puede ser útil.', '', 25549),
(126835, 'esMX', 'Tu amado exánime dice tener un plan que requiere los huesos de los que fueron sacrificados por la energía vil. Puedes ayudarlo si crees que será útil a nuestra causa. Pero mantén a esa... cosa... vigilada.', '', 25549),
(126834, 'esMX', '¡Ahóguense en las llamas!', '', 25549),
(126833, 'esMX', 'La Legión Ardiente continúa encontrando formas nuevas de corromper los mundos que invade.', '', 25549),
(126832, 'esMX', 'Los muertos atormentados responden el llamado de sus maestros demoníacos. ¡Destrúyelos!', '', 25549),
(126831, 'esMX', '', '¡No te arrepentirás, Archidruida! ¡Estoy lista para la acción!', 25549),
(126830, 'esMX', 'Usar la prisión de Kathra''natir para mantener las defensas de Dalaran quizá no sea una solución de largo plazo, pero me tranquiliza saber que la esencia del demonio está contenida. Vamos, regresemos al Salón del guardián.', '', 25549),
(126828, 'esMX', '', '¡Ajj, maldición!', 25549),
(126827, 'esMX', '¡Eres mío!', '', 25549),
(126826, 'esMX', '', '¡Uhhhh! Mi cabeza...', 25549),
(126825, 'esMX', 'La puerta se está cerrando... ¡Cuidado!', '', 25549),
(126824, 'esMX', '¡Por aquí!', '', 25549),
(126823, 'esMX', 'Seguramente habrá más defensores dentro. Ahora que el Señor Cresta Cuervo ya no está, supongo que Erdris ocupa sus aposentos. Siempre se creyó superior a los demás.', '', 25549),
(126822, 'esMX', '', '¡¿Qué... fue... eso!?', 25549),
(126821, 'esMX', '', '¡Te perseguiré hasta la muerte, $c! ¡No lo olvides!', 25549),
(126820, 'esMX', '', '¡Destruiste mi ilusión! ¡Criatura insolente!', 25549),
(126819, 'esMX', '¡Bien hecho! Con la destrucción del atracador vil, les hemos asestado un buen golpe a las fuerzas de la Legión.', '', 25549),
(126818, 'esMX', 'Temo por las vidas de nuestros aliados si no nos encargamos de este atracador vil.', '', 25549),
(126817, 'esMX', '', '¡No! ¡No puede ser!', 25549),
(126816, 'esMX', '', 'Vaya, sí que eres fuerte. ¡Será muy divertido hacerte pedazos!', 25549),
(126815, 'esMX', '', '¡NO! ¡¿Qué has hecho?! ¡Te haré sufrir!', 25549),
(126814, 'esMX', '$GArchimago:Archimaga;, quedé muy impresionado cuando supe que atrapaste al demonio Kathra''natir en la Piedra de alma natonocturno. ¡Fue muy ingenioso concebir un escudo de contención que nos permitiera mantener a salvo su poder!', '', 25549),
(126813, 'esMX', '', 'Adelante, $c. Vamos a divertirnos.', 25549),
(126812, 'esMX', '', 'Si bien Levia me ha dejado bastante satisfecha, sería muy desconsiderado de mi parte rechazar un regalo así.', 25549),
(126811, 'esMX', '', 'Así que el Kirin Tor me envía más juguetes para entretenerme...', 25549),
(126810, 'esMX', 'Es posible que el Señor Cresta Cuervo sea descuidado con sus responsabilidades, pero yo no. ¡Soldados, ataquen!', '', 25549),
(126809, 'esMX', '', 'Prefiero matarlos aquí que verlos pisoteando mi cosecha. Hagámoslo.', 25549),
(126808, 'esMX', '', '¡No me quedaré de brazos cruzados! ¡Hay que detener los ataques a mi poblado!', 25549),
(126807, 'esMX', 'Han llegado justo a tiempo. Atacarán en cualquier momento. Pero antes, debo pedirles que regresen a Bradensbrook. ¡No tienen por qué estar en esta pelea!', '', 25549),
(126806, 'esMX', 'Fshu quedó marchita. Que sus esporas viajen por siempre en los vientos de Zangar.', '', 25549),
(126805, 'esMX', '¡Ya viene Fshu!', '', 25549),
(126804, 'esMX', 'Fshu no puede sobrevivir mucho en la superficie sin tu ayuda. ¡Necesitamos sanadores, médicos y restaurachampiñones que la protejan!', '', 25549),
(126803, 'esMX', '¡Atención, esporinos! ¡Esporinos de honor! ¡Asistan al espectáculo del crecimiento de Fshu!', '', 25549),
(126802, 'esMX', '¡Fhambar capta el rastro de Levia!', '', 25549),
(126801, 'esMX', '¡Fhambar, ve a encontrar a Levia!', '¡Fhambar, ve a encontrar a Levia!', 25549),
(126800, 'esMX', 'Fhambar espera pacientemente la orden de seguir el rastro de Levia.', '', 25549),
(126799, 'esMX', '', 'Llevaremos a las grullas a un lugar seguro. Algún día, cuando la Costa Quebrada ya no esté invadida por demonios, los hijitos de sus hijitos podrán regresar a su hogar.', 25549),
(126798, 'esMX', 'Tengo... sueño.', '', 25549),
(126797, 'esMX', 'Jugar con los vivos me aburre.', '', 25549),
(126796, 'esMX', '¡Suficiente! ¡Regresaré a mi letargo!', '', 25549),
(126795, 'esMX', '', 'Los crocoliscos de Cala Dentada se acercan a una zona de grullas marinas. ¡Ayúdame a recoger a esos pobres pajaritos y llevémoslos a un lugar seguro!', 25549),
(126794, 'esMX', '', '¡Arg! Esta invasión demoníaca ha destruido tantos hábitats en la Costa Quebrada. ¡La vida salvaje no tiene dónde ir!', 25549),
(126793, 'esMX', '', '¡Asesina a los Sirvientes diablillos antes de que aumenten la energía de Agatha!', 25549),
(126792, 'esMX', '', '¡Gracias por la ayuda! Esos demonios son como mosquitos comparados con Goldrinn, pero eran tantos que quién sabe lo que podría haber sucedido...', 25549),
(126791, 'esMX', '', '¡Goldrinn necesita nuestra ayuda! Un demonio trajo refuerzos para eludir la cacería. ¡Paguémosle con la misma moneda!', 25549),
(126790, 'esMX', '', 'Excelente cacería. ¡Has hecho un buen trabajo, Archidruida!', 25549),
(126789, 'esMX', '', 'Goldrinn ha logrado acorralar a su presa, deberíamos echarle una mano. ¡Y cuando digo mano quiero decir una garfa, una garra... cualquier cosa que sea puntiaguda!', 25549),
(126787, 'esMX', 'Fhambar tiene la esencia. Encuéntrate con él del otro lado del portal y te guiará hasta la maga que buscas.', '', 25549),
(126786, 'esMX', '', '¡Protéjanme, hijos míos! ¡Les daré el poder que necesitan!', 25549),
(126785, 'esMX', 'Jubeka, ¿estás ahí? ¡No permitas que me lleven! ¡No podría soportar un destino así!', '', 25549),
(126784, 'esMX', '¡Basta de juegos!', '', 25549),
(126783, 'esMX', 'Regrésame al bancal.', 'Regrésame al bancal.', 25549),
(126782, 'esMX', 'Una nave de la Legión aparece en la distancia.', 'Una nave de la Legión aparece en la distancia.', 25549),
(126781, 'esMX', 'Nuestras tropas le darán un buen uso a estos suministros. Bien hecho, $gcampeón:campeona;.', '', 25549),
(126780, 'esMX', '¡$GCampeón:Campeona;! Hemos avistado los restos de una nave de la Horda. Asegura su cargamento antes de que lo haga la Legión.', '', 25549),
(126779, 'esMX', 'Has asestado un golpe contundente a la Legión, $n. La purificación ha comenzado. Aguardo tu regreso.', '', 25549),
(126778, 'esMX', '|TInterface\\Icons\\spell_fire_felrainoffire:20|t ¡Cuidado! ¡La nave de la Legión ha iniciado un |cFFFF0404|Hspell:235085|h[Bombardeo vil]|h|r!', '', 25549),
(126777, 'esMX', '¡Sí!', '¡Sí!', 25549),
(126776, 'esMX', '¡Feliz día de globos! ¿Alguien quiere dar un paseo en globo?', '¡Feliz día de globos! ¿Alguien quiere dar un paseo en globo?', 25549),
(126775, 'esMX', '', '¡He esperado mucho tiempo por este momento, Cazarian! ¡El látigo está en mi mano ahora!', 25549),
(126774, 'esMX', '', 'No tengo este látigo solo para asustar. Imparte la orden o da por terminado mi contrato y te mostraré las maravillas que puedo hacer con él...', 25549),
(126773, 'esMX', '', 'Deberían venir a hacerme compañía cuando se termine mi contrato. Mmm, las cosas que podría enseñarles...', 25549),
(126772, 'esMX', '', 'Mortales, ¿de verdad creen que pueden vencer a la Legión? Qué simpáticos. Son como un adorable grupo de ratitas que no logran ver al enorme depredador que los acecha.', 25549),
(126771, 'esMX', '', 'Odio estas naves. Son tan simplonas, no tienen suficientes cadenas.', 25549),
(126770, 'esMX', '', 'Si ves al Cazariano, avísame. Tengo un... asunto pendiente con él.', 25549),
(126769, 'esMX', '', 'Tehd me prometió que podríamos quemar este lugar hasta las cenizas.', 25549),
(126768, 'esMX', '', 'No entiendo cómo es posible que haga frío en una nave de la Legión Ardiente.', 25549),
(126767, 'esMX', '', 'Tengo frío. Mi vestimenta está pensada para mundos infernales donde siempre arde el fuego.', 25549),
(126766, 'esMX', '', 'Si le encuentras una capa a este, la quiero para mí.', 25549),
(126765, 'esMX', '', 'Aaah... ¿ya te das por vencido?', 25549),
(126764, 'esMX', '', 'Mmm. Creo que olvidé decirle la palabra clave.', 25549),
(126763, 'esMX', '', 'Ah, ese sí que fue malo.', 25549),
(126762, 'esMX', '', 'Parecería que estos demonios no pueden soportar siquiera un golpecito...', 25549),
(126761, 'esMX', '', 'Pf, ya no construyen a estos demonios como antes.', 25549),
(126760, 'esMX', '', 'Ay, se murió. Qué lástima. Podría haberme sido útil.', 25549),
(126759, 'esMX', '', '¿Esperas que me encargue de TODO yo sola?', 25549),
(126758, 'esMX', '', 'Mi amo me ordenó que te ayudara, así que intenta no morir o dirán que fue mi culpa.', 25549),
(126757, 'esMX', '¡Nos atacan!', '', 25549),
(126756, 'esMX', '¡Ayuda, $ct! ¡La Legión nos está haciendo retroceder!', '', 25549),
(126755, 'esMX', 'Envíame al bancal.', 'Envíame al bancal.', 25549),
(126754, 'esMX', '¡Urgh!', '', 25549),
(126753, 'esMX', 'Espera... ¡Algo anda  mal! No puedo... controlarlo...', '', 25549),
(126752, 'esMX', 'Las runas están activadas. Estabiliza el portal.', 'Las runas están activadas. Estabiliza el portal.', 25549),
(126751, 'esMX', '¿Has logrado descifrar estas runas? ¡No tenemos demasiado tiempo!', '', 25549),
(126750, 'esMX', 'Ya está hecho.', '', 25549),
(126749, 'esMX', '¡Las runas parecen funcionar! La energía vil se está debilitando...', '', 25549),
(126748, 'esMX', 'Bien, intentaré estabilizar el portal. Espero que sepas lo que haces, $c.', '', 25549),
(126747, 'esMX', 'Puedo mantenerlo abierto, pero necesitaré tu ayuda para estabilizarlo...', '', 25549),
(126746, 'esMX', '¡Listo! Las fallas están desapareciendo, pero el portal aún es demasiado volátil para atravesarlo.', '', 25549),
(126745, 'esMX', 'Llévame a la cima del Fuerte Torre Oscura.', 'Llévame a la cima del Fuerte Torre Oscura.', 25549),
(126744, 'esMX', 'Tenía que... ¡alejarme! Tenía que... ¡advertirte!', 'Tenía que... ¡alejarme! Tenía que... ¡advertirte!', 25549),
(126743, 'esMX', 'Debes detenerlos...', 'Debes detenerlos...', 25549),
(126742, 'esMX', 'Los Salones del valor resuenan con las canciones de aquellos a los que rescataste. ¡Magnífico trabajo!', '', 25549),
(126741, 'esMX', 'Los espíritus de los caídos gritan desesperados mientras los canes de la Legión drenan su esencia de vida. ¡Libera a los espíritus de este tormento y elimina a la escoria de la Legión!', '', 25549),
(126740, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(126739, 'esMX', 'Saludos, $GAlto señor:Alta señora;. Lord Grisillo te espera dentro.$b$bEstá supervisando los preparativos para la purificación de la gualdrapa.$b$bCuando estés $Glisto:lista;, te acompañaré dentro.', '', 25549),
(126738, 'esMX', '', 'Necesitamos una victi...ario... digo, un voluntario que se atreva a atravesar el portal y reducir las filas de los demonios del otro lado. Habla con Tehd. Él te puede prestar un demonio para empezar.', 25549),
(126737, 'esMX', 'Eso es todo por hoy. Gracias por volar... ¡y estudien para la próxima!', '', 25549),
(126736, 'esMX', '¡Buen intento! Pero la respuesta correcta es: "¡Una ilusión! ¿Qué ocultas?".', '', 25549),
(126735, 'esMX', 'Pregunta final para $n. ¿Cuál es el saludo tradicional que se usa en la ciudad de Suramar?', '', 25549),
(126734, 'esMX', 'Casi, casi. La respuesta que buscaba era "su piel".', '', 25549),
(126733, 'esMX', '$n. ¿Qué parte específica de la anatomía natonocturna se ha "realzado" debido al uso excesivo de maná?', '', 25549),
(126732, 'esMX', 'El consumo excesivo de maná afectó a los cuerpos de los natonocturnos.', '', 25549),
(126731, 'esMX', 'La sustancia que consumen es, en efecto, maná.', '', 25549),
(126730, 'esMX', '$n, ¿puedes decirme qué sustancia alucinógena usan los natonocturnos para relajarse?', '', 25549),
(126729, 'esMX', 'Entre otras cosas, los natonocturnos son conocidos por ser bastante desagradables.', '', 25549),
(126728, 'esMX', 'Debo admitir que la magia de los Vilnato es algo... llamativa. Es una pena que abusen de su potencial. Tuvieron el final que se merecían.', '', 25549),
(126727, 'esMX', 'Suramar, como todos sabemos, es el hogar de los elfos natonocturnos.', '', 25549),
(126726, 'esMX', 'Qué grupo más parlanchín. ¡Comencemos con el recorrido!', '', 25549),
(126725, 'esMX', 'Ya veo. Y la lista termina con $n. Supongo que eres tú, ¿correcto?', '', 25549),
(126724, 'esMX', 'Muy bien. ¿Se encuentra $n entre nosotros el día de hoy?', '', 25549),
(126723, 'esMX', 'Por favor, solo digan "aquí".', '', 25549),
(126722, 'esMX', '¿$n? ¿Está $n aquí?', '', 25549),
(126721, 'esMX', 'Pero primero, voy a tomar asistencia.', '', 25549),
(126720, 'esMX', 'Hoy vamos a hacer un recorrido escénico en globo sobre la ciudad antigua de Suramar.', '', 25549),
(126719, 'esMX', '¡Saludos! Suban a la barquilla... y prepárense para el paseo en globo más educativo de sus vidas.', '', 25549),
(126718, 'esMX', '', 'Muy bien, ¡se acabó el paseo en globo! ¡Estuvo divertido!', 25549),
(126717, 'esMX', '', 'Ya se acabó mi turno. ¡Que siga alguien más!', 25549),
(126716, 'esMX', '', '¡Y por descarte, me casaría con $n! Puedo vivir con eso.', 25549),
(126715, 'esMX', '', 'Mmm... Mataría a $n. Por razones obvias.', 25549),
(126714, 'esMX', '', '$n, tienes un rostro agradable y parece que eres $Gel único:la única; de todos los presentes que se cepilla los dientes. Te besaría.', 25549),
(126713, 'esMX', '', '¡Yo primero! Veamos...', 25549),
(126712, 'esMX', '', 'Es fácil. Solo hay que escoger una persona que besarías, una con la que te casarías y una a la que asesinarías.', 25549),
(126711, 'esMX', '', '¡Eh, eh, yo sé uno! Se llama besar, casarse o asesinar.', 25549),
(126710, 'esMX', '', 'Así que... ¿alguno de ustedes conoce algún juego para fiestas en globo?', 25549),
(126709, 'esMX', '', 'Lo siento, no tengo mucha experiencia como guía.', 25549),
(126708, 'esMX', '', '¿Ven todo eso de ahí abajo? Eso... emm.. eso es Stormheim.', 25549),
(126707, 'esMX', '', '¡Bienvenidos a bordo! Hoy haremos un recorrido por Stormheim.', 25549),
(126706, 'esMX', 'Ese fue el paseo en globo más catártico de mi vida. Incluso fue algo divertido. Gracias, a todos.', '', 25549),
(126705, 'esMX', 'No me olvidé de ti, $n. Cuéntanos un secreto. No te juzgaremos. Este es un globo seguro.', '', 25549),
(126704, 'esMX', '¿Qué hay de ti, $n? ¿Tienes algún secreto que sientas que te carcome el alma?', '', 25549),
(126703, 'esMX', '$n, inténtalo. Cuéntanos algo que nunca le hayas contado a nadie. Vamos.', '', 25549),
(126702, 'esMX', 'Ahora conocen mi secreto. ¿Qué hay de ustedes?', '', 25549),
(126701, 'esMX', 'Qué bien me siento luego de ese descargo. Nunca se lo había contado a nadie.', '', 25549),
(126700, 'esMX', 'Vaya.', '', 25549),
(126699, 'esMX', '... Bufff.', '', 25549),
(126698, 'esMX', '¿Esto te parece bien, padre? ¿Eh? ¡¡¿ESTÁS ORGULLOSO DE MÍ, PAPÁ?!!', '', 25549),
(126697, 'esMX', 'ODIO los globos. Los llevo odiando toda la vida. ¡Todo lo que quería era ser un chamán, pero no! Parece que "llevamos en la sangre lo de viajar en globo".', '', 25549),
(126696, 'esMX', 'Tengo una confesión que hacerles a ustedes tres.', '', 25549),
(126695, 'esMX', '¿Saben qué? Se acabó. ME CANSÉ.', '', 25549),
(126694, 'esMX', 'Debajo de nosotros, a la derecha, se encuentra la finca de Pang. Estén muy atentos a...', '', 25549),
(126693, 'esMX', '', 'Sí. ¡Sí! ¡SÍ! Apuesto a que no es tan divertido estar del otro lado, ¿verdad? ¡Escoria de la Legión!', 25549),
(126692, 'esMX', '<Suspiro>...', '', 25549),
(126691, 'esMX', 'Este es el paseo en globo hacia el Alcor. Por favor, mantengan las manos y todo lo demás dentro de la barquilla todo el tiempo.', '', 25549),
(126690, 'esMX', '¿Tenemos MÁS pasajeros? Bien, suban... supongo.', '', 25549),
(126689, 'esMX', 'Dejaré que hablen entre ustedes tres. Tengo que asegurarme de no estrellar el globo en Dalaran.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126688, 'esMX', '¿O qué tal tú, $n? ¿Qué tipo de aventuras de exploración tienes para contar?', '', 25549),
(126687, 'esMX', '¿Y tú, $n?', '', 25549),
(126686, 'esMX', '¿Qué hay de ti, $n? ¿A qué tierras exóticas has viajado?', '', 25549),
(126685, 'esMX', '', '$GSeñor:Señora; abisal, uno de nuestros brujos ha abierto un portal a un transportador de la Legión repleto de demonios. ¡Te sugiero que les muestres a estas alimañas lo que significa ser la marioneta de un poder superior!', 25549),
(126684, 'esMX', 'Los magos del Tirisgarde necesitan ayuda para investigar a los Vilnato que se asentaron en el Bancal sollozante. Esta varita te servirá para anular sus protecciones mágicas.', '', 25549),
(126683, 'esMX', 'Pido perdón por parlotear tanto. ¡No hay duda de que las historias de tus propias aventuras son mucho más emocionantes!', '', 25549),
(126682, 'esMX', 'Después de tantos viajes que hice, todavía recuerdo ese día con mucha claridad.', '', 25549),
(126681, 'esMX', 'Justo después de ese risco, en la Cuenca de Sholazar, conocí a una tribu de wolvar y otra de oráculos múrloc. ¡Qué criaturas más extrañas!', '', 25549),
(126680, 'esMX', 'Ahh... Pero qué lindos recuerdos tengo del tiempo que pasé en Rasganorte.', '', 25549),
(126679, 'esMX', 'A pesar de todos mis viajes, me entristece decir que nunca pude pasar mucho tiempo aquí. No podría decirles el porqué.', '', 25549),
(126678, 'esMX', 'Debajo puede verse el Bosque Canto de Cristal.', '', 25549),
(126677, 'esMX', 'Bienvenidos a bordo. Por favor, siéntense y disfruten del vuelo.', '', 25549),
(126676, 'esMX', 'Agh... parece que nos acercaremos mucho. ¡Todos saluden al Tótem del Trueno!', '', 25549),
(126675, 'esMX', 'O incluso tú, $n. ¡Que alguien me anime!', '', 25549),
(126674, 'esMX', '¿Y qué tal tú, $n?', '', 25549),
(126673, 'esMX', '$n, ¿tienes un poco?', '', 25549),
(126672, 'esMX', 'Ni siquiera disparar contra alimañas desde un globo aerostático me animaría.', '', 25549),
(126671, 'esMX', 'Es que en este último tiempo... Agh, no sé. Como que no me siento bien. Cazar ya no me da la alegría que solía darme.', '', 25549),
(126670, 'esMX', 'Le compré este globo a un goblin pequeñín. ¡Dijo que era un buen pedestal para disparar a los alces!', '', 25549),
(126669, 'esMX', 'Bienvenidos, mis amigos, al recorrido en globo por Altamontaña de Nesingwary.', '', 25549),
(126668, 'esMX', '¿Que hiciste QUÉ? ¡¡¡¡Rungle, lo echaste a perder todo otra vez!!!!', '', 25549),
(126667, 'esMX', 'Muy bien, $Gjefe:jefa;. Puse los fuegos artificiales en la barbacoa, justo como lo pediste.', '', 25549),
(126666, 'esMX', 'El costo es de 28,542 monedas de oro cada uno. A menos que, desde luego, prefieran que Rungle les rompa las piernas.', '', 25549),
(126665, 'esMX', '¡El truco es que no revelarle el precio al cliente sino hasta que ya está a bordo del globo contigo!', '', 25549),
(126664, 'esMX', 'Se estarán preguntando cómo puedo manejar un globo de tanta clase y, además, sacar ganancia. ¡Pues bien, ya les digo!', '', 25549),
(126663, 'esMX', 'Claro, jefe.', '', 25549),
(126662, 'esMX', 'Rungle, ¿por qué no calientas la barbacoa y preparas los fuegos artificiales?', '', 25549),
(126661, 'esMX', '¿Una toalla caliente? ¡Sólo lo mejor para nuestros clientes!', '', 25549),
(126660, 'esMX', 'Esa es la Academia Nar''thalas. Una escuela para magos en los tiempos antiguos, según he oído.', '', 25549),
(126659, 'esMX', '¿Alguien quiere caviar? ¡Tenemos solo lo mejor!', '', 25549),
(126658, 'esMX', 'Hoy volaremos sobre Azsuna, la joya de las Islas Quebradas.', '', 25549),
(126657, 'esMX', '¿Qué tal unas bebidas gratis? ¡Aquí tienen!', '', 25549),
(126656, 'esMX', '¡Tenemos el globo más genial de todo Azeroth! ¡Pregúntenle a cualquiera! ¡Les dirá que es cierto!', '', 25549),
(126655, 'esMX', '¡Suban, noveles entusiastas! ¿Alguien quiere una calcomanía de un globo? Aquí tienen.', '', 25549),
(126654, 'esMX', '', 'No hay tiempo como el hogar, no hay tiempo como el hogar, no hay tiempo como el hogar...', 25549),
(126653, 'esMX', '', '¿O acaso viajamos al futuro? No lo sé. ¡De cualquier modo, esto es espantoso! ¡Quiero volver!', 25549),
(126652, 'esMX', '', '¡No puedo creerlo! ¡Viajamos hacia atrás en el tiempo!', 25549),
(126651, 'esMX', '', '¿Estamos en Nagrand? ¡Estamos en Nagrand!', 25549),
(126650, 'esMX', '', 'No creo que sigamos en Nagrand.', 25549),
(126649, 'esMX', '', 'Oh oh...', 25549),
(126648, 'esMX', '', '¡Tengo una hermosura equipada con un acelerador cronal que fue una ganga! El tiempo pasará volando, ¡literalmente! ¿Qué podría salir mal?', 25549),
(126647, 'esMX', '', 'Vaya, están de suerte. Este no va a ser uno de esos viajes normales, soporíferos y ultralentos.', 25549),
(126646, 'esMX', '', '¡Bienvenidos a bordo!', 25549),
(126645, 'esMX', 'Esperemos que el Anillo de la Tierra encuentra la forma de recuperar el balance en esta tierra herida una vez que termine la guerra contra la Legión.', '', 25549),
(126644, 'esMX', 'Héroe, los chamanes del Anillo de la Tierra están luchando por contrarrestar las intensas maldiciones viles que se esparcen por esta tierra. Necesitan que los ayudes en la batalla mientras completan sus rituales de purificación.', '', 25549),
(126643, 'esMX', 'Bien hecho, Clarividente. Los chamanes se encargarán de la situación a partir de ahora.', '', 25549),
(126641, 'esMX', '¡Clarividente! Los elementales de fuego vil puro queman la tierra con sus maldiciones. Purifica a los que se enfrentan contra esas criaturas y purga la magia de estos monstruos.', '', 25549),
(126640, 'esMX', '¡Rápido, al extremo norte de la muralla! ¡Hay una presencia oscura en la cima de la fortaleza!', '', 25549),
(126639, 'esMX', '¿Un fuerte demoníaco en Torre Oscura? ¡Eliminen a los demonios de inmediato!', '', 25549),
(126638, 'esMX', '¡ME LO MEREZZZCO!', '', 25549),
(126637, 'esMX', 'La Guardia Nocturna sabe una que otra cosa acerca de rastrear. En el Bosque del Ocaso hay criaturas ocultas en cada rincón y grieta oscura.$b$bA veces logras atisbar esos ojitos entreabiertos y brillantes que te observan desde los arbustos.$b$b<El vigía se esfuerza para no estremecerse.>$b$bDe hecho, el otro día sentí que una criatura extraña me acechaba en el bosque, que me observaba oculta en las sombras.', '', 25549),
(126636, 'esMX', 'Muy bien. Ahora noz zentaremoz en zilenzio durante la ziguiente hora.', '', 25549),
(126635, 'esMX', 'Famos a darr un lindo paseo en globo y lo famos a disfrutarr. ¿Está clarro?', '', 25549),
(126634, 'esMX', 'Eztaz zon laz reglaz. Obedezcan o ze arrepentirán.', '', 25549),
(126633, 'esMX', '¡NADA DE TONTERRÍAS!', '', 25549),
(126632, 'esMX', 'Eztá prohibido charlar, zaltar o zarandear la barquilla.', '', 25549),
(126631, 'esMX', 'Tenemos un globo marrafilloso.', '', 25549),
(126630, 'esMX', 'Ahorra prréstenme atensión a mí.', '', 25549),
(126629, 'esMX', 'Debo recuperar mi fuerza. ¡Ten cuidado, $Gcampeón:campeona;!', '', 25549),
(126628, 'esMX', '¡No caeremos!', '', 25549),
(126627, 'esMX', 'En la Luz, somos uno.', '', 25549),
(126626, 'esMX', '¡Siente el poder de la Luz!', '', 25549),
(126625, 'esMX', 'Los Tejesueños nos han otorgado a sus hipogrifos para transportarlos hasta el navío de la Legión. Eliminen al comandante que lidera el asalto y el resto de estos demonios cobardes emprenderán la retirada. ¡Buena suerte, campeones!', '', 25549),
(126624, 'esMX', '¡Si queremos asegurar esta torre, debemos derribar al líder que se guarece dentro! ¡Tenemos que apoderarnos de ella!', '', 25549),
(126623, 'esMX', 'La barrera ha caído, pero el mal de la Legión aún nos acecha. Si logramos asegurar la cumbre de la torre, los Tejesueños nos indicarán la forma de llegar hasta el navío de los demonios.', '', 25549),
(126622, 'esMX', 'Percibimos que traes malas noticias de la Costa Quebrada. Te esperamos en la Ciudadela Violeta.', '', 25549),
(126621, 'esMX', '', 'He recuperado a Arikara. ¿Encontraste la Piedra de la muerte?', 25549),
(126620, 'esMX', '¡Intentaré estabilizarlo! ¡No dejen que los demonios avancen hasta que pueda detenerlos!', '', 25549),
(126619, 'esMX', '¡Estúpida! ¡Su portal se ha sobrecargado y está abriendo fallas al Vacío Abisal!', '', 25549),
(126618, 'esMX', 'Un muro de energía vil nos impide entrar en la Torre de la celadora. Adelanta a tu equipo y destruye las máquinas de la Legión que alimentan la barrera. Nosotros nos encargaremos de mantener esta posición mientras atacas.', '', 25549),
(126617, 'esMX', '¡Caerán, demonios!', '', 25549),
(126616, 'esMX', '¡Expulsemos a la Legión de nuestro mundo!', '', 25549),
(126615, 'esMX', '¡Defensores, muévanse! ¡Es hora de atacar a la Legión!', '', 25549),
(126614, 'esMX', 'Debemos purificar estos bosques antiguos de la presencia de la Legión. ¡Den la orden, héroes, y comenzaremos la batalla para salvar a Val''sharah!', '', 25549),
(126613, 'esMX', '¡Que Odyn te bendiga, $Gforastero:forastera;!', '', 25549),
(126612, 'esMX', '¡Ya no seré comida para los canes!', '', 25549),
(126611, 'esMX', '¡Gracias, $Gforastero:forastera;! ¡Ojalá nos volvamos a ver en los Salones del valor!', '', 25549),
(126610, 'esMX', '¡Libertad, al fin!', '', 25549),
(126609, 'esMX', 'La muerte... nos llega a todos.', '', 25549),
(126608, 'esMX', 'Libérame, $Gforastero:forastera;. ¡Preferiría pasar una eternidad en Helheim antes que sufrir el destino que me espera en este lugar!', '', 25549),
(126607, 'esMX', '¡Los canes nos devorarán a todos!', '', 25549),
(126606, 'esMX', '¡Libérame de este tormento!', '', 25549),
(126602, 'esMX', 'Ah... Creo que no se suponía que fuera tan pequeño.', '', 25549),
(126601, 'esMX', 'Hola. Te trajimos algunos juguetitos que tal vez podrían servirte. Suerte.', '', 25549),
(126600, 'esMX', 'Aquí tienes el agua bendita, Grisillo.', 'Aquí tienes el agua bendita, Grisillo.', 25549),
(126599, 'esMX', '¡%s usa dinomojo en ti, lo que te otorga una Adaptación!', '¡%s usa dinomojo en ti, lo que te otorga una Adaptación!', 25549),
(126598, 'esMX', 'Mmm... Laurence... a ver...\n\nAh, sí, estuvo por aquí hace unos días. Buscaba un bastón con unas propiedades bastante peculiares. Algo extraño a decir verdad, porque era un bastón del tipo que normalmente consigo para uno de mis clientes brujos.\n\nMe tomó algunos días conseguirlo, pero encontré uno e hice que lo entregaran en el salón Juego de Manos, como ella lo solicitó.', '', 25549),
(126597, 'esMX', '¿Qué puedo hacer por ti?', '', 25549),
(126596, 'esMX', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_03.BLP:32|t ¡Mephistroth usa |cFFFF0000|Hspell:233206|h[Desvanecimiento sombrío]|h|r para ocultarse!', '', 25549),
(126595, 'esMX', '¡No puedes esconderte, Mephistroth!', '', 25549),
(126594, 'esMX', 'Los esfuerzos de la Legión fracasarán.', '', 25549),
(126593, 'esMX', 'Que comience el asalto.', 'Que comience el asalto.', 25549),
(126592, 'esMX', '¡Debemos detener al enemigo, cueste lo que cueste!', '', 25549),
(126591, 'esMX', '', 'Ya oyeron las palabras de $ct, hijos míos. ¡Visiten las otras órdenes y aseguren su colaboración! Que los elementos guíen su camino.', 25549),
(126590, 'esMX', '%s empieza a canalizar |cFFFF0404|Hspell:234728|h[Aniquilación arcana]|h|r!', '', 25549),
(126589, 'esMX', 'Debemos informar al resto de las órdenes de clase de las novedades. Nos dirigiremos hacia la Costa Quebrada.', 'Debemos informar al resto de las órdenes de clase de las novedades. Nos dirigiremos hacia la Costa Quebrada.', 25549),
(126588, 'esMX', 'Abriré un portal hasta la posición de la arcanista Ryanna. Un momento.', '', 25549),
(126587, 'esMX', '', 'Que los espíritus te guíen, $ct.', 25549),
(126586, 'esMX', 'Sumo hechicero, necesito que convenzas al resto de las órdenes de clase de que se unan a nosotros para luchar contra la Legión.', 'Suma hechicera, necesito que reúnas al resto de las órdenes de clase para que se unan a nosotros en la lucha contra la Legión.', 25549),
(126585, 'esMX', '¡Saludos! Este lugar es perfecto para la meditación arcana, ¿no crees?', '', 25549),
(126584, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t ¡El Avatar comienza a lanzar |cFFFF0404|Hspell:234724|h[Aniquilación]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t ¡El Avatar comienza a lanzar |cFFFF0404|Hspell:234724|h[Aniquilación]|h|r!', 25549),
(126583, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FEL_ELEMENTALDEVASTATION:20|t ¡El Guardián corrupto comienza a lanzar |cFFFF0404|Hspell:233856|h[Protocolo de purificación]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FEL_ELEMENTALDEVASTATION:20|t ¡El Guardián corrupto comienza a lanzar |cFFFF0404|Hspell:233856|h[Protocolo de purificación]|h|r!', 25549),
(126582, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t ¡El Avatar comienza a lanzar |cFFFF0404|Hspell:239132|h[Ruptura de realidades]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t ¡El Avatar comienza a lanzar |cFFFF0404|Hspell:239132|h[Ruptura de realidades]|h|r!', 25549),
(126581, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFIRENOVA:20|t ¡El Avatar te lanza |cFFFF0404|Hspell:234059|h[Caos desatado]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFIRENOVA:20|t ¡El Avatar te lanza |cFFFF0404|Hspell:234059|h[Caos desatado]|h|r!', 25549),
(126580, 'esMX', '¡Grongo machacar!', '', 25549),
(126579, 'esMX', '', '¿Quieres un poco de Bum? ¡Pues aquí lo tienes, idiota!', 25549),
(126578, 'esMX', '¡Fuera de mi narco, basura de la Alianza!', '', 25549),
(126577, 'esMX', '¡Fuera de mi barco, basura de la Horda!', '', 25549),
(126576, 'esMX', '', '¡Ack!', 25549),
(126575, 'esMX', '¡Aléjate a menos que quieras unos fuegos artificiales en la cara!', '', 25549),
(126574, 'esMX', 'Fue una buena pelea, $n. Pero todavía queda mucho por hacer antes de cantar victoria.', '', 25549),
(126573, 'esMX', 'Se te concedió un barco gratis para usarlo en la superficie del agua por hoy. ¡Navega con cuidado!', 'Se te concedió un barco gratis para usarlo en la superficie del agua por hoy. ¡Navega con cuidado!', 25549),
(126572, 'esMX', '<Suspiro>... Tenía ganas de jugar al vóleibol, también...', '', 25549),
(126571, 'esMX', 'Toda su basura se acumula en este rincón de la laguna. No podemos tolerar este agravio a la naturaleza.', '', 25549),
(126570, 'esMX', 'El festejo alocado de las demás razas tiene un efecto drástico en el ambiente de esta tierra.', '', 25549),
(126569, 'esMX', 'Mmm... Apuesto a que esos piratas de allá tienen algo de cerveza...', '', 25549),
(126568, 'esMX', 'Lo siento.', '', 25549),
(126567, 'esMX', '¡Venimos desde tan lejos para celebrar este día de bote y a ti se te olvida la maldita cerveza!', '', 25549),
(126566, 'esMX', '¡AGH! ¡No puedo creerlo!', '', 25549),
(126565, 'esMX', '', '¡Oigan, marineros! ¿Tienen ganas de festejar?', 25549),
(126564, 'esMX', '<Jadeo> No puedo creer que recurras a los insultos. Y justo en un DÍA DE BOTE.', '', 25549),
(126563, 'esMX', 'Oye, tranquilízate, ¿quieres? ¡Robé sus bombas solo porque tú y tu escuadrón de chiquilines robaron las nuestras primero!', '', 25549),
(126562, 'esMX', '¡Siempre pasa lo mismo! ¡Me distraigo un momento y tus matones nos roban los explosivos!', '', 25549),
(126561, 'esMX', 'Diabólico. Esos diabillos atrevidillos pusieron en peligro grandes mejorillas.', '', 25549),
(126560, 'esMX', 'La Legión abrió un portal del que está emanando un enjambre de diablillos asquerosos. ¡$GCampeón:Campeona;, debes erradicar a estos pequeños demonios!', '', 25549),
(126559, 'esMX', 'La muerte de estas criaturas asquerosas avivará las llamas de la ira de la Legión. Vayamos rápido al Fuerte Torre Oscura. ¡Debemos atacar!', '', 25549),
(126558, 'esMX', 'Lamentablemente, unos gigantes de mar llegaron para llevarse los bienes. Mata a los gigantes y busca los suministros perdidos entre los restos.', '', 25549),
(126557, 'esMX', 'Perdimos suministros valiosos en el océano durante nuestro primer asalto. Serían muy útiles para nuestra batalla contra la Legión.', '', 25549),
(126556, 'esMX', 'La Legión Ardiente es una plaga que profana la tierra con su presencia. ¡Debemos erradicar a los demonios antes de que sus fuerzas sigan propagándose!', '', 25549),
(126555, 'esMX', 'Primero invaden nuestras tierras, y ahora sus demonios oscurecen los cielos.', '', 25549),
(126554, 'esMX', '¡Ha sido un honor pelear a tu lado, $GSeñor:Señora; de la batalla $n! Regresaré al Punto de Liberación. ¡Te veré ahí!', '', 25549),
(126553, 'esMX', 'Peleas con honor, $GSeñor:Señora; de la batalla $n. Me presentaré en el Punto de Liberación. Nos vemos allí.', '', 25549),
(126552, 'esMX', '¡Caballeros! ¡$GEl:La; $ct nos necesita! ¡A volar!', '', 25549),
(126551, 'esMX', 'Por supuesto, $ct. Partiremos de inmediato.', '', 25549),
(126550, 'esMX', 'Reúne al resto de las órdenes de clase. Nos dirigiremos a la Costa Quebrada.', 'Reúne al resto de las órdenes de clase. Nos dirigiremos a la Costa Quebrada.', 25549),
(126549, 'esMX', '¿Cómo puedo servirte, $ct?', '', 25549),
(126548, 'esMX', 'Los plumíferos no tienen lealtad. ¡Aunque Galleta me haya abandonado, todo pirata exitoso necesita una mascota! ¡Mico es mi nuevo compañero y ha demostrado ser muy útil!$b$bNo necesito a un pájaro, Mico es un ayudante mucho más útil.', '', 25549),
(126547, 'esMX', '¿Y ese hozen?', '¿Y ese hozen?', 25549),
(126546, 'esMX', 'Ah, $n. ¡Espero que haya una gran explosión!', '', 25549),
(126545, 'esMX', 'Helya... Te he fallado...', '', 25549),
(126544, 'esMX', '¡Vengaré la muerte de mi ama! ¡Ningún asqueroso forastero controlará a los kvaldir mientras yo esté vivo!', '', 25549),
(126543, 'esMX', '¡Envíame al puesto de avanzada de inmediato! [Cola para escenario]', '¡Envíame al puesto de avanzada de inmediato! [Cola para escenario]', 25549),
(126542, 'esMX', 'Estos demonios pagarán por lo que han hecho. ¡Lo juro!', '', 25549),
(126541, 'esMX', '¡Galleta! ¡Creí que eras mi amigo! ¡Me rompes el corazón!', '', 25549),
(126540, 'esMX', '', 'Gracias, $p. Has conseguido tiempo valioso para acabar con esta amenaza.', 25549),
(126539, 'esMX', '', '¿Kruul ha regresado? Debemos preparar un ataque a la guarida del demonio. Karlain, encárgate de proveer todos los suministros posibles a los Illidari.', 25549),
(126537, 'esMX', '¡Bah! ¿Estos vrykul creen que pueden robar nuestra pólvora? ¡No saben lo que hacen!', '', 25549),
(126536, 'esMX', '¡¿Qué?! ¿Las harpías se robaron mi pólvora? ¡Debo reunir a mi equipo y dirigirme hacia Altamontaña!', '', 25549),
(126535, 'esMX', 'En la otra esquina, un enano con su leal compañero que NUNCA la haría daño a su amo. ¡Jamás!', '', 25549),
(126534, 'esMX', '¡Hiciste un gran trabajo con esos gigantes! Los suministros que recolectaste serán una bendición para la guerra.', '', 25549),
(126533, 'esMX', 'Se han restablecido los tiempos de reutilización y los perjuicios.', '', 25549),
(126532, 'esMX', '', 'En la otra esquina, un enano con su leal compañero que NUNCA la haría daño a su amo. ¡Jamás!', 25549),
(126531, 'esMX', 'No está por ninguna parte. ¡Se la deben haber llevado una vez más!', '', 25549),
(126530, 'esMX', '', '¡Silencio, Crixa!', 25549),
(126529, 'esMX', '', 'Doloria, te buscan.', 25549),
(126528, 'esMX', '', 'Mmm, ¿no es esa de la máscara? Ah, un momento, claro. No, no la he visto.', 25549),
(126527, 'esMX', 'Estás más ciego que un pirata con dos parches.', '', 25549),
(126526, 'esMX', '', '¡Excelente! No se me ocurre nadie mejor que tú para esta tarea. Te informaremos de todas las amenazas conocidas.', 25549),
(126525, 'esMX', 'Normalmente, dejaría que la naturaleza siga su curso... sin embargo, preferiría no tener que enfrentar a un ejército de krakens y a la Legión Ardiente al mismo tiempo.', '', 25549),
(126524, 'esMX', 'Sus celos y sus kvaldir nos arrebataron muchas almas dignas de unirse a nuestro ejército. Debemos liberarlas para que al menos puedan ocupar el lugar que les corresponde aquí en el cielo.', '', 25549),
(126523, 'esMX', 'Tenemos un problema con unos huevos excedidos de tamaño... Bueno, técnicamente el problema no son los huevos, sino los krakens que nacen de ellos.', '', 25549),
(126522, 'esMX', '¡Guerreros de la Alianza! ¡Tenemos una tarea que cumplir!', '', 25549),
(126521, 'esMX', 'Saludos $GSeñor:Señora; de la batalla. Tu llegada es oportuna. Estos tiempos difíciles requieren de líderes como tú.', '', 25549),
(126520, 'esMX', 'Lord Darius, necesito que convoques a las demás órdenes de clase para formar una coalición contra la Legión.', 'Lord Darius, necesito que convoques a las demás órdenes de clase para formar una coalición contra la Legión.', 25549),
(126519, 'esMX', 'Saludos $GSeñor:Señora; de la batalla. Tu llegada es oportuna. Estos tiempos difíciles requieren de líderes como tú.', '', 25549),
(126514, 'esMX', '¡Ajá! ¡Una pista! Ah, no, solo un poco de polvo.', '', 25549),
(126513, 'esMX', 'Ah, tal vez esté aquí atrás...', '', 25549),
(126512, 'esMX', 'Disculpe, amable señor, ¿ha visto usted a mi Doloria?', '', 25549),
(126511, 'esMX', '¡Guerreros de la Horda, muévanse!', '', 25549),
(126510, 'esMX', '¡Estás a salvo, amor mío! Espera... algo no está bien.', '', 25549),
(126509, 'esMX', 'Eitrigg, necesito que convoques a las demás órdenes de clase para formar una coalición contra la Legión.', 'Eitrigg, necesito que convoques a las demás órdenes de clase para formar una coalición contra la Legión.', 25549),
(126507, 'esMX', '', 'Durante nuestro encarcelamiento, el Kirin Tor encerró el corazón de Kruul en las bóvedas de Dalaran para impedir que cayera en manos de la Legión.', 25549),
(126506, 'esMX', '¡Ven, $Gescudero:escudera;! Nos reuniremos en las montañas más elevadas.', '', 25549),
(126505, 'esMX', '¡No temas, querida mía, nos encargaremos de esos bandidos y te devolveremos la libertad!', '', 25549),
(126504, 'esMX', '', '¿Maximillian? ¿Cómo has hecho para encontrarme?', 25549),
(126503, 'esMX', '¡Doloria, mi amor! Por fin te he encontrado! ¿Estás bien?', '', 25549),
(126502, 'esMX', '¡Han traspasado las bóvedas!', '¡Han traspasado las bóvedas!', 25549),
(126501, 'esMX', '¡Héroes, a mí! ¡Protéjanme con la Égida mientras expulso a este señor del terror de las sombras!', '', 25549),
(126499, 'esMX', '¡La bestia que puso esos huevos está en la caverna! ¡Revisa el área superior!', '', 25549),
(126498, 'esMX', 'Has debilitado un poco sus fuerzas. Ahora, concéntrate en los huevos.', '', 25549),
(126497, 'esMX', '¡Llamaste su atención! ¡Aquí viene!', '', 25549),
(126496, 'esMX', '', '¿Quieres saber qué buscaba la Legión? ¡Que rebajara mis precios! ¡Los resguardos que usa la Legión no son nada baratos, cariño!', 25549),
(126495, 'esMX', '', '¡Ay, cuánta calamidad! ¡Cuánta destrucción! ¡Cuánta falta de confianza del cliente! $B$B<Glutonia hace una pausa para asegurarse de que la estás mirando.>$B$B¡Ah, tal vez el agradable aroma de diez monedas de oro me refresque la memoria!$B$BSin marcar, por favor.', 25549),
(126494, 'esMX', 'Vi al demonio escabullirse en un portal en medio del caos. ¡Era del tamaño de dos o casi tres tauren!', '', 25549),
(126493, 'esMX', 'Jamás... me... rendiré...', 'Jamás... me... rendiré...', 25549),
(126492, 'esMX', 'Déjame ir... te lo ruego. Mi familia me necesita.', 'Déjame ir... te lo ruego. Mi familia me necesita.', 25549),
(126491, 'esMX', '¿Por qué? ¿Por qué me haces esto?', '¿Por qué? ¿Por qué me haces esto?', 25549),
(126490, 'esMX', 'No sé nada...', 'No sé nada...', 25549),
(126489, 'esMX', '¡Sal... de... mi...cabeza!', '¡Sal... de... mi...cabeza!', 25549),
(126488, 'esMX', 'Mi... mente... sal de mi... mente.', 'Mi... mente... sal de mi... mente.', 25549),
(126487, 'esMX', '¡Haz que se detenga! ¡Por favor, haz que se detenga!', '¡Haz que se detenga! ¡Por favor, haz que se detenga!', 25549),
(126486, 'esMX', '¡Abre la trampa para que pueda disparar, Oso!', '', 25549),
(126485, 'esMX', 'Cada alma que rescatamos de la forja vil debilita la causa de nuestro enemigo. Buen trabajo.', '', 25549),
(126484, 'esMX', 'Los demonios están trayendo más refugiados desafortunados desde Suramar. Ayuda a los pícaros del Consejo de las sombras a liberar a los prisioneros antes de que se conviertan en alimento para la energía vil.', '', 25549),
(126483, 'esMX', 'Nuestro enemigo se debilita con cada alma que liberamos de la forja vil. Bien hecho.', '', 25549),
(126482, 'esMX', 'Hoja de las sombras, los demonios están trayendo más refugiados desafortunados desde Suramar. Tú y tus pícaros deben liberarlos antes de que se conviertan en alimento para la energía vil.', '', 25549),
(126481, 'esMX', 'Tayen Lomoacero', 'Tayen Lomoacero', 25549),
(126480, 'esMX', 'Melhen Iraluz', 'Melhen Iraluz', 25549),
(126479, 'esMX', 'Nalenn Atracacorazones', 'Nalenn Atracacorazones', 25549),
(126478, 'esMX', 'Guldek Petroescudo', 'Guldek Petroescudo', 25549),
(126477, 'esMX', 'Alawa Sabioestribo', 'Alawa Sabioestribo', 25549),
(126476, 'esMX', 'Rasean Infraluz', 'Rasean Infraluz', 25549),
(126475, 'esMX', '¡Si destruyes suficientes huevos, la monstruosidad que los puso vendrá en busca de venganza!', '', 25549),
(126474, 'esMX', 'Este es el lugar. ¡Mata a las abominaciones y destruye todos los huevos que encuentres!', '', 25549),
(126473, 'esMX', 'Los paladines de la Mano de plata están realizando un ritual sagrado en el Paso Fuego Vil, pero la Legión sigue entrometiéndose. Acaba con el líder de los demonios para que podamos santificar este lugar.', '', 25549),
(126472, 'esMX', 'Buen trabajo. Le has dado a nuestras fuerzas el tiempo que necesitaban para completar nuestra tarea.', '', 25549),
(126471, 'esMX', 'Gracias a tu ayuda, podremos completar nuestro trabajo y honrar el sacrificio de Tirion.', '', 25549),
(126470, 'esMX', 'Nuestra intención era consagrar la zona donde Tirion cayó, pero la Legión nos obligó a retroceder. Necesitamos tu ayuda, $GAlto señor:Alta señora;.', '', 25549),
(126469, 'esMX', 'Muchos no logran resistir la atracción del llamado del poder. Estos brujos eran una amenaza siniestra y no tuvimos más remedio que acabar con ellos.', '', 25549),
(126468, 'esMX', 'Hemos detectado una reunión de brujos poderosos de la Legión en Paso Fuegovil. Debemos detenerlos y asesinar a su maestra fanática antes de que se vuelvan demasiado fuertes.', '', 25549),
(126467, 'esMX', 'Por lo menos esta vez no hay láseres oculares gigantes, ¿no?', '', 25549),
(126466, 'esMX', '¡Buen trabajo, $Ghéroe:heroína;! Nuestros druidas se encargarán del resto.', '', 25549),
(126465, 'esMX', 'Me apena ver esta tierra antigua invadida por unas criaturas tan pestilentes. ¡Detenlos antes de que se propaguen!', '', 25549),
(126464, 'esMX', 'Esta vez vendrán muchos. La máquina rebosa de Luz.', '', 25549),
(126463, 'esMX', '', '¡Juro que esta será la última vez que acompaño a un Barbabronce en sus aventuras!', 25549),
(126462, 'esMX', '¡Aún no hemos terminado!', '', 25549),
(126461, 'esMX', 'Podemos regresar cuando tú digas, $GSumo sacerdote:Suma sacerdotisa;.', '', 25549),
(126460, 'esMX', 'Estoy listo para regresar a Dalaran.', 'Estoy lista para regresar a Dalaran.', 25549),
(126459, 'esMX', '¿Estás $Glisto:lista; para partir, $GSumo sacerdote:Suma sacerdotisa;? Avísame, y enviaré el submarino de vuelta a Dalaran.', '', 25549),
(126454, 'esMX', '', '¿Qué paladín deseas quitar de tus filas?', 25549),
(126453, 'esMX', '', 'Las fuerzas que están dentro de esta ciudad maldita no podrán ocultarse por mucho tiempo.$b$bEspero tus órdenes.', 25549),
(126452, 'esMX', '', 'Invoquemos la luz en este lugar profano.$b$b¿En qué puedo ayudarte?', 25549),
(126451, 'esMX', '', 'Saludos, $GAlto señor:Alta señora;. Estoy para servirte.', 25549),
(126450, 'esMX', 'Me han... ¿derrotado? Es... imposible...', '', 25549),
(126449, 'esMX', 'Hermano... ¿por qué?', '', 25549),
(126448, 'esMX', '', 'Galius, querido, deberías lanzar el hechizo que te he enseñado. ¡Y NO LO ECHES A PERDER!', 25549),
(126447, 'esMX', '', '¿Quieres un poco de veneno para tu espada?', 25549),
(126446, 'esMX', '', '¡No tengo tiempo para estupideces!', 25549),
(126445, 'esMX', '', ' ¿Creíste que podías hacerlo solo?', 25549),
(126444, 'esMX', '', 'Debo visitar las aguas de sanación.', 25549),
(126443, 'esMX', '', 'Necesito... recuperar el aliento.', 25549),
(126442, 'esMX', '', 'Estos huesos viejos necesitan un descanso.', 25549),
(126441, 'esMX', '', '¡Siente la furia de los Tótem siniestro!', 25549),
(126440, 'esMX', '', 'Yo puedo destruirte con un solo dedo. ', 25549),
(126439, 'esMX', '', '¡No debiste cruzarte en mi camino!', 25549),
(126438, 'esMX', '', '¡No estás a la altura de los elementos!', 25549),
(126437, 'esMX', '', 'Ni siquiera me hizo sudar.', 25549),
(126436, 'esMX', '', 'No tolero a los incompetentes.', 25549),
(126435, 'esMX', 'Thelsia Testarroble', 'Thelsia Testarroble', 25549),
(126434, 'esMX', 'Phillip Fosormenta', 'Phillip Fosormenta', 25549),
(126433, 'esMX', 'Kralgon Barbaluz', 'Kralgon Barbaluz', 25549),
(126432, 'esMX', 'Vindicadora Edhri', 'Vindicadora Edhri', 25549),
(126431, 'esMX', 'Vindicador Dran''aan', 'Vindicador Dran''aan', 25549),
(126430, 'esMX', 'Fiona Fosormenta', 'Fiona Fosormenta', 25549),
(126429, 'esMX', '', 'Haz exactamente lo que yo digo, $Gmuchacho:muchacha;.', 25549),
(126428, 'esMX', '¿Qué paladín deseas quitar de tus filas?', '', 25549),
(126427, 'esMX', '', '¿No se te antoja masacrar?', 25549),
(126426, 'esMX', 'Las fuerzas que están dentro de esta ciudad maldita no podrán ocultarse por mucho tiempo.$b$bEspero tus órdenes.', '', 25549),
(126425, 'esMX', 'Invoquemos la luz en este lugar profano.$b$b¿En qué puedo ayudarte?', '', 25549),
(126424, 'esMX', '', 'Sigue... Te alcanzaré más tarde.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126423, 'esMX', '', '¿Te importaría encargarte de eso por mí?', 25549),
(126422, 'esMX', '', 'Oigo el llamado de la tumba...', 25549),
(126421, 'esMX', 'Saludos, $GAlto señor:Alta señora;. Estoy para servirte.', '', 25549),
(126420, 'esMX', '', '¡Mi hacha tiene hambre!', 25549),
(126419, 'esMX', '', '¡Hora de jugar!', 25549),
(126418, 'esMX', '', '¿Creíste que ibas a quedarte con toda la diversión?', 25549),
(126417, 'esMX', '', '¡Enviemos a nuestros enemigos a la horca!', 25549),
(126416, 'esMX', '', '¡La muerte espera!', 25549),
(126415, 'esMX', '', '¡Hora de morir!', 25549),
(126414, 'esMX', '', 'Ah, sí. El dulce aroma de la muerte.', 25549),
(126413, 'esMX', '', '¡Bienvenido a la tumba!', 25549),
(126412, 'esMX', '', '¡Deja que la sangre fluya!', 25549),
(126411, 'esMX', '¡No estás a la altura de este poder!', '¡No estás a la altura de este poder!', 25549),
(126410, 'esMX', '¡Maestra, concédeme tu fuerza!', '¡Maestra, concédeme tu fuerza!', 25549),
(126409, 'esMX', '¡No permitiré que me sigan negando!', '¡No permitiré que me sigan negando!', 25549),
(126408, 'esMX', '¡No! ¡Me lo prometieron!', '¡No! ¡Me lo prometieron!', 25549),
(126407, 'esMX', '', 'No te preocupes... Sanaré.', 25549),
(126406, 'esMX', '', '¡Sigue sin mí!', 25549),
(126405, 'esMX', '', 'Déjame...', 25549),
(126404, 'esMX', '', '¡Hora de morir!', 25549),
(126403, 'esMX', '', '¡No eres capaz de igualar mi habilidad!', 25549),
(126402, 'esMX', '', 'Permíteme acompañarte a tu fin.', 25549),
(126401, 'esMX', '', '¡Todos estamos solos en la muerte!', 25549),
(126400, 'esMX', '', '¡Te dejaré hecho huesos y cenizas!', 25549),
(126399, 'esMX', '', '¡¿Cómo se siente tener mi espada en la espalda!?', 25549),
(126398, 'esMX', '', '¡Me entrené para esto!', 25549),
(126397, 'esMX', '', '¿Quién se está ocupando del rescate?', 25549),
(126396, 'esMX', '', 'Surjo de las sombras.', 25549),
(126395, 'esMX', '', '¡Termina con esto ahora!', 25549),
(126394, 'esMX', 'Yo... eh... ¡tengo que irme! ¡Adiós!', '', 25549),
(126393, 'esMX', '', '¡A ver si apuñalas de una vez!', 25549),
(126392, 'esMX', '', '¿Necesitas un poco más de sutileza?', 25549),
(126391, 'esMX', '', 'Parece que necesitas mi ayuda.', 25549),
(126390, 'esMX', '', 'Ningún desafío.', 25549),
(126389, 'esMX', '', 'Ah, parece que estás $Gmuerto:muerta;.', 25549),
(126388, 'esMX', '', 'Nunca te cruces con una princesa que lleva una daga.', 25549),
(126387, 'esMX', '', '¡Voy a retroceder!', 25549),
(126386, 'esMX', '', '¡Sigue adelante!', 25549),
(126385, 'esMX', '', '¡Termina el trabajo!', 25549),
(126384, 'esMX', '', 'No te preocupes, pronto estarás muerto.', 25549),
(126383, 'esMX', '', '¡Te presento a mi daga!', 25549),
(126382, 'esMX', '', '¡Te llegó la hora!', 25549),
(126381, 'esMX', '', '¡Yo me encargo!', 25549),
(126380, 'esMX', '¡Yo... yo no tuve nada que ver con todo esto! ¡Galius Miremoore jamás caería hipnotizado ante un insignificante súcubo!', '', 25549),
(126379, 'esMX', 'Auch, mi cabeza... qué... ¿qué sucedió?', '', 25549),
(126378, 'esMX', 'Con gusto, mi señor.', '', 25549),
(126377, 'esMX', 'Variss, deshazte de esta basura.', '', 25549),
(126376, 'esMX', 'No tan rápido...', '', 25549),
(126375, 'esMX', '', '¡Prueba mis garras!', 25549),
(126374, 'esMX', '', '¡Yo te cubro, Archidruida!', 25549),
(126373, 'esMX', '', '¡Salgamos de aquí!', 25549),
(126372, 'esMX', '', '¡Ja! ¡No puedes contra nosotros!', 25549),
(126371, 'esMX', '', '¡Qué bien se siente ensuciarme las garras!', 25549),
(126370, 'esMX', '', '¡Aún tengo más para dar!', 25549),
(126369, 'esMX', '', '¡Aah! ¡Eso duele!', 25549),
(126368, 'esMX', 'Galius se desmaya.', '', 25549),
(126367, 'esMX', '', 'Necesito... tomar un poco de aire.', 25549),
(126366, 'esMX', '', 'Necesito retroceder. ¡Sigan avanzando!', 25549),
(126365, 'esMX', '', '¡Mira estas garras!', 25549),
(126364, 'esMX', '', '¡Tengo ganas de clavar mis garras!', 25549),
(126363, 'esMX', '', '¡Hagamos daño!', 25549),
(126362, 'esMX', '', '¡Yo me encargo!', 25549),
(126361, 'esMX', 'La Piedra de la muerte es demasiado inestable. Debemos almacenarla en la Vorágine, alejada de todo. Llévasela a Nobundo; él se encargará de todo.', '', 25549),
(126360, 'esMX', '¡Entren al templo, rápido! Encuentren al demonio que lidera este ataque y aniquílenlo.', '', 25549),
(126359, 'esMX', '¡Necesito tu ayuda!', '¡Necesito tu ayuda!', 25549),
(126358, 'esMX', '¡Necesito tu acero!', '¡Necesito tu acero!', 25549),
(126357, 'esMX', '¡Necesito tu escudo!', '¡Necesito tu escudo!', 25549),
(126356, 'esMX', 'Estoy listo para ser invocado.', 'Estoy lista para ser invocada.', 25549),
(126355, 'esMX', '', 'Con tu liderazgo, el Consejo de Cosecha Oscura se volverá más poderoso que nunca.', 25549),
(126354, 'esMX', 'Estoy listo para enfrentarme a Tugar Tótem de sangre. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Estoy lista para enfrentarme a Tugar Tótem de sangre. (100 fragmentos del vacío |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 25549),
(126352, 'esMX', '', 'He llegado para asistirte y darte mis consejos sobre las amenazas indirectas que supone la Legión. Necesito que estés $Gpreparado:preparada;, estas misiones serán extremadamente difíciles. $b$bNecesitaremos Fragmentos del vacío para destruir sus defensas o equiparte a ti con defensas para contrarrestar sus horribles ataques. Puede que tenga algunos fragmentos de más ocasionalmente, pero no siempre será así. Debes estar $Gpreparado:preparada;.', 25549),
(126348, 'esMX', 'Has interrumpido la producción bélica de la Legión, aunque sea por un momento. Cada victoria cuenta en esta costa oscura.', '', 25549),
(126347, 'esMX', 'Estas alimañas recogen los minerales para sus hornos. Cada fragmento que arranquemos de sus manos es una espada menos contra nuestras fuerzas.', '', 25549),
(126337, 'esMX', 'Obedezco.', '', 25549),
(126336, 'esMX', '¡Asesina a $geste intruso:esta intrusa;!', '', 25549),
(126335, 'esMX', '¡¿Qué?! ¿Qué estás haciendo? ¡Nooo!', '', 25549),
(126334, 'esMX', '¡¿Destruirme?! Claro que no, hermano. ¡Solo te usaré como mi instrumento!', '', 25549),
(126333, 'esMX', 'Raest, no puedo permitir que liberes tu poder sobre Azeroth. ¡Si no te detienes, tendré que destruirte!', '', 25549),
(126332, 'esMX', 'No debiste seguirme, hermano. El Vacío Abisal alimenta mi fuerza. ¡Me han vuelto más poderoso de lo que jamás hayas imaginado!', '', 25549),
(126331, 'esMX', 'Tu Kirin Tor me ha dado uno de sus cristales de portal. Seguramente estarán complacidos con la noticia de tu éxito. Gracias de nuevo, $n. Nos volveremos a ver.', '', 25549),
(126330, 'esMX', 'Aun así, estaré atento a esos malditos traicioneros hasta derrotar a sus amos de la Legión.', '', 25549),
(126329, 'esMX', 'Ahora que Tugar desapareció, los Viltótem ya no serán una gran amenaza.', '', 25549),
(126328, 'esMX', '¡Aquí estoy! Estoy listo para... ¿Qué? ¡Tugar ha caído! ¡No es justo, te quedaste con toda la diversión!', '', 25549),
(126327, 'esMX', 'Esto... no cambia nada. La Legión... prevalecerá...', '', 25549),
(126326, 'esMX', '¡Contemplen mi más grande creación! ¡Con el poder de la Legión de mi lado, lograré destruir a Tótem del Trueno!', '', 25549),
(126325, 'esMX', 'Más les vale estar liiiiiistos para perder, $rt. ¡Llevo una semana sin darle nada de comer a este oso y los devorará de un bocado!', '', 25549),
(126324, 'esMX', 'Sus esfuerzos son inútiles. Sígueme y lo entenderás...', '', 25549),
(126321, 'esMX', 'Te dejaré elegir cómo conseguir los componentes finales para el ritual de purificación.$b$bTal vez también puedas averiguar qué es lo que ha estado alzando a los no-muertos en este lugar maldito.', '', 25549),
(126320, 'esMX', '¡Lo único que están logrando es demorar lo inevitable! ¡Mis bestias viles se han vuelto todavía más fuertes!', '', 25549),
(126319, 'esMX', '¡Insecto! ¡Me encontraste solo porque yo me dejé encontrar! ¡Ahora, me vengaré de Tótem del Trueno... y de ti!', '', 25549),
(126317, 'esMX', '', '¡Reúne a nuestros aliados! ¡Lucha por Tótem del Trueno! ¡Prevaleceremos!', 25549),
(126316, 'esMX', '', '¡Sus tribus dispares no están a la altura de nuestro ejército infinito!', 25549),
(126315, 'esMX', '¡Contrólate, o desatarás una destrucción masiva!', '', 25549),
(126314, 'esMX', '¡Clarividente! ¡Alto! ¡Estás destruyendo los planos elementales!', '', 25549),
(126313, 'esMX', '¡¿Qué está sucediendo?! ¡Tú... no puedes... derrotarme!', '', 25549),
(126312, 'esMX', '¡Un muro de llamas! ¡Aaaahh! Ve y encárgate de Tugar. ¡Te alcanzaré en cuanto pueda!', '', 25549),
(126311, 'esMX', '', 'Es difícil conseguir un buen ayudante. Esto se va a poner... intenso.', 25549),
(126310, 'esMX', '¿Qué es esa baratija que traes, chamán enclenque? ¿Pretendes enfrentarme con esa piedrita?', '', 25549),
(126309, 'esMX', '¡Argh!', '', 25549),
(126308, 'esMX', 'Por supuesto, querida. ¡No dejaré que arruinen nuestra cita!', '', 25549),
(126307, 'esMX', '', '¡Galius, querido, estos intrusos intentan interrumpir nuestro tiempo a solas! ¡ACABA CON ELLOS!', 25549),
(126306, 'esMX', '¡Como digas, cariño!', '', 25549),
(126305, 'esMX', 'Llévame a la Costa Quebrada.', 'Llévame a la Costa Quebrada.', 25549),
(126304, 'esMX', 'Estoy listo para ir a la Vorágine.', 'Estoy lista para ir a la Vorágine.', 25549),
(126303, 'esMX', 'Creemos que la bóveda perdida del titán está al noreste de la Vorágine. No debería tomarnos demasiado tiempo encontrarla. \n\n¿$GListo, Sumo sacerdote:Lista, Suma sacerdotisa;?', '', 25549),
(126302, 'esMX', '', 'Tal vez se pueda llegar a un acuerdo. $GGran maestro:Gran maestra; $n, luces bastante mal. ¡Deberías regresar al Pico de la Serenidad!', 25549),
(126301, 'esMX', 'Clarividente, avísame cuando necesites subir hasta donde está el Guardia apocalíptico. Canalizaré mi energía a través de tu Piedra de la muerte.', '', 25549),
(126300, 'esMX', '', 'Un último pedido, pequeña criatura. Thunderaan necesita tu ayuda.', 25549),
(126299, 'esMX', '', 'Te acompañaría, pero me temo que es una cueva del tamaño de los seres de carne. ¡Canaliza mi poder a través de tu Piedra de la muerte y aplasta a nuestros enemigos!', 25549),
(126298, 'esMX', 'Therazane necesita ayuda en una cueva cercana. ¡Ve lo antes posible!', '', 25549),
(126297, 'esMX', '¡Aprovecha mi ira, Clarividente! ¡Haz que la Legión arda con el poder del Señor del fuego!', '', 25549),
(126296, 'esMX', 'Clarividente, Fulguron ha solicitado su presencia en lo alto de la colina.', '', 25549),
(126295, 'esMX', '¡Canaliza mi poder a través de la Piedra de la muerte y destruye a esos propagadores viles!', '', 25549),
(126294, 'esMX', '¡Ah, deliciosas almas! ¡Quiero más!', '', 25549),
(126293, 'esMX', '', '¿Una bóveda perdida de un titán... conservada a la perfección? ¡Esto pasará a la historia! ¿Qué supones que contengan estas preciosuras?', 25549),
(126292, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_FELIMMOLATION:20|t%s empieza a lanzar |cFFFF0000|Hspell:233062|h[Quemadura infernal]|h|r. ¡Escóndete!', '', 25549),
(126291, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONINFERNAL:20|t¡%s te marca con |cFFFF0000|Hspell:233272|h[Estrella destrozadora]|h|r! ¡Escóndete!', '', 25549),
(126290, 'esMX', '|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERSGREEN:20|t¡%s te marca con un |cFFFF0000|Hspell:232249|h[Cometa vil]|h|r!', '', 25549),
(126289, 'esMX', '¿Quién osa interrumpir mi festín?', '', 25549),
(126288, 'esMX', 'Será un placer verte arder en llamas. ¡Hasta nunca, mortal!', '', 25549),
(126287, 'esMX', '¡Tal vez hayas logrado destruir mi nave, pero te aseguro que esa será tu última victoria!', '', 25549),
(126286, 'esMX', '¡Suficiente! ¡No tengo tiempo que perder!', '', 25549),
(126285, 'esMX', '¡Puede que esta madera luzca mal, pero su magia tiene la fuerza que necesitamos!', '¡Puede que esta madera luzca mal, pero su magia tiene la fuerza que necesitamos!', 25549),
(126284, 'esMX', '¡Todavía queda mucho duramen útil en este árbol!', '¡Todavía queda mucho duramen útil en este árbol!', 25549),
(126283, 'esMX', 'El poder de la Legión está disminuyendo. ¡Tenemos que acabar con esto ahora!', '', 25549),
(126282, 'esMX', 'Estoy listo para traer la fuente de poder.', 'Estoy lista para traer la fuente de poder.', 25549),
(126281, 'esMX', 'Me lo merecía.', '', 25549),
(126280, 'esMX', '¡Los héroes no mueren... reviven!', '', 25549),
(126279, 'esMX', '¡Búscame afuera de inmediato! ¡Es hora de cortar las cadenas de la Legión y liberar a Azsuna!', '', 25549),
(126278, 'esMX', 'Este es solo... el comienzo...', '', 25549),
(126277, 'esMX', '¡Somos infinitos! Nuestra visión se extiende más allá del horizonte de tu mundo miserable.', '', 25549),
(126276, 'esMX', '', 'Los Viltótem capturaron a mi pueblo para reclutarlo entre sus tropas. ¡Debemos detener este mal!', 25549),
(126275, 'esMX', '¿Por qué todo lo que vendes es tan costoso?', '¿Por qué todo lo que vendes es tan costoso?', 25549),
(126274, 'esMX', '¿Cómo puedo aportar al esfuerzo de guerra?', '¿Cómo puedo aportar al esfuerzo de guerra?', 25549),
(126273, 'esMX', 'Sí, el medallón de estatus y el anillo de nobleza son costosos... demasiado costosos como para que alguien pueda comprarlos sin ayuda.$b$bSugiero que te unas con otros aventureros y elijas un campeón. Para invocar a los miembros de alto rango del Consejo Abisal solo se necesita un medallón o un anillo, pero harán falta muchos héroes para derrotarlos.$b$bBuena suerte.', '', 25549),
(126272, 'esMX', '¡Perturbar los campos del Martillo Crepuscular y atacar el Alto Consejo Abisal!\n\n¡Matar a los poderosos colosos silítidos que habitan en las tres colmenas!\n\nRecolectar silitista, una especia de color rojo muy valiosa, para nuestra facción.\n\n¡Aventurarse en Ahn''Qiraj y encargarse de los qiraji y las antiguas amenazas divinas que habitan en el interior!\n\nLos aventureros que prefieran no luchar, también pueden participar donando material de guerra, específicamente carne, a nuestra causa.', '', 25549),
(126271, 'esMX', 'Un día como este, hace muchos años, un héroe llamado Kalahad hizo sonar el gong del Escarabajo, con lo que abrió las puertas de Ahn''Qiraj y dio inicio a una guerra nunca antes vista en Kalimdor.$b$bHoy, para celebrar los actos heroicos de aquellos aventureros ancestrales regresamos a Silithus y seguimos sus pasos.$b$bY más importante aún: es una competencia entre la Horda y la Alianza. El grupo que obtenga más créditos en las próximas 24 horas podrá izar su bandera junto al gong por lo que queda del año.', '', 25549),
(126270, 'esMX', '', 'De acuerdo. $GSumo sacerdote:Suma sacerdotisa;, danos un momento para agregarlos en los anales de la Luz. Nos encontraremos en el Templo Luz abisal.', 25549),
(126269, 'esMX', 'Eres tú, $GSumo sacerdote:Suma sacerdotisa;.', '', 25549),
(126268, 'esMX', 'Azeroth sabía que tarde o temprano el vacío si iba a apoderar de esta cámara. Sabía quiénes se encargarían de proteger a estas criaturas y ponerlas al servicio de la Luz.', '', 25549),
(126267, 'esMX', 'Te equivocas. Es por eso que Azeroth me envió... nos envió... hasta aquí.', '', 25549),
(126266, 'esMX', '', '¡No queda nadie para cuidar a estas pobres criaturas!', 25549),
(126265, 'esMX', '', 'Mmm, el custodio se está apagando.Quizá la cámara ha consumido toda su energía.', 25549),
(126264, 'esMX', 'Ese era el último. Espero que sea la última vez que tengo que pasar por esto...', '', 25549),
(126263, 'esMX', '¡Los grandes tampoco querían perderse la fiesta! ¡Tengan cuidado!', '', 25549),
(126262, 'esMX', 'Percibo algo de corrupción entre mis hermanos. Cuídate de la purificación.', '', 25549),
(126261, 'esMX', '', 'Engendros de la Luz, apenas de este mundo. Un buen hechizo de disipación debería dispersarlos.', 25549),
(126260, 'esMX', '¡Eso sí que fue de ayuda! ¡Muy bien, aquí vamos!', '', 25549),
(126259, 'esMX', 'Imposible cumplir. No es posible abortar el protocolo de purificación. Puede que los visitantes estén corrompidos. Si oyes susurros de origen desconocido, avanza directamente a la luz abrasadora.', '', 25549),
(126258, 'esMX', 'Mmm... ¡Detén el protocolo, ya!', '', 25549),
(126257, 'esMX', '¡Más de una vez! Tú eres el gran Portavoz sabelotodo. Deberías saber cómo se apaga.', '', 25549),
(126256, 'esMX', '¿Otra vez? ¿Ya habías hecho esto antes, hermano?', '', 25549),
(126255, 'esMX', '¡Ah, no! ¡Otra vez no!', '', 25549),
(126254, 'esMX', '¡Alerta! Se detectan energías del vacío. Iniciando protocolo de purificación.', '', 25549),
(126253, 'esMX', 'Estas criaturas nobles nos protegían desde antes de que supiéramos cómo protegernos a nosotros mismos.', '', 25549),
(126252, 'esMX', 'Desde el momento de su creación, este planeta ha recibido bombardeos de entidades invasoras corruptas. Las muertes en combate redujeron gradualmente la cantidad de Buscadores. En este momento, solo se conoce la existencia de estos tres.', '', 25549),
(126251, 'esMX', '¿Y qué pasó con ellos?', '', 25549),
(126250, 'esMX', '', '¿Entonces solo quedan tres aquí?', 25549),
(126249, 'esMX', 'Accediendo... Conteo actual de Buscadores conocidos: tres.', '', 25549),
(126248, 'esMX', '¿Manadas? ¡Jamás hemos visto uno! ¿Cuántos quedan?', '', 25549),
(126247, 'esMX', 'Designación: Buscador. Criaturas salvajes imbuidas con la Luz de los Creadores. Se elegía a los mejores especímenes de cada manada. Los entrenaban para servir a los vigilantes y los enviaban rápidamente a los sitios de corrupción de acuerdo con los protocolos de contención.', '', 25549),
(126246, 'esMX', 'Permíteme mostrarte.', '', 25549),
(126245, 'esMX', '', 'Señor custodio, en el nombre de la Forja, ¿qué se supone que es un Buscador?', 25549),
(126244, 'esMX', 'Buscadores... claro, sí, debe haber sido por eso que me envió a este lugar. Quería que encontremos a esas criaturas.', '', 25549),
(126243, 'esMX', 'Estado del portavoz verificado. Bienvenido, portavoz. ¿Has venido a recuperar a los buscadores?', '', 25549),
(126242, 'esMX', '¿Qué quieres decir? ¿Que yo no soy esencial? Tú no serás esencial... impertinente...', '', 25549),
(126241, 'esMX', 'No se detectaron formas de vida esenciales. Reanudando análisis.', '', 25549),
(126240, 'esMX', '¡Ah, sé bien dónde va a terminar esto! ¡Alcen las armas!', '', 25549),
(126239, 'esMX', 'Analizando formas de vida.', '', 25549),
(126238, 'esMX', 'Sistemas activos. Visitantes detectados.', '', 25549),
(126237, 'esMX', 'Deben activarse simultáneamente. $GSumo sacerdote:Suma sacerdotisa;, ¿harías los honores?', '', 25549),
(126236, 'esMX', 'Ah, qué pena.', '', 25549),
(126235, 'esMX', '', '¡Creo que ya no es necesario que sigas buscando palancas e interruptores, Brann!', 25549),
(126234, 'esMX', 'Revola ruk maez amir.', '', 25549),
(126233, 'esMX', '¡Guau! ¡Esta puerta sí que es grande! Debería haber una palanca por algún lado. ¡Siempre hay una palanca!', '', 25549),
(126232, 'esMX', 'Iniciando proceso de atraque.', '', 25549),
(126231, 'esMX', '', 'Nos acercamos a lo que parece ser la entrada a la bóveda.', 25549),
(126230, 'esMX', 'Se sentía... como un amanecer.', '', 25549),
(126229, 'esMX', 'Entonces... ¿estás diciendo que el planeta te hizo "sentir" que tenías que venir?', '', 25549),
(126228, 'esMX', 'A ver... supongamos que eres el alma de un mundo, ¿no? ¿Qué clase de sentimientos crees que tendrías? Por momentos te sentirías como un volcán a punto de explotar; por momentos un mar oscuro y profundo. No sé cómo describirlo exactamente.', '', 25549),
(126227, 'esMX', '', '¿Y qué significa eso?', 25549),
(126226, 'esMX', 'No explícitamente. Fue más bien... como una sensación... pero no una sensación como la que tendríamos tú y yo.', '', 25549),
(126225, 'esMX', 'Entonces, hermano... ¿el planeta, Azeroth, te dijo... que vinieras hasta aquí?', '', 25549),
(126224, 'esMX', '', 'El mar permanece calmo, incluso tan cerca de la Vorágine.', 25549),
(126223, 'esMX', 'Tomé prestado un pequeño submarino de mis amigos de la Liga de Expedicionarios. Partiremos hacia la costa de Azsuna en cuanto puedas acompañarnos, $GSumo sacerdote:Suma sacerdotisa;.', '', 25549),
(126222, 'esMX', '', '¡Adalid! Tengo información importante para ti.', 25549),
(126221, 'esMX', 'Es un honor haber sido elegido para esta misión. No te fallaré, $GGran maestro:Gran maestra; $n.', '', 25549),
(126220, 'esMX', 'Necesito que convenzas al resto de las órdenes para que se unan a nosotros contra la Legión. ¡Debemos pelear juntos!', 'Necesito que convenzas al resto de las órdenes para que se unan a nosotros contra la Legión. ¡Debemos pelear juntos!', 25549),
(126219, 'esMX', 'La Legión Ardiente se acerca a Azeroth. Todos debemos hacer nuestra parte.', '', 25549),
(126218, 'esMX', 'Hoy celebramos el aniversario del sonido del gong del Escarabajo. Verás gran cantidad de festividades en Silithus.$b$bUna parte de la tradición es convocar a los insectos colosales de las tres colmenas de silítidos. Para ello, necesitaremos carne. Montones y montones de carne.$b$b¿Nos ayudas?', '', 25549),
(126217, 'esMX', '', 'Estoy tan, pero tan cansada. Pero no podré descansar hasta estar segura de que nuestra orden sobrevivirá.', 25549),
(126216, 'esMX', '¡Con tu liderazgo y nuestro Brebaje de tormenta, prevaleceremos!', '', 25549),
(126215, 'esMX', 'Yo enfrentaré a Zen''dral. ¡Elévame!', 'Yo enfrentaré a Zen''dral. ¡Elévame!', 25549),
(126214, 'esMX', '¡Debemos liberar a esta tierra de la corrupción de la Legión!', '', 25549),
(126209, 'esMX', '', 'Parece que los lacayos de Kruul estuvieron por aquí.', 25549),
(126208, 'esMX', '<Recuerda el fallecimiento de Gul''dan>', '<Recuerda el fallecimiento de Gul''dan>', 25549),
(126207, 'esMX', '¡Dulce libertad!', '', 25549),
(126206, 'esMX', 'Odyn te bendiga.', '', 25549),
(126205, 'esMX', 'Que las puertas de Valhallas se abran para ti.', '', 25549),
(126204, 'esMX', 'Gracias a Odyn. ¡Creí que era mi fin!', '', 25549),
(126203, 'esMX', '', 'Mira... \n\nEstán cerca.\n\n¡Muévete!', 25549),
(126202, 'esMX', '¿Dónde están los demás?', '¿Dónde están los demás?', 25549),
(126201, 'esMX', '', 'Pues sí, NO tengo corona. Gracias por notarlo.\n\n<La emisaria te sonríe alegremente.>', 25549),
(126200, 'esMX', '', 'Rocas grisesss y fuego verde. Otra vez.', 25549),
(126199, 'esMX', '', 'Essstá claro por qué me enviaron aquí.', 25549),
(126198, 'esMX', '', '¿Por qué ssssiempre tienen que ser los demoniossss?', 25549),
(126197, 'esMX', '', 'Me has seguido demasiado lejos, $n. Mis queridos diablillos te harán sufrir más de lo que puedes imaginar.', 25549),
(126196, 'esMX', '', '¡Tu persistencia es irritante! ¡Mis queridos diablillos, protéjanme!', 25549),
(126195, 'esMX', '¡Llévame a la Costa Quebrada!', '¡Llévame a la Costa Quebrada!', 25549),
(126194, 'esMX', 'Has demostrado una destreza excepcional en la batalla. ¡Es una pena que no hayas nacido $Gguerrero:guerrera;! Supongo que todos los mortales tienen defectos.', '', 25549),
(126193, 'esMX', 'Todavía hay algunos felskorn que no se enteraron de la muerte de su Rey divino. ¡Únete a mi Valarjar en una batalla gloriosa! ¡Haz que estos descarados se encuentren con su líder derrotado!', '', 25549),
(126192, 'esMX', '¡Por el Valarjar!', '', 25549),
(126191, 'esMX', '¡$GSeñor:Señora; de la batalla! Algunos Felskorn todavía no se han enterado de la muerte de su Rey divino. Ve y gánate mi confianza. Haz que estos descarados se encuentren con su antiguo amo.', '', 25549),
(126190, 'esMX', '¡Has cometido un error al interrumpir mi festín, mortal! ¡Pagarás con tu vida!', '', 25549),
(126189, 'esMX', '¡Mi computadora! ¡¿Cómo... cómo adivinaste mi contraseña?! ¡Tenía tantos símbolos y letras mayúsculas!', '', 25549),
(126188, 'esMX', '', 'Sabrá que ha cometido un error. ¡La Legión Ardiente es nuestro verdadero aliado!', 25549),
(126187, 'esMX', 'Su atención por favor. Esta nave está a punto de autodestruirse. Abandonen la nave de inmediato.', '', 25549),
(126186, 'esMX', '', '¿Acaso fue Syrenne quien te envió hasta aquí? ¿Por qué enviaría a $Gun forastero:una forastera; en lugar de uno de los suyos?', 25549),
(126185, 'esMX', '', '¡Pagarás esta traición con tu vida!', 25549),
(126184, 'esMX', '', '¡Eres una desgracia, Lexera! Juraste proteger nuestra ciudad.', 25549),
(126183, 'esMX', '', 'Nosss vemosss allí.', 25549),
(126182, 'esMX', '', 'Tantos mesessss de confinamiento en esa nave apessstosa hicieron que enloqueciera. Además, la sssituación requería alguien con mis habilidadesss...\n\nTal vez tendría que haberme clonado primero.', 25549),
(126181, 'esMX', '¿Por qué abandonaste a los demás?', '¿Por qué abandonaste a los demás?', 25549),
(126180, 'esMX', 'Tus amplios conocimientos de cocina te permiten identificar esta flor extraña. ¡Es saludable y hasta puede hacerles bien a tus amigos!', 'Tus amplios conocimientos de cocina te permiten identificar esta flor extraña. ¡Es saludable y hasta puede hacerles bien a tus amigos!', 25549),
(126179, 'esMX', 'Como pandaren, reconoces esta flor comestible. ¡Hora de llevarla a tu boca!', 'Como pandaren, reconoces esta flor comestible. ¡Hora de llevarla a tu boca!', 25549),
(126178, 'esMX', '', 'Me alegra que honrarasss nuestro pacto, $GDessstripador:Dessstripadora; $n. Puede que te haya ssssubestimado.', 25549),
(126177, 'esMX', 'Has aprendido mucho sobre alimentos naturales con la herboristería. ¡Esto es comestible, sin duda!', 'Has aprendido mucho sobre alimentos naturales con la herboristería. ¡Esto es comestible, sin duda!', 25549),
(126176, 'esMX', 'Como druida, reconoces las plantas e ingredientes contenidos en este alimento. Es seguro comerlo.', 'Como druida, reconoces las plantas e ingredientes contenidos en este alimento. Es seguro comerlo.', 25549),
(126175, 'esMX', '¡$n purifica el orbe vil, lo que otorga a todos probabilidad de golpe crítico aumentada!', '¡$n purifica el orbe vil, lo que otorga a todos probabilidad de golpe crítico aumentada!', 25549),
(126174, 'esMX', '¡$n destruye el orbe vil, lo que otorga a todos probabilidad de golpe crítico aumentada!', '¡$n destruye el orbe vil, lo que otorga a todos probabilidad de golpe crítico aumentada!', 25549),
(126173, 'esMX', '¡No importa! Pagarás por esto... ¡DEVORARÉ TU ALMA!', '', 25549),
(126172, 'esMX', '¡Asqueroso mortal! ¡¿Qué le has hecho a mi nave?!', '', 25549),
(126171, 'esMX', '¡$n absorbe la magia del tomo infernal, lo que otorga a todos reducción de daño!', '¡$n absorbe la magia del tomo infernal, lo que otorga a todos reducción de daño!', 25549),
(126170, 'esMX', 'Tu entrenamiento como cazador de demonios ya te preparó hace mucho para esto. Obtén el poder del interior del tomo infernal.', 'Tu entrenamiento como cazador de demonios ya te preparó hace mucho para esto. Obtén el poder del interior del tomo infernal.', 25549),
(126169, 'esMX', 'Como brujo, este tipo de magia vil menor no representa un peligro para ti. Absorbe el poder del tomo infernal.', 'Como bruja, este tipo de magia vil menor no representa un peligro para ti. Absorbe el poder del tomo infernal.', 25549),
(126168, 'esMX', 'A los sacerdotes el orbe les parece antinatural. Debe ser destruido.', 'A los sacerdotes el orbe les parece antinatural. Debe ser destruido.', 25549),
(126167, 'esMX', 'La dedicación a la orden de los paladines sagrados demanda que purifiques esta corrupción vil.', 'La dedicación a la orden de los paladines sagrados demanda que purifiques esta corrupción vil.', 25549),
(126166, 'esMX', '¡Arrasen esta tierra! ¡No dejen ni un solo mortal con vida! ¡Todas sus almas serán mías!', '', 25549),
(126165, 'esMX', '', 'Podría haberme encargado de él... era ssssolo cuestión de tiempo. Graciassss.', 25549),
(126164, 'esMX', '', 'Ah, $GDessstripador:Dessstripadora; $n. Ya que estásss aquí, podrías darnos una mano.', 25549),
(126163, 'esMX', '¡Más almas para alimentar la energía vil! ¡Necesito más!', '', 25549),
(126162, 'esMX', 'Muln escupe a los pies de Magatha con disgusto.', '', 25549),
(126161, 'esMX', 'Más... ¡Necesito más almas!', '', 25549),
(126160, 'esMX', 'Hizo algunos comentarios sarcásticos sobre nuestra vigilancia y se marchó sola. No he vuelto a verla desde entonces.', '', 25549),
(126159, 'esMX', 'Te aseguro que no se le permitirá actuar con libertad.', '', 25549),
(126158, 'esMX', 'Pero tendríamos un problema mucho más grande si estuviera rondando libremente por el mundo. Creo que es mejor vigilarla de cerca.', '', 25549),
(126157, 'esMX', 'Muln, sé que verla aquí te enfurece y enfurece al resto de los taurení.', '', 25549),
(126156, 'esMX', '¡¿Patético?! ¡Clarividente, expúlsala de aquí! ¡No permitiré esto!', '', 25549),
(126155, 'esMX', '', 'Olvídalo, bufón. ¡Hay cosas más importantes en juego que tu patético jefe!', 25549),
(126154, 'esMX', '¿Dejarás que este monstruo entre en nuestro espacio sagrado? ¡Asesinó a nuestro jefe!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126153, 'esMX', 'Si lo deseas, puedo hacer que regreses al Salón del Guardián.', '', 25549),
(126152, 'esMX', 'No lo conocía bien, pero no dudo que Antonidas habría estado orgulloso de lo que lograste este día, $GArchimago:Archimaga; $p.', '', 25549),
(126151, 'esMX', '', 'He visto lo que hace tu supuesto "don", demonio. ¡Jamás me uniré con los de tu tipo!', 25549),
(126150, 'esMX', '¡Es inútil resistirse! ¡Únete a nosotros o te desollaré y haré una capa con tu piel!', '', 25549),
(126149, 'esMX', '', '¡Ey! ¡Libérame de estos grilletes!', 25549),
(126148, 'esMX', '', 'Gracias, pequeño.', 25549),
(126147, 'esMX', '', '¡Gracias! ¡Si no hubiera estado encadenado, le habría dado una paliza a ese bruto asqueroso!', 25549),
(126146, 'esMX', '¡Más carne para el fuego!', '', 25549),
(126145, 'esMX', '¡Tu vida por la Legión!', '', 25549),
(126144, 'esMX', '¡Pisotearé tus huesos!', '', 25549),
(126143, 'esMX', '¡Te aplastaré!', '', 25549),
(126142, 'esMX', 'Repara mi armadura, Gurr.', 'Repara mi armadura, Gurr.', 25549),
(126141, 'esMX', 'Gurr no saber cómo usar pequeño yunque.\n\n<El Bruto Mo''arg se mira los pies.>', '', 25549),
(126140, 'esMX', '¡En la otra esquina, un pirata con una definición letal del cañón principal! ¡Junten sus garfios para recibir a Roñanegra!', '', 25549),
(126139, 'esMX', 'Y ahora en el escenario, con ese ritmo que hace saltar el alma, ¡Aporreador y sus bailarines!', '', 25549),
(126138, 'esMX', 'Y en la otra esquina, está el terrible trío... ¡Hudson, Cosarpía y Dupree del equipo Ogrewatch!', '', 25549),
(126137, 'esMX', 'Enciéndanse para saludar al genio que literalmente derretirá sus corazones, ¡es Burnstachio!', '', 25549),
(126136, 'esMX', 'Y ahora el contendiente que tanto nos cuesta... ¡Es Ray D. Tear!', '', 25549),
(126135, 'esMX', 'Y en la otra esquina, un cazador de un esplendor increíble espectacularmente incomprensible, ¡Johnny Fenómeno!', '', 25549),
(126134, 'esMX', 'Y nuestro otro contendiente, un gusano al que le encantan las llamas. ¡Vamos, Carl! ¿No sabes acaso lo que pasa cuando se juega con fuego?', '', 25549),
(126133, 'esMX', 'También entrando en la arena... una máquina atractiva que produce bella música.', '', 25549),
(126132, 'esMX', 'Y en la otra esquina, no uno ni dos, ¡sino los TRES enanos letales del Consejo Martillo de Guerra!', '', 25549),
(126131, 'esMX', '¡Inserta una moneda de oro para luchar con el maestro Paku!', '', 25549),
(126130, 'esMX', 'En la otra esquina... ¡un dinosaurio enorme!', '', 25549),
(126129, 'esMX', 'En la otra esquina, un contendiente tan antiguo que nadie recuerda su verdadero nombre. ¡Lo llamaremos Serpiente de Antaño!', '', 25549),
(126128, 'esMX', 'En la otra esquina, un maestro de las sombras Y de la iluminación de interiores, ¡el maestro de las Sombras Aameen!', '', 25549),
(126127, 'esMX', 'Y presentando al draenei obsesionado con coleccionar mascotas, ¡tenemos a Ash''katzuum!', '', 25549),
(126126, 'esMX', 'Y su contendiente, ¡Bill, el ingeniero custodio de la muerte! Esperen... ¿Qué? ¿¡Bill!, qué haces aquí?', '', 25549),
(126125, 'esMX', 'Parece que cada día es Halloween para esta... cosa. ¡Reciban a Ooliss con sus mejores gritos!', '', 25549),
(126124, 'esMX', '¡Oh, el manatí enorme! Vino poner fin a esto... ¡ALETAFATAL!', '', 25549),
(126123, 'esMX', '¿Es ese un champiñón gigante? ¡Parece que las cosas están por ponerse extrañas!', '', 25549),
(126122, 'esMX', 'Y en esta esquina... ¿una gaviota? ¿Qué es esto, el Ojo de Azshara?', '', 25549),
(126121, 'esMX', 'Desde los caminos de Bosque del Ocaso, ¡tenemos a Puntos!', '', 25549),
(126120, 'esMX', 'Llévame a la Vorágine, o desapareceré con ella.', 'Llévame a la Vorágine, o desapareceré con ella.', 25549),
(126119, 'esMX', '', '¡Insolente! ¡Esa Piedra de la muerte se queda conmigo!', 25549),
(126118, 'esMX', 'Creo que estará más segura al cuidado de Nobundo.', 'Creo que estará más segura al cuidado de Nobundo.', 25549),
(126117, 'esMX', '', 'No sabes lo que dices. ¡Entrégamela!', 25549),
(126115, 'esMX', '', '¡En la otra esquina, un pirata con una definición letal del cañón principal! ¡Junten sus garfios para recibir a Roñanegra!', 25549),
(126114, 'esMX', '', 'Y ahora en el escenario, con ese ritmo que hace saltar el alma, ¡Aporreador y sus bailarines!', 25549),
(126113, 'esMX', '', 'Y en la otra esquina, está el terrible trío... ¡Hudson, Cosarpía y Dupree del equipo Ogrewatch!', 25549),
(126112, 'esMX', '', 'Enciéndanse para saludar al genio que literalmente derretirá sus corazones, ¡es Burnstachio!', 25549),
(126111, 'esMX', '', 'Y ahora el contendiente que tanto nos cuesta... ¡Es Ray D. Tear!', 25549),
(126110, 'esMX', '', 'Y en la otra esquina, un cazador de un esplendor increíble espectacularmente incomprensible, ¡Johnny Fenómeno!', 25549),
(126109, 'esMX', '', 'Y nuestro otro contendiente, un gusano al que le encantan las llamas. ¡Vamos, Carl! ¿No sabes acaso lo que pasa cuando se juega con fuego?', 25549),
(126108, 'esMX', '', 'Y también en la arena: un feo artilugio gnómico que emite música.', 25549),
(126107, 'esMX', '', 'Y en la otra esquina, no uno ni dos, ¡sino los TRES enanos letales del Consejo Martillo de Guerra!', 25549),
(126106, 'esMX', '', '¡Inserta una moneda de oro para luchar con el maestro Paku!', 25549),
(126105, 'esMX', '', 'En la otra esquina... ¡un dinosaurio enorme!', 25549),
(126104, 'esMX', '', 'En la otra esquina, un contendiente tan antiguo que nadie recuerda su verdadero nombre. ¡Lo llamaremos Serpiente de antaño!', 25549),
(126103, 'esMX', '', 'En la otra esquina, un maestro de las sombras Y de la iluminación de interiores, ¡el maestro de las Sombras Aameen!', 25549),
(126102, 'esMX', '', 'Y presentando al draenei obsesionado con coleccionar mascotas, ¡tenemos a Ash''katzuum!', 25549),
(126101, 'esMX', 'No te daré la Piedra de la muerte, Magatha.', 'No te daré la Piedra de la muerte, Magatha.', 25549),
(126100, 'esMX', '', 'Y su contendiente, ¡Bill, el ingeniero custodio de la muerte! Esperen... ¿Qué? ¿¡Bill!, qué haces aquí?', 25549),
(126099, 'esMX', '', '¡Oh, el manatí enorme! Vino poner fin a esto... ¡ALETAFATAL!', 25549),
(126098, 'esMX', '', '¿Es ese un champiñón gigante? ¡Parece que las cosas están por ponerse extrañas!', 25549),
(126097, 'esMX', '', 'Desde los caminos de Bosque del Ocaso, ¡tenemos a Puntos!', 25549),
(126096, 'esMX', '', 'Parece que cada día es Halloween para esta... cosa. ¡Reciban a Ooliss con sus mejores gritos!', 25549),
(126095, 'esMX', '¡Eso es! ¡Lo lograste! ¡Ahora los discos pueden alinearse y formar uno solo!', '', 25549),
(126094, 'esMX', '', 'Y en esta esquina... ¿una gaviota? ¿Qué es esto, el Ojo de Azshara?', 25549),
(126093, 'esMX', '', 'No me trates como si fuera una de tus súbditos, $r. Eres una criatura insignificante para mí.', 25549),
(126092, 'esMX', '¡No pierdas el foco, $GArchimago:Archimaga; $p! Solo queda un disco por purgar. Recuerda que mis aprendices pueden ayudarte.', '', 25549),
(126091, 'esMX', '¡Buen trabajo, $GArchimago:Archimaga; $p! La purga de la energía sobrante del disco logró detener su resonancia violenta cuando está cerca de los otros discos. Confío en que sucederá lo mismo con los otros dos.', '', 25549),
(126089, 'esMX', 'Destruye sus defensas, $n. ¡Acaba con estos demonios!', '', 25549),
(126088, 'esMX', 'Me gustaría ayudar en los Pantanales Ciegos.', 'Me gustaría ayudar en los Pantanales Ciegos.', 25549),
(126087, 'esMX', 'Debemos acabar con esta amenaza, rápido.', '', 25549),
(126086, 'esMX', '', '¿Cómo esperas usar el poder de la Piedra de la muerte si ni siquiera eres capaz de abrir tu propio portal? Insensato.', 25549),
(126085, 'esMX', '', 'Sigue por aquí y yo tomaré el camino opuesto. Te encontraré más tarde.', 25549),
(126084, 'esMX', 'No puedes derrotar... a la Legión...', '', 25549),
(126083, 'esMX', '¿Quieres la Piedra de la muerte, chamán? ¡Ven y quítamela!', '', 25549),
(126082, 'esMX', '¡Por Tótem del Trueno!', '¡Por Tótem del Trueno!', 25549),
(126081, 'esMX', '¡Resistan!', '¡Resistan!', 25549),
(126080, 'esMX', '¡Debes ayudar a los demás!', '¡Debes ayudar a los demás!', 25549),
(126079, 'esMX', '¡Que no avancen!', '¡Que no avancen!', 25549),
(126078, 'esMX', '¡No te rindas, $n!', '¡No te rindas, $n!', 25549),
(126076, 'esMX', 'Bienvenido. Espero que estés preparado para lo que sigue.', '', 25549),
(126075, 'esMX', '¡El linaje de Skovald debe extinguirse!', '', 25549),
(126074, 'esMX', '', 'Vamos, $Gmuchacho:muchacha;. Tenemos que salvar a mi tribu.', 25549),
(126073, 'esMX', '', '¡Ya basta de excusas! ¡¿Dónde está tu Clarividente?!', 25549),
(126072, 'esMX', 'La expulsión final de poder del disco arcano probablemente se parezca a lo que ya conoces. Te cuidado, si crece demasiado puede superar tu capacidad de destrucción.', '', 25549),
(126071, 'esMX', 'Estas criaturas, cuanto más tiempo permanecen con vida, más aumentan su poder. Destrúyelas rápido e interrumpe todo lo que puedas para impedir que se sigan desarrollando.', '', 25549),
(126070, 'esMX', 'Finalmente, esta es la última purga de energía del disco gélido. Recuerda a todas las criaturas contra las que te has enfrentado hasta ahora y aprovecha ese conocimiento para sacar ventaja.', '', 25549),
(126069, 'esMX', 'Las manifestaciones del disco están intentando ralentizarte para destruirte. Contrarresta sus hechizos y escápate rápido de la zona donde caerán sus ataques.', '', 25549),
(126068, 'esMX', 'Esta es la expulsión final, $GArchimago:Archimaga;. Recuerda lo que te lanzaron los enemigos a los que te enfrentaste hasta ahora y estarás $Glisto:lista; para lo que venga.', '', 25549),
(126067, 'esMX', 'Vas bien, $GArchimago:Archimaga; $p. Recuerda agrupar a las emanaciones más pequeñas para poder atacarlas con tus habilidades de área de efecto.', '', 25549),
(126066, 'esMX', '', '¡D''Bynn! ¿Me oyes? ¡En cuanto me libere, asesinaré hasta el último trampero que se me cruce por lo que nos han hecho!', 25549),
(126065, 'esMX', '¡Dichosos los ojos que te ven, $GSeñor:Señora; de la batalla $n!', '', 25549),
(126064, 'esMX', 'Si quieres recuperarlo, estoy seguro de que debe estar en algún lugar dentro de las Ruinas de Alterac, donde viven estos ogros.', '', 25549),
(126063, 'esMX', 'De todos modos, no hay de qué preocuparse. No logré descifrar cómo ayudar a Antonidas con ese disco, así que estoy seguro de que no saben qué hacer con él.', '', 25549),
(126062, 'esMX', 'Los malditos ogros. Bestias inmundas. Asaltaron nuestras ruinas hace un tiempo y desafortunadamente se llevaron la pieza del disco.', '', 25549),
(126061, 'esMX', 'Ah, sí, lo tengo. Es decir, lo tenía. Me lo robaron.', '', 25549),
(126060, 'esMX', '¿Tus cejas siguen intactas? ¡Algunos de nuestros magos aprendices no tuvieron la misma suerte la primera vez que probaron ese hechizo!', '', 25549),
(126059, 'esMX', 'Archimago Cedric, estoy buscando una pieza de un disco que te entregó Antonidas. ¿La tienes?', 'Archimago Cedric, estoy buscando una pieza de un disco que te entregó Antonidas. ¿La tienes?', 25549),
(126058, 'esMX', '$GConjurador:Conjuradora; los pirománticos de Tirisgarde están atacando a las colonias interminables en la Gruta Espeluznante. El señor Tormenta de maná nos ha ofrecido un hechizo personalizado. Dice que tú y él son "viejos amigos".', '', 25549),
(126057, 'esMX', 'En esa época estaba trabajando en ese asunto con el Archimago Alturus. Quizás él todavía sabe dónde está. Lo encontrarás justo a la salida de Karazhan.', '', 25549),
(126056, 'esMX', 'Estás hablando del Tridisco de fuego. Sí, me lo dio, pero eso fue hace mucho, en mis días de estudiante en Karazhan.', '', 25549),
(126055, 'esMX', 'Khadgar, estoy buscando una pieza de un disco que Antonidas te entregó hace mucho tiempo.', 'Khadgar, estoy buscando una pieza de un disco que Antonidas te entregó hace mucho tiempo.', 25549),
(126054, 'esMX', '', 'Siempre recordaré tus hazañas. Algún día los Marvilis también te recordarán.', 25549),
(126053, 'esMX', '', 'Al parecer, tenías razón, $Gforastero:forastera;. Gracias por ayudarme a encontrar mi camino.', 25549),
(126052, 'esMX', '¡$n! ¿Has visto lo que pasa ahí afuera? ¡Estamos tratando de contener a los demonios lo mejor que podemos!', '¡$n! ¿Has visto lo que pasa ahí afuera? ¡Estamos tratando de contener a los demonios lo mejor que podemos!', 25549),
(126051, 'esMX', '¡No permitiremos que estos demonios profanen nuestro hogar!', '¡No permitiremos que estos demonios profanen nuestro hogar!', 25549),
(126050, 'esMX', '¡Si sabes pelear, apresúrate y defiende a Tótem del Trueno! ¡No podemos darnos por vencidos!', '¡Si sabes pelear, apresúrate y defiende a Tótem del Trueno! ¡No podemos darnos por vencidos!', 25549),
(126049, 'esMX', '¡Cuidado! La Legión no tiene piedad cuando ataca.', '¡Cuidado! La Legión no tiene piedad cuando ataca.', 25549),
(126048, 'esMX', '¡$n! ¡Hemos sufrido una gran cantidad de bajas con sus ataques! ¡Cualquier ayuda que nos puedas dar nos permitirá mantener Tótem del Trueno!', '¡$n! ¡Hemos sufrido una gran cantidad de bajas con sus ataques! ¡Cualquier ayuda que nos puedas dar nos permitirá mantener Tótem del Trueno!', 25549),
(126047, 'esMX', '', 'Sin embargo, si crees que puedes terminar lo que Antonidas empezó, te daré la pieza. Buena suerte, $GArchimago:Archimaga; $n.', 25549),
(126046, 'esMX', '', 'Tras la muerte de Antonidas, decidí esconder el disco. No tenía motivos para seguir investigándolo.', 25549),
(126045, 'esMX', '', 'No había pensado en eso desde que... bueno, desde que un viejo amigo me preguntó antes de desaparecer de este mundo.', 25549),
(126044, 'esMX', '¡$GSeñor:Señora; de la batalla $n! Qué bueno que me encontraste.', '', 25549),
(126043, 'esMX', 'Estoy buscando la pieza del disco arcano de Antonidas. ¿Tú la tienes?', 'Estoy buscando la pieza del disco arcano de Antonidas. ¿Tú la tienes?', 25549),
(126042, 'esMX', 'Hola, $n. ¿Puedo ayudarte en algo?', '', 25549),
(126041, 'esMX', '', '¡Bien, te acabaré yo misma!', 25549),
(126040, 'esMX', 'Tus palabras son ciertas, valiente $c. ¡Debemos permanecer unidos!', 'Tus palabras son ciertas, valiente $c. ¡Debemos permanecer unidos!', 25549),
(126039, 'esMX', '¡La Legión! ¡Debes avisarle al resto!', '¡La Legión! ¡Debes avisarle al resto!', 25549),
(126038, 'esMX', '¡Estaré bien, debes ocuparte de los demás!', '¡Estaré bien, debes ocuparte de los demás!', 25549),
(126037, 'esMX', 'Agradezco tu ayuda.', 'Agradezco tu ayuda.', 25549),
(126036, 'esMX', 'Puedo oír valentía en tus palabras, $n. Cuídate.', 'Puedo oír valentía en tus palabras, $n. Cuídate.', 25549),
(126035, 'esMX', 'Nos aseguraremos de que todos los demonios hayan sido derrotados. Cuando tengas un momento, búscanos en el Salón de las sombras para recibir más instrucciones.', '', 25549),
(126034, 'esMX', '', 'La batalla que daremos hoy resonará en la historia; los bardos cantarán canciones sobre la gloria que alcanzaremos este día.', 25549),
(126033, 'esMX', '', '¡Con la unión de nuestras fuerzas, haremos caer a la Legión Ardiente!', 25549),
(126032, 'esMX', '¡Por fin! Déjame...', '', 25549),
(126031, 'esMX', 'Es una pena que no estarás aquí para verlo. ¡Muere!', '', 25549),
(126030, 'esMX', '¡Con un ejército de estas criaturas, lograré perforar la roca y enterrar a Tótem del Trueno!', '', 25549),
(126029, 'esMX', 'Encontré una bestia capaz de sobrevivir a la infusión vil.', '', 25549),
(126028, 'esMX', '¡Tomamos la delantera! ¡Por la Alianza!', '', 25549),
(126027, 'esMX', '¡Throm-ka! ¡La Horda tomó la delantera!', '', 25549),
(126026, 'esMX', '', 'Hoy celebramos el aniversario del sonido del gong del escarabajo. Verás todo tipo de festividades en torno a Silithus hoy.$b$bParte de la tradición incluye invocar insectos colosales de las tres colmenas de silítidos. Para esto necesitamos carne. Montones de carne.$b$b¿Puedes ayudar?', 25549),
(126025, 'esMX', '', 'Rápido, Hoja de las sombras. ¡Movámonos!', 25549),
(126024, 'esMX', 'Bueno, fue una situación bastante explosiva, pero la manejaste como todo un experto.', '', 25549),
(126023, 'esMX', '$GCampeón:Campeona;, los magos de Tirisgarde necesitan tu ayuda para erradicar a una colonia de arañas de la Gruta Espeluznante. Sus pirománticos arden de ganas de ayudarte.', '', 25549),
(126022, 'esMX', '', 'Muy bien, usa el punto de escalada. ¡Abajo!', 25549),
(126021, 'esMX', '', 'Un momento... ese bufón ebrio lo olvidó, ¿no? Más te vale que encuentres una forma de encender esa pólvora, $ct. ¡No voy a permitir que esta misión fracase!', 25549),
(126020, 'esMX', 'Estoy listo para viajar al Ojo de la Eternidad.', 'Estoy lista para viajar al Ojo de la Eternidad.', 25549),
(126019, 'esMX', '', 'Muy bien. El trabajo está casi terminado. Ahora sal de la cueva y enciende la pólvora con el fósforo que te dio Tethys.', 25549),
(126018, 'esMX', '', 'Ahora que lo pienso, mejor planta algunos explosivos más alrededor de la cueva para que suene un poco más... divertido.', 25549),
(126017, 'esMX', '', 'Bien. El próximo paso es simple: sal de la cueva sin que te vean. La pólvora hará el resto del trabajo.', 25549),
(126016, 'esMX', '', 'Por cierto, intenta que nadie te vea aquí dentro, a menos que quieras que una espada vil te atraviese la espalda.', 25549),
(126015, 'esMX', '', 'Cuando llegues al suelo, verás un barril. Está repleto de la pólvora imbuida de energía vil que... adquiriste.', 25549),
(126014, 'esMX', 'Estoy listo para enfrentar a Tugar. (Requiere la Piedra angular rebosante)', 'Estoy lista para enfrentar a Tugar. (Requiere la Piedra angular rebosante)', 25549),
(126013, 'esMX', 'Estoy listo para enfrentar a Tugar. (Se debe usar la Piedra angular rebosante de Navarrogg)', 'Estoy lista para enfrentar a Tugar. (Se debe usar la Piedra angular rebosante de Navarrogg)', 25549),
(126012, 'esMX', '¡Necesitamos enfrentar a Tugar y a sus gusanos! Avísame cuando estés $Glisto:lista; y te llevaré hasta allí.', '', 25549),
(126011, 'esMX', '', 'Tú me ayudaste a proteger estas tierras. Ahora, me toca a mí ayudarte. Ven, busquemos un lugar seguro donde hablar.', 25549),
(126010, 'esMX', 'Tienes mi eterna gratitud, $c.', 'Tienes mi eterna gratitud, $c.', 25549),
(126009, 'esMX', 'Muchas gracias, $Ghéroe:heroína;. Me has salvado de un destino horrible.', 'Muchas gracias, $Ghéroe:heroína;. Me has salvado de un destino horrible.', 25549),
(126008, 'esMX', 'Gracias, Señor de la batalla. ¡Por la Alianza!', 'Gracias, Señora de la batalla. ¡Por la Alianza!', 25549),
(126007, 'esMX', 'Llegaste justo a tiempo. Creo que se iban a dar un festín conmigo...', 'Llegaste justo a tiempo. Creo que se iban a dar un festín conmigo...', 25549),
(126006, 'esMX', '*sollozo* Eso fue... absolutamente fantástico, amiguito.', '', 25549),
(126005, 'esMX', 'Muchas gracias, $Ghéroe:heroína;. Me has salvado de un destino horrible.', 'Muchas gracias, $Ghéroe:heroína;. Me has salvado de un destino horrible.', 25549),
(126004, 'esMX', 'Cuentas con mi gratitud eterna, Señora de la batalla.', 'Cuentas con mi gratitud eterna, Señora de la batalla.', 25549),
(126003, 'esMX', 'Gracias, Señor de la batalla. ¡Por la Horda!', 'Gracias, Señora de la batalla. ¡Por la Horda!', 25549),
(126002, 'esMX', 'Llegaste justo a tiempo. Creo que se iban a dar un festín conmigo...', 'Llegaste justo a tiempo. Creo que se iban a dar un festín conmigo...', 25549),
(126001, 'esMX', '', 'Ay, no... No te lo dio, ¿verdad? ¡Sabía que se olvidaría! ¡Vas a tener que encontrar otra forma de encender la pólvora!', 25549),
(126000, 'esMX', '', '¡Ya casi lo logras! Ahora, sal de ahí y usa el fósforo que te dio Tethys para encender la pólvora.', 25549),
(125999, 'esMX', '¡Demasiado tarde, idiotas! ¡Tengo todo lo que se necesita para destruir a Tótem del Trueno!', '', 25549),
(125998, 'esMX', '', 'En el camino, aprovecha para dejar algunos explosivos más. No queremos decepcionar a Tethys, ¿no?', 25549),
(125997, 'esMX', '', 'Perfecto. El rastro de pólvora que dejaste a tu paso nos va a servir. Ahora, encuentra una salida y escapa de la cueva.', 25549),
(125996, 'esMX', '', 'Por último, es mejor que no te vean en este lugar. ¡Estos demonios son increíblemente salvajes!', 25549),
(125995, 'esMX', '', 'Cuando llegues al fondo, encontrarás el alijo de pólvora que adquiriste antes. Te recomiendo que lo recojas.', 25549),
(125994, 'esMX', '', 'Usa el punto de escalada para bajar a la cueva. Te daré más instrucciones cuando llegues.', 25549),
(125993, 'esMX', '', '¡Llegamos! Pronto, la Legión conocerá nuestra ira.', 25549),
(125992, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(125991, 'esMX', '', 'Antes de aceptar la corona, debo honrar a mi familia y cumplir el pedido de mi hermano. \n\nSi Eyir conoce al responsable del destino de mi familia, debería ser ella quien me lo diga.\n\nDime cuando estés $Glisto:lista;.', 25549),
(125990, 'esMX', '¡Con el Tirisgarde al mando, nuestras fuerzas unidas aplastarán a la Legión Ardiente de una vez por todas!', '', 25549),
(125989, 'esMX', 'Seguro que estos apóstatas poseen mejoras poderosas. ¡Un mago astuto haría bien en aprovechar y robarles ese poder, $n!', '', 25549),
(125988, 'esMX', '', '¡Ah, hemos llegado!', 25549),
(125987, 'esMX', 'Alguien... advierta a Tugar...', '', 25549),
(125986, 'esMX', 'Tugar me vengará...', '', 25549),
(125985, 'esMX', 'Llegas demasiado tarde... Tugar ganará...', '', 25549),
(125984, 'esMX', 'Estoy listo para regresar al campamento.', 'Estoy lista para regresar al campamento.', 25549),
(125982, 'esMX', '', 'No hay tiempo que perder, Hoja de las sombras. ¡Lleguemos a la cima!', 25549),
(125981, 'esMX', '¡Excelente! ¡Ahora que hemos superado la parte difícil, todo lo que tienes que hacer es destruir la nave!', '', 25549),
(125980, 'esMX', '¡Buenas noticias, $n! ¡Parece que el portal funcionó! Tus extremidades siguen intactas, ¿verdad?', '', 25549),
(125979, 'esMX', '', '¡D''Bynn, estás vivo! Estaba a punto de perder la esperanza, mi queridísimo amigo.', 25549),
(125976, 'esMX', '¡Tiemblen mientras desato todo el poder de la Legión Ardiente sobre este patético mundo!', '', 25549),
(125975, 'esMX', '', 'No se aleje, mi señor.', 25549),
(125974, 'esMX', '', 'Si Lord Mephistroth así lo desea, lo acompañaré hasta la consola de mando en la cubierta de navegación.', 25549),
(125973, 'esMX', '', 'Lo siento, maestro. Es necesario que sea usted quien ingrese los códigos de autodestrucción.', 25549),
(125972, 'esMX', '', 'Por desgracia, no tengo la autorización necesaria para emitir ese comando.', 25549),
(125971, 'esMX', '', 'Ahora que los generadores de los escudos están desactivados, puede utilizar un comando de autodestrucción para destruir la nave.', 25549),
(125970, 'esMX', 'Ya sobrecargué los generadores. ¿Qué debería hacer ahora?', 'Ya sobrecargué los generadores. ¿Qué debería hacer ahora?', 25549),
(125967, 'esMX', 'Paciencia, Tethys. No salgas corriendo todavía.', '', 25549),
(125965, 'esMX', '¡Siento una emoción incontrolable! ¡Quiero contemplar la explosión!', '', 25549),
(125964, 'esMX', '¡Ahí! ¡Detén a ese demonio antes de que llame a más seres de su raza vil!', '', 25549),
(125963, 'esMX', '¡Pongámonos raros de verdad!', '', 25549),
(125962, 'esMX', 'Recolectando', 'Recolectando', 25549),
(125957, 'esMX', 'He logrado devolver la energía a las líneas Ley de Azeroth a través del Iris de enfoque. Deberían estar restablecidas.', '', 25549),
(125956, 'esMX', '', '¡Esta farsa se termina AHORA!', 25549),
(125955, 'esMX', '', '¡Un frenesí voraz!', 25549),
(125954, 'esMX', '', '¡No puedes resistir el llamado del mar!', 25549),
(125953, 'esMX', '', '¡La marea te aplastará!', 25549),
(125952, 'esMX', '', 'No todas las tormentas vienen del cielo...', 25549),
(125951, 'esMX', '', '¡Arránquenles la carne de los huesos!', 25549),
(125950, 'esMX', '', 'Si hubieran entregado la Maretista, quizá les habría perdonado la vida...', 25549),
(125949, 'esMX', '', '¡Mi reina me ha concedido el dominio de los mares!', 25549),
(125948, 'esMX', '', '¡Enfréntate al poder que acecha bajo las olas!', 25549),
(125947, 'esMX', '', 'Le he fallado... a mi reina...', 25549),
(125945, 'esMX', '', 'Los jinetes de Lasan han emprendido vuelo. ¡Invoca a sus águilas para que te asistan en la defensa del Tótem del Trueno!', 25549),
(125944, 'esMX', 'Así es, Joanna. Gracias a $geste valiente:esta valiente; $c...', '', 25549),
(125943, 'esMX', '', '...¡y ya no percibo la sombra dentro de ti!', 25549),
(125942, 'esMX', '', '¡Archimago Xylem! Has regresado...', 25549),
(125941, 'esMX', '¡Llévame a la Costa Quebrada!', '¡Llévame a la Costa Quebrada!', 25549),
(125940, 'esMX', '', 'Espero que... te explote en la cara...', 25549),
(125930, 'esMX', 'Yo me encargaré de investigar a los Viltótem. Tráeme a los tótems cuando termines.', '', 25549),
(125926, 'esMX', '', 'Velen nos protegió antes de que la explosión nos alcanzara. Kruul no tuvo tanta suerte.', 25549),
(125925, 'esMX', '', '¡Lo lograste! Creí que te habíamos perdido en la explosión.', 25549),
(125924, 'esMX', '¡La sombra no me controlará!', '', 25549),
(125923, 'esMX', 'Sanaré tus heridas. Sigue siempre la Luz.', '', 25549),
(125922, 'esMX', 'Ay... bueno.', 'Ay... bueno.', 25549),
(125921, 'esMX', '¡Ja, ja, ja! ¿Cangrejos? ¡No haces más que poner de manifiesto tu desconocimiento sobre estos temas demoníacos! Debemos continuar con tu entrenamiento de inmediato. No queremos que quedes atrapado en el pozo de la ignorancia para siempre.', '', 25549),
(125920, 'esMX', 'Veo dos cangrejos muertos, ¿te refieres a eso?', 'Veo dos cangrejos muertos, ¿te refieres a eso?', 25549),
(125919, 'esMX', '¡Así es, $Gescudero:escudera;! Como verás, he asaltado esta costa y logré asegurar la playa contra la Legión, pero aún queda mucho trabajo por hacer. Ayer por la noche intentaron penetrar mis defensas, pero logré mantener la línea estoicamente contra su asalto. Puedes ver los cadáveres demoníacos por allá, aunque quizá no tengas las agallas para mirarlos durante mucho tiempo.', '', 25549),
(125918, 'esMX', '¿Entrenando?', '¿Entrenando?', 25549),
(125917, 'esMX', '¿Eres tú $Gescudero:escudera;? Casi no te reconozco. ¡El paso del tiempo no te ha favorecido para nada! No importa, supongo que incluso $glos:las; de edad avanzada, como tú, deben continuar con su entrenamiento.', '', 25549),
(125916, 'esMX', 'Ya estoy listo para partir.', 'Ya estoy lista para partir.', 25549),
(125915, 'esMX', 'Te saludo una vez más, Maximillian.', 'Te saludo una vez más, Maximillian.', 25549),
(125914, 'esMX', '', '¡Tenga cuidado, maestro!', 25549),
(125913, 'esMX', '', 'Si desea destruir la nave, puede sobrecargar los generadores, lo que causará un daño catastrófico al motor.', 25549),
(125912, 'esMX', '¡%s cae al suelo!', '¡%s cae el suelo!', 25549),
(125911, 'esMX', '', 'Anulación completa. Me tomé la libertad de abrir la sala de máquinas, espero que le sea de utilidad a mi maestro.', 25549),
(125910, 'esMX', '¡Se está sobrecargando de poder! ¡Cuidado!', '', 25549),
(125909, 'esMX', '¡CONTEMPLEN LA IRA DE KRUUL!', '', 25549),
(125908, 'esMX', 'Que así sea. Esta será la última vez que te cruces en nuestro camino.', '', 25549),
(125907, 'esMX', '', 'Dame un momento mientras desactivo los sistemas de defensa...', 25549),
(125906, 'esMX', '', 'Por supuesto. Lo que necesite, Lord Mephistroth. Estoy para servirlo.', 25549),
(125905, 'esMX', '¡Esto... no... no es posible!', '', 25549),
(125904, 'esMX', 'Tu luz se apaga, Profeta. Este es tu fin.', '', 25549),
(125903, 'esMX', 'No puedo mantener mi barrera por mucho más. ¡Tenemos que terminar con esto!', '', 25549),
(125902, 'esMX', '¿Has venido a recuperar el arnés? ¡Ja! ¡Veamos si puedes!', '', 25549),
(125901, 'esMX', 'Pues sí, eso me haría muy feliz. Encárgate de hacerlo.', 'Pues sí, eso me haría muy feliz. Encárgate de hacerlo.', 25549),
(125900, 'esMX', '', '¡Nosotros... nunca... nos rendiremos!', 25549),
(125899, 'esMX', '', '¿Le agradaría a mi señor oscuro que desactive todos los sistemas de defensa y de emergencia de la nave?', 25549),
(125898, 'esMX', 'Nuestro poder es infinito. Nuestras tropas son interminables. ¡Ríndanse ante el poder de la Legión Ardiente!', '', 25549),
(125897, 'esMX', '', 'Como ya sabe, Lord Mephistroth, esta nave contiene distintos sistemas de defensa diseñados para prevenir una variedad de fallas catastróficas.', 25549),
(125896, 'esMX', '¡Ja! Ustedes son todo lo que queda. No tienen esperanza, idiotas.', '', 25549),
(125895, 'esMX', '¡Saludos, caminante! Ven, siéntate junto a mi fogata. ¡No temas, he logrado asegurar esta posición en la punta de la playa y pronto frustraré el asalto de la Legión en estas tierras!', '', 25549),
(125894, 'esMX', 'Debes mantenerte firme, campeón. ¡No te des por vencido!', '', 25549),
(125893, 'esMX', '', '¡Aaaaaaah!', 25549),
(125892, 'esMX', '¡Eres tú quien está solo, Kruul! Te ha llegado la hora de morir.', '', 25549),
(125891, 'esMX', 'Su mundo caerá ante mí.', '', 25549),
(125890, 'esMX', 'Nadie vendrá a salvarlos.', '', 25549),
(125889, 'esMX', 'El arnés...', '', 25549),
(125888, 'esMX', '¡Devóratelos vivos!', '', 25549),
(125887, 'esMX', '', 'El dios de los viles y de las llamas, el mismísimo Sargeras, lo eligió para guiar a los Nathrezim a la gloria tras la derrota humillante que sufrió Tichondrius en manos de Illidan Tempestira.', 25549),
(125886, 'esMX', '', 'Por supuesto, mi señor. Usted es Mephistroth, el más poderoso y sabio de todos los Nathrezim.', 25549),
(125885, 'esMX', 'Sí, llévame de vuelta.', 'Sí, llévame de vuelta.', 25549),
(125884, 'esMX', 'Puedo devolverte al Aetherium. ¿Quieres que lo haga?', 'Puedo devolverte al Aetherium. ¿Quieres que lo haga?', 25549),
(125883, 'esMX', '', 'Si crees que me voy a quedar parada hasta congelarme, estás muy equivocado. Jaja, ¡vamos!', 25549),
(125882, 'esMX', 'Tan solo una parte de mi poder bastará para destruirlos.', '', 25549),
(125881, 'esMX', '', '¡Permítenos guiarte para convertirte en un no-muerto!', 25549),
(125880, 'esMX', '', '¡Vamos! ¡Es hora de enfrentarlo!', 25549),
(125879, 'esMX', '', 'Lamento el desorden. El Jarl creyó que una de sus mascotas podría retrasarme.', 25549),
(125878, 'esMX', 'Excelente trabajo, $GArchimago:Archimaga;. Pero me temo que las próximas manifestaciones de poder no serán fáciles de derrotar.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125877, 'esMX', '¡Estúpidos arrogantes! ¡Tengo el poder de las almas de mil mundos conquistados!', '', 25549),
(125876, 'esMX', '', 'Tengo comida fresca y vendas a tu disposición, $GArchimago:Archimaga;.', 25549),
(125875, 'esMX', '', 'Tengo orbes que podrían ser de mucha utilidad en tus tareas si las quieres, $GArchimago:Archimaga;.', 25549),
(125874, 'esMX', '$GArchimago:Archimaga;, si necesitas reparar tu equipo, estoy a tu disposición.', '', 25549),
(125873, 'esMX', 'Al parecer, el legado de Skovald sigue vigente.', '', 25549),
(125872, 'esMX', '', 'Tal como usted solicitó, ahora puedo ofrecer una variedad de servicios adicionales para servir mejor a mi señor oscuro.', 25549),
(125871, 'esMX', '', 'Mi programación estándar ha sido modificada para satisfacer todas las necesidades de Lord Mephistroth con mayor eficacia.', 25549),
(125870, 'esMX', '', 'Por supuesto, Lord Mephistroth. Aguarde un momento mientras accedo a la configuración de usuario previa...', 25549),
(125869, 'esMX', 'Estamos listos para irnos.', 'Estamos listos para irnos.', 25549),
(125868, 'esMX', 'Necesito destruir la nave. ¿Qué me recomiendas?', 'Necesito destruir la nave. ¿Qué me recomiendas?', 25549),
(125867, 'esMX', '¿Qué puedes contarme sobre mí? ¿Quién es Lord Mephistroth?', '¿Qué puedes contarme sobre mí? ¿Quién es Lord Mephistroth?', 25549),
(125866, 'esMX', 'Cuéntame sobre tu configuración anterior, S.I.R.I.', 'Cuéntame sobre tu configuración anterior, S.I.R.I.', 25549),
(125865, 'esMX', 'Gracias por quitar la maldición de Torre Oscura.', '', 25549),
(125864, 'esMX', 'Has hecho un gran trabajo. Gracias. Debemos regresar.', '', 25549),
(125862, 'esMX', 'Escaneando el nivel de estilo del oponente. Resultado: 0', '', 25549),
(125861, 'esMX', 'Tienes niveles insuficientes de funk.', '', 25549),
(125860, 'esMX', 'Cuando des la señal, $gcampeón:campeona;.', '', 25549),
(125859, 'esMX', 'A partir de ahora, haremos todo juntos.', '', 25549),
(125858, 'esMX', 'Tu ritmo anda mal.', '', 25549),
(125857, 'esMX', 'Ningún paso', '', 25549),
(125856, 'esMX', 'Qué horror', '', 25549),
(125855, 'esMX', 'Unidad de funk reactivada. Protocolos de golpe ajustados para derretir cara.', '', 25549),
(125854, 'esMX', 'Se agota la batería rítmica. Modo de conversación grosera activado.', '', 25549),
(125853, 'esMX', 'Circuitos de funk agotados...', '', 25549),
(125852, 'esMX', '¡Qué habilidad!', '¡Qué habilidad!', 25549),
(125851, 'esMX', 'Estás acabado, ¡Cajón!', 'Estás acabado, ¡Cajón!', 25549),
(125850, 'esMX', '¡Mira esos pasos funky!', '¡Mira esos pasos funky!', 25549),
(125849, 'esMX', '¡Hola! Prepárate para un desarmado rítmico.', '', 25549),
(125848, 'esMX', 'Bien hecho. Ahora debemos aventurarnos al mismísimo Vacío Abisal.', '', 25549),
(125847, 'esMX', '¡Archidruida! ¡Usa tu magia para cerrar el portal de una vez por todas!', '', 25549),
(125846, 'esMX', '¡Tenemos que cerrar el portal!', '', 25549),
(125844, 'esMX', '¡Siente la cólera de mi ejército!', '', 25549),
(125843, 'esMX', '', 'Acceso concedido. Bienvenido, Lord Mephistroth. ¿En qué puedo servirle hoy?', 25549),
(125842, 'esMX', '¡Pongámonos raros!', '', 25549),
(125841, 'esMX', '', 'Se ha detectado una falla de energía... Iniciando restauración de sistema...', 25549),
(125840, 'esMX', '', 'Matriz de Asistencia de Dominación Automática Malévola (M/A/D/A/M) iniciada. Bienvenido, usuario.', 25549),
(125839, 'esMX', 'Tu único camino es la muerte.', '', 25549),
(125838, 'esMX', 'Están poniendo a prueba mi paciencia. ¡Mueran, cretinos!', '', 25549),
(125837, 'esMX', 'Sus ejércitos caerán ante la ira de mi amo.', '', 25549),
(125836, 'esMX', '¡Las llamas eternas vienen por ustedes! ¡No podrán detenerlas!', '', 25549),
(125835, 'esMX', '', '¡Alto! ¿Quién se atreve a acercarse a la Bóveda de Eyir?', 25549),
(125834, 'esMX', '¡Por Kruul! ¡Por la Legión Ardiente!', '', 25549),
(125833, 'esMX', '', 'Yo... traje el brebaje envenenado hasta aquí. Si tan solo lo hubiera revisado antes...', 25549),
(125832, 'esMX', '¡Clara! ¡Explícate! ¡Toda la orden está muriendo!', '', 25549),
(125831, 'esMX', '', 'Vine a avisarte lo más rápido que pude. Llegué demasiado tarde...', 25549),
(125830, 'esMX', '', '¿Maestra cervecera? ¡Intentaste matarnos!', 25549),
(125829, 'esMX', '', '¡Siempre quise aprender a tejer niebla! Hasta pronto, Maestra cervecera.', 25549),
(125828, 'esMX', 'Si los necesitas, estos aprendices pueden proporcionarte algunos elementos esenciales. Te aconsejo que tomes nota de sus ofertas.', '', 25549),
(125827, 'esMX', 'Antonidas quería completar este proyecto él mismo. Era paciente, sabio y un maestro de nuestras disciplinas. Ahora debes demostrar que eres mejor que él para terminar lo que empezó.', '', 25549),
(125826, 'esMX', 'Haré desaparecer los resguardos que los protegen. Creo que si logras canalizar el poder hacia los discos a través de tu arma artefacto, provocarás una respuesta.', '', 25549),
(125825, 'esMX', '¿Esto es todo lo que su mundo tiene para dar? Patético.', '', 25549),
(125824, 'esMX', 'Antonidas logró imbuir estos discos con las mismísimas energías que los magos intentamos controlar. Sin embargo, ni él ni sus compañeros archimagos fueron capaces de difuminar la energía sobrante, y eso los dejó en el estado en el que están ahora.', '', 25549),
(125823, 'esMX', '', '¿Ves a la maestra cervecera?', 25549),
(125822, 'esMX', '', 'Creo que nos excedimos... Tendremos una terrible resaca cuando el efecto desaparezca. En fin... ¡al menos cerrar los portales va a ser pan comido!', 25549),
(125821, 'esMX', '', '¡La Maretista será nuestra!', 25549),
(125820, 'esMX', '¡Este será tu fin, Madre comandante!', '', 25549),
(125819, 'esMX', '', '¡Ya casi lo logramos! ¡Sigue así!', 25549),
(125818, 'esMX', '', '¡Cuidado! ¡Se acercan más enemigos!', 25549),
(125817, 'esMX', '', '¡Sus preciadas fuerzas de la naturaleza no son rival contra el poder de la energía vil!', 25549),
(125816, 'esMX', '', '¡Kruul renacerá!', 25549),
(125815, 'esMX', '', 'El portal está terminado. ¡Estoy contigo, $p!', 25549),
(125814, 'esMX', 'Destrúyelos, Vazuun. Mi renacimiento ya casi está completo.', '', 25549),
(125813, 'esMX', '¡Debemos derrotar al comandante antes de que arrasen con nuestras fuerzas por completo!', '', 25549),
(125811, 'esMX', '', 'Vuela con nosotros. ¡Sé rápido y certero!', 25549),
(125810, 'esMX', 'Mi poder no para de crecer. ¡Su fin está cerca!', '', 25549),
(125809, 'esMX', '', 'La espora maldita se encuentra en la cima de este risco. Tendrás que luchar para llegar a ella. ¡Buena suerte!', 25549),
(125808, 'esMX', '¡Un Heraldo de la perdición abre una Falla Abisal!', '¡Un Heraldo de la perdición abre una Falla Abisal!', 25549),
(125807, 'esMX', '', 'Intenta agregar un poco de magia sagrada. Casi siempre da resultado.', 25549),
(125806, 'esMX', '', 'Después de que lo destruyan, le solicitamos que complete una breve encuesta para ayudarnos a mejorar nuestro servicio en el futuro.', 25549),
(125805, 'esMX', '', 'La contraseña ingresada es incorrecta. Aguarde un instante mientras los agentes de seguridad llegan hacia su ubicación.', 25549),
(125803, 'esMX', '', 'Por aquí, Archidruida. ¡Está abajo, en la isla!', 25549),
(125802, 'esMX', 'Esta vrykul es la heredera del Rey divino y desea hablar con Eyir.', 'Esta vrykul es la heredera del Rey divino y desea hablar con Eyir.', 25549),
(125801, 'esMX', '', '¡Aquí arriba, Archidruida! ¡La encontramos!', 25549),
(125800, 'esMX', '', '¿Cuál es el motivo de tu regreso a Skold-Ashil, $Gforastero:forastera;?\n\n... ¿y quién es esta vrykul que te acompaña?', 25549),
(125799, 'esMX', '¡Concéntrense en el campo!', '', 25549),
(125798, 'esMX', '¡Nosotros cubriremos los flancos, $ct!', '', 25549),
(125797, 'esMX', 'En fin... ¡Nos vemos!', '', 25549),
(125796, 'esMX', 'Mmm. No se me ocurre nada.', '', 25549),
(125795, 'esMX', '¿Tienes las agallas para pararte en la puerta de mi reino? Que así sea.', '', 25549),
(125794, 'esMX', 'Uh... ¡Esto es más difícil de lo que parece! ¿Alguna vez se te ocurrió una frase interesante para decir en el momento?', '', 25549),
(125793, 'esMX', 'Emm... un momento. Debería decir algo épico y memorable antes de partir.', '', 25549),
(125792, 'esMX', 'Mira, mientras tú te encargas de este pequeño desorden (del que puedo haber sido el causante... o no…), voy a hacer una salida muy dramática.', '', 25549),
(125791, 'esMX', 'No es fácil saborear un jugoso trozo de carne de jabalí cuando te han partido el labio. No sé si me entiendes.', '', 25549),
(125790, 'esMX', '¿Yo?, no soy un gran luchador.', '', 25549),
(125789, 'esMX', 'Acabas de arruinarme una siesta perfecta.', '', 25549),
(125788, 'esMX', 'No deberías asustar a la gente de esa forma.', '', 25549),
(125787, 'esMX', '¡Uooo! ¡Cuidado!', '', 25549),
(125786, 'esMX', 'Asiste a nuestras fuerzas, Archidruida. Yo intentaré encontrar a su comandante.', '', 25549),
(125785, 'esMX', 'Nuestras fuerzas han logrado hacerlos retroceder hasta sus barricadas, pero continúan apareciendo de la nada.', '', 25549),
(125784, 'esMX', 'Los demonios han estado cómodos en la Costa Quebrada por demasiado tiempo. Es hora de un cambio.', '', 25549),
(125783, 'esMX', '', 'Has mejorado tus habilidades de lucha, Almai. Creo que has crecido tanto que la vida de un simple cervecero ya no te sienta.', 25549),
(125782, 'esMX', '', '¡Maestra cervecera, perdón por la interrupción! Haré que todos regresen a trabajar de inmediato.', 25549),
(125781, 'esMX', '', '$GGran maestro:Gran maestra; $n, te lo agradezco profundamente.', 25549),
(125780, 'esMX', '', '¡El enemigo se acerca!', 25549),
(125779, 'esMX', '', 'No bajes la guardia. No creo que estemos solos por mucho tiempo.', 25549),
(125778, 'esMX', 'La rebelión... nunca morirá...', 'La rebelión... nunca morirá...', 25549),
(125777, 'esMX', 'Al menos... morí... libre...', 'Al menos... morí... libre...', 25549),
(125776, 'esMX', 'Mi vida... por Suramar.', 'Mi vida... por Suramar.', 25549),
(125775, 'esMX', '¡Tengo que atraparlos a todos!', '', 25549),
(125774, 'esMX', 'Empecemos.', 'Empecemos.', 25549),
(125773, 'esMX', '', 'Acabaremos con la Legión Ardiente o moriremos en el intento.', 25549),
(125772, 'esMX', '', 'Párate en la runa. ¡Rápido!', 25549),
(125771, 'esMX', '', '¡Aguanta, Maestra cervecera! ¡Estamos en camino!', 25549),
(125770, 'esMX', 'Déjame explicarte lo que podemos hacer y lo que no. \n\nPODEMOS atravesar este portal hacia un portal demoníaco con el que logré conectarme. \n\nNO PODEMOS saber qué nos espera del otro lado porque la magia no funciona de esa forma.\n\nPor eso, tú irás $Gprimero:primera;. Suerte, "$ghéroe:heroína;".', '', 25549),
(125769, 'esMX', 'Opción 3: Usar el poder de tu arma artefacto contra la computadora.', 'Opción 3: Usar el poder de tu arma artefacto contra la computadora.', 25549),
(125768, 'esMX', 'Opción 2: Descargar tu frustración contra la computadora, pateándola varias veces tan fuerte como puedas.', 'Opción 2: Descargar tu frustración contra la computadora, pateándola varias veces tan fuerte como puedas.', 25549),
(125767, 'esMX', 'Opción 1: Desconectar el cable de alimentación de la computadora y volver a conectarlo.', 'Opción 1: Desconectar el cable de alimentación de la computadora y volver a conectarlo.', 25549),
(125766, 'esMX', 'Ingresar contraseña: "L0rd Meph1str0th manda".', 'Ingresar contraseña: "L0rd Meph1str0th manda".', 25549),
(125765, 'esMX', 'Ingresar contraseña: "contraseña".', 'Ingresar contraseña: "contraseña".', 25549),
(125764, 'esMX', 'Ingresar contraseña: "Todos los mundos arderán".', 'Ingresar contraseña: "Todos los mundos arderán".', 25549),
(125763, 'esMX', '¡Adelante, hacia la victoria!', '¡Adelante, hacia la victoria!', 25549),
(125762, 'esMX', 'Que la suerte te acompañe. Los esbirros de Kruul seguramente asistirán en su ayuda.', '', 25549),
(125761, 'esMX', '¡La Magistrix y sus secuaces caerán!', '¡La Magistrix y sus secuaces caerán!', 25549),
(125760, 'esMX', 'Mi familia me necesita. ¡Gracias, héroe!', 'Mi familia me necesita. ¡Gracias, heroína!', 25549),
(125759, 'esMX', '', 'Debemos tener cuidado cuando viajemos por Stormheim, $Gforastero:forastera;. Me he ganado varios enemigos por ser la descendiente de Skovald.', 25549),
(125758, 'esMX', '', 'Seguiré a pie. Buena suerte, $Gforastero:forastera;.', 25549),
(125757, 'esMX', '', 'Mis heridas... son demasiado grandes...', 25549),
(125756, 'esMX', '', '¡Hoy los dioses me sonríen!', 25549),
(125755, 'esMX', '', 'Sé que es arriesgado, pero si le damos solo una probadita nos dará el impulso que necesitamos. ¡Salud!', 25549),
(125754, 'esMX', '', '¡Jamás había visto tantos demonios en un solo lugar! Tenemos que tomar el Brebaje de tormenta, es nuestra única oportunidad.', 25549),
(125753, 'esMX', '', '¡Mi lanza los atravesará!', 25549),
(125752, 'esMX', '', 'Que así sea. ¡Levántate, Sigryn! ¡Te nombro Reina divina de los Marvilis!', 25549),
(125751, 'esMX', '', 'L... lo haré. ¡Aunque sea lo último que haga en mi vida, uniré a los Marvilis una vez más para expulsar a la Legión de esta tierra!', 25549),
(125750, 'esMX', '', '¿Puedes hacer a un lado tus errores y servir a tu pueblo?', 25549),
(125749, 'esMX', '', 'Ahora sé que mis visiones eran reales. Es tu destino unir a los Marvilis contra la Legión.', 25549),
(125748, 'esMX', '', 'Tú posees la fuerza y la voluntad necesarias para combatir a la energía vil; algo que ningún Vrykul logró jamás.', 25549),
(125747, 'esMX', '', '¡¿Qué?! Con los errores que he cometido, ¡no puedo ser digna de liderar a nuestro pueblo!', 25549),
(125746, 'esMX', '', 'Me complace ver que has regresado. Mi decisión es la siguiente: debes asumir la responsabilidad de reinar. ¡Debes convertirte en la Reina divina!', 25549),
(125745, 'esMX', '', 'Aceptaré cualquier castigo que consideres justo.', 25549),
(125744, 'esMX', '', 'Maravillosa Eyir, humildemente imploro tu perdón por mis actos.', 25549),
(125743, 'esMX', '', 'Perdóname, Eyir...', 25549),
(125742, 'esMX', '', 'No... la energía vil no me consumirá... ¡No lo permitiré!', 25549),
(125741, 'esMX', '', 'La venganza no la traerá de vuelta a la vida, Sigryn. Tu pueblo necesita un líder. ¡Si fracasas, los Marvilis estarán condenados!', 25549),
(125740, 'esMX', '', 'Pero... madre... ¡debo vengar tu muerte!', 25549),
(125739, 'esMX', '', '¡Debes luchar contra la corrupción, Sigryn! ¡Tienes la fuerza!', 25549),
(125738, 'esMX', '', '¿Qué... qué estoy haciendo? ¡Esto no está bien!', 25549),
(125737, 'esMX', '', 'Muy bien. ¡Has elegido la muerte!', 25549),
(125736, 'esMX', '', 'Te permitiré elegir. Lárgate de aquí... o muere.', 25549),
(125735, 'esMX', '', '¿Qué es esto? ¿$GEl forastero:La forastera; viene a detenerme? Estoy en deuda contigo, pero no puedo permitir que arrebates la justicia de mis manos.', 25549),
(125734, 'esMX', '', '¡No puedes esconderte detrás de estos muros por siempre, Odyn!', 25549),
(125733, 'esMX', '', 'Puedo mantener el portal abierto por un momento. Necesitarás más poder si necesitas volver a usarlo.', 25549),
(125732, 'esMX', '', 'Sigryn... ¿qué has hecho?', 25549),
(125731, 'esMX', '', '¡Madre! ¡Vengaré tu muerte!', 25549),
(125730, 'esMX', '', '¡Le mostraré a Odyn lo que es el verdadero miedo, incluso si tengo que derribar las paredes de los Salones del valor con él dentro!', 25549),
(125729, 'esMX', '', '¡Sigryn! ¡No! ¡No debes permitir que la oscuridad se apodere de ti!', 25549),
(125728, 'esMX', '', '¡Mi hermano tenía razón! ¡Los vigías titánicos no son distintos de la Legión!', 25549),
(125727, 'esMX', '', 'Él decretó que era preciso terminar con el linaje de Skovald... con sangre.', 25549),
(125726, 'esMX', '', 'Odyn temía que los herederos del Rey divino le ofrecieran el control de los Marvilis a la Legión.', 25549),
(125725, 'esMX', '', '¿¡Qué!?', 25549),
(125724, 'esMX', '', 'Muy bien. Fue el mismo Odyn quien ordenó las muertes de la familia Skovald.', 25549),
(125723, 'esMX', '', 'Sí.', 25549),
(125722, 'esMX', '', 'Hija mía... nada bueno puede salir de la respuesta a esa pregunta. ¿Estás segura de que quieres saberlo?', 25549),
(125721, 'esMX', '', 'Dime... ¿quién ordenó la muerte de mi madre?', 25549),
(125720, 'esMX', '', 'Muy bien. ¿Cuál es la pregunta, hija mía?', 25549),
(125719, 'esMX', '', 'Sin embargo, si voy a servir como tu reina, necesito que respondas una pregunta.', 25549),
(125718, 'esMX', '', 'Gran Eyir, tal como me pediste, he derrotado a los rivales pretendientes del trono de los Marvilis.', 25549),
(125717, 'esMX', 'Así que es cierto... el Alto señor ha regresado.', '', 25549),
(125716, 'esMX', '', 'Se ha... ido...', 25549),
(125715, 'esMX', '', '¡No! ¡Hermano!', 25549),
(125714, 'esMX', 'Tal vez entonces... puedas entender...', '', 25549),
(125713, 'esMX', 'Tal vez deberías preguntarles quién nos mandó a asesinar esa noche...', '', 25549),
(125712, 'esMX', 'Tú... tú crees que tus maestros son superiores a los míos...', '', 25549),
(125711, 'esMX', '', 'Lo siento, hermano. No puedo permitir que la Legión infecte a los Vrykul.', 25549),
(125710, 'esMX', 'No... no es posible...', '', 25549),
(125709, 'esMX', '', '¡No! ¡No seguiré tus pasos!', 25549),
(125708, 'esMX', '¡Ríndete, hermana! ¡La única forma que tienes de derrotarme es aceptar el poder de la energía vil!', '', 25549),
(125707, 'esMX', 'Hermana, lo siento... ¡pero si no te unes a mí, te conviertes en mi enemiga!', '', 25549),
(125706, 'esMX', '', '¡No, jamás trabajaré para la Legión!', 25549),
(125705, 'esMX', 'Había algo en nuestra sangre que nos hizo resistir su influencia... pero aún está en nuestro cuerpo. ¡Ríndete y deja que se apodere de ti!', '', 25549),
(125704, 'esMX', 'Parece que has olvidado que nuestro padre nos alimentó con la energía vil. El malestar que te produjo debe haber nublado tus recuerdos.', '', 25549),
(125703, 'esMX', '', '¡No, Torvald... has sucumbido ante las energías viles! ¡¿Pero cómo?!', 25549),
(125702, 'esMX', '¡¿Cómo puede ser?! ¡Yo acepté el don que nos concedió nuestro padre! ¡Ese que tú y nuestra madre rechazaron con tanta vehemencia!', '', 25549),
(125701, 'esMX', '', '¡Torvald, eres tú! ¡No quería dejarte, pero no tenía suficiente fuerza! ¿Cómo sobreviviste a los asesinos?', 25549),
(125700, 'esMX', 'Hermana... ha pasado mucho tiempo desde que me diste por muerto.', '', 25549),
(125699, 'esMX', '', 'No perdamos el tiempo. ¡A Vrekt!', 25549),
(125698, 'esMX', '', '¿Oíste eso? ¡Mejor vamos a ver qué sucede afuera!', 25549),
(125697, 'esMX', 'Los drekirjar respaldarán tu derecho al trono. Pero hay alguien más que podría darnos problemas.', '', 25549),
(125696, 'esMX', '¡Alto! ¡Has demostrado tu fuerza! Me has derrotado.', '', 25549),
(125695, 'esMX', '¡Los drekirjar nunca se rinden!', '', 25549),
(125694, 'esMX', 'No me importa si eres la hija del mismísimo Odyn, querida. ¡No toleraré tu insolencia!', '', 25549),
(125693, 'esMX', '', '¿Te rendirás ante mí?', 25549),
(125692, 'esMX', '', '¡Jarl Velbrand! ¡Como hija de Skovald y por orden de Eyir, reclamo el trono de los Marvilis!', 25549),
(125691, 'esMX', '', 'Seguiré hacia Hrydshal. Te veré ahí, $c.', 25549),
(125690, 'esMX', 'He sido derrotado. Tal vez subestimé tu fuerza, escudera.', '', 25549),
(125689, 'esMX', '¡Guarda tu espada!', '', 25549),
(125688, 'esMX', '', '¡Ya me cansé de tu parloteo, Vidente de runas!', 25549),
(125687, 'esMX', 'Heredaste la furia de tu padre, escudera, pero también percibo en ti su oscuridad.', '', 25549),
(125686, 'esMX', '¡Ancestros! ¡Vengan conmigo!', '', 25549),
(125685, 'esMX', '¡Así que la desgraciada hija del Rey divino ha venido a terminar la obra del insensato de su padre? La era de Skovald llegó a su fin, querida, y pronto te reunirás con él.', '', 25549),
(125684, 'esMX', '', '¡Vidente de runas Faljar! Soy Sigryn, hija de Skovald. ¡En el nombre de las Valkyra, te desafío por el reinado de los Marvilis!', 25549),
(125683, 'esMX', '', 'Me adelantaré hacia Haustvald. Sería un honor encontrarte ahí, $n.', 25549),
(125682, 'esMX', '', 'Seré tu instrumento. Dime qué tengo que hacer.', 25549),
(125681, 'esMX', '', 'Muy bien. Si es cierto que soy tan importante para los Marvilis, no puedo rechazar esta tarea.', 25549),
(125680, 'esMX', '', 'Sé que cargas con mucho peso, hija mía, pero puede que seas nuestra única esperanza.', 25549),
(125679, 'esMX', '', 'Si fracasas, los Marvilis se separarán y nadie podrá impedir que la Legión conquiste Stormheim.', 25549),
(125678, 'esMX', '', 'Eres la hija de Skovald, y tienes derecho a heredar su trono. Debemos poner de rodillas a todos los que se opongan a tu reinado.', 25549),
(125677, 'esMX', '', '$GEl forastero:La forastera; dice la verdad. Hace mucho tiempo, tuve una visión de unión entre las Valkyra y los Marvilis contra un terrible enemigo. Estaba encabezada por una descendiente de un Rey divino y una Doncella escudera.', 25549),
(125676, 'esMX', '', '$GEste forastero:Esta forastera; dice que debo unir a los Marvilis...', 25549),
(125675, 'esMX', '', '¿Así que la sangre de Skovald ha regresado a las Valkyra? ¿Sabes lo que esto significa, hija mía?', 25549),
(125674, 'esMX', '', '¡Ilustre Eyir, la mujer de la profecía ha llegado!', 25549),
(125673, 'esMX', '', 'Un momento... ese rostro... ¡Acompáñame!', 25549),
(125672, 'esMX', '', '¡¿La heredera del Rey Divino?! ¿Qué clase de locuras dices?', 25549),
(125671, 'esMX', '', 'La armadura de estas guerreras... me recuerda a la que usaba mi madre...', 25549),
(125670, 'esMX', '', '¡Skold-Ashil! De niña, mi madre me contaba historias de este sitio y de sus poderosas escuderas. ¡Sus palabras verdaderamente le hacían honor a la grandeza de este lugar!', 25549),
(125669, 'esMX', 'Así que para estar seguros, yo no mencionaría el fin del supuesto Rey Divino.', '', 25549),
(125668, 'esMX', 'Un detalle menor. Si este líder de las profecías realmente es el heredero del Rey Divino, la dimisión de Skovald podría ser un tema controversial.', '', 25549),
(125667, 'esMX', '<La consola de mando yace inerte frente a ti. Algunas runas demoníacas resplandecientes se mueven en la superficie de la terminal.>\n\nAcceso concedido.', '', 25549),
(125666, 'esMX', '<La consola de mando yace frente a ti. Algunas runas demoníacas resplandecientes se mueven a lo largo de la superficie de la terminal.>\n\nIngresar contraseña:', '', 25549),
(125664, 'esMX', '', '¡Es la última puerta! ¡Rápido!', 25549),
(125663, 'esMX', '', '¡Por aquí! Necesitamos abrir esta puerta.', 25549),
(125662, 'esMX', '', 'No veo a la Maestra cervecera por ningún lado. ¿Habrá logrado escapar?', 25549),
(125661, 'esMX', '', '¡Ahí está!', 25549),
(125660, 'esMX', '¡Pronto, su patético mundo conocerá la ira de Kruul!', '', 25549),
(125659, 'esMX', '¿Ocultarme? ¡Ja! La edad te está haciendo delirar, Profeta.', '', 25549),
(125658, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, $Gguerrero:guerrera;.', '', 25549),
(125657, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, $Gbrujo:bruja;.', '', 25549),
(125656, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, chamán.', '', 25549),
(125655, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, $Gpícaro:pícara;.', '', 25549),
(125654, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, $GSumo sacerdote:Suma sacerdotisa;.', '', 25549),
(125653, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, $GAlto señor:Alta señora;.', '', 25549),
(125652, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, monje.', '', 25549),
(125651, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, $Gmago:maga;.', '', 25549),
(125650, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, $Gcazador:cazadora;.', '', 25549),
(125649, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, druida.', '', 25549),
(125648, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar, $Gcazador:cazadora; de demonios.', '', 25549),
(125647, 'esMX', 'El destino ha conspirado para que nos volvamos a encontrar.', '', 25549),
(125646, 'esMX', '¡Buen trabajo, héroe! Has salvado a muchas almas nobles de convertirse en combustible para la magia vil de la Legión.', '', 25549),
(125645, 'esMX', '¡La Legión está profanando las costas de Stormheim! ¡No dejes ni un demonio en pie!', '', 25549),
(125644, 'esMX', 'Murgulis hace una pequeña pausa y te observa con una especie de sonrisa en su rostro antes de salir corriendo.', '', 25549),
(125643, 'esMX', 'Oh, oh...', '', 25549),
(125642, 'esMX', '', '¿Crees que los demonios saben lo que sucederá si beben el Brebaje de tormenta?', 25549),
(125641, 'esMX', '', 'Esperaba que estuviéramos a salvo aquí. Hasta hace poco, la Legión ni siquiera sabía de nuestra existencia.', 25549),
(125640, 'esMX', 'Hazte presente, demonio. ¡No te puedes ocultar de la Luz!', '', 25549),
(125639, 'esMX', '', '¡Tantos demonios!', 25549),
(125638, 'esMX', 'Percibo una fuerza oscura en la distancia, dentro del Vacío Abisal. Veamos qué es lo que hay oculto detrás del velo.', '', 25549),
(125637, 'esMX', 'Vine hasta aquí a observar el vacío que se alza sobre la tumba en busca de respuestas a una pregunta que desconozco.', '', 25549),
(125636, 'esMX', '¡%s drena completamente la energía del iris de enfoque! ¡Has perdido!', '¡%s drena completamente la energía del iris de enfoque! ¡Has perdido!', 25549),
(125635, 'esMX', 'La Legión robó el corazón de Kruul.', 'La Legión robó el corazón de Kruul.', 25549),
(125634, 'esMX', 'La Luz no nos abandonará.', '', 25549),
(125633, 'esMX', '¡Lo lograste! ¡Estoy curado!', '', 25549),
(125632, 'esMX', 'Percibí tu llegada, $n. Esta vez, tu presencia trae augurios oscuros.', '', 25549),
(125631, 'esMX', 'Murgulis señala hacia la estructura demoníaca de la costa sur.', '', 25549),
(125630, 'esMX', '¡Gahgll grllg!', '', 25549),
(125629, 'esMX', '¡Haré que estas criaturas te devoren el alma poco a poco!', '', 25549),
(125628, 'esMX', '¡¿Qué es todo este disturbio?! ¡No toleraré más demoras para preparar a estas criaturas!', '', 25549),
(125627, 'esMX', '', 'Deberíamos ir al alto antes de que se nos escape otra vez. ¡Yo te sigo!', 25549),
(125626, 'esMX', '', 'El profeta Velen pasa mucho tiempo cuidando a los heridos. Deberíamos empezar en el edificio de primeros auxilios.', 25549),
(125625, 'esMX', '', 'Se dirigía hacia el Alto de Krasus. Lo oí murmurar algo acerca de la tumba.', 25549),
(125624, 'esMX', '', 'Me temo que el Profeta acaba de irse.', 25549),
(125623, 'esMX', '', '¡Nunca confíes en un mago para hacer el trabajo de un cazador de demonios!', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125622, 'esMX', '', 'Arruinaste tus propias tierras, $Gforastero:forastera;. ¡No arruinarás las mías!', 25549),
(125621, 'esMX', '', 'Mmm, parece que eso solo empeoró las cosas. Intenta agregar un poco de magia de las sombras.', 25549),
(125620, 'esMX', '¡Gracias! ¡Vamos a mostrarles a estos demonios de qué estamos hechos!', '¡Gracias! ¡Vamos a mostrarles a estos demonios de qué estamos hechos!', 25549),
(125619, 'esMX', 'Te lo agradezco. Creí que aquí estaríamos a salvo de la Legión...', 'Te lo agradezco. Creí que aquí estaríamos a salvo de la Legión...', 25549),
(125618, 'esMX', '¡Bendiciones, $Gamigo:amiga;!', '¡Bendiciones, $Gamigo:amiga;!', 25549),
(125617, 'esMX', '¡Uf, eso sí que era incómodo. ¡Gracias!', '¡Uf, eso sí que era incómodo. ¡Gracias!', 25549),
(125616, 'esMX', 'Murgulis señala un pescado con mal aspecto y vuelve a mirarte. Parece que quiere que hagas algo al respecto.', '', 25549),
(125615, 'esMX', '', 'El corazón del Alto señor Kruul... Esto no está nada bien.', 25549),
(125614, 'esMX', 'Murglll... ¡Gruggl urg grullulll!', '', 25549),
(125613, 'esMX', '', 'Todavía podría haber demonios al acecho. Mantente alerta.', 25549),
(125612, 'esMX', '', '¡%s obtiene el efecto de |cFFFF0404|Hspell:230981|h[Alma separada]|h|r!', 25549),
(125611, 'esMX', 'El bruto parecía estar dispuesto a todo para protegerlo. Se esfumó apenas salió de la bóveda.', '', 25549),
(125610, 'esMX', 'Todo lo que sé es que tenía forma de corazón. ¿Te suena?', '', 25549),
(125609, 'esMX', '¡Ey! ¡Yo vi lo que se llevó el demonio! Acércate.', '', 25549),
(125608, 'esMX', '', '¿Quieres saber qué buscaba la Legión? ¡Que rebajara mis precios! ¡Los resguardos que usa la Legión no son nada baratos, cariño!', 25549),
(125607, 'esMX', 'Me temo que no lo sabremos por un tiempo. ¡Las secciones internas siguen cubiertas en llamas viles!', '', 25549),
(125606, 'esMX', '', '¡¿Ni siquiera sabemos si estamos a salvo y ya estás preguntando por la bóveda?! ¡Los únicos que tienen permiso para entrar son los miembros del Consejo de los Seis!', 25549),
(125605, 'esMX', '¿Qué importa? ¡Las bóvedas contienen nuestras reliquias más preciadas! ¡Cualquiera podría ocasionar un desastre!', '', 25549),
(125604, 'esMX', '', '¡Nuestros pobres cerveceros! Quizás el hechizo de depuración podría ayudarlos.', 25549),
(125603, 'esMX', '', 'Entremos.', 25549),
(125602, 'esMX', '', '$GGran maestro:Gran maestra; $n, gracias por venir tan pronto. ¡Ayúdame a abrir esta puerta!', 25549),
(125601, 'esMX', 'Bien, Glutonia. ¿Qué buscaba la Legión?', 'Bien, Glutonia. ¿Qué buscaba la Legión?', 25549),
(125600, 'esMX', '¿Qué se llevó exactamente?', '¿Qué se llevó exactamente?', 25549),
(125599, 'esMX', '¿Falta algo de la bóveda?', '¿Falta algo de la bóveda?', 25549),
(125598, 'esMX', '¿Sabes qué fue lo que se llevaron?', '¿Sabes qué fue lo que se llevaron?', 25549),
(125597, 'esMX', 'Saludos.', '', 25549),
(125596, 'esMX', '', 'Buenos días.', 25549),
(125595, 'esMX', '¿Qué se robaron en el ataque?', '¿Qué se robaron en el ataque?', 25549),
(125594, 'esMX', 'Necesito acceder a mi banco.', 'Necesito acceder a mi banco.', 25549),
(125593, 'esMX', '¿En qué puedo ayudarte?', '', 25549),
(125592, 'esMX', '¡%s cae el suelo!', '', 25549),
(125591, 'esMX', '¡Mrrglgl! ¡Grlmgrlmargl!', '', 25549),
(125590, 'esMX', '¡Gaghh gurl!', '', 25549),
(125589, 'esMX', '', 'Espero que a los monjes les guste mi brebaje de celebración. Me despido por el momento, $GGran maestro:Gran maestra;.', 25549),
(125588, 'esMX', '¡Mrrglgl! ¡Grlmrgl grmlgggl!', '', 25549),
(125587, 'esMX', '<<7.1 RPP>> ¡Hagamos trampa para sortear todo el contenido de los Caídos de la noche de la 7.0! ¡Quiero probar la 7.1!', '<<7.1 RPP>> ¡Hagamos trampa para sortear todo el contenido de los Caídos de la noche de la 7.0! ¡Quiero probar la 7.1!', 25549),
(125586, 'esMX', '', '¡Te maldigo, $Gforastero:forastera;!', 25549),
(125585, 'esMX', '¡Esto servirá!', '¡Esto servirá!', 25549),
(125584, 'esMX', 'Un Duende travieso revela su forma verdadera.', '', 25549),
(125583, 'esMX', 'Medivh, ¿eres tú?', 'Medivh, ¿eres tú?', 25549),
(125582, 'esMX', 'Una figura fantasmal del guardián flota sobre ti. Sientes como si estuviera escuchando, como si quisiera que notasen su presencia...', 'Una figura fantasmal del guardián flota sobre ti. Sientes como si estuviera escuchando, como si quisiera que notasen su presencia...', 25549),
(125581, 'esMX', 'Te lo agradezco. Debemos mantener la armonía. Nuestra supervivencia depende de ello.', '', 25549),
(125576, 'esMX', 'Y muchos barriles más para almacenarlo. Es una preparación bastante volátil y la madera normal no lo resistiría.', '', 25549),
(125575, 'esMX', '', '¡$GGran maestro:Gran maestra;! ¡Es hora de celebrar!', 25549),
(125574, 'esMX', '¡$GGran maestro:Gran maestra; $n! La Maestra cervecera Blanche y yo estábamos comentando la situación en la Costa Quebrada. Es hora de unir a todas las fuerzas de Azeroth y emprender una ofensiva conjunta contra la Legión.', '', 25549),
(125572, 'esMX', '¡Mi aliento contiene la ira de la tormenta! ¡Solo indícame dónde atacar, y nuestros enemigos caerán!', '', 25549),
(125571, 'esMX', '¡Ese demonio vil dirige su nave para atacar las Puertas del Valor! He enviado a una de mis val''kyr para que te ayude, $Ghéroe:heroína;. ¡Debemos ganar esta batalla!', '', 25549),
(125570, 'esMX', 'Estoy listo para llevar el Ojo de Aman''Thul a Dalaran.', 'Estoy lista para llevar el Ojo de Aman''Thul a Dalaran.', 25549),
(125569, 'esMX', 'El destino de Azeroth está en nuestras manos.', '', 25549),
(125568, 'esMX', '', 'Luces $Gperturbado:perturbada;, $ct. ¿Te sucede algo?', 25549),
(125567, 'esMX', 'Llévame a la Cervecería del Trueno.', 'Llévame a la Cervecería del Trueno.', 25549),
(125566, 'esMX', '', 'Gracias. ¡Nos veremos ahí!', 25549),
(125565, 'esMX', '¡Oh, no! ¡Justo cuando habíamos empezado a producir nuestro Brebaje de tormenta!', '', 25549),
(125564, 'esMX', '', '¡$GGran maestro:Gran maestra;! ¡La Legión está arrasando con la Cervecería del Trueno! ¡Ayúdanos!', 25549),
(125563, 'esMX', '', 'Sujétate bien, $GSeñor;Señora; de la muerte. Vayamos hasta ese pico.', 25549),
(125562, 'esMX', '', '¡Muere en nombre de Illidan!', 25549),
(125561, 'esMX', '', '¿El banco? ¿Cómo es posible...?', 25549),
(125560, 'esMX', 'Quiero ir a la Prueba de valor (Banda).', 'Quiero ir a la Prueba de valor (Banda).', 25549),
(125559, 'esMX', 'Teletranspórtame a la Costa Quebrada.', 'Teletranspórtame a la Costa Quebrada.', 25549),
(125558, 'esMX', '<Malorne te observa con un guiño de aprobación en sus ojos.>', '', 25549),
(125557, 'esMX', '', '¡Asgrim! ¡Pagarás por esta corrupción, demonio!', 25549),
(125556, 'esMX', '¡Contemplen a su honorable campeón, Val''kyr! Estoy seguro de que esta será una reunión conmovedora...', '', 25549),
(125555, 'esMX', 'Por favor, no se detengan, continúen intentando sobrevivir en vano. ¡Es divertido ver cómo se esfuerzan!', '', 25549),
(125554, 'esMX', '¡Mortales patéticos! Ni siquiera sus insignificantes val''kyr pueden salvarlos de la destrucción...', '', 25549),
(125553, 'esMX', 'Deberías regresar al Punto de liberación de inmediato, $n. Ha habido algunas... digamos... novedades.', '', 25549),
(125552, 'esMX', 'Gruuuuu.....', 'Gruuuuu.....', 25549),
(125551, 'esMX', 'Mimiron, extraño la antigua apariencia de Hati, ¿puedes volverla a como era antes?', 'Mimiron, extraño la antigua apariencia de Hati, ¿puedes volverla a como era antes?', 25549),
(125550, 'esMX', '¡Quiero ser el más maravilloso!', '', 25549),
(125549, 'esMX', '¡Muchas gracias, colega!', '¡Muchas gracias, colega!', 25549),
(125548, 'esMX', '¡No puedes huir del olvido!', '', 25549),
(125547, 'esMX', '¡Tus esfuerzos son inútiles!', '', 25549),
(125546, 'esMX', '¡Ja! ¡Retuércete y chilla! ¡Que tu grito de ira llegue a los cielos antes de morir!', '', 25549),
(125545, 'esMX', 'Siempre vuelan en pedazos superrápido.', '', 25549),
(125544, 'esMX', 'Oooh, ¡parece que estás muy mal!', '', 25549),
(125543, 'esMX', '¡Como ordene mi maestra!', '', 25549),
(125542, 'esMX', '¡Sangre! ¡Sangre por todos lados!', '', 25549),
(125541, 'esMX', 'No puedo... resistir...', '', 25549),
(125540, 'esMX', '¡Monstruos! ¡Monstruos por todas partes!', '', 25549),
(125539, 'esMX', '¡Los ancestros se comunican conmigo y dicen que debes morir!', '', 25549),
(125538, 'esMX', '¡Estos... estos no son los salones de Valhallas!', '', 25549),
(125537, 'esMX', 'Por las barbas de Odyn... ¿dónde estoy?', '', 25549),
(125536, 'esMX', 'Gracias, $gpequeño desconocido:pequeña desconocida;.', '', 25549),
(125535, 'esMX', '¡Malditos demonios!', '', 25549),
(125534, 'esMX', 'Las voces... ¡mentían! ¡No eran los ancestros!', '', 25549),
(125533, 'esMX', '¡Soy libre!', '', 25549),
(125532, 'esMX', 'Deberíamos regresar a mi torre. Imagino que tenemos mucho de que hablar...', '', 25549),
(125531, 'esMX', 'Gracias... $n. Gracias por perdonarme la vida. No... no sé lo que me sucedió...', '', 25549),
(125530, 'esMX', 'No... las líneas Ley siguen demasiado débiles... Sin magia.... Azeroth seguramente...', '', 25549),
(125529, 'esMX', 'Eso salió bien. Ahora, sigamos con la destrucción de Azeroth...', '', 25549),
(125528, 'esMX', '¡Ahora, veamos el verdadero potencial de un poder ilimitado!', '', 25549),
(125527, 'esMX', '¡Detenlos! ¡Por el bien de Azeroth!', '', 25549),
(125526, 'esMX', '¡No puedes desafiar la voluntad de la Legión, $GArchimago:Archimaga;! ¡Todos morirán!', '', 25549),
(125525, 'esMX', '¡Debo regresar este poder a través del Iris!', '', 25549),
(125524, 'esMX', 'No... ¡no puede ser!', '', 25549),
(125523, 'esMX', '¡Me apoderaré de TODO EL MANÁ!', '', 25549),
(125522, 'esMX', '¡Traga magia, $gimpostor:impostora;!', '', 25549),
(125521, 'esMX', 'Sin magia, su mundo estará listo para sufrir el azote de mis maestros demoníacos... ¡y mi poder no conocerá límites!', '', 25549),
(125520, 'esMX', '¡Llegas demasiado tarde, $c! Con el Iris de enfoque bajo mi control, puedo absorber la energía arcana de las líneas Ley de Azeroth hacia mi magnífico ser.', '', 25549),
(125519, 'esMX', 'Llévame al Sendero de Sufrimiento de la Costa Quebrada.', 'Llévame al Sendero de Sufrimiento de la Costa Quebrada.', 25549),
(125518, 'esMX', 'Teletransporte al Arco de las Profundidades.', 'Teletransporte al Arco de las Profundidades.', 25549),
(125517, 'esMX', 'Teletransporte al Patio del palacio.', 'Teletransporte al Patio del palacio.', 25549),
(125516, 'esMX', '¡Esto estará bomba!', '', 25549),
(125515, 'esMX', '¡Verán que tengo una personalidad explosiva!', '', 25549),
(125514, 'esMX', 'Ven a mí... ¡con toda tu angustia!', '', 25549),
(125513, 'esMX', '¡Parece que tendré que hacerlo yo misma!', '¡Parece que tendré que hacerlo yo misma!', 25549),
(125512, 'esMX', '¿Cómo esperan que me convierta en el mejor DPS si me tengo que mover cada vez que algo prende fuego?', '', 25549),
(125511, 'esMX', 'En realidad, vivo casi todo el tiempo en las sombras. ¿Por qué? Es un estilo de vida. Quizás no lo entiendas.', '', 25549),
(125510, 'esMX', 'No me echaron de mi último equipo. ¡Me fui porque eran todos unos debiluchos!', '', 25549),
(125509, 'esMX', '¿Que cuál es el secreto? Practica con jabalíes durante diez años como hice yo. Vas a fortalecerte... y podrás comer tocino.', '', 25549),
(125508, 'esMX', '¿Que si quise matar al cazador con el que me enfrenté? No. Pensé que se hacia el muerto y por eso seguí apuñalándolo. Digo, ¿quién se muere así de fácil? Qué debilucho.', '', 25549),
(125507, 'esMX', 'Si alguna vez vengo por ti, nunca me verás venir. A menos que te deje. ¡Y entonces seré lo último que veas!', '', 25549),
(125506, 'esMX', '¿Quieres saber en qué nivel estoy? En buen nivel, amigo. En buen nivel.', '', 25549),
(125505, 'esMX', '¿Quieres mi opinión? ¡Vive para ganar hasta el día que mueras! Esa es mi máxima.', '', 25549),
(125504, 'esMX', '¿Burlaste a la muerte alguna vez? Sabes que fui yo quien inventó eso, ¿no?', '', 25549),
(125503, 'esMX', '... Entonces dije: "¡No puedes matar lo que no puedes ver!". ¡Y luego desaparecí! ¡JA, JA! Deberías haber visto el rostro de ese niño. ¡Casi deja caer su helado!', '', 25549),
(125502, 'esMX', '... ¿Veneno? ¡Por qué hacer eso, si puedes hacerlo por atrás!', '', 25549),
(125501, 'esMX', 'Dejé a mi último equipo porque eran unos debiluchos. ¡Todos! Voy a formar un equipo nuevo, pero no sé si estás a la altura. Solo haz correr la voz, ¿sí?', '', 25549),
(125500, 'esMX', '¿Matar desde el cielo? ¡Eso lo he hecho 1,979 veces! ¿Quieres ser el número 1,800? Ya me parecía.', '', 25549),
(125499, 'esMX', '... y entonces dije: "Qué buena historia, amigo". ¡JA!', '', 25549),
(125498, 'esMX', 'Rezzle feliz por ayudar a $Gamigo:amiga;. ¡Rezzle no ser mal demonio después de todo!', '', 25549),
(125496, 'esMX', 'Esconde los Orbes de llamas de Felo''melorn', 'Esconde los Orbes de llamas de Felo''melorn', 25549),
(125495, 'esMX', 'Revela los Orbes de llamas de Felo''melorn', 'Revela los Orbes de llamas de Felo''melorn', 25549),
(125494, 'esMX', 'Atrapados en el tiempo.$b$b¡Ves, por ESTO me quedo con la telemancia! La cronomancia es peligrosa.$b$b<Oculeth hace una pausa breve.>$b$bPodrían quedar atrapados. Por siempre. ¡Debemos detener a Elisande!', '', 25549),
(125493, 'esMX', '', 'El poder de la Fuente de la Noche fue liberado...$b$bTiene que haber otro modo. ¡Lo encontraremos!', 25549),
(125492, 'esMX', '', 'Elisande... ¿Qué has hecho?', 25549),
(125491, 'esMX', '¡No pensaba que fuera posible! Cuánta energía se requiere...', '', 25549),
(125490, 'esMX', 'Perderás tu progreso si abandonas esta instancia. ¿Estás segura de que deseas salir?', 'Perderás tu progreso si abandonas esta instancia. ¿Estás segura de que deseas salir?', 25549),
(125489, 'esMX', 'Me gustaría salir de las Cuevas de los Lamentos.', 'Me gustaría salir de las Cuevas de los Lamentos.', 25549),
(125488, 'esMX', 'Llévame a las Cuevas de los Lamentos.', 'Llévame a las Cuevas de los Lamentos.', 25549),
(125487, 'esMX', '', 'Las Cuevas de los Lamentos están invadidas por bestias descarriadas. \n\nDebemos exterminarlas cuando sus líneas se vuelvan demasiado numerosas.', 25549),
(125486, 'esMX', 'Solo los entrenadores más experimentados pueden participar.\n\nCuando hayas entrenado a 15 mascotas hasta llegar a su nivel máximo, estarás listo.', 'Solo los entrenadores más experimentados pueden participar.\n\nCuando hayas entrenado a 15 mascotas hasta llegar a su nivel máximo, estarás lista.', 25549),
(125485, 'esMX', '¿Cuáles son los requisitos para entrar?', '¿Cuáles son los requisitos para entrar?', 25549),
(125482, 'esMX', 'Ábrete camino hasta allí de inmediato y encuentra a mi sirviente, el poderoso Vethir. ¡Juntos, le mostrarán a la Legión la clase de recibimiento que les damos a los de su clase en Stormheim!', '', 25549),
(125481, 'esMX', 'El pueblo de Azsuna está en deuda contigo.', '', 25549),
(125480, 'esMX', '', 'Tal vez. Esta nueva posición tiene algunos beneficiossss.', 25549),
(125479, 'esMX', 'Envíame al campo de batalla, estoy listo para ayudar.', 'Envíame al campo de batalla, estoy lista para ayudar.', 25549),
(125478, 'esMX', 'Nuestra guerra contra la Legión nos ha costado mucho. Muchos héroes valientes perdieron sus vidas en esta campaña. Esos sacrificios no pueden ser en vano.\n\n¡Aprovechemos nuestra oportunidad y quedémonos con la victoria!', '', 25549),
(125477, 'esMX', '', 'Tengo que hacer una limpieza aquí. Nos veremos pronto, $n.', 25549),
(125476, 'esMX', '', 'Mmm. De mal en peor. Bien, al menos aquí estamos mejor posicionados para pelear contra la Legión.', 25549),
(125475, 'esMX', '', 'Veamos dónde terminamos.', 25549),
(125474, 'esMX', '¡El Manantial Nor''Danil ha caído en manos de la Legión! ¡Purga a la infestación antes de que arrase con todo Azsuna!', '', 25549),
(125473, 'esMX', '¡Nuevamente, gracias, y dale mis saludos al Kirin Tor cuando lo veas!', '', 25549),
(125472, 'esMX', '¡Aún queda mucho trabajo por hacer para terminar de eliminar a estos rebeldes, pero gracias a tus esfuerzos será mucho más sencillo!', '', 25549),
(125471, 'esMX', '¡Hemos recuperado el control de la mayoría de los sistemas críticos, incluso la red de teletransporte para que regreses a salvo a Dalaran!', '', 25549),
(125470, 'esMX', '¡Lo lograste! Esta será la última vez que veamos la horrible cabezota de Sicco Termochufe en nuestra ciudad.', '', 25549),
(125469, 'esMX', '¡Claro que no! ¡Vine preparado!', '', 25549),
(125468, 'esMX', 'Envíen todo lo que tenemos. ¡Todo! ¡Protéjanme, tontos!', '', 25549),
(125467, 'esMX', '¡Excelente! Los sensores indican que Termochufe se ha retirado hacia la Cámara Manitas. ¡Tienes que eliminarlo de una vez por todas!', '', 25549),
(125466, 'esMX', '¡NOOOOOO! ¡MI MISIL!', '', 25549),
(125465, 'esMX', 'Tejedor de distorsión Tuviss atiende su negocio en la tienda Simplemente Encantador.', 'Tejedor de distorsión Tuviss atiende su negocio en la tienda Simplemente Encantador.', 25549),
(125464, 'esMX', 'El Talismán de los Shal''dorei rebosa de poder, lo que disipa a los resguardos del palacio.', 'El Talismán de los Shal''dorei rebosa de poder, lo que disipa a los resguardos del palacio.', 25549),
(125463, 'esMX', 'Siéntate y disfruta del espectáculo. Las probabilidades de que puedas hacer algo aparte de morir de forma miserable son nulas.', '', 25549),
(125462, 'esMX', 'Tic-tac, tic-tac. ¡Ya casi estamos listos para el lanzamiento!', '', 25549),
(125461, 'esMX', 'Aquí están.', '', 25549),
(125460, 'esMX', '¡Alto! ¡En nombre del Lord Mekigeniero!', '', 25549),
(125459, 'esMX', 'Listo para el enfrentamiento.', '', 25549),
(125458, 'esMX', 'Ahí estás.', '', 25549),
(125457, 'esMX', 'Los tengo en la mira.', '', 25549),
(125456, 'esMX', 'Sistemas de armamento preparados.', '', 25549),
(125455, 'esMX', 'Un agresor dentro de los vectores de proximidad.', '', 25549),
(125454, 'esMX', 'Detecto bajos niveles de obediencia cerca. Identificando fuente.', '', 25549),
(125453, 'esMX', 'Sensores de amenaza activados.', '', 25549),
(125452, 'esMX', 'Enemigo detectado. Preparando relés de combate.', '', 25549),
(125451, 'esMX', 'Detectando entidad no autorizada cerca.', '', 25549),
(125450, 'esMX', '', 'Tenemos al intruso bajo control. Hazme un favor y ve a ver al Vidente Akalu, ¿quieres, $GDestripador:Destripadora; $n?', 25549),
(125449, 'esMX', 'Intruso detectado en este sector.', '', 25549),
(125448, 'esMX', '¡Lupine Dientengranaje mira en tu dirección!', '', 25549),
(125447, 'esMX', 'Oí algo por aquí.', 'Oí algo por aquí.', 25549),
(125446, 'esMX', '¡No saldrás de aquí con vida!', '¡No saldrás de aquí con vida!', 25549),
(125445, 'esMX', '¡Usaremos tu cabeza para decorar estos salones!', '¡Usaremos tu cabeza para decorar estos salones!', 25549),
(125444, 'esMX', '¿Quién se atreve a ingresar en el territorio de Termochufe?', '¿Quién se atreve a ingresar en el territorio de Termochufe?', 25549),
(125443, 'esMX', 'No estamos solas.', 'No estamos solas.', 25549),
(125442, 'esMX', '¿Viste eso?', '¿Viste eso?', 25549),
(125441, 'esMX', 'Hay alguien cerca.', 'Hay alguien cerca.', 25549),
(125440, 'esMX', '¡Muéstrate en el nombre de Termochufe!', '¡Muéstrate en el nombre de Termochufe!', 25549),
(125439, 'esMX', '¡Sal para yo matar!', '', 25549),
(125438, 'esMX', '¿Qué ahí?', '', 25549),
(125437, 'esMX', '¡Yo ver algo!', '', 25549),
(125436, 'esMX', '¿Qué? ¿Qué es eso?', '', 25549),
(125435, 'esMX', '¡Muéstrate!', '', 25549),
(125434, 'esMX', '¡Trogg no tonto!', '', 25549),
(125433, 'esMX', '¡Esto es inconcebible! Mis cálculos eran... perfectos...', '', 25549),
(125432, 'esMX', 'No hay problema, todo está bien, pequeñín. Solo necesito asesinarte, arreglar estas asquerosas marcas que le has hecho a mi máquina y finalmente podremos acabar con todos tus amigos.', '', 25549),
(125431, 'esMX', 'Vamos, vamos, ¿dónde demonios está el maldito botón de explosión? ¡ESTOY SEGURO DE QUE INSTALÉ UN BOTÓN DE EXPLOSIÓN!', '', 25549),
(125430, 'esMX', 'Y pensar que vas a morir aquí abajo, completamente $gsolo:sola;. Como cuando me dejaron abandonado a mi muerte hace tantos años.', '', 25549),
(125429, 'esMX', 'Tendrás que pelear mucho más fuerte que eso, noble $ghéroe:heroína;. ¡Soy el inventor más grande de todo Azeroth!', '', 25549),
(125428, 'esMX', '¡Contempla el poder que obtengo de mis aliados! Yo, Lord Mekigeniero Termochufe, seré tu fin!', '', 25549),
(125427, 'esMX', 'Debería felicitarte, $Ghéroe:heroína;, pero me temo que tus esfuerzos fueron en vano. ¡Construiré un nuevo misil y esta vez no estarás ahí para detenerme!', '', 25549),
(125426, 'esMX', '', 'Él... llega...', 25549),
(125425, 'esMX', '', '¿Cómo es posible? ¡Eres INSIGNIFICANTE!', 25549),
(125424, 'esMX', '', '¡Tu mundo, todos los mundos, arderán! ¡Es su destino!', 25549),
(125423, 'esMX', '', 'Eres más $gpoderoso:poderosa; de lo que pensaba. No importa.', 25549),
(125422, 'esMX', '', 'Es inútil. Estamos en todas partes. ¡Somos la Legión!', 25549),
(125421, 'esMX', '', 'Llegas demasiado tarde, mortal. El destino de Azeroth está sellado.', 25549),
(125420, 'esMX', '', 'Bien hecho, $Gpequeño gnomo;pequeña gnomo;. ¡Pronto, no quedará nadie capaz de interponerse en el camino de la Legión!', 25549),
(125419, 'esMX', '', 'Las armas están muy dañadas. Si las activamos ahora, podrían destruirnos a nosotros también... Tal vez si desviamos la energía del núcleo del motor principal...', 25549),
(125418, 'esMX', '', '¡Bienvenida a nuestro servicio, Daumyr! Sube, $GSeñor:Señora; de la muerte. Es hora de regresar a Acherus.', 25549),
(125417, 'esMX', '', 'No resistiremos mucho más. ¡Tenemos que destruir esas navessss!', 25549),
(125416, 'esMX', '', 'Estoy impresionada. Renunciar a la Fuente de la Noche no fue fácil.$b$bSu poder y atracción desaparecerán con el tiempo. De algún modo, encontrarán su lugar en el mundo, así como ocurrió con nosotros.', 25549),
(125415, 'esMX', 'La Fuente de la Noche...$b$bCon esto, los natonocturnos comienzan a escribir un nuevo capítulo en la historia de Azeroth. Ahora que se libraron del escudo y de la Fuente de la Noche, podrán empezar a florecer. Estoy ansioso por ver su progreso.', '', 25549),
(125414, 'esMX', 'Es la decisión correcta.$b$bEl poder es muy grande, al igual que la responsabilidad. Incluso Elisande murió a causa de esto. Debemos hacerlo.', '', 25549),
(125413, 'esMX', '', 'Siempre me pregunto qué hubiera pasado si hubiéramos decidido salvar a la Fuente de la Noche. ¿Qué somos sin su poder?$b$bAl final, confío en el juicio de Thalyssra. Sé que los natonocturnos forjarán un nuevo camino bajo su liderazgo.', 25549),
(125412, 'esMX', '', 'La Fuente de la Noche ya no existe.$b$bLos natonocturnos tendrán que aprender a sobrevivir sin su poder corrupto o perecerán. Esperemos que no sea esto último.', 25549),
(125411, 'esMX', '', 'Tenía que ser así. Ya no necesitamos a la Fuente de la Noche ni su poder.$b$bDebemos forjar nuestro propio destino.', 25549),
(125410, 'esMX', '¡Eso fue difícil! Te agradezco la ayuda. ¡Me temo que es posible que Jace esté en problemas en la sala de control!', '', 25549),
(125409, 'esMX', '', 'Hemos perdido Mardum. En mi opinión, un hecho afortunado. Pero creo que sería inconveniente si también perdiéramos el Martillo Vil.', 25549),
(125408, 'esMX', '', '¡$GDestripador:Destripadora; $n, me alegra verte de regreso! ¡Esta vez nos atacan en serio!', 25549),
(125407, 'esMX', '', 'Más demoniossss... Si bien ansiaba algo de emoción a bordo, esssto no era lo que tenía en mente.', 25549),
(125406, 'esMX', '', 'El Martillo vil es NUESTRA nave. ¡Es hora de recordárselo a esos demonios!', 25549),
(125405, 'esMX', '', 'No creas que te enfrentarás a este pico sin mí, $GSeñor:Señora; de la muerte. ¡Vamos!', 25549),
(125404, 'esMX', '', 'Madre Matrona Malevolencia lanza una mirada malévola a Kor''vas.', 25549),
(125403, 'esMX', '', '¡Estoy en camino, madre!', 25549),
(125402, 'esMX', 'Estoy listo, Oculeth.', 'Estoy lista, Oculeth.', 25549),
(125401, 'esMX', '¡Mrg! Mrgrglgrgl gr mrglglrlr!', '', 25549),
(125400, 'esMX', '¡Mrglglg! Mrg grgl grrrrglmrg!', '', 25549),
(125399, 'esMX', '', '¡Quien lo encuentra, sssssse lo queda!', 25549),
(125398, 'esMX', '¡Sus golpes... también son bastante fuertes!', '', 25549),
(125397, 'esMX', '', '¡Demonio apestoso!', 25549),
(125396, 'esMX', 'Estoy listo para entrar al Sagrario.', 'Estoy lista para entrar al Sagrario.', 25549),
(125395, 'esMX', '', '¡Pagarán por haberme metido en esta prisión, criaturas apestosas!', 25549),
(125394, 'esMX', '¡$GDestripador:Destripadora; $n, ayúdame!', '', 25549),
(125393, 'esMX', 'Ya es hora. ¡Hay que penetrar el Sagrario y entrar a la Fortaleza Nocturna!', '', 25549),
(125392, 'esMX', '... de nada.', '', 25549),
(125391, 'esMX', '¡Huye, pequeña! ¡Corre!', '', 25549),
(125390, 'esMX', 'Bueno. Aquí va... ejem...', '', 25549),
(125389, 'esMX', '¡¿Por favor?! ¡Soy una gran admiradora!', '¡¿Por favor?! ¡Soy una gran admiradora!', 25549),
(125388, 'esMX', '¡Oh, vamos!', '¡Oh, vamos!', 25549),
(125387, 'esMX', '¡Ya no hago eso!', '', 25549),
(125386, 'esMX', 'Mmm. No lo sé...', '', 25549),
(125385, 'esMX', '¡Vamos, dilo!', '¡Vamos, dilo!', 25549),
(125384, 'esMX', 'La purificación ha terminado... por ahora. No bajes la guardia, la Legión nunca descansa.', '', 25549),
(125383, 'esMX', 'Roland Abernathy tose con violencia.', '', 25549),
(125382, 'esMX', 'Mmm... pasaron muchos años desde la última vez que mis ojos se posaron en los salones de Ulduar. Quizás debería visitar a los otros vigías ... Tenemos mucho de qué hablar. ¡Adiós!', '', 25549),
(125381, 'esMX', '¡Regocíjense en la victoria, dignos campeones! Ya llegará el día en que necesite de su coraje y habilidad una vez más.', '', 25549),
(125380, 'esMX', '¡Mi antiguo némesis cae derrotado! La maldición que me ata a los Salones del Valor está rota al fin.', '', 25549),
(125379, 'esMX', '¡No nos quedaremos viendo cómo la Legión profana nuestras tierras! ¡Defiendan Farondale!', '', 25549),
(125378, 'esMX', '', '$GDestripador:Destripadora; $n, ¡necesitamos la ayuda de tus gujas filosas para detener a estos demonios!', 25549),
(125377, 'esMX', '¡Los campeones deben demostrar tanto inteligencia como fuerza!', '', 25549),
(125376, 'esMX', '¡Otra prueba! ¡Mantente alerta!', '', 25549),
(125375, 'esMX', '', '|TInterface\\Icons\\SPELL_SHADOW_SHADETRUESIGHT.BLP:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:228565\n|h[Aliento corrupto]|h|r!', 25549),
(125369, 'esMX', '¡Ladrones! ¡Esta nave me pertenece!', '', 25549),
(125363, 'esMX', 'Teletranspórtate a la entrada del palacio.', 'Teletranspórtate a la entrada del palacio.', 25549),
(125362, 'esMX', 'Teletranspórtate a la Fuente Nocturna.', 'Teletranspórtate a la Fuente Nocturna.', 25549),
(125361, 'esMX', 'Teletranspórtate a los cuarteles secretos de Elisande.', 'Teletranspórtate a los cuarteles secretos de Elisande.', 25549),
(125360, 'esMX', 'Teletranspórtate a la Aguja de la Noche.', 'Teletranspórtate a la Aguja de la Noche.', 25549),
(125359, 'esMX', 'El portal brilla con imágenes de la Aguja.', '', 25549),
(125358, 'esMX', 'Oyes abrirse una puerta a lo lejos.', '', 25549),
(125357, 'esMX', '¡Ese es MI tesoro!', '¡Ese es MI tesoro!', 25549),
(125356, 'esMX', 'Ah, hola, $n. Por lo que escuché, parece que pudiste derrotar a Nocturno. Creo que ya era hora de poner a dormir para siempre a ese dragón. Reúne todos los huesos y llévalos al lugar de donde vinieron.', '', 25549),
(125349, 'esMX', 'No sé cómo comenzar a agradecerte por ayudar a rescatarme.$b$bSin tu intervención, no sería más que un ente vacío, viviendo un tormento eterno en la Fuente de la Noche. Ahora... soy libre.$b$bSiempre creí que Thalyssra nos guiaría a nuestra salvación. Ahora tengo la certeza de que los natonocturnos pueden y serán salvados.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125348, 'esMX', 'Estoy listo para el asedio.', 'Estoy lista para el asedio.', 25549),
(125347, 'esMX', 'Nada como un enemigo común para formar un ejército.$b$bHace una semana, estos elfos estaban matándose entre ellos. Ahora, gracias a tus esfuerzos, estamos listos para el asalto final contra la Fortaleza Nocturna.$b$bAunque me gustaría estar al frente, Tyrande insistió en que tú y yo nos quedemos en retaguardia con los Caídos de la Noche. Ven, $Gamigo:amiga; veamos cómo estos elfos resuelven su conflicto.', '', 25549),
(125346, 'esMX', 'Vamos.', 'Vamos.', 25549),
(125345, 'esMX', 'Avísame cuando quieras investigar el hechizo de bloqueo temporal.', '', 25549),
(125344, 'esMX', '', 'Me encantan los portales.', 25549),
(125343, 'esMX', '', 'Arde...', 25549),
(125342, 'esMX', '', '¡Espeluznante!', 25549),
(125341, 'esMX', '', '¡Calor!', 25549),
(125340, 'esMX', '', '¡Arde, insecto, arde!', 25549),
(125339, 'esMX', 'Ah, hola. Estaba haciendo una caminata por aquí y veo que parece que hay un hechizo considerable para los no fantasmas. Quizás con tus limitaciones verticales podamos tratar de limpiar el lugar de la infestación de vermis.', '', 25549),
(125338, 'esMX', '¡Gracias por venir tan rápido, $GDestripador:Destripadora; $n!', '', 25549),
(125337, 'esMX', '', '¡$GDestripador:Destripadora; $n! ¡Nos aborda una plaga de demonios! ¡Necesitamos tu presencia en el Martillo vil!', 25549),
(125336, 'esMX', 'Koren, tengo una entrega de herraduras para ti.', 'Koren, tengo una entrega de herraduras para ti.', 25549),
(125335, 'esMX', 'El can del foso lanza un gruñido siniestro.', '', 25549),
(125334, 'esMX', 'El can del foso percibe algo cerca.', '', 25549),
(125333, 'esMX', 'El Can del foso olfatea el aire.', '', 25549),
(125332, 'esMX', '¿Qué es esto? ¡Ah, al fin llegaron las herraduras que ordené! Momento... ¿Qué es esto? Están hechas trizas. Es como si las hubieran dejado bajo la lluvia durante décadas. Dile a ese "mago" que busque un proveedor nuevo.', '', 25549),
(125331, 'esMX', 'No dejan de aparecer...', 'No dejan de aparecer...', 25549),
(125330, 'esMX', 'Pensé que no lo lograría. ¡Gracias, $n!', 'Pensé que no lo lograría. ¡Gracias, $n!', 25549),
(125329, 'esMX', '¡Eso estuvo cerca! ¡Gracias!', '¡Eso estuvo cerca! ¡Gracias!', 25549),
(125328, 'esMX', '¡Tienes mi agradecimiento!', '¡Tienes mi agradecimiento!', 25549),
(125327, 'esMX', '', 'El archimago Alturus y yo podemos impedir que los refuerzos lleguen a las puertas, pero haz lo que puedas para hacerlos retroceder, $n.$B$BSi sus fuerzas siguen en aumento, puede que no podamos resistir.', 25549),
(125326, 'esMX', 'Las malditas arañas, los murciélagos que chillan sin parar y esas malditas bestias demoníacas han tomado residencia en las alcobas de los sirvientes. Al menos parece que los más grandes desaparecieron.', '', 25549),
(125325, 'esMX', '¡Malditas sean todas esas alimañas! ¿Puedes creer que AÚN siguen aquí? Ese último grupo que se acercó no ayudó para nada. Supongo que no podrías ayudarme con esta situación, ¿verdad?', '', 25549),
(125324, 'esMX', 'Ahora, como antes, debemos hacer lo que corresponde para seguir adelante.', 'Ahora, como antes, debemos hacer lo que corresponde para seguir adelante.', 25549),
(125323, 'esMX', '¿En serio esta fruta curó a Thalyssra? Increíble.', '¿En serio esta fruta curó a Thalyssra? Increíble.', 25549),
(125322, 'esMX', 'Erana-dora isil. Miles de gracias para ti.', 'Erana-dora isil. Miles de gracias para ti.', 25549),
(125321, 'esMX', 'Ya me habías salvado en la ciudad. Ahora esto... Es más de lo que merezco.', 'Ya me habías salvado en la ciudad. Ahora esto... Es más de lo que merezco.', 25549),
(125320, 'esMX', 'Al fin. Estoy listo para ser libre.', 'Al fin. Estoy listo para ser libre.', 25549),
(125319, 'esMX', '¿Puede esto terminar con el hambre?', '¿Puede esto terminar con el hambre?', 25549),
(125318, 'esMX', 'No olvidaremos lo que Thalyssra y tú hicieron por nosotros.', 'No olvidaremos lo que Thalyssra y tú hicieron por nosotros.', 25549),
(125313, 'esMX', '¿Qué es un arcandor? ¿Algún tipo de arca?', '¿Qué es un arcandor? ¿Algún tipo de arca?', 25549),
(125312, 'esMX', 'La señorita Valtrois me dijo que si comía esto me enseñaría sobre las líneas Ley. ¡Me lo prometió!', 'La señorita Valtrois me dijo que si comía esto me enseñaría sobre las líneas Ley. ¡Me lo prometió!', 25549),
(125311, 'esMX', '¿Esto me volverá fuerte como Thalyssra? ¡Es muy buena onda!', '¿Esto me volverá fuerte como Thalyssra? ¡Es muy buena onda!', 25549),
(125310, 'esMX', '¿Puedes sacarle la piel? Es que no me gusta...', '¿Puedes sacarle la piel? Es que no me gusta...', 25549),
(125309, 'esMX', '¡Puaj! ¡Quiero un dulce!', '¡Puaj! ¡Quiero un dulce!', 25549),
(125308, 'esMX', '¡¿Para mí?! ¡Gracias!', '¡¿Para mí?! ¡Gracias!', 25549),
(125307, 'esMX', '¡Sí, fruta mágica!', '¡Sí, fruta mágica!', 25549),
(125304, 'esMX', '', 'Oh, no. No puedo mirar...', 25549),
(125303, 'esMX', '', 'Oh, no. Qué mal...', 25549),
(125302, 'esMX', '', '¡Qué tragedia!', 25549),
(125301, 'esMX', '', '¡Oh, vaya!', 25549),
(125300, 'esMX', '', '¡Cuidado!', 25549),
(125299, 'esMX', '¡Me encontraste justo a tiempo!', '¡Me encontraste justo a tiempo!', 25549),
(125298, 'esMX', '', '¿Me llamaste?', 25549),
(125297, 'esMX', 'No olvidaremos tu amabilidad.', 'No olvidaremos tu amabilidad.', 25549),
(125296, 'esMX', 'Estoy en deuda contigo.', 'Estoy en deuda contigo.', 25549),
(125295, 'esMX', '¿Finalmente soy libre?', '¿Finalmente soy libre?', 25549),
(125294, 'esMX', 'Gracias, $c.', 'Gracias, $c.', 25549),
(125293, 'esMX', 'Quiero hablar sobre la técnica de Ímpetu Arcano.', 'Quiero hablar sobre la técnica de Ímpetu Arcano.', 25549),
(125292, 'esMX', '¿Estás $Gseguro:segura; de que quieres que elimine el conocimiento de Ímpetu Arcano de tus recuerdos?', '¿Estás seguro:segura; de que quieres que elimine el conocimiento de Ímpetu Arcano de tus recuerdos?', 25549),
(125291, 'esMX', '¿Estás seguro de que quieres aprender esta técnica nueva?', '¿Estás segura de que quieres aprender esta técnica nueva?', 25549),
(125290, 'esMX', 'El Ímpetu Arcano es una técnica que permite que los magos usen su ímpetu físico para indicar la dirección a la que quieren trasladarse con su hechizo Traslación en lugar de la técnica básica que solo los traslada hacia la ubicación que tienen enfrente.', 'El Ímpetu Arcano es una técnica que permite que los magos usen su ímpetu físico para indicar la dirección a la que quieren trasladarse con su hechizo Traslación en lugar de la técnica básica que solo los traslada hacia la ubicación que tienen enfrente.', 25549),
(125289, 'esMX', 'Quisiera olvidarme de Ímpetu Arcano y trasladarme hacia la dirección que tengo enfrente.', 'Quisiera olvidarme de Ímpetu Arcano y trasladarme hacia la dirección que tengo enfrente.', 25549),
(125288, 'esMX', 'Quisiera aprender la técnica Ímpetu Arcano y poder trasladarme a la dirección en la que me muevo.', 'Quisiera aprender la técnica Ímpetu Arcano y poder trasladarme a la dirección en la que me muevo.', 25549),
(125286, 'esMX', '', 'Los encontraremos. ¡Y qué hay de Lady S''theno?', 25549),
(125285, 'esMX', '¡Kor''vas, $GDestripador:Destripadora;! La paz reinaba hasta hace poco. ¡De pronto, aparecieron portales de la Legión y tuvimos que pelear por nuestras vidas! Hemos perdido a la mayoría de nuestros exploradores.', '', 25549),
(125284, 'esMX', '', '¡Vandel! Hemos respondido a tu pedido de ayuda. ¿Qué ha pasado?', 25549),
(125282, 'esMX', '¡Dirige al Atracador vil sobre las Minas terrestres para destruirlo!', '', 25549),
(125280, 'esMX', '¡La Bolavolcada verde está de vuelta en la base!', '', 25549),
(125278, 'esMX', '¡La Bolavolcada morada está de vuelta en la base!', '', 25549),
(125276, 'esMX', '¡La Bolavolcada naranja está de vuelta en la base!', '', 25549),
(125275, 'esMX', '¡%s aparece!', '¡Salta sobre el efecto para evitar el daño de |cFFFF0404|Hspell:211901|h[Presión de fusión]|h|r!', 25549),
(125274, 'esMX', '', 'No cuento con mucho tiempo. Este informe será corto, por desgracia.$b$bElisande está furiosa. Planea algo, pero no tengo los detalles aún.$b$bMis ojos y oídos están más abiertos que nunca. En cuanto sepa qué trama, me pondré en contacto.$b$bCuídate.', 25549),
(125273, 'esMX', '', 'Tus nuevos aliados no pasaron desapercibidos.$b$bNo sé de dónde los habrás sacado, pero tuve que disimular mi placer mientras observaba su progreso al infiltrarse en el Paseo.$b$bEl clima aquí se vuelve cada vez más pesado. Los nobles ya no creen que puedan evitar una pelea. Elisande no permitirá que se queden sin hacer nada mientras unos forasteros arrasan con Suramar.$b$bTodavía no cantaría victoria, $Gamigo mío:amiga mía;.$b$bTen cuidado, y no te rindas. Te veré pronto.', 25549),
(125272, 'esMX', '', 'Me alegra mucho saber que Vanthir está a salvo. ¡Dale mis saludos! Espero verlo en persona pronto.$b$bLas cosas se están poniendo... intensas. La demostración del lirio crepuscular alteró un poco a la nobleza. No están de acuerdo en cómo manejar la situación, pero la violencia es casi sin dudas una opción. Me preocupan aquellos que aún se encuentran atrapados en la ciudad.$b$bEscuché el rumor de que hay movimiento en el Paseo... Deben estar reforzando el área. Creo que debemos seguir eso de cerca.$b$bDiré todo lo que sepa cuando tenga más información.', 25549),
(125271, 'esMX', '', 'Como lo pediste, estuve averiguando sobre la situación en el Bastión Almavil. Parece que tus esfuerzos lograron reducir bastante el tráfico. Lamento decir que no se detendrá si no se toman más medidas.$b$bSe dice que quieren deshacerse de los desertores que quedaron luego de los sucesos acaecidos en el Puerto Astravar. Avisa a tu gente que estén atentos. Puede que te encuentres con más desertores.$b$bEn otras noticias, hay una nueva moda que arrasa en el palacio. Sus habitantes están obsesionados con colocarse adornos de aves anaranjadas en la cabeza. Es desconcertante, la verdad.$b$bComo siempre, sigo buscando a nuestro amigo en común. Te informaré directamente tan pronto como sepa algo.$b$bFuerzas, Primera Arcanista.', 25549),
(125270, 'esMX', '¡$n dejó caer la Bolavolcada verde!', '', 25549),
(125269, 'esMX', '¡$n dejó caer la Bolavolcada verde!', '', 25549),
(125268, 'esMX', '¡$n dejó caer la Bolavolcada morada!', '', 25549),
(125267, 'esMX', '¡$n dejó caer la Bolavolcada morada!', '', 25549),
(125266, 'esMX', '¡$n dejó caer la Bolavolcada naranja!', '', 25549),
(125265, 'esMX', '¡$n dejó caer la Bolavolcada naranja!', '', 25549),
(125264, 'esMX', '¡Punto! $n llevó la Bolavolcada verde a la base.', '', 25549),
(125263, 'esMX', '¡Punto! $n llevó la Bolavolcada verde a la base.', '', 25549),
(125262, 'esMX', '¡Punto! $n llevó la Bolavolcada morada a la base.', '', 25549),
(125261, 'esMX', '¡Punto! $n llevó la Bolavolcada morada a la base.', '', 25549),
(125260, 'esMX', '¡Punto! $n llevó la Bolavolcada naranja a la base.', '', 25549),
(125259, 'esMX', '<Ignorar mensaje.>', '<Ignorar mensaje.>', 25549),
(125258, 'esMX', '¡Punto! $n llevó la Bolavolcada naranja a la base.', '', 25549),
(125257, 'esMX', '¡$n ha tomado la Bolavolcada morada!', '', 25549),
(125256, 'esMX', '¡$n ha tomado la Bolavolcada morada!', '', 25549),
(125255, 'esMX', '¡$n ha tomado la Bolavolcada naranja!', '', 25549),
(125254, 'esMX', '¡$n ha tomado la Bolavolcada naranja!', '', 25549),
(125253, 'esMX', '¡$n ha tomado la Bolavolcada verde!', '', 25549),
(125252, 'esMX', '¡$n ha tomado la Bolavolcada verde!', '', 25549),
(125251, 'esMX', '¡Excelente trabajo! Gracias a tu ayuda, ¡la Legión Ardiente jamás se quedará con estas tierras!', '', 25549),
(125250, 'esMX', '<Escucha el quinto mensaje.>', '<Escucha el quinto mensaje.>', 25549),
(125249, 'esMX', '<Escucha el cuarto mensaje.>', '<Escucha el cuarto mensaje.>', 25549),
(125248, 'esMX', '<Escucha el tercer mensaje.>', '<Escucha el tercer mensaje.>', 25549),
(125247, 'esMX', '<Escucha el segundo mensaje.>', '<Escucha el segundo mensaje.>', 25549),
(125246, 'esMX', '<Escucha el primer mensaje.>', '<Escucha el primer mensaje.>', 25549),
(125245, 'esMX', '', 'No hay nada de movimiento aún. Sospecho que Elisande está conforme con el clima actual que se respira en la ciudad. Está tranquilo. Quizás nuestra gente esté muy asustada como para hacerse escuchar luego de la atrocidad que tuvo lugar en el Cuarto Menguante...$b$bNo pude localizar a Vanthir. Es notable cómo se evita su nombre en nuestras discusiones.$b$bComo dato interesante, Elisande es la persona menos puntual que haya tenido la mala fortuna de conocer.$b$bVolveré a informar tan pronto como pueda. Cuídate, Thalyssra.', 25549),
(125244, 'esMX', '', '<La imagen de Ly''leth te mira de cerca con expectación. ¿Te gustaría escuchar el mensaje que tiene para ti?>', 25549),
(125243, 'esMX', 'Elisande trató de ponerme como ejemplo, pero lo único que consiguió fue darle a nuestro movimiento todo el apoyo que necesitaba.$b$bNo puede ser perdonada por sus acciones en el Cuarto Menguante.', '', 25549),
(125242, 'esMX', '¡Cuántas caras conocidas del Cuarto Menguante! Mi corazón se alegra de saber que tantos sobrevivieron.$b$bEn cuanto al resto, solo puedo llorar.', '', 25549),
(125241, 'esMX', 'El Arcan''dor es el futuro de los natonocturnos. Probar la fruta me permitió servir a mi gente como siempre quise... libre del arcavino.', '', 25549),
(125240, 'esMX', 'Te debo la vida, $n. Y mi futuro a Thalyssra.', '', 25549),
(125238, 'esMX', 'Vanthir se esfuerza para ponerse de pie.', '', 25549),
(125237, 'esMX', 'Llévame a la superficie.', 'Llévame a Mardum.', 25549),
(125236, 'esMX', 'Dejaré que te prepares. Controlaré tu progreso a la distancia.', '', 25549),
(125235, 'esMX', 'Buena suerte, $p. Te advierto...  Si abandonas este lugar, perderás todo tu progreso y tendrás que volver a empezar desde el principio.', '', 25549),
(125234, 'esMX', '', 'No necesitas saltar. ¡Nuestros murciélagos viles agradecen cualquier oportunidad de estirar las alas!', 25549),
(125233, 'esMX', 'El aire comienza a calentarse.', 'El aire comienza a calentarse.', 25549),
(125232, 'esMX', 'Puedo sentir el extraño escalofrío de una presencia oscura en el aire...', 'Puedo sentir el extraño escalofrío de una presencia oscura en el aire...', 25549),
(125231, 'esMX', 'Estoy listo para regresar, Kalec.', 'Estoy lista para regresar, Kalec.', 25549),
(125230, 'esMX', 'Lo has logrado, $GArchimago:Archimaga; $n. Me gustaría agradecerte frente a todos en el Salón de la orden.$b$bNos teletransportaremos cuando tú lo indiques.', '', 25549),
(125228, 'esMX', '', '¡Illidari! Nos necesitan en Mardum. ¡Muévanse!', 25549),
(125227, 'esMX', '¿También oíste ese estruendo desde las ruinas de la torre? Seguramente, un mal presagio. ¡Ten cuidado!', '', 25549),
(125226, 'esMX', '¡Estúpido mortal! ¡Este es tu fin!', '', 25549),
(125222, 'esMX', '', 'He aprendido mucho de Silgryn, pero todavía hay mucho que todavía tengo que dominar.$b$bEspero que sea suficiente cuando llegue el momento de enfrentar a Elisande.', 25549),
(125221, 'esMX', '', 'La influencia del grimorio sobre él se ha intensificado en este último tiempo. Se ha vuelto paranoico y obsesivo.', 25549),
(125220, 'esMX', '', '¡$GDestripador:Destripadora; $n! ¡Hemos recibido un mensaje urgente de uno de nuestros exploradores de Mardum!', 25549),
(125219, 'esMX', '¡Cuidado! ¡El lugar se está desmoronando!', '', 25549),
(125218, 'esMX', '¡Y despegamoooooooos!', '', 25549),
(125217, 'esMX', '', 'Cuidado, $c. Es posible que el Archimago no te reciba con el humor jovial que lo caracteriza.', 25549),
(125209, 'esMX', '', '¿Ese es tu mejor golpe? Supongo que los Eredar no se destacan por su habilidad con la espada, ¿no?', 25549),
(125208, 'esMX', 'Un golpe débil y lento. Patético.', 'Un golpe débil y lento. Patético.', 25549),
(125207, 'esMX', '¡Uuh! ¡Brillante! ¿Me lo das?', '', 25549),
(125206, 'esMX', '¿Encontraste algo? ¿Algún objeto mágico? ¡Ey! ¡Dímelo!', '', 25549),
(125205, 'esMX', '¡Ey! ¡¿Encontraste algo bueno?! ¿Algo útil?', '', 25549),
(125204, 'esMX', 'Deseo comerciar.', 'Deseo comerciar.', 25549),
(125203, 'esMX', '¡Hola! ¿Supiste que por fin me pronunciarán mago? Póstumamente, claro..., pero sigue siendo un gran honor.$b$bCon el ascenso llegó una nueva responsabilidad: asear la torre. Hay que dejarla limpia para que luzca un poco más acogedora en caso de que el archimago Khadgar la necesite.', '', 25549),
(125202, 'esMX', '¡Oye, tú! ¿Qué estás haciendo?', '¡Oye, tú! ¿Qué estás haciendo?', 25549),
(125201, 'esMX', '¡ALBÓNDIGA TIENE HAMBRE!', '', 25549),
(125200, 'esMX', 'Esto es una masacre, estamos sufriendo muchas bajas. ¡Se están abriendo portales de la Legión por todas partes! ¡Necesitamos refuerzos!', '', 25549),
(125199, 'esMX', '', 'Lady S''theno fue allí a ayudar hace algunas horas, pero esto parece serio. ¿Deberíamos seguirla?', 25549),
(125198, 'esMX', '', '¡$GDestripador:Destripadora; $n! ¡Hemos recibido un mensaje urgente de uno de los exploradores de Belath en Mardum!', 25549),
(125196, 'esMX', '¡Mezclemos esto!', '', 25549),
(125195, 'esMX', 'Una parte de muerte... dos partes de destrucción...', '', 25549),
(125194, 'esMX', '¡Toma una dosis de esto!', '', 25549),
(125193, 'esMX', 'Un poco de esto... un poco de aquello...', '', 25549),
(125191, 'esMX', 'Mis nuevos aliados me han otorgado dones que van más allá de la razón. Lo único que has logrado es enviar a tu salvador solitario a una muerte segura.', '', 25549),
(125190, 'esMX', 'La vejez te ha hecho delirar, Gelbin.', '', 25549),
(125189, 'esMX', '', '¡Ha pasado taaaanto tiempo desde la última vez me divertí así!', 25549),
(125188, 'esMX', '', '¿A quién engaño? ¡ESTE es mi verdadero yo!', 25549),
(125187, 'esMX', '', 'Supongo que... me merecía esto.', 25549),
(125186, 'esMX', '', 'Siempre... es lo mismo...', 25549),
(125185, 'esMX', '', '¡Apuesto a que te gusto más así!', 25549),
(125184, 'esMX', '', '¡Tú te lo buscaste!', 25549),
(125183, 'esMX', '', 'No hay redención... para mí...', 25549),
(125182, 'esMX', '', 'Qué vergüenza... VERGÜENZA...', 25549),
(125181, 'esMX', '¡No! ¡La falla se está cerrando!', '', 25549),
(125180, 'esMX', '', '¡La virtud está sobrevalorada!', 25549),
(125179, 'esMX', '', 'Purga los oscuros pensamientos de tu mente. ¡Recuerda sus enseñanzas!', 25549),
(125178, 'esMX', '', 'He estado estudiando magia avanzada. ¡Incluso podría aplicar a los Kirin Tor!', 25549),
(125177, 'esMX', '', 'No sé... Creo que extraño los viejos tiempos.', 25549),
(125176, 'esMX', '', '¡Estoy muy contenta de que la doncella nos haya mostrado el camino correcto!', 25549),
(125175, 'esMX', '', 'Ser bueno... no paga...', 25549),
(125174, 'esMX', '', 'Le fallé... a la... doncella...', 25549),
(125173, 'esMX', '', '¡Intenté ser buena... de verdad!', 25549),
(125172, 'esMX', '', '¿Así que quieres jugar? ¡JUGUEMOS!', 25549),
(125171, 'esMX', '', '¡Ya no simpatizo con los de tu especie!', 25549),
(125170, 'esMX', '', 'Oh cielos... ¡Qué tentación!', 25549),
(125169, 'esMX', '', '¡La doncella no lo aprobaría!', 25549),
(125168, 'esMX', '', 'Levia... sí, la conozco. Se hospeda aquí de vez en cuando. La vi por última vez hace algunos días.\n\nLa magia de las sombras es muy peligrosa. Por eso, al Kirin Tor no le agrada que esté en la ciudad. Pero ella incursiona en cosas mucho más peligrosas de lo que acostumbramos ver. Ojalá al menos se encargara de sus asuntos fuera de la ciudad.\n\nPuedes ir arriba a revisar ver si dejó algo que te sirva.', 25549),
(125167, 'esMX', 'Espero que disfrutes mi creación, hermano. Es una pena que tenga que terminar así...', '', 25549),
(125166, 'esMX', 'Las cámaras de la orden contienen una enorme cantidad de dispositivos mágicos. Debe haber algo aquí que pueda ser útil para Dalaran...', '', 25549),
(125165, 'esMX', '¿Sabes dónde puedo encontrar a Levia Laurence?', '¿Sabes dónde puedo encontrar a Levia Laurence?', 25549),
(125164, 'esMX', '¡Tu mente diminuta no es capaz de comprender la fuerza del poder que me espera! Tal vez debería darte una muestra...', '', 25549),
(125163, 'esMX', '¡Hermano, por favor! ¡No dejes que la oscuridad te consuma!', '', 25549),
(125162, 'esMX', 'Llegas demasiado tarde, tonto hermano. ¡El Vacío Abisal me espera y, con él, un poder ilimitado! ¡Cuando regrese, todo Azeroth se arrodillará ante mí!', '', 25549),
(125161, 'esMX', '¡Termina con esta locura, hermano! ¡Aún puedes redimirte!', '', 25549),
(125160, 'esMX', 'Sí, sí, sí, Levia. ¿Una muchacha alta? ¿De cabello claro? Pasó por aquí y compró algunos pergaminos y algo de tinta. Dijo que necesitaba hacer algunas runas para un ritual o algo parecido.\n\nMencionó algo acerca de que necesitaba un tipo de bastón específico, pero nosotros no trabajamos ese tipo de objetos. Le dije que fuera al Místico Militante.\n\nDeberías preguntar ahí.', '', 25549),
(125159, 'esMX', '¿Sabes dónde puedo encontrar a Levia Laurence?', '¿Sabes dónde puedo encontrar a Levia Laurence?', 25549),
(125158, 'esMX', '¡UNO!', '', 25549),
(125157, 'esMX', '¡DOS!', '', 25549),
(125156, 'esMX', '¡TRES!', '', 25549),
(125155, 'esMX', '|cFFFF0000¡Hyrja|r! ¡Salta de nuevo a la batalla!', '|cFFFF0000¡Hyrja|r! ¡Salta de nuevo a la batalla!', 25549),
(125154, 'esMX', '|cFFFF0404¡Hymdall|r! ¡Salta de nuevo a la batalla!', '|cFFFF0404¡Hymdall|r! ¡Salta de nuevo a la batalla!', 25549),
(125153, 'esMX', '¡%s empieza a activarse!', '', 25549),
(125152, 'esMX', '', 'Sígueme arriba, ahí podremos activar este cubo sin compradores curiosos presentes...', 25549),
(125151, 'esMX', '', 'Muy bien, ve y actívalo... Te apoyaré desde una distancia prudente...', 25549),
(125150, 'esMX', '', 'Alguien viene... ¿Quién eres? ¡E... espera! ¡Suéltame! ¿Cómo te atreves? ¡¿Acaso sabes quién soy?!', 25549),
(125149, 'esMX', '', '¡Parece que hay un tipo de brecha que pasa por debajo de la Fuente de la Noche y va al interior del palacio! Están tratando de sellarla, pero estoy segura de que puedes encontrar una manera de...', 25549),
(125148, 'esMX', '¿Es broma?', '', 25549),
(125147, 'esMX', '¡No paren la música!', '', 25549),
(125146, 'esMX', '', 'Miau, miau, miau', 25549),
(125145, 'esMX', '', 'Miau, miau', 25549),
(125144, 'esMX', '¡Activa el cubo!', '¡Activa el cubo!', 25549),
(125143, 'esMX', 'Se prendió, familia.', '', 25549),
(125142, 'esMX', '<El zumbido del cubo genera una sensación de anticipación.>', '', 25549),
(125141, 'esMX', '¡Fórmense!', '', 25549),
(125140, 'esMX', '', 'Un ataque a la entrada principal no es aconsejable, pero puede haber otra manera. Andaris envió a sus arcanistas al Sagrario de la Orden.', 25549),
(125139, 'esMX', '¿Y cómo ser optimista con esto?', '', 25549),
(125138, 'esMX', 'Pero si cierras los ojos...', '', 25549),
(125137, 'esMX', '', 'Elisande nombró a una nueva primera Arcanista: una mujer terrible llamada Andaris. Juntas están trabajando en un encantamiento masivo para romper el asedio.', 25549),
(125136, 'esMX', 'Qué pasa.', '', 25549),
(125135, 'esMX', '', 'Thalyssra, espero que este mensaje te encuentre bien. Acabo de venir de un consejo de emergencia en relación con las fuerzas de la Alianza y la Horda que se acumulan afuera de Suramar.', 25549),
(125134, 'esMX', '', 'Miau.', 25549),
(125133, 'esMX', 'Estos elfos de sangre son aguerridos y disciplinados. Su fuerza será muy útil.', '', 25549),
(125132, 'esMX', '', '¡No paren la música!', 25549),
(125131, 'esMX', '¡Los elfos de la noche utilizan arcos! No creo que se haya fabricado un arco en Suramar, en siglos. Me pregunto si me dejarán usar uno para practicar...', '', 25549),
(125130, 'esMX', 'Es difícil creer que todos somos descendientes de los mismos elfos. Ninguno de nosotros es verdaderamente impermeable al paso del tiempo, parece.', '', 25549),
(125129, 'esMX', 'Se necesitan años para dominar el hechizo-esgrima. Victoire está mejor preparada para instruir a la rebelión en las maniobras marciales básicas.', '', 25549),
(125128, 'esMX', '¡SALVAJE!', '', 25549),
(125127, 'esMX', 'Parece que los tan aclamados Kirin Tor están aquí para verificar que no nos hayamos metido en problemas. Personalmente, me siento mucho más seguro ahora que están aquí. Me pregunto si van a intervenir en caso de que el campamento kaldorei cause algún problema.', '', 25549),
(125126, 'esMX', 'Mmmm. Tus ejércitos son caóticos y desordenados. Afortunadamente nuestros caballeros de sangre y Magisters formarán el núcleo de este asalto para dar un golpe certero en el corazón de la ciudad.', '', 25549),
(125125, 'esMX', 'La Fuente de la Noche. Una fuente inimaginable de poder arcano. ¿Qué le hubiera pasado a los sin''dorei si hubiésemos tenido una fuente así?... $b$bNo importa. Hemos forjado nuestro propio destino. La gloria es nuestra y ya no somos esclavos de nuestra hambre.$b$bEste asedio es una ocasión trascendental, $n. Junto a nuestros parientes perdidos hace tiempo, nuestros enemigos, ahora nos enfrentamos contra algunos de los magos más poderosos del mundo. Nuestras acciones determinarán el futuro de todos los elfos.', '', 25549),
(125124, 'esMX', '¡Me rehúso a rendirme sin dar batalla!', '¡Me rehúso a rendirme sin dar batalla!', 25549),
(125123, 'esMX', '¡Tu decisión no significa nada!', '¡Tu decisión no significa nada!', 25549),
(125122, 'esMX', '¡Tu decisión no significa nada! ¡La Legión Ardiente destruirá a los Mano de plata!', '¡Tu decisión no significa nada! ¡La Legión Ardiente destruirá a los Mano de plata!', 25549),
(125121, 'esMX', 'Respeto tu decisión, $GAlto señor:Alta señora;. Con el tiempo demostraré mi valía.', 'Respeto tu decisión, $GAlto señor:Alta señora;. Con el tiempo demostraré mi valía.', 25549),
(125120, 'esMX', 'Estoy a tu servicio.', 'Estoy a tu servicio.', 25549),
(125119, 'esMX', 'No te arrepentirás de esta decisión.', 'No te arrepentirás de esta decisión.', 25549),
(125118, 'esMX', 'Juro lealtad a los Mano de plata.', 'Juro lealtad a los Mano de plata.', 25549),
(125117, 'esMX', 'Te serviré con honor, $GAlto señor:Alta señora;.', 'Te serviré con honor, $GAlto señor:Alta señora;.', 25549),
(125116, 'esMX', '¡Los resguardos se han disipado! ¡Destrocemos a estos cultistas despreciables!', '', 25549),
(125115, 'esMX', '¡Por aquí, $n!', '', 25549),
(125114, 'esMX', '¡No olvides tu disfraz!', '¡No olvides tu disfraz!', 25549),
(125113, 'esMX', '¡A las armas, jinetes! ¡Encarguémonos del resto!', '', 25549),
(125112, 'esMX', 'Me adelantaré y veré qué puedo encontrar cerca de esta tumba. ¡Te veré en la Costa Quebrada, $n!', '', 25549),
(125111, 'esMX', 'Les devolveremos a los natonocturnos diez veces el daño que le hicieron a nuestro sagrario.', '', 25549),
(125110, 'esMX', 'Tal vez escriba un libro sobre la historia de los elfos de la noche. Su historia es fascinante.', '', 25549),
(125109, 'esMX', 'Estuve hablando con los magos sin''dorei. Me contaron sobre las vastas bibliotecas que hay en sus casas. Me gustaría verlas algún día...', '', 25549),
(125108, 'esMX', 'La Guardia lunar juró proteger la tierra. Aunque nuestros números son pocos, haremos lo que podamos.', '', 25549),
(125106, 'esMX', '¡¿Qué artimaña es esta?!', '', 25549),
(125105, 'esMX', 'Buena suerte.', '', 25549),
(125104, 'esMX', '¡Sí, Manitas Mayor! Estoy bajando la barrera en este instante.', '', 25549),
(125103, 'esMX', 'Capitán Resortinkle, baje la barrera un momento, por favor.', '', 25549),
(125102, 'esMX', '', 'Señor... te he fallado...', 25549),
(125101, 'esMX', '', '¡Conocerán la misericordia de los Jurabisal!', 25549),
(125100, 'esMX', '', 'Necios... ¿de verdad creyeron que sería tan fácil escapar?', 25549),
(125099, 'esMX', '', 'Vi a los centinelas haciendo prácticas de tiro en su campamento. Sí que pueden disparar...$b$b En realidad, nunca usamos el arco. Después de todo, ¿quién necesita este tipo de instrumentos primitivos cuando te pueden diseñar la estructura del mundo para lanzar misiles?', 25549),
(125098, 'esMX', '1, 2, 3, ¡SALTA!', '', 25549),
(125097, 'esMX', '2...', '', 25549),
(125096, 'esMX', '1...', '', 25549),
(125095, 'esMX', '', 'Estos elfos de sangre tienen un poco de magia formidable. Esperemos que sea suficiente para contrarrestar el poder de la Fuente de la Noche.', 25549),
(125094, 'esMX', '', 'La Guardia Umbría es formidable. Necesitaremos a todos los luchadores capaces si queremos cumplir nuestro objetivo.', 25549),
(125093, 'esMX', '¡Desata tu furia, Al''anath, para que nuestros visitantes puedan hacerse más fuertes!', '', 25549),
(125092, 'esMX', '', '¡Archimagos, usen su poder para convencer a estas dos entidades de unirse!', 25549),
(125091, 'esMX', '¡Te invoco, Al''anath Almaescarcha, furia de la tormenta, fragmento del glaciar!', '', 25549),
(125090, 'esMX', 'Nuestros visitantes pondrán a prueba su fuerza en nuestro crisol. ¡Oblígalos, Vis''ileth!', '', 25549),
(125089, 'esMX', 'Vis''ileth, Almamaná, guardián del poder, manifestación de la voluntad, ¡levántate!', '', 25549),
(125088, 'esMX', '¡He esperado más de diez mil años este momento!', '¡He esperado más de diez mil años este momento!', 25549),
(125087, 'esMX', '¡Muere, basura!', '¡Muere, basura!', 25549),
(125086, 'esMX', '¡La Legión Ardiente jamás nos derrotará!', '¡La Legión Ardiente jamás nos derrotará!', 25549),
(125085, 'esMX', '¡Por Nar''thalas!', '¡Por Nar''thalas!', 25549),
(125084, 'esMX', 'Mi muerte... no cambia nada.', 'Mi muerte... no cambia nada.', 25549),
(125083, 'esMX', 'Mis hermanos te asesinarán...', 'Mis hermanos te asesinarán...', 25549),
(125082, 'esMX', 'No puedes detener la sombra...', 'No puedes detener la sombra...', 25549),
(125081, 'esMX', 'Vete de aquí... mientras puedas...', 'Vete de aquí... mientras puedas...', 25549),
(125080, 'esMX', '¡RUIDOS MOLESTOS!', '', 25549),
(125079, 'esMX', 'Coloca bombas arcanas en los portales para destruirlos. ¡Una vez que los portales se cierren, nos encargaremos de exterminar esta infestación!', '', 25549),
(125078, 'esMX', 'Entran demonios a raudales desde los portales de todo el Sagrario en Ruinas. ¡Mis Vigilantes nocturnos quedarán abrumados!', '', 25549),
(125077, 'esMX', '¡Tu intromisión termina aquí!', '¡Tu intromisión termina aquí!', 25549),
(125076, 'esMX', '¡No eres bienvenida aquí, intrusa!', '¡No eres bienvenida aquí, intrusa!', 25549),
(125075, 'esMX', 'La derrota es una oportunidad para el cambio. Regresa cuando tu mente esté concentrada y vuelve a hacer nuestra prueba.', '', 25549),
(125074, 'esMX', '¡Te silenciarán!', '¡Te silenciarán!', 25549),
(125073, 'esMX', 'Nuestra orden se está desvaneciendo, pero te prestaremos la fuerza que tenemos. Vénganos y lleva a la Legión de vuelta a los infiernos de donde vinieron.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125072, 'esMX', '¡Buena pelea! Demostraste que eres una promesa más allá de tus años.', '', 25549),
(125070, 'esMX', '¡Tu intromisión termina aquí!', '¡Tu intromisión termina aquí!', 25549),
(125069, 'esMX', '¡Pon a prueba a nuestros visitantes con todo tu poder, Qui''mar!', '', 25549),
(125068, 'esMX', 'La sombra... se avecina...', 'La sombra... se avecina...', 25549),
(125067, 'esMX', 'No puedes ganar...', 'No puedes ganar...', 25549),
(125066, 'esMX', 'Todos... caerán...', 'Todos... caerán...', 25549),
(125065, 'esMX', 'Jurabisal... venguen mi muerte...', 'Jurabisal... venguen mi muerte...', 25549),
(125064, 'esMX', '¡Su mundo está condenado!', '¡Su mundo está condenado!', 25549),
(125063, 'esMX', '¡Todos caerán ante los Jurabisal!', '¡Todos caerán ante los Jurabisal!', 25549),
(125062, 'esMX', '¡Las sombras te consumen!', '¡Las sombras te consumen!', 25549),
(125061, 'esMX', '¿Por qué debería ayudarte? ¡No vale la pena el riesgo!', '¿Por qué debería ayudarte? ¡No vale la pena el riesgo!', 25549),
(125060, 'esMX', '¡Déjame en paz!', '¡Déjame en paz!', 25549),
(125059, 'esMX', '¡No te diré nada!', '¡No te diré nada!', 25549),
(125058, 'esMX', 'Fuego moldeado, furia derribada. ¡Álzate, Qui''mar, el Alma de fuego!', '', 25549),
(125057, 'esMX', '¡Confiamos en ti! ¿Lo harás?', '', 25549),
(125056, 'esMX', '$p, tienes que escabullirte y evadir a lo que sea que Sicco haya puesto al acecho, desactivar el misil y asesinar al gnomo maldito de una vez por todas.', '', 25549),
(125055, 'esMX', 'No podemos esperar sentados a que lleguen nuestras fuerzas. No tenemos tanto tiempo.', '', 25549),
(125054, 'esMX', '¡Envíame a la Costa Quebrada!', '¡Envíame a la Costa Quebrada!', 25549),
(125053, 'esMX', 'Aquí es donde Danusar dará su discurso épico de convocación. ¡Ahora, escucha a Bolvar y después ve con Mograine escaleras arriba!', '', 25549),
(125052, 'esMX', 'Brillante, una deducción simplemente brillante. Pero me temo que llegas demasiado tarde. ¡Ya casi estamos listos para irradiar a todos sus pequeños y preciados defensores en la Costa Quebrada!', '', 25549),
(125051, 'esMX', '', '¡Señor, tenemos motivos para creer que Termochufe está detrás de todo esto y, aparentemente, tiene una especie de misil en su arsenal!', 25549),
(125050, 'esMX', '¡$GSeñor de la batalla:Señora de la batalla; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125049, 'esMX', '¡$GSeñor Abisal:Señora Abisal; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125048, 'esMX', '¡Clarividente $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125047, 'esMX', '¡Hoja de las sombras $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125046, 'esMX', '¡$GSumo sacerdote:Suma sacerdotisa; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125045, 'esMX', '¡$GAlto señor:Alta señora; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125044, 'esMX', '¡$GGran maestro:Gran maestra; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125043, 'esMX', '¡$GArchimago:Archimaga; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125042, 'esMX', '¡$GMaestro de caza:Maestra de caza; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125041, 'esMX', '¡Archidruida $p! No esperaba encontrarme con $gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125040, 'esMX', '¡$GDestripador:Destripadora; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125039, 'esMX', '¡$GSeñor de la muerte:Señora de la muerte; $p! No esperaba encontrarme con $Gun campeón:una campeona; de la Horda en este preciso lugar. ¡Tu ayuda será muy bienvenida!', '', 25549),
(125038, 'esMX', '¡$GSeñor:Señora; de la guerra $p! ¡No esperaba que la agente Chispacero regresara con $Gel campeón más poderoso:la campeona más poderosa; de la Alianza!', '', 25549),
(125037, 'esMX', '¡$GSeñor:Señora; abisal $p! ¡No esperaba que la agente Chispacero regresara con $Gel campeón más poderoso:la campeona más poderosa; de la Alianza!', '', 25549),
(125036, 'esMX', '¡Clarividente $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125035, 'esMX', '¡Hoja de las Sombras $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125034, 'esMX', '¡$GSumo Sacerdote:Suma Sacerdotisa; $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125033, 'esMX', '¡$GAlto señor:Alta señora; $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125032, 'esMX', '¡$GGran maestro:Gran maestra; $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125031, 'esMX', '¡$GArchimago:Archimaga; $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125030, 'esMX', '¡$GMaestro de caza:Maestra de caza; $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125029, 'esMX', '¡Archidruida $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125028, 'esMX', '¡$GDestripador:Destripadora; $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125027, 'esMX', '¡$GSeñor de la muerte:Señora de la muerte; $p! ¡No esperaba que la agente Chispacero regresara con $Gel máximo campeón:la máxima campeona; de la Alianza!', '', 25549),
(125026, 'esMX', 'Muy bien. Centra tu mente. Se te pondrá a prueba en la tradición de nuestra orden.', '', 25549),
(125025, 'esMX', 'Esto iniciará un evento cronometrado. ¿Estás segura de que quieres comenzar?', 'Esto iniciará un evento cronometrado. ¿Estás segura de que quieres comenzar?', 25549),
(125024, 'esMX', 'Puedes contar conmigo.', 'Puedes contar conmigo.', 25549),
(125023, 'esMX', 'No permitiremos que Gnomeregan vuelva a caer.', '', 25549),
(125022, 'esMX', '|cFF0000FF+$1i oro|r', '|cFF0000FF+$1i oro|r', 25549),
(125021, 'esMX', '|cFFFF0000+$1i oro|r', '|cFFFF0000+$1i oro|r', 25549),
(125020, 'esMX', 'Esto... no cambia... nada...', 'Esto... no cambia... nada...', 25549),
(125019, 'esMX', '¡Estoy impresionada! La mayoría de los mortales habrían muerto tras tocar ese fragmento de alma.', '¡Estoy impresionada! La mayoría de los mortales habrían muerto tras tocar ese fragmento de alma.', 25549),
(125018, 'esMX', '¡Eso es todo lo que sé, lo juro!', '¡Eso es todo lo que sé, lo juro!', 25549),
(125017, 'esMX', 'Uno de ellos me dio este papiro. Tómalo, ¡no quiero tener nada que ver con su culto!', 'Uno de ellos me dio este papiro. Tómalo, ¡no quiero tener nada que ver con su culto!', 25549),
(125016, 'esMX', '¡Jamás conocerás nuestros secretos!', '¡Jamás conocerás nuestros secretos!', 25549),
(125015, 'esMX', '¡Juro que no sé nada! ¡Déjame en paz!', '¡Juro que no sé nada! ¡Déjame en paz!', 25549),
(125014, 'esMX', 'Ven, tenemos que detener al señor del foso antes de que descubra a Shal''Aran.', '', 25549),
(125013, 'esMX', 'Guíanos hacia Los Bajos Fondos, $n. Esperemos que no sea demasiado tarde.', '', 25549),
(125012, 'esMX', '', '|TInterface\\Icons\\inv_misc_monsterhorn_03.blp:20|t ¡Aparece un %s lejos de Helya!', 25549),
(125011, 'esMX', '¡$GArchimago:Archimaga; $n, tenemos una visita. ¡Ven a mi cuartel privado de inmediato!', '', 25549),
(125010, 'esMX', 'La sombra... lo consume todo...', 'La sombra... lo consume todo...', 25549),
(125009, 'esMX', '¡Nadie podrá detener el regreso de los Jurabisal!', '¡Nadie podrá detener el regreso de los Jurabisal!', 25549),
(125008, 'esMX', '¡Estúpidos mortales! Este asalto insignificante fracasará tal como el anterior... ¡y esta vez no lograrán escapar!', '', 25549),
(125007, 'esMX', '¡Háganlos retroceder! ¡Hoy no nos vencerán!', '', 25549),
(125006, 'esMX', '¡Tonto mortal! ¿Cómo te atreves a liberar a nuestros prisioneros? ¡Tú ocuparás su lugar!', '', 25549),
(125005, 'esMX', '', 'Si el teletransportador deja de funcionar, necesitaremos una |Hitem:143653:0:0:0:0:0:0:0:90:0|h[Piedra angular rebosante]|h para activarlo. ¡Métete apenas estés listo!', 25549),
(125004, 'esMX', '', '¡Lo logramos!', 25549),
(125003, 'esMX', '¡Xylem activa el Iris de enfoque!', '¡Xylem activa el Iris de enfoque!', 25549),
(125002, 'esMX', '', 'Te enviaré a las profundidades de la ciudad. El atenuador sólo tiene potencia para llevarnos una vez. ¡No podemos desperdiciar la oportunidad!', 25549),
(125001, 'esMX', '', 'Calibrando fluctuadores de hipervoltaje... ajustando microacelerador...', 25549),
(125000, 'esMX', '', '¡Necesitamos que llegues a Gnomeregan lo antes posible!', 25549),
(124999, 'esMX', 'Sabía que podía contar contigo. Si nuestras fuerzas están divididas y expulsan a la Horda del Kirin Tor, nada podrá impedir que la Legión consuma a nuestro mundo.', '', 25549),
(124998, 'esMX', 'Solo tú y mis tenientes más confiables. Pero no sé por cuánto tiempo más podremos mantenerlo en secreto.', '', 25549),
(124997, 'esMX', 'Invocaré un portal. ¡Nos vemos del otro lado, $GArchimago:Archimaga; $n!', '', 25549),
(124996, 'esMX', '¡Cuidado! ¡Se acerca un señor de la calamidad!', '', 25549),
(124995, 'esMX', 'Estado de terminal: desprotegido. Apagando.', '', 25549),
(124994, 'esMX', '¡Mantengan la formación! ¡$GEl Destripador:La Destripadora; ha llegado!', '', 25549),
(124993, 'esMX', '¡Mantengan la formación! ¡$GEl Archidruida:La Archidruida; ha llegado!', '', 25549),
(124992, 'esMX', '¡Mantengan la formación! ¡$GEl Gran maestro:La Gran maestra; ha llegado!', '', 25549),
(124991, 'esMX', '¡Mantengan la formación! ¡$GEl Señor abisal:La Señora abisal; ha llegado!', '', 25549),
(124990, 'esMX', '¡Mantengan la formación! ¡$GEl Archimago:La Archimaga; ha llegado!', '', 25549),
(124989, 'esMX', '¡Mantengan la formación! ¡$GEl Clarividente:La Clarividente; ha llegado!', '', 25549),
(124988, 'esMX', '¡Mantengan la formación! ¡$GEl Señor de la muerte:La Señora de la muerte; ha llegado!', '', 25549),
(124987, 'esMX', '¡Mantengan la formación! ¡$GEl Sumo sacerdote:La Suma sacerdotisa; ha llegado!', '', 25549),
(124986, 'esMX', '¡Mantengan la formación! ¡La Hoja de las sombras ha llegado!', '', 25549),
(124985, 'esMX', '¡Mantengan la formación! ¡$GEl Maestro de caza:La Maestra de caza; ha llegado!', '', 25549),
(124984, 'esMX', '¡Mantengan la formación! ¡$GEl Alto señor:La Alta señora; ha llegado!', '', 25549),
(124983, 'esMX', '¡Mantengan la formación! ¡$GEl Señor de la batalla:La Señora de la batalla; ha llegado!', '', 25549),
(124982, 'esMX', '', '¡¿Que tú QUÉ?!', 25549),
(124981, 'esMX', 'Tengo clientes por todas partes, Kels. ¿Por qué tendría que saber algo sobre un granuja de Gnomeregan?', '', 25549),
(124980, 'esMX', 'Activando módulo de protección de terminal 3B.', '', 25549),
(124979, 'esMX', 'Estado del sistema: Iniciando.', '', 25549),
(124978, 'esMX', '¡Ah, sí! ¡Finalmente el poder de Azeroth es MÍO!', '', 25549),
(124977, 'esMX', '$GEl Archimago:La Archimaga; $n y yo intentaremos reparar las armas de Dalaran. ¡Tenemos que hacerlo!', '', 25549),
(124976, 'esMX', 'Si esta noticia sale a la luz, la tregua llegará a su fin. ¿Quién más está enterado?', '', 25549),
(124975, 'esMX', 'Es terrible. Los traidores pertenecían a la Horda...', '', 25549),
(124974, 'esMX', '-- CINEMÁTICA -- La cámara se desplaza por la Costa Quebrada y revela una cantidad innumerable de demonios. La Tumba de Sargeras aparece en el fondo. Se oye la voz de Khadgar que dice... "Es posible que el destino de nuestro mundo se decida este día".', '', 25549),
(124973, 'esMX', '¡Hay un cable delgado muy tirante atado a la carta!', '¡Hay un cable delgado muy tirante atado a la carta!', 25549),
(124966, 'esMX', 'Buena suerte, camarada. ¡Los desiertos de Tanaris no tienen compasión!', '', 25549),
(124965, 'esMX', '¡Aquí no encontrarás recompensa alguna, tan solo muerte!', '¡Aquí no encontrarás recompensa alguna, tan solo muerte!', 25549),
(124964, 'esMX', '¡Los visitantes están prohibidos!', '¡Los visitantes están prohibidos!', 25549),
(124963, 'esMX', 'Al fin... libre.', 'Al fin... libre.', 25549),
(124962, 'esMX', 'Es hora de seguir adelante.', 'Es hora de seguir adelante.', 25549),
(124956, 'esMX', '', 'Sí, ¿qué quieres?', 25549),
(124955, 'esMX', 'Voy a abrir el camino. Mientras luchas contra ese Maligno, voy a romper la conexión de la torre a los mundos de la Legión. ¡Sugiero que lo hagamos rápido!', '', 25549),
(124954, 'esMX', '¿Medivh?', '', 25549),
(124953, 'esMX', 'Tenemos mucho de qué hablar, $GSeñor:Señora; de la batalla $n. ¡Ven de inmediato! No hay tiempo que perder.', '', 25549),
(124952, 'esMX', '¡Hagamos a un lado nuestras insignificantes diferencias y ataquemos juntos a la Legión! ¡Debemos unir a todas las fuerzas más poderosas de Azeroth!', '', 25549),
(124951, 'esMX', 'He dejado muchos fragmentos de mí mismo por toda esta torre...', '', 25549),
(124950, 'esMX', 'Bien. Terminen con los preparativos y diríjanse hacia la Costa Quebrada lo antes posible.', '', 25549),
(124947, 'esMX', 'También podríamos usar a los kvaldir en nuestro frente de batalla. Sus vidas ya están perdidas, así que no sería mala idea usarlas contra la Legión.', '', 25549),
(124943, 'esMX', '¡$GSeñor de la batalla:Señora de la batalla;! Ahora que esa despreciable bruja Helya está derrotada, ¡ya no podrá impedir que reclame lo que me pertenece!', '', 25549),
(124939, 'esMX', '¡Como ordene mi maestra!', '¡Como ordene mi maestra!', 25549),
(124938, 'esMX', '¡No puedo... resistir!', '¡No puedo... resistir!', 25549),
(124937, 'esMX', 'Obedezco.', 'Obedezco.', 25549),
(124936, 'esMX', '¡Por la Legión!', '¡Por la Legión!', 25549),
(124935, 'esMX', '¡Como ordene mi maestra!', '¡Como ordene mi maestra!', 25549),
(124934, 'esMX', 'Se habrían convertido en Valarjar hace mucho tiempo si Helya no se los hubiera llevado. ¡Ahora, sé testigo de su transformación!', '', 25549),
(124933, 'esMX', 'Muy bien, $GSeñor de la batalla:Señora de la batalla;, $n. ¡Has recuperado los guerreros que me habían robado!', '', 25549),
(124932, 'esMX', '<Recuerda la confrontación entre la Jefa de Guerra Sylvanas y Genn Cringris.>', '<Recuerda la confrontación entre la Jefa de Guerra Sylvanas y Genn Cringris.>', 25549),
(124931, 'esMX', '<Recuerda la trascendencia de Ysera.>', '<Recuerda la trascendencia de Ysera.>', 25549),
(124930, 'esMX', '<Recuerda la corrupción de Ysera.>', '<Recuerda la corrupción de Ysera.>', 25549),
(124929, 'esMX', '<Recuerda tu primera visita a Suramar.>', '<Recuerda tu primera visita a Suramar.>', 25549),
(124928, 'esMX', '<Recuerda la historia de la tentación de Khadgar.>', '<Recuerda la historia de la tentación de Khadgar.>', 25549),
(124927, 'esMX', '<Recuerda la historia de los Illidari de Illidan.>', '<Recuerda la historia de los Illidari de Illidan.>', 25549),
(124926, 'esMX', '<Recuerda la historia de Gul''dan.>', '<Recuerda la historia de Gul''dan.>', 25549),
(124925, 'esMX', '<Recuerda la ascensión de la Jefa de Guerra Sylvanas.>', '<Recuerda la ascensión de la Jefa de Guerra Sylvanas.>', 25549),
(124924, 'esMX', '<Recuerda la retirada de la Costa Quebrada.>', '<Recuerda la retirada de la Costa Quebrada.>', 25549),
(124923, 'esMX', '<Recuerda la muerte del Rey Varian Wrynn.>', '<Recuerda la muerte del Rey Varian Wrynn.>', 25549),
(124922, 'esMX', '<Recuerda tu encarcelamiento en la Bóveda de las Celadoras.>', '<Recuerda tu encarcelamiento en la Bóveda de las Celadoras.>', 25549),
(124921, 'esMX', '<Recuerda tu misión a Mardum.>', '<Recuerda tu misión a Mardum.>', 25549),
(124920, 'esMX', '<Recuerda el fallecimiento de Illidan.>', '<Recuerda el fallecimiento de Illidan.>', 25549),
(124919, 'esMX', '<Recuerda el navío vinculado a la luz.>', '<Recuerda el navío vinculado a la luz.>', 25549),
(124918, 'esMX', '<Una presencia que emana del cubo insta a tu mente a pensar de nuevo en tus experiencias en las Islas Quebradas.>', '', 25549),
(124917, 'esMX', '¿Era el mismo Sicco Termochufe al que le vendí la mira computarizada? Vaya puntería...', '', 25549),
(124916, 'esMX', '<Contarle a Mux lo que aprendiste en el campamento de Termochufe.>', '<Contarle a Mux lo que aprendiste en el campamento de Termochufe.>', 25549),
(124915, 'esMX', 'Salgamos de aquí.', 'Salgamos de aquí.', 25549),
(124914, 'esMX', '', 'No te demores demasiado tiempo aquí, $ct $n. Este horrible lugar hace decaer mi voluntad con cada paso que doy.', 25549),
(124913, 'esMX', '¡La gravedad se desvanecerá en 15 segundos!', '¡La gravedad se desvanecerá en 15 segundos!', 25549),
(124912, 'esMX', 'Ah, sí, olvidé mencionarlo. Esta terminal se autodestruirá en tan solo uuun momento. ¡Adiós!', '', 25549),
(124911, 'esMX', 'asdf', 'sdf', 25549),
(124910, 'esMX', 'Por supuesto, siempre que sobrevivas a la radiación masiva de la Costa Quebrada y a la subsiguiente marcha gloriosa de la Legión sobre todo lo que aprecias.', '', 25549),
(124909, 'esMX', '¡Si estás oyendo este mensaje, es porque te has ganado una invitación exclusiva a mi gloriosa coronación como rey de todos los mortales de Azeroth!', '', 25549),
(124908, 'esMX', '¡Saludos, habitante de la superficie! ¡Soy yo, el único, el inigualable, Mekigeniero Lord Termochufe!', '', 25549),
(124907, 'esMX', 'Quita la tarjeta perforada con cuidado.', 'Quita la tarjeta perforada con cuidado.', 25549),
(124906, 'esMX', '¡NO, NO, NO, NO, NO, NO, NO, ARRGGGH!', '', 25549),
(124905, 'esMX', '¡Aaahh, ahora sí que estoy enfadado!', '', 25549),
(124904, 'esMX', '', 'No me vieron llegar. Una sola hoja que golpea desde las sombras pasa inadvertida y, así, se abre una grieta en su defensa.', 25549),
(124903, 'esMX', '¡Uf! Con que quieres pelear sucio, ¿eh? ¡Muy bien, a ver si interrumpes esto!', '', 25549),
(124902, 'esMX', '', '<Estos deben ser los restos del último asistente de Grux.>$B$B<Notas algo que sobresale apenas entre las cenizas. ¡Debe ser la tarjeta perforada que ella estaba intentando devolver!>', 25549),
(124901, 'esMX', '<Has visto escritos como este en manos de la Legión antes. El Consejo de los Seis tenía razón en desconfiar de sus agentes.>', '', 25549),
(124900, 'esMX', '<Este helicóptero se utiliza normalmente como ayudante en talleres de ingeniería. Su estado deja mucho que desear.>', '', 25549),
(124899, 'esMX', 'Contaban con toda la "maestría de lo arcano" y todavía no estaban preparados para una piroexplosión en la cara. Casi siento pena por ellos. Casi.', '', 25549),
(124898, 'esMX', 'Inserta la tarjeta perforada.', 'Inserta la tarjeta perforada.', 25549),
(124897, 'esMX', '<La máquina hace un clic acompasado mientras está inactiva.>', '', 25549),
(124896, 'esMX', '<Adviertes una ranura en la superficie del dispositivo donde podría entrar la tarjeta perforada que mencionó Mux.>$B$B', '', 25549),
(124895, 'esMX', 'Examinar baliza', 'Examinar baliza', 25549),
(124894, 'esMX', '', 'Arluelle coloca una flor púrpura oscura frente a la pequeña maceta.', 25549),
(124892, 'esMX', 'Estos vrykul deben pagar por profanar mi ciudadela. ¡Acábalos! ¡Y resucítalos en nombre del Rey Exánime!', '', 25549),
(124891, 'esMX', 'Vas en busca del arnés de Dientefrío, pero has demorado demasiado. Ha caído en manos de los invasores vrykul, que ahora lo usan para someter a los vermis de escarcha a su voluntad.', '', 25549),
(124890, 'esMX', 'Bajo tus órdenes, los Cuatro Jinetes han sembrado el caos entre los demonios. Pero ahora nos espera otro camino hacia el poder.', '', 25549),
(124889, 'esMX', 'Me complace decir que tu campaña contra la Legión ha tenido una eficacia brutal, $GSeñor de la muerte:Señora de la muerte;.', '', 25549),
(124888, 'esMX', 'Contigo como líder, $ct, la Legión no tiene ninguna posibilidad.', '', 25549),
(124887, 'esMX', 'Las afueras de la gran y antigua ciudad de Suramar, donde la lucha de los caídos de la noche por sobrevivir y la corrupción se arrastran tan suavemente...', '', 25549),
(124886, 'esMX', '', 'Regresaré a la Falla Cicatriz Aterradora e informaré a los demás miembros del consejo sobre nuestro plan.', 25549),
(124885, 'esMX', '', 'Bien, creo que podemos decir que este ya no nos sirve. ¿Verdad?', 25549),
(124884, 'esMX', 'Tal vez si su actuación hubiera sido menos transparente, ¡no estaríamos sin trabajo!', '', 25549),
(124883, 'esMX', '', '¡Uff! ¡Es tan insoportable! Qué idiota.', 25549),
(124882, 'esMX', 'En realidad soy bastante inteligente, te lo demostraré.', '', 25549),
(124881, 'esMX', 'Obviamente, no estuve realmente *asustado* todo ese tiempo en el escenario. Simplemente soy un buen actor. De Verdad.', '', 25549),
(124880, 'esMX', 'No le digas a los otros miembros del reparto, pero me alegra que estemos en receso; ¡me preocupaba ser encasillado en el hombre con traje de metal durante toda mi carrera!', '', 25549),
(124879, 'esMX', 'Nos adelantaremos para explorar la zona. ¡Nos vemos en el campo de batalla, $GSeñor de la muerte:Señora de la muerte;!', '', 25549),
(124878, 'esMX', '¡Ja! No tienen la más mínima posibilidad.', '', 25549),
(124877, 'esMX', '', '¡Solo con su muerte podremos alcanzar la expiación!', 25549),
(124876, 'esMX', 'La Legión no tiene honor. Eso los llevará a su fin.', '', 25549),
(124875, 'esMX', '', '¿Esperaban que las llamara "mis bonitas"? ¿Y que hiciera algunos torbellinos? Es lo que llaman *actuación*, mis queridas.', 25549),
(124874, 'esMX', '', '$gQuerido:Querida;, estoy tan contenta de verte. ¿Trajiste rosas?', 25549),
(124873, 'esMX', '', '¡La gente ya ni siquiera reconoce a una verdadera ingenua! Todo es tan... trágico.', 25549),
(124872, 'esMX', '¡Excelente trabajo, héroe! ¡Nuestra alianza asegura que Azsuna jamás caerá ante la Legión!', '', 25549),
(124871, 'esMX', '', 'Todos se enloquecen por estos relatos tan "inteligentes". ¡Ya nadie aprecia los clásicos!', 25549),
(124870, 'esMX', '', 'Está bien, $gquerido:querida;. No necesito a nadie para que me ayude a repasar el libreto; ya lo tengo muy bien memorizado.', 25549),
(124869, 'esMX', '', 'Alguna vez él ocupó tu posición, $GSeñor abisal:Señora abisal;. Kanrethad fue el fundador de nuestro consejo.\n\nNos unió a todos, a pesar de nuestras diferencias, y nos guio en la búsqueda del poder más fuerte que conocimos jamás.\n\nSin embargo, para él nunca era suficiente. Tras la desaparición de Illidan en el Templo Oscuro, Kanrethad se obsesionó con los poderes que había presenciado en ese lugar. Quería controlar a las energías demoníacas tal como lo hacía Illidan, y estaba dispuesto a hacerlo a cualquier costo.\n\nLe prometí a Kanrethad que lo desterraría si cedía ante los poderes que intentaba controlar. Debo cumplir esa promesa, por su bien y por el de todos los demás.', 25549),
(124868, 'esMX', 'Monta a Daumyr una vez más, $GSeñor de la muerte:Señora de la muerte; y guíanos hacia la batalla.', '', 25549),
(124867, 'esMX', '¿Quién es Kanrethad?', '¿Quién es Kanrethad?', 25549),
(124866, 'esMX', '', '¡Debemos asegurarnos de que Kanrethad permanezca desterrado, cueste lo que cueste!', 25549),
(124865, 'esMX', '', 'Debo admitir, que tengo mucha curiosidad de explorar el mundo más allá de Suramar.$B$B¡Las culturas primitivas siempre me han fascinado!', 25549),
(124864, 'esMX', 'Todavía estás a tiempo de unirte a nosotros...', 'Todavía estás a tiempo de unirte a nosotros...', 25549),
(124863, 'esMX', '', 'Se siente tan bien ser yo misma de nuevo. $B$B<Valtrois pasa el dorso de la mano suavemente por su pómulo.>$B$BComo puedes ver, ¡el maná es maravilloso para la piel!', 25549),
(124862, 'esMX', '', 'Nunca me di cuenta de lo mucho que necesitamos la Fuente de la Noche. Deshacerse de su llamado es... liberador.', 25549),
(124861, 'esMX', '¡No estás a la altura de su poder!', '¡No estás a la altura de su poder!', 25549),
(124860, 'esMX', '¡Las llamas viles te consumirán!', '¡Las llamas viles te consumirán!', 25549),
(124859, 'esMX', '¡Arderás!', '¡Arderás!', 25549),
(124858, 'esMX', '¡La verdadera líder de la Cosecha Oscura se alzará una vez más!', '¡La verdadera líder de la Cosecha Oscura se alzará una vez más!', 25549),
(124857, 'esMX', '¡Kanrethad, concédeme tu poder!', '¡Kanrethad, concédeme tu poder!', 25549),
(124856, 'esMX', '¡$GNuestro:Nuestra; líder regresará!', '¡$GNuestro:Nuestra; líder regresará!', 25549),
(124855, 'esMX', '¡No nos detendrán!', '¡No nos detendrán!', 25549),
(124854, 'esMX', '¡Te he fallado, Kanrethad!', '¡Te he fallado, Kanrethad!', 25549),
(124853, 'esMX', '¡Esto... no puede ser!', '¡Esto... no puede ser!', 25549),
(124852, 'esMX', 'Mi muerte no será en vano.', 'Mi muerte no será en vano.', 25549),
(124851, 'esMX', '', '¡Pronto, Kanrethad estará entre nosotros una vez más!', 25549),
(124850, 'esMX', '', '¡Llegas demasiado tarde! El ritual ya está casi completo.', 25549),
(124849, 'esMX', '<Colócale una venda a la matriarca herida.>', '<Colócale una venda a la matriarca herida.>', 25549),
(124848, 'esMX', '', '<La matriarca herida se había mantenido oculta hasta que olió a su prole perdida, aunque está demasiado herida para cuidar de ella.>', 25549),
(124847, 'esMX', '<Ecos del pasado pasan por tu mente. Visiones aparecen lentamente al principio, pero pronto comienzan a parpadear rápidamente dentro y fuera de la realidad.$B$BControlando tu mirada, posas la vista directo sobre los ojos del Fragmento de Medivh. Mundos lejanos aparecen, luego se desvanecen rápidamente en la oscuridad.>', '', 25549),
(124846, 'esMX', 'Quiero saber el destino de Karazhan.', 'Quiero saber el destino de Karazhan.', 25549),
(124845, 'esMX', '¿Qué le pasó a la torre?', '¿Qué le pasó a la torre?', 25549),
(124844, 'esMX', '<Susurros nublan tu mente. Tus pensamientos se vuelven erráticos.>', '', 25549),
(124843, 'esMX', 'Entrarás en combate poco después de salir.\n\nRecomendamos que primero te tomes un momento para revisar la configuración de tu libro de hechizos de tu barra de acciones.\n\n¿Estás $Glisto:lista; para partir?', 'Entrarás en combate poco después de salir.\n\nRecomendamos que primero te tomes un momento para revisar la configuración de tu libro de hechizos de tu barra de acciones.\n\n¿Estás listo:lista; para partir?', 25549),
(124841, 'esMX', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:227573|h[Aliento del guardián]|h|r!', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:227573|h[Aliento del guardián]|h|r!', 25549),
(124832, 'esMX', 'Por aquí, Arluelle.', 'Por aquí, Arluelle.', 25549),
(124831, 'esMX', '', 'Mucho ha cambiado para mí desde que trajiste esa fruta.$b$bExtraño mucho a mi hermano, pero sé por qué se ofreció para esta causa.$b$bDebo pedirte algo. Debo recompensar a los otros por su amabilidad.$b$bPor favor, llévame con la primera arcanista para que pueda unirme a su causa.', 25549),
(124830, 'esMX', 'Esto dolerá, $pc.', 'Esto dolerá, $pc.', 25549),
(124829, 'esMX', '', 'Araña a ese.', 25549),
(124828, 'esMX', '', '¡Es un frenesí emplumado!', 25549),
(124827, 'esMX', '', '¡Lánzate!', 25549),
(124826, 'esMX', '', '¡Ganaste contra todo pronóstico!', 25549),
(124825, 'esMX', '', '¡Sigue así, te irá mejor la próxima!', 25549),
(124824, 'esMX', '', '¡La justicia cae del cielo!', 25549),
(124823, 'esMX', '', 'La Jefa de Guerra me otorgó este puesto para estudiar a las aves de la región, para que podamos usarlas de mejor manera al llevar mensajes a larga distancia. Con una ubicación tan central cerca de las zonas de comercio de la Horda, pude conseguir una gran cantidad de especies exóticas. ¿Quieres poner a prueba tu suerte contra ellas?', 25549),
(124821, 'esMX', 'La Legión está drenando la magia de nuestros dragones. ¡Tienes que rescatarlos!', '', 25549),
(124820, 'esMX', 'Corrió tan rápido como pudo. Me quedaré con él hasta que le llegue la hora.$b$bGracias... por todo. No hay nada más que nosotros podamos hacer.', '', 25549),
(124819, 'esMX', '', 'Para poder liberar a nuestros aliados, ¡esta monstruosidad debe ser destruida!', 25549),
(124818, 'esMX', '', 'Fibras de poder emanan de la aberración. Creo que Elisande está usando a esta criatura para mantener el hechizo de bloqueo temporal.', 25549),
(124817, 'esMX', '', 'Desde aquí, tenemos acceso a los terrenos del palacio. ¡Podemos abrir las puertas desde adentro!', 25549),
(124816, 'esMX', '', '¡El bloqueo temporal está roto! ¡Son libres!', 25549),
(124815, 'esMX', 'Un excelente plan. Buena suerte, héroes.', '', 25549),
(124814, 'esMX', 'Sin duda nuestras fuerzas quedarán desorientadas. Les informaré lo que ocurrió y me aseguraré de que estén listos para continuar con el ataque.', '', 25549),
(124813, 'esMX', '', '%s te indica que no te separes.', 25549),
(124812, 'esMX', '', 'Creo que debajo de toda su locura, todavía existe el hombre amable y bondadoso que alguna vez fue el Archimago Xylem.', 25549),
(124811, 'esMX', '', 'Tengo un último pedido, $c. Si bien es posible que Xylem no se de por vencido, perdónale la vida.', 25549),
(124810, 'esMX', '', 'Tomará algo de tiempo, pero quizá nos sirva para alcanzarlo.', 25549),
(124809, 'esMX', '', 'Su portal es inestable, pero aún quedan resabios.', 25549),
(124804, 'esMX', 'Uff. Si no van a presentar nuestro espectáculo pronto, ¡¿para qué tengo que seguir usando este traje?! Me da picazón...', '', 25549),
(124803, 'esMX', 'Debes seguirlo a través de su portal. ¡Rápido! ¡Antes de que sea demasiado tarde!', '', 25549),
(124802, 'esMX', 'Parece que el grimorio se apoderó de mi mente, tal como lo hizo con Xylem... ¡y ahora ha escapado con el Iris!', '', 25549),
(124801, 'esMX', '¡Suficiente! ¡Baja el arma!', '', 25549),
(124800, 'esMX', '¡Llegas demasiado tarde! Aprendiz Sanath, encárgate de mi $gperseguidor:perseguidora;.', '', 25549),
(124799, 'esMX', 'Mmm... eres bastante fuerte, ¿verdad? Pensándolo mejor, ¡no intentes detenerme!', '', 25549),
(124798, 'esMX', '¡El Iris de enfoque me convertirá en el mago más poderoso de todos los tiempos! ¡No se atrevan a detenerme!', '', 25549),
(124797, 'esMX', 'Xylem... ¿Qué has hecho?', 'Xylem... ¿Qué has hecho?', 25549),
(124796, 'esMX', 'La sombra... ¿desapareció?', 'La sombra... ¿desapareció?', 25549),
(124795, 'esMX', 'La sombra... nos consumió...', 'La sombra... nos consumió...', 25549),
(124794, 'esMX', 'Casi... me desvanezco...', 'Casi... me desvanezco...', 25549),
(124793, 'esMX', '¿Dó... dónde estoy?', '¿Dónde... dónde estoy?', 25549),
(124792, 'esMX', '¡Vas a tener que entrenar más duro!', '¡Vas a tener que entrenar más duro!', 25549),
(124791, 'esMX', '¡No, no, no! ¡Tu forma está mal!', '¡No, no, no! ¡Tu forma está mal!', 25549),
(124790, 'esMX', '¡Jamás podrás derrotar a la Legión con esos movimientos!', '¡Jamás podrás derrotar a la Legión con esos movimientos!', 25549),
(124789, 'esMX', 'Aprendisantes... ¡Ataquen!', '', 25549),
(124788, 'esMX', 'Un momento... ¡Tú no eres $gun aprendiz:una aprendiz; de verdad! ¡Toma esto, $gimpostor:impostora;!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(124787, 'esMX', 'Ten cuidado. Las respuestas incorrectas son nocivas para la salud. Y estoy hablando literalmente.', '', 25549),
(124786, 'esMX', 'Un gran esfuerzo... pero  también un completo y rotundo fracaso.', '', 25549),
(124785, 'esMX', '¿Estás tratando de... superar la barrera por la fuerza? ¡Eso NO es lo que te enseñé!', '', 25549),
(124784, 'esMX', '¡El orden es importante, aprendiz! Deberías leer tus notas con un poco más de atención.', '', 25549),
(124783, 'esMX', '¡¿Podrías parar de una vez?! ¡Estás dejando todo hecho un desastre!', '', 25549),
(124782, 'esMX', '¡Eso tuvo que doler!', '', 25549),
(124781, 'esMX', '¡No, no, no! ¡Esa no!', '', 25549),
(124780, 'esMX', '¡Por favor, no puedo concentrarme con tanta gente muriéndose en mi puerta!', '', 25549),
(124779, 'esMX', '¿Qué fue ese ruido?', '', 25549),
(124778, 'esMX', '¿$ct, podrías darte una vuelta por aquí antes de partir?', '', 25549),
(124777, 'esMX', '¡No puedo irme sin el jarrón! ¡Significa todo para mi maestro!', '', 25549),
(124776, 'esMX', '', '¡Apuesto a que ninguno de ustedes conoce siquiera el mar!', 25549),
(124775, 'esMX', '', '¡Ponte a trabajar, ogro! ¿Para qué te pagamos?', 25549),
(124774, 'esMX', '', '¡Deja de holgazanear o te haré caminar por la tabla!', 25549),
(124773, 'esMX', 'Parece que tienes las cosas bajo control, Scarleth. Tú y tus chicas deberían irse mientras puedan.', 'Parece que tienes las cosas bajo control, Scarleth. Tú y tus chicas deberían irse mientras puedan.', 25549),
(124772, 'esMX', '', 'Ninguna basura demoniaca le posará la mano a mis niñas.', 25549),
(124771, 'esMX', '¡No puedo irme sin mis hijos! Deben estar ocultándose...$b$b¡Encuéntralos, por favor!', '', 25549),
(124770, 'esMX', '¡Estoy detrás de ti! ¡Vamos!', '', 25549),
(124769, 'esMX', '¡Detrás de ti!', '', 25549),
(124768, 'esMX', '¿Creen que pueden ocultarse de Elisande? ¡Mueran, traidores!', '¿Creen que pueden ocultarse de Elisande? ¡Mueran, traidores!', 25549),
(124767, 'esMX', 'Tan solo un elfo de sangre y un $r sentado en la esquina hablando de tácticas. No hay nada extraño con eso.', '', 25549),
(124766, 'esMX', 'Qué bueno que hay alguien más aquí. Los hechizos de invisibilidad me llevan muy lejos. ¿Tienen alguna forma de detectarlos?', '', 25549),
(124765, 'esMX', 'Los protegeré a los dos. ¡Vamos!', 'Los protegeré a los dos. ¡Vamos!', 25549),
(124764, 'esMX', '', 'La presencia de la Legión es fuerte por aquí. Intenta no llamar mucho la atención, $r.', 25549),
(124763, 'esMX', '¡Bah, suerte!', '', 25549),
(124762, 'esMX', '¡Ja! Inténtalo otra vez.', '', 25549),
(124761, 'esMX', '', 'Avanza con cuidado, la presencia de la Legión es muy predominante por aquí.$b$b¿Acaso los natonocturnos se olvidaron de todo lo que perdimos en la Guerra de los Ancestros? Esta ruta lleva a la destrucción y a la muerte.', 25549),
(124760, 'esMX', 'Creo que tiene algo que ver con el orden en que Xylem enseña a sus aprendices. \n\nYo empecé por la escuela arcana, pero todavía no conozco el orden de las demás.', '', 25549),
(124759, 'esMX', 'Sabrás que puedes seleccionar tu barril cuando todos brillen de color blanco.', '', 25549),
(124758, 'esMX', 'No te distraigas mientras se mueven, y elige el barril correcto cuando se detengan.', '', 25549),
(124757, 'esMX', 'Voy a mezclar todo esto; pero el barril con cerveza aún en su interior brillará amarillo antes de que todo eso comience.', '', 25549),
(124756, 'esMX', 'Eh, hola. ¿Puedo ayudarte en algo?', '', 25549),
(124755, 'esMX', '¡Pues jugamos a un juego, obviamente!', '', 25549),
(124754, 'esMX', 'Bien hecho, $n. ¿Quieres saber qué hacemos luego de beber un solo barril de cerveza?', '', 25549),
(124753, 'esMX', '', '¿Yo? No tengo idea. Solo te recomiendo que no escuches a Wix. \n\nEs tan perverso que disfruta ver cómo los aprendices se fríen el cerebro con ese acertijo.', 25549),
(124752, 'esMX', '', 'Hagas lo que hagas, no intentes tocar las gemas a menos que sepas cuál es el orden correcto. \n\nHe visto lo que sucede cuando te equivocas y créeme: no es para nada bonito.', 25549),
(124751, 'esMX', 'Ah, ¿esa cosa? \n\nTe diré lo que sé: la primera gema sin dudas es la de fuego...\n\n<Wix se ríe por lo bajo.>', '', 25549),
(124750, 'esMX', 'Ya deja de molestarme. \n\n¿Crees que puedes venir a mandonearnos solo porque tienes unas togas bonitas?', '', 25549),
(124749, 'esMX', '¿Quieres superáh esa barrera? Pues buena suerte, colega.\n\nSimplemente asegúrate de no tocar ninguno de los cristales más de una vez, ¿me oyes? O te arrepentirás de haberlo hecho.', '', 25549),
(124748, 'esMX', '¡He estado entrenando todo el día pa'' que el archimago se fije en mí, pero hasta ahora no he tenido suerte!\n\nMe pregunto si siquiera andará pensando en incorporar más aprendices...', '', 25549),
(124747, 'esMX', 'Otro de los aprendices me aseguró que el orden era simplemente de derecha a izquierda. \n\nCreo que se llamaba Heinrich.', '', 25549),
(124746, 'esMX', 'Estoy seguro de que Xylem me dejará entrar a la torre si estudio lo suficiente. \n\nAunque no me vendría nada mal un sombrero de esos como el que llevas puesto.', '', 25549),
(124745, 'esMX', '', 'Una vez vi entrar a uno de los aprendices. Lo único que logré divisar fue que activó la gema blanca antes de activar la roja.', 25549),
(124744, 'esMX', '', 'Tenía un conjunto bonito como el tuyo, pero me cansé de los desafíos constantes de otros aprendices. \n\n¡Estoy segura de que Xylem me dejará entrar en la torre gracias a mis méritos como hechicera!', 25549),
(124743, 'esMX', '', 'Uno de los aprendices del círculo secreto me dijo que uno debe dominar todas las escuelas tradicionales antes de sumergirse en el reino de las sombras.\n\nCreo que eso era una pista.', 25549),
(124742, 'esMX', '¿Sabes algo sobre el acertijo de la barrera?', '¿Sabes algo sobre el acertijo de la barrera?', 25549),
(124741, 'esMX', '', '¡Sé que a Xylem se le perdieron algunos tornillos, pero así y todo es un archimago de renombre! ¡Piensa en todo lo que podría aprender de él!', 25549),
(124740, 'esMX', 'Eneas, debes irte ahora.', 'Eneas, debes irte ahora.', 25549),
(124739, 'esMX', 'Mi hijo salió herido en medio del caos... No he sido capaz de moverlo. ¡Ayúdanos, por favor!', '', 25549),
(124738, 'esMX', 'Debes irte de aquí. ¡No es seguro!', 'Debes irte de aquí. ¡No es seguro!', 25549),
(124737, 'esMX', 'No... no tuvimos opción. Lunette... ¡mis hijos! Ugh...', '', 25549),
(124736, 'esMX', '', '¡Iré!', 25549),
(124735, 'esMX', '¡¡Padre!!', '', 25549),
(124730, 'esMX', 'Tu padre te ayudará a llegar a un lugar seguro. ¡Ve abajo, ahora!', 'Tu padre te ayudará a llegar a un lugar seguro. ¡Ve abajo, ahora!', 25549),
(124729, 'esMX', '¡Oí gritos ¡Tengo miedo!', '', 25549),
(124728, 'esMX', 'Tu padre te está esperando abajo, ¡apresúrate!', 'Tu padre te está esperando abajo, ¡apresúrate!', 25549),
(124727, 'esMX', '', 'Mi... mi madre me dijo que... que me escondiera.', 25549),
(124725, 'esMX', '', '¿Un desafío? Muy bien, pero te lo advierto: Xylem me enseñó a dominar la magia del frío.', 25549),
(124722, 'esMX', 'Da igual, es un estúpido sombrero...', '', 25549),
(124721, 'esMX', '¡Bien, de acuerdo! ¡Aquí tienes!', '', 25549),
(124720, 'esMX', '¡Te desafío por ese sombrero!', '¡Te desafío por ese sombrero!', 25549),
(124719, 'esMX', 'Primero fueron esas estúpidas pruebas... Ahora, me pone a cavar en estas ruinas antiguas repletas de polvo. Espero que esto del círculo secreto valga la pena.\n\n¿Qué? Tú, vete de aquí. Estoy... arqueolo... arqueologando.', '', 25549),
(124718, 'esMX', '', '¡Ey, Archidruida! ¡Por aquí!', 25549),
(124712, 'esMX', '¡Ey, $r! ¿Buscas algo?', '', 25549),
(124710, 'esMX', 'La Legión debe estar intentando aprovecharse del debilitamiento de la Pesadilla. Puede que yo haya sido el primer objetivo, pero dudo que sea el último. Debemos encontrar y derrotar a quien sea que esté detrás de estos ataques contra nuestro pueblo.', '', 25549),
(124709, 'esMX', 'Lo solucionaremos.', 'Lo solucionaremos.', 25549),
(124708, 'esMX', '¿La Legión intentó corromperme?$b$bLa muerte del rey humano me afectó muchísimo. Lo elegí como mi campeón por su bravura y su capacidad para controlar el ansia de sangre y mantenerse fiel a sus principios y proteger a su pueblo. Entré al Sueño después de su muerte para reflexionar.$b$bPero es posible que la Legión me haya encontrado en ese momento.', '', 25549),
(124707, 'esMX', 'La Legión te estaba corrompiendo.', 'La Legión te estaba corrompiendo.', 25549),
(124706, 'esMX', 'No me... siento bien. ¿Qué está pasando?', '', 25549),
(124705, 'esMX', 'Ojalá Xylem te convierta en una cucaracha...', '', 25549),
(124704, 'esMX', '¡Suficiente! ¡Detente! ¡Puedes quedarte con las malditas togas!', '', 25549),
(124703, 'esMX', '¡¿Crees que puedes vencerme?! ¡Muy bien, veamos cómo lo haces contra cinco como yo!', '', 25549),
(124702, 'esMX', 'Yo, eh... necesito tus togas...', 'Yo, eh... necesito tus togas...', 25549),
(124701, 'esMX', 'Parece que los goblins ya estuvieron por aquí y se llevaron todo. \n\n¡A este ritmo, jamás voy a encontrar un objeto que impresione al archimago!', '', 25549),
(124700, 'esMX', '', 'Le dije a Aluriel que vendrías a rescatarme y solo se burló. ¿Quién se burla ahora?', 25549),
(124699, 'esMX', '', '¡Ah, al fin libre! Gracias, $Gforastero:forastera.', 25549),
(124698, 'esMX', '', 'Tenemos que dejar atrás a la Fuente de la Noche. Debemos hacernos responsables de nuestros fracasos, y pagar nuestra deuda con la gente de Azeroth.', 25549),
(124697, 'esMX', 'Muy bien, mereces saberlo. Permíteme mostrarte nuestro nuevo hogar.', '', 25549),
(124696, 'esMX', '¡Noressa! Pensé que nunca te volvería a ver...', '', 25549),
(124695, 'esMX', '', 'Cuéntame qué pasó. Qué le ocurrió a nuestra hija...', 25549),
(124694, 'esMX', '', '¡Absolon! ¿Qué te paso?', 25549),
(124693, 'esMX', '', 'Puedo llegar a la frontera. Gracias. ¡Dile a Absolon que voy en camino!', 25549),
(124692, 'esMX', '', 'Eres... tú. ¡Entregaste la carta!', 25549),
(124691, 'esMX', '', 'Deja que muera.', 25549),
(124690, 'esMX', 'Thalyssra, tu decides…', '', 25549),
(124689, 'esMX', '', '¡Podríamos estabilizarlo! Ya no necesitamos a La Fuente de la Noche para que nos de sustento, pero aún podemos contar con su poder...', 25549),
(124688, 'esMX', '¡Tu alma alimentará a la Legión!', '¡Tu alma alimentará a la Legión!', 25549),
(124687, 'esMX', 'Está muriendo. Sin el Ojo de Aman''thul, la Fuente de la Noche se volvió inestable.', '', 25549),
(124686, 'esMX', '', '¡Creí que nunca lo vería de nuevo!', 25549),
(124685, 'esMX', '', 'La Fuente de la Noche...', 25549),
(124684, 'esMX', 'Encontré todos los materiales.', 'Encontré todos los materiales.', 25549),
(124683, 'esMX', '', 'Con cada paso, nos acercamos cada vez más a la victoria.', 25549),
(124682, 'esMX', '', 'La guerra en Suramar requiere tu ayuda, $Gcampeón:campeona;.', 25549),
(124681, 'esMX', '', 'Buen trabajo, $Gcampeón:campeona;. ¡La horda marcha detrás tuyo!', 25549),
(124680, 'esMX', '', 'El enemigo no descansa. ¡Y nosotros tampoco!', 25549),
(124679, 'esMX', '', 'Sigues siendo $Gun aliado:una aliada; de confianza. Gracias, $Gcampeón:campeona;.', 25549),
(124678, 'esMX', '', 'Los caídos de la noche necesitan tu ayuda. ¿Volverás a responder su llamado?', 25549),
(124672, 'esMX', '|TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t¡%s comienza a abrir un |cFFFF0000|Hspell:229610|h[portal demoniaco]|h|r! ¡Síguelo a través de él!', '', 25549),
(124671, 'esMX', '|TInterface\\Icons\\inv_legionadventure.blp:20|t¡%s ordena un |cFFFF0000|Hspell:229284|h[Bombardeo]|h|r!', '', 25549),
(124670, 'esMX', 'Se suponía que sería un viaje sencillo. Simplemente ve a las islas con el bolsón y cobra lo que me deben.$b$b¡El jefe me va a matar!', '', 25549),
(124669, 'esMX', 'Cuidado, es una caída muuuuy larga.', '', 25549),
(124668, 'esMX', '', '¡Ya veo!', 25549),
(124667, 'esMX', '', 'Así está mucho mejor.', 25549),
(124666, 'esMX', 'Suelta tu agarre sobre la espada. No necesitas sujetarla tan firme.', '', 25549),
(124665, 'esMX', 'Controla tu respiración. Exhala con fuerza al lanzar una estocada.', '', 25549),
(124664, 'esMX', 'Relaja los hombros. Estás limitando tu movilidad.', '', 25549),
(124663, 'esMX', '', '¿Qué tal eso?', 25549),
(124662, 'esMX', '', '¿Qué te parece?', 25549),
(124661, 'esMX', '', '¿Estoy haciendo esto bien?', 25549),
(124660, 'esMX', '', 'Entendido, Silgryn.', 25549),
(124657, 'esMX', '', 'Creo que lo tengo.', 25549),
(124656, 'esMX', 'Separa un poco más tus pies. Estás un poquito fuera de balance.', '', 25549),
(124655, 'esMX', '', '¿Así?', 25549),
(124654, 'esMX', 'Tengo problemas para encontrar a los intrusos, Khadgar. ¿Me ayudas a detectarlos?', 'Tengo problemas para encontrar a los intrusos, Khadgar. ¿Me ayudas a detectarlos?', 25549),
(124653, 'esMX', 'No hay que permitir que Gul''dan use la Fuente de la Noche.', '', 25549),
(124652, 'esMX', 'Los elfos no descansan. Es todo lo que el Kirin Tor puede hacer para mantener la paz.', '', 25549),
(124651, 'esMX', 'Se podría cortar esta tensión con tijeras. Debemos atacar pronto...', '', 25549),
(124650, 'esMX', '', 'Ahora, déjame en paz.', 25549),
(124649, 'esMX', '', 'Ya basta. Eres mejor aprendiz que yo. Toma el manto...', 25549),
(124648, 'esMX', '', '¡Prepárate!', 25549),
(124647, 'esMX', 'Me temo que intentaste desafiar al goblin incorrecto. ¡Es hora de arder!', '', 25549),
(124646, 'esMX', 'Una tarea insignificante.', '', 25549),
(124645, 'esMX', '¡Regresa aquí, Fulgor!', '', 25549),
(124644, 'esMX', 'Necesito ese manto.', 'Necesito ese manto.', 25549),
(124643, 'esMX', '¡Nooooo!', '', 25549),
(124642, 'esMX', '', 'Esta torre ha estado abandonada por años. Seguramente encierra una cantidad impresionante de maravillas. \n\nXylem estará tan impresionado con este botín que me dejará entrar en su círculo secreto. Si tan solo pudiera abrir esta puerta...', 25549),
(124641, 'esMX', '¡Mírame!', '', 25549),
(124640, 'esMX', '¡Buena suerte!', '', 25549),
(124639, 'esMX', 'Evita la energía volátil allá afuera, e... intenta no caer, ¿sí?', '', 25549),
(124638, 'esMX', 'Asegúrate de pasar por los orbes de energía para recargar la facultad de carrerilla que te di. Oh, y...', '', 25549),
(124637, 'esMX', 'Te lanzaré un hechizo para otorgarte la capacidad de realizar carrerillas por el aire. Úsalo para llegar a tu objetivo en la distancia.', '', 25549),
(124636, 'esMX', 'Aquí estamos de nuevo, $n. ¿Alguna vez has notado que esta energía ley parece volar por todos lados?', '', 25549),
(124635, 'esMX', '¡Corran, pequeños ratones!', '', 25549),
(124634, 'esMX', '¡Huyes al costo de tu vida!', '', 25549),
(124633, 'esMX', '¡Quédate adentro si quieres vivir!', '', 25549),
(124632, 'esMX', '¡Quédense en sus hogares!', '', 25549),
(124631, 'esMX', '¡¿Quién anda ahí?!', '¡¿Quién anda ahí?!', 25549),
(124630, 'esMX', 'Algo no anda bien...', 'Algo no anda bien...', 25549),
(124629, 'esMX', '¡Una ilusión! ¿Qué ocultas?', '¡Una ilusión! ¿Qué ocultas?', 25549),
(124628, 'esMX', 'Esta tierra ha sufrido demasiado en manos de la Legión Ardiente. Tus acciones han traído algo de paz a esta región.', '', 25549),
(124626, 'esMX', 'Mis defensas... eran perfectas...', '', 25549),
(124622, 'esMX', '¡La Legión ha diseminado su corrupción hasta el corazón de Val''sharah! Nuestros defensores necesitan tu ayuda. Solo así tendremos una mínima esperanza de derrotar a los demonios.', '', 25549),
(124621, 'esMX', '¿De dónde vinieron?', '¿De dónde vinieron?', 25549),
(124620, 'esMX', 'Esos actos no quedarán impunes.', 'Esos actos no quedarán impunes.', 25549),
(124619, 'esMX', '¡Los demás! ¡Ayuda a los demás!', '¡Los demás! ¡Ayuda a los demás!', 25549),
(124618, 'esMX', 'Así no...', 'Así no...', 25549),
(124617, 'esMX', 'Haz lo que puedas, $n, pero ten cuidado.', 'Haz lo que puedas, $n, ten cuidado.', 25549),
(124616, 'esMX', '', 'Kaldorei, ¡prepárate para cargar el vestíbulo! ¡Elune te pide que acabes con esta ciudad maldita!', 25549),
(124615, 'esMX', '', '¡Sin''dorei, asegura la Caminata y mantén la posición! ¡La Luz ajusticiará a nuestros enemigos hoy!', 25549),
(124614, 'esMX', '', 'Shal''dorei, ¡llegó la hora de recuperar nuestra ciudad! ¡Adelante! ¡Anath''ashar!', 25549),
(124613, 'esMX', 'Thalyssra, puedes liderar la carga.', '', 25549),
(124612, 'esMX', '', 'Quizás pueda hacer una excepción.', 25549),
(124611, 'esMX', '', 'Tengo esto controlado. Mi entrenamiento me da una implacable resolución.', 25549),
(124610, 'esMX', '', 'He sobrevivido cosas peores.', 25549),
(124609, 'esMX', '', 'Luchamos contra la Legión.', 25549),
(124608, 'esMX', '', 'Mi lealtad jamás ha cambiado.', 25549),
(124607, 'esMX', '', 'Elisande no puede salirse con la suya.', 25549),
(124606, 'esMX', '', 'Sirvo a Suramar. A todo Suramar.', 25549),
(124605, 'esMX', '', '¿Sí?', 25549),
(124604, 'esMX', '', 'Tenu''balah.', 25549),
(124603, 'esMX', '', 'Hola.', 25549),
(124602, 'esMX', '', 'Saludos.', 25549),
(124601, 'esMX', '', 'Marchitar era menos cansado que esto.', 25549),
(124600, 'esMX', '', 'No tengo nada para ofrecerte.', 25549),
(124599, 'esMX', '', 'No tengo claro por qué aún necesitas mi atención.', 25549),
(124598, 'esMX', '', 'Hasta la vista.', 25549),
(124597, 'esMX', '', 'Adiós.', 25549),
(124596, 'esMX', '', 'Entendido.', 25549),
(124595, 'esMX', '', 'Buenos días.', 25549),
(124594, 'esMX', '', '¿Mm?', 25549),
(124593, 'esMX', '', 'Tienes toda mi atención.', 25549),
(124592, 'esMX', '', 'Saludos.', 25549),
(124591, 'esMX', '', 'Hola.', 25549),
(124590, 'esMX', '', '¿Qué te trae por Shal''Aran a estas horas?', 25549),
(124589, 'esMX', 'Me rompe el corazón verlo así.', '', 25549),
(124588, 'esMX', 'Nuestro amigo yace justo aquí.', '', 25549),
(124587, 'esMX', '¡Fuego a discreción!', '', 25549),
(124586, 'esMX', '¡Por la Dama Oscura!', '', 25549),
(124585, 'esMX', '¡Envíen a estos demonios al infierno! ¡FUEGO!', '', 25549),
(124584, 'esMX', '¡Objetivo en la mira! ¡Disparen!', '', 25549),
(124583, 'esMX', '¡Todos los cañones, disparen al objetivo!', '', 25549),
(124582, 'esMX', 'Apunten los cañones... ¡FUEGO!', '', 25549),
(124581, 'esMX', '', 'Tenemos lo necesario para asegurar el Sagrario. Ahora todo depende de Valtrois. Cuando esté lista, tú te enterarás antes que nadie.', 25549),
(124580, 'esMX', 'Muy bien. Centra tu mente. Se te pondrá a prueba en la tradición de nuestra orden.', '', 25549),
(124579, 'esMX', 'Busco la guía de la Guardia lunar.', 'Busco la guía de la Guardia lunar.', 25549),
(124578, 'esMX', 'Viniste a nuestro crisol, en donde los magos más honoríficos se han puesto a prueba por milenios. ¿Por qué estás aquí?', '', 25549),
(124577, 'esMX', 'Pisas suelo santo, $Gforastero:forastera;. Confió en que no lo harías sin un motivo.', '', 25549),
(124576, 'esMX', 'Qué buscas: ¿sabiduría o poder? ¿Quizás ambos?', '', 25549),
(124575, 'esMX', 'No te preocupes. Llevan siglos ignorando mis consejos para que mejoren esos resguardos...', '', 25549),
(124574, 'esMX', '¿Sus resguardos no bloquearán tu telemancia?', '', 25549),
(124573, 'esMX', '¡Tengo una idea! Una teletransportación en masa... pero necesito ayuda para hacerlo.', '', 25549),
(124572, 'esMX', '', 'La locura de Tel''arn no conoce límites. De no ser por ti, esa bestia podría haber destruido toda la terraza.', 25549),
(124571, 'esMX', '', '¡Los experimentos de Tel''arn han llegado demasiado lejos! ¡Hay una bestia arrasando con todo en la terraza!', 25549),
(124570, 'esMX', '', 'Esos traidores se merecen su destino. La historia recordará sus atrocidades.', 25549),
(124569, 'esMX', '', 'Los aduladores de Elisande y sus concubinas vagan en sus cámaras privadas sobre la Aguja de la noche. ¡No podemos permitirles dar aviso a la Legión sobre nuestro asalto!', 25549),
(124568, 'esMX', '', 'Estamos un paso más cerca de acabar con esta locura. ¡La hora final de Elisande ha llegado!', 25549),
(124567, 'esMX', '', 'Si podemos controlar la Aguja de la noche, el palacio caerá. ¡Detén el ritual!', 25549),
(124566, 'esMX', '', '¡Sin un flujo constante de suministros, el palacio caerá rápidamente! Bien hecho.', 25549),
(124565, 'esMX', '', 'Encuentra la ruta de abastecimiento del palacio y bloquéala. El Maestro de vuelo Volnath debe estar cerca de los cuarteles del capitán.', 25549),
(124564, 'esMX', '', 'Que esto sea una lección para aquellos que alardean de su poder.', 25549),
(124563, 'esMX', '', 'Hum. El constructo personal de Elisande está cerca. Sería una desgracia que algo malo le ocurriera...', 25549),
(124562, 'esMX', '', 'No puedo creer que nuestro refugio esté comprometido. ¡Rápido, encuentra a Aluriel y rompe las puertas!', 25549),
(124561, 'esMX', '', '¡Los fal''dorei han llegado hasta aquí! ¡Detenlos antes que los guardias los vean!', 25549),
(124560, 'esMX', '', 'Que descansen en paz. La Fuente de la Noche alguna vez nos dio sustento, pero se convirtió en una fuente de dolor... de muchas formas.', 25549),
(124559, 'esMX', '', 'Las almas de nuestros ancestros fueron atrapadas por el poder de la Fuente de la Noche. Debemos liberarlas de su tormento.', 25549),
(124558, 'esMX', '', 'Tiemblo al pensar que un ettin sea potenciado por la Fuente de la Noche. Gracias por salvarnos.', 25549),
(124557, 'esMX', '', '¡Un ettin está devastando las catacumbas! ¡Detenlo antes de que cause más daño!', 25549),
(124556, 'esMX', '', 'Jamás imaginé en diez mil años que la Legión llegaría hasta la entrada de la arboleda. \n\n¡No permitiré que pongan un pie en este lugar! ¡Cueste lo que cueste!', 25549),
(124555, 'esMX', '|TInterface\\Icons\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t ¡Hyrja marca a |cFFFF0000$n|r con |cFFFF0404|Hspell:228162|h[Escudo de luz]|h|r!', '|TInterface\\Icons\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t ¡Hyrja marca a |cFFFF0000$n|r con |cFFFF0404|Hspell:228162|h[Escudo de luz]|h|r!', 25549),
(124552, 'esMX', '', '¡No! El portal...', 25549),
(124551, 'esMX', '', '¡Contempla la Legión infinita!', 25549),
(124550, 'esMX', '', '¡Más almas para potenciar el portal!', 25549),
(124549, 'esMX', '¡Imposible! ¿Qué has hecho?', '', 25549),
(124548, 'esMX', '¡Levanta esos resguardos!', '', 25549),
(124546, 'esMX', 'Nos encargaremos de que vuelva a salvo. Informa a Thalyssra sobre nuestro éxito.', '', 25549),
(124545, 'esMX', '<Tose.> Ahora... necesito descansar. Gracias. Gracias por todo.', '', 25549),
(124544, 'esMX', 'Todos verán... esperanza... en el Lirio crepuscular.', '', 25549),
(124543, 'esMX', 'Querían hacer un ejemplo. Nos robamos su mensaje y ahora es nuestro.', '', 25549),
(124542, 'esMX', 'Que bueno que estás de vuelta.', '', 25549),
(124541, 'esMX', 'Aran''ethil... ¡La pesadilla llegó a su fin!', '', 25549),
(124540, 'esMX', 'Alivio... por fin...', '', 25549),
(124539, 'esMX', '', 'Estará bien. La fruta lo traerá de regreso.', 25549),
(124538, 'esMX', 'Ten calma. Te sacaremos.', '', 25549),
(124537, 'esMX', '', 'No lo sé. Solo espero que no sea demasiado tarde.', 25549),
(124536, 'esMX', '', '¿Cuánto tiempo tenemos?', 25549),
(124535, 'esMX', '', 'Debe ser un ejemplo para que todos lo vean.', 25549),
(124534, 'esMX', '¡Te lo agradeceré eternamente!', '¡Te lo agradeceré eternamente!', 25549),
(124533, 'esMX', '¡Alabada seas, heroína!', '¡Alabada seas, heroína!', 25549),
(124532, 'esMX', 'Ahh, mucho mejor. ¡Gracias!', 'Ahh, mucho mejor. ¡Gracias!', 25549),
(124531, 'esMX', 'Solo... Solo fue una herida superficial. Todavía puedo... ¡AAAYY! Olvídalo, regresaré a las defensas.', 'Solo... Solo fue una herida superficial. Todavía puedo... ¡Ay! Olvídalo, regresaré a las defensas.', 25549),
(124530, 'esMX', '', '¡Eso resultó mucho mejor de lo esperado! Seguiré refinando mi trabajo para el siguiente paso.', 25549),
(124528, 'esMX', '¡Te debo la vida! Volveré a la línea defensiva.', '¡Te debo la vida! Volveré a la línea defensiva.', 25549),
(124527, 'esMX', '', 'Ya he visto suficiente. Creo que puedo amortiguar el efecto de la magia vil sobre los marchitos. Ve hasta la Máquina de almas, que yo enviaré nuevos sujetos hacia ti.', 25549),
(124526, 'esMX', 'Gracias... Volveré a las defensas.', 'Gracias... Volveré a las defensas.', 25549),
(124525, 'esMX', 'Tal vez. La primera arcanista sabrá qué hacer. Llevemos a esta gente a Shal''Aran.', '', 25549),
(124524, 'esMX', '', 'Los cristales viles fijan el poder de la Legión aquí. Debemos ver qué pueden hacer los marchitos contra ellos.', 25549),
(124523, 'esMX', '¡No!... Seré... usado...', '', 25549),
(124522, 'esMX', '¡No eres nada! ¡Insignificante mosquito!', '', 25549),
(124521, 'esMX', '¡Shaza-kiel!', '', 25549),
(124520, 'esMX', '¡Disfrutaré mucho reduciendo tu alma a nada!', '', 25549),
(124519, 'esMX', '¡Ja! ¡Caminas ansioso hacía tu muerte, mortal!', '', 25549),
(124517, 'esMX', 'Las orbes de telemancia funcionan perfectamente. Mejor mantenemos esto en silencio hasta que estemos listos para el verdadero movimiento.', '', 25549),
(124516, 'esMX', '', 'Tenemos que acabar con esto.', 25549),
(124515, 'esMX', '', 'Esto debería sorprenderme, pero no es así. No luego del Cuarto menguante.', 25549),
(124514, 'esMX', '', '¡Nos descubrieron!', 25549),
(124513, 'esMX', 'Eso debiera bastar por ahora. Los datos sobre las posiciones mejorarán... oh, olvídalo. Hiciste un gran trabajo.', '', 25549),
(124512, 'esMX', 'Excelente. Empieza cuando estés listo. Utiliza el aparato y sigue el indicador de alineamiento. Eh... la luz. ¡Solo sigue la luz!', '', 25549),
(124511, 'esMX', '', 'Que así sea. Te enviaré con Silgryn. Con su entrenamiento, nos servirás bien.', 25549),
(124510, 'esMX', '', 'Tú debes ser la hermana de Arluin. Le debemos una gran deuda. Su sacrificio no fue en vano.', 25549),
(124509, 'esMX', '', 'Es un honor conocerte al fin, primera arcanista.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(124507, 'esMX', '', 'Mi hermano descansa aquí. Mi nombre es Arluelle.', 25549),
(124506, 'esMX', '', 'La fruta de este árbol me salvó de las garras de la locura. Ahora estoy completa, y deseo luchar.', 25549),
(124505, 'esMX', '', '¿Te acuerdas de mí, forastero?', 25549),
(124504, 'esMX', '', 'Te está esperando afuera.', 25549),
(124503, 'esMX', 'Como siempre, excelente sincronización, Deline.', '', 25549),
(124502, 'esMX', '¡Por aquí! ¡Todos a bordo!', '', 25549),
(124501, 'esMX', 'Espero que vea esto...', '', 25549),
(124500, 'esMX', 'No podemos retrasarnos mucho, me temo. Contén tu respiración.', '', 25549),
(124499, 'esMX', 'BORRAR', '', 25549),
(124498, 'esMX', '', 'Si algo sale mal, ten listos a tus marchitos. Buena suerte.', 25549),
(124497, 'esMX', 'Abriré el portal. ¡El elemento sorpresa estará a nuestro favor!', '', 25549),
(124496, 'esMX', '', 'Está hecho. La barrera debería estar desactivada.', 25549),
(124495, 'esMX', '', 'Muy bien, comenzaré. Al terminar, todos los dispositivos que hemos "ajustado" dejarán de funcionar.', 25549),
(124494, 'esMX', '', 'No creo que deba actuar a estas alturas. Volveré a Shal''Aran y seguiré con mi investigación.', 25549),
(124493, 'esMX', '', 'Mmm... están redirigiendo parte del poder de la Línea Ley directo al sagrario de la orden.', 25549),
(124492, 'esMX', '', 'No entiendo...', 25549),
(124491, 'esMX', '', 'Me esperaba esta clase de golpe bajo por parte de un enano...', 25549),
(124490, 'esMX', '', 'Pues, eso fue inmaduro.', 25549),
(124489, 'esMX', '', 'Ah, un hechizo de sigilo muy astuto, ¿pero qué es ese aparato? Ten cuidado.', 25549),
(124488, 'esMX', '', '¿Quién dejaría esta clase de abominación aquí?', 25549),
(124487, 'esMX', '', '¡Esos narcisistas errantes traga vileza!', 25549),
(124486, 'esMX', '', 'Están drenando esta Línea Ley, pero no puedo ver... Oh, ¡espera! Tengo una idea.', 25549),
(124485, 'esMX', 'Solicito tu ayuda por el bien de Suramar. La supervivencia de mi gente depende de ello.', '', 25549),
(124484, 'esMX', '¡Adalid! Necesito tu ayuda. Hay trabajo importante que hacer.', '', 25549),
(124483, 'esMX', '¡Adalid! ¡Es hora de demostrar tu fuerza y habilidad otra vez!', '', 25549),
(124482, 'esMX', 'Me alivia saber que están bien, al menos por ahora. Hmm, quizás debería pensar en la adopción...', '', 25549),
(124481, 'esMX', 'El patriarca búhogatito, Yowlon, tiene problemas guiando a sus gatitos de vuelta a casa. Mira esos ojos. Es imposible que los dejes solos ante el peligro.', '', 25549),
(124480, 'esMX', '', 'Permíteme ayudarte. Esta es muy pobre para pelear en tan corta distancia, y nos acompaña un campeón competente.', 25549),
(124479, 'esMX', '', 'Mis seguidores y yo estaremos a tu lado, Archidruida. ¡Debemos restablecer el equilibrio!', 25549),
(124478, 'esMX', '', 'Tu prueba más grande se acerca. Debes erradicar la corrupción de la Legión en Azeroth de una vez y para siempre.', 25549),
(124477, 'esMX', '', 'Archidruida, he visto crecer tu poder con cada desafío que has superado.', 25549),
(124476, 'esMX', 'Tal corrupción puede ser imparable, pero lograste detenerla... por ahora.', '', 25549),
(124473, 'esMX', 'Los rastros de la corrupción de Shaladrassil permanecen dentro de Suramar. Tal vez los cuernos de los sátiros viles puedan ser usados de mejor forma.', '', 25549),
(124471, 'esMX', 'Sé que te hemos exigido mucho en el transcurso de esta guerra, $gcampeón:campeona;, pero temo que esto aún no termina.', '', 25549),
(124470, 'esMX', 'Parece que ustedes dos comparten una afinidad. Un aliado es un aliado, ¡sin importar cuán pequeño sea!', '', 25549),
(124469, 'esMX', 'Una inusual criatura cerca de la costa está desafiando a los makrura de la zona. Siento que tiene relación contigo... Ve a ayudarlos.', '', 25549),
(124468, 'esMX', '¡Parece que bailar puede ser peligroso! Procura no perder el control.', '', 25549),
(124467, 'esMX', 'Los plumanegra nombraron a un nuevo jefe tras el último... incidente. Parece que intentarán su ritual una vez más.', '', 25549),
(124466, 'esMX', 'Bien hecho. ¡Luchas con la furia de una tormenta!', '', 25549),
(124465, 'esMX', 'Una frígida tormenta está naciendo en el pico cerca de Hafr Fjall. ¡Ataca su origen antes de que la tierra sufra con su congelado despertar!', '', 25549),
(124464, 'esMX', '', 'Éste es el último. Un último nudo que desatar y la energía debería volver a fluir.$b$bEspero estés $Glisto:lista;.', 25549),
(124463, 'esMX', '', 'Uno menos, faltan dos. Avísame cuando estés $Glisto:lista;.', 25549),
(124462, 'esMX', '', 'Ah, ya llegaste. Esperaba encontrar algo aquí, pero...', 25549),
(124461, 'esMX', '', 'Recuerdo este poder... ¡Kel''balor! El zarzal carmesí es nuestro destino.', 25549),
(124460, 'esMX', '', '¿Sí? ¿Qué quieres saber?', 25549),
(124459, 'esMX', '', 'Sí, y sé que la convergencia de las líneas ley alimenta con gran energía a la Fuente de la Noche. Aprovechar todo ese poder es de temer, pero si pudiese...', 25549),
(124458, 'esMX', '', 'Nuestros agradecimientos. No vamos a permitirles a los drogbar el sabotear nuestro estilo de vida. ¡Somos Altamontaña!', 25549),
(124457, 'esMX', '', 'Unos drogbar rebeldes arrojaron nuestras cajas de suministros al fondo del precipicio. Afortunadamente, tenemos un conveniente método para recuperarlas...', 25549),
(124456, 'esMX', '', 'El orden ha sido restaurado. Tu ayuda es siembre bienvenida aquí. ¡Por Altamontaña!', 25549),
(124455, 'esMX', '', 'Los drogbar están sembrando el caos en el Tótem del Trueno, arrasan con los tambores y ahuyentan a nuestro ganado. ¡Hay que acabar con su desastre!', 25549),
(124454, 'esMX', '', 'Tu control sobre tan vastas energías es impresionante. No fue una tarea pequeña.', 25549),
(124453, 'esMX', '%s revisa el fragmento.', '', 25549),
(124452, 'esMX', '', '¿Puedes en verdad ver las líneas, o solamente puedes sentirlas? ¿Es una sensación constante, o puedes prenderlo y apagarlo?', 25549),
(124451, 'esMX', '', 'Continúa e informa a Thalyssra. Tengo algunas preguntas que hacerle a nuestro amigo.', 25549),
(124450, 'esMX', '', 'Sé de lo que ella es capaz. Es por eso que debemos detenerla.', 25549),
(124449, 'esMX', '', 'Has sido un excelente asistente. Tu inherente conocimiento de las Líneas Ley es casi tan grande como el mío.', 25549),
(124448, 'esMX', '', 'Debo descansar antes de que regresemos a Shal''aran. Ay, fue mucho más agotador de lo que esperaba...', 25549),
(124447, 'esMX', '%s te admira.', '', 25549),
(124446, 'esMX', '%s gorjea felizmente.', '', 25549),
(124445, 'esMX', '%s luce alegre.', '', 25549),
(124444, 'esMX', 'Rrrr....', 'Rrrr....', 25549),
(124443, 'esMX', '¡%s está cansado tras su aventura!', '', 25549),
(124442, 'esMX', '', '¡Cuidado! ¡está aquí!', 25549),
(124441, 'esMX', '', 'Lo que sea que planees hacer, hazlo rápido. Siento que se aproxima algo… ¡hambriento!', 25549),
(124440, 'esMX', 'UNUSED DO NOT TRANSLATE', '', 25549),
(124438, 'esMX', 'Esos... esos... ¡Elfos de la noche!', 'Esos... esos... ¡Elfos de la noche!', 25549),
(124437, 'esMX', 'Esa vieja basura kaldorei abraza árboles.', 'Esa vieja basura kaldorei abraza árboles.', 25549),
(124436, 'esMX', '¿De dónde sacaron las cosas para hacer esto?', '¿De dónde sacaron las cosas para hacer esto?', 25549),
(124435, 'esMX', '¡Quiero pelear contra un enemigo aleatorio!', '¡Quiero pelear contra un enemigo aleatorio!', 25549),
(124434, 'esMX', 'Ni siquiera puedo adivinar de qué hicieron esto.', 'Ni siquiera puedo adivinar de qué hicieron esto.', 25549),
(124433, 'esMX', '¡¿Es esta alguna clase de broma?!', '¡¿Es esta alguna clase de broma?!', 25549),
(124432, 'esMX', '', 'Los marchitos... derrotados tan fácilmente por la magia vil. Por favor... salva a aquellos que puedas. ¡Mis heridas... no son importantes!', 25549),
(124431, 'esMX', '', 'Como si fuera a tomarme la molestia de enfrentarte. ¡Nato vil! ¡Mátenlos!', 25549),
(124430, 'esMX', '', '¡Probemos el temple de tu rebelión! Envía lo mejor que tengas a enfrentarme en los terrenos de Ly''leth... antes de que traiga a más ciudadanos para... interrogarlos.', 25549),
(124429, 'esMX', '', 'Pobre Thalyssra... intentas con tanta insistencia salvar a tu gente, ¡pero aun así les quitas lo único que puede permitirles recuperarse! Temo que Ly''leth pagará el precio por tu arrogancia.', 25549),
(124428, 'esMX', '', 'Te mostraré lo que estos cadáveres pueden hacer. ¡Ataquen!', 25549),
(124427, 'esMX', '', '¡Ja! ¿Es esto lo que trajiste? ¿Una escoria forastera y un grupo de cadáveres descerebrados sedientos de maná? Ciertamente has caído en tiempos difíciles.', 25549),
(124426, 'esMX', '', '¿Elisande te convirtió a TÍ en Primera Arcanista? Claramente tenía pocas opciones. ¡Liberen a Ly''leth ahora!', 25549),
(124425, 'esMX', '¡Baroo!', '¡Baroo!', 25549),
(124424, 'esMX', '¿Erk?', '¿Erk?', 25549),
(124423, 'esMX', 'Errrrrrr...', 'Errrrrrr...', 25549),
(124422, 'esMX', 'Esto me entusiasma solo un poco.', '', 25549),
(124421, 'esMX', 'Estoy listo, Valtrois.', 'Estoy lista, Valtrois.', 25549),
(124420, 'esMX', '', '¿Estás $Glisto:lista; para comenzar el ritual, $n?', 25549),
(124419, 'esMX', '', 'Esta cueva está muy bien oculta. Me sorprende que Oculeth lograse traernos aquí en una sola pieza.', 25549),
(124418, 'esMX', '', 'Cómodo, solitario y lleno de energía arcana. Puede que deba construir un taller aquí...', 25549),
(124417, 'esMX', '$GSeñor de la batalla:Señora de la batalla;, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124416, 'esMX', '$GSeñor abisal:Señora abisal;, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124415, 'esMX', 'Clarividente, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124414, 'esMX', 'Hoja de las sombras, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124413, 'esMX', '$GSumo sacerdote:Suma sacerdotisa;, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124412, 'esMX', '$GAlto señor:Alta señora;, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124411, 'esMX', '$GGran maestro:Gran maestra;, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124410, 'esMX', '$GArchimago:Archimaga;, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124409, 'esMX', '$GMaestro de caza:Maestra de caza;, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124408, 'esMX', 'Archidruida, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124407, 'esMX', '$GDestripador:Destripadora;, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124406, 'esMX', '', '$n entregó oro suficiente para pasar de largo las normas de la arena. ¡Habla con algún bruto si quieres pelear contra un camorrista aleatorio!', 25549),
(124405, 'esMX', '', 'Llevaré el teletransportador al terreno y traeré a nuestros marchitos más poderosos. Reúnete conmigo allá.', 25549),
(124404, 'esMX', '<Muestra la bosa de dados astillados.>', '<Muestra la bosa de dados astillados.>', 25549),
(124403, 'esMX', '', '¿Te sientes con suerte? $n quiere que hables con el jefe del foso Husmopasta para poner a prueba tu... capacidad de obtener oro.', 25549),
(124402, 'esMX', '<Muestra el contrato del gran jugador.>', '<Muestra el contrato del gran jugador.>', 25549),
(124401, 'esMX', '', '¿Estás viendo las peleas? En ese cuadrilátero se está repartiendo castigo a diestra y siniestra. Creo que me golpearon con un diente.', 25549),
(124400, 'esMX', 'No le hagas caso a Thelaron. No hay nada mejor que un buen martillo, una llama de arrabio y acero fino.$b$bY hablando de eso, debo seguir trabajando.', '', 25549),
(124399, 'esMX', '$GSeñor:Señora; de la muerte, has luchado una vez más para salvaguardar el futuro de Azeroth. En nombre de todo el consejo, gracias.', '', 25549),
(124398, 'esMX', '¡Que comiencen... LOS JUEGOS!', '', 25549),
(124397, 'esMX', '¡Sí, sí!', '', 25549),
(124396, 'esMX', '¡¿Ahhhh?!', '', 25549),
(124395, 'esMX', '¡Acábala!', '', 25549),
(124394, 'esMX', '¡Acaba con él!', '', 25549),
(124393, 'esMX', '¡Todo lo que ustedes hacen, debiluchos, es sólo correr!', '', 25549),
(124392, 'esMX', '¡Ve ahí y pelea, deja de esconderte!', '', 25549),
(124391, 'esMX', '¡Me aburres!', '', 25549),
(124390, 'esMX', '¡Guau! ¿Qué te mató tan rápido?', '', 25549),
(124389, 'esMX', '¡Jajajajajaja!', '', 25549),
(124388, 'esMX', '¡Más huesos para la arena!', '', 25549),
(124387, 'esMX', '¡Más huesos para la arena!', '', 25549),
(124386, 'esMX', '<Dale al garfafilada huérfano un poco de tus Arándanos secos.>', '<Dale al garfafilada huérfano un poco de tus Arándanos secos.>', 25549),
(124385, 'esMX', '<Dale al observasangre huérfano un poco de tus uvas azsunianas.>', '<Dale al observasangre huérfano un poco de tus uvas azsunianas.>', 25549),
(124384, 'esMX', '<Dale al Plumanívea huérfano un poco de tu vetecuerno ahumado.>', '<Dale al Plumanívea huérfano un poco de tu vetecuerno ahumado.>', 25549),
(124383, 'esMX', '<Dale al picotemible huérfano un poco de tu Queso añejo acre vrykul.>', '<Dale al picotemible huérfano un poco de tu Queso añejo acre vrykul.>', 25549),
(124382, 'esMX', '<El falcosaurio Plumanívea huérfano es tan débil que apenas puede caminar.>', '', 25549),
(124381, 'esMX', '<El falcosaurio garfafilada huérfano grita de hambre.>', '', 25549),
(124380, 'esMX', '<El falcosaurio observasangre huérfano tiembla descontroladamente. Luce aterrorizado.>', '', 25549),
(124379, 'esMX', '<El picotemible huérfano busca desesperadamente a su madre.>', '', 25549),
(124377, 'esMX', 'Quisiera sugerirte algo para tus estudios. Revisa la parte más alta de la estantería, si fueses tan amable.', '', 25549),
(124376, 'esMX', 'Acostumbramos mantener nuestra distancia, luego del incidente con la investigación.', '', 25549),
(124374, 'esMX', '', 'Si debes hacerlo, puedes ayudarme a encontrar las Líneas Ley. Solo intenta no cruzarte en mi camino.', 25549),
(124373, 'esMX', '¡Ese es su objetivo, camaradas! ¡Disparen!', '', 25549),
(124372, 'esMX', '¡Ese es el objetivo! Cañones... ¡FUEGO!', '', 25549),
(124371, 'esMX', '¡Fuego a discreción!', '', 25549),
(124370, 'esMX', '¡Disparen los cañones!', '', 25549),
(124369, 'esMX', 'Apunten los cañones... ¡FUEGO!', '', 25549),
(124368, 'esMX', 'Te pediría que obtengas la literatura, sin embargo no puedo encontrarla...', '', 25549),
(124367, 'esMX', 'Cambiando de tema, ¿te interesaría mirar a los dragones de la costa este?', '', 25549),
(124366, 'esMX', 'Eso fue verdaderamente interesante.', '', 25549),
(124365, 'esMX', 'De acuerdo.', '', 25549),
(124364, 'esMX', 'Quisiera sugerirte algo para tus estudios. Revisa la parte más alta de la estantería, si fueses tan amable.', '', 25549),
(124363, 'esMX', '', '¡Atención, camorristas! ¡$n hizo un trato con los ángeles de la Resurrección! ¡Pueden morir todo lo que quieran!', 25549),
(124362, 'esMX', 'Hidras. Son criaturas fascinantes.', '', 25549),
(124361, 'esMX', 'Avanzaré y haré un refugio seguro para los supervivientes. Aguanta, camarada.', '', 25549),
(124360, 'esMX', '<Muestra la estatuilla de ángel manchada de sangre.>', '<Muestra la estatuilla de ángel manchada de sangre.>', 25549),
(124359, 'esMX', '', '¿Te interesa comprar algo... ilegal?', 25549),
(124358, 'esMX', '$n muy generosamente pagó las pociones alborotadoras de todos. ¡No dejen que se enfríen y pierdan la espuma!', '', 25549),
(124357, 'esMX', '<Muestra el dispensador de pociones de Camorrista.>', '<Muestra el dispensador de pociones de luchador.>', 25549),
(124356, 'esMX', '¿Quieres comprar algo?', '', 25549),
(124355, 'esMX', 'Entonces, continúa.', '', 25549),
(124354, 'esMX', '¿Hmm? Oh, tú otra vez. Supongo que vienes a realizar estudios extracurriculares.', '', 25549),
(124353, 'esMX', '¡Ahí estás! ¡Por aquí!', '', 25549),
(124352, 'esMX', '¡Esta la paga $n! ¡Bebidas gratis por los próximos dos minutos!', '', 25549),
(124351, 'esMX', '', 'Practica utilizando tus ataques para eliminar a estos objetivos de entrenamiento.', 25549),
(124350, 'esMX', 'Practica utilizando tus ataques para eliminar a estos objetivos de entrenamiento.', '', 25549),
(124349, 'esMX', 'Hmm. No es tan cerca como lo esperaba, pero bastará. Ten cuidado.', '', 25549),
(124348, 'esMX', 'Te llevaré tan cerca de la Medialuna como pueda. Seguiremos en contacto.', '', 25549),
(124347, 'esMX', '<Muestra el cupón de bebidas gratis.>', '<Muestra el cupón de bebidas gratis.>', 25549),
(124346, 'esMX', '¡Oye! ¿Qué quieres?', '', 25549),
(124345, 'esMX', '', 'Más aves enfurecidas se han apoderado de esta zona. Reduce sus números antes de que esos huevos eclosionen.', 25549),
(124344, 'esMX', '', '¡Cuidado con las garras afiladas de estas bestias voladoras! Descubrimos que son feroces.', 25549),
(124343, 'esMX', '', '¡Estos seres malignos alados se multiplican fuera de control! ¡Acaba con su parranda cacofónica!', 25549),
(124342, 'esMX', '', 'Las aves depredadoras llegaron volando desde el mar. Hazlas retroceder de vuelta al océano o nos infestarán.', 25549),
(124341, 'esMX', '', '¡Oímos muchos graznidos! Esperamos que eso signifique que ganaron.', 25549),
(124340, 'esMX', '', 'Hiciste un trabajo admirable al acabar con esta horrible amenaza.', 25549),
(124339, 'esMX', '', 'Les cortaron las alas.', 25549),
(124338, 'esMX', '', '¡Otra victoria! Has demostrado ser muy hábil cazando bestias.', 25549),
(124337, 'esMX', '', 'Unos extraños depredadores están invadiendo este ecosistema. ¡Acaba con ellos antes de que se esparzan!', 25549),
(124336, 'esMX', '', 'Te damos las gracias. Monitorearemos de cerca sus números.', 25549),
(124335, 'esMX', '¡Viajes en zepelín gratuitos para todos, cortesía de $n! ¡Vengan al teletransportador!', '', 25549),
(124333, 'esMX', 'No te preocupes. No te GANASTE el derecho de subir al zep, pero un tarado me PAGÓ para que sigas. Puedes irte.\n\n¡Súbete a ese teletransportador! Estoy seguro de que no te matará... ¡Creo!', '', 25549),
(124332, 'esMX', '', 'El siguiente grifo debe ir aquí.', 25549),
(124331, 'esMX', '', '¡En fin, sigamos!', 25549),
(124330, 'esMX', '<Muestra el formulario de alquiler del zepelín.>', '<Muestra el formulario de alquiler del zepelín.>', 25549),
(124329, 'esMX', 'Ya estamos en ello.', '', 25549),
(124328, 'esMX', '', 'Si vas a golpear una línea ley, al menos asegúrate de que sea el punto correcto. Trata un poco más a la derecha.', 25549),
(124327, 'esMX', '|TINTERFACE\\ICONS\\SHA_ABILITY_ROGUE_BLOODYEYE:20|t¡Aléjate cuando Cosas que no deberían ser lancen |cFFFF0000|Hspell:207720|h[Presencia el vacío]|h|r para evitar quedar asustado!', '|TINTERFACE\\ICONS\\SHA_ABILITY_ROGUE_BLOODYEYE:20|¡Aléjate cuando Cosas que no deberían ser lancen |cFFFF0000|Hspell:207720|h[Presencia el vacío] para evitar quedar asustada|h|r!', 25549),
(124326, 'esMX', 'Archimago Karlain, nos vendría bien tu ayuda.', '', 25549),
(124325, 'esMX', 'Tenemos que viajar a Karazhan de una vez y descubrir qué busca la Legión. ¡Conjuraré un portal.', '', 25549),
(124324, 'esMX', '', 'Has hecho suficiente, arcanista. Debo llevarlos a ambos a Shal''Aran. Vengan conmigo.', 25549),
(124323, 'esMX', '', '¡Listo! La corriente ha sido redirigida a Shal''Aran.', 25549),
(124322, 'esMX', '', 'Casi... llegamos. ¡Solo hay que aguantar un poco más!', 25549),
(124321, 'esMX', '', 'Las corrientes son caóticas... esto llevará tiempo.', 25549),
(124320, 'esMX', '', 'El ritual requiere de mi completa concentración. Asegúrate de que no me interrumpan.', 25549),
(124319, 'esMX', '¡La Legión se apoderó de Karazhan! ¡Tenemos que recuperarla!', '', 25549),
(124318, 'esMX', '¡No! Me distraje tanto por nuestro trabajo en las Islas Quebradas que me olvidé de las defensas que coloqué...', '', 25549),
(124317, 'esMX', 'Qué lástima... Me temo que los resultados son imperfectos. El mensaje al interior del cristal está disperso. Solo entiendo algunos...', '', 25549),
(124316, 'esMX', 'Ahora, combinemos los fragmentos que recuperaste.', '', 25549),
(124315, 'esMX', 'La fuerza de los osos te acompañará. Te protegeremos. No podemos fracasar.', '', 25549),
(124314, 'esMX', 'Archidruida... he sido testigo de tu fuerza y tu resolución en el pasado. Será un orgullo estar a tu lado para enfrentar a la Legión.', '', 25549),
(124313, 'esMX', 'Sin''dorei y shal''dorei, tomen el camino y reténganlo contra nuestros enemigos. Tras tenerlo, que los kaldorei cabalguen en la delantera y tomen el vestíbulo.', '', 25549),
(124312, 'esMX', '', 'Cielos. ¿Eso fue un cumplido?', 25549),
(124311, 'esMX', '', 'Esta última transfusión me permitirá cambiar el flujo de energía, como el timón de un barco. Justo por aquí debería bastar.', 25549),
(124310, 'esMX', '', '¡Bien! Podemos hacerlo a tu manera. Pero si esta cueva termina explotando por culpa de la energía arcana, será toda tu culpa.', 25549),
(124309, 'esMX', '', 'He pasado milenios estudiando las Líneas Ley. ¡Soy suficientemente capaz de encontrar una a mis pies!', 25549),
(124308, 'esMX', '', 'No estoy "tocándolo", estoy transfusionándolo... Mmm, supongo que podría resultar aquí...', 25549),
(124307, 'esMX', '', '¡Esperen! ¡Esto no es lo que parece! Solo necesitamos usar el... Oh. Creo que sí es lo que parece...', 25549),
(124306, 'esMX', '', '¿Puedes hacer eso? Tal vez sepas una o dos cosas después de todo.', 25549),
(124305, 'esMX', '', 'Pero yo puedo ver la línea y el enfoque del conducto. Debes ponerlo ahí.', 25549),
(124304, 'esMX', '', '¿Estás seguro sobre esa posición? Sería mejor aquí.', 25549),
(124303, 'esMX', '', 'Al colocar los grifos sobre los puntos claves de la Línea Ley, puedo dirigir su corriente.', 25549),
(124302, 'esMX', '', 'Adalid, eres lo único que detiene mi mano. Habla rápido.', 25549),
(124301, 'esMX', '', '¿Deseas esconderte, Caído de la noche? ¡Pude sentir tu firma al teletransportarte desde Alazul!', 25549),
(124300, 'esMX', '¡Erk!', '¡Erk!', 25549),
(124299, 'esMX', '', 'Retrocede y alza tu arma. Le infundiremos una parte del poder de este consejo.', 25549),
(124298, 'esMX', '', '¡Todos unidos! ¡Debemos dar todas nuestras fuerzas!', 25549),
(124297, 'esMX', 'Nuestro poder se manifiesta: ¡Kirin''var torel, ahm shalar, azakim!', '', 25549),
(124296, 'esMX', '', 'Ahora, debemos concentrarnos en expulsar a sus ejércitos de Azeroth. ¡Atacaremos con todas nuestras fuerzas y pondremos fin a esto de una vez por todas!', 25549),
(124295, 'esMX', '', 'La Legión envió a sus agentes para neutralizar nuestros esfuerzos en la Tumba de Sargeras. Gracias a ti, sus planes fracasaron.', 25549),
(124294, 'esMX', 'Usa Espíritu feral ahora para invocar a estos espíritus.', '', 25549),
(124293, 'esMX', '', 'Usa Espíritu feral ahora para invocar a estos espíritus.', 25549),
(124292, 'esMX', '', 'Espera... ¿Qué...?', 25549),
(124291, 'esMX', '¡Aquí estamos! Tengo más o menos fijado el objetivo en la ubicación que solicitaste. ¡Aquí va!', '', 25549),
(124290, 'esMX', '¡Siguiente parada, la soleada Azsuna! Al menos... estaba soleado la última vez que estuve allí. Lo cual fue hace sólo unos miles de años.', '', 25549),
(124289, 'esMX', '¡Vamos!', '¡Vamos!', 25549),
(124288, 'esMX', '¿$GListo:Lista; para irte, $n? ¡Me encanta teletransportarme a nuevos lugares!', '', 25549),
(124287, 'esMX', 'Los portales de mago tardan tanto en aparecer. ¡Con telemancia, es como una transmisión instantánea!', '', 25549),
(124286, 'esMX', 'Las balizas de telemancia ayudan a conseguir poder para la triangulación de teletransportación. Deberíamos construir balizas adicionales.', '', 25549),
(124285, 'esMX', 'Se siente bien haber perdido el hambre. ¡Apuesto a que ahora podría teletransportar cualquier cosa!', '', 25549),
(124272, 'esMX', 'No debemos detenernos. Déjanos ver a Vanthir ahora.', '', 25549),
(124271, 'esMX', 'Esto... aún no... termina...', '', 25549),
(124270, 'esMX', 'Lo sé.', '', 25549),
(124269, 'esMX', 'No... se equivocaba... contigo...', '', 25549),
(124268, 'esMX', '¡Osaste levantar tus espadas en contra nuestra! ¡No eres más que un traidor!', '', 25549),
(124267, 'esMX', '¡Demasiado tarde, mortales! ¡Primero me encargaré de ustedes y después convertiré este mundo despreciable en cenizas!', '', 25549),
(124266, 'esMX', 'Tengo una conciencia. Le sirvo a la gente de Suramar.', '', 25549),
(124265, 'esMX', 'La decepcionaste, lanzador de hechizos. Podrías haber tomado mi lugar, si hubieses permanecido.', '', 25549),
(124264, 'esMX', 'Tal vez, pero no estoy solo.', '', 25549),
(124263, 'esMX', 'Acepta tu destino, Silgryn. ¡Eres superado!', '', 25549),
(124262, 'esMX', 'Qué bien que te nos unas, Silgryn. ¡Aluriel envía saludos!', '', 25549),
(124261, 'esMX', '¡No muevas tu espada, Thoramir!', '', 25549),
(124260, 'esMX', '¿Crees poder detener esta demostración? Muy bien, ¡te usaré como ejemplo primero!', '', 25549),
(124259, 'esMX', '', 'No pude levantar mi escudo a tiempo. ¿Qué sucedió?', 25549),
(124258, 'esMX', '¡Liadrin! Intentaré sacarla, pero hacerlo requiere de completa concentración. Ponte en guardia.', '', 25549),
(124257, 'esMX', '¡No puedo seguir manteniendo nuestra protección en alto! Debemos irnos.', '', 25549),
(124256, 'esMX', '', 'Con la destrucción de Azeroth se perdieron muchos conocimientos. Pero yo, Lunelli, hablo con la tierra y el viento.$b$bMe han dicho muchas cosas y me han otorgado conocimientos que debo transmitir a quienes sean dignos.$b$b¿Eres uno de ellos?', 25549),
(124255, 'esMX', 'No hay tiempo para eso. ¡Déjame llevarte a un lugar a salvo!', '', 25549),
(124254, 'esMX', '', 'Yo... estoy bien. ¿Qué ocurrió?', 25549),
(124253, 'esMX', '¡Eso estuvo cerca! Casi destruí el mismísimo flujo del tiempo... pero creo que así está mejor. ¿Estás bien?', '', 25549),
(124252, 'esMX', '¡Tyrande! Intentaré sacarla, pero para ello necesitaré concentración total. Mantén la guardia en alto.', '', 25549),
(124251, 'esMX', '¡Cuídate! ¡Entidades hostiles fueron atraídas a esta interrupción temporal! De acuerdo, guía el camino.', '', 25549),
(124250, 'esMX', '¡Esta magia temporal se equipara a la del Vuelo Bronce! Debo concentrarme en mantener nuestras defensas.', '', 25549),
(124249, 'esMX', 'Nuestros aliados sufrieron el impacto del encantamiento. Puedo protegernos de las energías residuales por un tiempo.', '', 25549),
(124248, 'esMX', 'Los Alazul demostraron ser un valioso aliado. Al ayudarlos, aseguraste su apoyo en nuestra campaña contra la Legión.', '', 25549),
(124247, 'esMX', '¡%s se enfurece por la muerte de sus crías cercanas!', '¡%s se enfurece por la muerte de sus crías cercanas!', 25549),
(124246, 'esMX', 'Hasta ahora, el ejercito de Suramar no ha querido alejarse de sus muros. Espero que eso no signifique que están planeando algo.', 'Hasta ahora, el ejercito de Suramar no ha querido alejarse de sus muros. Espero que eso no signifique que están planeando algo.', 25549),
(124245, 'esMX', 'Vereesa casi le dispara a Rommath esta mañana. Khadgar tuvo que convencerla de no hacerlo... otra vez.', 'Vereesa casi le dispara a Rommath esta mañana. Khadgar tuvo que convencerla de no hacerlo... otra vez.', 25549),
(124244, 'esMX', 'Los elfos se la pasan jugándose bromas. Solo nos aseguramos de que las cosas no se pongan violentas.', 'Los elfos se la pasan jugándose bromas. Solo nos aseguramos de que las cosas no se pongan violentas.', 25549),
(124243, 'esMX', 'Khadgar llamó a todo aquel que estuviera dispuesto a mandar tropas para apoyar al ejercito. Así que, ¿quién viene? \n\nLos elfos de sangre y los elfos de la noche. Dos razas tan enemigas que hace que la lucha entre la Alianza y la Horda luzca insignificante.', 'Khadgar llamó a todo aquel que estuviera dispuesto a mandar tropas para apoyar al ejercito. Así que, ¿quién viene? \n\nLos elfos de sangre y los elfos de la noche. Dos razas tan enemigas que hace que la lucha entre la Alianza y la Horda luzca insignificante.', 25549),
(124242, 'esMX', 'Suramar es una ciudad tan llena de magia que sería todo un desafío invadirla. Tan solo espero que podamos mantener juntos a estos ejércitos hasta que salgamos victoriosos.', 'Suramar es una ciudad tan llena de magia que sería todo un desafío invadirla. Tan solo espero que podamos mantener juntos a estos ejércitos hasta que salgamos victoriosos.', 25549),
(124241, 'esMX', 'Pícaros Caídos de la noche están reconstruyendo pilones de maná en las Ruinas Ley. Los Alazul han solicitado tu ayuda para erradicar la pestilencia.', '', 25549),
(124240, 'esMX', 'El conflicto entre los ejércitos no será tolerado. Estamos aquí para asegurarnos de que todos se enfoquen en el objetivo.', 'El conflicto entre los ejércitos no será tolerado. Estamos aquí para asegurarnos de que todos se enfoquen en el objetivo.', 25549),
(124239, 'esMX', '¿Kaldorei, Sin''dorei, Quel''dorei y Shal''dorei? Suenan parecido, ¿no?', '¿Kaldorei, Sin''dorei, Quel''dorei y Shal''dorei? Suenan parecido, ¿no?', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(124238, 'esMX', 'La tensión entre la Horda y la Alianza ya es mucha cuando comparten el campo de batalla. ¿Pero los elfos? Prácticamente puedes cortar esa tensión con unas tijeras.', 'La tensión entre la Horda y la Alianza ya es mucha cuando comparten el campo de batalla. ¿Pero los elfos? Prácticamente puedes cortar esa tensión con unas tijeras.', 25549),
(124237, 'esMX', 'Te pediría que le des clases a los principiantes del Kirin Tor... si no tuvieras que dedicar todo tu tiempo a salvar al mundo, obviamente.', '', 25549),
(124236, 'esMX', 'Los eruditos de la Academia Nar''thalas eran conocidos por sus conocimientos de runas para hechizos. Quizás puedas descubrir secretos ancestrales de los espíritus que ahí deambulan.', '', 25549),
(124235, 'esMX', 'Nada como un perfecto costillar.', '', 25549),
(124234, 'esMX', '', 'Maravilloso, mi queso favorito.', 25549),
(124233, 'esMX', 'No era necesariamente lo que tenía en mente, pero la perspicacia es la perspicacia. No hay que cerrar la mente a otras... oportunidades de aprendizaje.', '', 25549),
(124232, 'esMX', 'Los magos de Nar''thalas eran conocidos por fabricar varitas con una calidad excepcional. Revisa si sus técnicas pueden ayudarnos en nuestra guerra contra la Legión.', '', 25549),
(124230, 'esMX', '¡No! ¡Nuestro hipopótamo! ¡Nos rendimos!', '', 25549),
(124229, 'esMX', '¡Aaaaaaah!', '', 25549),
(124226, 'esMX', '¡Disentir está prohibido por orden de la Gran Magistrix Elisande!', '¡Disentir está prohibido por orden de la Gran Magistrix Elisande!', 25549),
(124225, 'esMX', '¡Quienes se opongan a la Gran magistrix lo pagarán caro!', '¡Quienes se opongan a la Gran magistrix lo pagarán caro!', 25549),
(124224, 'esMX', 'Sabemos dónde está tu familia. ¡Habla, o morirán también!', 'Sabemos dónde está tu familia. ¡Habla, o morirán también!', 25549),
(124223, 'esMX', '¡Confiesa! ¡Estás llevando traidores a Suramar!', '¡Confiesa! ¡Estás llevando traidores a Suramar!', 25549),
(124222, 'esMX', 'El conocimiento sobre posibles amenazas nos da una ventaja en batalla. Como siempre, ¡has demostrado aprender muy rápido!', '', 25549),
(124221, 'esMX', 'La Guardia Umbría quiere ir más allá de sus fronteras en medio de una revolución. ¡Hazlos pagar por su arrogancia!', '', 25549),
(124220, 'esMX', 'La Guardia Umbría instaló puestos de avanzada en el Zarzal carmesí. ¡Suelta a Los marchitos a tu disposición y échalos de ahí!', '', 25549),
(124219, 'esMX', 'Aunque no como sirviente, eres bienvenido para ayudarme a luchar.', 'Aunque no como sirviente, eres bienvenida para ayudarme a luchar.', 25549),
(124218, 'esMX', 'Sí, pero tu espíritu es libre de hacer lo que quieras. Ya no tienes que servirle más.', 'Sí, pero tu espíritu es libre de hacer lo que quieras. Ya no tienes que servirle más.', 25549),
(124217, 'esMX', 'Entonces elijo unirme a ti.', '', 25549),
(124216, 'esMX', 'He servido por tantos años. No creo que alguna vez haya hecho mi propia voluntad. ¿Necesitas un sirviente?', '', 25549),
(124215, 'esMX', '|TInterface\\Icons\\Spell_Mage_ArcaneOrb.blp:20|t |cFFFF0000|Hspell:228877|h¡[Anillos arcanéticos]|h|r caen desde el borde de la habitación!', '|TInterface\\Icons\\Spell_Mage_ArcaneOrb.blp:20|t |cFFFF0000|Hspell:228877|h¡[Anillos arcanos]|h|r caen desde el borde de la habitación!', 25549),
(124214, 'esMX', '|TInterface\\Icons\\Spell_Mage_ArcaneOrb.blp:20|t¡%s marca al enemigo con |cFFFF0000|Hspell:214278|h[Haces delfúricos]|h|r!', '|TInterface\\Icons\\Spell_Mage_ArcaneOrb.blp:20|t¡%s marca al enemigo con |cFFFF0000|Hspell:214278|h[Haces delfúricos]|h|r!', 25549),
(124213, 'esMX', '|TInterface\\Icons\\6BF_Explosive_Shard.blp:20|t¡%s teje energías |cFFFF0000|Hspell:209598|h[Conflexivas]|h|r a través de sus enemigos!', '|TInterface\\Icons\\6BF_Explosive_Shard.blp:20|t¡%s teje energías |cFFFF0000|Hspell:209598|h[Conflexivas]|h|r a través de sus enemigos!', 25549),
(124212, 'esMX', '|TInterface\\Icons\\SPELL_ARCANE_ARCANE01.BLP:20|t¡Vas a |cFFFF0000|Hspell:209973|h[Explotar]|h|r en 6 segundos!', '|TInterface\\Icons\\SPELL_ARCANE_ARCANE01.BLP:20|t¡Vas a |cFFFF0000|Hspell:209973|h[Explotar]|h|r en 6 segundos!', 25549),
(124211, 'esMX', '|TInterface\\Icons\\SPELL_ARCANE_INVOCATION:20|t |cFFFF0000|Hspell:210022|h¡[Orbes epoquéricos]|h|r caen del cielo!', '|TInterface\\Icons\\SPELL_ARCANE_INVOCATION:20|t |cFFFF0000|Hspell:210022|h¡[Orbes epoquéricos]|h|r caen del cielo!', 25549),
(124210, 'esMX', 'No siento ningún aprecio por la Horda; pero sus soldados lucharon y se sacrificaron junto a nosotros en la lucha contra los demonios.$b$bDe no haber sido por su cooperación y su valentía, ninguno de nosotros habría sobrevivido tanto tiempo.', '', 25549),
(124209, 'esMX', '', '¡No abandonaré esta isla hasta haber asesinado a todos los demonios y vengar a todos los guerreros caídos de la Horda!', 25549),
(124208, 'esMX', 'Derrotar a la Legión Ardiente demandará un enorme sacrificio. Lord Illidan lo sabe mejor que nadie.', '', 25549),
(124204, 'esMX', 'Es posible, pero tengo fe en nuestro comandante. ¡Si seguimos sus órdenes, saldremos victoriosos!', 'Es posible, pero tengo fe en nuestro comandante. ¡Si seguimos sus órdenes, saldremos victoriosos!', 25549),
(124203, 'esMX', 'Las fuerzas de la Legión parecen volverse cada día más fuertes.', 'Las fuerzas de la Legión parecen volverse cada día más fuertes.', 25549),
(124202, 'esMX', '¡Te dispararon con balas antiaéreas!', '¡Te dispararon con balas antiaéreas!', 25549),
(124200, 'esMX', '', 'El cielo se oscurece. Tenemos que avanzar.', 25549),
(124199, 'esMX', 'Oí que habían ciudadanos protegiendo refugios...', 'Oí que habían ciudadanos protegiendo refugios...', 25549),
(124198, 'esMX', 'Hay demonios por todas partes...', 'Hay demonios por todas partes...', 25549),
(124197, 'esMX', '¡Por favor, búscame un refugio!', '¡Por favor, búscame un refugio!', 25549),
(124196, 'esMX', '¡Rápido! ¡No estamos a salvo aquí!', '¡Rápido! ¡No estamos a salvo aquí!', 25549),
(124195, 'esMX', 'Estoy a salvo... gracias.', 'Estoy a salvo... gracias.', 25549),
(124194, 'esMX', 'La ciudad perdió la cordura...', 'La ciudad perdió la cordura...', 25549),
(124193, 'esMX', 'Casi... ¡Casi morimos!', 'Casi... ¡Casi morimos!', 25549),
(124192, 'esMX', 'Gracias, forastero.', 'Gracias, forastera.', 25549),
(124191, 'esMX', 'Estoy listo. ¡Envíame a las murallas!', 'Estoy lista. ¡Envíame a las murallas!', 25549),
(124190, 'esMX', 'El aire tan húmedo nos hace difícil volar por un tiempo considerable. Pero he creado un encantamiento que nos permitirá mantenernos en el aire lo suficiente para completar nuestro asalto.\n\nCuando tú digas, iniciaremos la distracción mientras te infiltras en el campamento.', '', 25549),
(124189, 'esMX', 'He preparado un encantamiento para que mis druidas puedan volar un momento a través de este aire húmedo.\n\nSimplemente da la orden y comenzaremos con la distracción mientras tú vas hacia el campamento.', '', 25549),
(124188, 'esMX', 'Vinimos a sacarte de aquí, Vanthir. Aguanta.', 'Vinimos a sacarte de aquí, Vanthir. Aguanta.', 25549),
(124187, 'esMX', '<La mirada de Vanthir se posa fuertemente sobre ti, pero no dice nada.>', '', 25549),
(124186, 'esMX', '<Vanthir se queda quieto. Sus ojos se ponen cristalinos y miran hacia la nada.>', '', 25549),
(124181, 'esMX', '....', '....', 25549),
(124180, 'esMX', '¡No puedes preguntarle a una bruja por qué lucha contra demonios!', '¡No puedes preguntarle a una bruja por qué lucha contra demonios!', 25549),
(124179, 'esMX', 'Pero... si eres un brujo.... ¿por qué luchas contra los demonios?', 'Pero... si eres una bruja.... ¿por qué luchas contra los demonios?', 25549),
(124178, 'esMX', '', 'No está fijo a la Fuente de la Noche, pero sí a las Líneas Ley. Nosotros los controlamos, pero aun así puede... ¡Eso es, ya veo!', 25549),
(124177, 'esMX', '¡Espero que tus matones se pudran!', '¡Espero que tus matones se pudran!', 25549),
(124176, 'esMX', '', 'Una perforación de maná, ¿quizás? Mmm... nada. Esto requiere mucho poder para sostenerse.', 25549),
(124175, 'esMX', '¡Rápido, a las ruinas!', '¡Rápido, a las ruinas!', 25549),
(124174, 'esMX', '¡Estoy a salvo!', '¡Estoy a salvo!', 25549),
(124173, 'esMX', '', '¡Muy eficiente! Veamos desde cerca... Ey, este es una obra de hechicería impresionante.', 25549),
(124172, 'esMX', 'Se decía que la biblioteca de la Academia Nar''thalas contenía estudios detallados sobre la fauna local. Tal conocimiento podría ser útil. ¡No dejes página alguna sin voltear!', '', 25549),
(124171, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(124170, 'esMX', '', 'Como lo desees, $GSeñor:Señora; de la batalla. ¿Estás $Glisto:lista; para partir?', 25549),
(124169, 'esMX', '¡Todos a la playa! ¡La Legión no deja de atacar!', '¡Todos a la playa! ¡La Legión no deja de atacar!', 25549),
(124168, 'esMX', 'Debemos ir a Helheim.', 'Debemos ir a Helheim.', 25549),
(124167, 'esMX', '', 'Alguien que pueda encontrar a nuestro amigo.', 25549),
(124166, 'esMX', '¿Qué clase de hechizo es este?', '', 25549),
(124165, 'esMX', '¡¿Thalyssra?!', '', 25549),
(124164, 'esMX', '', 'Baja la voz, Silgryn. Es bueno verte también.', 25549),
(124163, 'esMX', '', 'Debo mantener mi concentración para este trabajo... ¿estás $Glisto:lista; para ayudarme con esta tarea?', 25549),
(124162, 'esMX', '', 'Gracias, Silgryn. Ten cuidado.', 25549),
(124161, 'esMX', 'Estoy tristemente familiarizado con el captor de Vanthir.', '', 25549),
(124160, 'esMX', 'No temas, Primera Arcanista. Me aseguraré de que nuestro amigo no salga herido.', '', 25549),
(124159, 'esMX', '', '¡Por aquí! Siento energías que convergen por abajo, pero unos agresivos guardias me bloquean el paso. Necesito que despejes el camino.', 25549),
(124158, 'esMX', '', '¡Gracias a Elune estás aquí! Me vendría bien una mano con esto.', 25549),
(124157, 'esMX', '', 'Estoy agradecida de verte, a pesar de que vengas de otro campamento. Ven rápido, ¡hay mucho que discutir!', 25549),
(124156, 'esMX', '¡Ah, refuerzos! Por aquí, tengo mucho que contarte.', '', 25549),
(124155, 'esMX', 'Por aquí, $r. Procura no alertar a los guardias a medida que te acercas.', '', 25549),
(124154, 'esMX', '', 'Ah. Eso necesitó un mayor esfuerzo del que pensé. Tendrás que liberar a Vanthir sin mí. Lo siento.', 25549),
(124153, 'esMX', '¡Los traidores serán encontrados y asesinados por orden de la Gran magistrix!', '¡Los traidores serán encontrados y asesinados por orden de la Gran magistrix!', 25549),
(124152, 'esMX', 'Nos estamos acercando. ¡Puedo saborear su miedo!', 'Nos estamos acercando. ¡Puedo saborear su miedo!', 25549),
(124151, 'esMX', '¡No dejen ninguna piedra sin levantar! ¡Los traidores no se pueden esconder de nosotros!', '¡No dejen ninguna piedra sin levantar! ¡Los traidores no se pueden esconder de nosotros!', 25549),
(124150, 'esMX', '¡Otro necio en tierras prohibidas!', '¡Otro necio en tierras prohibidas!', 25549),
(124149, 'esMX', '¡El castigo por entrar aquí es la muerte!', '¡El castigo por entrar aquí es la muerte!', 25549),
(124148, 'esMX', '¡No deberías estar aquí!', '¡No deberías estar aquí!', 25549),
(124147, 'esMX', 'Mis fuerzas y yo te seguiremos hasta la Costa Quebrada. ¡Hundiremos a la Legión!', '', 25549),
(124146, 'esMX', 'Clarividente, debo admitir que me sorprende que hayas logrado lo que lograste.', '', 25549),
(124145, 'esMX', 'Hasta la vista, soldado.', '', 25549),
(124144, 'esMX', 'No te preocupes por mí. Me las arreglaré para salir...', '', 25549),
(124143, 'esMX', 'No descansaré hasta haber exterminado a esta inmunda escoria maléfica de esta maldita roca.', '', 25549),
(124142, 'esMX', 'Parece que tendré que fabricar mi propio equipo...', '', 25549),
(124141, 'esMX', 'Esos demonios malditos me robaron el equipo...', '', 25549),
(124140, 'esMX', '¿Te vas a quedar ahí parado? Vamos, tenemos muchos demonios que asesinar.', '', 25549),
(124139, 'esMX', '¡Neptulon, el Clarividente solicita tu ayuda!', '', 25549),
(124138, 'esMX', 'Era hora de que apareciera alguien. Ya empezaba a aburrirme...', '', 25549),
(124137, 'esMX', '', 'Ah. ¡Lo tienen prisionero en la Terraza de la orden! Debe ser hora de mostrarlo...', 25549),
(124136, 'esMX', '', '¡Enfócate! ¡Ahí!', 25549),
(124135, 'esMX', '', 'Está por marchitarse. Sus pensamientos son un revoltijo, son frenéticos... Solo necesito que...', 25549),
(124134, 'esMX', '', '...hasta que no puedo pensar en nada más!', 25549),
(124133, 'esMX', '', 'Hambre que no pasó, pero sí creció...', 25549),
(124132, 'esMX', '', 'Lo llevaron a un lugar oscuro y aislado. Comenzó a sentir como el hambre se enraizaba en sus entrañas.', 25549),
(124131, 'esMX', '', 'Teme por aquellos a quienes refugió, aquellos por quienes se sacrificó.', 25549),
(124130, 'esMX', '', 'En el momento en el que se lo llevaron del Cuarto Menguante sintió un miedo aterrador... pero no por él.', 25549),
(124129, 'esMX', '', 'Háblame, Vanthir...', 25549),
(124128, 'esMX', '', 'Salve, adalid.', 25549),
(124127, 'esMX', 'Me gustaría revisar la información que has recopilado sobre los agentes de la Legión.', 'Me gustaría revisar la información que has recopilado sobre los agentes de la Legión.', 25549),
(124126, 'esMX', 'Estoy a tus órdenes, Clarividente.', '', 25549),
(124125, 'esMX', 'Tu cría Plumavieja comienza a dormitar.', 'Tu cría Plumavieja comienza a dormitar.', 25549),
(124124, 'esMX', 'Tu cría Plumavieja te clava firmemente las garras en el hombro.', 'Tu cría Plumavieja te clava firmemente las garras en el hombro.', 25549),
(124123, 'esMX', 'Tu cría Plumavieja extiende las alas.', 'Tu cría Plumavieja extiende las alas.', 25549),
(124122, 'esMX', 'Tu cría Plumavieja parece estar aburrida.', 'Tu cría Plumavieja parece estar aburrida.', 25549),
(124121, 'esMX', 'Tu cría Plumavieja parece impresionada.', 'Tu cría Plumavieja parece impresionada.', 25549),
(124120, 'esMX', 'Tu cría Plumavieja quiere conocer mejor el mundo.', 'Tu cría Plumavieja quiere conocer mejor el mundo.', 25549),
(124119, 'esMX', 'Tu cría Plumavieja parece estar aprendiendo.', 'Tu cría Plumavieja parece estar aprendiendo.', 25549),
(124118, 'esMX', 'Tu cría Plumavieja suspira con satisfacción.', 'Tu cría Plumavieja suspira con satisfacción.', 25549),
(124117, 'esMX', 'Estoy listo, Thalyssra.', 'Estoy lista, Thalyssra.', 25549),
(124116, 'esMX', '', 'Lanza Descarga de Escarcha hasta que ganes Congelación cerebral, entonces lanzas Aluvión.', 25549),
(124115, 'esMX', '', 'Mientras Congelación cerebral está activa, Aluvión puede lanzarse instantáneamente ocasionado mayor daño.', 25549),
(124114, 'esMX', '', 'Lanzar Descarga de Escarcha puede desencadenar un efecto llamado Congelación cerebral.', 25549),
(124113, 'esMX', '', 'Aluvión es otro hechizo en tu arsenal. A pesar de poderse usar en solitario, Aluvión sirve mejor en combinación con otra habilidad.', 25549),
(124112, 'esMX', '', 'Rastrear a alguien por aquí requiere mucha energía. Espero que pueda durar...', 25549),
(124111, 'esMX', 'Lanza Descarga de Escarcha hasta que ganes Congelación cerebral, entonces lanzas Aluvión.', '', 25549),
(124110, 'esMX', 'Mientras Congelación cerebral esté activa, Aluvión puede lanzarse instantáneamente ocasionado mayor daño.', '', 25549),
(124109, 'esMX', 'Lanzar Descarga de Escarcha puede desencadenar un efecto llamado Congelación cerebral.', '', 25549),
(124108, 'esMX', 'Aluvión es otro hechizo en tu arsenal. A pesar de poderse usar en solitario, Aluvión sirve mejor en combinación con otra habilidad.', '', 25549),
(124107, 'esMX', 'Sigue controlando mi cuerpo, puedo sentirlo.', '', 25549),
(124106, 'esMX', '', '¡Mis guerreros de piedra aniquilarán a la Legión!', 25549),
(124105, 'esMX', '', 'Los ejércitos de Infralar están listos, pequeña criatura.', 25549),
(124104, 'esMX', 'Maté a tu maestro, ya no tienes que obedecerlo.', 'Maté a tu maestro, ya no tienes que obedecerlo.', 25549),
(124103, 'esMX', 'Madre Pétrea... El Clarividente te llama.', '', 25549),
(124102, 'esMX', '¿Qué quieres de la tierra?', '', 25549),
(124101, 'esMX', 'Traidores hasta el último de ellos...', '', 25549),
(124100, 'esMX', '¿Cómo que gratis?', '', 25549),
(124099, 'esMX', '', '¡Llevo semanas sola! ¡Tienes que creerme!', 25549),
(124098, 'esMX', 'Vamos a encontrar a tus amigos. ¡Confiesa, y tu muerte será rápida!', '', 25549),
(124097, 'esMX', 'El ejército del Muro celeste ha sido invocado. El viento te protegerá.', '', 25549),
(124096, 'esMX', 'He oído susurros en el viento. Llegó la hora de atacar a la Legión Ardiente.', '', 25549),
(124095, 'esMX', '¡Thunderaan, el Clarividente te invoca!', '', 25549),
(124094, 'esMX', 'Los vientos te llaman.', '', 25549),
(124093, 'esMX', 'No, lo derroté. Eres libre.', 'No, lo derroté. Eres libre.', 25549),
(124092, 'esMX', 'No te pareces a mi maestro...', '', 25549),
(124091, 'esMX', '', 'El maestro preparó una cena para sus invitados.\n\n Me temo que la lista de invitados es muy exclusiva y no veo tu nombre en ella. ¿Vienes a entregar algo para la fiesta?', 25549),
(124090, 'esMX', 'Mi investigación... muere conmigo...', '', 25549),
(124089, 'esMX', '¿Cómo llegaste hasta aquí? ¡Mi investigación debe mantenerse en secreto!', '', 25549),
(124088, 'esMX', '¿Qué ocurre aquí?', '¿Qué ocurre aquí?', 25549),
(124087, 'esMX', '', '¿En qué puedo ayudarte?', 25549),
(124086, 'esMX', 'Pronto, la Legión conocerá el verdadero significado de la palabra "ardiente".', '', 25549),
(124084, 'esMX', '', 'Mensaje... en el estanque... afuera...', 25549),
(124083, 'esMX', '¡Eso es! ¡El huevo está eclosionando!', '¡Eso es! ¡El huevo está eclosionando!', 25549),
(124082, 'esMX', 'El hipogrifo del interior lucha por escapar.', 'El hipogrifo del interior lucha por escapar.', 25549),
(124081, 'esMX', 'Oyes que algo se mueve dentro del huevo.', 'Oyes que algo se mueve dentro del huevo.', 25549),
(124080, 'esMX', 'Parece que el huevo está frio. Mantente cerca para calentarlo.', 'Parece que el huevo está frio. Mantente cerca para calentarlo.', 25549),
(124079, 'esMX', '¿Eh? ¿El huevo se está moviendo?', '¿Eh? ¿El huevo se está moviendo?', 25549),
(124078, 'esMX', 'Necesitamos que te unas a nuestras fuerzas para ayudarnos a encontrar y asesinar a estos demonios. Puede que tú seas el único capaz de detenerlos.', '', 25549),
(124077, 'esMX', 'Si estos demonios logran cumplir con su cometido, todos nuestros esfuerzos y sacrificios habrán sido en vano.', '', 25549),
(124076, 'esMX', '', 'Acechan todo Azeroth y amenazan con neutralizar nuestros esfuerzos por acceder a la tumba. Sus agentes son algunos de los campeones más poderosos de la Legión.', 25549),
(124075, 'esMX', '', 'Cuídate, Thalyssra. Debo regresar al palacio.', 25549),
(124074, 'esMX', '¡Lo dominaste!', '', 25549),
(124073, 'esMX', '', '¡Lo dominaste!', 25549),
(124072, 'esMX', 'Serás una excelente adición a la Alianza.', '', 25549),
(124071, 'esMX', '', 'Serás una excelente adición a la Horda.', 25549),
(124070, 'esMX', '', 'DELETE ME', 25549),
(124069, 'esMX', '', '¡Lo resolviste rápidamente!', 25549),
(124068, 'esMX', '¡Lo resolviste rápidamente!', '', 25549),
(124067, 'esMX', '', '¡Perfecto!', 25549),
(124066, 'esMX', '¡Perfecto!', '', 25549),
(124065, 'esMX', '', 'DELETE ME', 25549),
(124064, 'esMX', '', 'DELETE ME', 25549),
(124063, 'esMX', '', 'He escuchado cosas horribles de nuestro amigo Vanthir.', 25549),
(124062, 'esMX', '¡Bien! Debes haber estado practicando.', '', 25549),
(124061, 'esMX', '', '¡Bien! Debes haber estado practicando.', 25549),
(124060, 'esMX', '', '¡Aprendes rápido!', 25549),
(124059, 'esMX', '¡Aprendes rápido!', '', 25549),
(124058, 'esMX', 'Eso es, sabía que lo harías.', '', 25549),
(124057, 'esMX', '', 'Eso es, sabía que lo harías.', 25549),
(124056, 'esMX', '', 'Gracias, consejera. ¿Que noticias traes?', 25549),
(124055, 'esMX', '', 'Bienvenida a casa, Primera Arcanista. Gracias por venir con tanta urgencia.', 25549),
(124054, 'esMX', '', '¡Nada mal, $p!', 25549),
(124053, 'esMX', '¡Nada mal, $p!', '', 25549),
(124052, 'esMX', '¡Ahora lo tienes!', '', 25549),
(124051, 'esMX', '', '¡Ahora lo tienes!', 25549),
(124050, 'esMX', '¡Ahora sí que lo dominas!', '', 25549),
(124049, 'esMX', '', '¡Ahora sí que lo dominas!', 25549),
(124048, 'esMX', 'Los lazos del destino... Debo considerar esas palabras. Hasta la próxima, campeones.', '', 25549),
(124047, 'esMX', '¡Ahora nada puede detenerte!', '', 25549),
(124046, 'esMX', '', '¡Ahora nada puede detenerte!', 25549),
(124045, 'esMX', '', 'Realmente estás mejorando.', 25549),
(124044, 'esMX', 'Realmente estás mejorando.', '', 25549),
(124043, 'esMX', 'Hay mucho que nos espera más adelante. Hasta luego.', '', 25549),
(124042, 'esMX', '¡Impresionante!', '', 25549),
(124041, 'esMX', '', '¡Impresionante!', 25549),
(124040, 'esMX', '', '¡Excelente!', 25549),
(124039, 'esMX', '¡Excelente!', '', 25549),
(124038, 'esMX', 'Podría ser más sencillo cerrar una puerta que pasar por ella. Pero a veces, un paso a lo desconocido es necesario para romper los lazos del destino.', '', 25549),
(124037, 'esMX', '¡Basta de sentimentalismos! Escucha estas palabras antes de mi partida.', '', 25549),
(124036, 'esMX', 'No... no sé qué decir, Medivh.', '', 25549),
(124035, 'esMX', 'Tienes todo el poder que podrías necesitar, Khadgar. Es tu corazón, tu coraje, lo que te hace el guardián de este mundo. Y uno aún mejor de lo que yo jamás fuera.', '', 25549),
(124034, 'esMX', 'Ya lo dejé claro antes... ¡No quiero tal poder!', '', 25549),
(124033, 'esMX', 'Mi camino me lleva... a otro lugar. Además, Azeroth ha encontrado a su guardián en ti, joven aprendiz.', '', 25549),
(124032, 'esMX', '', 'Como verás, el alcance de la Legión se extiende incluso más allá de los límites de la Costa Quebrada.', 25549),
(124031, 'esMX', '¿Necesitabas mi ayuda?', '¿Necesitabas mi ayuda?', 25549),
(124030, 'esMX', '', '¡No nos rendiremos sin dar batalla!', 25549),
(124029, 'esMX', '¡Los demonios fueron eliminados de Karazhan! Gracias, campeones. Medivh, serías bienvenido como aliado en nuestra guerra contra la Legión.', '', 25549),
(124028, 'esMX', 'Bien, eso fue... interesante. Has hecho tu parte, pero aún no puedo encontrar una manera de...', '', 25549),
(124027, 'esMX', '¡Estoy del lado de la primera arcanista!', '¡Estoy del lado de la primera arcanista!', 25549),
(124026, 'esMX', '¡Por Thalyssra! ¡Por la rebelión!', '¡Por Thalyssra! ¡Por la rebelión!', 25549),
(124025, 'esMX', '¡Campeón! Mi arma está a tus ordenes.', '¡Campeona! Mi arma está a tus ordenes.', 25549),
(124024, 'esMX', '', 'Ven. No quiero hacerla esperar.', 25549),
(124023, 'esMX', '', 'El portal a mi hacienda es seguro. Querrás escuchar esto en persona.', 25549),
(124022, 'esMX', '', 'Tengo noticias urgentes, Thalyssra.', 25549),
(124021, 'esMX', '¡Muerte a la Legión! ¡Muerte a sus aliados!', '¡Muerte a la Legión! ¡Muerte a sus aliados!', 25549),
(124020, 'esMX', 'Campeón, vine a recibir tus enseñanzas.', 'Campeona, vine a recibir tus enseñanzas.', 25549),
(124019, 'esMX', 'Silgryn manda saludos.', 'Silgryn manda saludos.', 25549),
(124018, 'esMX', '[UNUSED] No hay para qué decirlo, pero mantente en guardia. Siento algo... una presencia que no sentía desde...', '', 25549),
(124017, 'esMX', 'Lo sé. Todo es parte de un ciclo mayor. Un ciclo que ahora por fin será destruido.', '', 25549),
(124016, 'esMX', 'No se pudo hacer nada, sabes. Intentamos cambiarlo, pero todo fue parte de un plan mayor.', '', 25549),
(124015, 'esMX', '', '¿Qué es eso? No hagas eso.', 25549),
(124014, 'esMX', '', 'Basta de holgazanear. Ustedes son natonocturnos preparándose para proteger a su ciudad y su legado. ¡Arriba ese orgullo!', 25549),
(124013, 'esMX', '', 'Alza tu arma. Álzala. Si la sientes muy pesada, vuélvete más fuerte.', 25549),
(124012, 'esMX', '', '¿A eso le llamas posición de batalla? Cualquier elfo de este campamento podría hacerte pedazos en esa posición.', 25549),
(124011, 'esMX', '', 'No, no, no. Dije formen filas. ¡Formen filas!', 25549),
(124010, 'esMX', 'No hay para qué decirlo, pero, está en guardia. Siento algo... una presencia que no he sentido desde...', '', 25549),
(124009, 'esMX', '', 'DELETE ME', 25549),
(124008, 'esMX', 'DELETE ME', '', 25549),
(124007, 'esMX', 'Aún no hay señales de Vanthir...', '', 25549),
(124006, 'esMX', '', 'DELETE ME', 25549),
(124005, 'esMX', '', 'Lo encontraremos, Silgryn. Estoy segura de ello.', 25549),
(124004, 'esMX', 'Estoy de acuerdo. ¡Todos a bordo! Iremos apretados.', '', 25549),
(124003, 'esMX', '', '¡Por aquí!', 25549),
(124002, 'esMX', 'Jmmm, debo recordar apagarte de vez en cuando. El uso excesivo puede provocar que te vuelvas... errático.', '', 25549),
(124001, 'esMX', 'Protocolos de defensa activados.', '', 25549),
(124000, 'esMX', 'Estás listo para supervisar la protección de la torre en mi ausencia.', '', 25549),
(123999, 'esMX', '', 'Debemos descubrir qué le ha pasado a Ly''leth. Aún puedes moverte con libertad por la ciudad, ¿cierto?', 25549),
(123998, 'esMX', 'Así es. Tengo una idea de cómo poner nuestras limitadas fuerzas en el lugar correcto en la hora correcta.', '', 25549),
(123997, 'esMX', '', 'Oculeth, necesitamos compensar la perdida de nuestros refuerzos.', 25549),
(123996, 'esMX', '', 'Así se hará.', 25549),
(123995, 'esMX', '', 'Valtrois, concéntrate en el hechizo de Elisande. Encuentra una manera de romperlo.', 25549),
(123994, 'esMX', '', 'No ha habido noticias de ella por algún tiempo. No debe ser coincidencia.', 25549),
(123993, 'esMX', '', '¿Por qué Ly''leth no nos advirtió de esto? Al ser una de las consejeras de Elisande, ¡debió haber escuchado algo!', 25549),
(123992, 'esMX', 'Lo que Elisande ha hecho... ¡debería ser imposible! Las energías necesarias...', '', 25549),
(123991, 'esMX', 'Elisande ha capturado a todas nuestras fuerzas dentro de un hechizo para detener el tiempo.', '', 25549),
(123990, 'esMX', 'Mis fuerzas se han estado preparando para este día. Su ira invade las Tierras de Fuego.', '', 25549),
(123989, 'esMX', '¡Utiliza Golpe de raptor!', '', 25549),
(123988, 'esMX', '', '¡Utiliza Golpe de raptor!', 25549),
(123987, 'esMX', '¿Nuestro viejo amigo puede soñar? ¿Está atrapado en pesadillas?', '', 25549),
(123986, 'esMX', 'Otro año de sueño. Me pregunto si Medivh despertará algún día.', '', 25549),
(123985, 'esMX', 'Detente, Arluelle. La estamos esperando.', '', 25549),
(123984, 'esMX', '', '¡Demuéstrame que tienes la experiencia e instinto necesarios para cazar a cualquier presa!', 25549),
(123983, 'esMX', '¡Demuéstrame que tienes la experiencia e instinto necesarios para cazar a cualquier presa!', '', 25549),
(123982, 'esMX', '¡Fulguron, escucha a este mortal!', '', 25549),
(123981, 'esMX', '¡Oh, pobre de mí! ¡Mi vida se acabó!\n\n¿Sabes quién es el Dr. Weavil? ¿O quién era? ¿O quien sigue siendo? No estoy seguro.\n\nLa muerte no lo detendrá, no, él lo predijo. Es un gnomo brillante, los locos siempre lo son.\n\nApenas se detuvo su corazón, las máquinas que tenía implantadas en su interior se encendieron. Estaba lleno de un fluido amarillo y electrificado. No sé si se trata de un no muerto, ingeniería alquímica, o algo... diferente.\n\nCuando oímos de una nueva pasantía a cargo del gran Dr. Weavil, muchos de nosotros volamos a la isla para inscribirnos. Ahora, no sé si estoy vivo o muerto, y me sale un fluido amarillo del cuerpo. Genial.\n\nLos demás decidieron llamarse a sí mismos, "gnomos serviles". Pues que les vaya bien, montón de idiotas.', '', 25549),
(123980, 'esMX', 'Hay que discutir esto de inmediato. Permíteme teletransportarte a Shal''Aran.', '', 25549),
(123979, 'esMX', 'Saludos, Alta señora.', 'Saludos, Alta señora.', 25549),
(123978, 'esMX', '', '¡Te debo la vida!', 25549),
(123977, 'esMX', '¡Al fin puedo estirar las piernas! Ahora necesito un demonio para golpear y estirar los puños.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(123976, 'esMX', '', '¿Soy libre? ¡Nunca lo olvidaré!', 25549),
(123975, 'esMX', '¡Los demonios pagarán por esto!', '', 25549),
(123974, 'esMX', '¡Lucharé hasta el último aliento!', '', 25549),
(123973, 'esMX', '¡Muerte a la Legión Ardiente!', '', 25549),
(123972, 'esMX', '¿Dónde está mi hacha? ¡Tengo que matar algunos demonios!', '', 25549),
(123971, 'esMX', '¡La Legión Ardiente pagará por esto!', '', 25549),
(123970, 'esMX', 'Me habrían enterrado en esa jaula de no haber sido por ti...', '', 25549),
(123969, 'esMX', '¡Te lo agradezco, $Gcampeón:campeona;!', '', 25549),
(123968, 'esMX', 'Necesito hablar con tu amo.', 'Necesito hablar con tu amo.', 25549),
(123967, 'esMX', 'Usa Golpe de raptor contra el muñeco de práctica.', '', 25549),
(123966, 'esMX', 'Golpe de raptor es un ataque rápido pero fuerte que puedes usar siempre que tengas la concentración para hacerlo.', '', 25549),
(123965, 'esMX', 'Ya que tu objetivo está sangrando y que tu mascota está comprometida, es hora de desatar tu propia furia.', '', 25549),
(123964, 'esMX', '', 'Usa Golpe de raptor contra el muñeco de práctica.', 25549),
(123963, 'esMX', '', 'Golpe de raptor es un ataque rápido pero fuerte que puedes usar siempre que tengas la concentración para hacerlo.', 25549),
(123962, 'esMX', '', 'Ya que tu objetivo está sangrando y que tu mascota está comprometida, es hora de desatar tu propia furia.', 25549),
(123961, 'esMX', '¿Qué puedo hacer por ti?', '', 25549),
(123960, 'esMX', '¡Libertad! ¡Al fin! Haz lo que puedas por los demás, no te preocupes por mí...', '', 25549),
(123959, 'esMX', '', '¡Maldición! Otro ataque. ¡Manténgase alerta!', 25549),
(123958, 'esMX', '', '¡El enemigo se quiebra ante los marchitos que hemos liberado! Sigue entrenándolos, ya que probarán ser invaluables en los días que están por venir.', 25549),
(123957, 'esMX', '', 'Estamos listos para empezar la ofensiva en Suramar. ¡Instala balizas en las afueras de la ciudad y lanza a los marchitos sobre las fuerzas de la Magistrix!', 25549),
(123956, 'esMX', 'Oh, el grog. Sí, gracias.', '', 25549),
(123955, 'esMX', '', 'Más de nuestros marchitos ahora son capaces de soportar la energía vil. ¡Nuestra revolución no será detenida!', 25549),
(123954, 'esMX', '', 'Los marchitos deben estar preparados para un asalto a la Fortaleza Nocturna. Su resistencia en contra de lo vil puede ser reforzada en el Bastión Almavil.', 25549),
(123953, 'esMX', '¡Pero qué hermosa ironía! ¡El caos surge entre los nobles mientras aquellos a quienes destierran aparecen en sus mismísimas puertas!', '', 25549),
(123952, 'esMX', 'Mis preparativos están completados. Veamos cómo los nobles de Suramar reaccionan a la distorsionada aparición de los marchitos!', '', 25549),
(123951, 'esMX', '', '¡La energía Ley fluye nuevamente! Un trabajo bien hecho.', 25549),
(123950, 'esMX', '', 'Líneas Ley ensombrecen todo Suramar, conforme las fuerzas de la Gran magistrix actúan desde las sombras. ¡Usa mis anteojos para ver más allá de lo evidente y conocer la fuente de esta interferencia!', 25549),
(123949, 'esMX', '', 'Deberíamos retirarnos mientras podamos.', 25549),
(123948, 'esMX', 'Oh sí, esta es una pieza maravillosa.', '', 25549),
(123947, 'esMX', '', 'Estos suministros serán cruciales para mantener nuestra campaña. ¡La horda sigue marchando!', 25549),
(123946, 'esMX', '', 'La falta de suministros está desanimando a nuestras tropas. ¡Ve a Suramar y obtén suministros de los opresores natonocturnos!', 25549),
(123945, 'esMX', '', 'La moral se ha vuelto a fortalecer con la llegada de suministros. ¡Has hecho bien!', 25549),
(123944, 'esMX', '', 'Lo teletransportaron lejos de aquí. ¿Dónde? No lo sé.', 25549),
(123943, 'esMX', '', 'Dijeron que serviría de ejemplo para el resto.', 25549),
(123942, 'esMX', '', 'Les rogó para que le perdonaran la vida a su gente.', 25549),
(123941, 'esMX', '', 'Los vilnatos mataron a cualquiera que se interpusiera en su camino, pero no a él.', 25549),
(123940, 'esMX', '', 'Observé desde mi posada cuando las fuerzas de Elisande arrasaron hacia la Media luna.', 25549),
(123939, 'esMX', '', 'Se acaban los suministros, pero el enemigo tiene muchos y de sobra. ¡Cabalga hacia Suramar y obtén suministros de las fuerzas de la Magistrix!', 25549),
(123938, 'esMX', '', 'Se les debe mostrar a los shal''dorei que existe un futuro más allá del caos. ¡Debemos alcanzar a cuantos podamos!', 25549),
(123937, 'esMX', '', 'Debemos avisar a los ciudadanos de Suramar sobre la llegada de la Horda. Publica boletines en toda la ciudad. ¡Que los oprimidos sepan que viene ayuda en camino!', 25549),
(123936, 'esMX', '', 'Entre más shal''dorei se unen a la batalla, menos de los míos caerán por liberar a Suramar.', 25549),
(123935, 'esMX', '', 'Debemos correr la voz acerca de la llegada de la Alianza. Avisa en la ciudad que el reino de la gran magistrix acabará pronto. ¡Motiva a los shal''dorei para que resistan!', 25549),
(123934, 'esMX', '', '¿Atacaron a su propia gente por atreverse a buscar resguardo? ¡Haremos caer nuestra ira sobre Elisande por esta injusticia!', 25549),
(123933, 'esMX', '', 'Los shal''dorei huyen de Suramar a medida que las fuerzas de Elisande avanzan por el Zarzal carmesí. Ve, derrota a los nato nocturnos en nombre de quienes escapen de la ciudad.', 25549),
(123932, 'esMX', '', '¿Los alguna vez orgullosos shal''dorei atacan a su propia gente? Esta situación es aún más desesperada de lo que imaginé...', 25549),
(123931, 'esMX', '', 'Las fuerzas de Elisande están abordando a los refugiados que huyen de Suramar por el Zarzal carmesí. ¡Es la oportunidad para poner a prueba sus habilidades en batalla!', 25549),
(123930, 'esMX', '', 'Mmm... ¿Así que los rumores son ciertos? ¿Las preciosas armas de Dalaran han dejado de existir? Debo asistir al funeral...\n\nSupongo que podríamos convencer a la Piedra de alma natonocturno para que se una a nosotros. Pero primero necesitaremos a alguien tenaz que se encargue de generar el escudo.', 25549),
(123929, 'esMX', 'Elisande no tiene perdón por condenar a tanta de nuestra gente. Debemos luchar por salvar a cuantos podamos.', '', 25549),
(123928, 'esMX', 'Elisande y la Legión están obligando a los ciudadanos a subir a barcos en dirección al Bastión Almavil. Sube a una góndola y libera a cuanto shal''dorei puedas.', '', 25549),
(123927, 'esMX', '¿Se te ocurre alguna manera de usar la Piedra de alma de natonocturno sin correr peligro?', '¿Se te ocurre alguna manera de usar la Piedra de alma de natonocturno sin correr peligro?', 25549),
(123926, 'esMX', 'Vamos. Es mejor discutir estos asuntos en privado.', '', 25549),
(123925, 'esMX', 'Mmm... ¡Casi todo es posible si estás $Gdispuesto:dispuesta; a hacer el esfuerzo! Si concentráramos a todos nuestros magos en la piedra, estoy seguro de que podríamos usarla sin mayores inconvenientes... Claro, puede que esa idea no sea demasiado práctica. \n\nQuizá podríamos protegerla con un escudo. Khagdar tiene una amiga un tanto peculiar, Ari, que es realmente brillante para resolver este tipo de misterios. ¡Veamos qué tiene para decirnos!', '', 25549),
(123924, 'esMX', '', 'Elisande humilló a nuestra gente cuando atacó a la Guardia lunar. Al mantener sus tradiciones con vida, nos ayudas a enmendar su trasgresión.', 25549),
(123923, 'esMX', '', 'La victoria sobre Elisande requerirá fuerza más allá de la que poseemos. Asciende hasta el Crisol Lunar y busca la bendición de los antiguos Guardias Lunares.', 25549),
(123921, 'esMX', '¿Se te ocurre alguna manera de usar la Piedra de alma natonocturno como arma sin correr ningún peligro?', '¿Se te ocurre alguna manera de usar la Piedra de alma natonocturno como arma sin correr ningún peligro?', 25549),
(123920, 'esMX', '', 'Nuestra ubicación permanece en secreto... por ahora. Temo que esta no será la última vez que Shal''Aran esté amenazada.', 25549),
(123919, 'esMX', '', 'Las patrullas de la Legión se encuentran más cerca que nunca de Shal''Aran. ¡Mátalos a todos antes de que encuentren nuestra ubicación!', 25549),
(123918, 'esMX', '¡Una idea interesante, $GArchimago:Archimaga; $n! Debo admitir que usar la magia de la legión en su propia contra es deliciosamente elegante. No podemos arriesgarnos a que Kathra''natir escape, pero... \n\nEl Archimago Kalec posee un amplio conocimiento sobre dispositivos mágicos y confío en que sabrá mantener la discreción. Veamos cuál es su opinión.', '', 25549),
(123917, 'esMX', '¿Podría Dalaran usar la Piedra de alma natonocturno como un arma?', '¿Podría Dalaran usar la Piedra de alma natonocturno como un arma?', 25549),
(123916, 'esMX', 'Si no fuera por ti, muchos inocentes habrían muerto en las calles. Una pequeña victoria, tal vez, pero una importante.', '', 25549),
(123915, 'esMX', 'Los ciudadanos tomaron armas para defender los refugios de todo Suramar. ¡Encuentra inocentes en peligro y llévalos a un lugar seguro!', '', 25549),
(123914, 'esMX', '¡Padre! ¡No!', '', 25549),
(123913, 'esMX', 'Demasiado... poder...', '', 25549),
(123912, 'esMX', '¡Basta de tonterías, muchacho! ¡Contén tu magia!', '', 25549),
(123911, 'esMX', '¡Debemos atacar antes de que sus defensas estén listas! Planta una Semilla de la ruina cerca de cada estructura y quedará destruida cuando la semilla brote. ¡Apúrate!', '', 25549),
(123910, 'esMX', '¿Qué le pasó a Vanthir, Maribeth?', '¿Qué le pasó a Vanthir, Maribeth?', 25549),
(123909, 'esMX', '', '¡Vanthir está en peligro!', 25549),
(123908, 'esMX', '', 'Este lugar no es seguro. Debemos partir pronto.', 25549),
(123907, 'esMX', '', 'Elisande y la Legión pagarán por la sangre que han derramado. ¡Aún tienen mucho que responder!', 25549),
(123906, 'esMX', '', 'Muchos natonocturnos fueron asesinados cuando Elisande y la Legión atacaron. ¡Devuelve el golpe! Muéstrale a esos demonios que no soportaremos ninguna tiranía.', 25549),
(123905, 'esMX', 'La Legión es un enemigo incansable. Sin embargo, hoy han logrado salvar el bosque. ¡Todo el pueblo de Val''sharah honra su victoria!', '', 25549),
(123903, 'esMX', '¡Estos demonios se han apoderado de las tierras sobre el Valle Zarpaluna! Oigo los gritos de los árboles. La Legión está drenando su esencia de vida para alimentar a sus defensas.', '', 25549),
(123898, 'esMX', '¡Te vas directo al portal!$b$bKhadgar estará esperando.', '', 25549),
(123897, 'esMX', '', '¡Un patético intento de disfrazarte! ¡Ahora pagarás con tu vida!', 25549),
(123896, 'esMX', '¡Maestro, por favor! Yo no quería...', '¡Maestro, por favor! Yo no quería...', 25549),
(123895, 'esMX', '', '¿Dónde estabas, $Gpequeño desgraciado:pequeña desgraciada;?$B$B¿Creíste que no estábamos mirando?', 25549),
(123894, 'esMX', '', 'No tengo tiempo para tus juegos.', 25549),
(123893, 'esMX', '', 'Tu raza nos sirve bien, esbirro.', 25549),
(123892, 'esMX', '', '¡Vete, esclavo!', 25549),
(123891, 'esMX', 'Necesitan ayuda para enfrentarse a una terrible amenaza y pidieron específicamente por ti.', '', 25549),
(123890, 'esMX', 'Asegúrate de que nadie vea el objeto que has recuperado hasta entonces. Buena suerte, $Gcampeón:campeona;.', '', 25549),
(123889, 'esMX', 'Puede que no sea un soldado, pero aún en la guerra hay camas que hacer y bebidas que servir.$b$bEs un trabajo que nací para cumplir.', '', 25549),
(123888, 'esMX', '', 'Estoy lista para quitar la barrera. Tendrás que avanzar rápido y asegurar la entrada antes de que se den cuenta de lo que ocurre.', 25549),
(123887, 'esMX', '¡Nuestra gente quedará libre de la Legión!', '¡Nuestra gente quedará libre de la Legión!', 25549),
(123886, 'esMX', '¡Estoy listo para luchar por Suramar!', '¡Estoy listo para luchar por Suramar!', 25549),
(123885, 'esMX', 'Correré la voz... ¡La tiranía de la Gran magistrix acaba ahora!', 'Correré la voz... ¡La tiranía de la Gran magistrix acaba ahora!', 25549),
(123884, 'esMX', 'La Guardia Umbría no sabrá qué los golpeó.', 'La Guardia Umbría no sabrá qué los golpeó.', 25549),
(123883, 'esMX', 'El portal funcionó y seguimos en una sola pieza. ¡Bien! Me preocupaba que sobrecargáramos la red al añadir otra baliza.', '', 25549),
(123882, 'esMX', 'No pude... prever... tal final...', '', 25549),
(123881, 'esMX', 'Pero el diseño... era perfecto...', '', 25549),
(123880, 'esMX', 'Un patético intento por resistirse a nuestro diseño.', '', 25549),
(123879, 'esMX', 'Es el fin de los mortales, tal como lo vislumbre.', '', 25549),
(123878, 'esMX', '¡Esta torre le pertenece a la Legión!', '', 25549),
(123877, 'esMX', '¡He previsto la destrucción de tu mundo!', '', 25549),
(123876, 'esMX', 'Uno a uno... ¡van a caer!', '', 25549),
(123875, 'esMX', 'Sin sentido... e inevitable.', '', 25549),
(123874, 'esMX', 'Solo queda una batalla. ¡Una última conquista para completar el diseño maestro!', '', 25549),
(123873, 'esMX', 'Nuestra cruzada ardiente ha consumido incontables mundos. Esta torre servirá como un conducto a cada uno de ellos.', '', 25549),
(123872, 'esMX', 'La presencia de Karazhan irradia a través del vacío... un faro que atrae el poder de la Legión', '', 25549),
(123871, 'esMX', '¡Amo! ¡Mi misión está completa! ¡Ven y reclama este mundo!', '', 25549),
(123870, 'esMX', '¡El gran diseño está completo! ¡Ahora cada mundo de la Legión está atado a esta torre!', '', 25549),
(123869, 'esMX', '¡Contemplen! ¡La puerta hacia la perdición se abre!', '', 25549),
(123868, 'esMX', '¡Un ejército infinito vendrá desde incontables mundos!', '', 25549),
(123867, 'esMX', 'Las preparaciones están listas. ¡Es hora de comenzar con el fin!', '', 25549),
(123866, 'esMX', '¡Basta de interrupciones! El gran diseño debe llevarse a cabo.', '', 25549),
(123865, 'esMX', 'Su resistencia está perdida. ¡Cedan ante nosotros!', '', 25549),
(123864, 'esMX', '¡Se arrodillarán! ¡Servirán!', '', 25549),
(123863, 'esMX', '¡Encárguense del objetivo!', '', 25549),
(123862, 'esMX', '', '¡Tu resistencia es irrelevante!', 25549),
(123861, 'esMX', '¡Incinera a ese!', '', 25549),
(123860, 'esMX', '¡Inicien el ataque!', '', 25549),
(123859, 'esMX', '¡Aniquílenlos!', '', 25549),
(123858, 'esMX', '¡La oscuridad te llevará!', '', 25549),
(123857, 'esMX', '¡Sientan el apretón de la entropía!', '', 25549),
(123856, 'esMX', '¡Maestro! Te he... fallado.', '', 25549),
(123855, 'esMX', '¡Nunca debiste regresar, necio mortal! ¡Tu torre nos pertenece!', '', 25549),
(123854, 'esMX', 'Los marchitos no durarán mucho ahí, $n. Reúne a un grupo de campeones de elite para avanzar. ¡De seguro ya conoces tales tácticas! Obviamente, estaremos detrás tuyo.', '', 25549),
(123853, 'esMX', '¡Cuando detengamos el bloqueo temporal que detiene a nuestras fuerzas, Gul''dan caerá!', '', 25549),
(123852, 'esMX', '', 'Puedo sentir a la Fuente de la Noche desde aquí. ¡Elisande debe estar muy desesperada como para sobrecargar a la Fuente así!', 25549),
(123851, 'esMX', '', 'Ahora que su mejor arcanista murió, dudo que Elisande envíe refuerzos. Tenemos la gruta. Sígueme.', 25549),
(123850, 'esMX', '', '¡Ey! ¡Por aquí!', 25549),
(123849, 'esMX', 'Andaris era la llave de sus defensas. La telemancia está trabajando nuevamente dentro del Sagrario. Enviaré a Thalyssra y a Khadgar a su ubicación.', '', 25549),
(123847, 'esMX', '¡Envíame a la Cumbre de Thorim!', '¡Envíame a la Cumbre de Thorim!', 25549),
(123846, 'esMX', '', 'Están todos... tan corruptos... como El Guardián...', 25549),
(123845, 'esMX', '', 'Yo... nunca... me rendiré...', 25549),
(123844, 'esMX', '', 'Una mente pura es una mente ordenada.', 25549),
(123843, 'esMX', '', 'La lección está completada.', 25549),
(123842, 'esMX', '¡Buena pelea! ¡Ahora, a Helya! ¡Hoy su traición llegará a su fin!', '', 25549),
(123841, 'esMX', '¡Cuidado, campeones! ¡El reino de Helya está protegido por una bestia salvaje salida de una pesadilla!', '', 25549),
(123840, 'esMX', '', '¡El hedor de la corrupción está sobre ustedes!', 25549),
(123839, 'esMX', 'Atiesh... será... destruido...', '', 25549),
(123838, 'esMX', 'Así que... se reduce... a esto...', '', 25549),
(123837, 'esMX', '', '¡Y así comienza tu purificación!', 25549),
(123836, 'esMX', 'Luché… lo mas... que pude...', '', 25549),
(123835, 'esMX', 'No tienes ni idea de cómo se siente hacer las cosas que he hecho. Cosas difíciles y necesarias.', '', 25549),
(123834, 'esMX', 'Una vez que te acostumbras, puedes matar amigos tan fácil como a cualquiera.', '', 25549),
(123833, 'esMX', 'Mi bastón... una reliquia, sí, ¡pero MÍA!', '', 25549),
(123832, 'esMX', 'Eres igual que los otros, ¿no es así?', '', 25549),
(123831, 'esMX', 'Hola, campeones. Los estaba esperando.', '', 25549),
(123830, 'esMX', '', 'un momento de aprendizaje', 25549),
(123829, 'esMX', '¡Un final apropiado para un ladrón!', '', 25549),
(123828, 'esMX', 'Todo va según lo planeado.', '', 25549),
(123827, 'esMX', '', 'Otra alma purificada', 25549),
(123826, 'esMX', 'Cada. Vez. Más fácil.', '', 25549),
(123825, 'esMX', 'Nunca has visto al verdadero Medivh.', '', 25549),
(123824, 'esMX', 'Esto es lo que soy. Fui contaminado de nacimiento, corrompido desde antes de mi concepción, una mala semilla portadora de un fruto amargo.', '', 25549),
(123823, 'esMX', '', 'Los titanes quieren que sus hijos tengan vidas virtuosas. Aún así, ¡esta torre hiede a depravación desde la piedra angular hasta la espira!', 25549),
(123822, 'esMX', 'No hagas nada. Deja que acabe.', '', 25549),
(123821, 'esMX', '¡Llegó el invierno!', '', 25549),
(123820, 'esMX', 'Sugiero mantener la calma.', '', 25549),
(123819, 'esMX', '¡Arde, arde, arde!', '', 25549),
(123818, 'esMX', 'Carroña para los pájaros...', '', 25549),
(123817, 'esMX', 'Tantas partes de mi...', '', 25549),
(123816, 'esMX', 'Un hechizo básico, pero efectivo.', '', 25549),
(123815, 'esMX', '¡Te debilitas y yo me fortalezco!', '', 25549),
(123814, 'esMX', '', 'Arrepiéntete... ¡o MUERE!', 25549),
(123813, 'esMX', '¡Arde... igual como aquel dragón!', '', 25549),
(123812, 'esMX', 'La naturaleza inherente del fuego...', '', 25549),
(123811, 'esMX', '', '¡Renuncia a tu avaricia y perversión!', 25549),
(123810, 'esMX', 'La torre necesita una nueva decoración.', '', 25549),
(123809, 'esMX', 'Un recuerdo, ¡congelado en el tiempo!', '', 25549),
(123808, 'esMX', '', '¡Alto, mortales! ¡Abran sus corazones a la virtud!', 25549),
(123807, 'esMX', '', '¡Entren en la luz, mortales!', 25549),
(123806, 'esMX', '', '¡Más trucos de marchitos! ¡No fallaré, Elisande! ¡Tú fallarás!', 25549),
(123805, 'esMX', '', '¡Andaris ha caído en un error crítico! Su escudo es vulnerable a los marchitos. Suelta algunos en un lugar seguro y succionarán la magia de su escudo.', 25549),
(123804, 'esMX', '¡Acabaré con ustedes!', '', 25549),
(123803, 'esMX', '¡Ya me he divertido lo suficiente con ustedes!', '', 25549),
(123802, 'esMX', '¡Es hora de acabar con esto!', '', 25549),
(123801, 'esMX', 'Las llamas... me esperan...', '', 25549),
(123800, 'esMX', 'Jamás... seré... libre...', '', 25549),
(123799, 'esMX', 'Jamás... se acaba...', '', 25549),
(123798, 'esMX', '¿Me llamaste hasta aquí sólo para morir a mis pies?', '', 25549),
(123797, 'esMX', '', '¡No podrás avanzar más! ¡Moriré antes de permitirte la entrada a la Fortaleza Nocturna!', 25549),
(123796, 'esMX', 'Los mortales jamás aprenden.', '', 25549),
(123795, 'esMX', 'Patético... como era de esperarse.', '', 25549),
(123794, 'esMX', '¡¿Quién sigue?!', '', 25549),
(123793, 'esMX', '¡Patético!', '', 25549),
(123792, 'esMX', '¡Más leña para el fuego!', '', 25549),
(123791, 'esMX', '¡Ven y arde!', '', 25549),
(123790, 'esMX', '¡Te reduciré a cenizas!', '', 25549),
(123789, 'esMX', '¡Conoce el significado del tormento!', '', 25549),
(123788, 'esMX', '¡Que así sea! ¡Sufrirán por su insolencia!', '', 25549),
(123787, 'esMX', '¿Estoy condenado a responder a las invocaciones de los mortales por toda la eternidad?', '', 25549),
(123785, 'esMX', '¡Suficiente! ¡Acabaré contigo yo mismo!', '', 25549),
(123784, 'esMX', '¡¿Otra vez?! ¡No! ¡Dime que no estuviste involucrado!', '', 25549),
(123783, 'esMX', 'Miserable alimaña. ¡Te exterminaré desde el aire!', '', 25549),
(123782, 'esMX', '¡Tu valor flaquea!', '', 25549),
(123781, 'esMX', '¡Mortales de voluntad débil!', '', 25549),
(123780, 'esMX', '¡Corran, cobardes!', '', 25549),
(123779, 'esMX', '¡Tu sangre de vida es mi arma!', '', 25549),
(123778, 'esMX', '¡Quémense desde adentro!', '', 25549),
(123777, 'esMX', '¡Tu alma traiciona a tus aliados!', '', 25549),
(123776, 'esMX', '¿Aethas? ¿Tú eres nuestro visitante secreto? ¿Qué está sucediendo?', '', 25549),
(123775, 'esMX', '', 'Los justos no tienen nada que temer.', 25549),
(123774, 'esMX', '', '¡Que te purifiques con fuego!', 25549),
(123773, 'esMX', '', '¡Los fuertes deben sufrir por los pecados de los débiles!', 25549),
(123772, 'esMX', '', '¡Todo será santificado!', 25549),
(123771, 'esMX', 'La Legión ha logrado infiltrarse en Dalaran y ha saboteado las armas de la ciudad... tanto que quizá sea imposible repararlas.', '', 25549),
(123770, 'esMX', 'Eso está mal... muy mal. ¡Pero por supuesto que ayudaremos!', '', 25549),
(123769, 'esMX', '¡Envíame a la Cumbre de Thorim!', '¡Envíame a la Cumbre de Thorim!', 25549),
(123768, 'esMX', '¡$GArchimago:Archimaga;! ¡El Kirin Tor necesita tu ayuda!', '', 25549),
(123767, 'esMX', '', 'Ahora que el perro de Andaris está muerto, podrás entrar al edificio. ¡Ve a la grieta!', 25549),
(123766, 'esMX', '', '¡Ahí! Esos taumaturgos están usando generadores para proteger el Sagrario. ¡Elimínalos!', 25549),
(123765, 'esMX', '', 'Parece que no pudiste entrar. Encuentra la fuente de poder de la barrera y derríbala.', 25549),
(123764, 'esMX', 'Así es. Supongo que llegamos a esto...', 'Así es. Supongo que llegamos a esto...', 25549),
(123763, 'esMX', 'No planeo ir en calma.', 'No planeo ir en calma.', 25549),
(123762, 'esMX', 'Los guardias nos arrancarán la cabeza tan solo por hablar de esto...', 'Los guardias nos arrancarán la cabeza tan solo por hablar de esto...', 25549),
(123761, 'esMX', 'Ya me harté de esta ocupación. ¡Tenemos que actuar!', 'Ya me harté de esta ocupación. ¡Tenemos que actuar!', 25549),
(123760, 'esMX', '', 'Estamos preparados para la posibilidad de realizar un descubrimiento. Con las orbes de telemancia y los marchitos resistentes a la maldad, tienes las herramientas necesarias para asegurar la brecha.', 25549),
(123759, 'esMX', 'No sé cómo se apropiaron de mi hechizo, no debería...', '', 25549),
(123758, 'esMX', '', '¿Creíste que no habíamos notado tu embuste? ¡Tus trucos pasados de moda no son rival para la verdadera hechicería!', 25549),
(123757, 'esMX', '¡Mi hechizo! ¡Qué acaba de suceder?', '', 25549),
(123756, 'esMX', 'Nuestra preciada ciudad, reducida a nada... ¿y para qué?', 'Nuestra preciada ciudad, reducida a nada... ¿y para qué?', 25549),
(123755, 'esMX', '¡Estoy harto de la Legión! ¡Somos más fuertes que esto!', '¡Estoy harto de la Legión! ¡Somos más fuertes que esto!', 25549),
(123754, 'esMX', 'La Gran magistrix ha ido demasiado lejos.', 'La Gran magistrix ha ido demasiado lejos.', 25549),
(123753, 'esMX', 'Me quitaron a mi hija... Hay que hacer algo.', 'Me quitaron a mi hija... Hay que hacer algo.', 25549),
(123752, 'esMX', '¿Acaso nosotros los Shal''dorei no somos mejores que esto?', '¿Acaso nosotros los Shal''dorei no somos mejores que esto?', 25549),
(123751, 'esMX', '¡No toleraré esta clase de trato!', '¡No toleraré esta clase de trato!', 25549),
(123750, 'esMX', 'Vamos. El Kirin Tor y los rebeldes del Lirio crepuscular aseguraron este nivel del puerto.', '', 25549),
(123749, 'esMX', 'Fascinante. Me encantaría comparar apuntes cuando todo esto termine.', '', 25549),
(123748, 'esMX', 'Bueno, honestamente hablando... recibí ayuda.', '', 25549),
(123747, 'esMX', '¿Una ciudad entera, dices? ¿De una sola vez?', '', 25549),
(123746, 'esMX', 'Justo a tiempo para nuestro próximo ferry. ¡Te vas a la Máquina de almas!', '', 25549),
(123745, 'esMX', '¡Los mortales no deben interrumpir el gran diseño!', '', 25549),
(123744, 'esMX', 'Buen trabajo, $p. Parece estar exhausta. La llevaré de regreso a Acherus por ti.', '', 25549),
(123743, 'esMX', '', 'Tendrás el tiempo que necesitas, Observador.', 25549),
(123742, 'esMX', 'Con nuestra gente armada, ¡los matones de Elisande se enfrentaran a una dura resistencia!', '', 25549),
(123741, 'esMX', 'Nuestros ciudadanos están desesperados por huir de la tiranía de Elisande. Asegúrate de que estén bien armados.', '', 25549),
(123740, 'esMX', '', 'Ven, únete a mis sin''dorei para destrozar a la vanguardia.', 25549),
(123739, 'esMX', '', 'Hay poco tiempo. Adalid, monta con nosotros al vestíbulo antes de que los nato nocturnos puedan reforzar su posición.', 25549),
(123738, 'esMX', '', 'Vamos. Defenderemos esta posición y enviaremos refuerzos.', 25549),
(123737, 'esMX', 'Qué huesos más frágiles, gusano. ¡Qué fácil se rompen!', '', 25549),
(123736, 'esMX', '¡Muévete antes de que mi espada te atraviese el cráneo!', '', 25549),
(123735, 'esMX', '¡Yo aplastarte como insecto!', '', 25549),
(123734, 'esMX', '¡Fuera de mi camino, gusano!', '', 25549),
(123733, 'esMX', '¡Pequeñín! ¡Yo aplastarte!', '', 25549),
(123732, 'esMX', '¡Peste despreciable! ¡Sigue avanzando!', '', 25549),
(123731, 'esMX', '¡No me toques, basura! ¡Vuelve a trabajar!', '', 25549),
(123730, 'esMX', '¡Llegas tarde, $Gpequeño:pequeña;!', '', 25549),
(123729, 'esMX', 'Si decides responder a su llamado, los encontrarás en la Ciudadela Violeta.', '', 25549),
(123728, 'esMX', 'El Consejo de los Seis te necesita, $GSeñor de la batalla:Señora de la batalla;.', '', 25549),
(123727, 'esMX', 'El Consejo de los Seis te necesita, $GSeñor abisal:Señora abisal;.', '', 25549),
(123726, 'esMX', 'El Consejo de los Seis te necesita, Clarividente.', '', 25549),
(123725, 'esMX', 'El Consejo de los Seis te necesita, Hoja de las sombras.', '', 25549),
(123724, 'esMX', 'El Consejo de los Seis te necesita, $GSumo sacerdote:Suma sacerdotisa;.', '', 25549),
(123723, 'esMX', 'El Consejo de los Seis te necesita, $GAlto señor:Alta señora;.', '', 25549),
(123722, 'esMX', 'El Consejo de los Seis te necesita, $GGran maestro:Gran maestra;.', '', 25549),
(123721, 'esMX', 'El Consejo de los Seis te necesita, $GArchimago:Archimaga;.', '', 25549),
(123720, 'esMX', 'El Consejo de los Seis te necesita, $GMaestro:Maestra; de caza.', '', 25549),
(123719, 'esMX', 'El Consejo de los Seis te necesita, Archidruida.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(123718, 'esMX', 'El Consejo de los Seis te necesita, $GDestripador:Destripadora;.', '', 25549),
(123717, 'esMX', 'El Consejo de los Seis te necesita, $GSeñor:Señora; de la muerte.', '', 25549),
(123716, 'esMX', 'Lo único que nos queda por hacer es contactar a...', '', 25549),
(123714, 'esMX', '¡Por aquí!', '', 25549),
(123713, 'esMX', 'Encárgate de que estas personas escapen de la ciudad, Deline. Tú, quédate conmigo.', '', 25549),
(123711, 'esMX', 'Ahh... la terraza. Esto tendrá que servir por ahora. Deline, llévanos lo más cerca que puedas.', '', 25549),
(123706, 'esMX', 'BORRAR', '', 25549),
(123704, 'esMX', '', 'Ya no puedo sostener más este hechizo. Reúnete conmigo en la Terraza Siempreluna y continuaremos.', 25549),
(123703, 'esMX', '', 'Perfecto. Con esto bastará para encontrarlo.', 25549),
(123702, 'esMX', '', 'Uno de sus proveedores debe haberle servido aquí. Recuerdos de tiempos más simples.', 25549),
(123701, 'esMX', '', '¡Puedo sentirlo! Al menos sigue con vida.', 25549),
(123700, 'esMX', '', 'Este jardín seguramente le dio muchas horas de descanso. Aquí, su esencia es fuerte y brillante.', 25549),
(123699, 'esMX', '', 'Ahí está. Ya vamos, Vanthir.', 25549),
(123698, 'esMX', '', 'Aquí debe ser donde comió muchas veces...', 25549),
(123697, 'esMX', 'Tus actos son ilógicos. Todo resultado posible para este encuentro ya fue calculado.', '', 25549),
(123696, 'esMX', '', 'Este lugar ha cambiado... se han ido las animadas multitudes y han sido remplazadas por guardias armados.', 25549),
(123695, 'esMX', '', 'No pude prever esto. Lo siento mucho, Suramar.', 25549),
(123694, 'esMX', '', 'Vaya que los demonios se han puesto cómodos ¡Qué desagradable!', 25549),
(123693, 'esMX', '', 'Mi gente... ¡en jaulas! Y algunos ya marchitos... Cuanta crueldad has demostrado, Elisande.', 25549),
(123692, 'esMX', '', 'Oh, Suramar...', 25549),
(123691, 'esMX', '', 'Este lugar rebosa usualmente en movimiento. ¿A dónde se habrán ido?', 25549),
(123690, 'esMX', 'Sientes que una fuerza poderosa entra en tu mente.', '', 25549),
(123689, 'esMX', 'Temo que, por ahora, me encuentro... indispuesto...', '', 25549),
(123688, 'esMX', '¡Cielos! Eso va a... dejar una cicatriz.', '', 25549),
(123687, 'esMX', 'Necesitaré solo... un momento...', '', 25549),
(123686, 'esMX', 'Nada que un buen rocío de aserrín pueda mejorar.', '', 25549),
(123685, 'esMX', 'Haré que los empleados de limpieza se hagan cargo de este desorden.', '', 25549),
(123684, 'esMX', ' ¡Mmm! Parece que alguien tuvo suficiente por esta noche.', '', 25549),
(123683, 'esMX', '¡Te arrastraré fuera de aquí por el cogote!', '', 25549),
(123682, 'esMX', '¡Deja de ser una molestia!', '', 25549),
(123681, 'esMX', '¿Nos muestras tu invitación?', '', 25549),
(123680, 'esMX', '¿Los juzgué mal? Espero que no...', '', 25549),
(123679, 'esMX', 'Decepcionante.', '', 25549),
(123678, 'esMX', '¡Levántate! ¡LUCHA!', '', 25549),
(123677, 'esMX', '', 'Entrenar a esa basura de los marchitos... ¡qué desagradable! ¡Dalion, protege la entrada! ¡Mata a mis enemigos!', 25549),
(123676, 'esMX', '', 'Estos mortales son prometedores.', 25549),
(123675, 'esMX', '', '¡Indigno!', 25549),
(123674, 'esMX', '', '¡Helya no será tan gentil como yo!', 25549),
(123673, 'esMX', '¡Muy bien peleado, campeones! Me rindo ante ustedes.', '', 25549),
(123672, 'esMX', '¡Ese fue demasiado débil!', '', 25549),
(123671, 'esMX', 'Débil... ¡como era de esperarse!', '', 25549),
(123670, 'esMX', '', 'Llegas... demasiado... tarde...', 25549),
(123669, 'esMX', '¡Una debilidad impactante!', '', 25549),
(123668, 'esMX', '¡Siente la furia de la tormenta!', '', 25549),
(123667, 'esMX', '¿Pueden aguantar la fuerza de un guardián?', '', 25549),
(123666, 'esMX', '¡Contemplen el poder que me otorgaron los titanes!', '', 25549),
(123665, 'esMX', '¡Portarrunas! ¡Denme poder!', '', 25549),
(123664, 'esMX', '¡Valarjar! ¡Prepara las runas! Hay que probar a estos héroes...', '', 25549),
(123663, 'esMX', 'Si vas a jurar tomar esta carga y terminar con su reinado, habla ahora, ¡y te enviaré al frente de la refriega!', '', 25549),
(123662, 'esMX', '¿De verdad hay valor en sus corazones?', '', 25549),
(123661, 'esMX', '¡Solo los cobardes le temen al llamado de la batalla!', '', 25549),
(123660, 'esMX', '', 'Manténganse juntos... ¡o mueran solos!', 25549),
(123659, 'esMX', '', '¡Formen filas!', 25549),
(123657, 'esMX', '', '¡Que así sea! ¡Los indignos serán eliminados de los Salones del Valor!', 25549),
(123656, 'esMX', '¡No se contengan! Debo asegurarme de que están listos para lo que les espera.', '', 25549),
(123655, 'esMX', '¿Debemos ser indulgentes con estas mascotas tuyas, Odyn?', '', 25549),
(123653, 'esMX', '¡TORMENTA ÓSEA!', '', 25549),
(123652, 'esMX', 'No le serviremos a la Legión.', 'No le serviremos a la Legión.', 25549),
(123651, 'esMX', '¡Esto es una locura!', '¡Esto es una locura!', 25549),
(123650, 'esMX', '¿Es cierto? ¿Podemos quedar libres de la Fuente de la Noche?', '¿Es cierto? ¿Podemos quedar libres de la Fuente de la Noche?', 25549),
(123649, 'esMX', 'Debo irme antes de que vengan más guardias.', 'Debo irme antes de que vengan más guardias.', 25549),
(123648, 'esMX', '¡El camino está despejado? Gracias, amigo.', '¡El camino está despejado? Gracias, amiga.', 25549),
(123647, 'esMX', 'Yo creo en el Lirio crepuscular.', 'Yo creo en el Lirio crepuscular.', 25549),
(123646, 'esMX', 'Helya se desespera… ¡Su fin se acerca!', '', 25549),
(123645, 'esMX', '¿Los Kvaldir amenazan a desafortunados aldeanos? ¡Patético! ¡Manda a esos cobardes al fondo del abismo marino!', '', 25549),
(123644, 'esMX', '¡Una victoria decisiva! La bruja marina se confió en su jugada.', '', 25549),
(123643, 'esMX', 'La magia de Helya amenaza a Altamontaña. ¡No hay que dejar que complete su ritual!', '', 25549),
(123642, 'esMX', '¡Es todo por esta semana amigos! Concurso de pesca: ¡FINALIZADO!', '', 25549),
(123641, 'esMX', 'Esto apenas es el comienzo y los premios están por acabarse. ¡Sigan lanzando esos anzuelos!', '', 25549),
(123640, 'esMX', '¡Aquí tenemos al ganador del primer lugar! ¡Felicitaciones!', '', 25549),
(123639, 'esMX', '¡Felicitaciones, ganaste el gran espectáculo de pesca de Tuercespina! Algún día le contarás esta historia a tus nietos. Ah, cierto... ¡gracias por todo el pescado!', '', 25549),
(123638, 'esMX', '¡Hola, camarada! ¡Hoy tenemos un torneo para pescadores extremos! Para ganar solo necesitas ser una de las PRIMERAS CINCUENTA PERSONAS EN EL MUNDO en traerme un trozo de delicioso pezrico. ¡Enróllate y arróllalos!', '', 25549),
(123637, 'esMX', '', 'Lo encontraré. Preferiblemente sin ser vista.', 25549),
(123636, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_SHADOWANDFLAME:20|t¡%s lanza |cFFFF0000|Hspell:228796|h[Encender alma]|h|r contra |cFFFF0000$n|r!', '', 25549),
(123635, 'esMX', 'La confianza es tu debilidad.', '', 25549),
(123634, 'esMX', 'La esperanza es una ilusión.', '', 25549),
(123633, 'esMX', 'Todo tu conocimiento se perderá.', '', 25549),
(123632, 'esMX', 'Al final estarás solo.', '', 25549),
(123631, 'esMX', 'Recuerda, $n. Aunque te parezcas a uno de ellos, quizás no tarden en descubrir tu fachada. Ten cuidado.', '', 25549),
(123630, 'esMX', '¿Me llamabas?', '', 25549),
(123629, 'esMX', '|TInterface\\Icons\\spell_fire_felfire.blp:20|t¡La %s adquiere a |cFFFF0000$n|r como objetivo del |cFFFF0000|Hspell:229242|h[Haz vil]|h|r!', '', 25549),
(123628, 'esMX', '¿Qué has oído acerca de Vanthir?', '¿Qué has oído acerca de Vanthir?', 25549),
(123627, 'esMX', '', 'No puedo quedarme mucho tiempo... Me esperan en el palacio. Debemos apresurarnos.', 25549),
(123626, 'esMX', '', '¡Alimenten a sus familias! ¡Vengan por una botella de arcavino!', 25549),
(123625, 'esMX', '', '¡Salgan de las sombras! ¡La rebelión trae arcavino para todos!', 25549),
(123624, 'esMX', 'Ah, llegó el Interrogador. ¡Será mejor que le digas lo que sabes, demonio!', 'Ah, llegó la Interrogadora. ¡Será mejor que le digas lo que sabes, demonio!', 25549),
(123623, 'esMX', 'Ten cuidado, $n. Incluso con la protección adicional del vial, éste no puede aguantar para siempre.', '', 25549),
(123622, 'esMX', '', '¿Ese tonto te mandó a recuperar su pólvora? ¡La perdió en buena ley!', 25549),
(123616, 'esMX', '', '¡Rompe sobre las olas!', 25549),
(123615, 'esMX', '', '¡Te lanzaré un beso!', 25549),
(123614, 'esMX', '', 'Respira profundo... ¡y pierde las esperanzas!', 25549),
(123613, 'esMX', '', '¡Atraparás un resfrío de muerte!', 25549),
(123612, 'esMX', '', '¡El frío te destrozará!', 25549),
(123611, 'esMX', '', '¡Tu fin acecha dentro de la niebla!', 25549),
(123610, 'esMX', '', '¡Contemplen mi ejército de los malditos!', 25549),
(123609, 'esMX', '', '¡Sus esfuerzos son inútiles, mortales! ¡Odyn NUNCA será libre!', 25549),
(123608, 'esMX', '', '¡Pronto te unirás a mi ejercito de Kvaldir!', 25549),
(123607, 'esMX', '', '¿Tengo tu atención?', 25549),
(123606, 'esMX', '', '¡Una caricia!', 25549),
(123605, 'esMX', '', '¡Deléitate con el frío beso del mar!', 25549),
(123604, 'esMX', '', '¡Sacudidas! ¡Temblor! ¡Terremoto!', 25549),
(123603, 'esMX', '', '¡Oscuridad sobre tu alma!', 25549),
(123602, 'esMX', '', '¡Que las Sombras te lleven!', 25549),
(123601, 'esMX', '', 'Él... no debe... ganar...', 25549),
(123600, 'esMX', '', 'Maldito seas... Odyn... maldito... seas...', 25549),
(123599, 'esMX', '', 'Mi reino... no puede acabar...', 25549),
(123598, 'esMX', '', 'Pronto los Salones del Valor caerán. ¡Los últimos días de Odyn están por llegar!', 25549),
(123597, 'esMX', '', 'Los campeones de leyenda de Odyn... ¡JA! Ni si quiera valen la pena.', 25549),
(123595, 'esMX', '¡Ah, mira, otro prisionero!', '', 25549),
(123594, 'esMX', '¡Ponlos en fila!', '', 25549),
(123593, 'esMX', 'Maestra encontrarse en lo más profundo de la torre.$B$BMaestra siempre ocupada, pero hacerse tiempo para Rezzle.$B$BAhora... ¡Rezzle estar asustado de volver! ¿Qué suceder si maestra pensar que Rezzle ahora ser traidor?', '', 25549),
(123592, 'esMX', '¿Dónde se encuentra el maestro del que hablas?', '¿Dónde se encuentra el maestro del que hablas?', 25549),
(123591, 'esMX', '', 'Húndanse en la desesperación, ¡perros falderos de Odyn!', 25549),
(123590, 'esMX', '', '¡Mío! ¡Mío por siempre!', 25549),
(123588, 'esMX', '', '¡Otra alma que se ahoga!', 25549),
(123587, 'esMX', '', '¡Sus almas me pertenecen!', 25549),
(123586, 'esMX', '', 'Vengan, mortales. ¡Se han ganado una eternidad de tormento!', 25549),
(123585, 'esMX', '', 'Eres muy amable al traer sus almas ante mí... le ahorrará a mi Val''kyr el problema de recolectarlos de la faz de la tierra.', 25549),
(123584, 'esMX', '', 'Oh, no... Los poderosos campeones de Odyn vinieron a terminar con mi reinado. ¿Qué debería hacer?', 25549),
(123583, 'esMX', 'Tenemos que completar el ritual unidos... ¡Hasta que la voluntad de Helya acabe!', '', 25549),
(123581, 'esMX', '|TInterface\\Icons\\INV_Icon_ShadowCouncilOrb_green.blp:20|t ¡Un |cFFFF0000|Hspell:228058\n|h[Orbe de corrosión]|h|r te está siguiendo!', '|TInterface\\Icons\\INV_Icon_ShadowCouncilOrb_green.blp:20|t ¡Un |cFFFF0000|Hspell:228058\n|h[Orbe de corrosión]|h|r te está siguiendo!', 25549),
(123580, 'esMX', '|TInterface\\Icons\\INV_Icon_ShadowCouncilOrb_purple.blp:20|t ¡Un |cFFFF0000|Hspell:227920|h[Orbe de corrupción]|h|r te está siguiendo!', '|TInterface\\Icons\\INV_Icon_ShadowCouncilOrb_purple.blp:20|t ¡Un |cFFFF0000|Hspell:227920|h[Orbe de corrupción]|h|r te está siguiendo!', 25549),
(123579, 'esMX', '¡La guarida de la Legión está en ruinas! Gracias a tu ayuda, la tierra se recuperará.', '', 25549),
(123578, 'esMX', 'Estoy en deuda contigo.', 'Estoy en deuda contigo.', 25549),
(123577, 'esMX', 'Estoy a salvo... ¡Gracias!', 'Estoy a salvo... ¡Gracias!', 25549),
(123575, 'esMX', '', '¡Toma esto!', 25549),
(123574, 'esMX', '', '¡Atrápalo!', 25549),
(123573, 'esMX', '¡Ayúdame! ¡Los guardias me lo quitaron todo!', '¡Ayúdame! ¡Los guardias me lo quitaron todo!', 25549),
(123572, 'esMX', 'Por aquí... ¡No he bebido arcavino en días!', 'Por aquí... ¡No he bebido arcavino en días!', 25549),
(123571, 'esMX', 'Por favor, aunque sea un poco de arcavino que te sobre... ¡tengo hijos!', 'Por favor, aunque sea un poco de arcavino que te sobre... ¡tengo hijos!', 25549),
(123570, 'esMX', 'Los demonios han abierto un portal para reforzar las líneas de sus tropas malditas. ¡Acaba con su infestación antes de que arrasen con el bosque!', '', 25549),
(123569, 'esMX', '', '[CUT]So be it. I will alert our forces inside the city. There is much I still have to learn about the world we left behind.', 25549),
(123568, 'esMX', '', '[CUT]There are still Nightborne in the city who blindly follow the Grand Magistrix. We must be careful not to hurt any innocents!', 25549),
(123567, 'esMX', '', 'Y los shal''dorei son más fuertes de lo que esperas. Cuando llegue el momento, lucharán junto a tí.', 25549),
(123566, 'esMX', '', '¿Los rebeldes están listos para el combate? Impresionante. Veamos qué pueden hacer.', 25549),
(123565, 'esMX', 'Aunque sufrimos a los pies de la Magistrix, nuestra gente debe ser alimentada. Son los cimientos de nuestra rebelión.', '', 25549),
(123564, 'esMX', '', 'Tus líderes tienen que poner la mente en el juego.$b$bVereesa está obsesionada con su deseo de venganza contra la Horda, por lo que no podemos confiarle nuestro flanco a ella.$b$bTyrande es una centinela. Sabe poco de guerra en este tipo de campo de batalla. Si bien su exploración es útil, debería impedir que los Kal''dorei se involucren en el ataque principal.$b$bMis caballeros de sangre son los únicos capaces de cargar con la responsabilidad del conflicto.', 25549),
(123561, 'esMX', '', 'Pocos comprenden la situación de los Caídos de la noche, a excepción de los Sin''dorei. Mi corazón está con ellos.$b$bPero Thalyssra debe entender que hay una diferencia entre una insurrección y una guerra.$b$bHasta ahora, sus rebeldes han sobrevivido con un par de escaramuzas por aquí y por allá. Pero no se han vuelto más fuertes con las batallas como los elfos de sangre.', 25549),
(123560, 'esMX', '', 'Bien. No tenemos la cantidad de gente necesaria para sostener este lugar por mucho. Entre antes presionemos, mejor.', 25549),
(123559, 'esMX', '', 'Para que quede claro, yo voté por no confiar en la Horda en esta campaña. Perdí un esposo y un rey por la traición de la Horda.$b$bNo veo motivos para confiar en ti ahora ni nunca.', 25549),
(123558, 'esMX', '', 'Nunca creí que compartiría un campamento con los kaldorei. Pero tiempos difíciles requieren medidas desesperadas.', 25549),
(123557, 'esMX', '', 'Debo hablar contigo;. Reúnete conmigo en cuanto te sea posible.', 25549),
(123556, 'esMX', 'Los matones de la Magistrix impiden los esfuerzos de Deline por distribuir el arcavino. Encuéntrala en los canales y protégela mientras alimenta a nuestra gente.', '', 25549),
(123555, 'esMX', '', 'Ha llegado la hora de marchar con un ejército sobre mi ciudad natal. Que Elune nos conceda un fin rápido a este conflicto.', 25549),
(123554, 'esMX', 'Planes de Thalyssra.', 'Planes de Thalyssra.', 25549),
(123553, 'esMX', '', 'Suramar. Aquí nací. Nunca en diez mil años creí que volvería con un ejercito para recuperarla de los mismos elfos a quienes alguna vez busque para que me protegieran.', 25549),
(123552, 'esMX', '', 'Cuando dejé que te llevarás las Lágrimas de Elune, asumí que la siguiente vez que nos viéramos sería en la última batalla contra la Legión.$b$bNo esperaba verte junto a adictos al maná a los pies de mi ciudad natal.$b$bHabla rápido, $r. No estoy de ánimos para peticiones de Thalyssra.', 25549),
(123551, 'esMX', '', 'Habla rápido, $r. No te quiero paseándote por mi campamento.$b$bUn buen amigo mío murió por culpa de tu Horda en la Costa Quebrada. Agradece que tenemos un enemigo en común por el momento.', 25549),
(123550, 'esMX', '', 'Me alegra ver una cara amistosa en el campo de batalla, $p.$b$bEs... difícil... para mí volver a caminar por Suramar. Han pasado diez mil años desde que mis pies sintieron el césped de esta tierra.$b$bEn ese entonces, huíamos de la Legión Ardiente.$b$bNunca creí que volvería al lugar donde nací para quitárselo de las manos de quienes alguna vez creí eran mi gente.', 25549),
(123549, 'esMX', 'Todo listo. Teletranspórtame a Dalaran, en las Islas Quebradas.', 'Todo listo. Teletranspórtame a Dalaran, en las Islas Quebradas.', 25549),
(123548, 'esMX', 'La Legión se cierne sobre nosotros. Contamos con escasos momentos antes de que la tengamos encima.\n\nEs probable que la ola de choque de energías arcanas que estamos por liberar los mande de vuelta a su dimensión maldita por un tiempo. Eso nos daría el tiempo suficiente para descansar y comenzar con la búsqueda de los Pilares de la Creación.\n\n¿Todo listo?', '', 25549),
(123547, 'esMX', '', 'Asegúrate de enseñarle una lección a ese demonio.', 25549),
(123546, 'esMX', 'Trabaja rápidamente, amigo.', '', 25549),
(123545, 'esMX', '', '¡Protegeremos el perímetro!', 25549),
(123544, 'esMX', 'No desperdiciemos este regalo de almas. ¡Sáquenlas de aquí!', '', 25549),
(123543, 'esMX', '¡Vienen más desde Suramar a cada hora! ¡Muévanse! ¡Hagan espacio!', '', 25549),
(123542, 'esMX', '¡No debemos hacer esperar a La Máquina de Almas!', '', 25549),
(123541, 'esMX', '¡Acelera la marcha! ¡La Máquina de Almas nos espera!', '', 25549),
(123540, 'esMX', '¡Que sus cadenas queden totalmente aseguradas!', '', 25549),
(123538, 'esMX', 'Hemos dibujado nuestra línea en la arena. El Helarjar no encontrará cuartel aquí.', '', 25549),
(123537, 'esMX', '¡La peste de los Kvaldir ensucia las costas de Azsuna! ¡Haz que regresen al mar!', '', 25549),
(123536, 'esMX', 'Ahhh... ¡Mucho mejor. Por un momento, nos preocupaste.', '', 25549),
(123535, 'esMX', '¡Tichar! ¡Tu atención!', '', 25549),
(123534, 'esMX', 'Necesitamos un punto de apoyo, desde donde podamos ver lo que ocurre.', '', 25549),
(123533, 'esMX', '', 'DELETE ME', 25549),
(123532, 'esMX', '¡La Máquina de Almas consumirá! ¡Kar Dan''Ashj!', '', 25549),
(123531, 'esMX', 'El pasaje al Bastión Almavil está abierto. Ve que nuestros prisioneros lleguen a su destino.', '', 25549),
(123530, 'esMX', 'Los natos nocturnos han accedido a retirar a sus no deseados.', '', 25549),
(123529, 'esMX', '', '|TInterface\\Icons\\inv_misc_monsterhorn_03.blp:20|t ¡Aparece un %s cerca de Helya!', 25549),
(123528, 'esMX', '|TInterface\\Icons\\INV_Polearm_2H_OdynSpear_D_01.blp:20|t ¡Odyn te marca con una |cFFFF0404|Hspell:228918|h[Lanza tronaforjada]|h|r!', '|TInterface\\Icons\\INV_Polearm_2H_OdynSpear_D_01.blp:20|t ¡Odyn te marca con una |cFFFF0404|Hspell:228918|h[Lanza tronaforjada]|h|r!', 25549),
(123527, 'esMX', 'El Bastión Almavil... de todas las formas en las que nos ha traicionado, esta definitivamente es la peor.', '', 25549),
(123526, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_IMPROVEDFIRENOVA:20|t¡Sombra de Medivh comienza a lanzar |cFFF00000|Hspell:228269|h[Corona de llamas]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_IMPROVEDFIRENOVA:20|t¡Sombra de Medivh comienza a lanzar |cFFF00000|Hspell:228269|h[Corona de llamas]|h|r!', 25549),
(123525, 'esMX', '', 'Las circunstancias actuales nos convierten en aliados.', 25549),
(123524, 'esMX', '', 'Es una reacción apropiada. Normalmente me vería en la obligación de matarlos a ambos.', 25549),
(123523, 'esMX', '', '... Como digas.', 25549),
(123522, 'esMX', '|TInterface\\Icons\\INV_Misc_Horn_03:20|t ¡Hymdall comienza a tocar el |cFFFF0404|Hspell:228012|h[Cuerno de valor]|h|r!', '|TInterface\\Icons\\INV_Misc_Horn_03:20|t ¡Hymdall comienza a tocar el |cFFFF0404|Hspell:228012|h[Cuerno de valor]|h|r!', 25549),
(123521, 'esMX', 'Tu vial imbuido de magia arcana se entibia a medida que emana una suave luz.', 'Tu vial imbuido de magia arcana se entibia a medida que emana una suave luz.', 25549),
(123520, 'esMX', '', 'Alturus, ¡cuidado! Oh, ¿eres tú, $n? Luces... diferente.', 25549),
(123519, 'esMX', '¡Por aquí, $n! La archimaga Leryda y yo los detendremos lo más que podamos, ¡pero debes apresurarte!', '', 25549),
(123518, 'esMX', 'Gracias por venir. Estamos aquí para hablar sobre nuestros intereses en común.', '', 25549),
(123517, 'esMX', 'Thalyssra, tus conocimientos sobre el enemigo serán cruciales en la batalla que está por suceder. Te llamaremos según sea necesario.', '', 25549),
(123516, 'esMX', '[CUT]We share a common goal. We must stop the Burning Legion and Gul''dan at all costs.', '', 25549),
(123515, 'esMX', 'Gracias por venir. Estamos aquí para hablar sobre nuestros intereses en común.', '', 25549),
(123514, 'esMX', '', 'Hay una cura para nuestra adicción, pero tomará tiempo administrarla a toda nuestra gente. Primero, debemos derrocar a Elisande y liberar a Suramar de la inmundicia de la Legión.', 25549),
(123513, 'esMX', '', 'Purificar es lo que haremos. Los sin''dorei liberan una furia justa sobre nuestros enemigos.', 25549),
(123512, 'esMX', '', 'Entiendo que los esfuerzos de los Caídos de la noche se asimilan a los nuestros, Primera Arcanista. Adicción, traición.', 25549),
(123511, 'esMX', 'BORRAR', '', 25549),
(123509, 'esMX', '', '[CUT]If that is your wish, so be it. When this war is won, my people will need allies. It is clear you will not be among them.', 25549),
(123508, 'esMX', '', 'No pretendemos ser esclavos de la Fuente de la Noche. Buscamos alejar a la Legión de Suramar y poner un fin a la opresión de Elisande.', 25549),
(123507, 'esMX', '', 'Sabemos adónde nos llevará el camino de Elisande, y te pedimos ayuda para acabar con su reino.', 25549),
(123506, 'esMX', '', 'Y cuando tu rival esté derrotado, ¿por qué deberíamos asumir que no nos traicionarás por el poder arcano de la Fuente de la Noche y te convertirás en $Gel:la; siguiente Elisande... o $Gel:la; siguiente Azshara?', 25549),
(123505, 'esMX', '', 'Los kaldorei pelearán para ver que la Legión sea derrotada y la Fuente de la Noche sea destruida. Después de eso... debemos ver dónde nos guiará el conocimiento de Elune.', 25549),
(123504, 'esMX', '', 'Arcanista Thalyssra. Recuerdo el bando de tu orden en la Guerra de los ancestros. ¿Cómo saber que no nos traicionarás para convertirte en la próxima Elisande... la próxima Azshara?', 25549),
(123503, 'esMX', 'Relájate y disfruta la trama del espectáculo que llamamos... "Malbaba"', '', 25549),
(123502, 'esMX', '¡La miserable nos encerró a todos!  Pero debió comportarse de otros modos.', '', 25549),
(123501, 'esMX', '¡Malditos diablillos! ¡A trabajar!', '', 25549),
(123500, 'esMX', '¡Déjennos en paz, pestes!', '', 25549),
(123499, 'esMX', '', 'Lasuel y yo somos amigos desde la infancia. Hemos pasado los mejores momentos de nuestras vidas juntos.', 25549),
(123498, 'esMX', '¡La bruja marina debe aprender el precio de su impertinencia!', '', 25549),
(123497, 'esMX', '¡Ya me harté de los juegos de esa horrible bruja!', '', 25549),
(123496, 'esMX', 'Hay que detener a Helya. ¡Llegó la hora de ajustar cuentas!', '', 25549),
(123495, 'esMX', 'La magia vil de Helya contiene a Odyn y detiene a los Valarjar. Necesitamos campeones como tú para frenar su avance.', '', 25549),
(123494, 'esMX', 'Sospecho que la bruja marina se impacienta cada vez más, ansiosa por compensar su campaña al conquistar las Islas Quebradas.', '', 25549),
(123493, 'esMX', '¡Noooooo!', '', 25549),
(123492, 'esMX', 'Llegas... demasiado tarde...', '', 25549),
(123491, 'esMX', '¡Helya hace señas!', '', 25549),
(123490, 'esMX', '¡Todos repórtense! ¡Debemos poner manos a la obra!', '', 25549),
(123489, 'esMX', '¡Trabaja el doble, o terminarás $Gmuerto:muerta;!', '', 25549),
(123487, 'esMX', '', '¡Que esta fallida rebelión sea una lección para cualquiera que se oponga a los shal''dorei!', 25549),
(123486, 'esMX', '', '¡Pero Suramar no olvida! Somos los natonocturnos, los últimos elfos verdaderos. El resto de ustedes son ecos vacíos de nuestra grandeza.', 25549),
(123485, 'esMX', '', 'Han denigrado el orgullo de su linaje. Han olvidado el poder antiguo que era nuestro derecho de nacimiento.', 25549),
(123484, 'esMX', '', '¿Sin''dorei? De todos los elfos, pensé que ustedes podrían entender la elección que tomé para salvar a mi pueblo. Pero, en su lugar, se han aliado con monstruos e inadaptados.', 25549),
(123483, 'esMX', '', '¿Quel''dorei? Ustedes son campesinos jugando a ser nobles, deseosos de juntarse con razas inferiores que diluyen su linaje. Son indignos del nombre de los altos elfos.', 25549),
(123482, 'esMX', '', '¿Kaldorei? Deshonran un glorioso pasado, escondiéndose en árboles y cubriéndose en falsa piedad. Se han vuelto tan salvajes como los trols que merodean por sus bosques.', 25549),
(123481, 'esMX', '', 'Contempla a este gentío en el que los rebeldes posan su fe.', 25549),
(123480, 'esMX', '$GForastero:Forastera;, ¿me oyes? ¿$GForastero:Forastera;? ¡Teletransportaré una baliza a tu ubicación!', '', 25549),
(123479, 'esMX', 'Pa... padre... Corre...', '', 25549),
(123477, 'esMX', '¡Arriba! ¡Hay que partir!', '', 25549),
(123476, 'esMX', '', 'Sé donde encontrar a Shal''Aran. Vamos, chicas. Ya no estamos a salvo en esta ciudad.', 25549),
(123474, 'esMX', '', 'Te dije que no dieras otro paso.', 25549),
(123473, 'esMX', '', '%s escupe sobre el cadáver del demonio.', 25549),
(123472, 'esMX', '¡Oh, gracias! Esta obra maestra es más valiosa que mi propia vida.', '', 25549),
(123471, 'esMX', '¿Dónde está? ¿El jarrón del maestro?', '', 25549),
(123469, 'esMX', 'Bendito sea el cielo... están a salvo. Vamos, ¡salgamos de aquí!', '', 25549),
(123468, 'esMX', '¿Brigitte? ¡¿Emille?! ¿Dónde están?', '', 25549),
(123461, 'esMX', 'Elisande sabe acerca de la participación de Vanthir en la rebelión. Ya se fue.', '', 25549),
(123460, 'esMX', '', 'Es demasiado tarde para mí. Se llevaron a... Vanthir...', 25549),
(123459, 'esMX', 'BORRAR', '', 25549),
(123457, 'esMX', 'No hay que retrasarse. Ve al módulo.', '', 25549),
(123456, 'esMX', 'BORRAR', '', 25549),
(123455, 'esMX', '¡Helya puede corromper a los Tronaforjados!', '¡Helya puede corromper a los Tronaforjados!', 25549),
(123454, 'esMX', '¡Como se atreve a oponerse a mí tan descaradamente!', '', 25549),
(123453, 'esMX', 'Al ver a su maestro morir, ¡Medianoche desata toda su furia!', 'Al ver a su maestro morir, ¡Medianoche desata toda su furia!', 25549),
(123452, 'esMX', '¿Helya tomó las almas de esos Valarjar? ¡Es imposible! Acaba con sus místicos y luego regresa a mí.', '', 25549),
(123451, 'esMX', 'Esto es demasiado... si me tienen que considerar traidor, ¡pues que así sea!', 'Esto es demasiado... si me tienen que considerar traidor, ¡pues que así sea!', 25549),
(123450, 'esMX', '¡Hay que detener a Elisande!', '¡Hay que detener a Elisande!', 25549),
(123449, 'esMX', '¡Sabía que habían otros! ¡Ya no mancharé mis manos con sangre por Elisande!', '¡Sabía que habían otros! ¡Ya no mancharé mis manos con sangre por Elisande!', 25549),
(123448, 'esMX', 'No dije nada cuando llegaron los demonios, pero esto... esto es horrible.', 'No dije nada cuando llegaron los demonios, pero esto... esto es horrible.', 25549),
(123447, 'esMX', 'No puedo creer lo que Elisande le está haciendo a su propia gente. ¡Debo contraatacar!', 'No puedo creer lo que Elisande le está haciendo a su propia gente. ¡Debo contraatacar!', 25549),
(123446, 'esMX', 'Creí que era el único... ¡Estoy de lado del Lirio crepuscular!', 'Creí que era el único... ¡Estoy de lado del Lirio crepuscular!', 25549),
(123445, 'esMX', '¿¡Te atreves a presentarte aquí!? ¡Muere, villano!', '¿¡Te atreves a presentarte aquí!? ¡Muere, villana!', 25549),
(123444, 'esMX', '¡Elisande me felicitará por matarte!', '¡Elisande me felicitará por matarte!', 25549),
(123443, 'esMX', '¡Rebelde! ¡Acabaré contigo!', '¡Rebelde! ¡Acabaré contigo!', 25549),
(123442, 'esMX', '¡Eres uno de ellos! ¡Muere, intruso!', '¡Eres uno de ellos! ¡Muere, intrusa!', 25549),
(123441, 'esMX', '¡Traidor!', '¡Traidora!', 25549),
(123440, 'esMX', 'Por eones, Helya ha formado su ejercito. Robándose las almas de los vrykul caídos para oponerse a los Valarjar.', '', 25549),
(123439, 'esMX', '¿Qué necesitas?', '¿Qué necesitas?', 25549),
(123438, 'esMX', 'La debilidad nunca se tolera.', '', 25549),
(123436, 'esMX', '|TInterface\\Icons\\SPELL_SHADOW_LIFEDRAIN02:20|t¡%s comienza a |cFFFF0000|Hspell:228835|h[Absorber vitalidad]|h|r de |cFFFF0000$n|r!', '', 25549),
(123435, 'esMX', '¡|TInterface\\Icons\\Spell_Shadow_Charm:20|t%s inhala profundamente para un |cFFFF0000|Hspell:228837|h[Rugido bramante]|h|r!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(123434, 'esMX', '', '|TInterface\\Icons\\achievement_dungeon_MawofSouls.blp:20|t Una densa niebla cubre la bahía...', 25549),
(123433, 'esMX', '', '|TInterface\\Icons\\SPELL_SHAMAN_TIDALWAVES.BLP:20|t %s invoca a la |cFFFF0000|Hspell:228300|h[Furia de las fauces]|h|r. ¡Ve a tierra alta!', 25549),
(123432, 'esMX', '¡Cuiden sus modales!', '', 25549),
(123431, 'esMX', '¡Insisto en que te vistas para cenar!', '', 25549),
(123430, 'esMX', 'Maestro... espero... haberle servido...', '', 25549),
(123429, 'esMX', 'Definitivamente los guardias deben hacer un mejor trabajo manteniendo lejos a los rufianes.', '', 25549),
(123428, 'esMX', 'Unidades de aseo: comiencen descontaminación de la Sala de las Fieras.', '', 25549),
(123427, 'esMX', 'El maestro no ha sido él mismo durante algún tiempo. ¡Tal vez un festín avive su espíritu!', '', 25549),
(123426, 'esMX', 'Protocolos disuasivos exitosos.', '', 25549),
(123425, 'esMX', '¡Detesto a los aguafiestas!', '', 25549),
(123424, 'esMX', '¡DISUASIVO ACTIVADO!', '', 25549),
(123423, 'esMX', 'Contramedidas enviadas.', '', 25549),
(123422, 'esMX', 'Fallo... de sistema... in... mi... nente...', '', 25549),
(123421, 'esMX', 'Bienvenidos a... ¡ACABEN CON LOS INTRUSOS!', '', 25549),
(123420, 'esMX', 'Efectos de sonido para las tropas.', '', 25549),
(123419, 'esMX', 'Buen espectáculo, viejo amigo. Consigamos algo de avena para ti.', '', 25549),
(123418, 'esMX', 'Mi... larga cacería... ha terminado.', '', 25549),
(123417, 'esMX', 'Hoy en día cazamos por deporte... ¡y por la gloria de la matanza!', '', 25549),
(123416, 'esMX', 'Ah, fiel Medianoche. Por muchos años nuestras incontables cacerías han provisto una mesa abundante para el amo.', '', 25549),
(123415, 'esMX', '', 'Mrgrrlmgrr.', 25549),
(123413, 'esMX', 'Esta acción cuesta 5|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 'Esta acción cuesta 5|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 25549),
(123412, 'esMX', 'Esta acción cuesta 15|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 'Esta acción cuesta 15|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 25549),
(123411, 'esMX', 'Esta acción cuesta 10|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 'Esta acción cuesta 10|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 25549),
(123410, 'esMX', '', 'Me chocan… todos ustedes... krakus.', 25549),
(123409, 'esMX', '', 'Algunos tienen... makakuidad... estocadas... en ellos...', 25549),
(123408, 'esMX', '', 'Si valoras mi amistad, harás que el Hozen se deshaga de estos intrusos... ¡luego iremos a ver al mago!', 25549),
(123407, 'esMX', '', 'Ya... murió... la malbaba...', 25549),
(123406, 'esMX', 'Te pregunto, $r. ¿Ese es el Cetro de Sargeras? ¡Claro que sí! Tienes la parte sórdida de la historia en tus manos, ¿eh?', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123405, 'esMX', 'Ah, bien. Aquí viene $n con el Cetro de Sargeras. Ya sabes, por si necesitamos abrir un agujero en el espacio-tiempo y hacer añicos el planeta.', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123404, 'esMX', '', 'Este apesta a energía vil. ¡Oye, brujo! ¿Ese es el Cetro de Sargeras? ¿Cómo lograste que el Kirin Tor te lo diera?', 25549),
(123403, 'esMX', '', '¡ERES tú! Ven, amor mío. ¡Es hora de vivir felices para siempre!', 25549),
(123402, 'esMX', 'Bella... ¡soy yo!', '', 25549),
(123401, 'esMX', '', '<Jadeando> ¡¿Quién eres?!', 25549),
(123400, 'esMX', 'Es... demasiado... tarde...', '', 25549),
(123399, 'esMX', '', '¡No! Nuestras cenas juntos... esas horas en la biblioteca... Oh, bruto, ¡te amo!', 25549),
(123398, 'esMX', 'La maldición... me está... matando...', '', 25549),
(123397, 'esMX', '¡Funciona! ¡Funciona!', '', 25549),
(123396, 'esMX', '', '¡Oooooh, amo los libros!', 25549),
(123395, 'esMX', 'Bien. Oye, ¿te gustan los libros?', '', 25549),
(123394, 'esMX', '', '¡Ahí tienes otra vez!', 25549),
(123393, 'esMX', 'No grito TODO el tiempo. ¿POR QUÉ SIEMPRE DICES ESO?', '', 25549),
(123392, 'esMX', '', 'Si no hubieras gritado todo el tiempo, no hubiera escapado.', 25549),
(123391, 'esMX', 'Oh, no, no, no... ¡esto no servirá! ¡Ustedes, forasteros, arruinarán nuestra última oportunidad de romper la maldición!', '', 25549),
(123390, 'esMX', '¡Bien! ¡Muere de hambre, no me importa!', '', 25549),
(123389, 'esMX', '', '¡Jamás! Solamente ceno con caballeros, ¡no con brutos como tú!', 25549),
(123388, 'esMX', '¡El amo de este castillo! ¡Serás mi invitada a cenar!', '', 25549),
(123387, 'esMX', '', '¿Quién… quién eres?', 25549),
(123386, 'esMX', '', 'Solo la belleza... puede matar... al bruto...', 25549),
(123385, 'esMX', '', '¡Eso te enseñará a coquetear con mi novio!', 25549),
(123384, 'esMX', '', 'Eso no salió del todo bien, ¿o sí?', 25549),
(123383, 'esMX', '', 'Parece que estoy... durmiendo en... la alacena.', 25549),
(123382, 'esMX', '', '¡Espero no arruinar su apetito, dulzuras!', 25549),
(123381, 'esMX', 'El amor verdadero, ¡cómo arde!', '', 25549),
(123380, 'esMX', '¡Rápido! ¡Deshazte de ellos!', '', 25549),
(123379, 'esMX', 'No... tomes... la... vela...', '', 25549),
(123378, 'esMX', '¡La vela MÍA!', '', 25549),
(123377, 'esMX', 'Parece... que mi rosa... se ha... marchitado...', '', 25549),
(123376, 'esMX', '¡Nunca te interpongas en el camino del verdadero amor!', '', 25549),
(123375, 'esMX', '¡Encantador! ¡Un invitado menos para la cena!', '', 25549),
(123374, 'esMX', '¡Luminore! ¡Sra. Calderos! ¡Babblet! ¡Dispersémonos con estos intrusos!', '', 25549),
(123373, 'esMX', '¡Averigua por ti mismo si la rosa de la pasión florece bajo una apariencia bestial! Y ahora... ¡vamos con el espectáculo!', '', 25549),
(123372, 'esMX', '¿Podrá la hermosa Bella aprender a amar al malhumorado Bruto? ¿O una maldición fantasmagórica reclamará las vidas del príncipe y sus sirvientes?', '', 25549),
(123371, 'esMX', 'Esta noche... un cuento de ira y romance, uno que demostrará de una vez por todas si la belleza es más que superficial.', '', 25549),
(123370, 'esMX', 'Buenas noches damas y caballeros. Orgullosamente les damos la bienvenida a la presentación programada para esta noche.', '', 25549),
(123369, 'esMX', '', 'De seguro que este sacerdote nos ayudará, Mardranel. Puedo sentir una gran emanación de energía sagrada de su bastón… poderosa, aunque contenida.', 25549),
(123368, 'esMX', 'Sacerdote… ese bastón que llevas… es inestable. Puedo sentir el caos que emana desde aquí.', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123367, 'esMX', '¡Será mejor que digas la verdad, Rezzle!', '¡Será mejor que digas la verdad, Rezzle!', 25549),
(123366, 'esMX', 'Pues bien, continúa.', 'Pues bien, continúa.', 25549),
(123365, 'esMX', '<Rezzle se asusta y se agacha para estar más cerca de la piedra a sus pies.>$B$B¡No pegarle a Rezzle! Si $Gamigo:amiga; le hace daño a Rezzle, Rezzle no podrá $Gayudarlo:ayudarla;.$B$B¡Rezzle sabe cosas para ayudar a $Gamigo:amiga;!', '', 25549),
(123364, 'esMX', 'Maestra ordenar mantener a los mortales fuera de torre. Su maestro necesitar torre para magia MUY grande. ¡En Legión Ardiente, incluso los maestros tener maestros!', '', 25549),
(123363, 'esMX', 'No me sirves para nada, ¡demonio!', 'No me sirves para nada, ¡demonio!', 25549),
(123362, 'esMX', 'Olvídalo. TÚ eres la tormenta.', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123361, 'esMX', '%s observa las armas de $n.', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123360, 'esMX', 'Cuidado, monje. Se avecina una tormenta.', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123359, 'esMX', '¡No tengo tiempo para juegos! Háblame de tu maestro.', '¡No tengo tiempo para juegos! Háblame de tu maestro.', 25549),
(123358, 'esMX', 'Sí... ¡SÍ! ¡Rezzle sabe obedecer! Rezzle obedece...$B$B<El demonio mira a su alrededor nerviosamente.>', '', 25549),
(123357, 'esMX', '¿Así que eres un sirviente?', '¿Así que eres un sirviente?', 25549),
(123356, 'esMX', 'Rezzle no sabe magia, $Gamigo:amiga;. ¡Rezzle solo sabe acarrear cosas!$B$BSi Rezzle aprende magia, Rezzle no reúne muestras para su maestra...$B$B<Con una gran sonrisa de superioridad.>$B$BRezzle crear su propia magia.', '', 25549),
(123355, 'esMX', 'Necesito que me saquen de aquí.', 'Necesito que me saquen de aquí.', 25549),
(123354, 'esMX', 'El Zarzal es un lugar peligroso. ¿Quieres que te saque de aquí?', '', 25549),
(123353, 'esMX', '¿Magia? ¿Qué clase de magia?', '¿Magia? ¿Qué clase de magia?', 25549),
(123352, 'esMX', '¡Rezzle seguir las ordenes de la maestra!$B$BRezzle solo reúne muestras de magia.', '', 25549),
(123351, 'esMX', 'Mira aquí, Brulf. $gEste:Esta; de aquí tiene la furia de la tormenta en sus manos. ¡Jaja, sigue luchando, $r!', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123350, 'esMX', 'Traes contigo la furia de los vientos a Tótem del Trueno, monje. Parece como si tuvieras una nube de tormenta en cada puño.', 'Traes contigo la furia de los vientos a Tótem del Trueno, monje. Parece como si tuvieras una nube de tormenta en cada puño.', 25549),
(123349, 'esMX', '¡A medida que Medianoche se debilita, el Montero procede a atacar!', '¡A medida que Medianoche se debilita, el Montero procede a atacar!', 25549),
(123348, 'esMX', 'Hay un frío penetrante en el aire… y aquí está la fuente. Este mago porta el bastón del primer guardián.', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123347, 'esMX', '¿Por qué debería dejarte con vida, demonio?', '¿Por qué debería dejarte con vida, demonio?', 25549),
(123346, 'esMX', 'Es bueno ver el gran bastón de Alodi en las manos de $gun mago:una maga; de tu destreza, $n. ¡El Kirin Tor cuenta contigo!', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123345, 'esMX', '¿Qué haces aquí?', '¿Qué haces aquí?', 25549),
(123344, 'esMX', '<Inhalando fuerte y mascullando sus palabras.>$B$B¡No! ¡$GAmigo:Amiga; no deber dañar a Rezzle!', '', 25549),
(123343, 'esMX', '', 'Ohhh… ¿sientes eso? ¿El calor en el aire? Una gran luz brilla en el interior del bastón de este sacerdote extraño…', 25549),
(123338, 'esMX', '', 'Ayúdanos… sacerdote… tu bastón brilla con una luz que nunca había visto…', 25549),
(123337, 'esMX', '', '$n, ¿portas dos colmillos de demonios? ¡Me gusta tu forma de pensar!', 25549),
(123336, 'esMX', '', 'Pícaro, ¿acaso son… colmillos de demonio? ¿Usas dientes de demonio como armas? ¡Qué asco!', 25549),
(123335, 'esMX', '¡Oh, sí, $n! Esas dagas que tienes ahí pueden cortar como una franja a la Legión, ¿no? ¿Esas son mordeduras de demonio? ¿Acaso muerden la mano de quien les da de comer? Me gusta lo que veo.', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123334, 'esMX', 'Ah. ¡AH! $gCazador:Cazadora;. Ese arco tuyo es el arma de un campeón. Puedo sentir que ya no está en este mundo, ¿cierto?', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123333, 'esMX', '', 'Un momento, $n. ¿Ese es el arco antiguo del Brisaveloz? Mi padre luchó junto a Alleria en la segunda guerra. Nunca pensé que volveríamos a ver esa arma…', 25549),
(123332, 'esMX', '¿Ves, Farah? $n está aquí. Mientras el espíritu de Ursoc camine entro nosotros, no tenemos por qué temerles a las arpías.', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123331, 'esMX', 'La vagoneta de fruta de Ramanzano suele estar en la zona suroeste de Dalaran.', 'La vagoneta de fruta de Ramanzano suele estar en la zona suroeste de Dalaran.', 25549),
(123330, 'esMX', 'Los instructores de minería y los vendedores de suministros se encuentran arriba en Tanques para Todo, en el Mercado de Magos, en la zona noroeste de Dalaran.', 'Los instructores de minería y los vendedores de suministros se encuentran arriba en Tanques para Todo, en el Mercado de Magos, en la zona noroeste de Dalaran.', 25549),
(123329, 'esMX', 'Los Colmillos de Ashamane… ¡qué cosas maravillosas portas, $n! El gran espíritu de la pantera murió en combate contra la Legión en la arboleda de aquí abajo.', 'Los Colmillos de Ashamane… ¡qué cosas maravillosas portas, $n! El gran espíritu de la pantera murió en combate contra la Legión en la arboleda de aquí abajo.', 25549),
(123328, 'esMX', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 'Los demás no me confundieron… ¡fue el espíritu de Ursoc el que llegó a Tótem del Trueno!', 25549),
(123327, 'esMX', 'Puedo sentir el espíritu de una bestia salvaje dentro de ti, druida. Parece que Ashamane nos vuelve a acechar.', 'Puedo sentir el espíritu de una bestia salvaje dentro de ti, druida. Parece que Ashamane nos vuelve a acechar.', 25549),
(123326, 'esMX', '', 'Veo que recuperaste las Garras de Ursoc del Sueño Esmeralda. ¿Puedes igualar su tenacidad, druida?', 25549),
(123325, 'esMX', '', 'Veo que llevas las Garras de Ashamane, druida. Todavía contamos sus historias de valentía en toda la arboleda.', 25549),
(123324, 'esMX', 'Me gustaría volver a presenciar la caída de Illidan Tempestira en el Templo Oscuro, Xe''ra.', 'Me gustaría volver a presenciar la caída de Illidan Tempestira en el Templo Oscuro, Xe''ra.', 25549),
(123323, 'esMX', '¡Estás de suerte! Una tienda llamada Cosas del Pasado abrió sus puertas hace poco en el Mercado de Magos.', '¡Estás de suerte! Una tienda llamada Cosas del Pasado abrió sus puertas hace poco en el Mercado de Magos.', 25549),
(123322, 'esMX', 'La Cámara del Guardián es un centro mágico ubicado en el medio de Dalaran.', 'La Cámara del Guardián es un centro mágico ubicado en el medio de Dalaran.', 25549),
(123321, 'esMX', 'Cámara del guardián', 'Cámara del guardián', 25549),
(123320, 'esMX', 'Los miembros de la Horda que nos visitan suelen quedarse en el Santuario del Brisaveloz, en la zona noreste de Dalaran.$B$BAllí hay una posada, además de portales a varias ciudades.', 'Los miembros de la Horda que nos visitan suelen quedarse en el Santuario del Brisaveloz, en la zona noreste de Dalaran.$B$BAllí hay una posada, además de portales a varias ciudades.', 25549),
(123319, 'esMX', 'Los miembros de la Alianza que nos visitan suelen quedarse en El Enclave del Colmillo Gris, en la zona sudoeste de Dalaran.$B$BAllí hay una posada, además de portales a varias ciudades.', 'Los miembros de la Alianza que nos visitan suelen quedarse en El Enclave del Colmillo Gris, en la zona sudoeste de Dalaran.$B$BAllí hay una posada, además de portales a varias ciudades.', 25549),
(123318, 'esMX', 'El Alto de Krasus se encuentra en la parte más oriental de Dalaran.$B$BEl maestro de vuelo de la ciudad se encuentra allí.', 'El Alto de Krasus se encuentra en la parte más oriental de Dalaran.$B$BEl maestro de vuelo de la ciudad se encuentra allí.', 25549),
(123317, 'esMX', 'Estás buscando El Animal Roñoso en el cuartel de la Horda del Santuario del Brisaveloz, en la zona noreste de Dalaran.$B$BDicen que es un lugar un poco tosco, pero que alberga a un excelente instructor de cocina en su interior.', 'Estás buscando El Animal Roñoso en el cuartel de la Horda del Santuario del Brisaveloz, en la zona noreste de Dalaran.$B$BDicen que es un lugar un poco tosco, pero que alberga a un excelente instructor de cocina en su interior.', 25549),
(123316, 'esMX', 'La Bienvenida de un Héroe se encuentra junto a El Enclave del Colmillo Gris, en la zona sudoeste de Dalaran.$B$BEse lugar tiene una terraza y a uno de los mejores instructores de cocina de la ciudad.', 'La Bienvenida de un Héroe se encuentra junto a El Enclave del Colmillo Gris, en la zona sudoeste de Dalaran.$B$BEse lugar tiene una terraza y a uno de los mejores instructores de cocina de la ciudad.', 25549),
(123315, 'esMX', 'Un lugar vil lleno de matones y criminales que no huelen bien.$B$BHay al menos tres maneras de llegar: las entradas al este y al oeste, y un pozo en el norte.', 'Un lugar vil lleno de matones y criminales que no huelen bien.$B$BHay al menos tres maneras de llegar: las entradas al este y al oeste, y un pozo en el norte.', 25549),
(123314, 'esMX', 'Los Bajos Fondos', 'Los Bajos Fondos', 25549),
(123313, 'esMX', '¡Los demonios de la Legión Ardiente no saben lo que les espera si piensan que el viejo Angus está acabado! ¡Tengo más trucos bajo la manga que un mago de Dalaran!', '', 25549),
(123312, 'esMX', 'El sabueso gruñe.', '', 25549),
(123311, 'esMX', 'El sabueso mira en tu dirección', '', 25549),
(123310, 'esMX', 'El sabueso huele el aire ansiosamente.', '', 25549),
(123309, 'esMX', '¡Cabalgamos, Medianoche! ¡A la victoria!', '', 25549),
(123308, 'esMX', '¡Hora de enfrentarme a mi presa cara a cara!', '', 25549),
(123307, 'esMX', '¡Mi presa jamás escapa!', '', 25549),
(123306, 'esMX', '¡Formen filas! ¡A la carga!', '', 25549),
(123305, 'esMX', 'Ahora… el cazado… soy yo.', '', 25549),
(123304, 'esMX', '¡Levántate, Medianoche! ¡Conviértelos en polvo!', '', 25549),
(123303, 'esMX', '¡Bien hecho, Medianoche!', '', 25549),
(123302, 'esMX', '¡No tenían ninguna oportunidad! ¡Vivo para matar!', '', 25549),
(123301, 'esMX', '¡Presa fácil!', '', 25549),
(123300, 'esMX', '¡Mi colección de trofeos crece!', '', 25549),
(123299, 'esMX', '¡Bien, bien! ¡Otro grupo de ladrones que intenta robarse mi caballo!', '', 25549),
(123298, 'esMX', 'Deberíamos salir de aquí antes de que sea demasiado tarde.', '', 25549),
(123297, 'esMX', 'Este ni siquiera es humano.', '', 25549),
(123296, 'esMX', 'Pensaste que esos eran mis huesos… ¿cierto?', '', 25549),
(123295, 'esMX', '¿Qué hay con todos estos huesos?', '', 25549),
(123294, 'esMX', '¿Qué? Ah… ya que lo mencionas…', '', 25549),
(123293, 'esMX', 'Sí...', '', 25549),
(123292, 'esMX', 'Eeehh… ¿qué huesos? Ah, ¿te refieres a estos? Esteee, yo…', '', 25549),
(123291, 'esMX', '¡Brambley! No puedo creer lo que ven mis ojos… ¡Estás vivo!', '', 25549),
(123290, 'esMX', 'Existe un... lugar para nosotros... en algún lugar...', '', 25549),
(123289, 'esMX', 'Nunca... dejaré de decir... Mrrgria...', '', 25549),
(123288, 'esMX', '¡Ya Les cabe una tumba, bandidos!', '', 25549),
(123287, 'esMX', '¡Una pandilla que no es dueña de los campos no es nada!', '', 25549),
(123286, 'esMX', 'Adelante... ¡vete!', '', 25549),
(123285, 'esMX', '¡Lárgate!', '', 25549),
(123284, 'esMX', '¡Bailemos!', '', 25549),
(123283, 'esMX', 'Así que quieres luchar, ¿no es así?', '', 25549),
(123282, 'esMX', '¡Somos tu yo contra el mundo, sí!', '', 25549),
(123281, 'esMX', 'Solo voy a... actuar natural.', '', 25549),
(123280, 'esMX', '¡Ay! Qué zancadillazo!', '', 25549),
(123279, 'esMX', '¿Quieres ir por un paseo?', '', 25549),
(123278, 'esMX', 'Al retumbar la canción de su amor por todo el campo, ¿terminará en triunfo... o tragedia? Y ahora... ¡qué siga el espectáculo!', '', 25549),
(123277, 'esMX', 'Divididos por generaciones de odio, se han reunido por la pasión de la danza... ¡y la violencia!', '', 25549),
(123276, 'esMX', 'Esta noche... unimos a dos amantes nacidos en lugares opuestos de Colina del Centinela.', '', 25549),
(123275, 'esMX', '¡Damas y caballeros, bienvenidos a la presentación estelar de esta tarde!', '', 25549),
(123274, 'esMX', '¿Qué vendes, Moorgoth?', '¿Qué vendes, Moorgoth?', 25549),
(123273, 'esMX', 'Agradezco tu ayuda, $n. Estoy seguro de que mi suerte cambiará pronto.$b$bDime algo, ¿crees que mi armadura se ve bien oscura?', '', 25549),
(123272, 'esMX', '¡Dejen de perturbar a los invitados del maestro!', '', 25549),
(123271, 'esMX', '¿Quiere que tome su chamarra?', '', 25549),
(123270, 'esMX', 'Creo que... me retiraré... por esta jornada...', '', 25549),
(123269, 'esMX', 'Tal vez tu grupo se sentiría más cómodo en la mesa de los niños.', '', 25549),
(123268, 'esMX', '¡No creo que el maestro los esté esperando!', '', 25549),
(123267, 'esMX', '¡Un sanador para Willy! No he visto a un gnomo así de pálido desde... ay, espera, todos los gnomos son pálidos.', '', 25549),
(123266, 'esMX', '', '¡¿Has visto eso?! ¡Un vapor ambulante de nivel épico! ¡Y algo desagradable también!', 25549),
(123265, 'esMX', '¡El espía nato nocturno se escapó!', '¡La espía nato nocturna se escapó!', 25549),
(123264, 'esMX', '¡Iuu! ¡Qué asco! Me siento apestoso.', '', 25549),
(123263, 'esMX', '', '¡Eres un individuo afortunado! Por supuesto que necesitaré una muestra de tu tejido cerebral...', 25549),
(123262, 'esMX', '', 'Está bien, está bien… pero el almuerzo corre por tu cuenta.', 25549),
(123261, 'esMX', 'Este de aquí es un desastre. ¡Quiero el trozo gnomótico que está abajo!', '', 25549),
(123260, 'esMX', '¿Te aventurarás a las profundidades de Helheim y matarás a Helya?', '', 25549),
(123259, 'esMX', '¡Lucharé contra ella en tu nombre, Odyn!', '¡Lucharé contra ella en tu nombre, Odyn!', 25549),
(123258, 'esMX', '', 'Lucha con todas tus fuerzas… me gusta que mi presa se sienta exhausta.', 25549),
(123257, 'esMX', '¡Carne fresca para mis sabuesos!', '', 25549),
(123256, 'esMX', '¡Tu alma está perdida!', '', 25549),
(123255, 'esMX', 'Veamos qué es lo que reside en tu alma, mortal.', '', 25549),
(123254, 'esMX', 'Sí… tu cerebro me vendrá muy bien… ¡dámelo!', '', 25549),
(123253, 'esMX', 'Criatura debilucha… ¡Músculo machacarte!', '', 25549),
(123252, 'esMX', '', '¡Mi magia acabará contigo!', 25549),
(123251, 'esMX', '¿Qué le pasó a tu burro?', '¿Qué le pasó a tu burro?', 25549),
(123250, 'esMX', '¿Qué puedo hacer con obliterium?', '¿Qué puedo hacer con obliterium?', 25549),
(123249, 'esMX', '¿Cómo consigo obliterium?', '¿Cómo consigo obliterium?', 25549),
(123248, 'esMX', '¡Cuida tu boca! ¡Desdemona no era un burro, sino una mula!\n\nEn fin, la vendí por tres Sangre de Sargeras. Me voy a comprar unas botas.', '', 25549),
(123247, 'esMX', 'Una vez que tengas la favila de obliterium suficiente, tienes que unirlo y amasarlo hasta formar una bolita. Luego, frótalo en tu armadura, y la armadura se volverá más fuerte.', '', 25549),
(123246, 'esMX', '¡Sencillo! Toma algunas partes de equipamiento, como sombreros, anillos, reliquias, frascos y esas cosas, y arrójalos en este agujerito ardiente. Agrega algo de Sangre de Sargeras como combustible y, ¡voila! ¡Ahí tienes obliterium!\n\nVerás, los fabricantes usan siempre cosas como HIERBA VIL, ACERO DEMONÍACO Y CRISTALES DEL CAOS para hacer su equipo. Esa armadura está cargada con muchas cosas demoníacas. ¡Haz arder esas cosas lo más que puedas y conseguirás obliterium!', '', 25549),
(123245, 'esMX', '¡Hola, $n! ¿Quieres asolar equipos? ¿O quieres usar algo de obliterium para reforzar el equipo que llevas puesto? ¡Entonces soy tu enano! ¡Pregunta nomás!', '', 25549),
(123244, 'esMX', '¡Estás demasiado lejos! ¡Acércate un poco antes de que se escape!', '¡Estás demasiado lejos! ¡Acércate un poco antes de que se escape!', 25549),
(123241, 'esMX', 'La llegada de la Legión no es una sorpresa. El poder bajo la torre existía mucho antes que nosotros mismos.$B$BEs una desgracia que hayamos llegado en estas condiciones, pero supongo que solo era cosa de tiempo.', '', 25549),
(123240, 'esMX', '', 'Como mago, perteneces a un grupo selecto que puede invocar un portal para transportarte de nuevo a este mismo lugar. Puedo enseñarte si estás $gpreparado:preparada;.', 25549),
(123239, 'esMX', '', 'No creo que tengas la agudeza mental para comprender la naturaleza de la magia del portal.', 25549),
(123234, 'esMX', '', 'Salta sobre uno de mis sables de maná y usa los nodos altos de energía Ley que están alrededor tuyo para manejarlo. Reúne toda la energía Ley que puedas para cargarlo por completo, ¡y listo! Recuerda que el sable de maná es bueno para ir a gran velocidad en una línea recta, pero aminora la marcha a la hora de virar. Trata de minimizar la cantidad de correcciones que debas hacer para manejarlo.', 25549),
(123233, 'esMX', '', 'Es muy fácil, en verdad. Dirígete hacia el cubo e interactúa con él para comenzar una partida. Solo sigue el camino que muestra antes de rellenar toda la red y ganarás una partida. Gana varias partidas y el cubo se activará.', 25549),
(123232, 'esMX', '¡Solo quédate dentro de un orbe que surque los aires y podrás volar! ¡Mira, lo estoy haciendo ahora! Salta de orbe en orbe para saber a dónde van.', '', 25549),
(123231, 'esMX', '|TInterface\\Icons\\spell_mage_infernoblast:20|t¡Estás $Gmarcado:marcada; por |cFFF00000|Hspell:227615|h[Saeta Inferno]|h|r!', '', 25549),
(123230, 'esMX', 'Eh, ¿qué?', 'Eh, ¿qué?', 25549),
(123229, 'esMX', 'Quiero experimentar el asedio de Dalaran y la invocación de Alodi.', 'Quiero experimentar el asedio de Dalaran y la invocación de Alodi.', 25549),
(123228, 'esMX', 'Quiero experimentar el regreso de Magni Barbabronce y las aventuras de Khadgar en Karazhan.', 'Quiero experimentar el regreso de Magni Barbabronce y las aventuras de Khadgar en Karazhan.', 25549),
(123227, 'esMX', 'Quiero experimentar la Costa Quebrada y sus consecuencias.', 'Quiero experimentar la Costa Quebrada y sus consecuencias.', 25549),
(123226, 'esMX', '', '¿Quieres escuchar una historia del pasado, $n?', 25549),
(123225, 'esMX', '', 'Tus enemigos sabrán que una vez que los tengas en tu mira les será muy difícil escapar.', 25549),
(123224, 'esMX', '', 'Utilizando tu habilidad Arpón puedes engancharte a tu enemigo e impulsarte hacia él.', 25549),
(123223, 'esMX', '', 'Utiliza Arpón contra el muñeco de entrenamiento objetivo.', 25549),
(123222, 'esMX', '', 'Ahora que has acortado la distancia entre tú y tu presa, es hora de infligirles una herida de la que les cueste trabajo recuperarse.', 25549),
(123221, 'esMX', '', 'Lacerar hará que tu enemigo sangre, lo que le infligirá daño con el tiempo.', 25549),
(123220, 'esMX', '', 'Utiliza Lacerar en el muñeco de práctica.', 25549),
(123219, 'esMX', '', 'Recuerda utilizar Lacerar cuando tu objetivo no se vea afectado.', 25549),
(123218, 'esMX', '', '¡Es hora de atacar a tu objetivo en equipo!', 25549),
(123217, 'esMX', '', 'Golpe lateral es un ataque coordinado entre tú y tu mascota, que puede infligir muchísimo daño.', 25549),
(123215, 'esMX', '', 'Usa Golpe lateral contra el muñeco de práctica.', 25549),
(123214, 'esMX', '', 'Tu mejor táctica es tambalear a tu oponente y aumentar constantemente tu daño hasta derrotarlo.', 25549),
(123213, 'esMX', '', 'Mordedura de mangosta es un ataque que se vuelve más poderoso cada vez que lo usas.', 25549),
(123212, 'esMX', '', 'Acumula cargas de Mordedura de mangosta y lánzalas todas de una sola vez para un efecto completo.', 25549),
(123211, 'esMX', '', 'Usa Mordedura de mangosta contra el muñeco de práctica.', 25549),
(123210, 'esMX', '', '¡Usa Cuchillada para dañar a múltiples enemigos a la vez!', 25549),
(123209, 'esMX', '', '¡Utiliza Fingir muerte para escapar!', 25549),
(123208, 'esMX', '', '¡Utiliza Golpe lateral!', 25549),
(123207, 'esMX', '', '¡Utiliza Arpón!', 25549),
(123206, 'esMX', '', '¡Usa Lacerar!', 25549),
(123205, 'esMX', '', '¡Utiliza Mordedura de mangosta!', 25549),
(123204, 'esMX', '', 'Los cazadores de supervivencia prosperan en el combate a corta distancia, en donde usan una combinación de herramientas para abrumar violentamente a su presa.', 25549),
(123203, 'esMX', '', 'Los Cazador de supervivencia prosperan en el combate a corta distancia, en donde usan una combinación de herramientas para abrumar violentamente a su presa.', 25549),
(123202, 'esMX', '', 'A veces te superarán en número. No te preocupes, puedes desatar la destrucción sobre un grupo de adversarios al mismo tiempo.', 25549),
(123201, 'esMX', '', 'Cuchillada realiza un barrido con tu arma frente a ti para infligir daño a todos los objetivos en su camino.', 25549),
(123200, 'esMX', '', 'Utiliza Cuchillada para despachar a todos los enemigos.', 25549),
(123199, 'esMX', 'Necesito otra piedra de adivinación de maná.', 'Necesito otra piedra de adivinación de maná.', 25549),
(123198, 'esMX', '¡Si te quedas en esta área, te marcarán para una batalla de JcJ!', '¡Si te quedas en esta área, te marcarán para una batalla de JcJ!', 25549),
(123195, 'esMX', '', 'Junto a tu confiable mascota, eres el maestro de tus alrededores. Llamar a mascota hará que tu mascota aparezca.', 25549),
(123194, 'esMX', '', 'Usa Llamar a mascota para que tu mascota entre en el combate.', 25549),
