INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(123154, 'esMX', 'Usa Llamar a mascota para que tu mascota entre en el combate.', '', 25549),
(123152, 'esMX', 'Junto a tu confiable mascota, eres el maestro de tus alrededores. Llamar a mascota hará que tu mascota aparezca.', '', 25549),
(123151, 'esMX', 'Los cazadores de supervivencia luchan en combates cercanos, donde utilizan una combinación de herramientas para acallar a su presa.', '', 25549),
(123150, 'esMX', 'Los cazadores de supervivencia prosperan en el combate a corta distancia, en donde usan una combinación de herramientas para abrumar violentamente a su presa.', '', 25549),
(123149, 'esMX', '¡Hay tan poco tiempo! ¡No puedo trabajar en estas condiciones!', '¡Hay tan poco tiempo! ¡No puedo trabajar en estas condiciones!', 25549),
(123148, 'esMX', 'A este paso, vamos a necesitar más pintura.', 'A este paso, vamos a necesitar más pintura.', 25549),
(123147, 'esMX', '', '¡Mientras la maldición persista, nunca tendremos paz con Farondis!', 25549),
(123146, 'esMX', '', 'Farondis es el responsable de nuestra maldición… ¡lo pagará muy caro!', 25549),
(123145, 'esMX', '¡Usa Ira del chamán!', '', 25549),
(123144, 'esMX', '', '¡Usa Ira del chamán!', 25549),
(123143, 'esMX', '¡Tu voluntad marchita se perderá si los dejas atrás!', '¡Tu voluntad marchita se perderá si los dejas atrás!', 25549),
(123142, 'esMX', 'Atención, invitados: ¡Mueran, mueran, mueran!', '', 25549),
(123141, 'esMX', '¡EXTERMINADO!', '', 25549),
(123140, 'esMX', 'Sobrecarga en progreso. Prepararse para... ¡PURGAR! ¡PURGAR! ¡PURGAR!', '', 25549),
(123139, 'esMX', 'Curator ya no está ope... ra... ti... vo.', '', 25549),
(123138, 'esMX', 'La Sala de las Fieras es para... ¡ERRADICAR, ERRADICAR!', '', 25549),
(123135, 'esMX', 'El arcavino se avinagró... ¡Debes empezar otra vez!', 'El arcavino se avinagró... ¡Debes empezar otra vez!', 25549),
(123134, 'esMX', 'El aroma de la sangre está en el viento.', 'Esta es tu nave, $n. Que la luz te acompañe.', 25549),
(123133, 'esMX', '¿Seguro que quieres omitir la introducción de la Costa Quebrada? \nLa archivista Elysiana en la ciudad de Dalaran de las Islas Quebradas puede volver a darte la misión.', '¿Seguro que quieres omitir la introducción de la Costa Quebrada? \nLa archivista Elysiana en la ciudad de Dalaran de las Islas Quebradas puede volver a darte la misión.', 25549),
(123132, 'esMX', 'Eso ya lo he oído antes... <Omitir las misiones introductorias de la Legión y empezar tu viaje por Dalaran.>', 'Eso ya lo he oído antes... <Omitir las misiones introductorias de la Legión y empezar tu viaje por Dalaran.>', 25549),
(123126, 'esMX', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t ¡Odyn comienza a |cFFFF0404|Hspell:227503|h[Extraer poder]|h|r de las runas!', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t ¡Odyn comienza a |cFFFF0404|Hspell:227503|h[Extraer poder]|h|r de las runas!', 25549),
(123124, 'esMX', '', '¡Grlmgmmrr!', 25549),
(123123, 'esMX', '', 'Mrrmgmrlgmm.', 25549),
(123122, 'esMX', '', 'Mlgrmgrlmgrmrrrmgrrr.', 25549),
(123121, 'esMX', 'Es difícil de creer. ¿No es una broma, o si?', '', 25549),
(123120, 'esMX', '', 'Mgrmglrm.', 25549),
(123119, 'esMX', 'Sentí que sabia algo que nunca había ocurrido, tenía que ocurrir. Pero esto es mucho más.', '', 25549),
(123118, 'esMX', '', 'Grrmgmrlgmrrm.', 25549),
(123117, 'esMX', '¿O nos habremos conocido antes?', '', 25549),
(123116, 'esMX', '', 'Mrgrlglrllrr.', 25549),
(123115, 'esMX', '¿No crees que soy otra persona?', '', 25549),
(123114, 'esMX', '¡BASTA! ¡Demostraste tu gran valor! Contigo como mi valiente, Helya caerá y por fin me liberaré de la maldición que me ata.', '', 25549),
(123113, 'esMX', 'No puedo llegar hasta Dalaran por el Paso de la Muerte para ayudarte, teletranspórtame a Dalaran directamente a las Islas Quebradas.', 'No puedo llegar hasta Dalaran por el Paso de la Muerte para ayudarte, teletranspórtame a Dalaran directamente a las Islas Quebradas.', 25549),
(123112, 'esMX', 'La legión ataca Dalaran en el Paso de la Muerte y parece que van en serio.\n\n¿Por qué no completamos aquí el ritual y nos reunimos en las Islas Quebradas?', '', 25549),
(123111, 'esMX', '', 'No tengo amigos... bueno, aparte de ti, Galindre.', 25549),
(123110, 'esMX', '', '¡Llegará tu hora de volar! Oye, ¿de verdad crees que el mago me quitará lo verde?', 25549),
(123109, 'esMX', '', 'Ja, ja, ja. ¡Pero claro, querida! Ese viejo saco que llevas... ¡Ay, mira! ¡Unos nuevos amigos vinieron a visitarnos!', 25549),
(123108, 'esMX', '', '¡Elfyra, baja de ahí! ¡Te agitas como una de esas horribles criaturas mono!', 25549),
(123106, 'esMX', '¡Comenzar la batalla está en sus manos, héroes!', '', 25549),
(123105, 'esMX', '¡Hymdall! ¡Hyrja! Pongan a prueba el temple de estos mortales. Debo asegurarme de que poseen el coraje y la habilidad necesaria para lo que está por venir.', '', 25549),
(123104, 'esMX', '¡Campeones! Han derramado la sangre de los esbirros de Helya. Llegó la hora de entrar al Helheim y terminar con el reino oscuro de la bruja del mar. Pero primero... ¡un reto final!', '', 25549),
(123103, 'esMX', '¡Pero yo seré el encargado de decidir si mereces los honores o no!', '', 25549),
(123102, 'esMX', 'Parece que he sido demasiado gentil. ¡Aquí voy!', '', 25549),
(123101, 'esMX', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t¡%s está lanzando |cFFFF0000|Hspell:227508|h[Arrepentimiento en masa]|h|r!', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t¡%s está lanzando |cFFFF0000|Hspell:227508|h[Arrepentimiento en masa]|h|r!', 25549),
(123100, 'esMX', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t¡%s te está lanzando |cFFFF0000|Hspell:227789|h[Terreno sagrado]|h|r!', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t¡%s te está lanzando |cFFFF0000|Hspell:227789|h[Terreno sagrado]|h|r!', 25549),
(123099, 'esMX', '|cffADFF2F+$1i Reputación con los Caídos de la Noche|r', '|cffADFF2F+$1i Reputación con los Caídos de la Noche|r', 25549),
(123098, 'esMX', 'a menos que encontremos otra forma de combatirlos.', '', 25549),
(123097, 'esMX', 'El ejército que marcha en Azeroth es tan solo una pequeña parte de la fuerza completa de la Legión.', '', 25549),
(123096, 'esMX', '', 'Te he fallado, Sargeras...', 25549),
(123095, 'esMX', 'Me parece sabio dividir nuestros esfuerzos. Trabajaré para eludir las defensas mágicas de la torre. Tal vez necesites adoptar un enfoque más... agresivo.', '', 25549),
(123078, 'esMX', 'Te daré una muerte rápida, $Gintruso:intrusa;.', 'Te daré una muerte rápida, $Gintruso:intrusa;.', 25549),
(123077, 'esMX', 'He acabado con cientos antes que tú. Solo serás otro más en mi colección.', 'He acabado con cientos antes que tú. Solo serás otro más en mi colección.', 25549),
(123076, 'esMX', 'Limpiaré tu sangre de mi hoja, ¡como la de todos los demás!', 'Limpiaré tu sangre de mi hoja, ¡como la de todos los demás!', 25549),
(123075, 'esMX', '¡Los de tu especie no son bienvenidos aquí!', '¡Los de tu especie no son bienvenidos aquí!', 25549),
(123074, 'esMX', '¡No hay lugar para ti aquí, demonio!', '¡No hay lugar para ti aquí, demonio!', 25549),
(123073, 'esMX', '¡No llegarás más lejos, $Ginvasor:invasora;!', '¡No llegarás más lejos, $Ginvasor:invasora;!', 25549),
(123072, 'esMX', '¡He estado entrenando para este momento!', '¡He estado entrenando para este momento!', 25549),
(123071, 'esMX', '¡$GIntruso:Intrusa;! ¡Haz sonar la alarma!', '¡$GIntruso:Intrusa;! ¡Haz sonar la alarma!', 25549),
(123069, 'esMX', '', '¡Esa fue toda una conmoción!', 25549),
(123068, 'esMX', '', 'Por primera vez, me siento… malbaba.', 25549),
(123067, 'esMX', '', '¿Acaso perdiste tu malbaba cabeza?', 25549),
(123066, 'esMX', '', 'Ese necesitaba un cambio.', 25549),
(123065, 'esMX', '', '¡Elekkamomen otunbuntu rotu kelaramen!', 25549),
(123064, 'esMX', '', 'Contemplen a mis esbirros, ¡y que se hagan escuchar!', 25549),
(123063, 'esMX', '', '¡Llegará tu hora de volar!', 25549),
(123062, 'esMX', '', '¡Siento haberte derribado!', 25549),
(123061, 'esMX', '', '¡Sígueme y serás popular!', 25549),
(123060, 'esMX', '', 'Unidas… ¡Y sin límite!', 25549),
(123055, 'esMX', '', '|TInterface\\Icons\\spell_arcane_arcanetorrent_nightborne:20|t¡Galindre está lanzando |cFFFF0404|Hspell:227776|h[Magia magnífica]|h|r! ¡Usa los vórtices de |TInterface\\Icons\\spell_priest_void blast:20|t|cFFFF0404|Hspell:227405|h[Desafiar gravedad]|h|rpara escapar!', 25549),
(123054, 'esMX', 'Comencemos.', 'Comencemos.', 25549),
(123053, 'esMX', '', '¿Estás $Glisto:lista; para comenzar?', 25549),
(123052, 'esMX', '¿Te acuerdas de esa bruja malvada?  Aprendió todo de una aún más mala.', '', 25549),
(123051, 'esMX', 'El makaku show que vas a ver es algo que crees ya conocer.', '', 25549),
(123050, 'esMX', 'Corta la charla, señor director.  ¡El Rey Mono tiene un plan mejor!', '', 25549),
(123049, 'esMX', 'Bienvenidos, señoras y señores, a nuestro... ¡UFF!', '', 25549),
(123048, 'esMX', '¿Cuál es la misión?', '¿Cuál es la misión?', 25549),
(123047, 'esMX', '', 'Cuento contigo, $n.', 25549),
(123046, 'esMX', '', 'Pero qué gran... tragedia.', 25549),
(123045, 'esMX', '', '¡Este lugar puede soportar el ser Galindreficado!', 25549),
(123044, 'esMX', '', '¡Ahora, por algo más grandioso!', 25549),
(123043, 'esMX', '¡Terminó Signo estelar de %s y provocó un Gran Trígono!', '¡Terminó Signo estelar de %s y provocó un Gran Trígono!', 25549),
(123042, 'esMX', '¡%s y $n chocaron, lo que provocó un Gran Trígono!', '¡%s y $n chocaron, lo que provocó un Gran Trígono!', 25549),
(123040, 'esMX', '¡Salta sobre el efecto para evitar el daño de |cFFFF0404|Hspell:211901|h[Presión de fusión]|h|r!', '¡Salta sobre el efecto para evitar el daño de |cFFFF0404|Hspell:211901|h[Presión de fusión]|h|r!', 25549),
(123039, 'esMX', '<Monta a Picorrecio.>', '<Monta a Picorrecio.>', 25549),
(123038, 'esMX', '<Picorrecio te observa con recelo.>', '', 25549),
(123037, 'esMX', '¡El amor es un ideal anticuado nacido del instinto!', '¡El amor es un ideal anticuado nacido del instinto!', 25549),
(123036, 'esMX', '¡No volveré a la oficina de correspondencia!', '¡No volveré a la oficina de correspondencia!', 25549),
(123035, 'esMX', '¡No me pagan lo suficiente como para hacer esto!', '¡No me pagan lo suficiente como para hacer esto!', 25549),
(123033, 'esMX', 'Sientes que una presencia asombrosa te toca por unos instantes al otro lado del portal...', 'Sientes que una presencia asombrosa te toca por unos instantes al otro lado del portal...', 25549),
(123030, 'esMX', '¿Tienes otro silbato de maestro de vuelo?', '¿Tienes otro silbato de maestro de vuelo?', 25549),
(123029, 'esMX', 'Debes estar debajo del nivel 101 para participar en las invasiones de la Legión.', 'Debes estar debajo del nivel 101 para participar en las invasiones de la Legión.', 25549),
(123028, 'esMX', '|TInterface\\Icons\\ability_mage_arcanebarrage_nightborne:20|t¡Eres el objetivo de |cFFF00000|Hspell:220871|h[Maná inestable]|h|r!', '', 25549),
(123027, 'esMX', 'Tengo que saltar a la arena para destruir a esa monstruosidad. Madre Luna, dame fuerza.', '', 25549),
(123026, 'esMX', 'La Espada de Ébano prevalecerá. Nadie se interpondrá en nuestro camino... y vivirá para contarlo.', '', 25549),
(123024, 'esMX', '¡El Anillo de la Tierra está contigo, Clarividente! ¡Lucharemos junto a ti contra la Legión Ardiente, sin importar el costo!', '', 25549),
(123023, 'esMX', 'Quisiera solicitar algunas tropas Cosecha Oscura.', 'Quisiera solicitar algunas tropas Cosecha Oscura.', 25549),
(123021, 'esMX', '¡Entremos!', '¡Entremos!', 25549),
(123020, 'esMX', '¿Estás $glisto:lista; para entrar al planetario?', '', 25549),
(123019, 'esMX', 'Estoy listo para partir a Karazhan.', 'Estoy lista para partir a Karazhan.', 25549),
(123018, 'esMX', '¡Debes ir con Khadgar y encontrar los pilares, $n!', '', 25549),
(123017, 'esMX', '¡Salvemos a Magni!', '¡Salvemos a Magni!', 25549),
(123016, 'esMX', '¿Estás $glisto:lista; para que disipe esta barrera?', '', 25549),
(123014, 'esMX', '¿Brann Barbabronce? Qué sorpresa.', '', 25549),
(123013, 'esMX', 'Danos tiempo para prepararnos, $n.$b$bProtege a la ciudad de la Legión o usa tu mapa para encontrar alguna invasión que detener.$b$bCuando sea hora de comenzar, te llamaré.', '', 25549),
(123012, 'esMX', 'Los ayudaré lo mejor que pueda. Es un honor servir al Kirin Tor.', '', 25549),
(123011, 'esMX', '', 'Nunca habíamos movido a Dalaran dos veces en tan poco tiempo.', 25549),
(123010, 'esMX', 'Debemos reunir nuestras fuerzas. El hechizo para mover la ciudad es agotador.', '', 25549),
(123009, 'esMX', 'Ahora, debo atender a otras visitas. ¡Buena suerte, $n!', '', 25549),
(123008, 'esMX', 'He escuchado rumores sobre poderosos artefactos que podrían serte de utilidad en tu misión. Mantén los ojos abiertos y alguna buena pista se presentará pronto.', '', 25549),
(123007, 'esMX', 'Los recursos de Dalaran están a tu disposición. ¡De aquí, los héroes de la Horda y la Alianza buscarán por igual los Pilares de la creación!', '', 25549),
(123006, 'esMX', '', '|TInterface\\Icons\\Spell_Shadow_Possession:20|t %s comienza a lanzar |cFFFF0000|Hspell:227233|h[Rugido corrompido]|h|r. ¡Cuidado!', 25549),
(123005, 'esMX', 'Caza esto.', '', 25549),
(123004, 'esMX', 'Adiós... y buena suerte. Quizás les vaya mejor la próxima si ruegan por sus vidas.', '', 25549),
(123003, 'esMX', 'Nunca derrotaremos a la Legión mientras los cobardes tengan las riendas.', '', 25549),
(123002, 'esMX', '¡Qué terquedad, Cresta Cuervo! No importa, ya aprendí todo lo que podía de ti.', '', 25549),
(123001, 'esMX', '¿Solo saben criticar mi forma de hacer las cosas? Mis magos murieron salvando nuestro mundo. ¿Y ustedes qué han hecho? ¿Qué han sacrificado?', '', 25549),
(123000, 'esMX', 'Esta sí que fue una invasión. Casi mataron a todos aquí y tomaron Suramar.', '', 25549),
(122999, 'esMX', '¿Podríamos qué? ¡Abre los ojos, Cresta Cuervo! ¡No sabes nada!', '', 25549),
(122998, 'esMX', '¡Siempre hay una opción! Podríamos haber...', '', 25549),
(122997, 'esMX', '¿Qué quieres que haga, Kur''talos? ¿Sonreír y saludar a nuestros nuevos amos de la Legión mientras reducen nuestro mundo a cenizas?', '', 25549),
(122996, 'esMX', 'Quizás no somos mejores que los monstruos que combatimos.', '', 25549),
(122995, 'esMX', 'Qué salvajismo...', '', 25549),
(122994, 'esMX', '¡No puede ser!', '', 25549),
(122993, 'esMX', '¡Illidan, no!', '', 25549),
(122992, 'esMX', 'Que la Madre Luna me perdone por lo que hago...', '', 25549),
(122991, 'esMX', '¡Haz algo, Illidan! ¡Nos está arrasando! ¡El fuerte no resistirá mucho más!', '', 25549),
(122990, 'esMX', 'Ataqué con todo lo que tengo a esta criatura, pero no hay caso. Debo solicitar la ayuda de mi Guardia lunar una última vez.', '', 25549),
(122989, 'esMX', '¡Nos uniremos a la batalla en la arena! ¡Capitán Tempestira, lidera la carga!', '', 25549),
(122988, 'esMX', '¡Illidan tomó el patio! ¡Guardagrajos, adelante!', '', 25549),
(122987, 'esMX', '¡Soy el cazador de magos más poderoso de todo el cosmos! ¡No tienes oportunidad, elfito!', '', 25549),
(122986, 'esMX', '¿Necesitas entrenamiento?', '', 25549),
(122985, 'esMX', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t¡%s está lanzando |cFFFF0000|Hspell:199193|h[Astucia del Señor del Terror]|h|r!', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t¡%s está lanzando |cFFFF0000|Hspell:199193|h[Astucia del Señor del Terror]|h|r!', 25549),
(122984, 'esMX', '', 'No debes preocuparte, $Gpequeño:pequeña;. Yo soy tu Jefa de Guerra.', 25549),
(122983, 'esMX', '', 'Ahora le sirvo a la Horda.', 25549),
(122982, 'esMX', '', 'No necesito protección, $Gembajador:embajadora;. Joven, el cargo de Jefa de Guerra es pesado, pero me eligieron para cargar con esa responsabilidad.', 25549),
(122981, 'esMX', 'Mi amigo en el orfanato dijo que siempre eliges a Los Renegados por sobre la Horda y que nos abandonas. ¿Es cierto?', '', 25549),
(122980, 'esMX', 'Habla conmigo cuando ya puedas empezar, $n.', '', 25549),
(122979, 'esMX', 'Gracias, camarada. Espero que estés en lo cierto.', '', 25549),
(122978, 'esMX', 'Él es más que una piedra preciosa. Es nuestro rey.', '', 25549),
(122977, 'esMX', 'Se fue, camarada. Se fue para seguir un llamado superior.', '', 25549),
(122976, 'esMX', 'Bueno, si es un diamante, entonces de seguro estará bien. ¡Los diamantes son duros!', '', 25549),
(122975, 'esMX', '¿El diamante huyó?', '', 25549),
(122974, 'esMX', '¿Dónde está el diamante grande?', '', 25549),
(122973, 'esMX', 'Debes apresurarte para hallarlos. En las manos de la Legión, los Pilares de la creación podrían desatar una devastación jamás vista sobre el mundo. Buena suerte.', '', 25549),
(122972, 'esMX', 'Gracias, guardián. Le serviste a Azeroth una vez más.', '', 25549),
(122971, 'esMX', '', 'Con eso podremos empezar, al menos. Buscaremos en cada rincón de las Islas Quebradas si es necesario.', 25549),
(122970, 'esMX', 'Muy bien. Mi investigación me llevó hacia las Islas Quebradas. Aunque nunca hallé sus ubicaciones exactas, creo que los pilares están en manos de la gente de esa tierra antigua.', '', 25549),
(122969, 'esMX', 'Encontrar esos artefactos es crucial. Los pilares son lo único que puede sellar el portal de la Legión en la Tumba de Sargeras.', '', 25549),
(122968, 'esMX', '¡Claro que no! Los pilares representan un poder primordial. Incluso como guardián, no me atrevía a entrometerme con ellos.', '', 25549),
(122967, 'esMX', '', 'Buscamos cinco artefactos antiguos llamados Pilares de la creación. Tus escritos no especificaban dónde encontrarlos.', 25549),
(122966, 'esMX', 'Qué mal que no podamos ver Stormheim.', '', 25549),
(122965, 'esMX', '¿Leíste mi trabajo? No creí que las nuevas generaciones se molestaran en leer libros. Siempre están jugando y aventurándose.', '', 25549),
(122964, 'esMX', 'La Legión Ardiente ha regresado. Para detenerlos, buscamos en la biblioteca de Karazhan un tomo de tu autoría llamado "Antigüedades notables del viejo Azeroth".', '', 25549),
(122963, 'esMX', 'Te conozco. El aprendiz que rehúsa el manto que usé yo primero. ¿Qué quieres de mí?', '', 25549),
(122962, 'esMX', 'Saludos, Alodi. Soy Khadgar, archimago del Kirin...', '', 25549),
(122961, 'esMX', '¡Una invocación! Han pasado eras desde que alguien necesitó mi ayuda.', '', 25549),
(122960, 'esMX', '¡Invoco al espíritu del primer guardián!', '', 25549),
(122959, 'esMX', 'Ya casi se me acaba la energía. Debo encontrar un portal para descansar o absorber la esencia de mi Guardia lunar.', '', 25549),
(122958, 'esMX', 'Nunca había sentido tal poder... tal agonía...', '', 25549),
(122957, 'esMX', 'Un eredar conocido como Balaadur protege el portal de Nihilam. Los hechizos convencionales son inútiles contra él. Tendré que invocar la furia del cosmos para destruir el portal. Así, solo seremos el demonio y yo.', '', 25549),
(122956, 'esMX', 'Hay muchos demonios. Yo... necesito más poder de mi Guardia lunar. ¿Me estoy sobrepasando? No, ¡debo permanecer concentrado! El futuro de mi gente está en mis manos.', '', 25549),
(122955, 'esMX', 'Qué atrevimiento, ¡desafías a la Gran Sombra Ardiente! ¡Esbirros, maten al "héroe"!', '', 25549),
(122954, 'esMX', '¡Miles más! Parece que los ejércitos demoniacos vienen del portal en el patio de abajo. Debo destruirlo si queremos sobrevivir, pero necesito ayuda de mi Guardia lunar.', '', 25549),
(122953, 'esMX', '¡Soy Illidan, demonio! ¡Recuerda mi nombre porque significa tu perdición!', '', 25549),
(122952, 'esMX', 'Acabaré con esto... ¡Debo hacerlo!', '', 25549),
(122951, 'esMX', '¿Cómo se puede desafiar a tal fuerza?', '', 25549),
(122950, 'esMX', '¡Debo encontrar la manera de cerrar ese portal!', '', 25549),
(122949, 'esMX', '¡Por cada demonio que mato llegan dos más!', '', 25549),
(122948, 'esMX', '¡No tienen fin!', '', 25549),
(122947, 'esMX', 'Quizás el viento se llevó la niebla.', '', 25549),
(122946, 'esMX', '¡Puedo ver toda Suramar desde aquí!', '', 25549),
(122945, 'esMX', '¡No volvamos a hacer eso!', '¡No volvamos a hacer eso!', 25549),
(122944, 'esMX', 'Mi descuido me obliga a retroceder. Aprenderé de esta derrota y volveré para vengarme.', '', 25549),
(122943, 'esMX', 'Malfurion se convertirá en el primer druida porque es un estudiante dedicado. NO como tú.', '', 25549),
(122942, 'esMX', 'Invocaré el espíritu de Alodi, el primer guardián de Tirisfal. Hazme saber cuándo quieres que comience.', '', 25549),
(122941, 'esMX', 'Comienza la invocación.', 'Comienza la invocación.', 25549),
(122940, 'esMX', 'Triunfaremos sobre la Legión.', '', 25549),
(122939, 'esMX', 'Dalaran no caerá, $n.', '', 25549),
(122938, 'esMX', '¡Hay que detener a la Legión!', '', 25549),
(122937, 'esMX', 'NO hay forma de que esto pueda salir mal.', 'NO hay forma de que esto pueda salir mal.', 25549),
(122936, 'esMX', '¡El maestro de los seis ojos ya vio tu destino, $n! ¡Fracasarás, y los mundos arderán!', '', 25549),
(122935, 'esMX', 'Si quieres seguir estudiando la espesura, puedes hacerlo con tu hermano.', '', 25549),
(122934, 'esMX', 'Traje todas mis rocas grandes para ayudar a las catapultas. ¡Gregg quiere unirse a la Horda!', 'Esta es tu nave, $n. Que la luz te acompañe.', 25549),
(122933, 'esMX', '$n agrega sigilosamente veneno al frasco de la noche solemne.', '$n agrega sigilosamente veneno al frasco de la noche solemne.', 25549),
(122932, 'esMX', '$n destruye el conducto de energía arcano, ¡lo que sobrecarga todos los ensamblajes de los guardianes!', '$n destruye el conducto de energía arcano, ¡lo que sobrecarga todos los ensamblajes de los guardianes!', 25549),
(122930, 'esMX', '$n interpreta el pergamino calado, ¡lo que otorga a todos velocidad de movimiento aumentada!', '$n interpreta el pergamino calado, ¡lo que otorga a todos velocidad de movimiento aumentada!', 25549),
(122929, 'esMX', '¡$n dirige la energía de la linterna mágica y otorga a todos daño aumentado!', '¡$n dirige la energía de la linterna mágica y otorga a todos daño aumentado!', 25549),
(122928, 'esMX', '$n interactúa con los refrigerios de Sombranoche, ¡lo que otorga a todos salud aumentada!', '$n interactúa con los refrigerios de Sombranoche, ¡lo que otorga a todos salud aumentada!', 25549),
(122927, 'esMX', '$n desata esporas de la corola umbría, ¡lo que otorga a todos celeridad aumentada!', '$n desata esporas de la corola umbría, ¡lo que otorga a todos celeridad aumentada!', 25549),
(122926, 'esMX', '$n absorbe el orbe vil, ¡lo que otorga a todos probabilidad de golpe crítico aumentada!', '$n absorbe el orbe vil, ¡lo que otorga a todos probabilidad de golpe crítico aumentada!', 25549),
(122925, 'esMX', '$n destruye un tomo infernal, ¡lo que otorga a todos reducción de daño!', '$n destruye un tomo infernal, ¡lo que otorga a todos reducción de daño!', 25549),
(122924, 'esMX', '$n interactúa con el brebaje de rosa luz estelar, ¡lo que otorga a todos restauración de salud y maná!', '$n interactúa con el brebaje de rosa luz estelar, ¡lo que otorga a todos restauración de salud y maná!', 25549),
(122923, 'esMX', 'Ya oyes el grito de batalla, ¿no, $n? ¡Te está llamando!', '', 25549),
(122912, 'esMX', '¡La guerra hace que la sangre me hierva, $n! ¿Acaso tu hacha no ansía un duelo?', '', 25549),
(122911, 'esMX', 'Sangre y truenos, $n. Tu barco y la gloria de la victoria te aguardan.', 'Esta es tu nave, $n. Que la luz te acompañe.', 25549),
(122908, 'esMX', 'Mmm... Eso me da una idea... Lo discutiremos cuando te hayas encargado de esas anomalías.', '', 25549),
(122907, 'esMX', 'La archimaga Modera y yo seguiremos examinando el tomo que recuperamos de Karazhan. ¡Hallaremos esos pilares, $n!', '', 25549),
(122906, 'esMX', 'Me alivia que lográramos salir de Karazhan en una sola pieza.', '', 25549),
(122900, 'esMX', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t ¡Hyrja comienza a lanzar |cFFFF0404|Hspell:192206|h[Santificar]|h|r!', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t ¡Hyrja comienza a lanzar |cFFFF0404|Hspell:192206|h[Santificar]|h|r!', 25549),
(122899, 'esMX', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t ¡Hyrja comienza a lanzar |cFFFF0404|Hspell:192305|h[Ojo de la Tormenta]|h|r!', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t ¡Hyrja comienza a lanzar |cFFFF0404|Hspell:192305|h[Ojo de la Tormenta]|h|r!', 25549),
(122898, 'esMX', 'Tenías razón, demonio. La magia vil es más poderosa que la Arcano, ¡pero lo blandes sin pericia! ¡Te mostraré la destrucción que puede provocar el toque de un maestro!', '', 25549),
(122897, 'esMX', '', '¿Te atreves a desafiar a la Legión Ardiente? ¡Inclínate ante el poder de la magia vil!', 25549),
(122896, 'esMX', 'Ay de mí, ¿qué opción tenemos? Si fracaso, Suramar caerá mañana, y con ella, mi amada Tyrande. ¡Debo actuar ya!', '', 25549),
(122895, 'esMX', 'Su magia vil es muy fuerte. Podría intentar succionar su energía desde mi Guardia lunar y desatar la destrucción sobre ella, pero mis magos morirían en el proceso.', '', 25549),
(122894, 'esMX', 'Archimago, debemos irnos.', 'Archimago, debemos irnos.', 25549),
(122893, 'esMX', '¡A tus órdenes, capitán!', '¡A tus órdenes, capitán!', 25549),
(122892, 'esMX', '¡Bajen la puerta y prepárense! ¡Que los lanzadoras de gujas estén listos!', '', 25549),
(122891, 'esMX', '¡Estoy listo, Lord Cresta Cuervo! ¡Baja la compuerta!', '', 25549),
(122890, 'esMX', '¡Excelente! La energía que emana del portal me energizará mientras me mantenga cerca. Debo recordar volver a estos portales si me siento fatigado.', '', 25549),
(122889, 'esMX', 'Illidan se queda pensativo.', '', 25549),
(122888, 'esMX', 'Si puedo reparar ese portal desactivado, tendré los refuerzos que necesito y una fuente de poder para restaurar mi energía.', '', 25549),
(122887, 'esMX', 'Nos tomó casi toda nuestra energía conjurar esa barrera protectora. Si presiono más a la Guardia lunar, morirán.', '', 25549),
(122886, 'esMX', '¡No te fallaré, mi lord!', '', 25549),
(122884, 'esMX', 'Y hallaré ese camino...', '', 25549),
(122883, 'esMX', 'Estamos perdidos...', '', 25549),
(122882, 'esMX', 'Incluso si los derrotamos aquí, no significará nada.', '', 25549),
(122881, 'esMX', 'Más allá de este ejército hay otro... y otro... y otro.', '', 25549),
(122880, 'esMX', 'Nuestros ojos... nos engañan.', '', 25549),
(122879, 'esMX', 'No importa lo mucho que quiera resistir este mundo. Caerá.', '', 25549),
(122878, 'esMX', '<gritos de agonía>', '', 25549),
(122877, 'esMX', 'Contempla el poder de la Legión.', '', 25549),
(122876, 'esMX', '¡Hermano!', '', 25549),
(122875, 'esMX', 'Atravesar este camino requiere de sacrificio, Illidan... Algo que aún no entiendes.', '', 25549),
(122874, 'esMX', 'Debes aprender a respetar.', '', 25549),
(122873, 'esMX', '¿Así que debo aprender de... un PRINCIPIANTE... en vez de un MAESTRO?', '', 25549),
(122872, 'esMX', 'Entonces...', '', 25549),
(122871, 'esMX', 'No. Puedes permanecer aquí, pero ya no seré tu maestro.', '', 25549),
(122870, 'esMX', '¡Me desterraste, Cenarius!', '', 25549),
(122869, 'esMX', 'Illidan, tu ira no tiene lugar aquí. Yo no te he insultado.', '', 25549),
(122868, 'esMX', '', 'Así es. El chico está destinado a un grandioso y próspero futuro. Su nombre... es Illidan.', 25549),
(122867, 'esMX', '¡Ese! ¡Sus ojos son dorados!', '', 25549),
(122866, 'esMX', '', 'Hermoso. Casi igual, excepto por...', 25549),
(122865, 'esMX', '', 'Los gemelos Tempestira.', 25549),
(122864, 'esMX', '¿Dos?', '', 25549),
(122862, 'esMX', '', '¡Corre, pobre Cresta Cuervo, corre! ¡Puede que aún tengas tiempo de huir y vivir tus últimos miserables días escondido en un árbol de por ahí!', 25549),
(122861, 'esMX', '', 'El cachorro... tiene colmillos...', 25549),
(122860, 'esMX', '', 'Tú... ¡¿Mataste a tus propios soldados?! ¡Es una locura! ¡Acabas de sellar tu propio destino!', 25549),
(122859, 'esMX', '', '¿¿Qué es esto?? ¿Cresta Cuervo mandó a un cachorro para enfrentarme? ¡Te enseñaré a respetar a tus mayores!', 25549),
(122858, 'esMX', '¡$n! ¡Khadgar! ¡Gracias a la forja que te encontré! ¡No lo vas a creer! ¡Mi hermano, Magni, regresó!', '', 25549),
(122857, 'esMX', '¡El capitán Tempestira nos dio una oportunidad! ¡Aseguren la muralla, Guardagrajos! ¡Avancen!', '', 25549),
(122856, 'esMX', '¡Haz lo que debas! ¡Si el Fuerte Torre Oscura cae, toda Suramar también lo hará!', '', 25549),
(122855, 'esMX', '', '%s se encoje de hombros y te patea por los cielos.', 25549),
(122854, 'esMX', '', 'Tu funeral.', 25549),
(122853, 'esMX', '', '¡LADRONA! ¡¿Cómo te ATREVES a robar lo que es mío?!', 25549),
(122852, 'esMX', '¡Eres nuestra última esperanza, Illidan!', '', 25549),
(122851, 'esMX', 'La Legión ya acabó con la mitad de nuestras fuerzas y esparció el resto por el campo. Lo que ves aquí es todo lo que queda de los Guardagrajos que protegían el fuerte.', '', 25549),
(122850, 'esMX', 'Me gustaría volver a desafiar a Ruina, señora.', 'Me gustaría volver a desafiar a Ruina, señora.', 25549),
(122849, 'esMX', 'Bien hecho, Illidan, pero la batalla apenas comienza.', '', 25549),
(122848, 'esMX', '¿Estas son tus iniciales?', '¿Estas son tus iniciales?', 25549),
(122847, 'esMX', '', '¿Qué te trae ante mí, $r?', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122846, 'esMX', '', 'El nacimiento, no de uno, sino de dos varones saludables.', 25549),
(122845, 'esMX', '', 'Gracias a la diosa. Nos ha bendecido esta noche con nueva vida.', 25549),
(122844, 'esMX', 'Illidan está muerto y el Ejército Dorado lucha en una interminable guerra en nuestro nombre por todo el cosmos.', '', 25549),
(122843, 'esMX', 'En cuanto al ejército de la Luz e Illidan, no tengo idea. Nunca me había sentido tan indefenso.', '', 25549),
(122842, 'esMX', 'Hemos estado solos todo este tiempo. Nuestros dioses murieron mucho antes de que naciéramos.', '', 25549),
(122841, 'esMX', 'Eso explica muchas cosas. Aun así, no puedo evitar sentir una gran tristeza.', '', 25549),
(122840, 'esMX', '¿Muertos? ¿Los titanes están muertos?', '', 25549),
(122838, 'esMX', '', 'Puedes hablar.', 25549),
(122837, 'esMX', '<Muestra la marca de Thalyssra a Valtrois.>', '<Muestra la marca de Thalyssra a Valtrois.>', 25549),
(122836, 'esMX', '', 'Los ecos de magia se detuvieron. Te damos las gracias.', 25549),
(122835, 'esMX', '', '¡Esos magos fantasmas entrometidos lograron conjurar un ser de magia salvaje! Ponlos de vuelta en su lugar.', 25549),
(122834, 'esMX', '', 'Bien hecho. Podemos quedarnos tranquilos... por ahora.', 25549),
(122833, 'esMX', '', 'Una bestia gigante se alzó de las aguas. ¡Mándala de vuelta a las profundidades!', 25549),
(122832, 'esMX', '¡Lo he visto todo! ¡Illidan! ¡Cresta Cuervo quiere que me encargue! ¡Tenemos que coordinar el ataque e intentar poner algo de orden!', '', 25549),
(122831, 'esMX', 'Quedas relevado de tu puesto, Illidan. Rhonin, la Guardia lunar está bajo tus órdenes.', '', 25549),
(122830, 'esMX', '¿QUÉ HICISTE? ¡LOS MATASTE A TODOS, ILLIDAN!', '', 25549),
(122829, 'esMX', '¡Busca al capitán Cantosombrío y a sus dos aliados extranjeros! Nos separamos tras el asalto inicial. ¡Espero que sigan vivos!', '', 25549),
(122828, 'esMX', 'Para empeorar las cosas, ¡esa monstruosidad de la arena hará arder el fuerte desde adentro si no la detiene nadie! ¡Lleva a la Guardia lunar y libra al Fuerte Torre Oscura de esta invasión demoníaca!', '', 25549),
(122827, 'esMX', '', 'Tyrande... El mundo solo tiene significado para los seres que lo habitamos. Incluso al final, Illidan la vio con la misma claridad que la primera vez. Jamás perdió de vista su mundo. Pregúntate hasta dónde llegarás por el tuyo.', 25549),
(122826, 'esMX', '', 'Con sus ojos quemados al ver la verdad, Illidan no desfalleció. Incluso bajo la mirada del señor de la Legión Ardiente, Illidan siguió resuelto y desafiante.', 25549),
(122825, 'esMX', '', 'Se tomaron decisiones difíciles, pero comprender la perspectiva de Illidan es esencial para el éxito de la misión. ¿Qué habrías hecho diferente?', 25549),
(122824, 'esMX', '', 'Pocos han conocido semejante fracaso y rechazo. La mayoría se rindieron, pero Illidan sigue adelante, guiado por la invisible mano del destino. Su destino está en otra parte.', 25549),
(122823, 'esMX', '', 'Illidan tuvo una vida llena de potencial. Su destino se forjó durante la gran ordenación y fue moldeado por los vientos cósmicos, donde al fin hallaría un hogar en Azeroth. En el pequeño contenedor, el gran ciclo empezó de nuevo.', 25549),
(122822, 'esMX', '', 'Un antiguo recuerdo se agita. Cuando te prepares, llámame y descubriremos un fragmento del pasado de Illidan.', 25549),
(122821, 'esMX', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|tUsa |cFF00FFFF|Hspell:212630|h[Suelo purificado]|h|r de Malfurion para evitar el daño de las |cFFFF0000|Hspell:210279|h[Pesadillas espeluznantes]|h|r.', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|tUtiliza el |cFF00FFFF|Hspell:212630|h[suelo purificado]|h|r de Malfurion para evitar el daño de las |cFFFF0000|Hspell:210279|h[pesadillas espeluznantes]|h|r.', 25549),
(122820, 'esMX', '¡Poder surcar los cielos es una maravilla!', '', 25549),
(122819, 'esMX', '¡Lo sabía! ¡Podía sentirlo!$B$B¡Desaloja la ciudad, $n! ¡Tenemos que contenerlos!', '', 25549),
(122818, 'esMX', '', '¡Hagan que retrocedan! ¡No podemos permitir que Dalaran caiga!', 25549),
(122817, 'esMX', '¡Que el veloz acero traiga tu fin!', '', 25549),
(122816, 'esMX', '¡NO lograrás tu cometido!', '', 25549),
(122815, 'esMX', 'Estoy tan sorprendido como tú, $n.', '', 25549),
(122814, 'esMX', '¡Es tu final!', '', 25549),
(122813, 'esMX', '¡Mi espada te purgará!', '', 25549),
(122812, 'esMX', '', 'Hazlo lo mejor que puedas, $n. Ya veremos cuánto podremos contener a los demonios.', 25549),
(122811, 'esMX', 'Soy el archimago Khadgar, líder del Kirin Tor. Cazadores de demonios, Azeroth necesita su ayuda.', '', 25549),
(122810, 'esMX', 'Tenía una elaborada fuga de la prisión lista, pero parece que te me adelantaste.', '', 25549),
(122809, 'esMX', '¡Estamos condenados!', '¡Estamos condenados!', 25549),
(122808, 'esMX', '¡La Luz ha muerto! ¿No lo ves?', '¡La Luz ha muerto! ¿No lo ves?', 25549),
(122807, 'esMX', '', '¡Estas cosas no dejan de venir!', 25549),
(122806, 'esMX', '¡No podrás detenerlos!', '¡No podrás detenerlos!', 25549),
(122805, 'esMX', '¡Sin él estamos perdidos!', '¡Sin él estamos perdidos!', 25549),
(122804, 'esMX', '¡Este es para ti, $n!', '', 25549),
(122803, 'esMX', '¡Fuera de nuestras tiendas!', '', 25549),
(122802, 'esMX', '¡Ni hablar!', '', 25549),
(122801, 'esMX', '', 'Gracias...', 25549),
(122800, 'esMX', '', 'Vuelvo... a la oscuridad del más allá...', 25549),
(122799, 'esMX', '', 'Libre... al fin...', 25549),
(122798, 'esMX', '', 'Muchas... gracias...', 25549),
(122797, 'esMX', '', 'Tan... perdida...', 25549),
(122796, 'esMX', '', 'La Luz ha muerto...', 25549),
(122795, 'esMX', '', 'Sin esperanza...', 25549),
(122794, 'esMX', '', 'Ayuda... ayuda.', 25549),
(122793, 'esMX', '¿Alguien puede controlar esto?', '¿Alguien puede controlar esto?', 25549),
(122792, 'esMX', '¡Que alguien pare esto!', '¡Que alguien pare esto!', 25549),
(122791, 'esMX', '¡Aleja esa cosa de mí!', '¡Aleja esa cosa de mí!', 25549),
(122790, 'esMX', '¡Nos unimos a la batalla, señor Illidan!', '', 25549),
(122789, 'esMX', '[%s] confiesa: Bajo el precio más que todos al vender en la casa de subastas porque puedo.', '[%s] confiesa: Bajo el precio más que todos al vender en la casa de subastas porque puedo.', 25549),
(122788, 'esMX', '[%s] confiesa: No me gusta pelear contra Gronn. Siento como si me mirara directamente.', '[%s] confiesa: No me gusta pelear contra Gronn. Siento como si me mirara directamente.', 25549),
(122787, 'esMX', '¡Al fin un rival digno de mi hacha!', '', 25549),
(122786, 'esMX', '[%s] confiesa: Creo que Garrosh era buen tipo.', '[%s] confiesa: Creo que Garrosh era buen tipo.', 25549),
(122785, 'esMX', '[%s] confiesa: Me gusta mucho, pero mucho, la posada de Villadorada.', '[%s] confiesa: Me gusta mucho, pero mucho, la posada de Villadorada.', 25549),
(122784, 'esMX', '[%s] confiesa: No entiendo por qué se llaman las Islas Quebradas. ¿No todas las islas son así?', '[%s] confiesa: No entiendo por qué se llaman las Islas Quebradas. ¿No todas las islas son así?', 25549),
(122783, 'esMX', '[%s] confiesa: Esperaba en secreto que un barco en concreto de mi astillero fallara su misión. No lo hizo.', '[%s] confiesa: Esperaba en secreto que un barco en concreto de mi astillero fallara su misión. No lo hizo.', 25549),
(122782, 'esMX', '[%s] confiesa: Llevo mucho tiempo sin visitar mi fortaleza. Espero que mis seguidores estén bien.', '[%s] confiesa: Llevo mucho tiempo sin visitar mi fortaleza. Espero que mis seguidores estén bien.', 25549),
(122781, 'esMX', '[%s] confiesa: Me gustaba más la vieja Dalaran. No, esa no, la otra.', '[%s] confiesa: Me gustaba más la vieja Dalaran. No, esa no, la otra.', 25549),
(122780, 'esMX', '[%s] confiesa: Soy el que siempre activaba Aspecto de la manada.', '[%s] confiesa: Soy la que siempre activaba Aspecto de la manada.', 25549),
(122779, 'esMX', '[%s] confiesa: No presto atención cuando se explica la pelea de un nuevo jefe de una banda.', '[%s] confiesa: No presto atención cuando se explica la pelea de un nuevo jefe de una banda.', 25549),
(122778, 'esMX', '[%s] confiesa: Me pregunto si las barbas de vrykul son suaves como gatitos.', '[%s] confiesa: Me pregunto si las barbas de vrykul son suaves como gatitos.', 25549),
(122777, 'esMX', '[%s] confiesa: Vendo todo lo que no necesito porque me da pereza usar la casa de subastas.', '[%s] confiesa: Vendo todo lo que no necesito porque me da pereza usar la casa de subastas.', 25549),
(122776, 'esMX', '[%s] confiesa: Paso más tiempo del que me gustaría admitir buscando Splashran en el océano.', '[%s] confiesa: Paso más tiempo del que me gustaría admitir buscando Splashran en el océano.', 25549),
(122775, 'esMX', '[%s] confiesa: No puedo creer lo grandes que son las armas de los tauren.', '[%s] confiesa: No puedo creer lo grandes que son las armas de los tauren.', 25549),
(122774, 'esMX', '[%s] confiesa: Creí que ya habíamos derrotado a la Legión.', '[%s] confiesa: Creí que ya habíamos derrotado a la Legión.', 25549),
(122773, 'esMX', '[%s] confiesa: No sé qué es una Piedra de salud y a estas alturas me da miedo preguntar.', '[%s] confiesa: No sé qué es una Piedra de salud y a estas alturas me da miedo preguntar.', 25549),
(122772, 'esMX', '¡Acaben con esta farsa, demonios! ¡No pueden derrotarme!', '', 25549),
(122771, 'esMX', 'La Legión cree que sus trucos nos toman por sorpresa, ¡pero estamos preparados!', '', 25549),
(122770, 'esMX', 'Caen del cielo con tanto aplomo. Ah, dulce catarsis.', '', 25549),
(122769, 'esMX', 'Parece que perdí mi Piedra de hogar de Dalaran, ¿puedes darme otra?', 'Parece que perdí mi Piedra de hogar de Dalaran, ¿puedes darme otra?', 25549),
(122768, 'esMX', 'Tu sacrificio será recordado.', '', 25549),
(122767, 'esMX', 'Hago lo que es necesario.', '', 25549),
(122766, 'esMX', 'Tu hoja es certera, Jarod. ¡Acompáñame y acabamos con este asalto!', '', 25549),
(122765, 'esMX', 'Solo espero que el sacrificio valga la pena.', '', 25549),
(122764, 'esMX', 'Este lugar se construyó para resistir casi cualquier asalto, pero nadie pudo predecir la fuerza de la Legión.', '', 25549),
(122763, 'esMX', 'Señor Illidan, ¡peleas con un gran poder!', '', 25549),
(122762, 'esMX', 'No soy un héroe, capitán, pero pelearé a tu lado.', '', 25549),
(122761, 'esMX', 'No sé si estoy cómodo con esto, señor Illidan.', '', 25549),
(122760, 'esMX', 'Un buen combate. Jamás habría derrotado a un señor del terror sin ayuda.', '', 25549),
(122759, 'esMX', '¡Illidan! Creo que en este mausoleo reside un señor del terror. Gracias por tu apoyo.', '', 25549),
(122758, 'esMX', '¡Que el fuego los purifique, demonios!', '', 25549),
(122757, 'esMX', 'Aseguraré los cielos, capitán. Parece que aún $Glo:la necesitan en tierra.', '', 25549),
(122756, 'esMX', '¡Creí que este ataque incesante no acabaría nunca!', '', 25549),
(122755, 'esMX', '¡Illidan! ¡Montas ese dragón con una habilidad increíble!', '', 25549),
(122754, 'esMX', 'Mi hacha es tuya.', '', 25549),
(122753, 'esMX', 'Aprendo nuevas tácticas solo combatiendo juntos, Illidan.', '', 25549),
(122752, 'esMX', 'Gracias por tu apoyo contra este enemigo.', '', 25549),
(122751, 'esMX', 'Illidan, peleas con fuerza y gracia. Es un honor verte en combate.', '', 25549),
(122750, 'esMX', 'Heces lo que debe hacerse. Es una cualidad admirable.', '', 25549),
(122749, 'esMX', '¿Qué clase de mago eres tú?', '', 25549),
(122748, 'esMX', '¡La pelea no es justa! ¡Tendrán que enviar más refuerzos contra mí, demonios!', '', 25549),
(122747, 'esMX', '¡Algún día te enseñaré mi colección de tabardos!', '', 25549),
(122746, 'esMX', '¡Algún día te enseñaré mi colección de monturas!', '', 25549),
(122745, 'esMX', '¡Algún día te enseñaré mi colección de monedas!', '', 25549),
(122744, 'esMX', '¡Algún día te enseñaré mi colección de pergaminos!', '', 25549),
(122743, 'esMX', '¡Algún día te enseñaré mi colección de mascotas!', '', 25549),
(122742, 'esMX', '¡Algún día te enseñaré mi colección de tazas!', '', 25549),
(122741, 'esMX', '¡Algún día te enseñaré mi colección de juguetes!', '', 25549),
(122740, 'esMX', 'Cuanto más bebo, mejores son mis estrategias... ¡Hip!', '', 25549),
(122739, 'esMX', 'Quedé en segundo lugar en la carrera de yaks de la semana pasada. ¡Necesito uno más rápido!', '', 25549),
(122738, 'esMX', 'Todas las mañanas corro por la Isla Errante... ¡dos veces! No puedo descuidar mi entrenamiento.', '', 25549),
(122737, 'esMX', '¡Algún día te enseñaré mi colección de hojas!', '', 25549),
(122736, 'esMX', 'Cuando acabe, ¡iré a por mi segunda cena!', 'Cuando acabe, ¡iré a por mi segunda cena!', 25549),
(122735, 'esMX', '¡$n! ¡Tengo buenas noticias! ¡Ven!', '', 25549),
(122734, 'esMX', '', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', 25549),
(122733, 'esMX', 'Nada fuera de lo normal. La energía ocasional, pero nada que considere peligroso.', 'Nada fuera de lo normal. La energía ocasional, pero nada que considere peligroso.', 25549),
(122732, 'esMX', '', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', 25549),
(122731, 'esMX', '', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', 25549),
(122730, 'esMX', '', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', 25549),
(122729, 'esMX', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', '', 25549),
(122728, 'esMX', '', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', 25549),
(122727, 'esMX', '', 'Te avisaremos si encontramos algo.', 25549),
(122726, 'esMX', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', '', 25549),
(122725, 'esMX', 'No tengo tiempo para cumplidos, $Gcazador:cazadora; de demonios.$b$bComo le dije al otro Illidari, tengo mucho en qué pensar.$b$bDebo preparar mis ejércitos para atacar a la Legión, incluso aunque algunos de mis aliados clamen venganza contra la Horda.', '', 25549),
(122724, 'esMX', '', '¡Todo parece ir bien por aquí de momento!', 25549),
(122723, 'esMX', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', '', 25549),
(122722, 'esMX', '¡$GSeñor:Señora;! Tengo cosas buenas. Venga a ver.', '', 25549),
(122721, 'esMX', '', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', 25549),
(122720, 'esMX', '', 'Estás en buenas manos. ¡Te sacará de ahí en un momento!', 25549),
(122719, 'esMX', '', '¡$n! Si tienes un momento, tengo algunos artículos disponibles que podrían interesarte.', 25549),
(122718, 'esMX', '', 'Parece que lo tienes casi todo controlado.', 25549),
(122717, 'esMX', '', 'Eh, Grindle... Ay, no voy ni a preguntar. Todo tuyo.', 25549),
(122716, 'esMX', 'Con la Orden de la Mano de plata reformada bajo tu mando, tenemos una nueva dirección y guía.$B$BTenemos mucho trabajo por delante.', '', 25549),
(122715, 'esMX', '', '¿Cómo van las cosas por aquí? ¿Pasa algo raro?', 25549),
(122714, 'esMX', '', '¿Tienen algún problema? Me informaron de energía inestable en la zona.', 25549),
(122713, 'esMX', 'Háblame de Khadgar otra vez.', 'Háblame de Khadgar otra vez.', 25549),
(122712, 'esMX', 'Háblame otra vez de Gul''dan.', 'Háblame de Gul''dan otra vez.', 25549),
(122711, 'esMX', 'Háblame de Illidan otra vez.', 'Háblame de Illidan otra vez.', 25549),
(122710, 'esMX', 'El Kirin Tor agradece tu ayuda.', '', 25549),
(122709, 'esMX', '¡Debemos retomar nuestra tierra sagrada!', '', 25549),
(122708, 'esMX', '', '¿Tendrás el valor de ayudarnos a derrotar a la Legión?', 25549),
(122707, 'esMX', '¿Sientes la vida en este bosque? Hemos protegido estas tierras durante años, pero llegó el día en que ya no podemos hacerlo sin ayuda. ¿Podemos contar contigo?', '¿Sientes la vida en este bosque? Hemos protegido estas tierras durante años, pero llegó el día en que ya no podemos hacerlo sin ayuda. ¿Podemos contar contigo?', 25549),
(122706, 'esMX', '', 'En pie, $n.$B$BPuede que Dubin sea un enano testarudo, pero estamos de acuerdo en algo: aquí pasa algo raro.', 25549),
(122705, 'esMX', '', '¡Tenemos que aguantar un poco más!', 25549),
(122704, 'esMX', '', 'El Consejo tiene un plan. ¡Estoy segura!', 25549),
(122703, 'esMX', '', '¡Van a mover la ciudad pronto! ¡No creo que podamos seguir así!', 25549),
(122702, 'esMX', '', '¡No podemos seguir así! ¡Pronto nos superarán!', 25549),
(122701, 'esMX', '', '¡Esto no acaba nunca! ¡No dejan de venir!', 25549),
(122700, 'esMX', '', '¡No podremos soportar mucho más!', 25549),
(122699, 'esMX', '¡Sigues con vida! Tus campeones vinieron a mí cuando no lograron despertarte en la sala del orden. Te trajimos aquí, a la enfermería. ¿Qué ocurrió?', '', 25549),
(122698, 'esMX', '', '¡Saludos! ¿Acabas de llegar a la ciudad? No pareces sufrir los efectos secundarios.', 25549),
(122697, 'esMX', '', 'Saludos, $n. ¿Te encuentras bien? Los otros se quejan de náuseas y mareos.', 25549),
(122696, 'esMX', '', 'El dolor pasará, $Gcampeón:campeona;. Ahora llevas mi marca y, a través de ella, puedo ver y sentir lo mismo que tú. Regresa cuando puedas, tenemos mucho que hacer.', 25549),
(122695, 'esMX', '¡Ja, ja, ja!', '', 25549),
(122694, 'esMX', 'Vaya, ¡mira quién volvió de entre los muertos! $gSeñor: Señora;, llevas inconsciente 3 días. Seguro que Khadgar estará aliviado de ver a su compañera especial con vida. ¿En cuanto a mí? Aún soy un león marino.', '', 25549),
(122693, 'esMX', '¡No puedes ocultar lo que realmente eres, demonio!', '¡No puedes ocultar lo que realmente eres, demonio!', 25549),
(122692, 'esMX', 'El viaje a Ulduar fue ajetreado, pero aún teníamos trabajo por delante.', '', 25549),
(122691, 'esMX', 'Adelante. Iré enseguida, solo necesito... ordenar mis pensamientos.', '', 25549),
(122690, 'esMX', 'He cambiado de idea. Muéstrame qué artefactos hay disponibles.', 'He cambiado de idea. Muéstrame qué artefactos hay disponibles.', 25549),
(122686, 'esMX', '¡Nadie podrá oponerse al Martillo Crepuscular!', '¡Nadie podrá oponerse al Martillo Crepuscular!', 25549),
(122685, 'esMX', '¡Somos los heraldos de la destrucción!', '¡Somos los heraldos de la destrucción!', 25549),
(122684, 'esMX', 'Grita por ayuda... ¡nadie te responderá!', 'Grita por ayuda... ¡nadie te responderá!', 25549),
(122683, 'esMX', '¡El crepúsculo cae sobre ti!', '¡El crepúsculo cae sobre ti!', 25549),
(122682, 'esMX', '¡Soy tu destrucción!', '¡Soy tu destrucción!', 25549),
(122681, 'esMX', '', '¡No sé qué les ocurre a las flores! Dejé de recogerlas cuando empezaron... ¡Bueno, empezaron a recogerse solas!$B$BRaro, ¿no?', 25549),
(122680, 'esMX', '¿Cuál es la historia del Viejo Fillmaff?', '¿Cuál es la historia del Viejo Fillmaff?', 25549),
(122679, 'esMX', 'Pasaron los años y reubicamos toda la ciudad en Corona de Hielo para la campaña de Rasganorte.$b$bUn día, de repente, el Viejo Fillmaff entró en la Torre Violeta. ¡Como si nada! Y sin decir una palabra, empezó a archivar libros y a organizar los archivos. Lleva así desde entonces.$b$b<Varenthas se inclina hacia ti y te susurra>$b$bNo creo que sepa que está muerto.', '', 25549),
(122678, 'esMX', '¿Quién? ¿Fillmaff? ¿Ese vejestorio? Lleva décadas siendo archivista aquí, en Dalaran. Lo recuerdo de mi época de estudiante. Siempre ensimismado con los libros. Podía encontrar cualquier cosa.$b$bEntonces llegó la Tercera Guerra, cuando Arthas saqueó la ciudad. Fillmaff desapareció, junto con muchos otros... Otro muerto anónimo. Nadie le dio importancia.', '', 25549),
(122677, 'esMX', 'Así que los eredar emboscaron a Arrexis, Balaadur? Entonces es probable que tenga el bastón...\n\nCon la invasión, no cabe duda de que está aquí o está mirando. Propongo algo... audaz.\n\n¡Recreemos el ritual de Arrexis! Si llevamos a cabo el ritual en un punto de invasión, atraeremos la atención de Balaadur. Es probable que intente emboscarnos, pero estaremos listos.', '', 25549),
(122676, 'esMX', '<En silencio, te observa con cautela>.', '<En silencio, te observa con cautela>.', 25549),
(122675, 'esMX', 'Si tú lo dices.', 'Si tú lo dices.', 25549),
(122674, 'esMX', 'No me das miedo.', 'No me das miedo.', 25549),
(122673, 'esMX', 'Pelea contra mí.', 'Pelea contra mí.', 25549),
(122672, 'esMX', 'No tengo.', 'No tengo.', 25549),
(122671, 'esMX', 'Márchate.', 'Márchate.', 25549),
(122670, 'esMX', '¿Qué?', '¿Qué?', 25549),
(122669, 'esMX', 'Je.', 'Je.', 25549),
(122668, 'esMX', 'Déjame en paz.', 'Déjame en paz.', 25549),
(122667, 'esMX', 'Conozco tu secreto.', 'Conozco tu secreto.', 25549),
(122666, 'esMX', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|tI¡l''gynoth casi ha completado su |cFFFF0000|Hspell:223121|h[Sopor final]|h|r!', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|tIl''gynoth casi ha completado su |cFFFF0000|Hspell:223121|h[Sopor final]|h|r!', 25549),
(122665, 'esMX', 'Si buscas empuñar las armas del señor de la tormenta, aventúrate dentro, y aprende sus hazañas y su caída...', '', 25549),
(122664, 'esMX', 'Te hice una pregunta, ¡responde!', 'Te hice una pregunta, ¡responde!', 25549),
(122663, 'esMX', '¡Hola! En realidad no soy yo, Khadgar, sino solo mi exageradamente atractivo semblante y mis vastos conocimientos. Si buscas la respuesta a cualquier pregunta, solo tienes que plantearla.\n\nLa enormidad de mi mente es tal, que solo quedó espacio mágico para impartir algunas frases de respuesta en este consejo, por lo que tus preguntas deberán ser MUY específicas.', '', 25549),
(122662, 'esMX', 'Esto no puede esperar. Hay demonios entre tus filas. Te lo demostraré.', 'Esto no puede esperar. Hay demonios entre tus filas. Te lo demostraré.', 25549),
(122661, 'esMX', '<Al parecer, Arduen estaba preso. Su cara está blanca como el papel>.$B$B$IEscapé... y corrí...$B$BCasi... lo logré...$B$BPor favor, $n, salva... a los otros... Illidari...', '', 25549),
(122660, 'esMX', 'Ulduar alberga muchos secretos.', '', 25549),
(122659, 'esMX', '', 'Buena suerte, a todos.', 25549),
(122658, 'esMX', '', 'XXXX', 25549),
(122657, 'esMX', '¡Avanza si las Ánimas de maná están distraídas!', '¡Avanza si las Ánimas de maná están distraídas!', 25549),
(122656, 'esMX', '', 'No te alarmes, mortal. Tu consciencia se ha proyectado ante mi presencia astral en la Gran oscuridad del más allá.', 25549),
(122655, 'esMX', '', 'Soy Xe''ra, una de los primeros naaru forjados aquí durante la gran ordenación del Cosmos.', 25549),
(122654, 'esMX', '¡Da la orden y partiremos!', '', 25549),
(122653, 'esMX', 'Partiremos hacia el Templo Luz Abisal ya mismo.', '', 25549),
(122652, 'esMX', 'Regresé a Dalaran en cuanto oí que se había cumplido la profecía.\n\nUniste la Luz, tal como lo vi. Esperemos que tus esfuerzos nos den la fuerza que necesitamos para derrotar a Balnazzar de una vez por todas.', '', 25549),
(122651, 'esMX', '<Sirius Alébano luce tan pálido como un fantasma. Tiembla descontroladamente>.', '', 25549),
(122650, 'esMX', '<El cuerpo de Cassiel Aguja Nocturna está casi irreconocible. Lo torturaron y murió por las heridas>.', '', 25549),
(122649, 'esMX', '', 'Eres tú, $n.\n\nPerseguíamos a un peligroso señor del terror. Por desgracia, nos llevó directo a su trampa.', 25549),
(122648, 'esMX', '¡Este demonio tiene ganas de pelear!', '¡Este demonio tiene ganas de pelear!', 25549),
(122647, 'esMX', 'No tenemos el poder...', 'No tenemos el poder...', 25549),
(122646, 'esMX', '¡Es muy fuerte! ¡Es una locura!', '¡Es muy fuerte! ¡Es una locura!', 25549),
(122645, 'esMX', '', 'Aquel llamado Illidan Tempestira.', 25549),
(122644, 'esMX', '', 'Estoy aquí en una misión desesperada. Busco al hijo de la Luz y la Oscuridad: el chico que acabará con la era de los demonios.', 25549),
(122643, 'esMX', '', 'Pero ahora, el Ejército Dorado mora en el precipicio del olvido y su campaña en Argus se acerca a su final. Si caen, la Legión iniciaría una nueva Cruzada Ardiente y el cosmos se estremecería.', 25549),
(122642, 'esMX', '', 'De las cenizas de los mundos devastados, los sobrevivientes se alzaron contra los demonios. Los llamaron el Ejército de la Luz.', 25549),
(122641, 'esMX', '', 'Tras la caída, no quedó nadie para enfrentarse a Sargeras. Sin oposición, el titán oscuro y su Legión Ardiente, aniquilaron incontables mundos en su Cruzada Ardiente.', 25549),
(122640, 'esMX', '', 'En un tiempo ya pasado, se luchó una gran batalla que determinaría el destino de todos los mundos. Fue en aquel combate final cuando el todopoderoso panteón de titanes cayó ante uno de los suyos: Sargeras.', 25549),
(122639, 'esMX', '', 'Has llegado al crisol de la creación en busca de respuestas. Escúchalas y encuentra la iluminación.', 25549),
(122638, 'esMX', 'Descansa en paz, camarada.', 'Descansa en paz, camarada.', 25549),
(122637, 'esMX', 'Aquí no hay lugar para la Pesadilla, debemos hacer cuanto podamos para proteger a Malorne. Sin él, el mismo equilibrio de la Naturaleza es vulnerable.$B$BNo creo que haya nada más importante que salvarlo... Incluso a costa de nuestras vidas.', '', 25549),
(122636, 'esMX', '', 'Debe de ser difícil para los dioses salvajes revivir este momento. No puedo ni imaginar el horror cuando invadió la Legión hace tantos años.', 25549),
(122635, 'esMX', '', '¡No me gusta nada este lugar! ¡Librémonos de estos monstruos, archidruida!', 25549),
(122634, 'esMX', '', 'Los enemigos de la Pesadilla son listos. Eligieron el momento de la caída de los Dioses Salvajes hace miles de años, cuando se alzaron para defender Azeroth contra la Legión Ardiente.', 25549),
(122633, 'esMX', 'Sirius, ¿estás bien?', 'Sirius, ¿estás bien?', 25549),
(122632, 'esMX', 'Asha, eres libre.', 'Asha, eres libre.', 25549),
(122631, 'esMX', 'Jagganoth acabará... contigo...', '', 25549),
(122630, 'esMX', '¡$GLADRÓN:LADRONA;!', '', 25549),
(122629, 'esMX', 'Ve con cuidado, $c...', '', 25549),
(122628, 'esMX', '', 'Les dije que pasaría esto. \n\nLES dije. \n\n¡¿Me hicieron caso?!', 25549),
(122627, 'esMX', 'Dime, $c, ¿has explorado las maravillas que Dalaran ofrece? Si no encuentras lo que buscas, seguro que conozco a alguien que pueda echarte una mano.', '', 25549),
(122626, 'esMX', '', '¡Estoy ocupada, lárgate!', 25549),
(122625, 'esMX', '', 'Yaaa sé que estás cooon laaa Legión. Así es como suenas.', 25549),
(122624, 'esMX', 'Saludos, vecinos, ¿cuál es el problema?', '', 25549),
(122623, 'esMX', 'Larry te convertirá en salsa de carne deliciosa.', '', 25549),
(122622, 'esMX', 'Je, este está frito.', '', 25549),
(122621, 'esMX', '¡Por la gloria!', '¡Por la gloria!', 25549),
(122620, 'esMX', 'Le temerán a nuestra ira.', 'Le temerán a nuestra ira.', 25549),
(122619, 'esMX', '¡Mi vida por Odyn!', '¡Mi vida por Odyn!', 25549),
(122618, 'esMX', 'Val''sharah', 'Val''sharah', 25549),
(122617, 'esMX', 'Mi lanza es tuya.', 'Mi lanza es tuya.', 25549),
(122616, 'esMX', 'Val''kyr, ¡ya es la hora! ¡A la batalla!', 'Val''kyr, ¡ya es la hora! ¡A la batalla!', 25549),
(122615, 'esMX', '¡Val''kyr! ¡Recibimos el llamado! ¡Prepárense!', '¡Val''kyr! ¡Recibimos el llamado! ¡Prepárense!', 25549),
(122614, 'esMX', 'Altamontaña', 'Altamontaña', 25549),
(122613, 'esMX', 'Azsuna', 'Azsuna', 25549),
(122612, 'esMX', '¿Puedes sacarme de aquí volando?', '¿Puedes sacarme de aquí volando?', 25549),
(122611, 'esMX', 'Creo que un $c te buscaba en la ciudad, mencionó algo sobre un arma antigua. Deberías hablar con ellos antes de adentrarte en las Islas Quebradas. Necesitarás todos los aliados que puedas.\n\nDigo... Puedo llevarte hasta allá si quieres, pero no te lo recomiendo.', '', 25549),
(122610, 'esMX', 'Creo que nuestras heridas ya se cerraron lo bastante. Seguiré explorando. Que tengas suerte, Lilryia.', '', 25549),
(122609, 'esMX', '', '¡Ah! ¡Me están haciendo enojar!', 25549),
(122608, 'esMX', '', '¿Por qué luchamos?', 25549),
(122607, 'esMX', 'Tenemos suerte de haber recibido la advertencia de Malorne, por muy funesta que haya sido. Temo por el Sueño Esmeralda, si está corrompido, no hay forma de saber cómo afectará a Azeroth.', '', 25549),
(122606, 'esMX', '', '¡Buen combate! Los enemigos de los vigilantes nocturnos pagarán por su traición.', 25549),
(122605, 'esMX', 'Preparado para asaltar Hrydshal.', 'Preparada para asaltar Hrydshal.', 25549),
(122604, 'esMX', '', 'Los magos más poderosos del templo conspiran contra los vigilantes nocturnos. ¡Muéstrales qué hacemos a nuestros enemigos!', 25549),
(122603, 'esMX', '', 'La fuerza se impone a los espíritus. ¡Bien hecho!', 25549),
(122602, 'esMX', '', 'El Templo de las Mil Luces está repleto de espíritus enloquecidos. Hay que aplacarlos.', 25549),
(122601, 'esMX', '<Activar el módulo con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral>.', '<Activar el módulo con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral>.', 25549),
(122600, 'esMX', 'Diría que el módulo perdió su fuente de energía hace mucho.', '', 25549),
(122599, 'esMX', 'Si necesitas ir a Dalaran, mis murciélagos te llevarán.', '', 25549),
(122598, 'esMX', '¿Pero qué...?', '', 25549),
(122597, 'esMX', 'Los Señores del Agua de Hydraxis están contigo, Clarividente. ¡La Legión Ardiente no triunfará!', '', 25549),
(122596, 'esMX', 'Escuchas un extraño crujido procedente de la caverna de más adelante.', 'Escuchas un extraño crujido procedente de la caverna de más adelante.', 25549),
(122595, 'esMX', 'Será un honor para mí.', 'Será un honor para mí.', 25549),
(122594, 'esMX', 'Mi escudo es tuyo.', 'Mi escudo es tuyo.', 25549),
(122593, 'esMX', 'Protegeré.', 'Protegeré.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122592, 'esMX', 'Escuchas un extraño crujido procedente de los portales del piso de abajo.', 'Escuchas un extraño crujido procedente de los portales del piso de abajo.', 25549),
(122591, 'esMX', '', 'Los Descoronados son solo un medio para un fin. El fin de la Legión.', 25549),
(122590, 'esMX', 'Cuernoatroz', 'Cuernoatroz', 25549),
(122589, 'esMX', 'Hidra', 'Hidra', 25549),
(122588, 'esMX', 'Bestia del río', 'Bestia del río', 25549),
(122587, 'esMX', 'Rylak', 'Rylak', 25549),
(122586, 'esMX', 'Mecánico', 'Mecánico', 25549),
(122585, 'esMX', 'Estoy listo para ir en busca de la hoja final.', 'Estoy lista para ir en busca de la hoja final.', 25549),
(122584, 'esMX', '', 'Cálmate, pronto volveremos a casa.', 25549),
(122583, 'esMX', '', 'Si lo rompes, madre debe comprarlo.', 25549),
(122582, 'esMX', '', 'Nada de dedos en el cristal, recuerda lo que platicamos.', 25549),
(122581, 'esMX', '', 'Silencio, deja trabajar a mamá.', 25549),
(122580, 'esMX', '', 'Mantén las manos lejos de mí, $Gpequeño:pequeña;.', 25549),
(122579, 'esMX', '', 'Más vale que no oiga que se rompe nada.', 25549),
(122578, 'esMX', 'Me gustaría revisar la información que reunimos sobre el arma artefacto.', 'Me gustaría revisar la información que reunimos sobre el arma artefacto.', 25549),
(122577, 'esMX', 'El núcleo de la Falla se está cargado. Puedes desplegar el cañón de la Falla cuando quieras.', 'El núcleo de la Falla se está cargado. Puedes desplegar el cañón de la Falla cuando quieras.', 25549),
(122576, 'esMX', 'La orden está clara. Comenzaremos a recargar de inmediato el núcleo de la Falla.', 'La orden está clara. Comenzaremos a recargar de inmediato el núcleo de la Falla.', 25549),
(122575, 'esMX', 'Mimiron me dio una plataforma de teletransporte para casos de emergencia. ¡Como este, por ejemplo!', '', 25549),
(122574, 'esMX', 'Estoy deseando ver a Magni otra vez. Ha pasado mucho tiempo.', '', 25549),
(122573, 'esMX', 'Quienes me invocan han de pagar el peaje. ¡Rinde ahora tu alma eterna!', '', 25549),
(122572, 'esMX', '¿Deseas viajar hasta Helheim? ¡Pues irás! ¡Jajajajaja!', '', 25549),
(122571, 'esMX', '¡Todos los que invocan al barquero deben pagar el peaje!', '', 25549),
(122570, 'esMX', '¡Espíritus! ¡Arrastren a estos mortales hacia las mareas!', '', 25549),
(122569, 'esMX', 'Venado', 'Venado', 25549),
(122568, 'esMX', 'Esta acción cuesta 50|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral. ¿Deseas continuar?', 'Esta acción cuesta 50|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral. ¿Deseas continuar?', 25549),
(122567, 'esMX', '<Libera al sable de maná vínculo vil gastando 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral>.', '<Libera al sable de maná vínculo vil gastando 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral>.', 25549),
(122566, 'esMX', '¡La Luz te quemará!', '', 25549),
(122565, 'esMX', 'Sabes que ahora soy el rey, ¿no?', '', 25549),
(122564, 'esMX', 'Suramar asciende.', 'Suramar asciende.', 25549),
(122563, 'esMX', '<Este sable de maná fue encarcelado por la Legión, pero si se sobrecarga el cristal con maná ancestral, la bestia será liberada>.', '', 25549),
(122562, 'esMX', 'Pones a prueba mi paciencia.', '', 25549),
(122561, 'esMX', 'Este no es el momento para eso.', '', 25549),
(122560, 'esMX', 'Victoria en la Luz.', '', 25549),
(122559, 'esMX', 'Que tengas un buen viaje.', '', 25549),
(122558, 'esMX', 'No pierdas nunca la esperanza.', '', 25549),
(122557, 'esMX', 'Siempre serás $Gbienvenido:bienvenida; en Ventormenta.', '', 25549),
(122556, 'esMX', 'Estate $Gatento:atenta;', '', 25549),
(122555, 'esMX', 'Un rey es tan noble como la causa a la que sirve y no más.', '', 25549),
(122554, 'esMX', 'Por la Alianza, por encima de todo.', '', 25549),
(122553, 'esMX', 'Por una causa justa siempre vale la pena luchar.', '', 25549),
(122552, 'esMX', 'A veces debemos pelear por aquello en lo que creemos.', '', 25549),
(122551, 'esMX', 'Saludos, $Gamigo:amiga;.', '', 25549),
(122550, 'esMX', 'Ventormenta resistirá.', '', 25549),
(122549, 'esMX', 'Ventormenta honra tu servicio a la Alianza.', '', 25549),
(122548, 'esMX', '¡La Legión Ardiente temblará ante el poder de los Cuatro Jinetes!', '', 25549),
(122547, 'esMX', '¡Jinetes! Nuestro destino está cerca.', '', 25549),
(122546, 'esMX', '¡No! ¡No permitiré que caiga la Espada de Ébano!', '', 25549),
(122545, 'esMX', '¡Soy demasiado rico para morir así!', '¡Soy demasiado rico para morir así!', 25549),
(122544, 'esMX', 'Guardias, ¿para qué les pagamos? ¡Maten a la bestia!', 'Guardias, ¿para qué les pagamos? ¡Maten a la bestia!', 25549),
(122543, 'esMX', '¡Su''esh está suelta! ¡Huid!', '¡Su''esh está suelta! ¡Huid!', 25549),
(122542, 'esMX', '¡Vamos a morir!', '¡Vamos a morir!', 25549),
(122541, 'esMX', '¡Quieres pelear por mi isla! ¡Muy bien! ¡La regaré con tu sangre!', '', 25549),
(122540, 'esMX', '', 'Pelearé con honor por la Orden de la Mano de plata, $ct.', 25549),
(122539, 'esMX', '¿¡Qué!?', '¿¡Qué!?', 25549),
(122538, 'esMX', '¡Ja! ¡¿Dónde están ahora tus malignos de maná?!', '¡Ja! ¡¿Dónde están ahora tus malignos de maná?!', 25549),
(122537, 'esMX', '¿Hay que limpiar algo?', '', 25549),
(122536, 'esMX', 'No hay tiempo para hablar. Tenemos que limpiar.', '', 25549),
(122535, 'esMX', 'Tengo muchas cosas que hacer. D-debo trabajar.', '', 25549),
(122534, 'esMX', 'Muy bien. ¡A Ulduar!', 'Muy bien. ¡A Ulduar!', 25549),
(122533, 'esMX', '¡Más vale que nos movamos, $n!', '', 25549),
(122532, 'esMX', '¡NO ME VAN A QUITAR MI ISLA!', '', 25549),
(122531, 'esMX', 'Un trabajo ingrato, pero hiciste lo que había que hacer. Prepararé las Lágrimas de Elune para el transporte. Reúnete conmigo en la Ciudadela Violeta.', '', 25549),
(122530, 'esMX', '¡BÚSCATE TU PROPIA ISLA, MALDITA SEA!', '', 25549),
(122529, 'esMX', '¡ESTA ES MI ISLA!', '', 25549),
(122528, 'esMX', 'Los guardias te olfatean, y gruñen suavemente.', '', 25549),
(122527, 'esMX', 'Con gusto.', 'Con gusto.', 25549),
(122526, 'esMX', '¡Maravilloso! Es magnífico ver que $Gun joven héroe:una joven heroína; como tú tiene tiempo para un poco de historia. Hay quien dice que, a fin de cuentas, lo único que importa es lo que dejamos atrás.\n\nTengo algo aquí... Un volumen totalmente distinto que podría ofrecerte a cambio de los grandes esfuerzos que hiciste con esto. ¿Lo quieres?', '', 25549),
(122525, 'esMX', 'Terminé de reunir todos los volúmenes.', 'Terminé de reunir todos los volúmenes.', 25549),
(122524, 'esMX', '$ct, ¡te estuve buscando por todas partes! Ah, ¿la cabeza de la bola de cristal? Estoy probando algo nuevo.', '', 25549),
(122523, 'esMX', '<Algo terrible le ha ocurrido a este viajero errante.>\n\n<Por desgracia, no hay manera de liberarlo.>', '', 25549),
(122522, 'esMX', '<Algo terrible le sucedió a este solitario errante>.', '', 25549),
(122521, 'esMX', 'Reclutar templario de la Mano de plata', 'Reclutar templario de la Mano de plata', 25549),
(122520, 'esMX', 'Reclutar caballeros de la Mano de plata', 'Reclutar caballeros de la Mano de plata', 25549),
(122519, 'esMX', '¿En qué puedo ayudarte hoy?', '¿En qué puedo ayudarte hoy?', 25549),
(122518, 'esMX', 'Temporizador de juego', 'Temporizador de juego', 25549),
(122517, 'esMX', 'Terminar ronda actual', 'Terminar ronda actual', 25549),
(122516, 'esMX', 'Nivel 4 defendido', 'Nivel 4 defendido', 25549),
(122515, 'esMX', 'Nivel 3 defendido', 'Nivel 3 defendido', 25549),
(122514, 'esMX', 'Nivel 2 defendido', 'Nivel 2 defendido', 25549),
(122513, 'esMX', '<Imbuye uno de los tridentes con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral>.', '<Imbuye uno de los tridentes con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral>.', 25549),
(122512, 'esMX', 'Nivel 1 defendido', 'Nivel 1 defendido', 25549),
(122511, 'esMX', 'El aspecto de esas armas mundanas no induce a creer en un potencial oculto.', '', 25549),
(122510, 'esMX', 'Escuchas un salvaje chirrido procedente del portal de las Tierras del Interior.', 'Escuchas un salvaje chirrido procedente del portal de las Tierras del Interior.', 25549),
(122509, 'esMX', 'Escuchas un salvaje chirrido procedente del portal de Feralas.', 'Escuchas un salvaje chirrido procedente del portal de Feralas.', 25549),
(122508, 'esMX', 'Escuchas un salvaje chirrido procedente del portal del Bosque del Ocaso.', 'Escuchas un salvaje chirrido procedente del portal del Bosque del Ocaso.', 25549),
(122507, 'esMX', '', 'Si quieres que algo salga bien, tienes que matarlo tú mismo...', 25549),
(122506, 'esMX', '', '¡Deja que te muestre el poder de la Legión!', 25549),
(122505, 'esMX', 'Mi vida por la Luz.', 'Mi vida por la Luz.', 25549),
(122504, 'esMX', 'Pelearé por ti.', 'Pelearé por ti.', 25549),
(122503, 'esMX', 'Escuchas que algo se aleja corriendo detrás de ti... y luego, solo silencio.', 'Escuchas que algo se aleja corriendo detrás de ti... y luego, solo silencio.', 25549),
(122502, 'esMX', 'Buen combate...', '', 25549),
(122501, 'esMX', 'Te... maldigo...', '', 25549),
(122500, 'esMX', 'Serás un buen calentamiento. Tengo que entrenar.', '', 25549),
(122499, 'esMX', 'Soy el hijo del maestro. Estás en desventaja.', '', 25549),
(122498, 'esMX', '¡Ayudemos a nuestros aliados bajo la Luz y defendamos el Templo Luz Abisal!', '', 25549),
(122497, 'esMX', 'Estamos armados y listos para pelear, $GSumo Sacerdote:Suma Sacerdotisa;.', '', 25549),
(122496, 'esMX', '¡La Legión inició su ataque! ¡Tenemos que defender el Templo Luz Abisal!', '¡La Legión inició su ataque! ¡Tenemos que defender el Templo Luz Abisal!', 25549),
(122495, 'esMX', 'Parece que llegamos justo a tiempo.', '', 25549),
(122494, 'esMX', '¡Explosiones! ¡MÁS explosiones! ¡Tengo que provocar más explosiones!', '', 25549),
(122493, 'esMX', '¡Usurpadores! ¡Gnomeregan es mía!', '', 25549),
(122492, 'esMX', 'Jinetes, ¡llegó nuestra hora!', '', 25549),
(122491, 'esMX', 'Nos reuniremos en el piso superior cuando estés listo, señor de la Muerte.', '', 25549),
(122490, 'esMX', 'Llegó la hora de asumir mi posición como líder de los Cuatro Jinetes.', '', 25549),
(122489, 'esMX', 'La Cicatriz Aterradora está a tus órdenes, $GSeñor Supremo:Señora Suprema;.\n\nQue los mundos de tus enemigos caigan a tus pies.', '', 25549),
(122488, 'esMX', '', '¡Cortesanos! ¡Cúbrannos mientras continuamos con el ritual!', 25549),
(122487, 'esMX', 'No temas, ¡usaré el poder de la Fuente de la Noche para acabar con ellos!', '', 25549),
(122486, 'esMX', '¡Intrusos!', '', 25549),
(122485, 'esMX', 'Tu intrusión no pasó inadvertida, pero el ritual continúa.', 'Tu intrusión no pasó inadvertida, pero el ritual continúa.', 25549),
(122484, 'esMX', '¡|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s invocó una |cFFFF0000|Hspell:226089|h[imagen de sombra]|h|r! ¡Destiérrala!', '¡|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s invocó una |cFFFF0000|Hspell:226089|h[imagen de sombra]|h|r! ¡Destiérrala!', 25549),
(122483, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(122482, 'esMX', 'Ven conmigo a la Semilla de los tiempos, Archidruida. Allá desvelaremos nuevos misterios de tu arma.', '', 25549),
(122481, 'esMX', '¡La Pesadilla comienza a llevarte!', '¡La Pesadilla comienza a llevarte!', 25549),
(122480, 'esMX', '¡Es la hora! Vanguardia de la Mano de plata, ¡a la batalla!', '¡Es la hora! Vanguardia de la Mano de plata, ¡a la batalla!', 25549),
(122479, 'esMX', '¡Por gloria y honor!', '¡Por gloria y honor!', 25549),
(122478, 'esMX', 'Sí, llévame. Aún tengo que hacer muchas cosas.', 'Sí, llévame. Aún tengo que hacer muchas cosas.', 25549),
(122477, 'esMX', 'Nuestra misión aquí es muy importante. Sin embargo, si tienes que realizar más preparativos puedo devolverte al Aetherium. ¿Quieres que lo haga?', 'Nuestra misión aquí es muy importante. Sin embargo, si tienes que realizar más preparativos puedo devolverte al Aetherium. ¿Quieres que lo haga?', 25549),
(122476, 'esMX', 'Aún tengo que prepararme.', 'Aún tengo que prepararme.', 25549),
(122475, 'esMX', '<El portal emite un zumbido mágico>.', '', 25549),
(122474, 'esMX', 'Descifrando', 'Descifrando', 25549),
(122473, 'esMX', 'Mi señor, ofrezco mis armas a tu causa.', 'Mi señora, ofrezco mis armas a tu causa.', 25549),
(122472, 'esMX', '¡Paladines de la Mano de plata! ¡Adelántense y prepárense para la batalla!', '¡Paladines de la Mano de plata! ¡Adelántense y prepárense para la batalla!', 25549),
(122471, 'esMX', 'Ven, $n. Reúnete conmigo junto a la Forja del Guardián.', '', 25549),
(122470, 'esMX', '¡¿Qué clase de fauces viles lanzaron esos demonios sobre nosotros?! ¡Que la Madre Luna nos ayude a todos!', '', 25549),
(122469, 'esMX', 'Nos veremos en Dalaran, sobre el Paso de la Muerte. Tengo un plan. Un plan terriblemente peligroso... ¡pero un plan, al menos!', '', 25549),
(122468, 'esMX', 'Necesitamos los Pilares de la Creación para devolver los demonios al Vacío Abisal y salvar nuestro mundo.', '', 25549),
(122467, 'esMX', '¡Dalaran está bajo asedio, $n! ¡La Legión quiere expulsarnos del cielo!', '', 25549),
(122466, 'esMX', '', 'Lleva tu tabardo con orgullo, $n. Nuestro color rojo ocultará tus heridas de tus enemigos.', 25549),
(122465, 'esMX', '¡Ja! Pronuncié cinco palabras, ese es mi límite.', '', 25549),
(122464, 'esMX', 'Cuéntame más sobre tus publicaciones.', 'Cuéntame más sobre tus publicaciones.', 25549),
(122463, 'esMX', 'Debemos descansar, maestro.', 'Debemos descansar, maestra.', 25549),
(122462, 'esMX', 'Guardia lunar, ¡concentren sus energías en mí! ¡Mostraremos a estos monstruos el poder de lo arcano!', '', 25549),
(122461, 'esMX', '¡Señor, por atrás! ¡Se abrieron otras fauces viles!', '', 25549),
(122460, 'esMX', 'Ese es el problema de la magia, ¡nunca se sabe cuándo te va a dar la espalda!', '', 25549),
(122459, 'esMX', 'Siempre odié a los elementales de agua... ¡Sobre todo a los grandes, como este!', '', 25549),
(122458, 'esMX', 'La pesca puede esperar, ¡ayúdame a acabar con este elemental!', '', 25549),
(122457, 'esMX', '¿Vas a golpearme primero o solo a mirarme como $Gun cobarde rastrero:una cobarde rastrera;?', '', 25549),
(122456, 'esMX', '', 'Ven, escoria extranjera. Hasta te dejaré dar el primer golpe. Aprovéchalo.', 25549),
(122455, 'esMX', 'Pedir una bendición', 'Pedir una bendición', 25549),
(122454, 'esMX', '', 'La Orden está contigo.', 25549),
(122453, 'esMX', '', 'Elisande pagará por su traición.', 25549),
(122452, 'esMX', '¡Atravesamos la puerta de la prisión! ¡El camino hacia Dalaran está despejado!', '', 25549),
(122451, 'esMX', 'Debieron escucharme desde el principio y destruir esos sátiros antes de que pasara esto.\n\nTe doy las gracias, $p, por liberarme de la locura de Xavius.', '', 25549),
(122450, 'esMX', '', 'El poder de la Fuente de la Noche me llama.', 25549),
(122449, 'esMX', '', 'Mucho he esperado para volver a casa...', 25549),
(122448, 'esMX', '<Usa 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral para extraer una parte de la energía ley>.', '<Usa 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral para extraer una parte de la energía ley>.', 25549),
(122447, 'esMX', 'Adelante, no podemos demorarnos mucho aquí.', '', 25549),
(122446, 'esMX', 'El resguardo palpita con energía rebosante.', '', 25549),
(122445, 'esMX', 'La Legión caerá hoy, $Gcampeón:campeona;.', '', 25549),
(122444, 'esMX', 'Debemos detener a Gul''dan antes de que pueda completar el ritual.', '', 25549),
(122443, 'esMX', 'La señora Goya empacó sus cosas y me dejó al cargo de todo. Dijo algo sobre una ciudad en el cielo. ¡Ja! ¡Como si las ciudades volaran!', '', 25549),
(122441, 'esMX', '¿Puede el poder de la esencia de claridad guiarnos hasta el corazón de la Pesadilla?', '¿Puede el poder de la esencia de claridad guiarnos hasta el corazón de la Pesadilla?', 25549),
(122440, 'esMX', '¡Estoy listo para comenzar la defensa del Templo Luz Abisal!', '¡Estoy lista para comenzar la defensa del Templo Luz Abisal!', 25549),
(122439, 'esMX', 'No podemos esperar mucho más. Debemos encarar a la Legión de frente.', '', 25549),
(122438, 'esMX', 'Deberíamos continuar con nuestra patrulla. No hay forma de saber cuántas de estas incursiones asolan la tierra.', '', 25549),
(122437, 'esMX', 'Esperaba más de esos demonios. Tal vez encontremos un señor del foso. Siempre quise encadenar la esencia de uno.', '', 25549),
(122436, 'esMX', 'El ritual se rompió. La figura suspendida dentro de la Fuente de la Noche despierta.', 'El ritual se rompió. La figura suspendida dentro de la Fuente de la Noche despierta.', 25549),
(122435, 'esMX', 'Escuchas los medidos cánticos y movimientos de un complejo ritual en el interior de La Aguja.', 'Escuchas los medidos cánticos y movimientos de un complejo ritual en el interior de La Aguja.', 25549),
(122434, 'esMX', 'Los guardianes de la Pesadilla cayeron. ¿Qué más hay que hacer para abrir el camino hasta Xavius?', 'Los guardianes de la Pesadilla cayeron. ¿Qué más hay que hacer para abrir el camino hasta Xavius?', 25549),
(122433, 'esMX', '¡Lo lograron, campeones! El Iris está abierto. Cuando quieran, les abriré el paso.', '', 25549),
(122432, 'esMX', '<Realiza una ofrenda de 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral>.', '<Realiza una ofrenda de 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral>.', 25549),
(122431, 'esMX', 'Asher, hijo de Exurotus, la nueva Furia de Pirofrío, desea otorgarte esta bendición.', '', 25549),
(122430, 'esMX', '$ct, te convocaron. Sígueme.', '', 25549),
(122429, 'esMX', 'Por lo que parece, esta fuente lleva algún tiempo sin usarse.', '', 25549),
(122421, 'esMX', 'Héroes de la Alianza, les escribo en las horas más oscuras de Azeroth. Los ejércitos ardientes de la Legión han regresado de las fauces del infierno.', '', 25549),
(122420, 'esMX', '$GMaestro:Maestra;, tu arma y tu experiencia demuestran que hasta los valarjar pueden aprender de las razas jóvenes. Estos son nuevos enemigos y nuevas formas de pelear que no he visto en mis numerosos años de experiencia. Me diste mucho con lo que trabajar, gracias.', '', 25549),
(122419, 'esMX', '¡Hay que contenerlos! ¡No podemos perder la ciudad!', '', 25549),
(122418, 'esMX', '¡Nos sorprendieron con la guardia baja! ¡Hay que acabar con esos malditos demonios de una vez por todas!', '', 25549),
(122417, 'esMX', 'Si no detenemos a Xavius, la Pesadilla consumirá todo Azeroth.', '', 25549),
(122416, 'esMX', 'Más vale tarde que nunca, ¿eh? Los que aún respiramos seguimos peleando. ¿Estás lis...?', '', 25549),
(122415, 'esMX', '¡No te quedes ahí, $n! ¡Esos demonios no se van a destruir solos!', '', 25549),
(122414, 'esMX', '¡Señor de la Guerra!', '', 25549),
(122413, 'esMX', '|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t¡El $n |cFFFF0000|Hspell:202663|h[estalla]|h|r antes de morir!', '', 25549),
(122412, 'esMX', '¡Vete!', '¡Vete!', 25549),
(122411, 'esMX', '', 'Termina de mezclar ese mojo, ¡hay que llegá a la Coh''ta Quebrada!', 25549),
(122410, 'esMX', '¡Despiértame de esta pesadilla!', '¡Despiértame de esta pesadilla!', 25549),
(122409, 'esMX', 'Este lugar... Es mucho peor de lo que podría haber imaginado.', '', 25549),
(122408, 'esMX', '¡|TInterface\\Icons\\sha_spell_shadow_shadesofdarkness_nightmare:20|t%s comienza a lanzar |cFFFF0000|Hspell:214876|h[bestias de la Pesadilla]|h|r!', '', 25549),
(122407, 'esMX', '', 'Lunargenta se encuentra detrás de ti, $n. Permítenos bendecir tu arma con poder sagrado.', 25549),
(122406, 'esMX', 'Una hoja de demonio puede encontrar hasta la más pequeña grieta en tu armadura, $n. Repárala si no quieres acabar con tu cabeza en una pica.', '', 25549),
(122405, 'esMX', '<Inserta 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral en la matriz de defensa>.', '<Inserta 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná ancestral en la matriz de defensa>.', 25549),
(122404, 'esMX', '<La matriz de defensa no parece tener poder.>', '', 25549),
(122403, 'esMX', 'Tengo que volver a la superficie.', 'Tengo que volver a la superficie.', 25549),
(122402, 'esMX', 'Si no estás $Gseguro:segura; del camino que vas a emprender, puedo devolverte a la superficie. ¿Quieres que lo haga?', '', 25549),
(122401, 'esMX', '', '¡No hay nadie que supere mi destreza!$b$bPero escuché que tengo competencia. Hay otro herrero en las afueras de la ciudad.$b$bMe gustan los retos. ¡Adelante! ¡Ja, ja, ja!', 25549),
(122400, 'esMX', '', 'Uy.$b$bA tu armadura no le vendrían mal unas reparaciones.', 25549),
(122399, 'esMX', '$GBienvenido:Bienvenida;. ¿Qué puedo hacer por ti?', '', 25549),
(122398, 'esMX', '', '¡Siéntate y relájate!', 25549),
(122397, 'esMX', '', '¡Nos quedamos sin vino, pero tenemos mucha comida, bebidas y lugares para que puedas descansar!', 25549),
(122396, 'esMX', '', '¡Hola, cariño!$b$b¿En qué puedo ayudarte?', 25549),
(122395, 'esMX', '', 'El cristal está cargado. Puedes usarlo a voluntad.', 25549),
(122394, 'esMX', '<Rottgut se voltea hacia ti y eructa con fuerza>.$b$bRottgut... ¡Rott-gut!', '', 25549),
(122393, 'esMX', '', 'Conjuradores, ¡que comience la canalización!', 25549),
(122392, 'esMX', '¡Es el Guardián de G''Hanir! ¡Contamos contigo, $n!', '¡Es la Guardiana de G''Hanir! ¡Contamos contigo, $n!', 25549),
(122391, 'esMX', '¡Es $n! ¡$gEl héroe:La heroína; que purgó la corrupción de G''Hanir!', '¡Es $n! ¡$gEl héroe:La heroína; que purgó la corrupción de G''Hanir!', 25549),
(122390, 'esMX', 'Me alegra ver que G''Hanir está en buenas manos.', 'Me alegra ver que G''Hanir está en buenas manos.', 25549),
(122389, 'esMX', '¡El Guardián de G''Hanir está aquí! ¡Elune te bendice, $n!', '¡La Guardiana de G''Hanir está aquí! ¡Elune te bendice, $n!', 25549),
(122388, 'esMX', '¡Me alegra que el Círculo Cenarion te tenga entre sus filas, $gportador:portadora; del Colmillo!', '¡Me alegra que el Círculo Cenarion te tenga entre sus filas, portador:portadora; del Colmillo!', 25549),
(122387, 'esMX', 'Dalaran cambió de posición para defender los Reinos del Este. La encontrarás sobre el Paso de la Muerte, justo encima de Karazhan. Reúnete conmigo allá.', '', 25549),
(122386, 'esMX', '$n, reconozco esas dagas. Son los Colmillos de Ashamane, ¿no? Debes haber hecho algo sorprendente para que los cinéreos te permitieran conservarlas.', '$n, reconozco esas dagas. Son los Colmillos de Ashamane, ¿no? Debes haber hecho algo sorprendente para que los cinéreos te permitieran conservarlas.', 25549),
(122385, 'esMX', 'No me gusta tener que interrumpir tan importante tarea, pero me vendría muy bien tu ayuda para una cuestión de... diplomacia. Me temo que estoy a punto de enojar a un viejo amigo.', '', 25549),
(122384, 'esMX', 'Saludos, $n. Llegaron a mis oídos los rumores sobre tus esfuerzos para repeler la invasión de la Legión.', '', 25549),
(122383, 'esMX', '¡Los Colmillos de Ashamane! ¡Pensé que los cinéreos jamás les quitarían los ojos de encima!', '¡Los Colmillos de Ashamane! ¡Pensé que los cinéreos jamás les quitarían los ojos de encima!', 25549),
(122382, 'esMX', 'Qué aspecto tan raro que tienen esas garras. ¿Acaso son... dientes?', 'Qué aspecto tan raro que tienen esas garras. ¿Acaso son... dientes?', 25549),
(122381, 'esMX', '¡Los Colmillos de Ashamane! ¡El rumor sobre el ataque contra el santuario cinéreo era cierto!', '¡Los Colmillos de Ashamane! ¡El rumor sobre el ataque contra el santuario cinéreo era cierto!', 25549),
(122380, 'esMX', '', 'Tethys nos llevará en una de sus naves. Navegaremos a vela hasta perder de vista la costa y luego nos llevará a remo al caer la oscuridad, cuando la densa niebla cubra las aguas.\n\nAvísame cuando estés $Glisto:lista; para partir, $n.', 25549),
(122379, 'esMX', '¡Salve, Archidruida $n, el elegido de Ursoc!', '¡Salve, Archidruida $n, la elegida de Ursoc!', 25549),
(122378, 'esMX', '¡$gNuestro campeón:Nuestra campeona; está aquí con las Garras de Ursoc! ¡La Legión tiene los días contados!', '¡$gNuestro campeón:Nuestra campeona; está aquí con las Garras de Ursoc! ¡La Legión tiene los días contados!', 25549),
(122377, 'esMX', 'Los rumores son ciertos. ¡$n empuña las Garras de Ursoc!', 'Los rumores son ciertos. ¡$n empuña las Garras de Ursoc!', 25549),
(122376, 'esMX', 'Esas garras se ven muy afiladas. ¡Me alegra que estés de nuestro lado!', 'Esas garras se ven muy afiladas. ¡Me alegra que estés de nuestro lado!', 25549),
(122375, 'esMX', 'Bienvenido, Shan''do. Es un honor encontrarse con el amo de la guadaña.', 'Bienvenida, Shan''do. Es un honor encontrarse con la ama de la guadaña.', 25549),
(122374, 'esMX', '¡La Guadaña de Elune! Debe ser un gran peligro el que nos amenaza si necesitamos el poder de tal arma.', '¡La Guadaña de Elune! Debe ser un gran peligro el que nos amenaza si necesitamos el poder de tal arma.', 25549),
(122373, 'esMX', '¿Eso que llevas es la Guadaña de Elune? ¿Es cierto que te transforma en una bestia?', '¿Eso que llevas es la Guadaña de Elune? ¿Es cierto que te transforma en una bestia?', 25549),
(122372, 'esMX', 'Cuidado con esa guadaña, Shan''do. Preferiría no perder el control de mi mente.', 'Cuidado con esa guadaña, Shan''do. Preferiría no perder el control de mi mente.', 25549),
(122371, 'esMX', 'Elune-Ado... Alto, ¿es la Guadaña de Elune lo que llevas en la mano? ¡Asombroso!', 'Elune-Ado... Alto, ¿es la Guadaña de Elune lo que llevas en la mano? ¡Asombroso!', 25549),
(122370, 'esMX', '', 'El ritual está terminado. ¡Hay que contenerlo, deprisa!', 25549),
(122369, 'esMX', '', '¡Sí, sí! ¡Funciona!', 25549),
(122368, 'esMX', '', '¡Invocadores, comiencen el ritual!', 25549),
(122367, 'esMX', '', 'Yo, y solo yo debo cargar con los crímenes de mi pasado. Sin embargo, la Legión Ardiente corrompió mi antigua orden y nos sacó del camino de la rectitud.$b$b¡Haré que la Legión pague por su traición!', 25549),
(122366, 'esMX', 'Esta acción cuesta 20|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 'Esta acción cuesta 20|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 25549),
(122365, 'esMX', '<Alimenta al nato nocturno maldito con 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná ancestral.>', '<Alimenta al nato nocturno maldito con 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná ancestral.>', 25549),
(122364, 'esMX', '¿Convertir a Shal''Aran en tu nuevo hogar?', '¿Convertir a Shal''Aran en tu nuevo hogar?', 25549),
(122363, 'esMX', 'Quiero vincular mi piedra de hogar aquí.', 'Quiero vincular mi piedra de hogar aquí.', 25549),
(122362, 'esMX', 'Deseo comerciar.', 'Deseo comerciar.', 25549),
(122361, 'esMX', '', '¡Fuera de aquí, peste!', 25549),
(122360, 'esMX', '¡Zepelín desbocado! ¡Todos entren en pánico!', '', 25549),
(122359, 'esMX', '¡Manténganse lejos! ¡Este zepelín tiene mente propia!', '', 25549),
(122358, 'esMX', '¡Cuidado! ¡No logro controlar esta cosa!', '', 25549),
(122357, 'esMX', '¡Fuera de mi camino! ¡Esta cosa no piensa en la seguridad!', '', 25549),
(122356, 'esMX', '¡Manténganse lejos! ¡Quién sabe lo que le pasa a esta cosa!', '', 25549),
(122355, 'esMX', '¿Qué buscas?', '', 25549),
(122354, 'esMX', '', '¿Puedo ayudarte en algo?', 25549),
(122353, 'esMX', 'La Mano Destrozada volverá a su antigua gloria.', '', 25549),
(122352, 'esMX', '¿En qué puedo ayudarte, Sombra $n?', '', 25549),
(122351, 'esMX', '', 'Estos elementales son unos aliados poderosos en nuestra batalla contra la Legión Ardiente.', 25549),
(122350, 'esMX', 'Saludos.', '', 25549),
(122349, 'esMX', '¿Qué buscas?', '', 25549),
(122348, 'esMX', '¿Qué quieres que haga por ti?', '', 25549),
(122347, 'esMX', '', 'Que estos diablillos te resulten útiles, $GSeñor Abisal:Señora Abisal;.', 25549),
(122346, 'esMX', '', 'Puedes estar $Gtranquilo:tranquila; de que estos arqueros siempre darán en el blanco.', 25549),
(122345, 'esMX', '¡Estos aspirantes valarjar nos ayudarán en nuestra batalla contra la Legión Ardiente!', '', 25549),
(122344, 'esMX', '¡Mosquito insignificante!', '', 25549),
(122343, 'esMX', '¡IN-FIER-NO!', '', 25549),
(122342, 'esMX', '¡Gnomo insignificante! ¡Tu arrogancia será tu perdición!', '', 25549),
(122341, 'esMX', '¡ARRANCARÉ LA CARNE!', '', 25549),
(122340, 'esMX', '¡Te enfrentas a Jaraxxus, señor Eredar de la Legión Ardiente!', '', 25549),
(122339, 'esMX', '¡Gee!... ¡Gee!... Por favor, recuérdale al cajero Gee que sigo aquí, esperando pacientemente a volver a mi estado normal. Muchas gracias.', '', 25549),
(122338, 'esMX', '¡Ah, otro valioso cliente! ¡$gBienvenido:Bienvenida;, $gbienvenido:bienvenida;!', '', 25549),
(122337, 'esMX', '¡Todo está bien! Sigan con sus asuntos con normalidad. ¡Tenemos todo bajo control!', '', 25549),
(122336, 'esMX', 'Recuérdale a Gee que requeriré un pago adicional. Técnicamente aún estoy detrás del mostrador.', '', 25549),
(122335, 'esMX', '¡Resolveremos esto en poco tiempo! Por favor, un poco de paciencia.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122334, 'esMX', 'Esto es completamente normal. ¡No se alarmen!', '', 25549),
(122333, 'esMX', '¡Estamos al tanto de la situación y todo está bajo control!', '', 25549),
(122332, 'esMX', '', '¿Estás $glisto:lista;, $n? Cuando quieras, donde quieras.', 25549),
(122330, 'esMX', 'Iré a un lugar seguro. ¡No volverán a atraparme.', 'Iré a un lugar seguro. ¡No volverán a atraparme.', 25549),
(122329, 'esMX', 'Te... te lo agradezco. Ya empezaban a sonar hambrientos...', 'Te... te lo agradezco. Ya empezaban a sonar hambrientos...', 25549),
(122328, 'esMX', 'Gracias por rescatarme de ese terrible lugar.$b$bSoy muy útil para restaurar equipo. ¿Necesites que repare algo?', '', 25549),
(122327, 'esMX', 'Tu tarjeta de sonido funciona correctamente.', '', 25549),
(122326, 'esMX', 'El pronóstico no luce claro. Reúne 4289 cristales de ápices más y vuelve a preguntar.', '', 25549),
(122325, 'esMX', 'Poco probable... no en esta línea temporal.', '', 25549),
(122324, 'esMX', 'Déjame preguntarle a mis fuentes... sí.', '', 25549),
(122323, 'esMX', 'Déjame preguntarle a mis fuentes... no.', '', 25549),
(122322, 'esMX', 'Quizás sobrevivirás. Quizás.', '', 25549),
(122321, 'esMX', 'Respuesta... borrosa... intenta otra vez.', '', 25549),
(122320, 'esMX', 'La derrota es segura.', '', 25549),
(122319, 'esMX', 'Tu pronóstico es seguro. ¡Una muerte segura!', '', 25549),
(122318, 'esMX', 'Nooooo... de hecho, sí.', '', 25549),
(122317, 'esMX', '', 'Y levántate, renace como el escudo del hombre, la mano de la devoción y la espada de las represalias.', 25549),
(122316, 'esMX', 'Le fallé a mi reino y a mi gente... No le fallaré también a mi mundo.', '', 25549),
(122315, 'esMX', 'Por favor, regresa en unos pocos días. Valoramos mucho hacer negocios contigo...', '', 25549),
(122314, 'esMX', '¡Nuestro personal está trabajando día y noche para asegurar que tus pertenencias estén a salvo! No hay absolutamente nada que temer.', '', 25549),
(122313, 'esMX', 'No hay absolutamente nada de qué preocuparse. Solo unos pocos efectos secundarios por mover a una enorme y mágica ciudad.', '', 25549),
(122312, 'esMX', 'Sí, sí. Sabemos como luce. Todas tus queridas pertenencias estarán aquí cuando volvamos a abrir. Te doy mi palabra.', '', 25549),
(122311, 'esMX', '¡Gente! ¡Gente! Por favor... Aunque suene raro, tenemos todo bajo control. Conseguimos guardias extra para asegurar que no se pierda nada.', '', 25549),
(122310, 'esMX', '¡Todos atrás! Es solo otro efecto secundario de trasladar a la ciudad. ¡Volveremos a abrir pronto!', '', 25549),
(122309, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122308, 'esMX', 'Saludos, $n. Tengo algunas cosas que te pueden parecer útiles.', '', 25549),
(122307, 'esMX', '', 'El oro ilumina incluso un lugar oscuro como este.', 25549),
(122306, 'esMX', '¿Qué tienes a la venta?', '¿Qué tienes a la venta?', 25549),
(122305, 'esMX', '¿Qué tienes a la venta?', '¿Qué tienes a la venta?', 25549),
(122304, 'esMX', '', 'Tu llama arde con fuerza hoy, $n.', 25549),
(122303, 'esMX', '¡No *hip* interrumpas! Necesitamos el poder de la Fuente de la Noche...', '¡No *hip* interrumpas! Necesitamos el poder de la Fuente de la Noche...', 25549),
(122302, 'esMX', 'Sin importar lo que hagas, no comas la fruta de los cuencos.$b$bSon de pésima calidad. Si quieres probar lo mejor que Suramar tiene para ofrecer, permíteme mostrarte los verdaderos sabores.', '', 25549),
(122301, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122300, 'esMX', '', '¡Hola, $n! ¿Cómo puedo ayudarte hoy?', 25549),
(122299, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122298, 'esMX', '', '¡Hola, $n! ¿Cómo puedo ayudarte hoy?', 25549),
(122297, 'esMX', '', '¡No pasarás a través de nosotros, Lady Keletress!', 25549),
(122296, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122295, 'esMX', '$gBienvenido:Bienvenida;, $n. Tengo algunas cosas que te pueden parecer útiles.', '', 25549),
(122294, 'esMX', '¡Correcto!', '', 25549),
(122293, 'esMX', 'Que los elementos te sirvan.', '', 25549),
(122292, 'esMX', '', '$gBienvenido:Bienvenida;, $n. Que los Celestiales te cuiden.', 25549),
(122291, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122290, 'esMX', 'Hmm... ¿ninguna oveja especial? ¡Demonios! Más suerte para mañana, ¿eh?', '', 25549),
(122289, 'esMX', '', 'Los escuderos no se entrenan muy rápido, pero apresuraré esta orden por ti.', 25549),
(122288, 'esMX', '', '¿Cómo pudieron creer las mentiras del Heraldo? Hay magia oscura detrás de todo esto, marca mis palabras.\n\nPor favor, si puedes hacer algo para detener esto, hazlo ahora. Se han perdido tantas vidas inocentes...', 25549),
(122287, 'esMX', 'Si Toryl dice que viniste a ayudarnos, entonces puedes quedarte en nuestro hogar. ¡Prueba nuestra carne e hidromiel!', '', 25549),
(122286, 'esMX', '¡Oh, no! Cómo cambiaron las cosas.', '', 25549),
(122285, 'esMX', 'En mis tiempos, estos árboles eran más verdes.', '', 25549),
(122283, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122282, 'esMX', 'Tengo algunos objetos que puedes encontrar útiles, $n.', '', 25549),
(122281, 'esMX', 'Perdón por el engaño, $n. ¡No interferiría con las pruebas, ni siquiera por mi $gcampeón elegido:campeona elegida;!', '', 25549),
(122280, 'esMX', 'Estos necrófagos están listos para seguir tus órdenes,$gSeñor:Señora; de la Muerte.', '', 25549),
(122279, 'esMX', 'Recluta a un Eco de un Celestial', 'Recluta a un Eco de un Celestial', 25549),
(122278, 'esMX', '¡Hola!', '¡Hola!', 25549),
(122277, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122276, 'esMX', '¿Cómo puedo ayudarte, $n?', '', 25549),
(122275, 'esMX', 'Que la gloria de Odyn te acompañe, Valarjar.', '', 25549),
(122274, 'esMX', 'Recluta a un Anciano de la Guerra', 'Recluta a un Anciano de la Guerra', 25549),
(122273, 'esMX', '<hojas crujiendo>', '<hojas crujiendo>', 25549),
(122272, 'esMX', '¡Por aquí, $gamigo:amiga; $c! Este tiene cosas brillantes que ofrecer. ¡Mira!', '', 25549),
(122271, 'esMX', 'Inicia el ritual.', 'Inicia el ritual.', 25549),
(122270, 'esMX', 'El vermis de escarcha quiere liberarse.', '', 25549),
(122269, 'esMX', 'Escuché historias de tus hazañas. Veamos si son más que historias, ¿quieres?', '', 25549),
(122268, 'esMX', '¡Si no es nada más ni nada menos que $Gel campeón:la campeona; de Odyn!', '', 25549),
(122266, 'esMX', 'Te debo la vida... No tengo mucho, pero revisa mis suministros y llévate lo que quieras.', '', 25549),
(122265, 'esMX', 'Si aprecias tus zapatos, será mejor que te alejes un poco.', '', 25549),
(122264, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122263, 'esMX', '', '$gBienvenido:Bienvenida; a la Rama nudosa, $n.', 25549),
(122262, 'esMX', '¡Mira este desastre! ¡Todas nuestras cosas están tiradas! Libros en el suelo, herramientas por todas partes... ¡Ojalá nos hubieran advertido antes de mover a toda la ciudad!$B$BY mira a Dorian. El pobre aún se está recuperando.', '', 25549),
(122261, 'esMX', '', 'Lo siento, $n, pero nos pidieron no tomar alumnos nuevos por un tiempo. Cuando lleguemos a nuestro destino final, de seguro las cosas volverán a la normalidad.', 25549),
(122260, 'esMX', 'Hacer un pedido de armamentos para campeones.', 'Hacer un pedido de armamentos para campeones.', 25549),
(122259, 'esMX', 'Tráeme a tus muertos. Les daré algún uso.', '', 25549),
(122258, 'esMX', '¡Los marchitos! Están sobre nosotros. ¡Ayuda, por favor!', '', 25549),
(122257, 'esMX', 'Espera... ¿oyes eso?', '', 25549),
(122256, 'esMX', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122255, 'esMX', 'Gra... gracias... no... no sé como seguir... perdí tanto.', '', 25549),
(122254, 'esMX', '¿Qué necesitas, $gpequeño:pequeña; $n?', '', 25549),
(122253, 'esMX', '<Alimenta a Llorian con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná ancestral.>', '<Alimenta a Llorian con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná ancestral.>', 25549),
(122252, 'esMX', 'Hacer un pedido de armamentos para campeones.', 'Hacer un pedido de armamentos para campeones.', 25549),
(122251, 'esMX', '', 'Que la Luz te bendiga.', 25549),
(122250, 'esMX', 'La mataron... esos marchitos mataron a mi Luniel. Ya... no me queda nada.', '', 25549),
(122249, 'esMX', 'Escucharé lo que $Geste cazador:esta cazadora; de demonios tiene que decir.', '', 25549),
(122248, 'esMX', '¡Tengo que terminar estas muestras, $n! ¡La última carga fue tan inestable que casi nos mata a todos durante el viaje!$B$BNo le digas eso último a nadie.', '', 25549),
(122247, 'esMX', 'Inicia el ritual', 'Inicia el ritual', 25549),
(122246, 'esMX', '', '¿Ya es hora?', 25549),
(122244, 'esMX', 'Comienza a cargar el Martillo', 'Comienza a cargar el Martillo', 25549),
(122243, 'esMX', '', '¿Sí?', 25549),
(122241, 'esMX', 'Hacer un pedido de armamentos para campeones.', 'Hacer un pedido de armamentos para campeones.', 25549),
(122240, 'esMX', '¿Cómo puedo ayudarte?', '¿Cómo puedo ayudarte?', 25549),
(122239, 'esMX', 'Comenzar la llamada', 'Comenzar la llamada', 25549),
(122238, 'esMX', '', '¿Qué necesitas?', 25549),
(122237, 'esMX', 'Luniel... dulce Luniel... ¿Cómo pude dejar que te pasara esto?', '', 25549),
(122236, 'esMX', 'Hacer un pedido de armamentos para campeones.', 'Hacer un pedido de armamentos para campeones.', 25549),
(122235, 'esMX', '¿Qué?', '', 25549),
(122232, 'esMX', 'Manda a llamar a la Vanguardia', 'Manda a llamar a la Vanguardia', 25549),
(122231, 'esMX', '¿Cuál es tu orden?', '', 25549),
(122230, 'esMX', '|TInterface\\Icons\\spell_deathknight_necroticplague.blp:20|t ¡Te afecta |cFFF00000|Hspell:206480|h[Plaga carroñera]|h|r!', '', 25549),
(122229, 'esMX', 'Por favor... mata a todos estos monstruos.', 'Por favor... mata a todos estos monstruos.', 25549),
(122228, 'esMX', 'Libre... libre al fin. ¿Cómo salgo de aquí?', 'Libre... libre al fin. ¿Cómo salgo de aquí?', 25549),
(122227, 'esMX', 'Creo... que puedo seguir. Gracias.', 'Creo... que puedo seguir. Gracias.', 25549),
(122226, 'esMX', 'Qué horror... qué horror.', 'Qué horror... qué horror.', 25549),
(122225, 'esMX', 'No puedo seguir...', 'No puedo seguir...', 25549),
(122224, 'esMX', 'Me siento... tan débil...', 'Me siento... tan débil...', 25549),
(122223, 'esMX', 'Si aún no aprendiste a volar aquí en Pandaria, tomate la libertad de usar a Graddoc para un viaje al Valle.', '', 25549),
(122222, 'esMX', 'La caja vuelve a brillar. ¡Una secuencia más y quedará totalmente activada!', 'La caja vuelve a brillar. ¡Una secuencia más y quedará totalmente activada!', 25549),
(122221, 'esMX', 'El ruido de las campanillas aumenta su volumen.', 'El ruido de las campanillas aumenta su volumen.', 25549),
(122220, 'esMX', 'La caja comienza a emitir una serie de sonidos de campanilla agradables.', 'La caja comienza a emitir una serie de sonidos de campanilla agradables.', 25549),
(122219, 'esMX', 'La caja brilla con intensidad.', 'La caja brilla con intensidad.', 25549),
(122218, 'esMX', 'La próxima vez que alguien te diga que moverán una ciudad con magia, ¡prepárate para todo! En serio, ¡para todo!', '', 25549),
(122217, 'esMX', 'Necesito que presiones ese gran botón rojo que dice "NO PRESIONAR ESTE BOTÓN".', '', 25549),
(122216, 'esMX', 'Pero puede que experimentemos un caso menor de fracaso total.', '', 25549),
(122215, 'esMX', 'Dorothy está dentro, si la necesitas; pero si buscas suministros no podemos tomar pedidos por el momento. Mis disculpas.', '', 25549),
(122214, 'esMX', '', 'Mucha gente a venido a buscar una cura para los efectos secundarios.$B$BSi tan solo pudiera encontrar esas recetas antiguas... ¡Sé que están por aquí!', 25549),
(122213, 'esMX', '', 'Oh, no te preocupes por él. Es olvidadizo. Todos los objetos añejados quedaron bien guardados antes de nuestra partida.$B$B¡Asegúrate de visitarnos cuando abramos la tienda de nuevo! ¡De seguro pronto llegaremos nuestro destino final!', 25549),
(122212, 'esMX', '¡Solo pude salvar la mitad de mi queso! ¡La mitad!$B$B¿Cómo vamos a administrar un negocio de vino y queso tan solo con mucho vino y migajas de deliciosos queso? ¡Esto es inaceptable! ¡Es absurdo! Y...$B$B¡Oh, no! Ahora me siento débil. ¿En qué se convirtió este mundo!', '', 25549),
(122211, 'esMX', '', '¡Ya casi están todos! ¿Quién diría que mover a Dalaran provocaría tantos problemas? ¡Un corral más, las aves, y luego todo volverá a la normalidad!$B$B<Mira alrededor de la habitación>.$B$BExcepto por ese pobre tipo de la pecera. Espero que solucionen eso pronto.', 25549),
(122210, 'esMX', '', '¡Este lugar es un desastre!', 25549),
(122209, 'esMX', '', 'Para proteger a los débiles, defender la justicia e ir por el camino de la rectitud.', 25549),
(122208, 'esMX', '', 'El escudo del hombre, la mano de la devoción y la espada de las represalias.', 25549),
(122207, 'esMX', '', 'Un guerrero de la Luz', 25549),
(122206, 'esMX', '', 'Con este juramento, he renacido.', 25549),
(122205, 'esMX', '', 'Y me uno a mis hermanos y hermanas en humilde servicio.', 25549),
(122204, 'esMX', '', 'Ofrezco mi vida a la Orden de la Mano de plata.', 25549),
(122202, 'esMX', '', 'Aquí, en presencia de los Campeones Eternos, hago este juramento sagrado:', 25549),
(122201, 'esMX', '<Alimenta al sable de maná con 10 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná ancestral.>', '<Alimenta al sable de maná con 10 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná ancestral.>', 25549),
(122200, 'esMX', '<El sable de mana te mira como si tuvieras algo para comer.>', '', 25549),
(122198, 'esMX', 'Qué bueno que vaciaron la pecera antes de irnos. ¡Eso hubiese sido todo un nuevo problema!', '', 25549),
(122197, 'esMX', 'No encuentro nada acerca de esta situación en particular. ¡Solo aguanta! Ya se nos ocurrirá algo.', '', 25549),
(122196, 'esMX', 'Necesito más tiempo para pensar. Estas son circunstancias bastante particulares. No es el tipo de trabajo que se haga... a medias.', '', 25549),
(122195, 'esMX', 'No te preocupes, te sacaremos en un momento... ¿Por qué le sigo hablando a esa cosa?', '', 25549),
(122194, 'esMX', 'Si lo giramos un poco a la derecha, entonces... no. Quizás para el otro lado.', '', 25549),
(122193, 'esMX', 'Pronuncia los votos en el altar cuando estés $Glisto:lista;.', 'Pronuncia los votos en el altar cuando estés $Glisto:lista;.', 25549),
(122192, 'esMX', 'Bueno, podríamos esperar hasta que volvamos a avanzar. ¿Quién sabe? ¡El problema podría solucionarse solo!', '', 25549),
(122191, 'esMX', '', 'Vanthir sintió que estaríamos más a salvo aquí. Después de lo que le pasó a mi querida Korine, estoy de acuerdo.\n\nLos Caídos de la Noche viven una vida difícil, pero soportaremos.\n\nGracias nuevamente por salvar a mi hija.', 25549),
(122190, 'esMX', 'Potencia el cristal de enfoque', 'Potencia el cristal de enfoque', 25549),
(122189, 'esMX', '', 'Estamos listos para empezar.', 25549),
(122188, 'esMX', '¿Qué fue eso? ¡Basta! ¡Alguien me está pinchando al otro lado!', '', 25549),
(122187, 'esMX', '¿Qué quieres decir, "quizás tenga que esperar hasta la próxima traslación"? ¡No puedo quedarme aquí! ¡Tengo cosas que hacer!', '', 25549),
(122186, 'esMX', 'Nunca lo noté antes, pero las piedras en el suelo aquí están muy bien cuidadas.', '', 25549),
(122185, 'esMX', 'Sí, ¡pero asegúrate de protegerme si aparecen demonios! Realmente no puedo defenderme, sientiendes lo que digo.', '', 25549),
(122184, 'esMX', 'Oh, vaya. Otro espectador. Seguuuro... disfruta del espectáculo. Todos vengan a ver al pobre gnomo. Cuando baje de aquí...', '', 25549),
(122183, 'esMX', '¡Oye! ¡Un poco más lento! Me gustaría mantener intactas mi piernas, de ser posib... ¡espera un minuto! Si estoy aquí, ¿¡dónde está el resto de mí!?', '', 25549),
(122182, 'esMX', '¿Especialista, eh? ¡Llevo aquí atrapado por horas!', '', 25549),
(122181, 'esMX', 'El sable de maná ronronea cálidamente y te indica que te acerques.', '', 25549),
(122180, 'esMX', '', 'Me convertí en sacerdotisa para ayudar a los demás, pero últimamente me he preguntado si puedo hacer más.', 25549),
(122179, 'esMX', 'Reclutar ascendientes', 'Reclutar ascendientes', 25549),
(122178, 'esMX', 'Los Ascendientes no reciben órdenes, solo son desatados.', 'Los Ascendientes no reciben órdenes, solo son desatados.', 25549),
(122177, 'esMX', '<Alimenta al Tejedor de fuego Ovin 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná Ancestral.>', '<Alimenta al Tejedor de fuego Ovin 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná Ancestral.>', 25549),
(122176, 'esMX', 'Mi llama... flaquea. No me queda mucho en este mundo...', '', 25549),
(122175, 'esMX', 'Haz un pedido de un Sello del Destino quebrado.', 'Haz un pedido de un Sello del Destino quebrado.', 25549),
(122174, 'esMX', '¡Ponte los lentes de espía con estilo para encontrar el rastro de sangre!', '¡Ponte los lentes de espía con estilo para encontrar el rastro de sangre!', 25549),
(122173, 'esMX', 'Los Descoronados deben luchar perjudicar a la Legión Ardiente de todas las formas que conocemos: artificio, astucia, engaño y, por supuesto, política.\n\nHasta que la Legión caiga, nuestra cooperación continua es mi mayor prioridad, $n. Espero que también sea la tuya.', '', 25549),
(122172, 'esMX', '<Alimenta a la Tempomante Virinya con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|tde maná ancestral.>', '<Alimenta a la Tempomante Virinya con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|tde maná ancestral.>', 25549),
(122171, 'esMX', '', 'Ayuda... por favor. Mis pensamientos... se vuelven lentos.', 25549),
(122170, 'esMX', 'Con gusto aceptamos tu ayuda, Delas. La Luz es más fuerte cuando brilla en conjunto.', '', 25549),
(122169, 'esMX', '¡Encontré uno! ¡Fortalezcan las defensas en este lugar de inmediato!', '', 25549),
(122168, 'esMX', '¡La Legión temblará ante mi! ¡Todos lo harán!', '', 25549),
(122167, 'esMX', '¡Tu energía vital amplifica la mía! ¡Soy imparable!', '', 25549),
(122166, 'esMX', '¡Seré el conducto para la retribución de Azeroth!', '', 25549),
(122165, 'esMX', '¡Debes morir para que yo pueda vivir! ¡Tengo un destino que cumplir! ¡Un mundo al cual salvar!', '', 25549),
(122164, 'esMX', 'Gracias por este sacrificio. Tu muerte no será en vano.', '', 25549),
(122163, 'esMX', 'Si solo hubiese otra forma, pero necesito poder si queremos sobrevivir.', '', 25549),
(122162, 'esMX', 'Tus energías vitales le darán una oportunidad de luchar a nuestro mundo, $Gacólito:acólita;.', '', 25549),
(122161, 'esMX', 'Yo no pedí esta responsabilidad, sino que es decisión del destino...', '', 25549),
(122160, 'esMX', 'Vas por un camino oscuro, Illidan. No hay vuelta atrás...', 'Vas por un camino oscuro, Illidan. No hay vuelta atrás...', 25549),
(122159, 'esMX', '¡Madre Luna, llévame!', '¡Madre Luna, llévame!', 25549),
(122158, 'esMX', 'Illidan... ¿por qué?', 'Illidan... ¿por qué?', 25549),
(122157, 'esMX', '¡¿No puedes ver los sacrificios que he hecho para asegurar nuestra supervivencia?!', '', 25549),
(122156, 'esMX', 'Me aseguraré que tu familia esté protegida, $gamigo:amiga;.', '', 25549),
(122155, 'esMX', 'La amenaza de la Legión nos cuesta vidas. ¡Sus vidas!', '', 25549),
(122154, 'esMX', '¡Estoy más allá de tu juicio! Lo que hago, ¡lo hago por Azeroth!', '', 25549),
(122153, 'esMX', '¡Algunos de ustedes deben morir si queremos que nuestro mundo sobreviva!', '', 25549),
(122152, 'esMX', '¡Deberías estar $gagradecido:agradecida; con esta oportunidad que se te ha dado para servir!', '', 25549),
(122151, 'esMX', '¡Mira a tu alrededor! ¡Esta es la única forma!', '', 25549),
(122150, 'esMX', '¡Sirves a un propósito superior ahora, mi fiel acólito!', '', 25549),
(122149, 'esMX', '¡Hago lo que es necesario!', '', 25549),
(122148, 'esMX', '¿Quieres mi magia? ¡Toma, pruébala!', '¿Quieres mi magia? ¡Toma, pruébala!', 25549),
(122147, 'esMX', '¡Arderás por esto, Illidan!', '¡Arderás por esto, Illidan!', 25549),
(122146, 'esMX', '¡TRAIDOR!', '¡TRAIDORA!', 25549),
(122145, 'esMX', '¡No eres mejor que los demonios que se ciernen sobre nosotros!', '¡No eres mejor que los demonios que se ciernen sobre nosotros!', 25549),
(122144, 'esMX', '¿Quieres mi maná? ¡Pues ven! ¡Quítamela si te atreves!', '¿Quieres mi maná? ¡Pues ven! ¡Quítamela si te atreves!', 25549),
(122143, 'esMX', '¡Nos traicionaste a todos!', '¡Nos traicionaste a todos!', 25549),
(122142, 'esMX', '¡Ya no eres mi capitán, Illidan! ¡MUERE!', '¡Ya no eres mi capitán, Illidan! ¡MUERE!', 25549),
(122141, 'esMX', '¡Guardagrajo! ¡Envía a estos demonios de vuelta con sus maestros oscuros! ¡Por Azshara! ¡Por Kalimdor!', '', 25549),
(122140, 'esMX', '¡No me mataras sin pelear!', '¡No me mataras sin pelear!', 25549),
(122139, 'esMX', '¡Eres un monstruo, Illidan!', '¡Eres un monstruo, Illidan!', 25549),
(122138, 'esMX', 'Te atraparé con mis cadenas.', '', 25549),
(122137, 'esMX', 'Hacer un pedido de armamentos para campeones.', 'Hacer un pedido de armamentos para campeones.', 25549),
(122136, 'esMX', 'Puedo ayudarte a conseguir algunos objetos valiosos.', 'Puedo ayudarte a conseguir algunos objetos valiosos.', 25549),
(122135, 'esMX', '¡Detente! ¡Nos estás matando!', '¡Detente! ¡Nos estás matando!', 25549),
(122134, 'esMX', 'No puedes hacer esto, Illidan.', 'No puedes hacer esto, Illidan.', 25549),
(122133, 'esMX', 'No puedo moverme... no tengo fuerzas...', 'No puedo moverme... no tengo fuerzas...', 25549),
(122132, 'esMX', 'El poder disminuye...', 'El poder disminuye...', 25549),
(122131, 'esMX', 'M... Maestro, me estoy muriendo...', 'M... Maestro, me estoy muriendo...', 25549),
(122130, 'esMX', '¿Tiburones de cloaca? ¡Criaturas horribles, solo los he visto una vez!', '', 25549),
(122129, 'esMX', '¡Tomen sus cervezas calientes y sus salchichas frías! ¡Pregunten por Derrape y digan que Joe los manda!', '', 25549),
(122128, 'esMX', '¿Alguien ha visto a mi hermano Daryl?', '', 25549),
(122127, 'esMX', '¿Qué es ese olor?', '', 25549),
(122126, 'esMX', 'Las cosas no pueden empeorar, ¿o sí?', '', 25549),
(122125, 'esMX', '¡Muévete a la derecha! ¡Ahora muévete a la izquierda!', '', 25549),
(122123, 'esMX', '¿Alguien ha visto a Apestoso? Empiezo a preocuparme.', '', 25549),
(122122, 'esMX', '¡Este jubón no es gratis!', '', 25549),
(122120, 'esMX', 'Mi esposa me dejó por un pescado.', '', 25549),
(122119, 'esMX', 'La caída es larga, $Gamigo:amiga;. \n\n¡Necesitas una mano?', '', 25549),
(122118, 'esMX', '', 'Hola, muchachos. Si necesitan algo, o si quieren que le pida algo a alguien.\n\nO, ya saben, si quieren charlar un rato, Nikki está aquí para ustedes.', 25549),
(122117, 'esMX', '¿Sí? ¿Qué ocurre?$B$BSiento tener poco, pero muchas veces pedí aviso antes de mover a toda la ciudad. Ahora mira mi tienda... ¡es un desastre! ¡Ildine y Vanessa estará ocupada por meses!$B$BAhora, si me disculpas, ¡debo terminar estos encantamientos antes de que decidan transportarnos otra vez!', '', 25549),
(122116, 'esMX', '¡Gracias!', '', 25549),
(122115, 'esMX', '¡Da la orden y revelaré al enemigo!', '', 25549),
(122114, 'esMX', '', 'Sufre bien, $n. Estaremos listos cuando nos necesites.', 25549),
(122113, 'esMX', '', 'Incluso el más dedicado artesano necesita descansar de vez en cuando. Toma una piel para dormir y descansa bajo la protección de mi corazón.', 25549),
(122112, 'esMX', 'Será mejor ir al Fuerte Grommash de inmediato, $n.', '', 25549),
(122111, 'esMX', 'Esta acción cuesta 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t mana ancestral. ¿Quieres continuar?', 'Esta acción cuesta 25|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná ancestral. ¿Deseas continuar?', 25549),
(122110, 'esMX', '<Dale al Arcanista Ke''lorin 25|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná ancestral.>', '<Dale al Arcanista Ke''lorin 25|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t Maná ancestral.>', 25549),
(122109, 'esMX', 'Hay algo diferente aquí. El aire está bien, pero hay una sensación extraña.$B$BDesde que llegamos, la gente se ha comportado raro. Y no me refiero a los mareos por el viaje, sino a la forma en que la gente se mueve y los susurros ocasionales que se escuchan.', '', 25549),
(122108, 'esMX', 'Mi mente... se marchita... necesito... ayuda.', '', 25549),
(122107, 'esMX', '[PH] ¡Y luego corre una increíble cinemática final! [PH]', '[PH] ¡Y luego se reproduce una cinemática final genial! [PH]', 25549),
(122106, 'esMX', 'Volveré cuando esté a tu nivel, Arluin.', 'Volveré cuando esté a tu nivel, Arluin.', 25549),
(122105, 'esMX', 'Publico mensajes cuando siento cosas.', '', 25549),
(122104, 'esMX', '', 'Los ataques drógbar no le dejaron nada a mi familia, pero lo que nos queda es tuyo, $Ghéroe:heroína;.', 25549),
(122103, 'esMX', '', '$gBienvenido:Bienvenida, $gforastero:forastera.$b$bLos de tu especie no suelen llegar a lo alto de estas montañas, pero todos son igualmente bienvenidos.', 25549),
(122102, 'esMX', '¿Quién será el próximo en probar mi acero?', '', 25549),
(122100, 'esMX', '¿Qué? ¡Oh, ni siquiera sabía que estabas ahí! ¿Desde cuándo todos ustedes $cs se volvieron tan sigilosos?$B$BNecesito saber si nos iremos pronto para poder preparar mis cosas.', '', 25549),
(122099, 'esMX', 'Ven, $gviajero:viajera. Únete a nosotros.$b$bDeja que nuestro corazón sea tu corazón.$b$bQuédate aquí. Únete a nosotros.$b$bÚnete a nosotros...', '', 25549),
(122098, 'esMX', '¿$GUn cazador:Una cazadora; de demonios? ¡Qué asco! Tus alas son tan curtidas y tenebrosas.', '¿$GUn cazador:Una cazadora; de demonios? Ugh... Tus alas son tan curtidas y tenebrosas.', 25549),
(122097, 'esMX', '', 'Decías la verdad, Elias. Los cazadores de demonios están descontrolados. Ten cuidado... $n lo ve todo con esos ojos.', 25549),
(122096, 'esMX', 'Me alegro de volver a verte, $n. Supongo te encuentras bien.\n\n<Mathias mira a su alrededor y luego dice el resto susurrando.>\n\n¿Cómo van las cosas de los Descoronados? Como jefe de la IV:7, no puedo apoyarte públicamente.\n\nPero hasta que la guerra en contra de la Legión Ardiente llegue a su fin, te daré todo mi apoyo, aún cuando sea en secreto.\n\nHasta que nos volvamos a encontrar.', '', 25549),
(122095, 'esMX', 'Quiero reclutar doncellas escuderas.', 'Quiero reclutar doncellas escuderas.', 25549),
(122094, 'esMX', 'Quiero reclutar Val''kyr.', 'Quiero reclutar Val''kyr.', 25549),
(122093, 'esMX', 'Acércate una piedra de descanso, brul. Navarrogg dice que puedes descansar aquí.', '', 25549),
(122092, 'esMX', '', '¡$gUn cazador:Una cazadora; de demonios! Perfecto, justo lo que estaba buscando.', 25549),
(122091, 'esMX', '¿Eres uno de ellos, $n? ¿O uno de nosotros? Tanta energía demoniaca...', '', 25549),
(122090, 'esMX', '', 'Espero que puedas controlar tus... habilidades... en este lugar sagrado, "$Gcazador:cazadora; de demonios". Te estaremos observando.', 25549),
(122089, 'esMX', '¿Qué te hiciste, $n? Eres más $Gdemoniaco:demoniaca; que $r.', '¿Qué te hiciste, $n? Tienes más de demonio que $r.', 25549),
(122088, 'esMX', '<refunfuña>', '', 25549),
(122087, 'esMX', '', 'Un campeón para las excusas, según parece.', 25549),
(122086, 'esMX', 'Soy su campeón, Dama Oscura. Es mi trabajo hacerla quedar bien.', '', 25549),
(122085, 'esMX', 'Jace Tejeoscuro habló con la verdad. ¡Portas las Hojas de Guerra Aldrachi, $n! Contigo a la cabeza de nuestra orden, los Illidari serán imparables.', 'Jace Tejeoscuro habló con la verdad. ¡Portas las Hojas de Guerra Aldrachi, $n! Contigo a la cabeza de nuestra orden, los Illidari serán imparables.', 25549),
(122084, 'esMX', '', 'He matado a muchos más que tú, Nathanos. ¡Estás fatal!', 25549),
(122083, 'esMX', '¡$n! Veo que conseguiste las espadas de Varedis Almavil. Esperemos que tengas más control sobre el demonio en tu interior.', '¡$n! Veo que conseguiste las espadas de Varedis Almavil. Esperemos que tengas más control sobre el demonio en tu interior.', 25549),
(122082, 'esMX', 'Usa la Baliza continuamente, el poder de la Luz es infinito y nunca se niega.', '', 25549),
(122081, 'esMX', '$gBienvenido:Bienvenida; a bordo, $n. \n\nEstamos todos acomodados y listos para nuestro envío cuando estés $gpreparado:preparada;.', '', 25549),
(122080, 'esMX', 'Tu bastón, al igual que el cristal de Velen, es un regalo que le concedemos a aquellos que tratamos de salvar de la destrucción. Quedan muy pocos, no lo dejes caer al Vacío.', '', 25549),
(122079, 'esMX', 'De todos los usuarios, los draenei son los que mejor han portado la Baliza. Se espera que los draenei sobrevivan donde otros no podrán.', '', 25549),
(122078, 'esMX', 'La Baliza estuvo en silencio por un tiempo, no se había pedido ayuda. Qué bien que la hayas reparado.', '', 25549),
(122077, 'esMX', 'Madre... Padre...', '', 25549),
(122076, 'esMX', '', 'Escuché mucho de estos dos héroes. No me cabe duda de que este mensaje es importantísimo.', 25549),
(122075, 'esMX', 'Arator tiene razón. Turalyon y Alleria hicieron un gran esfuerzo para enviarnos esta advertencia. $GAlto señor:Alta señora;, estamos a tus ordenes. ¿Qué hacemos?', '', 25549),
(122074, 'esMX', 'No lo hubiese creído de no verlo con mis propios ojos.', '', 25549),
(122073, 'esMX', '', 'Turalyon y Alleria... no puedo creer que hayan estado vivos todos estos años...', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122072, 'esMX', '', 'Por la Luz... ¿qué significa?', 25549),
(122071, 'esMX', '', '¡Solo dilo y liberaré a la amenaza oculta!', 25549),
(122070, 'esMX', '¿Por qué la manteca de cacao está resbaladiza? ¡TRAÍGANME UNA TOALLA! ¡Quien haya comprado esta manteca resbaladiza está DESPEDIDO!', '', 25549),
(122069, 'esMX', '$GBienvenido:Bienvenida; a la tienda, $n. Perdón por el desorden. Estamos en proceso de limpieza.$B$B¡El último viaje si que dejó un desastre!', '', 25549),
(122068, 'esMX', '', 'Tendrás que disculparme. A veces me mareo un poco. Empezó a ocurrirme luego de tu llegada.', 25549),
(122067, 'esMX', '', 'Todos estos papeles. ¿Cómo pudimos tener un registro de ellos? Ahora están por todas partes.$B$B¡Me tomará semanas organizarlos de nuevo!', 25549),
(122066, 'esMX', '', '¡Oh, no te había visto!$B$BEstamos ocupados limpiando. Ven a vernos cuando hayamos terminado.', 25549),
(122065, 'esMX', 'Disculpa el desorden. Llevamos mucho tiempo limpiando.$B$B<Mira por toda la tienda>. Aunque parece no servir de mucho. Parece que hubiera pasado un huracán. Y mi mercancía se dañó. ¿Quién va a quererla ahora?$B$BLa próxima vez que decidamos mover la ciudad, primero engraparé todo.', '', 25549),
(122064, 'esMX', 'Hmmm... No tengo nada, $n. Todos los envíos están detenidos hasta nuevo aviso.$B$BEstá todo arruinado. Transportar una ciudad... ¿quién creyó que sería buena idea? Tomará semanas reparar este lugar.', '', 25549),
(122063, 'esMX', '', 'Sería sabio no considerar esta posada como tu hogar por ahora. Puede que no estemos aquí mismo la próxima vez que volvamos.', 25549),
(122062, 'esMX', '', '¡Aaah!', 25549),
(122061, 'esMX', '¿Sabes que ocurre?', '¿Sabes que ocurre?', 25549),
(122060, 'esMX', '', '¿También lo sientes? Se me eriza la piel...', 25549),
(122059, 'esMX', '', 'Ugggh... esa espada... ¿qué llevas ahí? ¡La enfermedad y la descomposición te rodean, Caballero de la Muerte!', 25549),
(122058, 'esMX', '', 'Esa espada demoniaca que tienes... apesta a corrupción, Caballero de la Muerte. Termina tus asuntos y llévate esa arma de este templo sagrado.', 25549),
(122057, 'esMX', 'Un aura de enfermedad y pestilencia rodea el arma que portas, Caballero de la Muerte. Mantente $Galejado:alejada; de Senegos.', '', 25549),
(122056, 'esMX', '', 'Así que los rumores que corren por las Entrañas son ciertos... ¡La Agonía de Escarcha fue reforjada! Ten cuidado, $n. Esas espadas podrían tener vida propia.', 25549),
(122055, 'esMX', '¿Qué es esta blasfemia, $n? ¿Cómo te atreves a reforjar esa espada maldita? La misma espada que maldijo a Lordaeron y a su príncipe. Le advertí a Arthas que no tocara la Agonía de Escarcha, y ahora te lo advierto a ti: lanza esas cosas al mar antes de que nos maldiga a todos.', '', 25549),
(122054, 'esMX', '', '¿Son esas... las Fauces de los Malditos? Usaremos las armas de la Legión en su contra, ¿eh? ¡Me agrada tu forma de pensar, $n!', 25549),
(122053, 'esMX', '¡Quienquiera que haya hecho esto va a pagarlo! ¡Encuéntralos! ¡ENCUÉNTRALOS!', '', 25549),
(122052, 'esMX', 'Espera un minuto... una de mis llaves está... ¡ALGUIEN ROBÓ LA LLAVE DE MI CAJA FUERTE!', '', 25549),
(122051, 'esMX', 'Fiu... está aumentando la temperatura. Es hora de una siesta relajante...', '', 25549),
(122050, 'esMX', '¡Muy bien! ¡Estoy listo para romper cabezas!', '', 25549),
(122049, 'esMX', '¡Idiotas! ¡¿Dónde está mi manteca de cacao?! ¡¿Qué parte de MANTECA y CACAO no entienden?!', '', 25549),
(122048, 'esMX', 'Ahora, iré al sauna a descansar un poco... ¡así que llévenme un cóctel granizado y manteca de cacao!', '', 25549),
(122047, 'esMX', 'Esa hacha que portas... es un arma de la Legión. ¿Estás $gseguro:segura; que puedes controlar su hambre?', '', 25549),
(122046, 'esMX', 'Placeholder Text', '', 25549),
(122045, 'esMX', '¡Escuchen, idiotas! ¡El palacio del placer está FUERA DE TODO ALCANCE! ¡No quiero que NADIE ponga un pie en mi propiedad!', '', 25549),
(122044, 'esMX', 'Sin texto', '', 25549),
(122043, 'esMX', 'Si puedes escabullirte al sauna, ¡puedes tomar la llave mientras no la tenga puesta!', '', 25549),
(122042, 'esMX', '¡Hoy es tu día de suerte, $gamigo:amiga;! Mientras hablamos, Gallywix está disfrutando de un relajante momento en su sauna personal.', '', 25549),
(122041, 'esMX', 'Muerte a la Legión.', '', 25549),
(122040, 'esMX', '', 'Esas espadas que portas... están malditas. Por favor, ¡no traigas el frío de la muerte a este sagrado lugar!', 25549),
(122039, 'esMX', '', 'Azeroth no debe caer.', 25549),
(122038, 'esMX', '', 'Si él no habla, recuérdale que me debe un favor por "ya sabes qué" en "ya sabes dónde"... ¿entendido?', 25549),
(122037, 'esMX', '', 'Pregúntale a Izak el camarero, él debe saber cómo obtener la llave de la caja fuerte.', 25549),
(122036, 'esMX', '', 'El señor Illidan conoce el camino.', 25549),
(122035, 'esMX', '', 'Cada vez que nos trasladamos, tengo que pasar días organizando mi colección. Ojala hubiese una forma más fácil de limpiar este desastre.', 25549),
(122034, 'esMX', '¡Pronto tendremos a un montón de tontos enamorados lanzándonos dinero!', '', 25549),
(122033, 'esMX', '¡Este será un asalto inolvidable!', '', 25549),
(122032, 'esMX', '', 'Somos todo lo que se interpone entre la Legión y la aniquilación.', 25549),
(122031, 'esMX', '', 'Por favor, Caballero de la Muerte. No profanes este lugar sagrado con esa hacha maldita que tienes. Puedo sentir sus ansias desde aquí.', 25549),
(122030, 'esMX', '', 'No es tuyo... el cetro no es tuyo...', 25549),
(122029, 'esMX', '', 'Cómo osas reclamar el cetro de nuestra amada reina como tuyo...', 25549),
(122028, 'esMX', '¡Pagarás por andar escabulléndote por ahí!', '', 25549),
(122027, 'esMX', '', 'Ese cetro le pertenece a nuestra reina...', 25549),
(122026, 'esMX', '¡Tenemos a un intruso!', '', 25549),
(122025, 'esMX', '¡No deberías estar aquí!', '', 25549),
(122024, 'esMX', '', 'Ese cetro no es tuyo, chamán. ¡Regrésalo!', 25549),
(122023, 'esMX', '¡ODIO que se escabullan!', '', 25549),
(122022, 'esMX', '¡Te haré puré a golpes!', '', 25549),
(122021, 'esMX', '¡Te encontré! ¡Ahora morirás!', '', 25549),
(122020, 'esMX', '¡Ahí estás! ¡Ya verás!', '', 25549),
(122019, 'esMX', '¡Alguien merodea por aquí!', '', 25549),
(122018, 'esMX', 'Sé que estás ahí... ¡muéstrate!', '', 25549),
(122017, 'esMX', '¡Sal para que pueda verte! ¡Cobarde!', '', 25549),
(122016, 'esMX', '¡Alguien se escabulle por aquí cerca!', '', 25549),
(122015, 'esMX', '¡Mi señor! Se acerca un extraño que porta un arma con la marca de la mismísima Reina Azshara.', '¡Mi señor! Se acerca un extraño que porta un arma con la marca de la mismísima Reina Azshara.', 25549),
(122014, 'esMX', '¿Qué fue ese ruido?', '', 25549),
(122013, 'esMX', '¡Alguien intenta escabullirse aquí!', '', 25549),
(122012, 'esMX', '¿¡Quién intenta escabullirse!?', '', 25549),
(122011, 'esMX', 'Cuídate.', '', 25549),
(122010, 'esMX', 'Estoy listo.', 'Estoy lista.', 25549),
(122009, 'esMX', 'Si me lo preguntas, hay algo raro en el aire. Desde que llegamos aquí la gente se ha portado de manera muy extraña. Y el consejo... se han reunido muy a menudo. Espero que esté todo bien.', '', 25549),
(122008, 'esMX', '', 'Todo está demasiado tranquilo desde el viaje. Quizás aún sienten los efectos. ¡Mover a todo Dalaran no es fácil!$B$BEspero que las cosas vuelvan a la normalidad.', 25549),
(122007, 'esMX', 'La locura me llama más allá...', '', 25549),
(122006, 'esMX', 'El abismo susurra tu nombre.', '', 25549),
(122005, 'esMX', 'Se revuelca... sin rostro, olvidado... inmortal.', '', 25549),
(122004, 'esMX', 'No puedes perder la esperanza si no existe.', '', 25549),
(122003, 'esMX', '¡$GTonto:Tonta; mortal! No puedes ganar...', '', 25549),
(122002, 'esMX', '¡El maestro destruirá... tu alma!', '', 25549),
(122001, 'esMX', 'La oscuridad más allá... me espera.', '', 25549),
(122000, 'esMX', 'Mi vida... por el maestro...', '', 25549),
(121999, 'esMX', 'Si no puedo doblegar tu mente, lo haré con tu cuerpo.', '', 25549),
(121998, 'esMX', 'Te mostraré lo que les ocurre a los héroes.', '', 25549),
(121997, 'esMX', 'Diviérteme... ¡Grita y pide ayuda!', '', 25549),
(121996, 'esMX', 'No puedes detener lo que viene. Ni en tus sueños.', '', 25549),
(121995, 'esMX', '¡La pesadilla te consume!', '', 25549),
(121994, 'esMX', '¡Tu tormento será eterno!', '', 25549),
(121993, 'esMX', 'Te mandaré al sueño eterno.', '', 25549),
(121992, 'esMX', '', 'Lo siento, $n. Con todo lo que está ocurriendo, parece que no cortaré el cabello a nadie por un tiempo. La mayoría de los otros negocios también cerraron sus puertas.$B$B<Mira a los demás comerciantes.>$B$BSe dice que está ocurriendo algo, y no solo por aquí. Las mismísimas ciudades están llenas de... bueno, no sé, y será mejor que no hable mucho. No quiero ver a nadie más con los nervios de punta por aquí. Ya hemos aguantado mucho.', 25549),
(121991, 'esMX', '¡Sé presa de la oscuridad!', '', 25549),
(121990, 'esMX', 'Trixyni me ha enviado. Necesito la llave para la caja fuerte... ella dice que tú "se lo debes".', 'Trixyni me ha enviado. Necesito la llave para la caja fuerte... ella dice que tú "se lo debes".', 25549),
(121989, 'esMX', '$GNecio:Necia;... Esta tierra ya está condenada...', '', 25549),
(121988, 'esMX', 'Si viniste a buscar problemas, no quiero ser parte de ello... ¿A quién engaño? ¡Cualquier cosa es mejor que esto!', '', 25549),
(121987, 'esMX', '¡$GBienvenido:Bienvenida; a tu pesadilla!', '', 25549),
(121986, 'esMX', 'La Pesadilla... me da la bienvenida...', '', 25549),
(121985, 'esMX', '¿Morirías por esta patética tierra?', '', 25549),
(121984, 'esMX', 'Qué lástima, pudiste unirte a nosotros...', '', 25549),
(121983, 'esMX', '¿Buscas pelea? Permíteme...', '', 25549),
(121982, 'esMX', 'Me pregunto: ¿Los elfos de la noche lamentarán tu muerte?', '', 25549),
(121981, 'esMX', 'No pueden detenernos. ¡Somos la Legión!', '', 25549),
(121980, 'esMX', 'Te lo advertí.', '', 25549),
(121979, 'esMX', 'No puedes ver, pero lo harás.', '', 25549),
(121978, 'esMX', '¡Tu resistencia es inútil!', '', 25549),
(121977, 'esMX', 'M envió Noggenfogger. Necesito entrar a la caja fuerte.', 'M envió Noggenfogger. Necesito entrar a la caja fuerte.', 25549),
(121976, 'esMX', '¡Esta tierra está condenada!', '', 25549),
(121975, 'esMX', '¡No puedes escapar del alcance del Señor de la Pesadilla!', '', 25549),
(121974, 'esMX', 'Maestro...', '', 25549),
(121973, 'esMX', '', 'Shhh... ¡baja la voz! Si alguien nos escucha hablando, ¡estamos muertos!', 25549),
(121972, 'esMX', 'Tu mundo está... perdido...', '', 25549),
(121971, 'esMX', '¡Ríndete! No hay esperanza para este mundo...', '', 25549),
(121970, 'esMX', 'La muerte no... nos detendrá...', '', 25549),
(121969, 'esMX', 'Mis manos no son las únicas... manchadas de sangre...', '', 25549),
(121968, 'esMX', 'Raaarrgh...', '', 25549),
(121967, 'esMX', 'El terror es todo... lo que te aguarda...', '', 25549),
(121966, 'esMX', 'Nuestro maestro quemará este mundo... ¡y a ti con él!', '', 25549),
(121965, 'esMX', 'Pronto... todos le darán la bienvenida a la muerte con los brazos abiertos.', '', 25549),
(121964, 'esMX', 'No puedes escapar... tus sueños...', '', 25549),
(121963, 'esMX', 'Creo... ¡que he cavado mi propia tumba! Por favor... ¡no me mates!', '', 25549),
(121962, 'esMX', 'Mientras tú estás ahí afuera, trataremos de asegurar una ubicación más cercana al santuario. Que Elune te guíe, $n.', '', 25549),
(121961, 'esMX', '¡Fue la IV:7! ¡Nos ofrecieron las riquezas de Ventormenta a cambio de Amber Kearnen!', '', 25549),
(121960, 'esMX', '¡Oh, dios, no! He escuchado de ti... ¡por favor, no me mates!', '', 25549),
(121959, 'esMX', 'Ahora que lo mencionas... me pareces $gconocido:conocida;.', '', 25549),
(121958, 'esMX', 'Yo... ¡nunca te lo diré!', '', 25549),
(121957, 'esMX', 'Tráeme su cabeza, y la espada carmesí tendrá acceso completo a la Bahía Ventormenta y el perdón real por los crímenes antes cometidos.', '', 25549),
(121956, 'esMX', 'Yo, el Maestro Mathias Shaw, por la presente autorizo que la Espada carmesí le dé caza al agente pícaro Amber Kearnen.', '', 25549),
(121955, 'esMX', '¡Debes quedarte en la Cima del Templo!', '¡Debes quedarte en la Cima del Templo!', 25549),
(121954, 'esMX', 'La Mano de plata...', '', 25549),
(121953, 'esMX', 'Veraguardia...', '', 25549),
(121952, 'esMX', 'Estamos listos para comenzar la misión.', 'Estamos listos para comenzar la misión.', 25549),
(121951, 'esMX', '¡Bien dicho!', '', 25549),
(121950, 'esMX', 'Así será.', '', 25549),
(121949, 'esMX', '', 'Acepto tu juramento de lealtad, $n. ¡La Horda perdura!', 25549),
(121948, 'esMX', 'No bajes la guardia, $n... ¡ahí hay un grupo de piratas!', '', 25549),
(121947, 'esMX', 'Señor, la perturbación de la Legión a nuestra red de teletransporte a larga distancia ha hecho que viajar sea un... desafío.', '', 25549),
(121946, 'esMX', 'Necesito tus energías vitales, mi obediente guardia lunar.', '', 25549),
(121945, 'esMX', 'Necesito más poder si queremos ganar esta batalla...', '', 25549),
(121944, 'esMX', 'Perdón por lo que hago.', '', 25549),
(121943, 'esMX', 'Aún no me llega la hora, pero a ti sí.', '', 25549),
(121942, 'esMX', '<El jinete del aire aletea, entusiasmado por la próxima batalla>', '<El jinete del aire aletea, entusiasmado por la próxima batalla>', 25549),
(121941, 'esMX', 'El bosque te protege.', '', 25549),
(121940, 'esMX', 'Contempla las hojas, $gamigo:amiga;.', '', 25549),
(121939, 'esMX', 'Me perdí de una buena charla.', '', 25549),
(121938, 'esMX', '¿Qué es lo que buscas?', '', 25549),
(121937, 'esMX', 'Cuando llegue el momento.', '', 25549),
