(120077, 'esMX', 'Efectos de sonido para las tropas.', 'Efectos de sonido para las tropas.', 25549),
(120076, 'esMX', 'Efectos de sonido para las tropas.', 'Efectos de sonido para las tropas.', 25549),
(120075, 'esMX', 'Maná... necesito... maná.', '', 25549),
(120074, 'esMX', 'Efectos de sonido para las tropas.', 'Efectos de sonido para las tropas.', 25549),
(120073, 'esMX', 'Por favor... No he comido en semanas...', '', 25549),
(120072, 'esMX', 'Efectos de sonido para las tropas.', '', 25549),
(120071, 'esMX', 'Efectos de sonido para las tropas.', 'Efectos de sonido para las tropas.', 25549),
(120070, 'esMX', '', 'Efectos de sonido para las tropas.', 25549),
(120069, 'esMX', '', 'Efectos de sonido para las tropas.', 25549),
