(112225, 'esMX', '', 'Nuestra mano está en todos lados.', 25549),
(112224, 'esMX', 'Tómatelo con calma.', '', 25549),
(112223, 'esMX', 'Nos vemos.', '', 25549),
(112222, 'esMX', '¡Regresa cuando quieras!', '', 25549),
(112221, 'esMX', 'Mantén tu vista en el horizonte.', '', 25549),
