(112219, 'esMX', 'Hablemos.', '', 25549),
(112218, 'esMX', 'Soy todo oídos.', '', 25549),
(112217, 'esMX', '¡Me alegra verte!', '', 25549),
(112216, 'esMX', 'Llamaste, pero la Mano de Argus está ocupada. Intenta más tarde.', '', 25549),
(112215, 'esMX', 'El profeta Velen habla menos que tú. Sin ofender.', '', 25549),
(112214, 'esMX', 'Seguramente hay cosas más importantes.', '', 25549),
(112213, 'esMX', 'Um... ¿aak?', 'Um... ¿aak?', 25549),
(112212, 'esMX', 'No estoy escuchando.', '', 25549),
(112211, 'esMX', 'Permanezcan alerta.', '', 25549),
(112210, 'esMX', 'Mis bendiciones estén contigo.', '', 25549),
(112209, 'esMX', 'Que la Luz te proteja.', '', 25549),
(112208, 'esMX', 'Dioniss aca.', '', 25549),
(112207, 'esMX', 'Somos agentes de la Luz.', '', 25549),
(112206, 'esMX', '<Los cuervosos están en posición y listos para comenzar con el ritual. \n\nParece que te están esperando.>', '', 25549),
(112205, 'esMX', 'La Mano de Argus está contigo.', '', 25549),
(112204, 'esMX', 'Archenon poros.', '', 25549),
