(112165, 'esMX', '', 'Saludos cordiales.', 25549),
(112164, 'esMX', '', 'El momento más oscuro es siempre antes del amanecer.', 25549),
(112163, 'esMX', 'Que el relámpago te guíe.', '', 25549),
(112162, 'esMX', 'La cacería continuará.', '', 25549),
(112161, 'esMX', 'Habla con suavidad.', '', 25549),
(112160, 'esMX', 'Imita la danza de los cuervosos para ayudar a completar el ritual.', '', 25549),
(112159, 'esMX', 'Adiós.', '', 25549),
(112158, 'esMX', 'La caza no espera a nadie.', '', 25549),
(112157, 'esMX', 'Estás lejos de casa.', '', 25549),
(112156, 'esMX', '¡Saludos, criatura insignificante!', '', 25549),
(112155, 'esMX', 'Soy Thorim, ¡Señor del Trueno!', '', 25549),
(112154, 'esMX', '¿Qué te trae al Templo de las Tormentas ?', '', 25549),
(112153, 'esMX', 'Fascinante. ¡Qué conversación más agradable!', '', 25549),
