UPDATE `broadcast_text_locale` SET `MaleText_lang`='Me reuniré con ustedes en la Capilla de Alonsus. Es el lugar sagrado en el que Uther el Iluminado entró en la orden de la Mano de plata. Es el único edifico que la Plaga no puede tocar, y será la base de operaciones de nuestra avanzada en esa mitad de la ciudad. Con su ayuda, Stratholme se convertirá en la capital de la Luz y en un nuevo comienzo para Lordaeron.', `VerifiedBuild`=25549 WHERE (`ID`=45541 AND `locale`='esMX');
